window.TRAUMA_QB = {"meta":{"title":"台灣外傷醫學會專科考題","range":"95–114 年","total":1006,"years":[95,96,97,98,99,100,101,102,103,104,105,106,107,108,109,110,111,112,113,114],"outdated":53,"suspect":58,"images":11},"topics":[{"id":"總論評分","short":"總論／評分","name":"外傷總論／初始評估／評分／機轉","count":49},{"id":"氣道","short":"氣道","name":"氣道與呼吸道處置","count":19},{"id":"休克輸血","short":"休克／輸血","name":"休克／輸液輸血／MTP／凝血","count":107},{"id":"頭部TBI","short":"頭部 TBI","name":"頭部外傷（TBI）","count":71},{"id":"脊椎脊髓","short":"脊椎／脊髓","name":"脊椎與脊髓損傷","count":48},{"id":"顏面頸部","short":"顏面／頸部","name":"顏面與頸部外傷","count":26},{"id":"胸部","short":"胸部","name":"胸部外傷","count":146},{"id":"腹部","short":"腹部","name":"腹部外傷","count":152},{"id":"骨盆泌尿","short":"骨盆／泌尿","name":"骨盆與泌尿生殖","count":42},{"id":"四肢血管骨科","short":"四肢／血管／骨科","name":"四肢／血管／骨科外傷","count":37},{"id":"燒傷環境","short":"燒傷／環境","name":"燒傷與環境傷害","count":23},{"id":"小兒","short":"小兒","name":"小兒外傷","count":29},{"id":"老年孕婦","short":"老年／孕婦","name":"老年與孕婦外傷","count":59},{"id":"ICU營養併發症","short":"ICU／營養／併發症","name":"ICU／營養／感染／併發症","count":66},{"id":"DCS_ACS","short":"DCS／ACS","name":"Damage control／腹腔室症候群（ACS）","count":49},{"id":"災難院前法規","short":"災難／院前／法規","name":"災難／院前／創傷體系／法規倫理","count":70},{"id":"影像FAST","short":"影像／FAST","name":"影像與 FAST","count":8},{"id":"其他","short":"其他","name":"其他（流行病學／ICD／酒駕等）","count":5}],"questions":[{"id":"95-1","year":95,"qnum":1,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷病患照護的營養支持原則，下列何者敘述為非？","opts":[{"k":"A","t":"若情況允許，應儘快恢復腸道營養。"},{"k":"B","t":"外傷病患通常都是處於負氮平衡狀況。"},{"k":"C","t":"重症外傷病患常有胃排空不良問題，有時需考慮置放鼻十二指腸導管灌食。"},{"k":"D","t":"燒傷病患的蛋白質需求量可達2 g/kg/day。"},{"k":"E","t":"重症外傷病患若需插管使用呼吸器時，可給予多一些脂肪，因為脂肪的呼吸商(respiratory quotient) 較高。"}],"answer":"E","expl":"脂肪的呼吸商約 0.7，低於碳水化合物（約 1.0），所以呼吸器依賴、CO2 滯留的病人才會「增加脂肪比例」以減少 CO2 產生；(E) 把原因說反了，故為錯誤敘述。(A)(B)(C)(D) 皆為外傷營養的標準觀念：early enteral feeding、hypercatabolism／負氮平衡、gastroparesis 時改放 post-pyloric tube、燒傷蛋白質需求可達 1.5–2 g/kg/day。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-2","year":95,"qnum":2,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"一位29 歲男性建築工人，不幸於工作時從 5 樓的鷹架直接掉落地面，被送至急診室，發現病人神智清楚，血壓為 142/92 mmHg，心跳每分鐘93 次，病患陰囊腫脹，有血尿現象，病患右下肢及股關節處疼痛無法運動，pelvic X-ray 發現unstable pelvic fracture and L5 spine fracture，在救治病患的處置中，下面的敘述那項最不適當？","opts":[{"k":"A","t":"因病患仍可能有出血性休克問題，可在建立IV catheter後，給予2L warm Lactated Ringers solution輸注。"},{"k":"B","t":"血尿表示有泌尿道傷害，應馬上置入Foley catheter引流。"},{"k":"C","t":"骨盆腔骨折可以會診專家，必要時做外固定或血管攝影。"},{"k":"D","t":"因高處墜落的機制及L5 fracture，病患生命現象穩定後可考慮做兩側跟骨(calcaneus) X-rays。"},{"k":"E","t":"做FAST排除腹內內出血是有必要的。"}],"answer":"B","expl":"血尿合併陰囊腫脹與 unstable pelvic fracture，要高度懷疑 urethral injury；在做 retrograde urethrogram 排除前不應盲目置入 Foley，所以 (B) 是最不適當的。(C)(D)(E) 皆合理：骨盆骨折可 external fixation／angioembolization，高處墜落合併 L5 fracture 要找 calcaneus fracture，FAST 為必要。","outdated":true,"suspect":false,"flagNote":"選項 (A)「2L warm LR」已不符現行觀念：ATLS 10 初始晶體液上限約 1 L，ATLS 11 更強調限制晶體液、盡早給血品與 permissive hypotension（無 TBI 時）。本題官方答案 (B) 仍成立，但勿把 (A) 當成正確做法背起來。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"95-3","year":95,"qnum":3,"topic":"休克輸血","subtopic":"總論／其他","stem":"一位17 歲女性機車乘客，不幸發生與汽車對撞車禍，被送至急診室，發現病人神智不清，明顯皮膚冰冷，蒼白，血壓為92/60 mmHg，心跳每分鐘 117 次，病患呻吟，腹部脹，超因波檢查有腹內積液現象，病患在給予輸液，輸血處理後，腹部超音波顯示腹內大量積液，於是將病患送至手術式緊急剖腹探查，發現右側肝臟裂傷大量出血，手術開始一小時後，麻醉科告知病患體溫掉至 32℃，手術視野呈現瀰漫性滲血現象，下面的敘述那項最正確？","opts":[{"k":"A","t":"因病患有出血性休克問題，並為緊急需要，此時輸血最佳選擇為O型Rh陰性血。"},{"k":"B","t":"病患低體溫最大的可能是手術室溫度過低。"},{"k":"C","t":"最佳手術方式為先以紗布墊填塞止血，再馬上照會肝臟外科專家進行右肝葉切除術。"},{"k":"D","t":"此病患手術時應使用溫毯防止體溫繼續惡化。"},{"k":"E","t":"經驗性在術前使用冷凝沉澱物(cryoprecipitate) 可以防止手術視野呈現瀰漫性滲血現象。"}],"answer":"D","expl":"體溫 32°C 加上瀰漫性滲血，代表 lethal triad（hypothermia、acidosis、coagulopathy）已啟動，此時應主動保暖（溫毯、warm fluid、提高室溫）並走 damage control surgery，所以 (D) 正確。(B) 低體溫主因是大量出血與大量輸液、暴露，不只是室溫；(C) 應 perihepatic packing 縮短手術，而非硬做 right hepatectomy；(E) 不應「經驗性」預防給 cryoprecipitate，而是依 fibrinogen 等檢驗或 MTP 給予；(A) O-neg 只在尚未能 type-specific 時使用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-4","year":95,"qnum":4,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"男性司機35歲，左胸中彈，到達急診後主述吸不到空氣、氣促，左下腋與左胸疼痛，觸診明顯皮下氣腫(crepitus)，左胸聽不到呼吸聲。下列處置最優先為：","opts":[{"k":"A","t":"安排胸部X-光，尋找彈頭。"},{"k":"B","t":"安排全身電腦斷層檢查，診斷胸廓內之肺槍傷之程度。"},{"k":"C","t":"頸部、頸椎側面X-光(C-spine lateral X-ray)。"},{"k":"D","t":"安排胸部X-光，排除張力性氣胸。"},{"k":"E","t":"評估動脈脈搏血氧濃度( pulse oximetry)，扎針解除張力性氣胸。"}],"answer":"E","expl":"張力性氣胸（呼吸窘迫、單側無呼吸音、皮下氣腫）是臨床診斷，不能等 X-ray，應立即減壓，所以 (E) 優先。(A)(B)(D) 都會延誤處置，(C) 的 C-spine film 屬於 primary survey 之後。補充：ATLS 10 把 needle decompression 位置改為第 5 肋間 anterior axillary line，院內若條件允許，finger thoracostomy／chest tube 才是確切處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-5","year":95,"qnum":5,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關中彈駕駛槍擊傷敘述，最不適當的是何者？","opts":[{"k":"A","t":"射擊後子彈以以高速運動，產生高熱，所以子彈彈頭可視為無菌消毒。"},{"k":"B","t":"子彈擊中組織產生暫時性(temporal )與永久性 (permental) 腔洞(cavitations)。"},{"k":"C","t":"治療槍擊傷患，檢查應傷者傷勢，而非調查手槍火力，子彈口徑。"},{"k":"D","t":"子彈彈頭速度越快，殺傷力越大。"},{"k":"E","t":"槍擊傷口如有滯留彈頭，子彈的摘除為最後考慮的因素。"}],"answer":"A","expl":"彈頭射出時的高溫並不能使彈頭無菌，且子彈會把衣物與皮膚碎屑帶入傷口，所以 (A) 為錯誤敘述。(B) 槍傷會形成 temporary 與 permanent cavity；(D) 動能 = ½mv²，速度越大能量越大；(C)(E) 處置重點在傷勢而非彈道細節，滯留彈頭通常不是優先處理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-6","year":95,"qnum":6,"topic":"小兒","subtopic":"總論／其他","stem":"計程車後座乘客媳婦與小孫兒，隨後由救護車送至急診。小兒下肢傷口，心跳120，血壓86mmHg，緊抱母親。逐漸出現呼吸窘迫、神智昏睡時，針對呼吸的敘述最不適當的是：","opts":[{"k":"A","t":"考慮外科氣道切開術。"},{"k":"B","t":"小兒呼吸靠橫膈運動為主。"},{"k":"C","t":"兒童對張力性氣胸，更易產生休克。"},{"k":"D","t":"兒童(AGE < 9)使用氣管內管不需氣囊(cuff)。"},{"k":"E","t":"小兒呼吸道結構與成人不同，仰臥時應保持嗅姿(Sniffing position)以防呼吸道角度過小阻塞。"}],"answer":"A","expl":"兒童到院後呼吸窘迫且有休克，最可能是 tension pneumothorax，先做胸腔減壓即可；12 歲以下兒童也不應首選 surgical cricothyroidotomy，若需要 surgical airway 是用 needle cricothyroidotomy，所以 (A) 為不適當。(B)(C)(E) 為兒童生理與氣道特徵的正確敘述。","outdated":true,"suspect":false,"flagNote":"選項 (D)「<9 歲插管不需 cuff」是舊觀念；ATLS 10 起已指出 cuffed ETT（尺寸適當、cuff 壓力監測）在兒童也可使用。本題官方答案 (A) 不變，但 (D) 在現行觀念下不再是安全的『正確敘述』。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"95-7","year":95,"qnum":7,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"計程車後座乘客該年輕媳婦為孕婦，因懷孕 8 個月而有兩個生命個體，受傷後最不適當的敘述：","opts":[{"k":"A","t":"孕婦不只有嚴重外傷，才可能危及胎兒；最有效的胎兒急救，便是維持母親的復甦。"},{"k":"B","t":"孕婦急救時，如無脊椎損傷，右側躺左側在上，防止子宮壓迫主動脈。"},{"k":"C","t":"例常監測胎兒的心跳。"},{"k":"D","t":"縱使母親血壓正常，胎兒可能已經休克。"},{"k":"E","t":"儘早會診婦產科或外科。"}],"answer":"B","expl":"妊娠 20 週以上需把子宮從 IVC 移開，正確做法是 left lateral decubitus（左側臥）或手動把子宮往左推；題目寫「右側躺左側在上」反而讓子宮壓迫 IVC，故 (B) 錯。(A) 母親穩定就是胎兒最佳急救；(C)(D)(E) 為孕婦外傷標準處置，母親血壓正常時胎盤灌流仍可能已不足。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-8","year":95,"qnum":8,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"計程車後座76歲老先生乘客，顏面直接撞擊前座椅背，到達急診後顏面嚴重腫脹，口腔內有血絲，主敘頭疼痛，有關老年外傷敘述，最不適當的是何者？","opts":[{"k":"A","t":"治療老年外傷的傷患，應檢查傷者傷勢，優先順序與原則與一般相同。"},{"k":"B","t":"老年人如有頭部外傷，症狀常延遲出現。"},{"k":"C","t":"老年外傷的預後，與罹瘓之慢性病無關。"},{"k":"D","t":"臺閩地區94年底平均壽命估計為76歲早已達到高齡化社會。"},{"k":"E","t":"隨著年齡增加，老年人的生理功能降低。"}],"answer":"C","expl":"老年外傷的預後深受共病（慢性病）、用藥（如 anticoagulant、beta-blocker）影響，所以 (C) 錯。(A) ATLS 優先順序不變；(B) 老人 head injury 可延遲出現症狀（如 chronic／delayed SDH）；(E) 生理儲備下降。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-9","year":95,"qnum":9,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"偏遠交通不便的地區，發生大型遊覽車重大交通意外事件，各方資源正陸續到達中。你奉令支援，抵現場向指揮中心報到時，指揮官表示，規模有近百人嚴重傷亡，你是第一位到現場的醫師，故委託你先擔任醫療救護組長，擔負起搶救之任務。下列救護選項，何者應會是你的適切初步想法與作為：","opts":[{"k":"A","t":"先統計現場可用之醫療用品，以合理分配作為救治傷患。"},{"k":"B","t":"先組成CPR之急救小組，搶救最急需治療的傷患。"},{"k":"C","t":"先請救護員對每位傷患作簡易之生命現象記錄與核對姓名等基本資料。"},{"k":"D","t":"先作檢傷分類，並指派資深救護員對傷患巡視作再檢傷評估。"},{"k":"E","t":"先建立通訊，以作為適當轉診、照會與治療。"}],"answer":"D","expl":"大量傷患事件到場的第一步是 triage（先分類），並指派人員反覆 re-triage；統計物資、CPR 小組、通訊建立都要晚於 triage。依 MCI 原則，資源不足時 CPR 不是優先。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-10","year":95,"qnum":10,"topic":"燒傷環境","subtopic":"低體溫與凍傷","stem":"當外傷病患出現嚴重的低體溫狀態(< 30°C)時，下列那個方法能最有效的升高體溫？","opts":[{"k":"A","t":"覆蓋加溫的被子、包布。"},{"k":"B","t":"用烤燈、電毯。"},{"k":"C","t":"靜脈輸液加溫。"},{"k":"D","t":"經由胃管或胸管用溫水灌洗。"},{"k":"E","t":"使用continuous venous hemodialysis 機器加溫。"}],"answer":"E","expl":"體溫 <30°C 屬 severe hypothermia，被動／外部加溫與加溫輸液速度太慢；需要 active core rewarming，其中 CVVH 或更積極的 ECMO／cardiopulmonary bypass 效率最高，所以 (E)。(D) 胃管／胸管灌洗雖屬 core rewarming，效果有限。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-11","year":95,"qnum":11,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列那一種外傷造成的出血不適合使用血管攝影栓塞來止血？","opts":[{"k":"A","t":"骨盆骨折。"},{"k":"B","t":"顏面骨折。"},{"k":"C","t":"肝臟外傷。"},{"k":"D","t":"腸繫膜裂傷。"},{"k":"E","t":"脾臟裂傷。"}],"answer":"D","expl":"骨盆、顏面、肝、脾的動脈性出血皆可 angioembolization；腸繫膜裂傷多合併腸壁缺血、穿孔，需要手術處理並切除或修補，單靠栓塞不適合，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-12","year":95,"qnum":12,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"ㄧ30 歲男性病患，因車禍受傷送醫。到院時 Glasgow Coma Score 為10 分，血壓135/70，心跳82/min，呼吸16/min，胸部X 光顯示mediastinal widening，頭部電腦斷層檢查顯示 acute subdural hematoma 及胸部電腦斷層檢查顯示traumatic aortic aneurysm。神經外科醫師判斷腦部暫時無需手術，但需至ICU 觀察。此時針對其主動脈瘤之處置，下列何者較合適？","opts":[{"k":"A","t":"至ICU監測，並使用降血壓劑，將收縮壓維持在100 mmHg以下。"},{"k":"B","t":"立刻進行血管攝影並將動脈瘤栓塞。"},{"k":"C","t":"立刻進行手術，切除受傷的主動脈，並以graft修補。"},{"k":"D","t":"在主動脈放置支架(stent) 。"},{"k":"E","t":"以上皆不正確。"}],"answer":"A","expl":"創傷性主動脈損傷（BTAI）合併 acute SDH，腦出血使手術與抗凝治療風險高，可先延後修補，在 ICU 使用 anti-impulse therapy（beta-blocker 為主）控制血壓與心率。(A) 符合延遲修補策略。補充：現行 SVS 指引（2011）建議需要修補時以 TEVAR 為首選，而非開胸置換；所以 (D) 是日後的確切治療，而非此刻處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-13","year":95,"qnum":13,"topic":"總論評分","subtopic":"總論／其他","stem":"下列有關各種score system 何者為非?","opts":[{"k":"A","t":"ISS (Injury Severity Score)是屬於anatomic score。"},{"k":"B","t":"GCS ( Glasgow Coma Score)是屬於physiologic score。"},{"k":"C","t":"TRISS 是合併physiologic score 和anatomic score。"},{"k":"D","t":"RTS (Revised Trauma Score)是屬於 anatomic score。"},{"k":"E","t":"APACHE 是屬於physiologic score。"}],"answer":"D","expl":"RTS 由 GCS、SBP、RR 組成，屬 physiologic score，不是 anatomic score，所以 (D) 錯。ISS、AIS 屬 anatomic；TRISS = RTS + ISS + 年齡 + 受傷機轉（blunt/penetrating）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-14","year":95,"qnum":14,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"24 y/o 男性，兇殺事件，肚臍正下方 2 公分處被生魚片刀刺入，半小時後被送至外科急診處，意識昏迷，收縮壓 70 mmHg，心跳140 次/分，呼吸 8 次/分，經緊急插管，進行resuscitation，理學檢查可見刀卡在腹壁中，此時應?","opts":[{"k":"A","t":"連同刀馬上送入手術室，聯絡相關醫師，進行剖腹術。"},{"k":"B","t":"將刀拔除，交予警方，傷口加壓止血。"},{"k":"C","t":"安排腹部電腦斷層檢查。"},{"k":"D","t":"安排血管攝影檢查。"},{"k":"E","t":"做診斷性腹腔內透析(Diagnostic peritoneal lavage)。"}],"answer":"A","expl":"Impaled object 要留在原處，直接連同刀具送手術室；SBP 70、心跳 140 為 hemorrhagic shock，已不適合做 CT、血管攝影或 DPL。(B) 拔刀可能造成大出血且失去 tamponade。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-15","year":95,"qnum":15,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關骨盆骨折出血何者錯誤?","opts":[{"k":"A","t":"靜脈出血和骨頭出血約佔 80-90％。"},{"k":"B","t":"動脈出血約佔10～20％。"},{"k":"C","t":"骨盆骨折傷患做 Diagnostic peritoneal lavage 時，false positive rate: 16～30％，建議從肚臍下開放的方法。"},{"k":"D","t":"針對動脈出血，應用血管攝影檢查。"},{"k":"E","t":"傷患接受第一次血管攝影探查止血後，如持續低血壓，又已排除腹腔出血，應緊急再做第二次血管攝影檢查。"}],"answer":"C","expl":"骨盆骨折約 80–90% 為 venous／骨髓出血，10–20% 為動脈出血。骨盆骨折若要做 DPL，應採 supraumbilical open technique，避免進入 pelvic hematoma 造成 false positive，所以 (C)「肚臍下」為錯。補充：現今 DPL 多已被 FAST／CT 取代。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-16","year":95,"qnum":16,"topic":"頭部TBI","subtopic":"總論／其他","stem":"下列診斷與處置配對何者有誤?","opts":[{"k":"A","t":"懷疑顱底骨折 (skull base fracture) –可置鼻胃管 (NG tube) 。"},{"k":"B","t":"嚴重顏面骨折併持續出血–可考慮環狀軟骨切開術(Cricothyroidectomy) 。"},{"k":"C","t":"意識清醒但呼吸道有阻塞–可放置鼻咽呼吸道 (Nas0pharyngeal airway) 。"},{"k":"D","t":"6 歲以下小孩周邊點滴放置兩次皆失敗–可考慮由脛骨骨髓腔灌注(Intraosseous injection) 。"},{"k":"E","t":"孕婦懷疑腹腔出血–由肚臍上(supra-umbilicus)作診斷性腹腔灌洗檢查(DPL) 。"}],"answer":"A","expl":"懷疑 basilar skull fracture 或中臉部骨折不應放 NG tube（可能進入顱內），改放 orogastric tube，所以 (A) 為錯誤配對。(C) 清醒者可用 NPA（但 midface fracture 時須小心）；(D) 小於 6 歲 peripheral IV 失敗兩次可用 IO；(E) 孕婦 DPL 要在臍上做。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-17","year":95,"qnum":17,"topic":"休克輸血","subtopic":"總論／其他","stem":"處理低血容性休克(hypovolemic shock)時,下列何者為組織灌流(tissue perfusion)已經足夠之最可信指標?","opts":[{"k":"A","t":"血壓。"},{"k":"B","t":"脈博壓。"},{"k":"C","t":"中心靜脈壓。"},{"k":"D","t":"尿量。"},{"k":"E","t":"心跳。"}],"answer":"D","expl":"低血容休克中，單看 BP、HR 不夠可靠；傳統教科書以尿量（成人 0.5 mL/kg/hr、兒童 1 mL/kg/hr）作為 end-organ perfusion 的指標，故為 (D)。補充：現代也會一併追蹤 lactate 與 base deficit；CVP 不是可靠的 volume 指標。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-18","year":95,"qnum":18,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"關於老人外傷，何者錯誤？","opts":[{"k":"A","t":"老人外傷的死亡率(mortality rate)是年輕人的3-4倍。"},{"k":"B","t":"大於65歲的老人，最常見的外傷機轉是跌倒。"},{"k":"C","t":"老人外傷的預後與個人原本的身體狀態有非常大的相關，意外發生有時可能導因於內科疾病。"},{"k":"D","t":"老人的胸部外傷常有嚴重的合併症，如肺部擴張不全、肺炎等。"},{"k":"E","t":"老人的胸部外傷不應給予止痛以免造成呼吸抑制。"}],"answer":"E","expl":"老人胸部外傷更需要良好止痛（regional block、epidural、多模式止痛）才能咳痰、避免 atelectasis 和 pneumonia；因怕呼吸抑制而不給止痛會增加併發症，所以 (E) 錯。(A)(B)(C)(D) 為 geriatric trauma 的標準觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-19","year":95,"qnum":19,"topic":"腹部","subtopic":"脾臟","stem":"一位25歲男性機車騎士，為了閃躲右前方衝出來的小朋友，連人帶車往左側滑倒，被送至急診室時，身上無明顯外傷，主述左側肋骨下緣疼痛。在做初步評估時，病人開始燥動不安，Systolic blood pressure為115mmHg，心跳每分鐘100次，FAST發現有腹內出血。給予2000㏄ 輸液及PRBC 2U後，Systolic blood pressure為130mmHg，心跳每分鐘85次。急診醫師室安排了腹部電腦斷層檢查發現是第三級脾臟撕裂傷合併腹內出血，您是南部某教學醫院的外傷值班醫師，下列處置何者有誤？","opts":[{"k":"A","t":"此病患應安排緊急剖腹探查及脾臟切除術。"},{"k":"B","t":"此病患可考慮非手術治療方式。"},{"k":"C","t":"此病患應於加護病房密切關察生命跡象、Hb 及Hct 值。"},{"k":"D","t":"採取非手術治療方式最常見的併發症為遲發性出血，較常見於前幾天。"},{"k":"E","t":"對於年齡較老或合併其他嚴重相關傷害的病患，如頭部外傷，非手術治療方式的失敗率(failure rate)較高。"}],"answer":"A","expl":"血流動力學穩定（對輸液有反應）的 Grade III 脾臟撕裂傷可採 non-operative management，所以 (A)「應緊急手術」為錯。NOM 需要 ICU／密切監測、Hb 追蹤，delayed bleeding 多在前幾天，高齡與合併嚴重傷害（如 TBI）時失敗率較高。補充：WSES／EAST 皆主張穩定者不論 grade 皆可 NOM，有 blush 可加 angioembolization。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-20","year":95,"qnum":20,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"一位32歲男性，酒後與他人爭執，不幸被人以西瓜刀砍傷左手腕，受傷被送至急診室，病人意識清醒，左手腕掌側有一六公分長、一公分深的切割傷口，大量鮮血冒出，血壓呈現收縮壓100mmHg，心跳每分鐘96次，呼吸速率每分鐘24次，有關急診室外傷醫師第一線處置，下面的敘述那項有誤？","opts":[{"k":"A","t":"傷口檢查後，立即直接將傷口加壓包紮。"},{"k":"B","t":"傷口檢查時，若見到動脈血管斷裂噴血，必須立即以血管夾將動脈斷端夾住。"},{"k":"C","t":"傷口檢查後，儘快聯絡整形外科或血管外科醫師處理。"},{"k":"D","t":"安排左手腕X-ray檢查。"},{"k":"E","t":"建立靜脈輸液路徑，給予生理食鹽水點滴注射。"}],"answer":"B","expl":"大血管損傷的第一線是 direct pressure（必要時 tourniquet），不可在視野不佳時盲目用 hemostat 夾，容易傷到旁邊的 median／ulnar nerve 與其他血管，所以 (B) 錯。(A)(C)(D)(E) 為標準處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-21","year":95,"qnum":21,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"病人受到嚴重傷害後，體內新陳代謝會發生改變，他的何種荷爾蒙分泌在受傷後會下降?","opts":[{"k":"A","t":"Glucagon。"},{"k":"B","t":"Arginine vasopressin。"},{"k":"C","t":"Prolactin。"},{"k":"D","t":"Insulin。"},{"k":"E","t":"以上皆可。"}],"answer":"D","expl":"創傷後 stress response 會使 glucagon、cortisol、catecholamine、ADH（vasopressin）、prolactin 皆上升；insulin 早期因 catecholamine 抑制分泌而下降，並出現 insulin resistance，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-22","year":95,"qnum":22,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"38歲男性業務員騎機車過馬路時，不慎和對方來車相撞，119送他到醫院時，發現他下巴中間有凹陷，臉部和口腔都在流血，右側脖子腫脹，血壓86/60 mmHg、心跳126/min、呼吸24/min，下列何種醫囑要先執行？","opts":[{"k":"A","t":"臉部和口腔壓迫止血。"},{"k":"B","t":"下巴固定。"},{"k":"C","t":"輸林格氏液2000ml。"},{"k":"D","t":"口咽氣管插管。"},{"k":"E","t":"環甲軟骨切開術 (cricothyroidotomy)。"}],"answer":"D","expl":"有下巴凹陷、口腔出血、頸部腫脹，ABC 的 A 最優先；此時應先確保氣道，口咽氣管插管（同時保護 C-spine）為優先，若插管失敗再做 surgical airway (cricothyroidotomy)。壓迫止血、輸液與下巴固定都在氣道之後。補充：現行 ATLS 對輸液主張限制晶體液，「林格氏液 2000 mL」不是首選。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-23","year":95,"qnum":23,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"以下何者不是”angioembolization for pelvic fracture”之適應症？","opts":[{"k":"A","t":"blood transfusion > 8 U in 24 hours。"},{"k":"B","t":"large pelvic hematoma。"},{"k":"C","t":"hemodynamic instability with positive FAST。"},{"k":"D","t":"pelvic pseudoaneurysm by helical CT。"},{"k":"E","t":"blood transfusion > 12 U in 48 hours。"}],"answer":"C","expl":"血流動力學不穩定且 FAST 陽性代表腹內出血要優先 laparotomy，而非單純血管栓塞，故 (C) 不是 angioembolization 適應症。其他：大量輸血、large pelvic hematoma、CT 見 contrast blush／pseudoaneurysm 都是栓塞指徵。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-24","year":95,"qnum":24,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"以下何者不是”abdominal compartment syndrome”之臨床表現？","opts":[{"k":"A","t":"increased venous return。"},{"k":"B","t":"increased intrathoracic pressure。"},{"k":"C","t":"decreased blood flow to gastrointestinal tract。"},{"k":"D","t":"increased systemic vascular resistance。"},{"k":"E","t":"decreased renal blood flow。"}],"answer":"A","expl":"Abdominal compartment syndrome 的特徵為腹內壓升高，壓迫 IVC 使 venous return 下降、cardiac output 下降、SVR 上升、intrathoracic pressure 上升、腸胃道與腎灌流下降，所以 (A)「venous return 增加」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-25","year":95,"qnum":25,"topic":"氣道","subtopic":"總論／其他","stem":"有關外傷病患之呼吸道處置原則，下列敘述何者有誤？","opts":[{"k":"A","t":"決定經口氣管或鼻氣管插管之最重要因素為醫師本身之經驗。"},{"k":"B","t":"對無呼吸之傷患仍可進行經鼻氣管插管。"},{"k":"C","t":"有嚴重顏面上頷骨(faciomaxillary)骨折之病患需給予呼吸道保護處置。"},{"k":"D","t":"動脈血氧濃度(PaO2)為30 mmHg 時血色素氧氣飽和度為60%。"},{"k":"E","t":"當昏迷指數(GCS)低於8 分(含)以下時應儘速進行插管處置。"}],"answer":"B","expl":"無自發呼吸（apnea）者不可做 blind nasotracheal intubation，因其仰賴病人自發吸氣；應改為經口插管或 surgical airway，所以 (B) 錯。(D) PaO2 30 mmHg 約對應 SaO2 約 60%；(E) GCS ≤8 通常需要 definitive airway。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-26","year":95,"qnum":26,"topic":"休克輸血","subtopic":"總論／其他","stem":"對於一位遭受嚴重外傷休克送至急診室之年輕病人，檢查發現脈膊：126 跳/分，血壓：90/65 mmHg，呼吸：36 次/分，尿量每小時10 ml，在初步判斷上，下列敘述何者有誤？","opts":[{"k":"A","t":"其出血等級屬第三級 (class III)。"},{"k":"B","t":"病人會出現焦躁及意識糢糊之情形。"},{"k":"C","t":"此時應繼續觀察血壓是否有惡化再決定是否給予輸液治療。"},{"k":"D","t":"若需給液應以crystalloids 及血液輸注為主。"},{"k":"E","t":"其出血量應在1500-2000 ml 左右。"}],"answer":"C","expl":"HR 126、RR 36、BP 90/65、UO 10 mL/hr 為 class III–IV hemorrhagic shock，需要立即給 crystalloid 與血品，不能「繼續觀察」，所以 (C) 錯。(A)(B)(E) 為 class III（失血 30–40%，約 1500–2000 mL）的描述。","outdated":true,"suspect":false,"flagNote":"選項 (D)「crystalloids 及血液輸注」仍沿用舊 ATLS；ATLS 10/11 建議初始晶體液上限約 1 L，並盡早給 blood products（MTP、1:1:1 balanced ratio）。官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"95-27","year":95,"qnum":27,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"小兒遠端肱骨髁上骨折(Supracondylar frcture)，最常合併的神經傷害為：","opts":[{"k":"A","t":"尺神經(Ulnar nerve)。"},{"k":"B","t":"橈神經(Radial nere)。"},{"k":"C","t":"肌皮神經(Musculocutaneous nerve)。"},{"k":"D","t":"正中神經(Median nerve)。"},{"k":"E","t":"臂神經(Axillary nerve)。"}],"answer":"D","expl":"小兒 supracondylar fracture 最常傷 anterior interosseous nerve（為 median nerve 的分支），所以選 median nerve；另要留意 brachial artery injury 與 Volkmann ischemic contracture。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-28","year":95,"qnum":28,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"8歲男孩騎腳踏車撞上車門，生命跡象穩定，但他哭訴腹部疼痛。身體檢查只發現其上腹部有擦傷，腹部壓起來軟軟地沒有反彈痛，驗血檢查發現澱粉酵素酶(Amylase)指數220 Iu，尿液檢查有 2-5 個 RBCs，以下敘述何者正確？","opts":[{"k":"A","t":"儘管腹部電腦斷層顯示正常，他還是有可能胰臟挫傷並且需要住院觀察。"},{"k":"B","t":"進行靜脈內腎盂攝影，對血尿的評估。"},{"k":"C","t":"在這個機轉中腸子是最普遍受傷的器官。"},{"k":"D","t":"如果再次檢查腹痛改善，不太可能是十二指腸血腫。"},{"k":"E","t":"在這個機轉中肝臟是最普遍受傷的器官。"}],"answer":"A","expl":"腹部鈍傷後 amylase 升高、早期 CT 正常仍可能是 pancreatic contusion／duct injury，需要住院觀察、serial exam，所以 (A)。(B) IVP 已非血尿評估首選；(C)(E) 在兒童腳踏車把手機轉中，常見受傷器官是脾、肝；(D) 腹痛暫時改善並不能排除 duodenal hematoma。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-29","year":95,"qnum":29,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"40歲男性司機發生重大車禍，他有繫安全帶，當時其生命跡象BP：90/60mmHg H/R:120 /分；R/R︰20 /min；身體檢查發現GCS 15，有瀰漫性腹痛，骨盆腔不穩定，初部X光顯示open book fracture，並且FAST 顯示 mrison’s pouch 有大量積液，請問下一步是？","opts":[{"k":"A","t":"剖腹探查術(celiotomy)。"},{"k":"B","t":"骨盆腔血管攝影及栓塞。"},{"k":"C","t":"心包膜穿刺術(Pericardiocentesis)。"},{"k":"D","t":"骨科手術會診。"},{"k":"E","t":"觀察。"}],"answer":"A","expl":"血壓 90/60、HR 120，骨盆不穩定（open book）並 FAST 在 Morison's pouch 見大量積液，血流動力學不穩定且腹內出血來源明確，優先 celiotomy 止血，同時 pelvic binder；之後再評估 pelvic angioembolization。(C) 與題幹無心包填塞表現；(D)(E) 都延誤。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-30","year":95,"qnum":30,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"一懷孕30 週27 歲孕婦於行駛中機車後座跌落，並遭尾隨轎車碾過頭及胸部，在救護車抵達你所在的創傷中心急診室時，她的 Glagscow Coma Scale 為3分，10 分鐘後雖已建立 ABC，但量不到血壓、且心電圖呈現PEA 隨即停止(arrest)，你是Trauma Team 的外科醫師，請問以下處置何者錯誤？","opts":[{"k":"A","t":"先重新評估 (re-evaluation)，包括檢查已建立的呼吸道。"},{"k":"B","t":"加強輸液及緊急輸O型血。"},{"k":"C","t":"進行CPR三十分鐘，若無效則考慮急診室開胸術(ED Thoracotomy)。"},{"k":"D","t":"於arrest五分鐘內決定進行 perimortem cesarean delivery。"},{"k":"E","t":"在ED進行cesarean delivery 時必須對母親持續復甦不可停止。"}],"answer":"C","expl":"(C) 為錯：孕婦 arrest 時不應等 30 分鐘才決定，應在 arrest 後 4–5 分鐘內進行 perimortem cesarean delivery（可改善母親 venous return 與胎兒存活），這屬於 resuscitative hysterotomy。(A) 先重新評估氣道與 reversible causes；(B) 補充容積與輸血；(D)(E) 為標準處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-31","year":95,"qnum":31,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"關於咬傷(Bite injury)，下面的敘述何項正確？","opts":[{"k":"A","t":"動物咬傷的常見致病菌為 Eikenella corrodens。"},{"k":"B","t":"人咬傷(Human bites)經常的致病菌為Pseudomonas aeruginosa。"},{"k":"C","t":"需施打 Toxoid，因致病菌全為厭氧菌 (anaerobic infection)。"},{"k":"D","t":"治療咬傷的建議抗生素為 β-lactam antibiotic 合併β-lactam inhibitor。"},{"k":"E","t":"若咬傷超過24小時未就醫者，有80%會導致截肢。"}],"answer":"D","expl":"咬傷預防用抗生素的標準選擇是 amoxicillin-clavulanate（β-lactam + β-lactamase inhibitor），涵蓋 Pasteurella multocida（動物咬傷）、Eikenella corrodens（人咬傷）與 anaerobes，所以 (D)。(A)(B) 菌種配對錯誤；(C) 破傷風預防是 tetanus toxoid／TIG，而非全部厭氧菌；(E) 誇大。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-32","year":95,"qnum":32,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"關於創傷嚴重指數(Injury Severity Score)，下面的敘述何項正確？","opts":[{"k":"A","t":"共分有五大項記分區域，Glasgow Coma Scale為其中記分項目。"},{"k":"B","t":"由AIS(Abbreviated Injury Severity)的分數總合而成。"},{"k":"C","t":"ISS最高記分為75分。"},{"k":"D","t":"相同ISS分數的外傷病患中，男性年齡大於65歲者，死亡率才會明顯較高。"},{"k":"E","t":"只要認真記分，急診室就可正確完成ISS記分，這對病患預後極有參考價值。"}],"answer":"C","expl":"ISS 最高分為 75（任一區域 AIS 6 分即直接計 75），所以 (C)。(A) ISS 有六個身體區域，不含 GCS；(B) 是三個最嚴重 AIS 區域「平方和」，不是總和；(D)(E) 錯誤。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-33","year":95,"qnum":33,"topic":"總論評分","subtopic":"總論／其他","stem":"一位50歲男性原住民的卡車司機，因打瞌睡於高速公路追撞前方連結車，卡在前座達20分鐘，到達你的急診時，血壓80/40mmHg、意識清楚但躁動不安，腹部脹大、左腿變形，下列何項處置不適當？","opts":[{"k":"A","t":"給予林格氏輸液2L後，血壓若成60/40mmHg時，應準備剖腹探查手術，並同時輸血。"},{"k":"B","t":"腦部電腦斷層檢查是必要的。"},{"k":"C","t":"床邊腹部超音波(FAST)是必要的，應可加速手術的決定。"},{"k":"D","t":"中心靜脈導管的放置不應拖延進手術室的時間。"},{"k":"E","t":"血氧計讀數92％因為血壓低故僅可供參考。"}],"answer":"B","expl":"血壓 80/40 的不穩定病人應優先 resuscitation 與 FAST／決定是否 laparotomy，不宜先送去做腦部 CT，所以 (B) 為不適當。(C)(D)(E) 為合理處置，血氧計在低灌流時不準確。","outdated":true,"suspect":false,"flagNote":"選項 (A)「給 Ringer's 2L」依 ATLS 10/11 已不被推薦：初始晶體液約 1 L 為上限，應盡早 blood products（MTP）。官方答案 (B) 不變，但請勿記成 2L 是標準。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"95-34","year":95,"qnum":34,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"請依序由1至5診斷配合的可能受傷機轉診 斷 機 轉\n1. Fracture of Scaphoid 甲、 Wrist hyperextension\n2. Posterior dislocation of hip 乙、 Rotatory ankle force\n3. Calcaneus fracture 丙、 Striking knee against dashboard on car collision\n4. Fracture of any of the malleoli 丁、 Landing on outstretched arm\n5. Fracture of radial head 戊、 Landing on feet from height","opts":[{"k":"A","t":"甲、戊、丙、乙、丁。"},{"k":"B","t":"丁、戊、丙、乙、甲。"},{"k":"C","t":"甲、丙、戊、乙、丁。"},{"k":"D","t":"丁、丙、戊、乙、甲。"},{"k":"E","t":"以上皆非。"}],"answer":"C","expl":"配對：Scaphoid fracture 為 wrist hyperextension（甲）；posterior hip dislocation 為膝撞 dashboard（丙）；calcaneus fracture 為由高處落下以足著地（戊）；malleolar fracture 為 rotatory ankle force（乙）；radial head fracture 為 FOOSH（丁）。依序「甲、丙、戊、乙、丁」，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-35","year":95,"qnum":35,"topic":"氣道","subtopic":"總論／其他","stem":"一位50 歲男性機車騎士，不幸發生車禍，被送至急診室，急救後送至加護病房照顧，此時如何判斷呼吸(Ventilation)需要給予換氣支持(Ventilatory support)，下面的敘述都是有關需要呼吸換氣支持(Ventilatory support)的使用條件，其中那項是錯誤的？","opts":[{"k":"A","t":"Respiratory rate 大於每分鍾35 次。"},{"k":"B","t":"動脈血中PaCO2 大於60 mmHg。"},{"k":"C","t":"Alveolar-arterial oxygen difference 大於350 mmHg。"},{"k":"D","t":"VD/VT大於0.6。"},{"k":"E","t":"Shunt fraction為5%。"}],"answer":"E","expl":"需要 ventilatory support 的常見標準包括 RR >35、PaCO2 >60 mmHg、A-a gradient >350 mmHg（FiO2 1.0）、VD/VT >0.6；shunt fraction 正常 <5%，要到 >20% 才代表明顯 shunt，所以 (E) 5% 不是需要支持的條件。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-36","year":95,"qnum":36,"topic":"休克輸血","subtopic":"總論／其他","stem":"有關復甦急救，下列敘述何者錯誤？","opts":[{"k":"A","t":"外傷中心必須在急診之外，獨立發展出一個有效率的外傷急救團隊。"},{"k":"B","t":"急診部門，應該有一個大的空間被指定設計來做為外傷之急救區域。"},{"k":"C","t":"急救區域必須包含：足夠的電話、電話線路以及對講機，但不接入非急救相關之電話。"},{"k":"D","t":"根據任務，外傷團隊成員與器械擺放的位置，是經過協調而固定的。"},{"k":"E","t":"復甦急救時間寶貴，緊急床邊X光照像(portable)應盡早完成。"}],"answer":"A","expl":"外傷急救團隊是在急診部門內整合、而非另外獨立於急診之外發展，所以 (A) 錯。(B)(C)(D)(E) 屬於 trauma resuscitation room 的設計與團隊分工原則，床邊 portable X-ray（CXR、pelvis）應在 primary survey 同時完成。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-37","year":95,"qnum":37,"topic":"休克輸血","subtopic":"總論／其他","stem":"一名29 歲女性自高處墜落，送至貴院急診時血壓為 120/80 mmHg，神智清楚，下列處置何者較不正確？","opts":[{"k":"A","t":"一律先戴上頸圈。"},{"k":"B","t":"一律給予氧氣。"},{"k":"C","t":"一律打上大口徑靜脈管路。"},{"k":"D","t":"一律給予2000ml 輸液。"},{"k":"E","t":"一律要照頸椎側照，CXR 及骨盆X 光檢查。"}],"answer":"D","expl":"血壓正常、清醒的高處墜落病人，不需要「一律」2000 mL 輸液；應建立 IV 並依反應給予，所以 (D) 最不正確。(A)(B)(C)(E) 為高能量機轉的標準 primary survey 處置（C-collar、O2、large-bore IV、C-spine/CXR/pelvis）。","outdated":true,"suspect":false,"flagNote":"(E)「一律照頸椎側位」已不是現行做法：臨床上以 NEXUS／Canadian C-spine rule 或直接 CT 評估頸椎；高能量機轉多半直接做 CT C-spine。官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"95-38","year":95,"qnum":38,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關DPL(Diagnostic Peritoneal Lavage)之敘述，何者為非？","opts":[{"k":"A","t":"DPL 之Sensitivity 高，Specificity 較低。"},{"k":"B","t":"對於懷孕之婦女，施行DPL 時，abdomen 之Incision wound 必須在umbilicus下方1 公分處。"},{"k":"C","t":"施行DPL 前，應先置放 NG 及Foley Catheter。"},{"k":"D","t":"DPL 較易偵測bowel injury or perforation。"},{"k":"E","t":"DPL 較不易偵測diaphragm rupture。"}],"answer":"B","expl":"DPL 對孕婦要在 umbilicus 之上（supraumbilical）開放式進行，避免傷到增大的子宮，所以 (B)「臍下 1 公分」為錯。(A) DPL 敏感度高、專一性較低；(C) 需先置 NG（減少胃擴張）與 Foley（減少膀胱受傷）；(D) 易偵測腸道損傷；(E) 對橫膈與後腹腔傷害不敏感。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-39","year":95,"qnum":39,"topic":"腹部","subtopic":"脾臟","stem":"下列有關blunt spleen injury 之敘述何者為非？","opts":[{"k":"A","t":"對於hemodynamically unstable 之病人，手術仍是最好之選擇。"},{"k":"B","t":"非手術療法non-operative management(NOM)已成為主要治療選擇。"},{"k":"C","t":"於abdominal CT 上若可見spleen之顯影劑逸出(contrast extravasation)，則NOM之成功機會大。"},{"k":"D","t":"liver cirrhosis 之病人NOM較不易成功。"},{"k":"E","t":"目前有許多Trauma center 已採用血管栓塞(Angioembolization)做為輔助治療方式。"}],"answer":"C","expl":"CT 見 contrast extravasation（blush）代表有 active bleeding，NOM 失敗風險較高，需要 angioembolization 或手術，所以 (C)「成功機會大」為錯。(A) 不穩定病人仍以手術為首選；(D) cirrhosis 者 NOM 較難成功；(E) angioembolization 為 NOM 輔助。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-40","year":95,"qnum":40,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"關於head injury 下列何者為錯？","opts":[{"k":"A","t":"Autoregulation often impaired in moderate or severe brain injury."},{"k":"B","t":"Acute epidural hematoma is higher mortality rate than acute subdural hematoma."},{"k":"C","t":"Epidural hematoma 常伴隨著skull fracture."},{"k":"D","t":"Contusion 常發生於 frontal base or temporal tip."},{"k":"E","t":"有C-spine injury 的病人，不可以作oculocephalic test."}],"answer":"B","expl":"Acute epidural hematoma 若及時手術預後通常優於 acute SDH（SDH 常合併底層腦實質傷害），所以 (B) 錯。(A) autoregulation 在中重度 TBI 常受損；(C) EDH 常合併 skull fracture（middle meningeal artery）；(D) contusion 好發於 frontal base、temporal tip；(E) 懷疑 C-spine injury 不可做 oculocephalic test。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-41","year":95,"qnum":41,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"The hallmarks of neurogenic shock are hypotension with：","opts":[{"k":"A","t":"Tachycardia"},{"k":"B","t":"Bradycardia"},{"k":"C","t":"Tachypnea"},{"k":"D","t":"Hyperpyrexia"},{"k":"E","t":"Arrhythmia"}],"answer":"B","expl":"Neurogenic shock（高位脊髓損傷，頸胸髓）是交感神經失去張力，表現為低血壓合併 bradycardia、四肢溫暖；hemorrhagic shock 則是 tachycardia。故 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-42","year":95,"qnum":42,"topic":"燒傷環境","subtopic":"電擊傷","stem":"十八歲男性，在工作時被2000伏特電流電擊，送到醫院時，右手及右腳肢端呈現二度灼傷，capillary refill為兩秒鐘，GCS為E4V5M6，收縮壓為100 mmHg，脈博為90 bpm，請問以下何者為非？","opts":[{"k":"A","t":"必須監測心電圖。"},{"k":"B","t":"無內出血之可能。"},{"k":"C","t":"必須監測尿量。"},{"k":"D","t":"必須觀察肢體腔室症候群(compartment syndrome)。"},{"k":"E","t":"組織的電阻大小: 骨骼＞皮膚＞神經血管。"}],"answer":"B","expl":"高壓電燒傷表面傷口常低估，內部組織可能有深層破壞，應注意 cardiac arrhythmia（ECG monitoring）、rhabdomyolysis（尿量 >1 mL/kg/hr 以上、監測 myoglobinuria）與 compartment syndrome；電流穿過身體也可能造成 blunt 合併傷，所以 (B)「無內出血可能」錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-43","year":95,"qnum":43,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"二十歲男性，騎機車與汽車相撞，送至醫院時收縮壓為80 mmHg，對叫喚有反應，但四肢完全不會動，且無感覺反應，肛門收縮(anal tone)消失，請問以下何者有誤？","opts":[{"k":"A","t":"極可能為頸椎脊髓損傷，應盡速照會神經外科。"},{"k":"B","t":"即使是神經性休克，仍需輸液灌注，但須監測血容狀態。"},{"k":"C","t":"若確診為頸椎脊髓損傷，應給予高劑量類固醇滴注，初始 bolus 劑量為30 mg/kg，維持劑量為5.4 mg/kg/hr。"},{"k":"D","t":"若脊髓損傷已超過 8 小時，但未超過24 小時，高劑量類固醇滴注仍建議給予。"},{"k":"E","t":"應先排除胸腹腔內出血的可能。"}],"answer":"D","expl":"頸髓損傷合併低血壓、四肢無力、anal tone 消失，要先排除出血，才能歸因於 neurogenic shock；高劑量 methylprednisolone 的適應是 NASCIS II 的 8 小時內，超過 8 小時不應給，所以 (D) 為錯。","outdated":true,"suspect":false,"flagNote":"選項 (C)（NASCIS II 30 mg/kg + 5.4 mg/kg/hr）在今日已不被推薦：ATLS 10、AANS/CNS 2013 指引皆不建議常規使用 high-dose steroid for acute SCI（副作用大、效益不確定）。官方答案 (D) 不變，但 (C) 不應再當成標準處置背。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"95-44","year":95,"qnum":44,"topic":"頭部TBI","subtopic":"總論／其他","stem":"36歲男性病人，車禍送至急診處，呼吸速率: 20/min，心博速: 120/min，血壓: 110/68 mmHg，SaO2: 98%，昏迷指數 = E2V2M4，瞳孔不等大: 6 mm/3 mm (左大於右)，右前臂骨折，頭皮十公分撕裂傷，請問下列處置何者適當？\n(1) 使用頸圈固定頸部 (2) 清除呼吸道 (3) 給氧氣(4) 建立二條靜脈路徑，給予1500 c.c.生理食鹽水點滴注射(5) 安排腦斷層","opts":[{"k":"A","t":"(1)、(2)、(3)。"},{"k":"B","t":"(1)、(2)、(3)、(5)。"},{"k":"C","t":"(2)、(3)、(4)。"},{"k":"D","t":"(1)、(2)、(3)、(4)、(5)。"},{"k":"E","t":"(4)、(5)。"}],"answer":"D","expl":"GCS 8（E2V2M4）合併左側瞳孔放大，要想到 transtentorial herniation；處置包含頸圈、清除氣道、給氧、IV、輸液維持 BP、盡快 CT，所以本題官方答案 (D)。TBI 需避免 hypotension 與 hypoxia。","outdated":true,"suspect":false,"flagNote":"題目中「1500 c.c. 生理食鹽水」是舊式大量輸液做法；ATLS 10/11 建議初始晶體液上限約 1 L 並盡早給血，TBI 病人以維持 SBP ≥100–110 mmHg（BTF）為目標，另需 airway protection（GCS ≤8 須插管）與 osmotherapy 準備。官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"95-45","year":95,"qnum":45,"topic":"頭部TBI","subtopic":"輕度頭部外傷 CT 適應症（Canadian CT Head Rule）","stem":"輕度頭部外傷病人接受電腦斷層檢查準則的guideline 包括","opts":[{"k":"A","t":"受傷後 2 小時，沒有恢復到 GCS score 15 分。"},{"k":"B","t":"疑似有顱骨骨折的現象例如腦脊髓液鼻漏、耳漏等。"},{"k":"C","t":"局部神經學異常。"},{"k":"D","t":"嚴重顏面損傷。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"輕度頭部外傷（GCS 13–15）符合以下任一條件宜做 head CT：受傷 2 小時後 GCS 仍 <15、疑似 skull fracture（CSF rhinorrhea／otorrhea）、focal neurologic deficit、嚴重顏面損傷、年齡 ≥65、抗凝血劑等（Canadian CT Head Rule），故 (E) 皆是。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-46","year":95,"qnum":46,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"肢體外傷造成的腔室症候群(Compartment syndrome)最早期臨床症狀是？","opts":[{"k":"A","t":"疼痛。"},{"k":"B","t":"肢體乏力。"},{"k":"C","t":"壓痛。"},{"k":"D","t":"脈搏摸不到。"},{"k":"E","t":"深層腱反射喪失( Loss of deep tendon reflex)。"}],"answer":"A","expl":"Compartment syndrome 最早的症狀是 pain out of proportion，尤其被動牽拉時加劇，所以 (A)。Pulselessness、paralysis、loss of reflex 為晚期表現，不應等到才處理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-47","year":95,"qnum":47,"topic":"顏面頸部","subtopic":"總論／其他","stem":"外傷導致恆久齒脫落(avulsed tooth)時，以下描述何者為非？","opts":[{"k":"A","t":"30 分鐘內重新植入socket效果最好。"},{"k":"B","t":"每超過一分鐘重植之成功率降低1%。"},{"k":"C","t":"牛奶為適合的替代保存液，是由於Na與Cl濃度。"},{"k":"D","t":"Hank solution是最適合的。"},{"k":"E","t":"接獲電話求援時應教導病患嚐試植入。"}],"answer":"C","expl":"Avulsed permanent tooth 要盡快 re-implantation（30 分鐘內最好，成功率隨時間下降），保存液以 Hank's balanced salt solution 最佳，牛奶為替代方案；牛奶適合的原因是 osmolality 與 pH 較接近、含細胞營養，並非「Na、Cl 濃度」，所以 (C) 錯。電話求救時教導現場嘗試植入可提高保住率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-48","year":95,"qnum":48,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"下列有關central cord syndrome 的描述何者為非?","opts":[{"k":"A","t":"常見於老人。"},{"k":"B","t":"大多肇因於Hyperflexion。"},{"k":"C","t":"Upper extremity motor weakness 大於lower extremity motor weakness。"},{"k":"D","t":"會有urinary retension。"},{"k":"E","t":"患者常患有cervical stenosis。"}],"answer":"B","expl":"Central cord syndrome 多為 hyperextension injury（常見於老年人 cervical spondylosis／stenosis），因 ligamentum flavum 皺褶壓迫脊髓，表現為上肢無力 > 下肢，常伴 urinary retention；所以 (B)「hyperflexion」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-49","year":95,"qnum":49,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下述那種腹部外傷，既使做了腹膜灌洗術(diagnostic peritoneal lavage)也當不易診斷出來？","opts":[{"k":"A","t":"肝臟撕裂傷。"},{"k":"B","t":"小腸破裂。"},{"k":"C","t":"十二指腸破裂。"},{"k":"D","t":"腸繫膜破裂。"},{"k":"E","t":"脾臟外膜破裂。"}],"answer":"C","expl":"DPL 偵測腹腔內（intraperitoneal）出血或腸液很靈敏，但 duodenum 大部分在 retroperitoneum，破裂時腹膜腔液體量少，DPL 可能呈假陰性，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-50","year":95,"qnum":50,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"一個28 歲男性摩托車騎士發生車禍，入急診時意識不清，臉部變形，口鼻中有鮮血持續湧出，呼吸窘促，嘗試經口咽插氣管內管時，病患躁動，無法清楚看到聲帶，應考慮如何建立呼吸道：","opts":[{"k":"A","t":"Bronchoscope guided intubation。"},{"k":"B","t":"先放Laryngeal mask airway爭取時間。"},{"k":"C","t":"環狀甲狀軟骨間切開術( Cricothyroidotomy )。"},{"k":"D","t":"以rapid sequence intubation減少病患躁動。"},{"k":"E","t":"氣管切開術。"}],"answer":"C","expl":"嚴重顏面外傷、口鼻持續出血、無法看清聲帶，屬 failed airway／can't intubate can't oxygenate 情境，此時應立即 cricothyroidotomy，而非繼續嘗試 bronchoscope、LMA 或 RSI；急診不選 tracheostomy 是因耗時與風險較高。故 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-51","year":95,"qnum":51,"topic":"顏面頸部","subtopic":"食道外傷","stem":"一位25歲年青男性於星期五餐廳，和人發生爭吵遭刺傷於於脖子，傷口沿著左側Sternocleidomastoid muscle之前，約Cricoid cartilage的相對高度位置，你是值班醫師檢視傷口時發現此穿刺傷明顯己穿過Platysma muscle，此時以下處置何者最正確","opts":[{"k":"A","t":"此病患需進入加護病房以防止血腫變大導致呼吸道阻塞。"},{"k":"B","t":"需做Bronchoscopy，若沒有異常，便直接留觀即可。"},{"k":"C","t":"需做Flexible Esophagoscopy，若沒有異常，便直接留觀即可。"},{"k":"D","t":"需做Carotid arteriography，若沒有異常，便直接留觀即可。"},{"k":"E","t":"需開刀探查脖子(Exploration)。"}],"answer":"E","expl":"依傳統教學，Zone II 的穿刺傷若穿透 platysma，一律需要 neck exploration，所以官方答案 (E)。","outdated":true,"suspect":false,"flagNote":"現行觀念已改為 selective management：血流動力學穩定且無 hard signs 者先做 CTA neck，再依結果決定是否 esophagoscopy／探查（EAST 2008、WTA 與 ATLS 10 皆採此原則）；只有 hard signs（expanding hematoma、active bleeding、airway compromise、shock）才需立即手術。考試仍照官方答案 (E)，臨床則要看有無 hard signs。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"95-52","year":95,"qnum":52,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"一位20歲男性機車騎士，不幸撞上安全島並且安全帽脫落，被送至急診室，發現病人神智不清，四肢癱瘓，此時病人需確切維持呼吸道，但又發現這是一個氣管內插管困難(Difficult intubation)的病人，此時最佳處理方法為","opts":[{"k":"A","t":"做氣切術(Tracheostomy)。"},{"k":"B","t":"做環狀甲狀軟骨間膜切開術(Cricothyroidotomy)。"},{"k":"C","t":"於支氣管鏡指引下做插氣管內管(Fiberoptic bronchoscopic insertion of endotracheal tube)。"},{"k":"D","t":"給予鼻咽呼吸道(Nasophargngeal airway)。"},{"k":"E","t":"給予口咽呼吸道(Orophargngeal airway)。"}],"answer":"C","expl":"昏迷合併四肢癱瘓，需保護頸椎的 difficult airway，在 can-ventilate 的前提下，最合理是 fiberoptic bronchoscopic intubation（in-line stabilization 下氣管插管），所以 (C)；若 can't intubate can't oxygenate 才轉 cricothyroidotomy。補充：今日 video laryngoscope／bougie 已成為常用的第一線工具。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-53","year":95,"qnum":53,"topic":"災難院前法規","subtopic":"總論／其他","stem":"在外傷中心對於外病患的照顧，外傷發生後的第一小時最主要的死因是？","opts":[{"k":"A","t":"頭部外傷。"},{"k":"B","t":"多重器官衰竭。"},{"k":"C","t":"大量出血。"},{"k":"D","t":"感染。"},{"k":"E","t":"體溫過低。"}],"answer":"C","expl":"外傷死亡的 trimodal distribution 中，最初一小時內（含 golden hour）最大的死因是大量出血與中樞神經損傷；本題選項中以 (C) hemorrhage 為最佳。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-54","year":95,"qnum":54,"topic":"氣道","subtopic":"Definite airway／插管方式選擇","stem":"在施行RSI (快速依序麻醉誘導插管) 之前，第一步要進行的動作是:","opts":[{"k":"A","t":"Jaw Thrust 及將床單墊於背後擺好姿勢 (position) 等輔助插管步驟。"},{"k":"B","t":"通知麻醉科請派人支援。"},{"k":"C","t":"行 Sellick Maneuver 使插管時 vocal cord 較易看到。"},{"k":"D","t":"以 Succinylcholine 進行麻醉誘導。"},{"k":"E","t":"將氣切包 (Tracheostomy Set) 準備好，必要時進行 Surgical Airway 以外科手術方法建立呼吸道。"}],"answer":"E","expl":"RSI 前的準備（Preparation）包括預氧、擺位、藥品、人員與 backup plan（surgical airway kit）。官方答案 (E) 強調先備妥外科氣道，是『failed airway 預案』的觀念。","outdated":false,"suspect":true,"flagNote":"選項 (A)(B)(E) 都屬於 RSI 前的準備，題目問「第一步」沒有單一明確答案，(E) 為官方答案但依據薄弱；另外 (C) Sellick maneuver 在現行指引已不再常規建議。考試仍以 (E) 為準，但本題不宜用來推論臨床優先順序。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"95-55","year":95,"qnum":55,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"關於軍陣外傷的戰場處置，下面的敘述何項有誤？","opts":[{"k":"A","t":"對所有傷者的處置，仍以查看呼吸道是否暢通為優先。"},{"k":"B","t":"自越戰以來戰傷的死亡率約為20%，但最近的伊拉克戰爭已有下降趨勢。"},{"k":"C","t":"戰傷所致的肢體出血，止血帶(tourniquet)的使用已列為絕對禁忌症。"},{"k":"D","t":"前進外科小組FST(Forward Surgical Team)使戰傷患者儘早接受創傷控制手術。"},{"k":"E","t":"各種外用止血劑中，以QuickClot最為有效，每次建議用量為100公克。"}],"answer":"C","expl":"戰場 Tactical Combat Casualty Care（TCCC）主張對可致命的肢體大出血要儘早使用 tourniquet，不是禁忌，所以 (C) 錯。(D) FST 提供 damage control surgery；(E) 外用止血劑目前以 hemostatic gauze（如 QuickClot Combat Gauze）為代表。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"95-56","year":95,"qnum":56,"topic":"ICU營養併發症","subtopic":"總論／其他","stem":"20歲年輕機車騎士，車禍後多重性外傷，合併顱內出血、胸部肋骨骨折、連枷胸與血胸，下肢腿骨骨折，住院後已使用呼吸器。連續兩天，血中氧氣分壓偏低，P(A-a)O2分壓差200mmHg，最可能的診斷是：","opts":[{"k":"A","t":"肺挫傷 (Pulmonary contusion) 。"},{"k":"B","t":"肺栓塞 (Pulmonary embolism) 。"},{"k":"C","t":"呼入性肺炎 (Aspiration pneumonia) 。"},{"k":"D","t":"以上皆非。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"flail chest 與 hemothorax 病人可能同時有 pulmonary contusion、PE（下肢骨折、制動、TBI 高危）與 aspiration pneumonia，都可使 A-a gradient 上升，P(A-a)O2 200 mmHg 無法區分，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-1","year":96,"qnum":1,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"一位51 歲男性騎摩托車時於交通繁忙的路口與逆向車對撞而飛出五公尺遠，送到急診時呈現右側胸壁變形、病人呼吸急促、但心跳音可清楚聽見。由脈衝式血氧飽和濃度測量器 (Pulse oximetry) 所測得血氧飽和濃度 (SpO2) 呈現極低 80%的情況。外傷科醫師在放入右側胸管接上水封防漏胸瓶 (Underwater-seal chest bottle)後，血氧飽和濃度 (SpO2) 一度可上昇到90%，但接著卻又向下降，且急救間外傷護理師發現持續有大量氣泡自胸瓶冒出，而胸管至胸瓶間無接合不良漏氣情况。此時應首先高度懷疑下列那種外傷?","opts":[{"k":"A","t":"心包膜填塞 (Cardiac tmponade)"},{"k":"B","t":"橫膈膜破裂 (Diaphragmatic rupture)"},{"k":"C","t":"創傷性窒息 (Traumatic asphyxia)"},{"k":"D","t":"支氣管破裂 (Tracheobronchial tree injury)"},{"k":"E","t":"食道破裂 (Esophageal rupture)"}],"answer":"D","expl":"已置胸管後仍持續大量 air leak、肺無法擴張，氧合惡化，要高度懷疑 tracheobronchial tree injury（多在 carina 2.5 cm 內的主支氣管）。其他選項無此表現：心包填塞會有 Beck's triad、橫膈破裂與食道破裂不會出現大量持續氣泡。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-2","year":96,"qnum":2,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"承上題: 此時最恰當的診斷處置為：","opts":[{"k":"A","t":"緊急剖胸探查 (Emergency thoracotomy)"},{"k":"B","t":"環甲切開術 (Cricothyroidotomy) 建立確定呼吸道"},{"k":"C","t":"氣管鏡檢查 (Bronchoscopy)"},{"k":"D","t":"心包膜穿刺 (Pericardiocentesis)"},{"k":"E","t":"緊急剖腹探查 (Emergency laparotomy)"}],"answer":"C","expl":"疑似 tracheobronchial injury 的確診方式是 bronchoscopy，同時可評估損傷位置並協助插管；不應盲目開胸。(B) 環甲切開對下氣道損傷無幫助。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-3","year":96,"qnum":3,"topic":"胸部","subtopic":"VATS／ECMO","stem":"承上題: 外傷醫師在採取了恰當的處置後，SpO2 卻持續低於70%，病人血壓漸漸下降，病人瀕臨死亡，於此非常緊急情况下可能最迅速最有效的處置為施行：","opts":[{"k":"A","t":"左側主支氣管插管 (Left main-stem bronchial intubation) 行單肺呼吸"},{"k":"B","t":"ECMO (Extra-Corporeal Membrane Oxygenation)"},{"k":"C","t":"緊急剖胸探查 (Emergency Thoracotomy)"},{"k":"D","t":"心包膜穿刺 (Pericardiocentesis)"},{"k":"E","t":"緊急剖腹探查 (Emergency laparotomy)"}],"answer":"A","expl":"主支氣管撕裂導致大量漏氣、低血氧時，最迅速的措施是 selective intubation of the contralateral main bronchus（受傷在右側，故插入左側），行單肺通氣，讓健側氧合；之後再手術修補。ECMO 需時間與設備，緊急開胸也非最快。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-4","year":96,"qnum":4,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"於一場路邊幫派槍擊中，計程車駕駛 35 歲男性意外被流彈擊中左胸，導致對撞車禍。到達急診後主述吸不到空氣、氣促，左下腋與左胸疼痛，觸診明顯皮下氣(Cepitus)，左胸聽不到呼吸聲，病人呈現休克狀態。下列處置最優先為：","opts":[{"k":"A","t":"安排胸部X-光，尋找彈頭。"},{"k":"B","t":"安排全身電腦斷層檢查，診斷胸廓內之肺槍傷之程度。"},{"k":"C","t":"頸部、頸椎側面X-光(C-spine lateral X-ray)。"},{"k":"D","t":"安排胸部X-光，排除張力性氣胸。"},{"k":"E","t":"評估動脈血氧濃度(O2 saturation)，扎針(Needle thoracostomy) 解除張力性氣胸。"}],"answer":"E","expl":"同 95-4：張力性氣胸合併休克，是臨床診斷，要馬上減壓，不能等 X-ray 或 CT，所以 (E)。補充：ATLS 10 的 needle decompression 位置為第 5 肋間 anterior axillary line，院內更建議 finger thoracostomy／chest tube。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-5","year":96,"qnum":5,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重腹部外傷手術時，下列那一項不是屬於損害控制處置(Damage control procedure)？","opts":[{"k":"A","t":"將受傷的腸道切除並以 autosuture 完成anastomosis"},{"k":"B","t":"將斷裂的輸尿管直接作 ligation"},{"k":"C","t":"將裂傷的脾臟直接摘除"},{"k":"D","t":"將裂傷出血的肝臟以大紗布填塞壓迫"},{"k":"E","t":"以上都是損害控制處置(Damage control procedure)"}],"answer":"A","expl":"Damage control surgery 的原則是縮短手術時間，不做複雜重建：出血控制 packing、腸道破裂用 stapler 或 clamp 暫時關閉、輸尿管可結紮或 stent，並暫時關腹，所以 (A) 腸切除加 anastomosis 不屬於 damage control。脾臟破裂直接 splenectomy 是快速止血的選項。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-6","year":96,"qnum":6,"topic":"腹部","subtopic":"肝臟","stem":"肝臟裂傷病患合併下列何種狀況不適合採用非手術治療(Non-operative treatment)?","opts":[{"k":"A","t":"第四級及第五級肝臟裂傷"},{"k":"B","t":"合併頭部外傷"},{"k":"C","t":"65 歲老年人"},{"k":"D","t":"合併小腸穿孔"},{"k":"E","t":"合併多處骨折"}],"answer":"D","expl":"血流動力學穩定時，高 grade（IV–V）肝損傷、頭部外傷、高齡或多處骨折本身都不是 NOM 的絕對禁忌；但合併 hollow viscus injury（小腸穿孔）需要剖腹手術，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-7","year":96,"qnum":7,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列那一種外傷造成的出血不適合使用血管攝影栓塞(Angiographic embolization) 來止血?","opts":[{"k":"A","t":"骨盆骨折"},{"k":"B","t":"顏面骨折"},{"k":"C","t":"肝臟裂傷"},{"k":"D","t":"腸繫膜裂傷"},{"k":"E","t":"脾臟裂傷"}],"answer":"D","expl":"同 95-11：腸繫膜損傷常合併腸道缺血或穿孔，需要手術探查；骨盆、顏面、肝、脾的動脈出血都可 angioembolization，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-8","year":96,"qnum":8,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"一位29 歲男性建築工人，不幸於工作時從 5 樓的鷹架直接掉落地面，被送至急診室，發現病人神智清楚，血壓為 142/92 mmHg，心跳每分鐘93 次，病患陰囊腫脹，有血尿現象，病患右下肢及股關節處疼痛無法運動，pelvic 及L spine X-ray發現unstable pelvic fracture and L5 spine fracture，在救治病患的處置中，下面的敘述那項最不適當？","opts":[{"k":"A","t":"因病患仍可能有出血性休克問題，可在建立 IV catheter 後，給予 2 L warm Lactated Ringer’s solution 輸注。"},{"k":"B","t":"血尿表示有泌尿道傷害，應馬上置入 Foley catheter 引流。"},{"k":"C","t":"骨盆腔骨折可以會診專家，必要時做外固定或血管攝影。"},{"k":"D","t":"因高處墜落的機制及 L5 fracture，病患生命現象穩定後可考慮做兩側跟骨(Calcaneus) X-rays。"},{"k":"E","t":"做FAST 排除腹內內出血是有必要的。"}],"answer":"B","expl":"同 95-2：血尿合併陰囊腫脹與 pelvic fracture，要先懷疑 urethral injury，未做 retrograde urethrogram 前不可盲目置 Foley，故 (B) 最不適當。","outdated":true,"suspect":false,"flagNote":"選項 (A)「2L warm LR」依 ATLS 10/11 已不被推薦（初始晶體液上限約 1 L，儘早 blood products）。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"96-9","year":96,"qnum":9,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"根據 2003 年update Modified CPP-targeted Therapy，在嚴重頭部外傷的成人病患腦部灌流壓力(Cerebral perfusion pressure)的最低限度為:","opts":[{"k":"A","t":"40mmHg"},{"k":"B","t":"60mmHg"},{"k":"C","t":"80mmHg"},{"k":"D","t":"90mmHg"}],"answer":"B","expl":"依 Brain Trauma Foundation 2003 年版，成人 severe TBI 的 CPP 應 ≥60 mmHg，避免為提高 CPP 而過度輸液／升壓（>70 mmHg 有 ARDS 風險）；所以 (B)。補充：BTF 第 4 版（2016）建議 CPP 目標 60–70 mmHg。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-10","year":96,"qnum":10,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"下列何者屬於第三等級(Class Ⅲ)出血狀況？","opts":[{"k":"A","t":"Blood loss 15-30％，pulse rate ＞120，respiratory rate 30-40"},{"k":"B","t":"Blood loss 30-40％，pulse rate ＞140，respiratory rate ＞35"},{"k":"C","t":"Blood loss ＞40％，pulse rate ＞120，respiratory rate ＞35"},{"k":"D","t":"Blood loss 30-40％，pulse rate ＞120，respiratory rate 30-40"},{"k":"E","t":"Blood loss ＞40％，pulse rate ＞140，respiratory rate 30-40"}],"answer":"D","expl":"ATLS 失血分級：Class I <15%；Class II 15–30%（HR 100–120）；Class III 31–40%（HR 120–140、RR 30–40、SBP 下降）；Class IV >40%（HR >140、RR >35）。故 (D) 為 Class III。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-11","year":96,"qnum":11,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部鈍傷之診斷方法中，下列敍述何者錯誤？","opts":[{"k":"A","t":"DPL 對腹內出血之診斷有高敏感性及專一性"},{"k":"B","t":"FAST(Focussed Assessment Sonography in Trauma)可用於偵測低血壓病人腹內液體堆積部位"},{"k":"C","t":"FAST 不易偵測横膈膜、腸道及胰臟傷害"},{"k":"D","t":"CT scan 對腹部鈍傷之診斷專一性最高"},{"k":"E","t":"DPL 檢查可能偵測不到後腹腔之傷害"}],"answer":"A","expl":"DPL 對腹內出血敏感度高，但專一性較差（會把微量出血也驗陽性），所以 (A)「高專一性」為錯。(B)(C)(E) FAST 不易偵測橫膈、腸道、胰臟與後腹腔傷害；(D) CT 專一性最高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-12","year":96,"qnum":12,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"肢體肌肉骨骼外傷時有關皮節感覺神經之測試，下列何者為誤？","opts":[{"k":"A","t":"前臂內側感覺屬T1 皮節神經"},{"k":"B","t":"大腿內側感覺屬L3 皮節神經"},{"k":"C","t":"足部外側感覺屬S1 皮節神經"},{"k":"D","t":"上臂外側感覺屬C6 皮節神經"},{"k":"E","t":"小腿內側感覺屬L4 皮節神經"}],"answer":"D","expl":"上臂外側感覺為 C5 dermatome，不是 C6（C6 為拇指與前臂外側），所以 (D) 錯。其他：前臂內側 T1、大腿內側 L3、足外側 S1、小腿內側 L4 都正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-13","year":96,"qnum":13,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"外傷病患接受治療時，下列何者是 Indication for Emergency thoracotomy？","opts":[{"k":"A","t":"Release cardiac tamponade"},{"k":"B","t":"Control intrathoracic hemorrhage"},{"k":"C","t":"Thoracic aortic cross-clamping"},{"k":"D","t":"Control massive air embolism"},{"k":"E","t":"以上都是"}],"answer":"E","expl":"急診開胸（resuscitative thoracotomy）的目的包括：解除 cardiac tamponade、控制胸內出血、對 descending thoracic aorta 做 cross-clamping 以維持腦與心臟灌流、處理 massive air embolism 或 bronchovenous fistula，所以 (E)。依 EAST/WTA 指引，穿刺傷、有生命徵象者最受益，鈍傷效益較低。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-14","year":96,"qnum":14,"topic":"腹部","subtopic":"肝臟","stem":"下列有關嚴重肝臟外傷病患接受手術治療的敘述，那一項是不正確的？","opts":[{"k":"A","t":"手術後應放置Sump drain 以降低膿瘍的產生"},{"k":"B","t":"Perihepatic packing 在48 小時內拿掉可降低感染率"},{"k":"C","t":"為達成Intrahepatic hemostasis 的目的，常會使用Finger fracture technique"},{"k":"D","t":"Pringle maneuver 可在術中減少失血量"},{"k":"E","t":"以上都正確"}],"answer":"A","expl":"嚴重肝外傷術後不建議放 sump drain，因為開放式引流易逆行感染、增加膿瘍；若要引流，用 closed suction drain。(B) perihepatic packing 通常 24–72 小時內再手術取出；(C) finger fracture 與 (D) Pringle maneuver 均為肝止血手法。故 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-15","year":96,"qnum":15,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重穿刺傷病患，當必須接受 Damage control surgery 時，下列那一條血管不宜直接ligate？","opts":[{"k":"A","t":"Celiac axis"},{"k":"B","t":"Common hepatic artery"},{"k":"C","t":"Portal vein"},{"k":"D","t":"Superior mesenteric artery"},{"k":"E","t":"Internal iliac artery"}],"answer":"D","expl":"Damage control 時，celiac axis、common hepatic artery（GDA 以遠有側枝）、portal vein 及 internal iliac artery 在緊急情況可結紮；SMA 結紮會造成廣泛腸缺血，應修補或 temporary shunt，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-16","year":96,"qnum":16,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"24 歲健康騎士，因機車跌倒受傷就診。到達急診後，生命徵象、血循穩定，陳敘腹痛，臆斷為內臟破裂出血。如果採行保守性非手術治療，最不適當的處置為？","opts":[{"k":"A","t":"立即緊急輸血，全血 2000 cc。"},{"k":"B","t":"嚴密監測生理功能。"},{"k":"C","t":"安排腹部超音波檢查。"},{"k":"D","t":"安排腹部電腦斷層檢查。"},{"k":"E","t":"排氣與食慾回復前，暫時禁食。"}],"answer":"A","expl":"血流動力學穩定的腹部鈍傷採 NOM，需監測、影像（FAST／CT）與禁食，不需要預先「全血 2000 cc」，輸血是依出血情況，所以 (A) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-17","year":96,"qnum":17,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"前述病患，腹部電腦斷層檢查可見脾臟內有 5 公分血腫，左腎周圍亦伴隨 1 公分血塊(perirenal hematoma)，右側橫膈、肝葉間與空腸、空腸間有游離氣(free air)，一段空腸壁肥厚亦可見。你的處置為？","opts":[{"k":"A","t":"持續觀察治療。"},{"k":"B","t":"安排核磁共振，排除橫膈傷害。"},{"k":"C","t":"安排血管攝影，排除小腸血管傷害。"},{"k":"D","t":"緊急剖腹探查術。"},{"k":"E","t":"安排胃鏡檢查。"}],"answer":"D","expl":"CT 見 free air、腸壁肥厚，是 hollow viscus injury（small bowel perforation）的訊號，需要 laparotomy，而不是繼續保守治療，所以 (D)。脾臟血腫與 perirenal hematoma 可 NOM，但腸穿孔優先決定手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-18","year":96,"qnum":18,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"急診室常需診治119 送入之頭頸部創傷病患，且是置於硬長背板上並已為病患戴上頸圈固定，針對脊椎可能之潛在損傷，必需牢記的重點與原則，下面的敘述那項有誤？","opts":[{"k":"A","t":"針對清醒的病患，能清楚表示頸部活動無礙與不痛者，可不作頸椎之 X-ray檢查，取下頸圈"},{"k":"B","t":"當病患以硬長背板固定傷患送抵急診後，我們通常是在 secondary survey作背部理學評估時移除之"},{"k":"C","t":"當發現病患有頸椎引起之肢體癱瘓現象時，應儘量持續置於其長背板上，保持其正中姿態"},{"k":"D","t":"當發現病患有非穿刺之脊索損傷，於 8 小時內者，可使用高劑量 methylprednisolone治療"},{"k":"E","t":"對於不清醒之躁動傷患，可使用短效型之鎮定葯物，以利檢查與治療進行"}],"answer":"C","expl":"頸椎癱瘓病人應盡快脫離硬背板，避免壓瘡並在 log-roll 下維持脊椎對位，所以 (C)「儘量持續置於長背板上」為錯。(A) 清醒、無痛、無神經症狀、無 distracting injury 可依 NEXUS 臨床清除頸椎；(B) 在 secondary survey 移除背板；(E) 躁動者可短效鎮靜，以利檢查。","outdated":true,"suspect":false,"flagNote":"選項 (D)「非穿刺性脊髓損傷 8 小時內可使用 high-dose methylprednisolone」是 NASCIS II 的舊觀念；ATLS 10、AANS/CNS 2013 皆已不建議常規使用。官方答案 (C) 不變，(D) 不應再背為標準。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"96-19","year":96,"qnum":19,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"在山區發生一輛大型遊覽車翻入山谷之重大交通意外；院方指示你帶領兩位醫護人員就近前往救援。事故現場已有警官指揮 119 人員搶救中，指揮官表示，估計約有50 人傷亡，你是第一位到現場的資深醫師，故請你負責現場緊急醫療。\n下列選項，何者會是你的適切初步想法與作為：","opts":[{"k":"A","t":"先發揮 CPR 急救小組技能，搶救心跳停止的重傷病患"},{"k":"B","t":"先彙集現場可用之急救醫療用品，分類以作有效分配與利用"},{"k":"C","t":"先製作傷患姓名表，快速核對出病患資料，以利後續後送治療"},{"k":"D","t":"先作病患檢傷分類，標示出受傷嚴重度及後送優先次序"},{"k":"E","t":"先建置視訊系統，以作為適當轉診、照會與治療指引"}],"answer":"D","expl":"大量傷患現場，第一位到場資深醫師的優先任務是 triage 與指揮，而非 CPR 或寫名單；因為資源有限時，要先把最能受益的傷者辨識出來，也要設立 triage／treatment／transport 區域。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-20","year":96,"qnum":20,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"對於外傷導致大量血胸以下處置何者不正確？","opts":[{"k":"A","t":"大量血胸是指出血大於 1500 ml 或者全身血量1/3"},{"k":"B","t":"應放置較粗之胸管，例如# 36 French"},{"k":"C","t":"若胸管放置後，立即引流超過 1500 ml 血液，應儘早手術"},{"k":"D","t":"胸管引流量每小時 200 ml 以上，維持2 - 4 小時，也應儘早手術"},{"k":"E","t":"胸管引流之血液顏色是否鮮紅，也是決定開胸手術的很好依據"}],"answer":"E","expl":"大量血胸（massive hemothorax）定義為初始引流 >1500 mL 或持續 >200 mL/hr 達 2–4 小時，需要開胸。血液顏色（動脈或靜脈血）無法可靠決定是否開胸，所以 (E) 錯。補充：ATLS 10 建議胸管 28–32 Fr，臨床上不需一定用 36 Fr。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-21","year":96,"qnum":21,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"二十歲男性，騎機車與汽車相撞，送至醫院時收縮壓為 80 mmHg，對叫喚有反應，但四肢完全不會動，且無感覺反應，肛門收縮(Anal tone)消失，請問以下何者有誤？","opts":[{"k":"A","t":"極可能為頸椎脊髓損傷，應盡速照會神經外科。"},{"k":"B","t":"即使是神經性休克，仍需輸液灌注，但須監測血容狀態。"},{"k":"C","t":"若確診為頸椎脊髓損傷，可給予高劑量類固醇滴注，初始 bolus 劑量為30 mg/kg，維持劑量為5.4 mg/kg/hr。"},{"k":"D","t":"若脊髓損傷已超過 8 小時，但未超過24 小時，高劑量類固醇滴注仍建議給予。"}],"answer":"D","expl":"同 95-43：頸髓損傷合併低血壓時，要先排除出血（neurogenic shock 為診斷排除）；NASCIS II 建議的 steroid 限於 8 小時內，超過 8 小時不應給，故 (D) 為錯。","outdated":true,"suspect":false,"flagNote":"選項 (C) 的 methylprednisolone 方案（30 mg/kg bolus + 5.4 mg/kg/hr）現在已不建議常規使用（ATLS 10、AANS/CNS 2013）。官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"96-22","year":96,"qnum":22,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"有一位45 歲女性體重 60 公斤因為火災造全身燒傷面積如下：一度燒傷 10%，二度燒傷20%以及三度燒傷 20%。請問根據Parkland 公式，應該給予這位病患在發生燒傷後的八小時內給予多少體液的補充？","opts":[{"k":"A","t":"4200 ML"},{"k":"B","t":"4800 ML"},{"k":"C","t":"6000 ML"},{"k":"D","t":"9600 ML"},{"k":"E","t":"12000 ML"}],"answer":"B","expl":"Parkland formula = 4 mL × 體重 (kg) × %TBSA（只算 second 與 third degree，不含 first degree）。60 kg × 40% × 4 = 9600 mL／24 小時，前 8 小時給一半 = 4800 mL，所以 (B)。補充：ATLS 10 建議起始速率改為 2 mL/kg/%TBSA，再依尿量（成人 0.5 mL/kg/hr）調整，以避免 fluid creep。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-23","year":96,"qnum":23,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列關於孕婦生理變化及外傷處理的敘述何者最適當？","opts":[{"k":"A","t":"孕婦的血量較一般狀況為低，稱作生理性貧血。"},{"k":"B","t":"孕婦的凝血因子相對不足，容易出血。"},{"k":"C","t":"孕婦受傷急救時，為減少下腔靜脈壓迫，要考慮右側臥。"},{"k":"D","t":"急救孕婦時發生胎兒流產的最多原因是子宮破裂。"},{"k":"E","t":"即使是懷孕期，不尋常的受傷情况仍應考慮家暴的可能性。"}],"answer":"E","expl":"孕婦受傷若有不尋常機轉或傷痕，應警覺 intimate partner violence，(E) 為最適當。(A) 孕婦血漿增加多於紅血球，造成 physiologic anemia，但總血量增加；(B) 凝血因子偏高為 hypercoagulable state；(C) 應採 left lateral tilt（左側臥）；(D) 流產的最常見原因為 placental abruption。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-24","year":96,"qnum":24,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"下列關於嬰幼兒急救的敘述，何者最不適當？","opts":[{"k":"A","t":"治療原則及優先順序與成人相同。"},{"k":"B","t":"嬰兒對缺氧的敏感度特別明顯。"},{"k":"C","t":"若有氣道阻塞，且無法順利插管，不論年紀均應實施環甲狀軟骨切開術。"},{"k":"D","t":"若無法建立靜脈輸注管線，六歲以下小孩可考慮先用骨內釘做骨髓內注射。"},{"k":"E","t":"在休克治療時，靜脈輸液起始量為 20 ml/kg。"}],"answer":"C","expl":"兒童（尤其 <12 歲）氣道阻塞又無法插管時，應做 needle cricothyroidotomy，不是 surgical cricothyroidotomy，因為小兒環甲膜小、喉結構脆弱，所以 (C)「不論年紀」為錯。(D) <6 歲 IV 失敗可用 IO；(E) 休克起始給 20 mL/kg crystalloid；補充：ATLS 10 對兒童出血性休克建議先 20 mL/kg 晶體液，之後盡早用 10 mL/kg pRBC。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-25","year":96,"qnum":25,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下列關於胰臟外傷處理的概念何者最適當？","opts":[{"k":"A","t":"經常合併其他腹內傷害。"},{"k":"B","t":"診斷工具以診斷性腹膜內灌洗為首選。"},{"k":"C","t":"有嚴重胰臟外傷，早期一定有症狀。"},{"k":"D","t":"血清澱粉脢濃度唯一重要診斷指標。"},{"k":"E","t":"即使病患生命現象不穩定，若無確切診斷，仍不應該做剖腹探查。"}],"answer":"A","expl":"胰臟外傷多半合併其他腹內器官損傷（如肝、脾、十二指腸、血管），診斷延遲常見；早期症狀不明顯，amylase 非唯一指標，CT 與 MRCP/ERCP 評估 main duct injury 較重要，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-26","year":96,"qnum":26,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"下列關於外傷初級評估及治療的概念何者不適當？","opts":[{"k":"A","t":"即使第一次初級評估為正常，一有變化，要立即再評估。"},{"k":"B","t":"以有生命威脅的狀況要優先評估並處理。"},{"k":"C","t":"需有詳細的實驗室檢查及病史詢問。"},{"k":"D","t":"一定要初級評估處置後且病患生命現象初步穩定時，才能進行到二級評估。"},{"k":"E","t":"要轉送病人前，應再做一次初級評估。"}],"answer":"C","expl":"Primary survey 的重點是辨識與處置危及生命的問題（ABCDE），過程中不做詳細實驗室檢查與詳細病史；AMPLE history 與檢驗屬 secondary survey，所以 (C) 錯。補充：ATLS 10 也提到需於轉送前再評估、狀況變化立即回到 primary survey。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-27","year":96,"qnum":27,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"30y/o 男性，高樓墜落事故，被送至醫院急診室，診斷為骨盆骨折，腹腔內出血休克，緊急送至手術室接受剖腹術，發現有腸繫膜裂傷出血，十二指腸及胰臟頭斷裂，骨盆後腹膜腔血腫，術中出血總量已過 5000cc,base deficit<-15 mmol/L，此時你決定做 Damage control，則下列處置方法，何者不恰當？","opts":[{"k":"A","t":"腸繫膜裂傷結紮縫合止血"},{"k":"B","t":"修補十二指腸及胰臟頭止血，Packing"},{"k":"C","t":"探查骨盆後腹膜腔血腫"},{"k":"D","t":"腹壁快速縫合"},{"k":"E","t":"送回加護病房，繼續 resuscitation"}],"answer":"C","expl":"Damage control 在嚴重出血、低體溫、酸中毒時，只做止血與控制污染，不做複雜重建：(A)(B)(D)(E) 為 damage control 內容（結紮出血、壓迫止血、暫時關腹、轉 ICU 復甦）；(C) 不應去探查 pelvic retroperitoneal hematoma，除非 expanding／pulsatile，否則會破壞 tamponade，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-28","year":96,"qnum":28,"topic":"頭部TBI","subtopic":"腦死判定與器官捐贈","stem":"下列何者非腦死(Brain death)之必要條件?","opts":[{"k":"A","t":"GCS=3"},{"k":"B","t":"無瞳孔反射"},{"k":"C","t":"無腦幹反射"},{"k":"D","t":"昏迷超過十年"},{"k":"E","t":"無自發性呼吸"}],"answer":"D","expl":"Brain death 的必要條件包括：先排除可逆因素（藥物、低體溫、代謝），並確認 coma、brainstem reflexes absent（瞳孔、角膜、gag、oculocephalic 等）、無自發呼吸（apnea test）。「昏迷超過十年」不屬標準，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-29","year":96,"qnum":29,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"有關Central cord syndrome，下列何者為非?","opts":[{"k":"A","t":"上肢比下肢症狀更嚴重"},{"k":"B","t":"常因Hyperextension injury 造成"},{"k":"C","t":"癒後不佳"},{"k":"D","t":"因Anterior spinal artery 受損造成"},{"k":"E","t":"常發生在退化性頸椎"}],"answer":"C","expl":"Central cord syndrome 的典型表現是上肢無力重於下肢、常見於退化性頸椎狹窄的 hyperextension injury；一般預後比其他 incomplete SCI 好（常見下肢先恢復、ambulation 可達多數），所以官方答案 (C)「預後不佳」為非。","outdated":false,"suspect":true,"flagNote":"選項 (D)「因 anterior spinal artery 受損」其實也是錯：ASA 損傷造成的是 anterior cord syndrome，central cord syndrome 機轉是 hyperextension 與灰質中央受損。(C)(D) 兩者皆有爭議，官方答案以 (C) 為準，但請注意 (D) 本身也是錯誤敘述。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"96-30","year":96,"qnum":30,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"下列何種燒燙傷不需轉診至燒傷中心?","opts":[{"k":"A","t":"40 歲男性全身8% BSA partial-thickness burns"},{"k":"B","t":"9 歲女童全身11% BSA full-thickness burns"},{"k":"C","t":"臉部和生殖器燒燙傷"},{"k":"D","t":"8% BSA full-thickness burns"},{"k":"E","t":"5 歲男童全身8% BSA partial-thickness burns"}],"answer":"A","expl":"依 ABA 轉診標準，成人 partial-thickness burn <10% TBSA 不需要轉診；所有 full-thickness burn、臉／手／足／會陰／生殖器／大關節燒傷、兒童（無適當設備時）都建議轉診，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-31","year":96,"qnum":31,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"20 歲女性右膝被小客車撞傷，.X 光檢查發現右膝關節脫臼，對脫臼之敘述何者錯誤？","opts":[{"k":"A","t":"膝關節脫臼常見於年輕女性膝蓋在外翻(Genu valgus)姿勢時遭遇外力"},{"k":"B","t":"膝關節脫臼可能引起膝膕動脈(Popliteal artery)損傷"},{"k":"C","t":"常合併前脛神經損傷"},{"k":"D","t":"如果有軟骨，肌腱卡著，需開刀復位"},{"k":"E","t":"在復位前，通常須靜脈注射麻醉劑及鎮定劑"}],"answer":"C","expl":"膝關節脫位（knee dislocation）高風險併發症為 popliteal artery injury 與 common peroneal nerve injury；若軟組織／半月板卡住 irreducible 需手術復位，復位前通常需鎮靜或麻醉。官方答案指 (C)「前脛神經」為錯。","outdated":false,"suspect":true,"flagNote":"題目有疑點：(A)「常見於年輕女性、膝外翻」與實際流行病學不符（高能量外傷、男性較常見），而 (C)「前脛神經」可能是 peroneal nerve 的誤譯。(A)(C) 皆有爭議，考試以官方答案 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"96-32","year":96,"qnum":32,"topic":"頭部TBI","subtopic":"總論／其他","stem":"關於顱骨骨折之描述何者為非？","opts":[{"k":"A","t":"顱穹窿骨折(Vault fracture)為最常見，常為線狀骨折"},{"k":"B","t":"顱穹窿骨折若發生在聶部形成中硬腦膜動脈破裂，會發生蛛網膜下出血"},{"k":"C","t":"顱底骨折(Basilar fracture)大多會貫穿岩樣骨及副鼻竇"},{"k":"D","t":"顱底骨折可能會出現耳漏或鼻漏之臨床現象"},{"k":"E","t":"Battle’s sign 為後顱窩骨折之徵候"}],"answer":"B","expl":"Middle meningeal artery 受損造成的是 epidural hematoma，不是 subarachnoid hemorrhage，所以 (B) 錯。(A) vault fracture 最常見、多為 linear；(C)(D) basilar fracture 常波及 petrous bone／paranasal sinuses，出現 CSF otorrhea／rhinorrhea；(E) Battle's sign 為 posterior fossa／mastoid 表現。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-33","year":96,"qnum":33,"topic":"頭部TBI","subtopic":"總論／其他","stem":"頭部外傷倒地神智不清之患者，急救依 ABCDE 原則處置過程中，不能忽略的動作","opts":[{"k":"A","t":"迅速氣管插管"},{"k":"B","t":"迅速放置導尿管"},{"k":"C","t":"保護頸部"},{"k":"D","t":"迅速放置胸管"}],"answer":"C","expl":"頭部外傷、意識不清的病人必須假設有 c-spine injury，在 primary survey 時應先 manual in-line stabilization 並使用頸圈，保護頸部不能忽略，所以 (C)。氣管插管與胸管要視狀況，導尿管不屬 primary survey 必要步驟。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-34","year":96,"qnum":34,"topic":"腹部","subtopic":"肝臟","stem":"下列何者部位受傷有最差的存活率？","opts":[{"k":"A","t":"The infrahepatic vena cava"},{"k":"B","t":"The vena cava in the area of the renal veins"},{"k":"C","t":"The retrohepatic vena cava"},{"k":"D","t":"The external iliac vein"},{"k":"E","t":"The portal vein"}],"answer":"C","expl":"Retrohepatic IVC injury 死亡率最高（約 50% 以上），因位置深、被肝臟包覆而難暴露，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-35","year":96,"qnum":35,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"評估外傷嚴重度有很多種方法，其中一種是 Abbreviated Injury Scale，請問此種方法把身體分為幾個部位？","opts":[{"k":"A","t":"3"},{"k":"B","t":"4"},{"k":"C","t":"5"},{"k":"D","t":"6"},{"k":"E","t":"7"}],"answer":"D","expl":"考題寫「AIS 把身體分為 6 部位」符合 ISS 的六個身體區域，但原始 AIS 本身的分區為 9 個（AIS 2005：head、face、neck、thorax、abdomen、spine、upper extremity、lower extremity、external）；官方答案 (D) 6 是將 AIS 與 ISS 混合。","outdated":false,"suspect":true,"flagNote":"題目把 AIS 與 ISS 的分區混用：ISS 取六個身體區域（head/neck、face、chest、abdomen/pelvic contents、extremities/pelvic girdle、external），AIS 詞典則共有九個分區，因此答案 (D) 對應的是 ISS，須注意。考試仍以官方答案 (D) 為準。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"96-36","year":96,"qnum":36,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"外傷防治的步驟有下列，(1)找出原因和危險因子；(2)推行有效方法和評估結果；(3)發展測試方法；(4)釐清問題，其正確的順序為：","opts":[{"k":"A","t":"4 1 2 3"},{"k":"B","t":"1 4 3 2"},{"k":"C","t":"4 1 3 2"},{"k":"D","t":"4 3 2 1"},{"k":"E","t":"1 4 2 3"}],"answer":"C","expl":"公共衛生預防的邏輯：先釐清問題（surveillance, 4）→ 找出原因和危險因子（1）→ 發展並測試介入方法（3）→ 推行有效方法並評估成效（2），所以順序為 4→1→3→2，選 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-37","year":96,"qnum":37,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"台灣各地區因外傷或自殺造成的死亡率以下列何者最高？","opts":[{"k":"A","t":"台北市"},{"k":"B","t":"雲林縣"},{"k":"C","t":"花蓮縣"},{"k":"D","t":"屏東縣"},{"k":"E","t":"台中市"}],"answer":"C","expl":"本題為台灣各縣市外傷與自殺死亡率統計，屬資料記憶題；官方答案為花蓮縣，與東部偏遠地區醫療資源不足、交通事故死亡率高有關。因為各年統計會變動，不要把這一題當成通用知識。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-38","year":96,"qnum":38,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重外傷併有重度出血性休克、低體溫、凝血障礙的傷患，Damage control是合理也是適當的的選擇。下列符合實施 Damage control 的條件中，何者為錯？","opts":[{"k":"A","t":"Body temperature < 35℃"},{"k":"B","t":"Arterial pH < 7.4"},{"k":"C","t":"Base deficit < -15mmol/L"},{"k":"D","t":"Serum lactate > 5 mmol/L"},{"k":"E","t":"Partial thromboplastin time > 50% of normal"}],"answer":"B","expl":"Damage control 啟動的生理條件包括：core temp <34–35°C、pH <7.2（不是 7.4）、base deficit >15 mmol/L、lactate >5、PT/PTT 超過 50% 延長與大量輸血。pH 7.4 是正常值，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-39","year":96,"qnum":39,"topic":"頭部TBI","subtopic":"總論／其他","stem":"Head injury 的處理，下列那個不應該做：","opts":[{"k":"A","t":"Maintain PaCO2 near/at 35 mmHg"},{"k":"B","t":"Use isotonic solution for euvolemia"},{"k":"C","t":"Use long-acting paralytic agents in patients with head injury"},{"k":"D","t":"Maintain mean BP＞90 mmHg"},{"k":"E","t":"None of the above"}],"answer":"C","expl":"TBI 避免使用長效 paralytic agent，因為會遮蔽神經學評估（瞳孔、運動反應），所以 (C) 不應做。(A) PaCO2 維持 35 mmHg 左右（避免預防性 hyperventilation）；(B) 用 isotonic fluid 維持 euvolemia；(D) 維持足夠 MAP 以保障 CPP。補充：BTF 4th edition 建議 SBP ≥100（50–69 歲）或 ≥110 mmHg（15–49 或 >70 歲）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-40","year":96,"qnum":40,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"Gastrointestinal trauma in a spinal cord injured patient with a lesion at T4 can present with all of the following except：","opts":[{"k":"A","t":"Anorexia and nausea"},{"k":"B","t":"Hypovolemia"},{"k":"C","t":"Abdominal guarding"},{"k":"D","t":"Abdominal distension with air-fluid level on X-ray"},{"k":"E","t":"A negative peritoneal lavage"}],"answer":"C","expl":"T4 以上脊髓損傷病人腹部感覺喪失，腹部穿孔或出血時常不會出現 abdominal guarding／pain，所以 (C) 為「不會出現」。其他如 anorexia、hypovolemia、ileus 擴張與 DPL 假陰性都可能出現。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-41","year":96,"qnum":41,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"Hypoxia in a spinal cord injured patient with a lesion at C6 cannot be explained by","opts":[{"k":"A","t":"Increased bronchial secretion"},{"k":"B","t":"Loss of abdominal tone"},{"k":"C","t":"Paralysis of the external intercostals muscles"},{"k":"D","t":"Paralysis of the diaphragm"},{"k":"E","t":"Paralystic ileus"}],"answer":"D","expl":"C6 損傷時，phrenic nerve（C3–5）支配的 diaphragm 保留，所以呼吸缺氧不能用 (D) 解釋；真正原因是 intercostal paralysis、腹肌張力喪失、分泌物增加與 ileus。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-42","year":96,"qnum":42,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"關於頭部外傷之描述，下列何者錯誤?","opts":[{"k":"A","t":"硬腦膜外血腫 (Epidural hematoma)的病人可能會發生lucid interval (清明期)"},{"k":"B","t":"腦部萎縮的病人，如老年人或喝酒的病人最易造成硬腦膜外血腫 (Epidural hematoma)"},{"k":"C","t":"Nimodipine 使用於創傷性蜘蛛網膜下出血 (Subarachnoid hemorrhage)的病人，可降低死亡率"},{"k":"D","t":"硬腦膜下血腫 (Subdural hematoma)的電腦斷層顯示為弦月型(crescent-shaped)的病兆"},{"k":"E","t":"硬腦膜外血腫 (Epidural hematoma)的電腦斷層顯示為雙凸型(biconvex-shaped)的病兆"}],"answer":"B","expl":"Epidural hematoma 多見於年輕人，因為老人或酒癮者因腦萎縮、dura 與顱骨黏著較緊，反而較易發生 subdural hematoma，所以 (B) 錯。(A) lucid interval；(D) SDH 為 crescent-shaped；(E) EDH 為 biconvex。","outdated":false,"suspect":true,"flagNote":"(C) 同樣有疑點：nimodipine 用於 traumatic SAH 並未證實能降低死亡率（HIT 試驗結果為陰性），考試仍以官方答案 (B) 為準。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"96-43","year":96,"qnum":43,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"創傷病人常見處置和合併症下列何者為非？","opts":[{"k":"A","t":"Cardiac Tamponade 常見之症狀為increased venous pressure, decreased pulse pressure, paradoxical pulse"},{"k":"B","t":"Flail chest 之病人應給予 Intermittent positive-pressure breathing (IPPB)"},{"k":"C","t":"Tension Pneumothorax 須等X-光片確認"},{"k":"D","t":"第一，二肋骨骨折病人，常見合併氣管傷害"},{"k":"E","t":"Thoracic aorta rupture 常在X-光片上見到Widened mediastinum"}],"answer":"C","expl":"Tension pneumothorax 是臨床診斷，不能等 X-ray 才處理，所以 (C) 錯。(A) 為 Beck's triad 與 pulsus paradoxus 的描述；(D) 第一、二肋骨骨折提示高能量傷，需想到 tracheobronchial／great vessel injury；(E) widened mediastinum 為 aortic injury 的 CXR 徵象。補充：(B)「Flail chest 給 IPPB」並非現行標準，現在以止痛、呼吸治療，必要時 mechanical ventilation。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-44","year":96,"qnum":44,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"外傷性橫膈膜破裂常合併其他部位之嚴重外傷，同時也常導致腹部器官移位至胸腔，壓迫肺臟，導致急性呼吸衰竭。試問其死亡率與下列何者最有關？","opts":[{"k":"A","t":"橫膈膜破裂之面積大小"},{"k":"B","t":"是否於外傷後12 小時內診斷"},{"k":"C","t":"合併受傷器官之嚴重度"},{"k":"D","t":"手術方法"},{"k":"E","t":"左邊或右邊之橫膈膜"}],"answer":"C","expl":"創傷性橫膈破裂的死亡率主要與合併受傷器官的嚴重度有關，而非橫膈破裂大小、左右側或手術方式，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-45","year":96,"qnum":45,"topic":"胸部","subtopic":"肺挫傷／創傷性窒息","stem":"下列有關肺臟挫傷(Pulmonary contusion)之描述，下列何者為真？","opts":[{"k":"A","t":"通常於急診第一次之胸部 X 光片，即可清楚診斷"},{"k":"B","t":"病患之血氧分壓(PO2)，將會逐漸於受傷後24 小時內惡化"},{"k":"C","t":"這類病患應盡量減少靜脈輸液之供應，以避免肺臟組織水腫，造成呼吸衰竭"},{"k":"D","t":"嚴重肺臟挫傷呈現呼吸衰竭時，corticosteroid 為drug of choice"},{"k":"E","t":"受傷後，肺功能之惡化，可能與 surfactant 之減少無關"}],"answer":"B","expl":"Pulmonary contusion 於受傷後 24–72 小時內氧合逐漸惡化，胸部 X-ray 早期可能看不清楚，所以 (B)。(A) 早期 CXR 可能不明顯，CT 較靈敏；(D) steroid 不是首選；(E) 失去 surfactant 為機轉之一；補充：輸液應避免過量，但仍需維持足夠灌流，不宜極端限制。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-46","year":96,"qnum":46,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"36 歲駕駛翻車被車子壓住 2 小時後才脫困，雙下肢呈現腫脹，冰冷，無感覺，病患生命癥候穩定，但兩側股動脈以下脈搏摸不著，下列何種作為最有機會保留他的雙腿 ?","opts":[{"k":"A","t":"骨頭牽引"},{"k":"B","t":"給與抗凝固劑"},{"k":"C","t":"緊急筋膜切開術 (Fasciotomy)"},{"k":"D","t":"給與血栓溶解劑"},{"k":"E","t":"轉院"}],"answer":"C","expl":"Crush injury 合併下肢冰冷無脈搏，缺血與 reperfusion 後腔室壓力增加，快速 fasciotomy 與血流重建是保肢關鍵，所以 (C)。anticoagulation 與 thrombolysis 在大面積肌肉壞死與出血風險下不適合；骨頭牽引與轉院都延遲。補充：同時要注意 rhabdomyolysis、hyperkalemia 與 AKI。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-47","year":96,"qnum":47,"topic":"氣道","subtopic":"總論／其他","stem":"嚴重多發性外傷病人被送至急診室時，同時併有下述各種傷害。那一種情況必須最優先處置？","opts":[{"k":"A","t":"壓迫性氣胸(Tension pneumothorax)"},{"k":"B","t":"腹腔內大出血以致休克(Hemorrhagic shock)"},{"k":"C","t":"喉部骨折(Laryngeal fracture)致呼吸道阻塞"},{"k":"D","t":"第一頸椎骨折"},{"k":"E","t":"右大腿開放性骨折"}],"answer":"C","expl":"ABC 優先順序下，airway obstruction 是最先處理的威脅：喉部骨折造成呼吸道阻塞會在數分鐘內致命，需要先確保氣道（必要時 surgical airway）；tension pneumothorax 與出血性休克接著處理。C1 fracture 與開放性大腿骨折不是最先。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-48","year":96,"qnum":48,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"腹部穿刺傷之處置原則，下列何者錯誤?","opts":[{"k":"A","t":"一旦有槍傷病患進入急診，需立即通報相關警察單位介入處理，以保存證物並且確保急診人員之安全"},{"k":"B","t":"穿刺傷會比鈍挫傷造成更多之出血量，應先給予大量輸液與血液"},{"k":"C","t":"局部探查傷口病無法排除內部器官之傷害"},{"k":"D","t":"電腦斷層在生命徵象穩定的病患，可提供很良好之診斷幫助"},{"k":"E","t":"根據傷口之型態與污染情況可予以清創後縫合或是延遲縫合"}],"answer":"B","expl":"穿刺傷不一定出血量大於鈍挫傷，也不應先「大量輸液與血液」；現行是 limited resuscitation 配合早期手術止血，所以 (B) 錯。(A) 槍傷通報與證物保存；(C) 局部探查無法排除腹腔內傷害；(D) 穩定者 CT 有診斷幫助；(E) 依污染程度初級縫合或延遲縫合。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-49","year":96,"qnum":49,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一位25 歲年青男性因鬥毆左前胸被人捅了一刀, 而送來急診，在急診室突然失去生命跡象,沒有心跳脈搏,此時以下處置何者最正確?","opts":[{"k":"A","t":"開始進行CPR，持續做三十分鐘，若仍無心跳脈搏才宣佈死亡"},{"k":"B","t":"趕快做胸部電腦斷層找出受傷部位"},{"k":"C","t":"趕快聯絡轉院"},{"k":"D","t":"在急診室立即做緊急開胸"},{"k":"E","t":"緊急輸血及大量輸液"}],"answer":"D","expl":"穿刺性胸部外傷病人在急診失去生命跡象（witnessed arrest），有 cardiac tamponade 或 massive hemorrhage 的可能，應立即做 resuscitative thoracotomy，所以 (D)。依 EAST/WTA 2015，穿刺性胸傷且有生命徵象或剛失去者強烈建議 ED thoracotomy；CPR 30 分鐘或轉院都來不及。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"96-50","year":96,"qnum":50,"topic":"脊椎脊髓","subtopic":"SCIWORA／Chance fracture","stem":"Which statement is incorrect about SCIWORA (Spinal cord injury without radiographic abnormality)?","opts":[{"k":"A","t":"The most common cause of pediatric SCI"},{"k":"B","t":"Occur as a result of flexion, hyperextension , longitudinal distraction and ischemia"},{"k":"C","t":"If diagnosed, a period of supervised immobilization, restriction of activity and follow-up radiographic investigation is necessary"},{"k":"D","t":"None of above"},{"k":"E","t":"All of above"}],"answer":"D","expl":"SCIWORA 指脊髓損傷但影像（X-ray、CT）無骨折或脫位，多見於兒童（脊椎彈性大），機轉包括 flexion、hyperextension、longitudinal distraction 與缺血；確診後需要限制活動、固定與追蹤影像（含 MRI）。(A)(B)(C) 均為正確敘述，所以 (D) none of above。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-1","year":97,"qnum":1,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"下列有關腸系膜損傷 mesenteric injury之敘述何者正確？","opts":[{"k":"A","t":"創傷機轉trauma mechanism 以穿刺傷penetrating injury居多。"},{"k":"B","t":"發生部位mesentery of the colon 多於 mesentery of the small bowel。"},{"k":"C","t":"可能造成腸壁缺血壞死 bowel ischemic necrosis，引起腹膜炎 peritonitis及敗血症sepsis。"},{"k":"D","t":"安排腹部電腦斷層，只發現腸系膜血腫isolated mesenteric hematoma時，仍須進行剖腹探查手術 exploratory laparotomy。"},{"k":"E","t":"mobility and mortality與因診斷困難造成延遲診斷 delayed diagnosis無關。"}],"answer":"C","expl":"腸繫膜損傷若造成血管損傷，會導致腸壁缺血、壞死，進而 peritonitis 與 sepsis，所以 (C)。(A) 鈍傷（如安全帶損傷）較多；(B) 小腸繫膜多於結腸；(D) isolated mesenteric hematoma 可先觀察，不一定剖腹；(E) 延遲診斷會增加併發症與死亡率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-2","year":97,"qnum":2,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下列有關胰臟損傷pancreatic injury之敘述何者錯誤？","opts":[{"k":"A","t":"可能合併肝臟或近端小腸 proximal small bowel損傷。"},{"k":"B","t":"腹部X光plain abdominal radiographs檢查，沒有發現胸椎或腰椎骨折fractures of the lower thoracic and/or upper lumbar vertebrae，即可排除胰臟損傷的可能性。"},{"k":"C","t":"診斷性腹腔灌洗diagnostic peritoneal lavage，對於胰臟損傷的診斷，可能出現偽陰性。"},{"k":"D","t":"血清澱粉酶濃度serum amylase level高低，與胰臟損傷程度沒有相關性。"},{"k":"E","t":"診斷胰管損傷pancreatic duct injury，可以安排endoscopic retrograde cholangio-pancreatography (ERCP)或magnetic retrograde cholangio-pancreatography (MRCP)檢查。"}],"answer":"B","expl":"胰臟位於腹膜後，即使 X-ray 無胸腰椎骨折，也不能排除胰臟傷害，所以 (B) 錯。(C) DPL 可能假陰性；(D) amylase 與損傷程度無明確相關；(E) ERCP／MRCP 可診斷 pancreatic duct injury。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-3","year":97,"qnum":3,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"下列有關abdominal compartment syndrome 之敘述何者為非？","opts":[{"k":"A","t":"由膀胱內壓力來估計腹內壓為一實用的方法。"},{"k":"B","t":"腹內壓超過30 mmHg以上，且伴隨相關壓迫症狀，需考慮減壓治療。"},{"k":"C","t":"Abdominal compartment syndrome一定要有腹部創傷才會發生。"},{"k":"D","t":"Abdominal compartment syndrome若未適當處理，死亡率極高。"},{"k":"E","t":"過度輸液治療，也可能引發 abdominal compartment syndrome。"}],"answer":"C","expl":"Abdominal compartment syndrome 不一定要有腹部創傷：大量輸液（over-resuscitation）、burn、sepsis 等也會引起 secondary ACS，所以 (C) 為錯。(A) 膀胱內壓是常用測量方法；(B) IAP 高伴臟器功能障礙需考慮減壓（decompressive laparotomy）。補充：WSACS 定義 IAP 持續 >20 mmHg 且新發器官衰竭為 ACS。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-4","year":97,"qnum":4,"topic":"腹部","subtopic":"肝臟","stem":"預測肝臟裂傷非手術性療法成功與否的因子，哪一項最不重要？","opts":[{"k":"A","t":"病患生命現象穩定與否。"},{"k":"B","t":"AAST裂傷程度的分級。"},{"k":"C","t":"有無合併其他腹內空心臟器穿孔。"},{"k":"D","t":"病患是否須持續輸血。"},{"k":"E","t":"病患合併肝硬化。"}],"answer":"B","expl":"預測肝損傷 NOM 成功與否，關鍵是血流動力學穩定、是否持續輸血、是否有合併空腔臟器傷害或肝硬化；AAST grade 本身不是決定是否 NOM 的主要依據，所以 (B) 最不重要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-5","year":97,"qnum":5,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關大量血胸 (massive hemothorax) 之敘述，何者為非？","opts":[{"k":"A","t":"出血大於1,500 ml，可由胸部挫傷或穿刺傷造成。"},{"k":"B","t":"處理須包括補充血量及插大號管徑胸管引流。"},{"k":"C","t":"胸管引流出血的顏色是開胸手術的指標。"},{"k":"D","t":"胸管引流量 ＞1,500 ml及每小時出血 200 ml持續2至4小時需要盡早剖胸探察。"},{"k":"E","t":"胸部穿刺傷於乳房線的內側及肩胛骨的內側時皆有損傷到大血管、心臟及肺門結構的機會。"}],"answer":"C","expl":"Massive hemothorax 是否開胸取決於引流量（初始 >1500 mL 或 >200 mL/hr 持續 2–4 小時）與病人血行動力，不是血液顏色，所以 (C) 錯。(E) 乳頭線內側與肩胛骨內側的穿刺傷可傷及心臟、大血管與肺門。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-6","year":97,"qnum":6,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列有關外傷性橫膈膜損傷 (traumatic diaphragmatic injury) 之敘述，何者為非？","opts":[{"k":"A","t":"常發生在左側。"},{"k":"B","t":"鈍傷比穿刺傷會產生較大的輻射狀撕裂傷 (radial tears) 。"},{"k":"C","t":"一旦延遲對橫膈膜外傷診療時應由腹部進行手術。"},{"k":"D","t":"初始外傷之發現有賴臨床懷疑及放射線檢查確定。"},{"k":"E","t":"對於懷疑之病例，微創性內視鏡檢查也許可協助橫膈膜之評估。"}],"answer":"C","expl":"橫膈損傷多見左側；鈍傷造成較大的 radial tear；急性期從腹部手術同時處理其他腹內傷害，而延遲診斷的慢性疝氣因腹腔與胸腔黏連，應經胸腔入路，所以 (C)「延遲時由腹部進行」為錯。(E) VATS／laparoscopy 可協助診斷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-7","year":97,"qnum":7,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"下列有關外傷性主動脈斷裂 (traumatic aortic disruption) 之敘述，何者為非？","opts":[{"k":"A","t":"肇因於主動脈近動脈韌帶(ligamentum artriosum )附近不完全撕裂。"},{"k":"B","t":"螺旋顯影胸部電腦斷層檢查為一準確之篩檢方式。"},{"k":"C","t":"肺尖帽(apical cap)出現胸積水及左支氣管型降間接說明胸腔內有大血管外傷。"},{"k":"D","t":"發生縱隔腔變寬者，有 10%在主動脈攝影會出現主動脈破裂情形。"},{"k":"E","t":"治療方式可為原位縫合修補或切除受傷區段及置換人工血管。"}],"answer":"D","expl":"外傷性主動脈破裂（blunt aortic injury）好發於 ligamentum arteriosum 附近的 isthmus；CT angiography 為準確的篩檢；apical cap、left hemothorax、left mainstem bronchus depression 為間接徵象；治療為修補或置換，現今多以 TEVAR。官方答案 (D) 判其錯誤。","outdated":false,"suspect":true,"flagNote":"選項 (D)「縱隔腔變寬者約 10% 於血管攝影證實主動脈破裂」與常見教科書數字（約 10–15% 或以下）接近，看不出哪裡錯誤，答案 (D) 可能是來源文獻數字不同或原題有誤。考試以官方答案 (D) 為準，但臨床上請記得 widened mediastinum 只是篩檢指標，確診需 CTA。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"97-8","year":97,"qnum":8,"topic":"胸部","subtopic":"總論／其他","stem":"下列有關肋骨骨折的描述何者為非?","opts":[{"k":"A","t":"肋骨斷裂數越多，肺部的相關併發症比例越高。"},{"k":"B","t":"65歲以上的肋骨骨折病患因肺部的相關併發症及死亡率比例高，因此應建議住院觀察。"},{"k":"C","t":"肋骨骨折的治療包含適度的止痛。"},{"k":"D","t":"肋骨骨折固定手術對所有肋骨骨折病患都有助益。"},{"k":"E","t":"合併第一肋骨骨折的病患都應視為嚴重外傷病患處置。"}],"answer":"D","expl":"肋骨固定手術（SSRF）只對特定族群有益（flail chest、多發移位性骨折、呼吸衰竭等），並非所有肋骨骨折都有幫助，所以 (D) 錯。(A)(B)(C)(E) 皆為肋骨骨折的標準觀念：骨折數越多併發症越多、≥65 歲建議住院、需要止痛、第一肋骨骨折提示高能量傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-9","year":97,"qnum":9,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"下列有關心臟損傷的描述何者為非?","opts":[{"k":"A","t":"所有胸部損傷的病患都應懷疑合併心包填塞(cardiac temponade)及心臟損傷。"},{"k":"B","t":"所有懷疑合併心臟損傷的病患都應接受心電圖(ECG)檢查。"},{"k":"C","t":"心電圖(ECG)異常的胸部損傷的病患都有心臟損傷。"},{"k":"D","t":"心電圖(ECG)及Troponin I正常的胸部損傷病患幾乎可以排除心臟損傷。"},{"k":"E","t":"所有心電圖(ECG)及Troponin I異常的胸部損傷病患都應該接受心臟超音波。"}],"answer":"C","expl":"胸部外傷後 ECG 異常不代表一定有 myocardial injury（可能為 electrolyte、既有心臟病、pneumothorax 等），所以 (C)「都有心臟損傷」錯。(D) 依 EAST 指引，ECG 與 troponin 皆正常可有效排除臨床上有意義的鈍性心臟傷害；(E) 異常者需 echo。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-10","year":97,"qnum":10,"topic":"腹部","subtopic":"脾臟","stem":"下列有關blunt plenic injury之敘述何者為非?","opts":[{"k":"A","t":"Non-operative management (NOM)為主要治療選擇。"},{"k":"B","t":"對hemodynamic instability 手術仍為最好的選擇。"},{"k":"C","t":"Spleen arterial embolization(SAE)，是一相當安全的治療輔助幾乎不會有complication。"},{"k":"D","t":"單一脾臟外傷，但合併大量血腹(large hemoperitoneum)容易NOM失敗。"},{"k":"E","t":"Liver cirrhosis 之病人，NOM不易成功。"}],"answer":"C","expl":"脾動脈栓塞（SAE）雖然是 NOM 的輔助，但並非「幾乎無併發症」：可能有脾梗塞、脾膿瘍、再出血、血管併發症與造影劑腎病變，所以 (C) 錯。(A)(B)(D)(E) 為 blunt splenic injury 的標準觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-11","year":97,"qnum":11,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"嚴重外傷病人Right Subdural hematoma >50cc, Right 2-6 ribs fracture with pulmonary contusion, liver GradeⅡlaceration, right femoral Shaft middle third fracture 請問ISS (Injury Severity Score)應有多少?","opts":[{"k":"A","t":"50。"},{"k":"B","t":"41。"},{"k":"C","t":"45。"},{"k":"D","t":"29。"},{"k":"E","t":"17。"}],"answer":"A","expl":"ISS 取三個不同身體區域中最高 AIS 的平方和。依我對常見 AIS 編碼的估算：head（large SDH >50 cc）AIS 5、chest（≥3 根肋骨骨折合併 lung contusion）AIS 3–4、extremity（femoral shaft fracture）AIS 3、abdomen（grade II liver）AIS 2。官方答案 50 = 5² + 4² + 3²，需要 chest 為 4。","outdated":false,"suspect":true,"flagNote":"我的估算在 chest AIS = 3 時為 5² + 3² + 3² = 43，與官方答案 50（需 chest AIS = 4）不同；依 AIS 版本不同編碼可能不同，無法確認官方是以哪個版本計算。考試請依官方答案 (A) 50，但請把「ISS = 三個不同區域最高 AIS 平方和」這個計算原則學好。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"97-12","year":97,"qnum":12,"topic":"總論評分","subtopic":"總論／其他","stem":"下列有關遺漏性傷害(missed injuries)或是延遲診斷(delayed diagnosis) 之敘述何者為錯誤？","opts":[{"k":"A","t":"遺漏性傷害(missed injuries)或是延遲診斷(delayed diagnosis)在加護病房之嚴重外傷病患上常見，報告從 14％到40％不等。"},{"k":"B","t":"對加護病房中嚴重外傷併意識不清之患者進行頸部電腦斷層，發現 30％之患者有情況輕重不等之頸椎傷害。"},{"k":"C","t":"以肢體傷害佔比例最高，常引起醫療糾紛，但很難導致可預防之死亡。"},{"k":"D","t":"病患過多因而時間壓力大時，或是意志不清的病患身上易發生。"},{"k":"E","t":"嚴重外傷病患到ICU時，由另一人進行另一次完整之全身檢查(tertiary survey)，可以減少發生機會。"}],"answer":"C","expl":"Missed injuries 在 ICU 嚴重外傷病人常見，主要是肢體骨折遺漏，且部分可造成嚴重併發症與可預防死亡，所以 (C)「很難導致可預防死亡」為錯。(E) tertiary survey 能減少遺漏；(B) 昏迷病人頸椎 CT 常發現異常。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-13","year":97,"qnum":13,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關一名同時合併頭部外傷與腹部鈍挫傷均採取非手術療法之加護病房中的患者之敘述，下列何者為正確？","opts":[{"k":"A","t":"因合併頭部外傷，腹部外傷實質器官出血，應採取較為寬鬆之標準，盡量避免手術。"},{"k":"B","t":"腹部電腦斷層越來越精密，可完全排除小腸傷害的可能。"},{"k":"C","t":"患者若是清醒，腹痛不明顯，即可排除小腸傷害的可能。"},{"k":"D","t":"若合併小腸傷害，病患血壓一定會很快變差。"},{"k":"E","t":"腹膜診斷性灌洗術DPL，對小腸傷害的診斷敏感度高於腹部電腦斷層。"}],"answer":"E","expl":"DPL 對腸道損傷（hollow viscus）敏感度高於 CT，特別是在昏迷、無法可靠腹部理學檢查的 TBI 病人，所以 (E)。(A) 合併 TBI 不應放寬腹部手術標準；(B)(C) CT 與清醒程度不能完全排除小腸傷；(D) 小腸傷害血壓不一定很快惡化。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-14","year":97,"qnum":14,"topic":"休克輸血","subtopic":"總論／其他","stem":"男性車禍傷患，經急診診斷骨盆腔骨折、後腹腔出血、脾臟撕裂傷與左側血胸。\n經急救復甦處理後生命徵象仍不穩定，通知外科預行緊急手術；並安排輸血。但血庫通知患者驗血為 A型Rh陰性，血庫無Rh陰性血，下列何者處置最適當？","opts":[{"k":"A","t":"聯絡其他醫院安排轉院治療。"},{"k":"B","t":"僅用乳酸林格液 (Lactate Ringers Solution)急救。"},{"k":"C","t":"乳酸林格液5000 cc輸注後改用膠體溶液(如: HES:hydroxyethyl starch) 。"},{"k":"D","t":"改採Rh陽性 A型血輸血緊急開刀。"},{"k":"E","t":"通知媒體召集Rh陰性A型捐血者。"}],"answer":"D","expl":"大量出血的緊急情況下，無法取得 Rh-negative 血時，可輸 Rh-positive 血以挽救生命，所以 (D)。特別是男性與停經後女性，致敏風險可接受。補充：(B)(C) 單靠大量晶體液或膠體不符 ATLS 與 damage control resuscitation，應盡早 MTP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-15","year":97,"qnum":15,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"近年腹部鈍挫傷，導致之實質臟器(肝、脾、腎)破裂出血，如果血循穩定亦無胃腸道(hollow organs)破裂時，常採行選擇性非手術治療(selective non-operative treatment)，下列何適應指示最適當？","opts":[{"k":"A","t":"僅單一器官出血可採行。"},{"k":"B","t":"其成功率低，介於60%～70%。"},{"k":"C","t":"合併頭部外傷為禁忌。"},{"k":"D","t":"血管攝影合併栓塞(angio-embolization)，增加成功率。"},{"k":"E","t":"血循不穩定，只要血色素仍大於 30%仍可採行。"}],"answer":"D","expl":"血管攝影加栓塞可提高實質器官損傷 NOM 成功率，所以 (D)。(A) NOM 不限單一器官；(B) 成功率其實高（脾 >80–90%）；(C) 合併 TBI 並非禁忌；(E) 血流動力學不穩定不適合 NOM。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-16","year":97,"qnum":16,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一18歲男性工廠操作員，工作中不幸右手前臂被高處墜下之重物壓傷，受傷被送至急診室，病人右手前臂腫脹疼痛並有明顯瘀痕，生命徵象穩定，X-ray檢查並無骨折，有關急診室外傷醫師第一線處置，下面的敘述那項正確？","opts":[{"k":"A","t":"立即熱敷，增加血液循環，避免肌肉壞死。"},{"k":"B","t":"立即安排angiography，檢查是否血管受損。"},{"k":"C","t":"患肢冰冷是compartment ischemia的最初症狀。"},{"k":"D","t":"一旦患肢摸不到脈搏，常已是 compartment syndrome 後期。"},{"k":"E","t":"上臂不易造成compartment syndrome，應安慰病人不須過慮。"}],"answer":"D","expl":"Compartment syndrome 的早期症狀是 pain out of proportion，無脈搏、冰冷與感覺異常是晚期表現，所以 (D)。(A) 不應熱敷；(B) 不需先做血管攝影；(E) 前臂與上臂都可能發生。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-17","year":97,"qnum":17,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"一位50歲女性，從三樓墜落，被送至急診室，病人意識清楚，生命徵象穩定，但下背部明顯腫痛，下肢癱瘓無法活動，腰部 X-ray發現L2 fracture dislocation，有關急診室外傷醫師第一線處置，下面的敘述那項正確？","opts":[{"k":"A","t":"立即理學檢查 anus tone。"},{"k":"B","t":"Reduction of dislocation手術須待病人下背消腫後進行。"},{"k":"C","t":"Neurogenic shock呈現 hypotension and tachycardia。"},{"k":"D","t":"不可使用methylprednisolone。"},{"k":"E","t":"應該儘速給予病人穿上背架以固定骨折。"}],"answer":"A","expl":"脊椎骨折脫位合併下肢癱瘓，需要先做 rectal exam（anal tone、perianal sensation、bulbocavernosus reflex）評估 complete／incomplete SCI，所以 (A) 正確。(B) 需要盡早復位／減壓而非等消腫；(C) neurogenic shock 為 hypotension + bradycardia；(E) 不穩定骨折不應只靠背架。","outdated":true,"suspect":false,"flagNote":"選項 (D)「不可使用 methylprednisolone」在今日其實符合 ATLS 10 與 AANS/CNS 2013 的建議（不建議常規使用），而在本題年代（2008 前）的標準做法是 NASCIS II，所以題目對 steroid 的看法已改變。官方答案 (A) 不變，(D) 在現行指引下也算合理。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"97-18","year":97,"qnum":18,"topic":"氣道","subtopic":"總論／其他","stem":"一位20歲男性機車騎士，不幸撞上安全島並且安全帽脫落，被送至急診室，發現病人神智不清，四肢癱瘓，此時病人需確切維持呼吸道，下列敘述何者有誤？","opts":[{"k":"A","t":"當昏迷指數(GCS)低於8分(含)以下時應考慮儘速進行插管處置。"},{"k":"B","t":"決定經口氣管或鼻氣管插管之最重要因素為醫師本身之經驗。"},{"k":"C","t":"對無呼吸之傷患仍可進行經鼻氣管插管。"},{"k":"D","t":"有嚴重顏面上頷骨(Maxillary)骨折之病患需給予呼吸道保護處置。"},{"k":"E","t":"動脈血氧濃度(PaO2)為60 mmHg時血色素氧氣飽和度為90%。"}],"answer":"C","expl":"無自發呼吸（apnea）者不可做 blind nasotracheal intubation，所以 (C) 錯。(A) GCS ≤8 考慮插管；(D) 嚴重顏面骨折須保護氣道；(E) 在氧解離曲線上 PaO2 60 mmHg 約對應 SaO2 90%。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-19","year":97,"qnum":19,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"30歲工人右胸乳頭上方被刺 1刀，被送醫後已插上氣管插管，胸管只引流出 500cc血液，已輸2000 cc Lactated Ringer，血壓仍是60 /0 mmHg，心跳160下/分，下列處置何者最優先？","opts":[{"k":"A","t":"做血管攝影。"},{"k":"B","t":"緊急開胸術。"},{"k":"C","t":"腹部CT檢查。"},{"k":"D","t":"胸部CT檢查。"},{"k":"E","t":"立即照胸部X 光。"}],"answer":"B","expl":"胸部穿刺傷合併持續低血壓（60/0）、胸管引流 500 mL 與大量輸液仍不穩，需要立即 emergency thoracotomy（可能是 cardiac injury 或大血管、肺門出血），不應再做影像，所以 (B)。補充：ATLS 10/11 主張限制晶體液，已輸 2000 cc LR 已超出現行建議。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-20","year":97,"qnum":20,"topic":"影像FAST","subtopic":"總論／其他","stem":"有關腹部創傷病人的放射學檢查，下列何者為錯？","opts":[{"k":"A","t":"Plain abdomen film 為最基本及必要之檢查。"},{"k":"B","t":"電腦斷層攝影不易診斷小腸及腸系膜之創傷。"},{"k":"C","t":"電腦斷層攝影不易診斷胰臟及橫膈膜之創傷。"},{"k":"D","t":"腹部電腦繼層攝影檢查應包含下胸部及骨盆腔。"},{"k":"E","t":"電腦斷層攝影在診斷後腹腔之創傷時優於腹腔灌洗術。"}],"answer":"A","expl":"腹部外傷不需要 plain abdomen film 作為「必要」檢查，血流動力學不穩定者做 FAST，穩定者做 CT，所以 (A) 錯。(D) 腹部 CT 範圍應含下胸部與骨盆；(E) CT 對後腹腔傷害優於 DPL。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-21","year":97,"qnum":21,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"診斷腹部鎗傷時，下列何者不正確？","opts":[{"k":"A","t":"遭受高速子彈鎗傷時，傷口易遭受外物(如衣服破片)之進入而感染。"},{"k":"B","t":"遭受高速子彈鎗傷時，組織傷害(tissue damage)由外觀上不易判斷而常有低估之情形。"},{"k":"C","t":"腹部鎗傷之診斷步驟與一般之穿刺傷完全不同。"},{"k":"D","t":"診斷之步驟主要在檢查子彈有無進入腹腔。"},{"k":"E","t":"診斷之步驟主要在檢查是否需要手術。"}],"answer":"C","expl":"腹部槍傷與穿刺傷的診斷邏輯大致相同：判斷是否穿透腹膜、有無需手術的傷害，高速子彈會把外物帶入並造成較大組織傷害，所以 (C)「完全不同」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-22","year":97,"qnum":22,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"一位在外科加護病房觀察的頭部外傷的患者，他的顱內腦壓(ICP)持續升高時，以下的處理何者最不合適？","opts":[{"k":"A","t":"再作一次腦部的電腦斷層評估是否有變化。"},{"k":"B","t":"必須排除是否有抽搐(status epilepticus)的現象。"},{"k":"C","t":"考慮做腦室穿刺引流腦脊髓液(CSF)。"},{"k":"D","t":"趕緊降低血中的鈉離子(Sodium)濃度。"},{"k":"E","t":"增加鎮定劑的量(increase sedation)。"}],"answer":"D","expl":"ICP 升高時應排除抽搐，重做 CT，增加鎮靜、CSF drainage，並使用 hyperosmolar therapy（mannitol 或 hypertonic saline）；不應降低血鈉，反而要升高血鈉，所以 (D) 最不合適。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-23","year":97,"qnum":23,"topic":"影像FAST","subtopic":"FAST／超音波的使用","stem":"有關使用超音波診斷(FAST)腹部挫傷的患者，下列何者為非？","opts":[{"k":"A","t":"腹部超音波(FAST)可以重複作檢查。"},{"k":"B","t":"對於後腹腔的受傷，超音波檢查比腹部沖洗術(DPL)較準確。"},{"k":"C","t":"使用FAST單獨檢查 Morrison’s pouch有無積血，與同時再加上檢查左上腹與膀胱邊是否積血，在評估腹內創傷的準確度是沒有差異的。"},{"k":"D","t":"使用FAST檢查時，常需轉動病人才能看清楚腹內是否積血。"},{"k":"E","t":"以上皆正確。"}],"answer":"C","expl":"FAST 的四個窗口（RUQ、LUQ、suprapubic、pericardial）比單看 Morrison's pouch 更能提高敏感度，所以 (C)「沒有差異」為錯。","outdated":false,"suspect":true,"flagNote":"(B)「超音波對後腹腔傷害比 DPL 準確」也不正確：FAST 與 DPL 都不擅長評估後腹腔，這點屬於題目瑕疵。考試以官方答案 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"97-24","year":97,"qnum":24,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"造成外傷患者腹內壓力上升症候群 (abdominal compartment syndrome)的主要原因為何？","opts":[{"k":"A","t":"休克與使用輸液急救。"},{"k":"B","t":"低體溫(hypothermia)。"},{"k":"C","t":"傷害控制手術(damage control surgery)。"},{"k":"D","t":"肝脾臟受傷。"},{"k":"E","t":"腦部嚴重受損。"}],"answer":"A","expl":"Secondary ACS 的主要原因為大量復甦（massive fluid resuscitation）與休克，造成腸道水腫、腹水，所以 (A)。Damage control surgery 與 packing 也可誘發，但大量輸液才是常被考的主因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-25","year":97,"qnum":25,"topic":"頭部TBI","subtopic":"總論／其他","stem":"36歲男性病人，車禍送至急診處，呼吸速率: 22/min，心博速: 130/min，血壓:\n96/60 mmHg，SaO2: 98%，昏迷指數 = E2M4V1，瞳孔不等徑: 6 mm/3 mm(左大於右)，右下肢變形，頭皮十公分撕裂傷請問下列處置何者適當？\n(1) 插管 (2) 建立二條靜脈路徑，給予 2000 c.c.生理食鹽水點滴注射(3) 安排全身腦斷層 (4) 給予dopamine (5)腹部超音波(FAST)","opts":[{"k":"A","t":"(1)、(2)、(3)。"},{"k":"B","t":"(1)、(2)、(3)、(5)。"},{"k":"C","t":"(2)、(3)、(4)。"},{"k":"D","t":"(1)、(2)、(3)、(4)、(5)。"}],"answer":"B","expl":"GCS 7（E2V1M4）、左瞳孔放大，需要先 airway control，再做 resuscitation、CT；同時懷疑多處出血要做 FAST，所以官方答案 (B)。dopamine 不是此時首選。","outdated":true,"suspect":false,"flagNote":"選項 (2)「給予 2000 c.c. 生理食鹽水」是舊式輸液處方；ATLS 10/11 初始晶體液上限約 1 L 並盡早 blood products，TBI 需避免 hypotension 但也避免 hypotonic／過量液體。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"97-26","year":97,"qnum":26,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"在嚴重頭部外傷的病人，於加護病房中，鎮靜劑的使用，何者為錯？","opts":[{"k":"A","t":"有助於呼吸器的使用。"},{"k":"B","t":"可降低顱內壓。"},{"k":"C","t":"不應使用，影響神經學檢查。"},{"k":"D","t":"會降低代謝。"}],"answer":"C","expl":"嚴重 TBI 在 ICU 使用鎮靜劑可幫助呼吸器配合、降低 CMRO2 與 ICP，並非一律禁止；所以 (C)「不應使用」為錯。使用短效藥並定期中斷以評估神經狀態。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-27","year":97,"qnum":27,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"32歲男性傷患，上腹水果刀穿刺傷，半小時後被送至外科急診處，意識清醒，收縮壓80 mmHg，心跳120次/分，呼吸22次/分，下列何種處置適當除了?","opts":[{"k":"A","t":"局部傷口探查。"},{"k":"B","t":"內部出血，顯示有上升的脈博率，煩躁不安，臉色蒼白應行剖腹術。"},{"k":"C","t":"病人的內臟，通過他的腹壁傷應進行剖腹術。"},{"k":"D","t":"haematemesis，nasogastric tube有出血或直腸出血應進行剖腹術。"},{"k":"E","t":"安排電腦斷層檢查。"}],"answer":"E","expl":"血壓 80 mmHg、HR 120 的腹部穿刺傷病人已有血流動力學不穩定，應直接剖腹，不應做 CT，所以 (E)。(A) 局部傷口探查可確認是否穿透腹膜；(B)(C)(D) 為腹部穿刺傷剖腹手術的適應症（腹膜炎、evisceration、hypotension、GI bleeding）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-28","year":97,"qnum":28,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"35歲男性傷患，肚臍下兩公分子彈槍傷， 20分後被送至外科急診處，意識清醒，收縮壓110 mmHg，心跳 89次/，呼吸18次/分，傷患接受電腦斷層檢查，下列何種情況高度懷疑有重大損傷需手術探查除了?","opts":[{"k":"A","t":"free intraperitoneal or retroperitoneal air。"},{"k":"B","t":"free intraperitoneal fluid in the absence of solid organ injury。"},{"k":"C","t":"localized bowel wall thickening。"},{"k":"D","t":"iliac bone fracture with hematoma。"},{"k":"E","t":"bullet tract close to a hollow viscus with surrounding hematoma。"}],"answer":"D","expl":"腹部槍傷穩定病人，CT 發現 free air、無實質器官傷的 free fluid、局部腸壁增厚、彈道靠近空腔臟器伴血腫，都提示 hollow viscus injury，需要探查；髂骨骨折合併血腫本身不是剖腹指徵，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-29","year":97,"qnum":29,"topic":"顏面頸部","subtopic":"總論／其他","stem":"一位65歲病人割喉自殺，傷口位於甲狀軟骨旁，長約 2公分，呼吸 30/min，BP120/80 mmHg，傷口有暗紅色血流出，呼吸時傷口產生泡沫。\n下例何者為最適當的處置，請按順序排列：\n(1) Arrange Angiography (2) Surgical exploration (3) Set up airway (4) Intravenous fluid (5) Bronchoscope (6)Barium swallow","opts":[{"k":"A","t":"(3)(1)(5)(6)。"},{"k":"B","t":"(4)(5)(1)。"},{"k":"C","t":"(3)(4)(5)(2)。"},{"k":"D","t":"(3)(4)(2)。"},{"k":"E","t":"(4)(5)(6)(2)。"}],"answer":"D","expl":"頸部穿透傷合併呼吸道症狀（傷口冒泡）要先確保氣道，再建立 IV，並進行手術探查，所以順序為 (3)(4)(2)，選 (D)。此時有 platysma 穿透且有氣管傷害，不適合先做 angiography 或 barium swallow。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-30","year":97,"qnum":30,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關於neck penetrating injury，下列敘述何者為非?","opts":[{"k":"A","t":"Zone II區域比 Zone I或Zone III區域更容易進行外科介入性治療(surgical intervention)。"},{"k":"B","t":"Zone III區域因位置靠近 thoracic outlet血管區，故手術時常需作 median sternotomy或clavicle resection。"},{"k":"C","t":"在Zone I或Zone III區域，arteriography通常被認為是可被接受的檢查，來檢視大血管是否被傷害。"},{"k":"D","t":"因頸部食道傷害延遲診斷超過 12小時，其死亡率可高達 17%。"},{"k":"E","t":"用esophagography來診斷食道破裂，其敏感度 (sensitivity)約為70-80%。"}],"answer":"B","expl":"頸部 Zone 分區：Zone I（胸廓出口，需要 sternotomy／clavicle resection）、Zone II（最易探查）、Zone III（下顎角以上，難暴露，常需 mandibular subluxation）。把 sternotomy／clavicle resection 描述為 Zone III 是錯的，所以 (B)。補充：現行指引對 hemodynamically stable 的 Zone II 傷也偏向 CTA 為主的 selective management。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-31","year":97,"qnum":31,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於abdominal penetrating injury 下列敘述何者為非?","opts":[{"k":"A","t":"軀幹前方乳頭以下，背部肩胛骨(scapula)以下穿刺傷，須考慮到腹膜腔可能有受傷。"},{"k":"B","t":"穿刺傷口需要在適當的局部麻醉下做局部檢視(local exploration)判斷是否進入腹膜腔。"},{"k":"C","t":"有較高比率的negative laparotomy，因此對於一些selective patients，可採取non-operative management。"},{"k":"D","t":"用diagnostic peritoneal lavage (DPL)來診斷腹膜是否已被穿刺，以>105/mm3為判斷基準，其敏感度約 95%。"},{"k":"E","t":"腹部槍傷(Gunshot Wound)合併有80%重大腹部傷害，因此絕大部份需要剖腹探查。"}],"answer":"D","expl":"DPL 診斷穿刺傷是否進入腹膜腔的閾值遠低於鈍傷（鈍傷 RBC >100,000/mm³；穿刺傷常用 >10,000/mm³ 甚至更低，部分依 lavage 方式用 1,000–5,000），所以把 >10⁵/mm³ 當作穿刺傷的判斷基準並說敏感度約 95%，是不正確的，答案 (D)。(A)(B)(C)(E) 皆為腹部穿刺傷的常規觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-32","year":97,"qnum":32,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"小飛於酒吧裡與人爭吵，被人從下背部捅了一刀，他被立即送到醫院，理學檢查血壓118/74mmHg，心跳84/min，呼吸18/min，左下腹有輕微壓痛，此時，最好的診斷方法是:","opts":[{"k":"A","t":"肛診。"},{"k":"B","t":"Diagnostic peritoneal lavage。"},{"k":"C","t":"腹部超音波 (FAST)。"},{"k":"D","t":"Triple-contrast abdominal CT。"},{"k":"E","t":"腹部核磁共振 (MRI)。"}],"answer":"B","expl":"下背部（back／flank）穿刺傷、穩定、左下腹壓痛，官方答案為 (B) DPL。","outdated":true,"suspect":false,"flagNote":"現行觀念：穩定病人的背部／flank 穿刺傷多用 contrast-enhanced CT（含 colon 評估）加上 serial abdominal exam，DPL 已很少使用（ATLS 10、WTA/EAST 指引）。考試仍以官方 (B) 為準；臨床則以 CT 為先。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"97-33","year":97,"qnum":33,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"治療懷孕的外傷病人時，下列何者為對?","opts":[{"k":"A","t":"一般治療的優先順序(priority)與未懷孕者是不同的。"},{"k":"B","t":"先治療孕婦的傷勢再對胎兒做早期評估。"},{"k":"C","t":"面對孕婦與胎兒兩者皆存活則先治療那一位以當時狀況而定。"},{"k":"D","t":"X光檢查在懷孕初期不可使用。"},{"k":"E","t":"需待孕婦穩定後再會診婦產科。"}],"answer":"B","expl":"ATLS 原則：孕婦外傷的優先順序與一般相同，先處理母親（母親存活是胎兒最佳急救），再評估胎兒，所以 (B)。(A) 錯；(C) 母體優先；(D) 需要的 X-ray 不應因懷孕而不做；(E) 應早期會診婦產科。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-34","year":97,"qnum":34,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有關老人外傷處理的警句，那一項是錯的?\n1 所有老年病人的生理預備機能是有限(limited physiological reserve)2 穩定到不穩定的生命徵象多有跡象可循3 儘早侵入性手段以監測病人血流動力學資料有助於診斷與處置4 非必要盡量不要輸血5 太過與不及的急救都是不可取的","opts":[{"k":"A","t":"1、2。"},{"k":"B","t":"2、3。"},{"k":"C","t":"3、4。"},{"k":"D","t":"4、5。"},{"k":"E","t":"2、4。"}],"answer":"E","expl":"老年外傷警句：生理儲備有限、病情常突然惡化（穩定與不穩定之間常無明顯徵兆，所以 2 錯）、早期 invasive monitoring 有幫助；輸血方面也不該刻意避免（4 錯），過與不及的復甦都不好，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-35","year":97,"qnum":35,"topic":"小兒","subtopic":"總論／其他","stem":"以下關於小兒外傷處置的敘述何者正確？\n甲、外傷造成心跳停止的最常見原因為失血性休克。\n乙、估計氣管內管直徑，約同於第五指直徑。\n丙、因為插管時可能引發較強烈的迷走神經刺激，因此建議先打 atropine。\n丁、當小兒困難插管時，應先考慮 needle cricothyroidotomy，而非surgical cricothyroidotomy。\n戊、兒童的生理耐受性較成人為差，因此同比例的失血時，低血壓出現的較早。","opts":[{"k":"A","t":"甲、丙、戊。"},{"k":"B","t":"丙、丁、戊。"},{"k":"C","t":"乙、丙、丁。"},{"k":"D","t":"乙、丙、戊。"},{"k":"E","t":"甲、丁、戊。"}],"answer":"C","expl":"乙：氣管內管直徑約等於小指（第五指）粗細；丁：兒童無法插管時用 needle cricothyroidotomy，而非 surgical；丙：官方認為插管前可考慮 atropine（避免迷走反應）。故 (C)。甲：兒童創傷心跳停止最常因 hypoxia 而非單純出血；戊：兒童代償能力強，低血壓出現較晚，所以錯。","outdated":true,"suspect":false,"flagNote":"丙「建議先打 atropine」在現行指引（ATLS 10、PALS）已非常規，只在特定狀況（如 bradycardia、使用 succinylcholine 的幼兒）考慮。官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"97-36","year":97,"qnum":36,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"76歲男性過馬路時被機車撞倒，檢查發現血壓為 80/50 mmHg，心跳80/min，GCS為E3V5M6，末梢血循不佳，右側第五至七肋骨骨折，無氣血胸，右側恥骨骨折，腹部超音波未發現積液，四肢無骨折現象，過去病史為高血壓及心臟病，長期服用降血壓藥及抗血小板製劑，以下何者不恰當？","opts":[{"k":"A","t":"應以加溫的Ringer’s lactate開始灌注。"},{"k":"B","t":"灌注2L點滴後血壓升至 120mmHg，但五分鐘後血壓又降至 90，此時應考慮輸血。"},{"k":"C","t":"承上，應該由胸腹部再次檢查以尋找可能出血來源。"},{"k":"D","t":"承上，胸腹部若無明顯出血來源，應考慮血管攝影以排除骨盆腔或後腹腔出血。"},{"k":"E","t":"恥骨骨折為輕微的骨盆骨折，應不可能造成出血性休克。"}],"answer":"E","expl":"恥骨骨折即使看似輕微，在老人合併抗凝／抗血小板藥物時仍可能造成大量出血與休克，所以 (E)「不可能」為錯。(A)(B)(C)(D) 為合理處置：先晶體液，無法維持就輸血、找出血來源、血管攝影栓塞。補充：現行 ATLS 建議初始晶體液上限約 1 L，並較早輸血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-37","year":97,"qnum":37,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列關於急診緊急開胸術的禁忌症，下列何者為非？","opts":[{"k":"A","t":"超過五分鐘未建立氣管內管的心肺復甦術(CPR)。"},{"k":"B","t":"超過十分鐘建立氣管內管的心肺復甦術(CPR)。"},{"k":"C","t":"穿刺傷患者在事發現場已無生命徵象。"},{"k":"D","t":"鈍傷患者在事發現場已無生命徵象。"},{"k":"E","t":"鈍傷患者在急診室只有無脈搏心臟電氣活動(pulseless electrical activity)。"}],"answer":"C","expl":"Emergency department thoracotomy 的禁忌，鈍傷無生命徵象與久延的心肺復甦都屬禁忌；穿刺傷（尤其胸部）即使現場無生命徵象，仍有機會因 cardiac tamponade 得救，所以不算禁忌，答案 (C)。依 EAST/WTA 2015，穿刺性心臟傷最受益。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-38","year":97,"qnum":38,"topic":"DCS_ACS","subtopic":"總論／其他","stem":"下列有關損害控制(Damage Control)手術之敘述何者為非？","opts":[{"k":"A","t":"單一血管、臟器損傷或腸損傷是常見適應症。"},{"k":"B","t":"最常見放棄傳統確定手術治療方式的原因是凝血功能異常。"},{"k":"C","t":"有其他合併傷害急需非手術治療時也可考慮損害控制手術。"},{"k":"D","t":"常是階段性安排手術。"},{"k":"E","t":"損害控制手術的觀念數十年前就有了。"}],"answer":"A","expl":"Damage control 是針對 physiologic exhaustion（lethal triad）與多重嚴重傷害的階段性手術，不是單純單一血管、臟器或腸道傷害，所以 (A) 錯。(B) 常見因 coagulopathy 放棄確定性手術；(C)(D)(E) 皆正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-39","year":97,"qnum":39,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列何者不是施行急診部開胸術(ED thoracotomy)的主要目標？","opts":[{"k":"A","t":"解除心包膜填塞(pericardial temponade)。"},{"k":"B","t":"去除大量的空氣栓塞(air embolism)。"},{"k":"C","t":"控制心臟出血(cardiac hemorrhage)。"},{"k":"D","t":"暫時夾住降主動脈(descending aorta)。"},{"k":"E","t":"解除張力性氣胸(tension pneumothorax)。"}],"answer":"E","expl":"ED thoracotomy 的主要目標：解除 cardiac tamponade、控制心臟出血、處理 massive air embolism 與 bronchovenous fistula、暫時夾住 descending aorta、開胸心臟按摩。張力性氣胸用 needle／finger／chest tube 即可，不是開胸的主要目標，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-40","year":97,"qnum":40,"topic":"DCS_ACS","subtopic":"總論／其他","stem":"下列何者不是施行損害控制(damage control)手術的適應情況(indication)？","opts":[{"k":"A","t":"Initial body temperature < 35℃。"},{"k":"B","t":"PT and/or aPTT > 50% of normal。"},{"k":"C","t":"Arterial pH<7.2。"},{"k":"D","t":"Serum lactate <5mmol/L。"},{"k":"E","t":"Base deficit<-15mmol/L in patient <55 years of age。"}],"answer":"D","expl":"Damage control 啟動條件：core temp <34–35°C、PT/aPTT >50% 延長、pH <7.2、lactate >5 mmol/L、base deficit >15（<55 歲）；題目 (D) lactate <5 為正常範圍，所以不是適應症。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-41","year":97,"qnum":41,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"當病患遭受穿透性的胸部創傷時，接受氣管插管及正壓換氣，突然產生shock，此時要懷疑是否有 bronchovenous air embolism 產生，下列有關其相關敘述何者為錯？","opts":[{"k":"A","t":"此時產生的休克是因為 air embolism 塞住了pulmonary artery 而造成的。"},{"k":"B","t":"應立刻作emergency department thoracotomy 實行pulmonary hilar cross-clamping。"},{"k":"C","t":"可將病患擺成Trendelenburg’s position有利血壓的提升。"},{"k":"D","t":"可作Vigorous cardiac massage以趨出air。"},{"k":"E","t":"可用空針從aortic root 或左心室處吸出air。"}],"answer":"A","expl":"Bronchovenous air embolism 是空氣從受傷的支氣管進入肺靜脈，進入左心後進入 coronary 與 cerebral arteries（systemic arterial air embolism），不是塞住 pulmonary artery，所以 (A) 錯。處置：ED thoracotomy 與 pulmonary hilar cross-clamping、Trendelenburg、抽出 aortic root/left ventricle 的空氣與 cardiac massage。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-42","year":97,"qnum":42,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"當實行emergency department thoracotomy 時，欲作 aortic cross-clamping，下列相關敘述何者錯誤?","opts":[{"k":"A","t":"可增加brain及myocardium的血流。"},{"k":"B","t":"目的在減少subdiaphragmatic hemorrhage。"},{"k":"C","t":"當打開胸腔作internal defibrillation時，心臟仍無恢復cardiac activity 時，可直接先作cross clamp 的動作。"},{"k":"D","t":"最好把thoracic aorta的anatomy分清楚以利將aorta 完全環繞套住以免傷到其他branch。"},{"k":"E","t":"當病患有效的心臟活動及血壓一回復應儘快移開 clamp，以減少 anaerobic metabolism。"}],"answer":"D","expl":"ED thoracotomy 做 descending aortic cross-clamp 時，不需也不應把 aorta 完全環繞游離（容易傷到 intercostal/ 脊髓的分支與食道），直接 clamp 即可，所以 (D) 錯。clamp 的目的為增加心腦灌流與減少橫膈下出血，血壓恢復後儘快放開。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-43","year":97,"qnum":43,"topic":"顏面頸部","subtopic":"顏面骨折（LeFort、咬合）","stem":"下列關於顏面骨折的描述，何者有誤？","opts":[{"k":"A","t":"Maxillofacial fracture 造成的骨折與脫位，常會造成上呼吸道的阻塞，進而影響呼吸的問題。"},{"k":"B","t":"顏面骨折的病人常因為出血以及分泌物的增加，讓這類的病人呼吸道的維持增加很多困難。"},{"k":"C","t":"特別是下顎骨骨折的病人，更要注意呼吸道的維持。"},{"k":"D","t":"顏面骨折的病人，特別是在 supine的姿勢，容易發生呼吸道阻塞的問題。"},{"k":"E","t":"Maxillofacial fracture的病人，尤其鼻骨骨折的病人，用鼻管(Nasoendo tube)重新建立呼吸道，是最正確的方法。"}],"answer":"E","expl":"顏面骨折（尤其鼻骨、中臉部骨折）不建議 nasotracheal intubation，因可能進入顱內並造成出血，所以 (E) 錯。應選擇 orotracheal intubation 或 surgical airway。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-44","year":97,"qnum":44,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"當pelvic bone fracture with massive bleeding 的時候，最有可能是傷到那一個arterial system？","opts":[{"k":"A","t":"External iliac arterial system。"},{"k":"B","t":"Internal iliac arterial system。"},{"k":"C","t":"Femoral arterial system。"},{"k":"D","t":"Abdominal aorta system。"},{"k":"E","t":"Mesenteric arterial system。"}],"answer":"B","expl":"骨盆骨折的大出血多來自 internal iliac artery system 的分支（superior gluteal、internal pudendal 等），其次是 presacral venous plexus，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-45","year":97,"qnum":45,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"一位22歲男性勞工，於工作時被一長 1公尺、寬1公尺、厚度 3公分的鐵板自前方水平地撞到上腹部，隨即被送到某醫學中心急診處。到院時血壓 100/60 mm-Hg；\n心跳速率90/min；呼吸速率 24/min；體溫36.7℃。Abdominal CT發現liver有grade II的blunt injury；pancreas周圍有一些fluid，在hemodynamic stable的情況下，下列處置何者不妥？","opts":[{"k":"A","t":"馬上laparotomy，因為要檢查 pancreas，順便作hepatorrhaphy。"},{"k":"B","t":"作ERCP。"},{"k":"C","t":"作MRCP。"},{"k":"D","t":"先嘗試non-operative management，每 2到4小時測amylase；如果 amylase level持續升高，需要further evaluation。"},{"k":"E","t":"先嘗試non-operative management，數小時後再follow up abdominal CT。"}],"answer":"A","expl":"血流動力學穩定的 liver grade II 損傷合併胰臟周圍積液，應先 NOM、追蹤 amylase 與 CT，必要時以 ERCP／MRCP 評估 duct，不需要立即 laparotomy，所以 (A) 不妥。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-46","year":97,"qnum":46,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"處理懷孕婦女外傷時，如果臨床上無脊椎 (spinal injury) 時，可以將病人擺成何種姿勢，以減少對於下腔靜脈回流的壓迫?","opts":[{"k":"A","t":"頭低腳高。"},{"k":"B","t":"頭高腳低。"},{"k":"C","t":"俯臥 (prone) 使子宮不受重力向下壓迫。"},{"k":"D","t":"以 logroll 將病人側左邊。"},{"k":"E","t":"抬高左肩。"}],"answer":"D","expl":"無脊椎損傷的孕婦（>20 週）應將病人側臥向左（left lateral decubitus），或手動把子宮往左移，以減少 IVC 壓迫，所以 (D)。補充：若有 spinal injury 則維持 supine，用 backboard 傾斜 15° 或手動移子宮。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-47","year":97,"qnum":47,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"一跳水選手不慎頭部撞及池底，在 ER時照lateral C-spine後，發現 increased prevertebral soft tissue space， 以下後續處置何者為非？","opts":[{"k":"A","t":"應注意是否潛在壓迫上呼吸道的可能，作預防性的插氣管內管。"},{"k":"B","t":"放置氣管內管時應視為困難插管，故應先會診麻醉醫師或預備作 surgical airway。"},{"k":"C","t":"放置氣管內管成功後，應同時以 bronchoscope 檢視氣道。"},{"k":"D","t":"作完整神經學檢查後，可會診神經外科醫師進一步排除頸椎損傷。"},{"k":"E","t":"在secondary survey 作neck CT時應吞contrast檢查上消化道後，若未見leakage，則可排除esophageal perforation。"}],"answer":"E","expl":"Prevertebral soft tissue swelling 暗示 cervical spine injury 或血腫，可能壓迫氣道，需考慮預防性插管並視為 difficult airway；食道損傷無法僅靠 contrast swallow 排除，檢查敏感度約 70–80%，所以 (E) 錯，需要再加 esophagoscopy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-48","year":97,"qnum":48,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"有關嚴重創傷患者之新陳代謝反應，下列何者為誤？","opts":[{"k":"A","t":"受傷後24到48小時稱為“ebb phase”，此時耗氧量最大。"},{"k":"B","t":"待情況穩定後，進入“flow phase”。前期以異化作用為主，呈負氮平衡。"},{"k":"C","t":"有些病患可能會產生 insulin resistance，導致高血糖。"},{"k":"D","t":"這些新陳代謝上的變化，與壓力所引起的血中茶酚氨(Catecholamine)上升及細胞激素(cytokine)大量產生成正相關。"},{"k":"E","t":"受傷後，身體組織會釋放 inflammatory mediators，例如 tumor necrosis factor 及interleukin-1，可以增加 basal metabolic expenditure 及產生 fever, tachycardia 症狀。"}],"answer":"A","expl":"創傷後代謝：ebb phase 是受傷後最初 24–48 小時，以低灌流、耗氧與代謝率下降為主；之後 flow phase 才有 hypermetabolism、catabolism、insulin resistance，所以 (A)「ebb phase 耗氧量最大」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-49","year":97,"qnum":49,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"嚴重創傷患者的營養供給原則如下，除了","opts":[{"k":"A","t":"鼓勵儘早餵食，最好能在受傷後 24-48小時內開始。"},{"k":"B","t":"足夠的蛋白質供給最為重要，有助於組織、傷口的復元。"},{"k":"C","t":"相較於underfeeding calories，overfeeding calories引起的併發症較少。"},{"k":"D","t":"相較於靜脈給予，enteral route 是比較理想的營養給予方式。"},{"k":"E","t":"平常熱量的主要來源是脂肪及醣類，於嚴重外傷時，以消耗蛋白質以增加熱量的比例大為增加，如果熱量及蛋白質補充不足，病人會處於營養不良狀態 (malnutrition)。"}],"answer":"C","expl":"創傷病人營養：早期 enteral feeding（24–48 小時內）、足夠蛋白質、避免 overfeeding；overfeeding 會造成 hyperglycemia、CO2 增加、肝功能異常等併發症，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"97-50","year":97,"qnum":50,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關槍傷之敘述何者為錯誤？","opts":[{"k":"A","t":"彈道可能是曲線，可能打中體內堅硬物反彈。"},{"k":"B","t":"彈道的路徑與血管有所距離，就可排除血管的傷害。"},{"k":"C","t":"胸肺部的傷害要小心張力性氣胸與大量血胸之發生。"},{"k":"D","t":"在照X光檢查之前，應先將槍傷傷口以迴紋針或是一般針頭指引傷口做標記，以利後續檢查與治療。"},{"k":"E","t":"臨床傷口照護須依每一創傷的特性來做決定，而不能只依槍枝火力或是部位。"}],"answer":"B","expl":"槍傷彈道可偏折，也可能因 cavitation 傷及離彈道有距離的血管、神經，不能因彈道看似遠離血管就排除血管損傷，所以 (B) 錯。(D) 以 paper clip 標示入出口再拍 X-ray 為常見做法。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-1","year":98,"qnum":1,"topic":"骨盆泌尿","subtopic":"腎臟外傷","stem":"下列有關 blunt renal injury 的敍述何者有誤。","opts":[{"k":"A","t":"持續的原發性或續發性的出血是施行血管攝影的適應症(angiographic indication)。"},{"k":"B","t":"若病患處於 hemodynamically unstable 的情況下，是施行血管攝影的禁忌症(angiographic contraindication)。"},{"k":"C","t":"於 abdominal CT 上見到 renal artery thrombosis，須立即施行血管攝影。"},{"k":"D","t":"AAST Grade V 的病患，大部分(85%-90%)須接受外科手術治療。"},{"k":"E","t":"接受血管栓塞治療後 (endovascular embolization)，持續有威脅生命的出血的患者，須接受外科手術治療。"}],"answer":"C","expl":"鈍性腎損傷：血流動力學不穩者應直接手術，不做血管攝影；持續出血為 angioembolization 適應症；AAST V（shattered kidney 或 avulsion）多需手術；栓塞後仍有致命出血須手術。官方認為 (C)「CT 見 renal artery thrombosis 就一定要立即血管攝影」為錯，因為處置要依側別、單腎、缺血時間與其他合併傷決定（revascularization 或手術）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-2","year":98,"qnum":2,"topic":"胸部","subtopic":"總論／其他","stem":"一名 22 歲男子遭受槍擊，槍傷入口在左肩。他最初的血壓為 80/40mmHg，經過 2 公升林格氏液灌注，他的血壓增加為 122/84mmHg。目前心跳 100 次/分，呼吸 28 次/分，左側胸部呼吸聲降低。放置胸管後，只見少量的血，且無空氣排出，最合適的下一個步驟是：","opts":[{"k":"A","t":"再次評估胸部。"},{"k":"B","t":"主動脈攝影。"},{"k":"C","t":"胸部電腦斷層。"},{"k":"D","t":"評估動脈血氧。"},{"k":"E","t":"經食道心臟超音波檢查。"}],"answer":"A","expl":"左肩槍傷、2L 輸液後血壓上升，放置胸管僅少量血、無漏氣，這時應 re-assess（重新評估）胸管位置、其他出血來源、對輸液反應與 great vessel／mediastinal injury，所以 (A)。直接做其他檢查前要先確認病人是否真的穩定。補充：2 L 林格氏液已超出 ATLS 10/11 限制晶體液的建議。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-3","year":98,"qnum":3,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有ㄧ 30 歲男性用水果刀於右上腹自刺，產生一處 1 公分長傷口，到院時生命現象穩定，下列敘述何者為是？","opts":[{"k":"A","t":"此病患有超過 80%的機會有嚴重需開刀修補的臟器傷害。"},{"k":"B","t":"若持續生命現象穩定，無腹膜炎徵象可先以非手術性療法治療，有變化才需剖腹探查手術。"},{"k":"C","t":"因肝臟的位置保護，完全不需擔心橫膈膜傷害的可能。"},{"k":"D","t":"若傷口處有網膜疝出(omentum evisceration)，100%有嚴重內部臟器傷害。"},{"k":"E","t":"安排腹部電腦斷層掃描可以精確地預測是否有嚴重內部臟器傷害。"}],"answer":"B","expl":"腹部穿刺傷若生命徵象穩定、無腹膜炎，可採 selective non-operative management，有變化才剖腹，所以 (B)。(A) 實際約 25–35% 需要手術修補；(C) 右上腹傷仍可能傷橫膈；(D) 網膜 evisceration 不一定有嚴重內臟傷；(E) CT 對 hollow viscus injury 不是 100% 準確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-4","year":98,"qnum":4,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關槍傷的敘述何者為非？","opts":[{"k":"A","t":"槍傷的經過路徑(trajectory)ㄧ般比刀傷更加難以預測。"},{"k":"B","t":"槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。"},{"k":"C","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)可達 90%以上的準確率。"},{"k":"D","t":"治療槍傷的基本原則與刀傷同，仍依高級外傷救命術精神為主。"},{"k":"E","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"}],"answer":"C","expl":"槍傷彈道會因彈頭 yaw、碎裂與碰到骨頭而偏折，以「直線原則」預測並不可靠，所以 (C) 的 90% 準確率為錯。入口通常比出口有較多 abrasion collar，但不可作為判斷依據。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-5","year":98,"qnum":5,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"一位十八歲男性機車騎士與前方來的計程車正面相撞後被送來到急診處。外傷團隊先確定呼吸道通暢與評估患者的呼吸。接著測量血壓，心跳，微血管灌流的同時打了兩條 IV 補充生理食鹽水。最後將患者的衣服除去從頭到腳仔細檢查皮膚外表。請問根據 ATLS 的照顧原則，這個外傷團隊忽略了那個重要的步驟？","opts":[{"k":"A","t":"簡易的神經學檢查。"},{"k":"B","t":"告知家屬有關患者之病情。"},{"k":"C","t":"測量患者體溫。"},{"k":"D","t":"利用 bag-mask 幫患者呼吸(ventilation) 。"},{"k":"E","t":"沒有忽略任何重要的步驟。"}],"answer":"A","expl":"根據 ATLS primary survey：A、B、C、D（disability，簡易神經學檢查：GCS、瞳孔）、E（exposure/environment，含保暖）。題目團隊做了 A、B、C、E，卻沒做 D，所以 (A)。題中使用「生理食鹽水」也不是 ATLS 優先建議，現行偏好 balanced crystalloid（如 LR）或血品。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-6","year":98,"qnum":6,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"下列何者外傷患者來到急診處時會有頸靜脈怒張的表現？","opts":[{"k":"A","t":"有增壓性氣胸的病人。"},{"k":"B","t":"有開放性氣胸的病人。"},{"k":"C","t":"有大量血胸的病人。"},{"k":"D","t":"心臟挫傷的病人。"},{"k":"E","t":"以上所述患者都有可能。"}],"answer":"A","expl":"Tension pneumothorax 因縱隔移位與 IVC 受壓，造成 neck vein distension 與休克；massive hemothorax 因低血容，頸靜脈通常塌陷（flat），開放性氣胸、心臟挫傷表現不同，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-7","year":98,"qnum":7,"topic":"休克輸血","subtopic":"總論／其他","stem":"一位二十歲的女大學生過街時被一輛遊覽巴士撞。二十分鐘後被送到您工作的急診處。病人呈現明顯的失血性休克與多部位創傷。以下的何種外傷無法解釋他的失血性休克？","opts":[{"k":"A","t":"左側血胸。"},{"k":"B","t":"兩側股骨骨折。"},{"k":"C","t":"肝脾臟受傷。"},{"k":"D","t":"左側硬腦膜下出血和併同側腦挫傷。"},{"k":"E","t":"以上的外傷都會造成失血性休克。"}],"answer":"D","expl":"成人顱內出血（SDH、腦挫傷）容量有限，不足以解釋出血性休克；嬰兒因顱縫未閉才可能。因此 (D) 無法解釋休克，需尋找胸、腹、骨盆、長骨等出血源。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-8","year":98,"qnum":8,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"有關懷孕婦女的敘述何者不正確 ？","opts":[{"k":"A","t":"懷孕婦女常需較大量失血才會導致血壓下降。"},{"k":"B","t":"胎兒比懷孕婦女更早因失血休克而受害。"},{"k":"C","t":"懷孕婦女之心跳在第三產程較正常人時為快。"},{"k":"D","t":"為提供胎兒氧氣需要，在第三產程懷孕婦女之血紅素較正常人為高。"},{"k":"E","t":"懷疑出血性休克的懷孕婦女宜將右臀墊高四到六英吋。"}],"answer":"D","expl":"懷孕時血漿容量增加多於紅血球，造成 dilutional anemia，血紅素不會比較高，所以 (D) 錯（題目的「第三產程」應是 third trimester 的誤譯）。(A) 孕婦 blood volume 增加，需較大出血量才會低血壓；(B) 胎盤血流先犧牲；(E) 墊高右臀等於 left lateral tilt。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-9","year":98,"qnum":9,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"有關外傷小組的敘述何者不正確 ？","opts":[{"k":"A","t":"外傷小組之組成每個醫院可以不同，可隨著醫院的層級、所在地理位置與外傷病患類型來設計。"},{"k":"B","t":"可以規定依病患傷害嚴重度之不同，啟動不同層級之外傷小組。"},{"k":"C","t":"由醫師、護理人員、檢驗放射技術人員聯合組成。"},{"k":"D","t":"外傷急救醫院之外傷小組依賴團隊成員之默契，一般來說不需要文字規定。"},{"k":"E","t":"外傷小組的運作良否直接與病患之預後存活與否相關。"}],"answer":"D","expl":"外傷小組的啟動標準、組成與流程需要明文規定（activation criteria、角色分工）以確保品質，所以 (D)「不需要文字規定」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-10","year":98,"qnum":10,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關頸部外傷的解剖分區(anatomic zone)，下列敘述何者為誤？","opts":[{"k":"A","t":"Zone I 至 Zone III 是 自上而下作為區分。"},{"k":"B","t":"Zone II 是指頸部中段，自 cricoid cartilage 至 angle of mandible。"},{"k":"C","t":"Zone III 富含血管構造，一旦深部受傷不易手術止血，radiological intervention 有助於此處受傷的診斷與控制。"},{"k":"D","t":"Posterior triangle 比 anterior traniangle 較不重要，因重要結構較少。"},{"k":"E","t":"血管攝影檢查對評估 Zone I 和 Zone III 的受傷較 Zone II 重要。"}],"answer":"A","expl":"頸部 Zone 的分區由下往上：Zone I（clavicle 至 cricoid）、Zone II（cricoid 至 angle of mandible）、Zone III（angle of mandible 以上），所以 (A)「自上而下」為錯。Zone I 與 III 難以手術暴露，血管攝影／CTA 較重要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-11","year":98,"qnum":11,"topic":"顏面頸部","subtopic":"總論／其他","stem":"一船員被鋼鎖掃中左側肩頸部，兩日後突然昏厥被送至你的醫院急診，以下處置何者為誤？","opts":[{"k":"A","t":"先按 ABCDE 的原則作 primary survey。"},{"k":"B","t":"在未排除頸椎受傷前，須以頸圈固定頸椎。"},{"k":"C","t":"頸部身體檢查時無血腫、聽診也無 bruit，呼吸道亦查無血塊異物時，即可排除頸部血管損傷。"},{"k":"D","t":"頭頸部電腦斷層檢查時，須用顯影劑。"},{"k":"E","t":"頭頸部電腦斷層檢查為 secondary survey procedure。"}],"answer":"C","expl":"沒有血腫、bruit 等 hard signs，也不能排除 blunt cerebrovascular injury（carotid／vertebral artery dissection），兩日後昏厥更要想到這點，需要 CTA，所以 (C) 錯。(D) CT 須用顯影劑。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-12","year":98,"qnum":12,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"有關嚴重胸腹外傷病患之急救處理，請選出正確敘述？","opts":[{"k":"A","t":"所有傷患均應該使用”Damage Resuscitation” ，且無例外。"},{"k":"B","t":"輸液以”crystalloid”為最佳選擇。"},{"k":"C","t":"“permissive hypotension”觀念可應用於重傷急救。"},{"k":"D","t":"“Damage Resuscitation”之觀念僅適用胸腹外傷領域。"},{"k":"E","t":"手術方式之選擇不必考慮病人之生理狀況。"}],"answer":"C","expl":"嚴重胸腹外傷時，現行建議 damage control resuscitation：permissive hypotension、早期輸血（balanced ratio）、避免大量晶體液與低體溫，所以 (C)。但 TBI 或 spinal cord injury 需維持較高 BP，不可套用 permissive hypotension。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-13","year":98,"qnum":13,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"關於常見胸部外傷之”Pitfall”， 下列何者為錯誤之敘述？","opts":[{"k":"A","t":"“tension pneumothorax”與”massive hempthorax”兩者都引起”decreased breath sound”，但理學檢查仍可區分兩者。"},{"k":"B","t":"病人插管後，左胸呼吸音消失，一定有左側氣胸或血胸。"},{"k":"C","t":"血胸若不能引流乾淨，可能發生”lung entrapment” or ”empyema” 。"},{"k":"D","t":"“pulmonary contusion”往往無法單純從”CXR”作正確評估。"},{"k":"E","t":"若無心臟血管外科支援，對於有”wide mediastinum”病人應盡速轉院，而非做更詳盡檢查。"}],"answer":"B","expl":"插管後左胸呼吸音消失最常見原因是 right mainstem intubation（管子太深）；氣胸、血胸只是可能，不是「一定」，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-14","year":98,"qnum":14,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有一健康的高中生，沒有任何過去病史。他被揮棒擊中前胸，送至急診時呈現蒼白盜汗氣促的模樣，經置入氣管內管及 2000cc 生理食鹽水靜脈注射後，症狀稍解；此時胸部 X 光並無異狀，氣管內管的位置良好；腹部超音波檢查也無出血現象。但是，約 20 分鐘後，病患血壓又漸漸降至 80/60mmHg，心跳 126/min；此時呼吸音兩側正常，心音清楚但有心縮期雜音(systolic murmur)。下列何者是比較適宜的處置？","opts":[{"k":"A","t":"繼續大量輸液及輸血。"},{"k":"B","t":"立即執行急診部開胸術(ED thoracotomy) 。"},{"k":"C","t":"沿第二肋間鎖骨中線插入大號針頭。"},{"k":"D","t":"心臟超音波檢查(echocardiogram) 。"},{"k":"E","t":"立即執行心包膜穿刺術(pericardiocentesis) 。"}],"answer":"D","expl":"胸部鈍傷後持續低血壓、新出現 systolic murmur，需考慮 blunt cardiac injury（如 VSD、valve／papillary muscle rupture），應做 echocardiography 診斷，所以 (D)。補充：2000 mL 生理食鹽水不符現行 ATLS 對晶體液的限制。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-15","year":98,"qnum":15,"topic":"胸部","subtopic":"總論／其他","stem":"有關胸壁鈍傷的敘述，下列何者不正確？","opts":[{"k":"A","t":"斷裂的肋骨數和死亡或病情(mortality / morbidity)有正相關性。"},{"k":"B","t":"超過三根的肋骨骨折時代表整體傷勢較重，病患宜轉送外傷中心。"},{"k":"C","t":"小孩的肋骨骨折較少見；若有時，應考慮兒童虐待的可能性。"},{"k":"D","t":"確定胸廓是否有骨折斷裂是胸部 X 光檢查最主要的目的。"},{"k":"E","t":"老年人的胸壁鈍傷常造成肋骨骨折，較少造成胸內的傷害。"}],"answer":"D","expl":"胸部 X-ray 的目的不只確認肋骨骨折，而是找出 pneumothorax、hemothorax、pulmonary contusion、mediastinal widening、diaphragm injury 等危及生命的問題，所以 (D)「最主要目的是確認肋骨骨折」為錯。(A)(B) 肋骨骨折數越多預後越差；(C) 兒童肋骨有彈性，骨折要想到 child abuse；(E) 老人常見肋骨骨折且併發症多（因肺功能差）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-16","year":98,"qnum":16,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"下列關於主動脈外傷性破裂(traumatic aortic disruption)的敘述，何者錯誤？","opts":[{"k":"A","t":"造成嚴重出血者，死亡率為 100%，多半死於現場。"},{"k":"B","t":"到院時生命徵象不穩定者，多半在數小時內，死於多重傷害(multisystem trauma) 。"},{"k":"C","t":"到院時生命徵象穩定者，也有 5~30% 的死亡率，多半死於中樞神經(CNS)傷害。"},{"k":"D","t":"因為致死率高，在 ATLS 初級評估中，列為六項危及生命狀況的胸部外傷之一。"},{"k":"E","t":"顯影劑電腦斷層螺旋檢查(helical contrast-enhanced CT)是可信賴的篩檢方法。"}],"answer":"D","expl":"ATLS 把主動脈破裂列在 secondary survey 的 potentially life-threatening chest injuries（共 8 項），而 primary survey 的「immediately life-threatening」六項是 airway obstruction、tension pneumothorax、open pneumothorax、massive hemothorax、flail chest/pulmonary contusion 與 cardiac tamponade，所以 (D) 錯。(E) helical CTA 為可靠篩檢。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-17","year":98,"qnum":17,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一位 30 歲男性摩托車騎士不幸發生車禍，與小轎車對撞，立即送至急診室。發現有右側股骨開放性骨折，右下肢變形，傷口有滲血，下肢感覺神經未受損，但右足背血管(Dorsalis pedis)跳動減弱，此時應該?","opts":[{"k":"A","t":"應該立即使用止血加壓帶止血。"},{"k":"B","t":"立刻於此開放性傷口塞入紗布以止血。"},{"k":"C","t":"立刻探查傷口並清除壓迫血管的異物。"},{"k":"D","t":"可使用 traction splint，恢復些股骨 alignment，以改善足背血管血流不佳情況。"},{"k":"E","t":"立刻做 fasciotomy。"}],"answer":"D","expl":"開放性股骨骨折並足背脈搏減弱，應先 realign 肢體（in-line traction）並夾板固定，常能恢復血流；如果之後脈搏仍弱，才進一步做 ABI、CTA 或手術探查，所以 (D)。(A) 不應直接用 tourniquet；(B) 不應將紗布塞入傷口；(E) 非首要。補充：開放性骨折若骨頭外露，使用 traction splint 時要注意避免將污染骨頭拉回傷口內。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-18","year":98,"qnum":18,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"一位 22 歲男性轎車駕駛不幸發生轎車-轎車對撞車禍，送至急診室。因轎車起火燃燒，導致胸部和兩上臂整圈三度整層皮的燒傷，約佔 50﹪T.B.S.A.，立刻插管並接上呼吸器，並給予充分生理食鹽水，其血中 carboxy- hemoglobin 為 45﹪，動脈血液分析為：PaO2：90㎜ Hg，PaCO2：60 ㎜ Hg，PH：7.3。此時較適當的處理為：(複選重組的單選)(1) 做 hemodialysis。\n(2) 做 Chest Escharotomy。\n(3) 可給予高壓氧治療。\n(4) 給予大量 IV NaHCO3。\n(5) 給予高濃度氧。","opts":[{"k":"A","t":"2,3,4"},{"k":"B","t":"3,4,5,"},{"k":"C","t":"2,3,5"},{"k":"D","t":"1,3,5"},{"k":"E","t":"1,2,5"}],"answer":"C","expl":"火災病人有 CO 中毒（COHb 45%）且胸部環狀三度燒傷，需給予 100% oxygen（縮短 COHb 半衰期）、考慮 hyperbaric oxygen，並做 escharotomy 解除胸壁限制，所以 (2)(3)(5)，答案 (C)。透析與大量 NaHCO3 無必要，且 PaO2 不代表實際氧含量，因為 CO 中毒者 SpO2 讀值不可靠。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-19","year":98,"qnum":19,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"關於多重外傷的病理生理學(pathophysiology)，下面的敘述何項正確？","opts":[{"k":"A","t":"SIRS (systemic inflammatory response syndrome)就等同於 MODS(multiple organ dysfunction syndrome) 。"},{"k":"B","t":"CARS (compensatory anti-inflammatory response syndrome) 無關於外傷後感染。"},{"k":"C","t":"所謂 SIRS (systemic inflammatory response syndrome)，即為外傷後的宿主防衛反應。"},{"k":"D","t":"Two-hit theory 中發生感染(infection)應列為 first hit。"},{"k":"E","t":"組織在承受外傷低血壓後不會產生宿主防衛反應。"}],"answer":"C","expl":"多重外傷後的 SIRS 是宿主對組織傷害的防衛反應；SIRS 不等於 MODS，而 CARS 與外傷後感染有關；two-hit theory 中第一擊為初始創傷／休克，第二擊（如感染、手術）才會誘發 MODS；故 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-20","year":98,"qnum":20,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"土石流災難後有產生大量外傷傷患，外傷醫師常會被分派很多臨時的額外工作，下列何種原則是最正確的？","opts":[{"k":"A","t":"除非外傷病患被困住無法移動，否則外傷醫師最適合接觸病患的地方是從急救站檢傷區開始，在此之前的工作不會比急救技術員做的好。"},{"k":"B","t":"雖然沒有受過特別的災難醫療訓練，外傷醫師在災難現場也都能發揮很大的救災功能。"},{"k":"C","t":"一般而言，儘早調動較多醫院的外傷醫師到災難現場，一定可以提高救災品質。"},{"k":"D","t":"一般而言，急救技術員緊急時可以替代護士在醫院內的工作。"},{"k":"E","t":"災難時，急救技術員較醫護人員有公共衛生的概念。"}],"answer":"A","expl":"大量傷患事件中，外傷醫師最適合的角色從檢傷分類區域開始，現場搶救與後送由 EMT 與指揮系統負責；一般外傷醫師未經災難醫學訓練並不一定能在現場發揮最大效能；因此 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-21","year":98,"qnum":21,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"關於骨盆骨折的敘述，以下何者有誤？","opts":[{"k":"A","t":"若發生休克現象，須先排除胸腔或腹腔內出血。"},{"k":"B","t":"Lateral compression 是最常見的骨折類型，也是發生出血性休克機率最高的類型。"},{"k":"C","t":"以床單綑綁骨盆處可以幫忙穩定骨盆，減少繼續出血。"},{"k":"D","t":"血管攝影栓塞術是控制骨盆腔內動脈出血的首選方法。"},{"k":"E","t":"若需要插尿管，須先做骨盆局部的理學檢查。"}],"answer":"B","expl":"骨盆骨折中，最常見的類型是 lateral compression（LC），但出血性休克機率最高的是 anteroposterior compression（open book）與 vertical shear，所以 (B) 錯。(A) 先排除胸腹出血；(C) pelvic binder／床單包覆；(E) 置尿管前應評估 urethral injury。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-22","year":98,"qnum":22,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"Severe head injury 的處理，下列敘述何者為錯?","opts":[{"k":"A","t":"宜維持腦灌流壓(CCP)至少 60－70 mmHg。"},{"k":"B","t":"use isotonic solution for euvolemia。"},{"k":"C","t":"use Steroid for brain swelling。"},{"k":"D","t":"Maintain PaCO2 near/at 35 mmHg。"},{"k":"E","t":"Barbiturate coma。"}],"answer":"C","expl":"嚴重 TBI 不建議使用 corticosteroid（CRASH trial 顯示死亡率反而增加），所以 (C)。其他：維持 CPP 60–70 mmHg、isotonic fluid 維持 euvolemia、PaCO2 約 35 mmHg、難治性 ICP 可考慮 barbiturate coma。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-23","year":98,"qnum":23,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有一 35 歲板模工人，工作時由三樓高鷹架跌下，病人到急診室意識清楚，生命跡象穩定，但左下肺野呼吸聲降低，扣診呈頓音，胸部 x-ray 發現左胸有小腸腸氣，最佳之治療為？","opts":[{"k":"A","t":"急作左側開胸手術並作橫膈膜修補。"},{"k":"B","t":"急作剖腹探查手術並作橫隔膜修補。"},{"k":"C","t":"急作胃鏡。"},{"k":"D","t":"作上腸胃道攝影。"},{"k":"E","t":"保守治療。"}],"answer":"B","expl":"左下肺野呼吸音降低並見腸氣在左胸，是 traumatic diaphragmatic rupture 的典型表現。急性期建議由腹部入路 laparotomy，才能同時評估與處理其他腹內傷害，所以 (B)。(A) 胸部入路多用於延遲診斷；(C)(D)(E) 皆不適合。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-24","year":98,"qnum":24,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"結腸是腹部穿刺傷中第二常見受創的器官。下列何種做法並不建議?","opts":[{"k":"A","t":"血行動力學狀態穩定的患者，儘量考慮直接修補縫合。"},{"k":"B","t":"低血容性休克患者，也可以考慮直接修補縫合。"},{"k":"C","t":"低血容性休克患者，第一次手術時，在控制腹部出血後，對結腸廣泛性損傷(extensive injuries)進行 Hartmann's procedure 來建立結腸造廔口。"},{"k":"D","t":"血行動力學狀態穩定的患者，如果距結腸損傷超過 24 小時，建議合併結腸造廔口手術。"},{"k":"E","t":"合併腹部腔室症候群(abdominal compartment syndrome)的病人儘量避免建立結腸造廔口。"}],"answer":"C","expl":"結腸穿刺傷：血流動力學穩定者可 primary repair／resection with anastomosis；低血壓、嚴重污染或多重傷害則可用 resection、damage control 與後續 stoma。官方答案 (C) 把 Hartmann's procedure 列為『不建議』。","outdated":false,"suspect":true,"flagNote":"依現行 EAST／WSES 指引，休克合併廣泛性結腸損傷時 Hartmann's procedure（切除 + end colostomy）或 damage control 暫不吻合，是常見且被接受的選擇；真正較不被建議的反而是休克下的 (B) 直接修補，所以 (C) 可能是官方答案錯誤。考試仍以官方 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"98-25","year":98,"qnum":25,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"一位 40 歲男性機車騎士，不幸撞上電線桿，被送至急診室，發現病人神智不清，四肢癱瘓，並呈現休克狀態，Systolic blood pressure 為 70mmHg，心跳 45 次，頸部 X-ray 發現 C6 fracture dislocation，於急救後送至加護病房照顧，下面的敘述何者不正確 ?","opts":[{"k":"A","t":"理學檢查可發現其皮膚是溫暖的但肛門收縮(anal tone)喪失。"},{"k":"B","t":"早期處理可使用升壓劑(Vasopressor) 。"},{"k":"C","t":"其低血壓不需大量輸液處理。"},{"k":"D","t":"早期處理可使用 Steroid。"},{"k":"E","t":"早期其深層腱反射喪失(Loss of deep tendon reflex)是可預測的。"}],"answer":"C","expl":"頸髓損傷（C6）合併低血壓與 bradycardia、皮膚溫暖，是 neurogenic shock。官方答案認為 (C)「低血壓不需大量輸液」為錯誤：因為必須先排除 hypovolemia 合併出血（尤其多重傷害），先給予補液再用 vasopressor。","outdated":true,"suspect":false,"flagNote":"選項 (D)「早期可使用 steroid」是舊的 NASCIS 觀念，現行 ATLS 10 與 AANS/CNS 2013 不建議，所以在今日這題「何者不正確」其實 (D) 才更符合。官方答案 (C) 不變，但請注意 (D) 已過時，且 (C) 的對錯取決於是否先排除出血。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"98-26","year":98,"qnum":26,"topic":"頭部TBI","subtopic":"總論／其他","stem":"一位 40 歲機車騎士被送至急診室，有明顯頭部外傷，兩眼瞳孔大小不等，血壓 80/40mmHg，呼吸聲音大，給予疼痛刺激時，兩眼睜開且兩側上臂彎曲併發出呻吟聲，以下敘述何者正確?","opts":[{"k":"A","t":"此病患 GCS 為 6 分，屬於 severe head injury。"},{"k":"B","t":"此病患需迅速建立呼吸道，例如放置氣管內管，並給予 Hyperventilation。"},{"k":"C","t":"先輸予含葡萄糖水之靜脈輸液，將血壓提升至 100mmHg 以上，且穩定後再送電腦斷層室行頭部及腹部電腦斷層檢查。"},{"k":"D","t":"做頭部電腦斷層時要注射顯影劑。"},{"k":"E","t":"若該院無神經外科醫師，則在病患到急診未做任何檢查前，需緊急將病患轉院。"}],"answer":"B","expl":"嚴重頭部外傷併瞳孔不等大，代表可能 herniation；應先 airway control（插管）、給氧，並在 herniation 徵象下做短暫 hyperventilation 作為橋接，所以 (B)。依描述 GCS 約 7–8（E2、V2、M3–4），仍屬 severe TBI，(A)「6 分」不精確。(C) 不應給含糖液；(D) 一般頭部 CT 不需顯影劑；(E) 不需「未做任何檢查」就轉院。補充：BP 80/40 也要同時處理低血壓，因 hypotension 會增加 TBI 死亡率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-27","year":98,"qnum":27,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"The following concepts of abdominal compartment syndrome (ACS) are right, except:","opts":[{"k":"A","t":"Increased intra-abdominal pressure (IAP), usually > 20 mmHg。"},{"k":"B","t":"The gold standard for IAP measurement involves using a nasogastric tube。"},{"k":"C","t":"Aggressive non-operative intensive care support is critical to prevent the complications of ACS。"},{"k":"D","t":"The second aspect of management is to correct any reversible cause of ACS, such as intra-abdominal bleeding。"},{"k":"E","t":"Surgical abdominal decompression is one of the treatments to prevent ACS。"}],"answer":"B","expl":"IAP 的 gold standard 是經 Foley 的 bladder pressure（WSACS），不是 nasogastric tube，所以 (B) 錯。ACS 定義為 IAP 持續 >20 mmHg 加上新發器官衰竭；治療包含重症支持、矯正可逆因素與必要時 decompressive laparotomy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-28","year":98,"qnum":28,"topic":"腹部","subtopic":"脾臟","stem":"關於 cirrhosis of liver 病人合併脾臟創傷,下列敘述何者正確?","opts":[{"k":"A","t":"因為醫療技術進步,目前這類病患治療起來並無困難。"},{"k":"B","t":"非手術治療之死亡率並不高。"},{"k":"C","t":"非手術治療決不能使用,因成功率太低。"},{"k":"D","t":"應積極矯正這類病患之凝血功能障礙。"},{"k":"E","t":"High-grade 脾臟創傷,應進快做血管栓塞,避免開刀以求降低死亡率。"}],"answer":"D","expl":"肝硬化病人合併脾臟外傷，常伴 coagulopathy、thrombocytopenia 與 portal hypertension，NOM 失敗率與死亡率較高，應積極矯正凝血功能障礙，所以 (D)。(C) 並非絕對禁忌；(E) high-grade 仍需依血流動力學決定。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-29","year":98,"qnum":29,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"一位 18 歲男性病患，從 10 公尺高樓墜地，來院急診時，血壓為 86/48mmHg，心跳:118/min，呼吸 30/min，0.9% N/S challenge 1000cc 及氣管內管插管後生命跡象穩定；隨後影像檢查，顯示:1.顱內出血(GCS 插管後為 E1M5VE,pupil 2.0/2.0minm,有光反應) (如圖 1). 2.胸部挫傷合併左側血氣胸及左肺挫傷及顯影劑外漏(如圖 2). 3.左肱骨閉合性骨折. 4.骨盆恥骨閉合性骨折合併顯影劑外漏(如圖 3). 5.右側股骨閉合性骨折；請問病患之 Injury Severity Score(ISS)及 New Injury Severity Score (NISS)各為多少?\n(圖 1) (圖 2) (圖 3)","opts":[{"k":"A","t":"41 分及 45 分。"},{"k":"B","t":"43 分及 55 分。"},{"k":"C","t":"57 分及 57 分。"},{"k":"D","t":"66 分及 66 分。"},{"k":"E","t":"66 分及 75 分。"}],"answer":"C","expl":"ISS 取三個不同身體區域最高 AIS 的平方和，NISS 則取全身最嚴重的三個傷（不分區域）。依官方答案 57：head（顱內出血）AIS 5、chest（血氣胸、肺挫傷合併顯影劑外漏）AIS 4、骨盆／extremity（恥骨骨折合併 contrast extravasation）AIS 4，ISS = 25 + 16 + 16 = 57；三個最高傷勢分屬不同區域，所以 NISS 也是 57。注意：AIS 版本不同編碼可能不同，無法在此獨立驗證每個 AIS 值，請以計算原理為主。","outdated":false,"suspect":false,"flagNote":"","images":["p049-1.jpg"]},{"id":"98-30","year":98,"qnum":30,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"依上題病患多重外傷病況發展，發現病患氣管內管開始持續冒血，血壓在來院 20 分鐘後，又再次下降至 80/40mmHg，除繼續 blood 及 fluid resuscitation 外，如果您是外傷小組的主事者，接下來的處理，何者較為適當?","opts":[{"k":"A","t":"聯絡 Radiologist，作血管攝影栓塞。"},{"k":"B","t":"聯絡外傷骨科醫師，行右股骨，左肱骨及骨盆骨折內固定。"},{"k":"C","t":"行右側 one-lung intubation 並 block 左側氣管，聯絡胸腔外科醫師行 thoracotomy。"},{"k":"D","t":"聯絡神經外科醫師，行 craniotomy，清除腦內血塊。"},{"k":"E","t":"聯絡胸腔外科醫師裝上 ECMO (Extra-corporial Membranous Dxygenation)並聯絡Radiologist 行血管栓塞。"}],"answer":"C","expl":"氣管內管持續冒血，表示肺實質或支氣管出血，且病人休克再度惡化，應立即 selective one-lung ventilation（插入健側主支氣管、封閉出血側）並緊急開胸止血，所以 (C)。血管攝影、骨折固定與 craniotomy 都不是此刻最急；ECMO 在出血性休克相對不適。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-31","year":98,"qnum":31,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"對於診斷性腹膜沖洗術(Diagnostic Peritoneal Lavage, DPL)在外傷病患的應用，下列敘述，何者為非?","opts":[{"k":"A","t":"於 1965 年，Dr. Root 等人發表，主要為幫助診斷外傷病患可能存在的腹膜腔出血或腸道破裂。"},{"k":"B","t":"目前主要應用於外傷病患的可能腸道破裂的快速篩選。"},{"k":"C","t":"有腹部手術過的外傷病患，仍可以執行，不過須用開放性方式(open method)來執行。"},{"k":"D","t":"依據 Dr. Otomo 等人統計，以 DPL ascites 的 cell count:WBC> RBC/150 當作 bowel perforation 的診斷根據，在受傷 3 到 18 小時內作 DPL，其診斷正確率可達到 99%。"},{"k":"E","t":"對於 anterior abdominal wall stab wound，若 DPL ascites≦ 50,000 RBC s/mm3，病人可以回家其 false negative rate 僅有 1%。"}],"answer":"E","expl":"腹部前壁穿刺傷的 DPL 判讀，傳統上 RBC >100,000/mm³ 為鈍傷陽性標準，穿刺傷的標準較低（常用 >1,000–10,000/mm³）；把 ≤50,000 當作可回家且 false negative 僅 1%，不符合文獻，所以 (E) 錯。(B)(D) 為 DPL 在偵測腸道穿孔的用途。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-32","year":98,"qnum":32,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"有關 Retroperitoneal Duodenal injury 早期診斷最好的方法為?","opts":[{"k":"A","t":"Double contrast CT scan。"},{"k":"B","t":"Diagnostic peritoneal lavage。"},{"k":"C","t":"Laparoscope。"},{"k":"D","t":"Sonogram。"},{"k":"E","t":"Local wound exploration。"}],"answer":"A","expl":"後腹腔十二指腸損傷常無腹膜炎，DPL 容易偽陰性；早期診斷可用 contrast-enhanced CT（含 oral contrast 的 double contrast CT）或 upper GI series，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-33","year":98,"qnum":33,"topic":"DCS_ACS","subtopic":"總論／其他","stem":"33 y/o 男性，鈍性肝臟裂傷接受手術止血，當出現下列何種情況應考慮 Damage Control，除 了?","opts":[{"k":"A","t":"Massive blood loss (> 5000 cc) 。"},{"k":"B","t":"Acidosis (pH < 7.2) 。"},{"k":"C","t":"Hypotension (shock > 30 minutes) 。"},{"k":"D","t":"Hyothermia (core temperature < 34 C) 。"},{"k":"E","t":"Management of extra-abdominal life-threatening injuries。"}],"answer":"C","expl":"Damage control 的適應條件：大量失血（>5000 mL／大量輸血）、acidosis（pH <7.2）、hypothermia（<34°C）、coagulopathy、無法在短時間完成確定性手術，以及合併腹外危及生命傷害。「休克 >30 分鐘」不是典型標準，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-34","year":98,"qnum":34,"topic":"DCS_ACS","subtopic":"總論／其他","stem":"30 y/o 男性，機車事故，被送至醫院急診室，診斷為腹腔內出血休克，緊急送至手術室接受剖腹術，發現有肝裂傷出血，小腸斷裂，骨盆骨折後腹膜腔血腫，術中 blood loss 總量已過 6000c.c.，此時你決定做 Damage Control，則下列處置方法,何者不恰當?","opts":[{"k":"A","t":"肝臟裂傷修補、縫合。"},{"k":"B","t":"肝臟出血 packing。"},{"k":"C","t":"小腸部分切除並做吻合術減少感染。"},{"k":"D","t":"腹壁快速縫合。"},{"k":"E","t":"繼續 resuscitation，安排 transarterial embolization。"}],"answer":"C","expl":"Damage control laparotomy 不做複雜重建：肝臟用 packing、腸道破裂用快速縫合或 stapler 切除並暫時不吻合（abbreviated laparotomy）、暫時關腹、再回 ICU 做 resuscitation／angioembolization。因此 (C)「切除並吻合」不恰當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-35","year":98,"qnum":35,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"Which of the following statement(s) about penetrating cardiac injury is/are CORRECT? (複選重組的單選)(1) Pericardiocentesis has a role in establishing the diagnosis of cardiac injuries.(2) Subxiphoid Pericardial Window has a role in the acute evaluation of penetrating cardiac injuries.(3) Two-Dimensional Echocardiography has a role in the acute evaluation of penetrating cardiac injuries.(4) Thoracoscopy has a role in the acute evaluation of penetrating cardiac injuries.(5) Emergency Department Thoracotomy has a role in the acute evaluation of penetrating cardiac injuries.","opts":[{"k":"A","t":"(1), (2)。"},{"k":"B","t":"(1), (3) 。"},{"k":"C","t":"(2), (3) 。"},{"k":"D","t":"(1), (2), (3) 。"},{"k":"E","t":"(1), (2), (3), (5) 。"}],"answer":"C","expl":"穿透性心臟傷評估：subxiphoid pericardial window 與 2D echocardiography（FAST 的心包窗口）是診斷 tool，所以 (2)(3)；單純 pericardiocentesis 有高假陰性，不建議作為診斷方法；ED thoracotomy 為治療而非診斷；thoracoscopy 在血流動力學穩定者偶用，但不是標準。故 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-36","year":98,"qnum":36,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"Which of the following statement(s) about penetrating thoracic injury is/are CORRECT? (複選重組的單選)(1) The treatment of open pneumothorax is sterile occlusive dressing only.(2) Most of the penetrating chest trauma require only tube thoracostomy.(3) Acute or hypovolemic cardiac arrest in the patients with penetrating trauma to the chest suggests the need for resuscitative thoracotomy.(4) All of the patients with mediastinal traverse need emergent thoracotomy.(5) Most lung lacerations following penetrating trauma can be handled by pulmonary tractotomy or stapled nonanatomic resections.","opts":[{"k":"A","t":"(2), (3), (4) 。"},{"k":"B","t":"(2), (3), (5) 。"},{"k":"C","t":"(2), (4), (5) 。"},{"k":"D","t":"(3), (4), (5) 。"},{"k":"E","t":"(2), (3), (4), (5) 。"}],"answer":"B","expl":"(2) 多數穿刺性胸傷只需 tube thoracostomy；(3) 穿刺傷到院時剛停止心跳或低容積性心跳停止，需要 resuscitative thoracotomy；(5) 肺撕裂傷多用 tractotomy 或 stapled non-anatomic resection，所以 (B)。(1) 開放性氣胸應先用單向（三邊）敷料再放胸管，單純密封會造成 tension pneumothorax；(4) 縱隔穿透傷在穩定時需影像／食道／血管評估，不是全都要緊急開胸。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-37","year":98,"qnum":37,"topic":"休克輸血","subtopic":"總論／其他","stem":"男性車禍傷患，經急診診斷骨盆腔骨折、後腹腔出血、脾臟撕裂傷與左側血胸。經急救復甦處理後生命徵象仍不穩定，通知外科預行緊急手術；並安排輸血。但血庫通知患者驗血為 A 型 Rh 陰性，血庫無 Rh 陰性血﹐下列何者處置最適當？","opts":[{"k":"A","t":"聯絡其他醫院安排轉院治療。"},{"k":"B","t":"通知媒體召集 Rh 陰性 A 型捐血者。"},{"k":"C","t":"僅用乳酸林格液 (Lactate Ringers Solution)急救。"},{"k":"D","t":"乳酸林格液 5000 cc 輸注後，改用膠體溶液(如: HES:hydroxyethyl starch)。"},{"k":"E","t":"改採 Rh 陽性 A 型血輸血，緊急開刀。"}],"answer":"E","expl":"同 97-14：大量出血而無法取得同 Rh 血時，應立即輸 Rh-positive type A 血挽救生命（對男性與停經後女性尤其合理）。補充：(C)(D) 的大量晶體液與膠體不符現行 damage control resuscitation。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-38","year":98,"qnum":38,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"槍擊傷在台灣屬於相對少見，下列敘述何者不正確？","opts":[{"k":"A","t":"腹部槍擊傷大多數的外科醫師均採剖腹探查治療(laparotomy)。"},{"k":"B","t":"腹部槍擊傷期刊上亦有採行選擇性非手術(selective non-op.)的報告。"},{"k":"C","t":"腹部槍擊傷，剖腹探查發現僅為肝臟右葉表淺貫穿傷(Grade II)，已無持續出血，但為避免感染仍應行右肝葉切除手術，其結果最好。"},{"k":"D","t":"槍擊造成胸腔單純氣血胸，生命徵象穩定，可行胸管置放術後住院觀察。"},{"k":"E","t":"四肢肌肉與軟組織的槍擊傷，無血管、神經損傷，如有彈頭，不須立即擴創手術將彈頭取出。"}],"answer":"C","expl":"肝右葉 grade II 表淺貫穿傷且已止血，只需簡單處置（如 hemostatic agent 或單純縫合）與引流，不應做 right hepatectomy，所以 (C) 錯。(A)(B) 槍傷多採 laparotomy，也有 selective non-operative 報告；(D) 穩定氣血胸以 tube thoracostomy 處理；(E) 肢體軟組織槍傷若無血管神經傷，彈頭不需立即取出。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-39","year":98,"qnum":39,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關 resuscitative thoracotomy 之敘述何者為非?","opts":[{"k":"A","t":"胸部穿刺傷病患到院時無脈搏(arrive pulseless),但有 myocardial electrical activity 時,應實行 resuscitative thoracotomy。"},{"k":"B","t":"胸部穿刺傷病患到院前已接受 CPR,到院時有生命徵象(reactive pupils or spontaneous movement),且有 myocardial electrical activity 時,應實行 resuscitative thoracotomy。"},{"k":"C","t":"胸部鈍傷病患到院時無脈搏(arrive pulseless),但有 myocardial electrical activity 時,應實行 resuscitative thoracotomy。"},{"k":"D","t":"在急診針對無血壓病患執行之 resuscitative thoracotomy 成功率低於 10%。"},{"k":"E","t":"實行 resuscitative thoracotomy 之切口為 left anterolateral thoracotomy。"}],"answer":"C","expl":"依 EAST/WTA 指引，胸部穿刺傷無脈搏但有 signs of life 或電氣活動，是 resuscitative thoracotomy 的最佳適應症；鈍傷無脈搏（pulseless）即使有電氣活動，存活率極低，一般不建議，所以 (C) 為非。(D) 急診開胸整體存活率 <10%；(E) 標準切口為 left anterolateral thoracotomy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-40","year":98,"qnum":40,"topic":"休克輸血","subtopic":"總論／其他","stem":"25 歲男性病患，因機車車禍受傷，至本院急診時血壓 80/55mmHg，心跳速率 110/min，意識清楚，無頸部疼痛，無血氣胸，腹部超音波檢查無明顯出血，Pelvis X ray 顯示 unstable pelvic fracture，左側 femoral shaft 有 open type II fracture，Abdominal CT 懷疑有 hollow organ perforation。病患接受 2000c.c. Ringer lactate 及 8u PRBC 的 resuscitation，血壓為 70/40 mmHg，此時應做什麼處置較適當？","opts":[{"k":"A","t":"立刻進行開腹手術，以防 septic shock。"},{"k":"B","t":"立刻進行 Angiography 並視需要做 Embolization。"},{"k":"C","t":"立刻進行 femoral shaft open fracture 的 fixation 以止血。"},{"k":"D","t":"更積極輸血，使血壓穩定，以免在進行下一步處理時發生危險。"},{"k":"E","t":"以上皆非。"}],"answer":"B","expl":"骨盆骨折併 hemodynamic instability，已對 2000 mL 晶體液與 8 U PRBC 無反應，且腹部超音波沒有腹內出血，下一步為控制骨盆動脈出血：pelvic binder／external fixation 並 angiography with embolization，所以 (B)。補充：現行多加入 preperitoneal pelvic packing 與 REBOA，並以 MTP 取代大量晶體液。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-41","year":98,"qnum":41,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"施行急診室開胸手術 (ED thoracotomy) 後影響存活率之因子中，下列敘述何者為非？","opts":[{"k":"A","t":"鈍傷之存活率較穿刺傷高。"},{"k":"B","t":"穿刺傷之存活率較槍傷高。"},{"k":"C","t":"腹部外傷之存活率較多重外傷高。"},{"k":"D","t":"胸腔外傷之存活率較腹部外傷高。"},{"k":"E","t":"心臟外傷之存活率較胸腔外傷高。"}],"answer":"A","expl":"ED thoracotomy 存活率：穿刺傷 (約 10–20%) 遠高於鈍傷（約 1–2%），槍傷低於刀傷，單純心臟傷最高（尤其刀刺傷與 tamponade），所以 (A)「鈍傷較穿刺傷高」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-42","year":98,"qnum":42,"topic":"胸部","subtopic":"肺挫傷／創傷性窒息","stem":"請問 Traumatic asphyxia 的病患下列何者為非?","opts":[{"k":"A","t":"Cervicofacial cyanosis and edema."},{"k":"B","t":"Bilateral subconjunctival hemorrhage."},{"k":"C","t":"The most common neurological consequences are transient loss of consciousness and confusion, which may be prolonged but are generally self-limiting."},{"k":"D","t":"Oxygen has almost excellent effect on the resolution of the facial discoloration."},{"k":"E","t":"Most patients have good clinical outcome."}],"answer":"D","expl":"Traumatic asphyxia（胸部擠壓造成上半身靜脈壓突然上升）表現為頭頸部 cyanosis／petechiae、subconjunctival hemorrhage，多數預後良好；皮膚變色會自行消退，並非吸氧會使其明顯消失，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-43","year":98,"qnum":43,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"有關 Secondary abdominal compartment syadnme (ACS)之敘述，何者為非？","opts":[{"k":"A","t":"Early large volume crystalloid administration 是造成 secondary ACS 之主要 predictor。"},{"k":"B","t":"Severe extremities injury with shock 之病人為高危險群。"},{"k":"C","t":"某種程度上，可視為大量輸液後之 normal sequela 。"},{"k":"D","t":"此類病人不易走向 multiple organ failure (MOF)途徑。"},{"k":"E","t":"Abdominal CT 常顯示 large amount intraperitoneal fluid 或 diffuse bowel edema。"}],"answer":"D","expl":"Secondary ACS 常見於大量輸液與休克，後續容易走向 MOF，死亡率高，所以 (D)「不易走向 MOF」為錯。(A) 早期大量晶體液是重要 predictor；(B) 為高風險群；(E) CT 可見大量腹水與腸道水腫。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-44","year":98,"qnum":44,"topic":"胸部","subtopic":"總論／其他","stem":"有一患慢性阻塞性肺病(COPD)的老先生，走路時遭車禍，被撞到右側胸部，急診時胸部 X光發現有三根肋骨骨折，無其他異狀。下列敘述何者錯誤？","opts":[{"k":"A","t":"可以用束帶限制胸壁以減少疼痛。"},{"k":"B","t":"可能會有續發的血/氣胸。"},{"k":"C","t":"可能會有續發的肺挫傷。"},{"k":"D","t":"可能會有續發的呼吸衰竭。"},{"k":"E","t":"留置觀察為宜。"}],"answer":"A","expl":"束帶或胸壁綁帶會限制胸廓擴張，增加 atelectasis 與 pneumonia 風險，不建議；應以有效止痛（如 regional block）、呼吸治療與觀察處理，所以 (A) 錯。COPD 合併 ≥3 根肋骨骨折屬高風險，宜留院觀察，並留意 delayed hemothorax、pulmonary contusion 與呼吸衰竭。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-45","year":98,"qnum":45,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"28y/o 男 性 因 摩 托 車 與 車 輛 相 撞 ， 立 即 送 到 本 院 急 診 ， 到 達 時 血 壓 112/76mmHg ，PR:110/min，RR:22/min，GCS:E4M6V5，理學檢查，腹部稍微 distension 及 tenderness，腹部超音波發現腹膜腔內有 Fluid collection，腹部電腦斷層(未喝 oral contrast medium)顯示如下圖，接下來處置何者較為適當?","opts":[{"k":"A","t":"Fluid 或 blood resuscitation 後，轉到外科加護病房作密切追蹤。"},{"k":"B","t":"行緊急剖腹探查手術。"},{"k":"C","t":"聯絡 Radiologist，作緊急血管攝影栓塞治療。"},{"k":"D","t":"於急診留觀 1 小時候，再作一次腹部電腦斷層檢查，若出血量有增加，再行剖腹探查手術。"},{"k":"E","t":"轉到外科加護病房，隨時用腹部超音波追蹤，若腹膜腔內 fluid 量增加，再行剖腹探查手術。"}],"answer":"B","expl":"腹部超音波有腹內積液、CT 顯示腹內傷害伴積液，血壓正常但 HR 110 與腹部壓痛、擴張，官方答案 (B) 為緊急 laparotomy（附圖為 CT，可能代表腹內 free fluid 與腸道或腸繫膜傷害）。若 CT 顯示有 free fluid 但無實質器官傷害，要高度懷疑 hollow viscus／mesenteric injury，需手術探查。","outdated":false,"suspect":false,"flagNote":"","images":["p054-1.jpg"]},{"id":"98-46","year":98,"qnum":46,"topic":"休克輸血","subtopic":"總論／其他","stem":"關於 fluid resuscitation for trauma patients 何者為非?","opts":[{"k":"A","t":"Crystalloid 比較容易快速大量取得。"},{"k":"B","t":"Crystalloid 比較容易造成 lung or brain edema。"},{"k":"C","t":"Colloid 比較容易增加 intra-vascular volume。"},{"k":"D","t":"Colloid 比較不會引起過敏反應。"},{"k":"E","t":"Colloid 成本比較昂貴。"}],"answer":"D","expl":"Colloid 並不比 crystalloid 少引起過敏反應，反而 HES 與 dextran 等會有 anaphylactoid reaction 及腎功能與凝血的副作用，所以 (D) 錯。補充：現行 ATLS 與 SAFE trial 不建議常規使用 colloid 做創傷復甦。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-47","year":98,"qnum":47,"topic":"總論評分","subtopic":"總論／其他","stem":"Multiple trauma 的病人的治療方式何者為是?","opts":[{"k":"A","t":"尿量減少時應優先考慮給利尿劑以避免急性腎衰竭。"},{"k":"B","t":"使用大量昇壓劑以維持血壓。"},{"k":"C","t":"為避免血壓降低,儘量不要給病人止痛。"},{"k":"D","t":"儘可能使用全靜脈營養(TPN) 。"},{"k":"E","t":"避免醫源性傷害。"}],"answer":"E","expl":"多重外傷處置原則：避免 iatrogenic injury（如過度輸液、遺漏傷勢、不當藥物）；尿量減少首先要補液而非利尿劑；需要適當止痛；營養首選 enteral。所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-48","year":98,"qnum":48,"topic":"胸部","subtopic":"總論／其他","stem":"Subcutaneous emphysema may indicate which of the following?","opts":[{"k":"A","t":"Pneumothorax。"},{"k":"B","t":"Tracheal disruption。"},{"k":"C","t":"Bronchiole disruption。"},{"k":"D","t":"Phargngeal perforation。"},{"k":"E","t":"All of the above。"}],"answer":"E","expl":"皮下氣腫可由 pneumothorax、tracheobronchial disruption、esophageal／pharyngeal perforation 以及 blast／gas gangrene 造成，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-49","year":98,"qnum":49,"topic":"四肢血管骨科","subtopic":"股骨／開放性骨折","stem":"The most immediate life threat from bilateral femur fracture is?","opts":[{"k":"A","t":"fat emboli。"},{"k":"B","t":"deep vein thrombosis。"},{"k":"C","t":"hemorrhage。"},{"k":"D","t":"femoral nerve injury。"},{"k":"E","t":"osteomyelitis。"}],"answer":"C","expl":"雙側股骨骨折每側可失血約 1–1.5 L，最立即的威脅是 hemorrhagic shock，所以 (C)。Fat embolism、DVT 都是之後才發生的併發症，osteomyelitis 更晚。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"98-50","year":98,"qnum":50,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"20 歲男性頸部穿刺傷，於中線甲狀軟管高度向右一公分處有ㄧ道 1.5 公分長裂傷，傷口持續出血，有皮下氣腫及呼吸窘迫狀況，下列敘述何者為非？","opts":[{"k":"A","t":"此傷口位於頸部解剖分區的第二區(Zone II) 。"},{"k":"B","t":"皮下氣腫及呼吸窘迫狀況被視為危急的徵象(hard signs) 。"},{"k":"C","t":"在做完初級評估(primary Survey)後，需考慮氣管內插管、輸液、與直接送病患至手術室以手術探查處理病灶。"},{"k":"D","t":"需考慮血管損傷及食道傷害的可能性。"},{"k":"E","t":"安排頸動脈血管攝影是第一優先處置。"}],"answer":"E","expl":"頸部穿刺傷合併持續出血、皮下氣腫、呼吸窘迫，有 hard signs，要先處理氣道（插管）與輸液，並直接送手術室探查，不應先做頸動脈血管攝影，所以 (E) 錯。(A) 位置在 cricoid level 屬 Zone II；(D) 需考慮血管與食道傷害。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-1","year":99,"qnum":1,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列關於Blunt diaphragmatic rupture 的敘述，何者不合理?","opts":[{"k":"A","t":"較少單獨外傷傷害，最常合併 associated injury，是 hepatic 或 splenic laceration。"},{"k":"B","t":"左側的發生率較右側為高。"},{"k":"C","t":"CXR 顯示 diaphragmatic elevation 或 visceral herniation 到胸腔。"},{"k":"D","t":"皆需手術治療，行 diaphragmatic repair，在 acute phase，可由 laparotomy approach。"},{"k":"E","t":"其合併cardio-pulmonary dysfunction的發生，可能與其increased intra-abdominal pressure 有關。"}],"answer":"A","expl":"鈍性橫膈破裂：左側較常被診斷，常合併肝、脾或骨盆損傷，CXR 可見橫膈抬高或腹內臟器疝入胸腔，急性期經腹手術修補。官方答案指 (A) 為不合理。","outdated":false,"suspect":true,"flagNote":"依我所知，(A)「鈍性橫膈破裂常合併 hepatic／splenic laceration 等其他傷害」其實是合理的，看不出哪裡錯；原題可能取自書中另一種說法（例如強調 isolated 的比例），官方答案存疑，考試仍以 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"99-2","year":99,"qnum":2,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"Blunt bowel perforation 在腹部挫傷病患中，診斷相當重要；下列相關之敘述，何者有誤?","opts":[{"k":"A","t":"發生的 mechanism 通常是外力 compression，因外壓形成 closed loop，再因 high intraluminal pressure，而 blowout。"},{"k":"B","t":"在 alcohol drinking, spinal cord injury 或 head injury with conscious disturbance 的腹部挫傷病患，常會 missed diagnosis。"},{"k":"C","t":"Abdominal CT 呈現 bowel wall thickening, mesenteric hematoma 或 streaky sign，應可確定診斷。"},{"k":"D","t":"Diagnostic peritoneal lavage (DPL)，可作輔助性診斷，可發現 positive Gram stain,elevation of amylase 或 alkaline phosphatase (ALP)。"},{"k":"E","t":"Laparotomy 是 treatment of choice，開刀延遲的時間長短與其合併症或死亡率有關。"}],"answer":"C","expl":"腹部 CT 的 bowel wall thickening、mesenteric hematoma、streaky sign 只是 hollow viscus injury 的間接徵象，不能「確定診斷」，需結合臨床與 serial exam；所以 (C) 錯。(A) 為 closed loop blowout 機轉；(B) 酒精、脊髓損傷、意識障礙易漏診；(D) DPL 輔助；(E) 延遲手術會增加併發症與死亡率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-3","year":99,"qnum":3,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"對於一個您懷疑有腹部壓力症候群 (abdominal compartment syndrome)的外傷患者，以下敘述何者為正確?","opts":[{"k":"A","t":"如果腹部內壓力低於 20 mmHg，並不需要特別降壓處理。"},{"k":"B","t":"臨床的表現，例如尿流出量減少或 peak airway pressure 增加，比起實際的腹內壓力數值大小，更有意義。"},{"k":"C","t":"降低腹內壓應先以利尿劑為優先處理方法，若沒有成效才考慮剖腹降壓。"},{"k":"D","t":"剖腹降壓手術的危險性相當高，因此安排緊急降壓手術前必須先確認腹部壓力症候群的診斷，同時腹內壓高於 40 mmHg 才合宜。"},{"k":"E","t":"以上都正確。"}],"answer":"B","expl":"Abdominal compartment syndrome 的診斷與是否減壓，要看 IAP 是否合併新發器官功能障礙（少尿、peak airway pressure 上升、低 CO），單看數值不足，所以 (B)。(C) 利尿劑非首選；(D) 不需等到 40 mmHg。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-4","year":99,"qnum":4,"topic":"ICU營養併發症","subtopic":"總論／其他","stem":"嚴重外傷能引起嚴重發炎免疫之反應，而人體最早產生的發炎因子為 tumor necrosis factor (TNF)。請問 TNF 主要由以下何種細胞產生?","opts":[{"k":"A","t":"肝細胞 (hepatocytes)"},{"k":"B","t":"多核白血球 (neutrophils)"},{"k":"C","t":"巨噬細胞 (macrophages)"},{"k":"D","t":"血小板 (platelets)"},{"k":"E","t":"血管內壁細胞 (endothelial cells)"}],"answer":"C","expl":"TNF 主要由活化的 macrophages／monocytes 產生，是創傷與 sepsis 早期的 proinflammatory cytokine，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-5","year":99,"qnum":5,"topic":"頭部TBI","subtopic":"總論／其他","stem":"有關於頭部外傷的處理原則，下列敘述何者錯誤？","opts":[{"k":"A","t":"急診室的處理是依據 ATLS 的原則，應優先處理 Airway, Breathing, Circulation。"},{"k":"B","t":"作為復甦輸液時，0.9%生理食鹽水較4% Human albumin 為佳。"},{"k":"C","t":"在嚴重頭部外傷的病人，因為病人可能會有低血糖的問題，所以應該例行給予含醣的輸液做補充。"},{"k":"D","t":"在接受鎮靜劑治療之病患，需補足靜態能量消耗量(Resting metabolic expenditure)之100%。"},{"k":"E","t":"經腸道或經靜脈給予之營養製劑配方，應於受傷後七天內給予含至少15%蛋白質之熱量來源，以維持氮平衡。"}],"answer":"C","expl":"嚴重 TBI 不應例行給含糖輸液，因為 hyperglycemia 會加重腦損傷；應維持血糖正常，所以 (C) 錯。(B) SAFE trial 顯示 TBI 使用 albumin 死亡率較高，生理食鹽水較佳；(D)(E) 為營養支持原則。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-6","year":99,"qnum":6,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"小張是一位45歲板模工人，今早在工作時不慎從3樓高處跌落，被送至急診室，到院時意識清楚，生命跡象穩定，四肢動度5分且無麻痛，但有後頸部疼痛，頸部 X-ray 及 CT結果如圖，則下列何者為是？","opts":[{"k":"A","t":"此病人的 C2 fracture pattern 又稱為 Jefferson fracture。"},{"k":"B","t":"此病人的 C2 fracture pattern 又稱為 Hangman’s fracture。"},{"k":"C","t":"病人不一定需要開刀固定，也可以考慮使用 Halo vest 做外固定。"},{"k":"D","t":"病人必須使用 methylprednisolone (Solu-Medrol) 30mg/kg 持續滴注24小時。"},{"k":"E","t":"病人通常不會合併胸部挫傷的問題，如果病人沒有呼吸困難就不需要照胸部 X-ray。"}],"answer":"C","expl":"影像為 C2 骨折（可見 C2 後方 pars 區域斷裂）並使用 halo vest 外固定。穩定、無神經缺損的 C2 骨折可用 halo vest／rigid collar，不一定手術，所以官方答案 (C)。(D) 高劑量 methylprednisolone 不是必要，現行指引已不建議常規使用。","outdated":false,"suspect":true,"flagNote":"(B)「Hangman's fracture」也可能同時成立：若 C2 骨折為雙側 pars interarticularis 骨折，就是 Hangman's fracture；(A) Jefferson fracture 則是 C1 burst fracture，錯。依圖形判斷 (B) 與 (C) 都可能成立，官方答案 (C) 不變，但本題 (B) 有爭議。原官方答案維持 (C)，考試請以官方答案為準。","images":["p057-1.jpg"]},{"id":"99-7","year":99,"qnum":7,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"下列有關外傷損傷控制(Trauma damage control)之敘述何者為非？","opts":[{"k":"A","t":"最先由治療腹部外傷開始、而後擴展至其他部位的外傷治療。"},{"k":"B","t":"通常外傷病患發生低體溫、酸血症、凝血病變時，需應用損傷控制的觀念。"},{"k":"C","t":"良好的加護照顧是損傷控制成功的關鍵之一。"},{"k":"D","t":"應用損傷控制觀念治療外傷病患，需於病患情況穩定後，重返手術室再治療。"},{"k":"E","t":"應用損傷控制觀念治療時，除搶救病患生命外，相關合併症比例亦極低。"}],"answer":"E","expl":"損傷控制手術不是所有併發症都少：腹腔開放、腸瘻、感染與二次手術的併發症不低，所以 (E)「併發症比例極低」為錯。(A) 最早從腹部外傷開始；(B) 針對 lethal triad；(C)(D) 需要 ICU 復甦與計畫性再手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-8","year":99,"qnum":8,"topic":"頭部TBI","subtopic":"輕度頭部外傷 CT 適應症（Canadian CT Head Rule）","stem":"關於輕度頭部外傷的病人(GCS:13-15)，需要做頭部的電腦斷層的適應症？\na.受傷後 2 小時，沒有恢復到 GCS score15 分b.顱底骨折的任何徵候(例如腦脊髓液鼻漏、耳漏等)c.局部神經學異常d.癲癇e.嚴重顏面損傷f.藥物或酒精過量g.危險的受傷機轉","opts":[{"k":"A","t":"a、b、c、d、g"},{"k":"B","t":"a、c、d、e、f、g"},{"k":"C","t":"b、d、e、f"},{"k":"D","t":"a、b、c、d、e、f、g"},{"k":"E","t":"病人是輕度頭部外傷，故不需要做頭部電腦斷層"}],"answer":"D","expl":"Mild TBI（GCS 13–15）需要 head CT 的條件包括：受傷 2 小時後 GCS 仍 <15、skull base fracture 徵象、focal neurologic deficit、seizure、嚴重顏面損傷、藥物或酒精（無法可靠評估）、高風險機轉，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-9","year":99,"qnum":9,"topic":"腹部","subtopic":"肝臟","stem":"下列對於blunt hepatic injury 的敘述，何者較不適當?(9)","opts":[{"k":"A","t":"大部分可採取 non-operative management，其 successful rate 可達 95%以上。"},{"k":"B","t":"Abdominal CT 是相當準確的診斷工具，當它顯示有 contrast extravasation，表示一定是 arterial active bleeding, angiographic embolization 或手術是最好的治療方式。"},{"k":"C","t":"Liver abscess 是其可能的 complication，可用 CT or sono-guided percutaneous drainage 來處理。"},{"k":"D","t":"Liver biloma 發生的機會約為 3%，亦可用 percutaneous drainage 處理，若合併intra-hepatic duct stricture，可用 ERCP with stent 來引流。"},{"k":"E","t":"病患出院後，restriction of activity 是必要的；對於 high grade injury(≧3)，可能需要 3-4 個月時間才能恢復 full activity。"}],"answer":"B","expl":"CT 看到 contrast extravasation 不一定代表動脈性出血，也可能是靜脈或假性動脈瘤，不能說「一定」，處置要依血流動力學決定（angioembolization 或手術），所以 (B) 較不適當。(A) 肝損傷 NOM 成功率 >90%；(C)(D)(E) 皆為合理敘述。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-10","year":99,"qnum":10,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷會引起身體重大的新陳代謝與內分泌變化，臨床表現不包括下列何項敘述?","opts":[{"k":"A","t":"新陳代謝與內分泌的變化，與疾病嚴重度成正相關。"},{"k":"B","t":"基礎新陳代謝率大大提升，與疾病嚴重度成正相關。"},{"k":"C","t":"大量脂肪燃燒，作為主要的燃料來源。"},{"k":"D","t":"醣質新生加上胰島素抗性所導致的高血糖。"},{"k":"E","t":"蛋白質分解大於合成，呈現負氮平衡。"}],"answer":"C","expl":"創傷後代謝：catecholamine、cortisol、glucagon 升高造成 hypermetabolism、insulin resistance、gluconeogenesis 與 protein catabolism（負氮平衡）。官方答案 (C)「脂肪大量燃燒為主要燃料」被視為非創傷後的表現。","outdated":false,"suspect":true,"flagNote":"創傷與重症期間脂肪氧化其實也大幅增加（lipolysis 為重要能量來源之一），所以 (C) 並非絕對錯誤；題目偏向強調蛋白質與葡萄糖。考試仍以官方答案 (C) 為準，但請注意這是一題敘述有爭議的題目。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"99-11","year":99,"qnum":11,"topic":"顏面頸部","subtopic":"顏面骨折（LeFort、咬合）","stem":"有關顏面骨骨折(facial bone fracture)，何者正確？","opts":[{"k":"A","t":"上頷骨(maxilla)骨折是最常見之顏面骨骨折。"},{"k":"B","t":"顴骨(zygoma)骨折，一般不會有結膜下出血(subconjunctival hemorrhage)之症狀。"},{"k":"C","t":"顴骨(zygoma)骨折，一般不會造成眼眶周圍腫脹瘀青之症狀。"},{"k":"D","t":"一旦有鼻骨骨折，就要開刀治療。"},{"k":"E","t":"若病人顏面外傷後，有咬合不正(malocclusion)之症狀，需懷疑有下頷骨(mandible)骨折。"}],"answer":"E","expl":"顏面骨折後咬合不正（malocclusion）提示 mandible 或 maxilla 骨折，所以 (E)。(A) 最常見的是鼻骨骨折；(B)(C) 顴骨骨折常有眼周瘀青與 subconjunctival hemorrhage；(D) 並非所有鼻骨骨折都要手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-12","year":99,"qnum":12,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"進行外傷損傷控制(Trauma damage control)手術時，關於重返手術室的敘述何者為非？","opts":[{"k":"A","t":"一般適合重返手術室的時機約在 24-72 小時之間。"},{"k":"B","t":"病人體溫應回升至 36°C 以上再重返手術室。"},{"k":"C","t":"病人的凝血病變應已回復到 PT(prothrombin time)不超過 15 秒長。"},{"k":"D","t":"若病患發生腹部腔室壓力症候群(abdominal compartment syndrome)，須考慮早期重返手術室。"},{"k":"E","t":"若病患體溫已回升至 35°C 以上仍須持續輸血達每小時 1000CC 以上，表示凝血病變未紓緩，此時絕不可重返手術室。"}],"answer":"E","expl":"Damage control 再手術時機約為 24–72 小時，條件為體溫回升（>35–36°C）、pH 與 lactate 改善、凝血功能糾正；若仍持續大量輸血，要先繼續復甦或考慮 angioembolization，但不是「絕對不可」，所以 (E) 的絕對說法錯。(D) 若發生 ACS 要早期再開腹。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-13","year":99,"qnum":13,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重腹部外傷手術，下列那一項不是 damage control procedure？","opts":[{"k":"A","t":"將受傷的腸道切除並以 autosuture 完成 anastomosis。"},{"k":"B","t":"將斷裂的輸尿管直接作 ligation。"},{"k":"C","t":"將裂傷的脾臟直接摘除。"},{"k":"D","t":"將裂傷出血的肝臟以大紗布填塞壓迫。"},{"k":"E","t":"將裂傷的肝門靜脈直接結紮。"}],"answer":"A","expl":"Damage control 不做腸道吻合與複雜重建：(A) 腸切除加 anastomosis 不屬於 damage control；(B) 輸尿管結紮、(C) 脾切除、(D) 肝 packing、(E) portal vein ligation（在極端情況下）都可能被接受，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-14","year":99,"qnum":14,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤?","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"營養配方上，外傷病人的熱量約 25–30 kcal/kg/day，蛋白質 1.0–1.5 g/kg/day（燒傷可 >2 g/kg/day）；熱量主要來源為碳水化合物與脂肪的混合，不是 70% 脂肪，所以 (B) 錯。(E) 目前不建議 tight glycemic control（80–110 mg/dL），目標約 140–180 mg/dL。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-15","year":99,"qnum":15,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"42歲男生外傷病患主訴頸部及左手疼痛及左手食指感覺異常。臨床身體檢查發現左側三頭肌(triceps muscle)無力及肱三頭肌腱反射(triceps jerk)減少。請問病患的頸部椎間盤突出(disc herniation)位置，下列何者為是?","opts":[{"k":"A","t":"C3-C4"},{"k":"B","t":"C4-C5"},{"k":"C","t":"C5-C6"},{"k":"D","t":"C6-C7"},{"k":"E","t":"C7-T1"}],"answer":"D","expl":"C7 神經根症狀：triceps 無力、triceps reflex 減少、食指／中指感覺異常，對應 C6–C7 disc herniation，所以 (D)。（C5–C6 為 C6 root：biceps／brachioradialis reflex、拇指感覺。）","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-16","year":99,"qnum":16,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重穿刺傷病患，當必須接受 Damage control operation 時，下列那一條血管不宜直接ligate？","opts":[{"k":"A","t":"Celiac axis"},{"k":"B","t":"Common hepatic artery"},{"k":"C","t":"Portal vein"},{"k":"D","t":"Superior mesenteric artery"},{"k":"E","t":"Internal iliac artery"}],"answer":"D","expl":"同 96-15：damage control 時，SMA 結紮會造成廣泛腸缺血，應盡量修補或 temporary shunt；celiac、common hepatic、internal iliac 與 portal vein 在緊急情況可結紮，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-17","year":99,"qnum":17,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來調節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸(glutamine)是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"創傷後免疫反應一開始是 SIRS（hyperinflammatory），隨後（或同時）出現 CARS（hypoinflammatory，易感染），所以 (A) 的順序說反了。(B)(C) 為 CARS 的描述；(D) 早期 enteral feeding 有助於維持腸黏膜屏障；(E) glutamine 在創傷與燒傷的建議有時會有爭議，但此題以官方敘述為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-18","year":99,"qnum":18,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"下列何者不是ATLS 教材中列為潛在危及生命( potentially life-threatening)的胸部外傷？","opts":[{"k":"A","t":"外傷性主動脈破裂(traumatic aortic disruption)。"},{"k":"B","t":"外傷性橫膈傷害(traumatic diaphragmatic injury)。"},{"k":"C","t":"氣管支氣管傷害(tracheobronchial tree injury)。"},{"k":"D","t":"胸骨骨折(sternum fracture)。"},{"k":"E","t":"心臟鈍挫傷(blunt cardiac injury)。"}],"answer":"D","expl":"ATLS 把 aortic disruption、diaphragm injury、tracheobronchial injury、blunt cardiac injury、esophageal injury、pulmonary contusion 等列為 potentially life-threatening chest injuries；單純 sternum fracture 不在該清單，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-19","year":99,"qnum":19,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"下列有關“delayed small bowel perforation”之敘述何者為非？","opts":[{"k":"A","t":"對於此類病人之評估“Contrast-enhanced computed tomography”是必要之選擇。"},{"k":"B","t":"“Physical examination”因無法診斷出較細微病變，故不可倚賴，且常容易導致延誤診斷。"},{"k":"C","t":"“Mesentery injury”引發之腸道缺血為可能之原因。"},{"k":"D","t":"病人臨床之症狀如”absent bowel sound; increased abdominal tenderness”等為使用”CT”檢查之適應症。"},{"k":"E","t":"“delayed presentation”之時間亦可能超過一星期以上。"}],"answer":"B","expl":"Delayed small bowel perforation 的診斷需要高度警覺並 serial physical examination（腹痛增加、腸音消失等），再配合 contrast CT；理學檢查並非「不可倚賴」，反而是追蹤變化的重要依據，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-20","year":99,"qnum":20,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"75歲男性因車禍送入急診，主訴右頭頂處頭皮血腫，右側腹部大片擦傷與瘀青，到院時可與醫師對談，稍顯急躁焦慮並略有 disorientation，似乎有輕度失智現象，血壓120/80mmHg，呼吸次數25 次/分，心跳 60 次/分，有高血壓、腦梗塞及冠心症病史，不確定今天有無服藥。以下敘述，請選出正確者","opts":[{"k":"A","t":"病患生命徵象穩定，暫時無須緊急評估與處置。"},{"k":"B","t":"病患的老年性腦萎縮造成大腦周圍空間較大，腦脊髓液量也較多，其緩衝效果使得大腦比較不易挫傷。"},{"k":"C","t":"病患如果出現休克，考量其高齡與心血管疾病，輸液量應比照一般成人減量，輸液速率也應該較慢。"},{"k":"D","t":"依照 ATLS 的準則，此病患如果有肝臟損傷併發腹內出血，早期手術或侵入性治療的危險性，通常較非手術或保守性療法為高。"},{"k":"E","t":"以上皆正確。"}],"answer":"B","expl":"官方答案 (B) 的推論是老年腦萎縮使腦與顱骨間隙變大，有緩衝效果。","outdated":false,"suspect":true,"flagNote":"此說法與臨床相反：腦萎縮使 bridging veins 被拉長，老年人反而較易發生 subdural hematoma，且症狀常延遲出現；其他選項（A 生命徵象穩定不需處置、C 輸液減量、D 手術風險較高）也都不正確，所以 (B) 可能是相對最佳，但敘述本身有疑義。考試以官方 (B) 為準。補充：病人 HR 60 可能因服用 beta-blocker，而 RR 25 與意識改變提示並不穩定。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"99-21","year":99,"qnum":21,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"有關懷孕的外傷病患的評估診察準則上的建議，下列何者有誤？","opts":[{"k":"A","t":"創傷初期，對胎兒最好的治療，是對母體作適當的 resuscitation 與對胎兒作early assessment。"},{"k":"B","t":"所有懷孕廿週以上的婦女，在受到較嚴重的創傷之後，都應該接受至少六小時的胎心音監測(Cardiotocographic monitoring)。"},{"k":"C","t":"考量輻射線的可能副作用，應先考慮無輻射性的影像檢查工具，因此，無論對母體是否必要，對懷孕婦女絕不考量有游離放射線的診斷工具以免傷及胎兒。"},{"k":"D","t":"懷孕婦女最好左側躺約 15 度，以避免子宮壓迫下腔靜脈而導致平躺低血壓症候群(Supine hypotension syndrome)。"},{"k":"E","t":"母體血管內容積(Intravascular volume)因外傷突然減少時，即使母體的生命跡象穩定，也可能使胎兒因子宮的血管阻抗(Vasculature resistance)增加而發生缺氧。"}],"answer":"C","expl":"孕婦外傷時若有診斷需求，不應因懷孕而完全拒絕 X-ray 或 CT；有需要時母親優先，必要影像仍應進行，所以 (C)「絕不考慮」為錯。(B) 20 週以上需要至少 4–6 小時 CTG；(D) 左側傾斜 15°；(E) 母體血管收縮使子宮血流下降，胎兒可能先缺氧。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-22","year":99,"qnum":22,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有關Emergency Department thoracotomy (ED thoracotomy)之敘述何者為非?","opts":[{"k":"A","t":"penetrating chest trauma 之病人，雖然於到院前 CPCR 過，仍需仔細評估生命跡象。"},{"k":"B","t":"於 penetrating chest trauma 之病人, 若仔細評估生命跡象後, 仍無血壓, 則不需更進一步急救。."},{"k":"C","t":"ED thoracotomy for patients with blunt trauma, CPR > 5 minutes, arrived asystole is often ineffective."},{"k":"D","t":"ED thoracotomy for patients with penetrating trauma, CPR >15 minutes and no sign of life is often ineffective."},{"k":"E","t":"ED thoracotomy for patients with witnesses penetrating trauma, CPR< 5 minutes is indicated."}],"answer":"B","expl":"穿刺性胸傷在仔細評估後有 signs of life 時，仍可 ED thoracotomy；若已確認無 signs of life 且 CPR 時間過長，才不需進一步急救，但單說「沒血壓就不需更進一步急救」不正確，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-23","year":99,"qnum":23,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"以下測量abdominal intra-abdominal Pressure 的方法何者最常使用?","opts":[{"k":"A","t":"測 Stomach pressure"},{"k":"B","t":"測 inf. vena cava pressure"},{"k":"C","t":"測 Urinary Bladder pressure"},{"k":"D","t":"測 central venous pressure，再以公式換算"},{"k":"E","t":"測 portal venous flow，再以公式換算"}],"answer":"C","expl":"IAP 最常用的測量方法是 intravesical（bladder）pressure：以 Foley 注入 25 mL 生理食鹽水後測量，是 WSACS 建議的標準方式，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-24","year":99,"qnum":24,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"有關嚴重胸腹外傷病患之急救處理，請選出正確敘述？","opts":[{"k":"A","t":"所有傷患均應該使用“Damage Resuscitation”，且無例外。"},{"k":"B","t":"輸液仍以“crystalloid”為最佳選擇。"},{"k":"C","t":"“Permissive hypotension”觀念可應用於重度創傷的復甦急救。"},{"k":"D","t":"“Damage Resuscitation”之觀念僅適用胸腹外傷領域。"},{"k":"E","t":"手術方式之選擇不必考慮病人之生理狀況。"}],"answer":"C","expl":"同 98-12：damage control resuscitation 的概念是 permissive hypotension、早期 balanced blood products、限制晶體液，所以 (C)。例外為 TBI 與 SCI，需要維持較高 MAP/CPP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-25","year":99,"qnum":25,"topic":"腹部","subtopic":"脾臟","stem":"有關“Splenic artery embolization”用於脾臟創傷治療之敘述，請選出錯誤者？","opts":[{"k":"A","t":"Splenic artery embolization”可適用於老年人。"},{"k":"B","t":"“CT scan” 發現“contrast extravasation”為採用“Splenic artery embolization”重要考慮因素。"},{"k":"C","t":"“Splenic artery embolization”後，無法保留脾臟之免疫功能。"},{"k":"D","t":"不當採用“Splenic artery embolization”會增加病人死亡率。"},{"k":"E","t":"“Splenic artery embolization”可用於“high grade”脾創傷。"}],"answer":"C","expl":"脾動脈栓塞（SAE）可保留脾臟功能（特別是 distal／selective embolization），所以 (C)「無法保留免疫功能」為錯。(A)(B)(D)(E) 為 SAE 的標準觀念：老年人、CT blush、high-grade 脾傷皆為適應症；不當使用會增加併發症與死亡率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-26","year":99,"qnum":26,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"張力性氣胸(tension pneumothorax)造成外傷患者血液循環與呼吸功能急速下降(cardiopulmonary decompensation)的機轉，與下列何者比較無關?","opts":[{"k":"A","t":"減少靜脈回流 (venous return)。"},{"k":"B","t":"降低心臟輸出血量 (cardiac output)。"},{"k":"C","t":"交感神經功能亢進 (increased sympathetic tone)。"},{"k":"D","t":"降低血氧濃度(oxygen saturation)。"},{"k":"E","t":"以上皆有關。"}],"answer":"C","expl":"Tension pneumothorax 造成 decompensation 的機轉：縱隔移位、venous return 減少、cardiac output 下降、低血氧；交感神經亢進是代償反應，不是造成 decompensation 的機轉，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-27","year":99,"qnum":27,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"下列有關頭部創傷及處置的敘述中，何者最不正確?","opts":[{"k":"A","t":"老人較容易有腦膜部位出血，而小孩以腦組織挫傷較易見。"},{"k":"B","t":"為了降低腦壓(ICP)，可以考慮將外傷患者的上半身提高 30 度。"},{"k":"C","t":"多部位外傷患者合併嚴重腦部外傷不宜考慮使用低血壓急救 (hypotensive resuscitation)。"},{"k":"D","t":"嚴重腦部外傷患者到達急診時血壓為 170/100 mmHg，患者應趕緊接受藥物降壓以避免腦部的二度傷害。"},{"k":"E","t":"大量輸液對於嚴重頭部外傷患者所造成的可能傷害，遠低於輸液不足所造成的傷害。"}],"answer":"D","expl":"嚴重 TBI 到院時 BP 170/100 常是為了維持 CPP 的代償反應（如 Cushing response），不應急著降壓，所以 (D) 最不正確。(B) 床頭抬高 30°；(C) TBI 合併多處外傷不宜 hypotensive resuscitation；(E) 低血壓與缺氧對 TBI 傷害大。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-28","year":99,"qnum":28,"topic":"小兒","subtopic":"總論／其他","stem":"有關小兒外傷，以下何者有誤?","opts":[{"k":"A","t":"小兒由於很少合併有既存的肺部疾病，因此如果 room air 就可以達成氧氣飽和度(Oxygen saturation)在 90％以上，即表示其肺功能大致正常。"},{"k":"B","t":"小兒在 intubation 之後，最好能放置 Nasogastric 或 Orogastric tube 作胃部減壓(Gastric decompression)，以免影響橫膈膜運動範圍。"},{"k":"C","t":"無法於周邊建立靜脈途徑，兩側小腿也不適合作骨內注射時，第一優先考量為 Venous cut-down。"},{"k":"D","t":"骨內針(Intraosseous needle)同一部位的多次穿刺，可能造成輸液的漏失進而引發腔室症候群(Compartment syndrome)"},{"k":"E","t":"在張力性氣胸(Tension pneumothorax)，以針頭減壓之後，仍然應該立即插入胸管。"}],"answer":"C","expl":"兒童無法建立周邊 IV 時，應先考慮 IO（脛骨近端，若不行再選股骨遠端或肱骨），不是 venous cutdown 優先，所以 (C) 錯。(D) 同一部位反覆穿刺會漏液並導致 compartment syndrome；(E) 針頭減壓後仍需放胸管。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-29","year":99,"qnum":29,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"對於損害控制手術(Damage control surgery)應用於胸部創傷時，下列敘述何者為誤？","opts":[{"k":"A","t":"與腹部損害控制手術相同，皆以快速止血為優先。"},{"k":"B","t":"盡可能避免大範圍的肺部切除。"},{"k":"C","t":"病人常須接受二次探查手術(Second look procedure)。"},{"k":"D","t":"若遇困難止血時，可將肺門扭轉以減少出血。"},{"k":"E","t":"閉胸時胸壁肌肉建議以縫線縫合，以避免持續出血。"}],"answer":"C","expl":"Thoracic damage control：以快速止血為先，盡量避免大範圍肺切除，可用 pulmonary tractotomy、hilar twist（肺門扭轉）與暫時性關胸，閉胸時可縫合胸壁肌肉。官方答案指 (C)「常須二次探查」為誤。","outdated":false,"suspect":true,"flagNote":"文獻中 thoracic damage control 多為暫時關胸（temporary chest closure）後再計畫性 re-exploration，所以 (C) 其實看起來是合理描述，答案可能存疑。考試仍以官方 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"99-30","year":99,"qnum":30,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"頭部外傷病人昏迷指數 8 分，經身體檢查有：左瞳孔 4mm、無光反應，右瞳孔 2mm，呼吸已氣管插管、腹部脹，血壓 80/40mmHg、脈搏 120 次/分，腹部超音波檢查有脾臟部位積液，腦部電腦斷層檢查有左側硬腦膜下血腫，中線明顯位移，此病人治療：","opts":[{"k":"A","t":"繼續輸血輸液觀察病情變化。"},{"k":"B","t":"先施開顱術後，再施腹部手術。"},{"k":"C","t":"先施腹部手術後，再施開顱術。"},{"k":"D","t":"先施動脈血管栓塞後，再施開顱術。"},{"k":"E","t":"開顱術與腹部手術同時聯合手術。"}],"answer":"E","expl":"GCS 8 合併瞳孔散大、中線位移的 SDH，同時有脾出血與休克，兩者都需要立即手術，不能等一個做完再做另一個，所以官方答案為 (E) 兩組外科醫師同時手術（simultaneous craniotomy and laparotomy）。若只能先一個，通常先處理致命的腹內出血控制，但此題官方答案以聯合手術為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-31","year":99,"qnum":31,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"背部穿刺外傷病人於急診檢查，有右側下肢運動肌力消失，有痛覺、溫覺，左側下肢有運動能力，傷處皮節兩節下部痛覺溫覺消失，此病人為：","opts":[{"k":"A","t":"左側脊髓損傷。"},{"k":"B","t":"右側脊髓損傷。"},{"k":"C","t":"前側脊髓動脈損傷。"},{"k":"D","t":"後側脊髓損傷。"},{"k":"E","t":"以上皆非。"}],"answer":"B","expl":"右側運動消失、左側痛溫覺在傷處兩節以下消失，是 Brown-Séquard syndrome：同側運動與本體感覺喪失，對側痛溫覺喪失，因此病灶在右側脊髓（hemisection），所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-32","year":99,"qnum":32,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"一位30 歲男性摩托車騎士不幸與小轎車對撞後送至急診室。EMT 說病人未戴安全帽，他的昏迷指數G.C.S.是 8，血壓：160/90 ㎜ Hg，心跳 60/min，呼吸: 12/min。立刻緊急安排頭部電腦斷層，於送電腦斷層室前應優先：","opts":[{"k":"A","t":"應優先給予 mannitol (1 g/kg)。"},{"k":"B","t":"應優先照 portable CXR。"},{"k":"C","t":"應優先照 lateral C-spine X ray。"},{"k":"D","t":"應優先做腹部 sonography。"},{"k":"E","t":"應優先建立確切呼吸道 (definitive airway)。"}],"answer":"E","expl":"GCS 8、高血壓與心搏過緩、呼吸慢，符合 Cushing response／ICP 升高；送 CT 前必須先確保 definitive airway（插管），所以 (E)。Mannitol、X-ray 都在氣道之後。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-33","year":99,"qnum":33,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"影響胎兒預後最重要因素為:","opts":[{"k":"A","t":"胎兒成熟度 (maturity)。"},{"k":"B","t":"胎兒'心跳是否有 beat-to-beat variability。"},{"k":"C","t":"孕婦是否有 vaginal bleeding。"},{"k":"D","t":"孕婦是否為 stable hemodynamic status。"},{"k":"E","t":"孕婦是否為 RH 陰性。"}],"answer":"D","expl":"孕婦外傷時，對胎兒預後最重要的是母親的 hemodynamic stability 與 resuscitation 是否成功（母親存活與灌流是胎兒最佳急救），所以 (D)。胎兒成熟度、Rh 狀態與 vaginal bleeding 都是次要因素。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-34","year":99,"qnum":34,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一位20 歲年輕人，因故遭不良少年圍毆，被小刀刺中左前胸，30 分鍾後送至急診室。發現血壓70/30 ㎜ Hg，心跳 140/min，於左乳頭下有一穿刺傷，長約 2公分，兩側呼吸聲正常，但心音聽不清楚，同時頸靜脈鼓漲。此時最適當的處置應該是：","opts":[{"k":"A","t":"立刻做 CT of chest。"},{"k":"B","t":"立刻照 portable CXR。"},{"k":"C","t":"立刻左胸緊急插入胸管。"},{"k":"D","t":"立刻做 endotracheal tube intubation。"},{"k":"E","t":"立刻做緊急開胸術 (emergency thoracotomy)。"}],"answer":"E","expl":"左前胸穿刺傷、低血壓、心音遙遠、頸靜脈鼓脹，為 Beck's triad，診斷 cardiac tamponade，需要緊急手術處理，所以官方答案 (E) emergency thoracotomy。重點是不要先做 CT、X-ray 或 chest tube 延誤治療；pericardiocentesis 只是暫時措施。補充：若病人尚穩定且有手術室，可考慮 subxiphoid pericardial window 或胸骨切開。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-35","year":99,"qnum":35,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"造成頭部外傷腦死最主要的原因？","opts":[{"k":"A","t":"血管痙攣(Vasospasm)。"},{"k":"B","t":"顱內壓升高(IICP)。"},{"k":"C","t":"缺血(Ischemia)。"},{"k":"D","t":"腦水腫(Brian edema)。"},{"k":"E","t":"休克。"}],"answer":"C","expl":"頭部外傷造成腦死的最終機轉是顱內壓升高導致 cerebral perfusion 下降，引起全腦缺血與壞死，題目以 (C) ischemia 為最主要。其他如腦水腫、血管痙攣、休克都會促成缺血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-36","year":99,"qnum":36,"topic":"頭部TBI","subtopic":"總論／其他","stem":"36 歲男性病人，車禍送至急診處，呼吸速率: 16/min，心博速: 120/min，血壓: 90/68 mmHg，SaO2: 98%，昏迷指數 = E1M4V1，瞳孔等徑:3 mm/3 mm(左大於右)，頭皮十公分撕裂傷，請問下列處置何者最不適當？","opts":[{"k":"A","t":"插管：建立安全呼吸道。"},{"k":"B","t":"給氧氣。"},{"k":"C","t":"建立二條靜脈路徑。"},{"k":"D","t":"先做頭部電腦斷層，排除顱內出血，再做腹部超音波。"},{"k":"E","t":"給予 2000 c.c.生理食鹽水點滴注射。"}],"answer":"D","expl":"GCS 6（E1M4V1）合併低血壓（BP 90/68、HR 120）的病人，TBI 不是休克原因，要先找 extracranial bleeding；因此應先做 FAST/ABCs 與復甦，而不是先送 CT 再做腹部超音波，所以 (D)。","outdated":true,"suspect":false,"flagNote":"選項 (E)「給予 2000 c.c. 生理食鹽水」被視為合理，在今日已過時：ATLS 10/11 建議初始晶體液上限約 1 L 並盡早 blood products；TBI 需避免 hypotension 也避免 hypotonic 溶液。官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"99-37","year":99,"qnum":37,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"一位76 歲老先生，不幸由二層樓高處墜落後送至急診室，有關老年外傷敘述最不適當的是:","opts":[{"k":"A","t":"治療優先順序與一般相同。"},{"k":"B","t":"隨著年齡增加生理功能降低。"},{"k":"C","t":"預後與罹患之慢性病無關。"},{"k":"D","t":"頸部外傷可能性增加。"},{"k":"E","t":"頭部外傷可能性增加。"}],"answer":"C","expl":"老年外傷的預後與共病、用藥密切相關，所以 (C)「與慢性病無關」為錯。(D)(E) 老人頸椎與頭部受傷機率增加，(A)(B) 為 ATLS 老年外傷原則。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-38","year":99,"qnum":38,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"一位30 歲男性機車騎士，不幸發生車禍後被送至急診室，發現病人神智不清且四肢癱瘓，此時病人需確切維持呼吸道，但發現這是一個氣管插管困難(Difficult intubation)的病人，此時最佳處理方法為","opts":[{"k":"A","t":"做氣管切開術(tracheostomy)。"},{"k":"B","t":"做環甲狀軟骨間膜切開術(cricothyroidotomy)。"},{"k":"C","t":"於支氣管鏡指引下做插氣管內管插管(bronchoscopy-guided endotracheal tube intubation)。"},{"k":"D","t":"給予鼻咽呼吸道(nasophargngeal airway)。"},{"k":"E","t":"給予口咽呼吸道(orophargngeal airway)。"}],"answer":"C","expl":"同 95-52：昏迷合併四肢癱瘓的 difficult airway，在能維持通氣時，最合理是 fiberoptic bronchoscope-guided intubation，並保持 in-line cervical stabilization；若 can't intubate can't oxygenate 才轉 cricothyroidotomy。補充：video laryngoscope 為現今常用工具。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-39","year":99,"qnum":39,"topic":"胸部","subtopic":"Tracheobronchial injury","stem":"關於Tracheobronchial injury 敘述下列何者為非?","opts":[{"k":"A","t":"當我們懷疑有 Tracheobronchial injury 時應儘速安排 bronchoscopy 檢查。"},{"k":"B","t":"“Falling lung sign”代表小支氣管完全斷裂。"},{"k":"C","t":"臨床症狀常見有皮下氣腫及縱膈腔氣腫存在。"},{"k":"D","t":"當氣管受傷範圍小於 1/3 圈時可以考慮使用非手術性治療。"},{"k":"E","t":"以上皆正確。"}],"answer":"B","expl":"Falling lung sign 代表主支氣管（main bronchus）完全斷裂，肺因失去支持下墜於胸腔外側，不是「小支氣管」，所以 (B) 錯。(A) 確診用 bronchoscopy；(C) 常見皮下與縱隔氣腫；(D) 氣管損傷 <1/3 周且無嚴重症狀可考慮保守治療。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-40","year":99,"qnum":40,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"架構身體lean body mass、主要免疫組成及傷口癒合的營養素為下列何者：","opts":[{"k":"A","t":"醣類"},{"k":"B","t":"脂肪"},{"k":"C","t":"蛋白質"},{"k":"D","t":"維生素"},{"k":"E","t":"礦物質"}],"answer":"C","expl":"蛋白質是 lean body mass、免疫蛋白（抗體、補體、細胞）與 collagen／傷口癒合的主要材料，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-41","year":99,"qnum":41,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"四歲男童過馬路時，遭到時速 50 公里的汽車撞擊，彈離車子 5 公尺遠；送至急診室時，抱怨腹部疼痛，身體理學檢查發現血壓 68/40 mmHg、心跳每分鐘 200 次、腹部緊繃合併觸痛(firm and tender)，病人體重約 20 公斤，其收縮壓持續低於 90 mmHg，下列何項為最適當的輸液方式？","opts":[{"k":"A","t":"先輸注 400 cc 溫的等張晶體溶液，血壓持續偏低，就須輸 200 cc 的紅血球濃厚液(packed RBC)。"},{"k":"B","t":"先輸注 400 cc 溫的等張晶體溶液，血壓持續偏低，就須輸 400 cc 的紅血球濃厚液。"},{"k":"C","t":"先輸注 200 cc 溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸 200 cc 的紅血球濃厚液。"},{"k":"D","t":"先輸注 400 cc 溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸 200 cc 的紅血球濃厚液。"},{"k":"E","t":"先輸注 400 cc 溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸 400 cc 的紅血球濃厚液。"}],"answer":"D","expl":"兒童出血性休克，起始 bolus 為 20 mL/kg warmed isotonic crystalloid（20 kg 為 400 mL），反應不佳再給 10 mL/kg pRBC（200 mL）。依官方答案，可再重複輸注晶體液兩次後輸 pRBC，所以 (D)。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議：初始 20 mL/kg 晶體液最多一次，若仍不穩定就盡快給 10 mL/kg pRBC，不再多次重複晶體液（避免 dilutional coagulopathy 與水腫）。官方答案 (D) 不變，但實際臨床請改依 ATLS 10/11。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"99-42","year":99,"qnum":42,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"25 歲懷孕32 週女性，配戴安全帶駕駛小客車，被時速 25 公里的公車從後追撞，安全氣囊爆開，車身沒有明顯損害，病人無神智喪失(loss of consciousness)，病人在車禍現場可以走動，只有抱怨頸部疼痛；接著病人戴上頸圈，躺在長背板上，由救護車送至急診室，身體理學檢查發現第五、六頸椎壓痛，下列敘述何者正確？","opts":[{"k":"A","t":"產婦配戴安全帶駕駛發生車禍，發生早產的機會比未配戴安全帶者高。"},{"k":"B","t":"病人接受基本外傷評估、確認胎兒心音及活動正常後，就可以安全離院。"},{"k":"C","t":"病人不宜接受頸部 X-Ray 檢查，以防放射線可能造成胎兒畸形。"},{"k":"D","t":"病人不應繼續躺在長背板上，應該改躺在一般的病床以改善胎兒循環。"},{"k":"E","t":"病人接受外傷評估後，仍須接受胎兒心音監視 6 小時以上，才可以離院。"}],"answer":"E","expl":"孕 20 週以上、被追撞後需要持續胎心音監測（CTG）；官方答案為至少 6 小時，所以 (E)。(A) 配戴安全帶可降低早產與胎兒死亡；(B) 不能僅憑胎心音正常就離院；(C) 需要的 X-ray 不應因懷孕而拒絕；(D) 頸椎壓痛仍需保持固定，可用 left lateral tilt。補充：ATLS 10 建議至少 4 小時，出現宮縮、陰道出血、腹痛或母體不穩時延長至 24 小時。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-43","year":99,"qnum":43,"topic":"總論評分","subtopic":"Trimodal death distribution／到院前死亡高峰","stem":"根據Trimodal Death Distribution，下列何者不屬於 early death(preventable death)之外傷病患?","opts":[{"k":"A","t":"Cardiac tamponade."},{"k":"B","t":"Blunt splenic laceration grade IV with bleeding."},{"k":"C","t":"Aortic rupture."},{"k":"D","t":"Right 2nd-7th rib fracture with hemothorax."},{"k":"E","t":"Left temporal epidural hematoma."}],"answer":"C","expl":"Trimodal death distribution：第一峰（秒到分鐘，現場死亡）多為 aortic rupture、brain stem 與 heart injury，難以預防；第二峰（數小時，golden hour）才是可預防，如 tamponade、spleen、hemothorax、EDH。故 aortic rupture 不屬於 early preventable death，答案 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-44","year":99,"qnum":44,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕28 週女性因高速車禍撞擊受傷，被送至一級創傷中心急救，3 分鐘後婦女忽然量不到脈搏(pulseless)，下列敘述何者正確？","opts":[{"k":"A","t":"產婦發生車禍，胎兒的存活率不高，急救重點應該放在產婦上。"},{"k":"B","t":"若急救復甦無效，應該在產婦心臟停止五分鐘內進行緊急剖腹產。"},{"k":"C","t":"必須先證實胎兒還有心跳，再進行緊急剖腹產，以確保胎兒存活。"},{"k":"D","t":"進行緊急剖腹產時，應該使用水平子宮切口以利取出胎兒。"},{"k":"E","t":"緊急剖腹產未完成前，產婦不宜使用升壓劑，以免造成胎兒循環不足。"}],"answer":"B","expl":"孕 ≥20 週產婦心跳停止，若 CPR 無效，應在 4–5 分鐘內進行 perimortem cesarean（resuscitative hysterotomy），以改善母親 venous return 與胎兒存活，所以 (B)。(C) 不必先確認胎心；(D) 應用 vertical midline incision；(E) 不禁止 vasopressor。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-45","year":99,"qnum":45,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"胸部外傷處理部分敘述，以下何者為非?","opts":[{"k":"A","t":"Tracheobronchial injury 因有傷及 Airway，故在 primary survey 就需處理。"},{"k":"B","t":"施行 Needle decompression for tension pneumothorax 的位置，通常在鎖骨中線下第二肋間處。簡單找法為沿鎖骨中線往下約 1 至 2 個指幅之肋骨上緣，便為下針處。"},{"k":"C","t":"Subcutaneous emphysema 本身症狀是不會造成生命危險，但當出現時，仍要積極尋找潛藏原因並盡量避免正壓呼吸。"},{"k":"D","t":"Traumatic asphyxia 病人臉部出現 cyanosis 的程度不影響急救方式與積極態度。"},{"k":"E","t":"肋骨骨折常見於胸部外傷，處理上除了須注意骨折部位與其相關位置器官亦可能受傷外，積極的給於止痛是關鍵。"}],"answer":"A","expl":"Tracheobronchial injury 在 ATLS 是 potentially life-threatening injury，屬 secondary survey 發現與處理；只有 airway obstruction 與 tension pneumothorax 才在 primary survey，所以 (A) 為非。","outdated":true,"suspect":false,"flagNote":"選項 (B)「needle decompression 在鎖骨中線第二肋間」是舊 ATLS：ATLS 10 起成人建議 5th intercostal space、略前於 mid-axillary line（2nd ICS MCL 為替代位置），因為胸壁較薄、較不易傷及大血管。官方答案 (A) 不變。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"99-46","year":99,"qnum":46,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"下列何者與外傷病患的醫療品質改善無關?","opts":[{"k":"A","t":"外傷病患的死亡率。"},{"k":"B","t":"外傷病患的住院率。"},{"k":"C","t":"外傷病患的生活品質。"},{"k":"D","t":"外傷病患的併發症發生率。"},{"k":"E","t":"以上皆是相關"}],"answer":"B","expl":"創傷品質改善指標包含死亡率、併發症率、功能與生活品質；住院率本身不能代表醫療品質，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-47","year":99,"qnum":47,"topic":"腹部","subtopic":"肝臟","stem":"Which of the following descriptions is about class IV liver injury?","opts":[{"k":"A","t":"Hepatic avulsion"},{"k":"B","t":"Parenchymal disruption involving > 75% of hepatic lobe"},{"k":"C","t":"Parenchymal disruption involving 25 to 75% of hepatic lobes"},{"k":"D","t":"Juxtahepatic venous injuries (IVC/central major hepatic veins)."},{"k":"E","t":"Subcapsular hematoma> 50% of liver surface."}],"answer":"C","expl":"AAST 肝損傷分級：I–II 為 subcapsular hematoma 與淺撕裂傷；III 為深度 >3 cm 的撕裂傷、hematoma >50%；IV 為 parenchymal disruption involving 25–75% of hepatic lobe；V 為 >75% 或 juxtahepatic venous injuries；VI 為 hepatic avulsion。故 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-48","year":99,"qnum":48,"topic":"ICU營養併發症","subtopic":"疼痛控制","stem":"疼痛的控制是外傷照護的重要一環，下列相關敘述何者錯誤?","opts":[{"k":"A","t":"疼痛的控制有助於緩解外傷引起的壓力反應，也是一品質照護的重要指標。"},{"k":"B","t":"一些非藥物的處置(nonpharmacologic intervention)，如骨折固定、傷口包紮、適當的患者擺位等，亦都有助於疼痛的緩解。"},{"k":"C","t":"在胸腔外傷患者，亦建議以硬脊膜外止痛或肋膜腔內止痛等方式進行疼痛控制，這有助於減少全身性給予嗎啡類藥物的副作用。"},{"k":"D","t":"嗎啡類藥物為嚴重疼痛的標準用藥。在腎功能不佳的情況下，首選者為 morphine。"},{"k":"E","t":"嗎啡類藥物為嚴重疼痛的標準用藥。在血壓不穩的情況下，首選者為 fentanyl。"}],"answer":"D","expl":"腎功能不佳時，morphine 的活性代謝物（M6G）會蓄積，造成鎮靜與呼吸抑制，不宜作為首選，所以 (D) 錯；可改用 fentanyl 或 hydromorphone。(E) 血壓不穩時 fentanyl 對血流動力學影響較小，是較好的選擇。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-49","year":99,"qnum":49,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"有關同意書，下列敘述何者錯誤?","opts":[{"k":"A","t":"病人若病情危急，而病人之配偶、親屬或關係人不在場，亦無法取得病人本身之同意，為搶救病人性命，依醫療法規定，應先為病人進行必要之處理，不須簽署同意書。"},{"k":"B","t":"病人若病情危急，而病人之配偶、親屬或關係人不在場，亦無法取得病人本身之同意，醫師應將須為必要處理之原因及無法取得同意之理由註明於病歷，並依據醫學學理為病人進行必要之處理。"},{"k":"C","t":"承(A)，若手術中病人之配偶、親屬或關係人已趕到，則應由其補簽同意書。"},{"k":"D","t":"常規手術進行時，如發現建議手術項目或範圍有所變更，而病人尚在麻醉中，須待其退麻醉並完全清醒之後，予以告知並獲其同意。"},{"k":"E","t":"緊急手術進行時，如發現建議手術項目或範圍有所變更，應由病人之法定或指定代理人、配偶、親屬或關係人代為同意。"}],"answer":"C","expl":"緊急情況且無家屬在場時，依醫療法規定可先進行必要處置，不必先簽同意書；事後也不一定要求家屬補簽，所以 (C)「應補簽」為錯。(B) 醫師要在病歷記載原因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"99-50","year":99,"qnum":50,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"一位45 歲中年男性於黑美人酒家，因故遭人痛毆，20 分鍾後由友人送至急診室。發現右側胸部肋骨骨折(rib fracture)合併連枷胸(flail chest)、兩側呼吸聲仍可聽到，但血中氧氣分壓偏低，最佳的解釋是：","opts":[{"k":"A","t":"因肺挫傷 (Pulmonary contusion) 。"},{"k":"B","t":"因肋骨骨折剌穿肺部。"},{"k":"C","t":"因呼入性肺炎 (Aspiration pneumonia) 。"},{"k":"D","t":"因縱隔腔左右搖擺 (mediastinal shift) 。"},{"k":"E","t":"因胸部反常規起伏 (paradoxical movement) 。"}],"answer":"D","expl":"官方答案 (D) 認為 flail chest 低血氧是因 mediastinal shift（縱隔搖擺）。","outdated":true,"suspect":true,"flagNote":"ATLS 與現行觀念認為 flail chest 的低血氧主因是疼痛造成換氣不足與底下的 pulmonary contusion，不是 paradoxical movement 或 mediastinal shift（100-13 (A) 也這麼敘述）。因此 (A) 肺挫傷才是最合理的解釋，官方答案 (D) 有疑義且概念過時。考試仍依官方 (D)，臨床請記 pulmonary contusion。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"100-1","year":100,"qnum":1,"topic":"DCS_ACS","subtopic":"總論／其他","stem":"1993 年首先倡導對外傷病患施以「簡易手術」(abbreviated operation)以避免致命性三徵象(triad)達到損害控制者為：","opts":[{"k":"A","t":"Loveland JA。"},{"k":"B","t":"Rotondo MF。"},{"k":"C","t":"Shapiro M。"},{"k":"D","t":"Kouraklis G。"},{"k":"E","t":"Beekley A。"}],"answer":"B","expl":"1993 年 Rotondo MF 與 Schwab 等在 J Trauma 發表 \"damage control: an approach for improved survival in exsanguinating penetrating abdominal injury\"，首次提出 abbreviated laparotomy 以避開 hypothermia、acidosis、coagulopathy 的致命三徵象，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-2","year":100,"qnum":2,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"有關外傷之「損傷控制 damage control」敘述，何者為非？","opts":[{"k":"A","t":"主要三步驟(triology)依序為：簡易性手術，加護中心急救，確定性手術。"},{"k":"B","t":"確定性手術最常於簡易性手術實施 24-36 小時後進行。"},{"k":"C","t":"簡易性手術主要是在最短時間內止血，其次為腸道接合或造口處理。"},{"k":"D","t":"確定性手術包括血管修補或置換術、止血棉墊移除及腹部肌膜閉合等。"},{"k":"E","t":"於加護中心急救時，須儘快矯正低體溫、凝血機能不全及酸血症。"}],"answer":"C","expl":"Damage control 三階段：(1) abbreviated laparotomy（止血、控制污染、暫時關腹），(2) ICU 復甦（保暖、矯正酸中毒與凝血功能），(3) 24–72 小時後 definitive surgery。第一階段優先是止血與控制腸道污染，腸道吻合與造口屬確定性手術，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-3","year":100,"qnum":3,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"外傷病患所作「損傷控制」之相關急救敘述，何者為非？","opts":[{"k":"A","t":"急救措施一般是在損傷控制手術之前或之間為之。"},{"k":"B","t":"當面對無法控制之出血點時，可允許「適度」之低血壓狀況以減少出血量。"},{"k":"C","t":"幫病人升溫，以避免體溫下降所造成之凝血病變。"},{"k":"D","t":"需積極矯正病患之酸中毒。"},{"k":"E","t":"緊急輸液是以新鮮冷凍血漿：分離紅血球：血小板三者 1：2：1 之比例給予。"}],"answer":"E","expl":"Damage control resuscitation 包含適度低血壓（permissive hypotension）、保暖、矯正酸中毒；輸血以 balanced ratio 為原則。選項 (E)「FFP：RBC：platelet = 1：2：1」不是標準比例，所以 (E) 錯。","outdated":true,"suspect":false,"flagNote":"現行比例為 1:1:1（PROPPR 2015）或 1:1:2 以上的血漿／血小板比 RBC，且盡早 TXA。舊式 1:2:1 或 1:4 已過時。官方答案 (E) 與現行一致。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"100-4","year":100,"qnum":4,"topic":"休克輸血","subtopic":"總論／其他","stem":"外傷病患在手術室內之體溫若低於 35℃時，其死亡風險較體溫高於 35℃者多出：","opts":[{"k":"A","t":"3 倍。"},{"k":"B","t":"7 倍。"},{"k":"C","t":"10 倍。"},{"k":"D","t":"25 倍。"},{"k":"E","t":"41 倍。"}],"answer":"E","expl":"資料型題目：創傷病人術中 core temp <35°C，死亡風險明顯提高（與 hypothermia、coagulopathy、acidosis 的 lethal triad 有關），官方選項為 41 倍，所以 (E)。注意這是文獻統計數字，臨床不需背數字，但要記住 hypothermia 是獨立的死亡風險因子。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-5","year":100,"qnum":5,"topic":"頭部TBI","subtopic":"總論／其他","stem":"有關單純頭部槍傷，下列何者不是預後不佳的指標？","opts":[{"k":"A","t":"PT (Prothrombin Time)異常。"},{"k":"B","t":"休克。"},{"k":"C","t":"抵達急診之 GCS (Glascow Coma Scale) 。"},{"k":"D","t":"兩側大腦貫穿。"},{"k":"E","t":"呼吸每分鐘 5 次。"}],"answer":"C","expl":"頭部槍傷預後不佳的指標包括：抵達時低 GCS、兩側大腦貫穿（bihemispheric、transventricular）、休克、凝血異常、呼吸異常、瞳孔散大且固定、年齡大。官方答案指 (C) 不是預後指標。","outdated":false,"suspect":true,"flagNote":"多數研究顯示抵達急診時的 GCS 是最重要的預測因子之一（GCS 3–5 預後極差），因此 (C) 當作「不是預後不佳指標」與文獻不符，答案可能是 OCR 或原題有誤。考試仍以官方答案 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"100-6","year":100,"qnum":6,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"下列有關頸部穿刺傷的敘述何者為是？","opts":[{"k":"A","t":"Zone II 的槍擊貫穿傷，都應該手術檢查。"},{"k":"B","t":"Zone I 的穿刺傷合併大範圍的皮下氣腫，應該手術檢查。"},{"k":"C","t":"Zone I 的穿刺傷合併咳血，應該手術檢查。"},{"k":"D","t":"Zone III 的穿刺傷合併吞嚥困難，應該手術檢查。"},{"k":"E","t":"Zone II 的槍擊貫穿傷，50%以上會有需手術治療的損傷。"}],"answer":"B","expl":"頸部穿刺傷：Zone I 合併大量皮下氣腫，提示氣管、食道或肺尖損傷，需要手術或內視鏡探查，所以 (B)。補充：現行 EAST/WTA 傾向穩定病人 CTA 為主的 selective management，只有 hard signs 才直接探查，所以 (A)(E)「Zone II 槍傷都要手術」是舊式觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-7","year":100,"qnum":7,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"25 歲男性，自行步入急診室，並主訴因為 30 分鐘前，左下腹被人使用尖刀刺傷，以下處置何者不適當 ?","opts":[{"k":"A","t":"應先檢查是否有其他傷口。"},{"k":"B","t":"在施以局部麻醉後，進行傷口探查；若沒有刺穿肌肉層，只需處理傷口即可。"},{"k":"C","t":"在施以局部麻醉後，進行傷口探查；若無法確定有無刺穿肌肉層，且腹部超音波檢查無明顯腹腔內出血，可以先進行電腦斷層檢查後，再做決定。"},{"k":"D","t":"若已有網膜由傷口露出體外，應進行手術檢查腹腔內器官。"},{"k":"E","t":"手術於1小時後進行，手術中發現乙狀結腸有2公分的裂傷，應進行結腸造廔手術。"}],"answer":"E","expl":"穩定的腹部穿刺傷，傷口探查及 CT 評估後，乙狀結腸 2 cm 小傷口在 1 小時內手術，可 primary repair，不需要 colostomy（EAST 指引），所以 (E) 不適當。(D) 網膜外露（evisceration）需手術探查。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-8","year":100,"qnum":8,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部穿刺傷，以下處置何者不適當 ?","opts":[{"k":"A","t":"若病患無休克徵兆，可在施以局部麻醉後進行傷口探查；若確定沒有淺層筋膜(fascia)破損，可以不必進行腹腔手術檢查。"},{"k":"B","t":"若病患無休克徵兆且腹部超音波顯示無出血現象，可施以腹膜灌洗檢查(DPL) ，若灌洗液顯示<100,000 WBCs/mm3可以不必進行腹腔手術檢查。"},{"k":"C","t":"針對腰背部穿刺傷，若 triple-contrast helical CT 顯示無明顯損傷，仍無法排除左側橫膈受損。"},{"k":"D","t":"經傷口探查，確定有穿透淺層筋膜(fascia)，若血行穩定且無腹膜炎，可選擇性進行非手術治療。"},{"k":"E","t":"若針對病患採行非手術之觀察療法，可在急診觀察 24 小時後出院。"}],"answer":"B","expl":"腹部穿刺傷 DPL 的陽性標準，與鈍傷不同：穿刺傷 RBC >10,000/mm³（較敏感設定）或 WBC >500/mm³；將 <100,000 WBC/mm³ 當作陰性標準是不正確，所以 (B) 不適當。(C) 腰背穿刺傷即使 CT 正常仍不能排除橫膈傷；(D)(E) 穩定者可 NOM 並觀察 24 小時。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-9","year":100,"qnum":9,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有關胸部穿刺傷，以下敘述何者不適當 ?","opts":[{"k":"A","t":"胸部槍傷，僅約有20%以下的病患，需要開胸手術。"},{"k":"B","t":"胸部槍傷病患，於抵達急診後5分鐘發生心臟停止跳動，應立即於急診執行開胸手術。"},{"k":"C","t":"胸部槍傷病患，若彈道明顯橫貫縱膈腔，都應該接受手術治療。"},{"k":"D","t":"胸部穿刺傷病患，若一開始胸管引流出2000ml 血液，都應該接受手術治療。"},{"k":"E","t":"胸部穿刺傷病患，若有持續由胸管漏氣的現象(air leaks)，大多數都不需接受手術治療。"}],"answer":"C","expl":"胸部槍傷穿過縱隔（transmediastinal）若血流動力學穩定，需要完整評估（CT、CTA、esophagoscopy、bronchoscopy），並不是一律手術；不穩定者才立即手術，所以 (C) 不適當。(D) 初始引流 >1500 mL 是開胸指徵；(E) 多數持續漏氣可保守處理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-10","year":100,"qnum":10,"topic":"胸部","subtopic":"總論／其他","stem":"Which chamber of heart is the least involved in cardiac penetrating injuries?","opts":[{"k":"A","t":"Right atrium。"},{"k":"B","t":"left atrium。"},{"k":"C","t":"right ventricle。"},{"k":"D","t":"left ventricle。"},{"k":"E","t":"right atrium and right ventricle。"}],"answer":"B","expl":"穿透性心臟傷以 right ventricle 最常見（位置在前），其次 left ventricle、right atrium，left atrium 位於後方，最少受傷，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-11","year":100,"qnum":11,"topic":"休克輸血","subtopic":"總論／其他","stem":"急診車禍男性病患，診斷為脾臟撕裂傷與左側血胸。經急救復甦處理後生命徵象仍不穩定，通知開刀房預行緊急手術，並安排輸血。但血庫通知患者驗血為 B 型 Rh 陰性，血庫無 Rh 陰性血，下列何者處置最適當？","opts":[{"k":"A","t":"通知媒體召集 Rh 陰性 B 型捐血者。"},{"k":"B","t":"改採 Rh 陽性 B 型血輸血，緊急開刀。"},{"k":"C","t":"聯絡其他醫院安排轉院治療。"},{"k":"D","t":"乳酸林格液 5000 cc 輸注後，改用膠體溶液(如:HES: hydroxyethyl starch)。"},{"k":"E","t":"採用乳酸林格液與 O 型血輸血，聯絡捐血中心急領 Rh 陰性 B 型血。"}],"answer":"B","expl":"同 97-14：大出血而無 Rh-negative 血時，應給 Rh-positive 同型血挽救生命，所以 (B)。補充：大量晶體液與膠體不是現行建議，應改採 MTP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-12","year":100,"qnum":12,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"34 歲年輕婦女，家暴案件受害者，與先生爭執，被踢中右上腹與腰部，因疼痛就醫。血壓124/70 mmHg 心跳98/min，腹部明顯反彈痛(rebounding pain)，腹部 CT 顯示右上腹肝臟周遭有游離氣(free air)，合併腹內液體(intraperitoneal fluid)。經診斷腹部鈍挫傷，並有臟器破裂。下列敘述何者最正確？","opts":[{"k":"A","t":"腹部鈍挫傷，生命徵象穩定，如為肝臟、脾臟出血，可 選擇保守性非手術治療(selective non-op.)。但本例宜採剖腹探查治療(laparotomy)。"},{"k":"B","t":"剖腹探查發現僅為肝臟右葉表淺撕裂傷(Grade II)，已無持續出血，但為避免感染仍應行右肝葉切除手術，其結果最好。"},{"k":"C","t":"剖腹探查發現十二指腸第二部份(2nd portion)約近四分之三斷裂，十二指腸相對少見，簡單縫合即可。"},{"k":"D","t":"因十二指腸約近四分之三斷裂，無法排除胰臟頭傷害，將行胰頭十二指腸切除術(Whipple’s Op) 最適當。"},{"k":"E","t":"剖腹探查術後傷口較大，可以腹腔鏡手術(laparoscope op.)取代。"}],"answer":"A","expl":"穩定的肝脾傷可 NOM，但此例有 peritonitis（rebound）、CT 見 free air 與腹腔積液，提示 hollow viscus injury，應 laparotomy，所以 (A)。(B) 肝 grade II 淺撕裂不應做 hepatectomy；(C)(D) 十二指腸 3/4 圓周斷裂不能只簡單縫合，也不需要一律 Whipple；(E) 不適用於此情況。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-13","year":100,"qnum":13,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有關胸部外傷之敘述何者為非?","opts":[{"k":"A","t":"鏈伽胸(Flail chest)造成缺氧，主要機轉為疼痛造成換氣量不足，及肺挫傷而引起低血氧現象，並非主要因胸部不正常運動(paradoxical movement)影響氣體交換。"},{"k":"B","t":"當胸管放置後，引流血量大於 1500 毫升稱為大量血胸，鈍挫傷及穿刺傷都可能造成大量血胸，其中以穿刺傷為主要造成原因。"},{"k":"C","t":"有關急診行緊急剖胸術，胸部穿刺性外傷患者較鈍傷患者有較好之預後；如果傷患在事故現場已無生命跡象，則不應再行剖胸術急救，因其成效有限，而鈍傷患者呈現PEA，代表心臟仍有電氣活動，應施行 Resuscitative thoracotomy。"},{"k":"D","t":"幼兒行氣管插管時，易導致單側肺插管，主肇因於幼兒氣管短。"},{"k":"E","t":"創傷性膈疝(Traumatic Diaphragmatic Hernia)左側比較容易發生，急性期手術治療宜採剖腹探查術;慢性外傷性橫膈疝氣手術治療，以從胸部探查較佳。"}],"answer":"C","expl":"ED thoracotomy 的適應症：穿刺傷有 signs of life 或剛失去；鈍傷無脈搏即使有 PEA 預後極差，不應「鈍傷 PEA 就一定施行」，所以 (C) 為非。(A) flail chest 低血氧主因是疼痛與肺挫傷；(B) 大量血胸 >1500 mL；(D) 幼兒氣管短、易單側肺插管；(E) 橫膈疝急性期走腹部、慢性期走胸部。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-14","year":100,"qnum":14,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"一位60 歲男性，在車禍中前胸猛烈撞擊方向盤，被送達急診室時主訴胸痛，他的血壓為60/40 mmHg，呼吸速率為每分鐘 40 次，病人的低血壓經臨床判斷可能肇因於張力性氣胸或心包填塞(cardiac tamponade)，有關張力性氣胸及心包填塞下列何者有誤？","opts":[{"k":"A","t":"兩者可以氣管位置是否偏移、呼吸音有無來區分。"},{"k":"B","t":"Beck's triad 常出現於心包膜填塞，而 Kussmaul's sign 較常出現於張力性氣胸。"},{"k":"C","t":"張力性氣胸及大量血胸都伴隨有呼吸音降低現象，但可以敲診方式來區分兩者之不同。"},{"k":"D","t":"FAST 可以快速而正確診斷心包膜填塞，其正確率約 90%，當合格外科醫師在時，病人情況允許的話，最好到開刀房實施引流；若無合格外科醫師在時，Pericardiocentesis可以提供診斷，但並非是確定性治療。"},{"k":"E","t":"張力性氣胸為臨床診斷，不需 X 光來診斷，Needle decompression 可以暫時緩解症狀，但確定性治療仍需放置胸管引流。"}],"answer":"B","expl":"Kussmaul's sign（吸氣時頸靜脈壓反而上升）常見於 cardiac tamponade、constrictive pericarditis 等，不是 tension pneumothorax 的特徵，所以 (B) 錯。(E) tension pneumothorax 為臨床診斷，needle decompression 為暫時處置，需接著放胸管。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-15","year":100,"qnum":15,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關 resuscitative thoracotomy 的治療策略 (therapeutic maneuvers)， 何者為非？","opts":[{"k":"A","t":"移除心包膜填塞之心臟周圍 (pericardial) 的血液。"},{"k":"B","t":"打開心包腔，直接心臟按摩。"},{"k":"C","t":"修補左側主支氣管截斷。"},{"k":"D","t":"直接控制正在流血的胸內出血。"},{"k":"E","t":"夾住 descending aorta， 以減緩橫膈以下部位的流血。"}],"answer":"C","expl":"Resuscitative thoracotomy 的目標：解除 tamponade、心臟按摩、控制胸內出血、夾 descending aorta；修補主支氣管斷裂屬於確定性手術，不在急診開胸的治療手段範圍，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-16","year":100,"qnum":16,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有關老年外傷病患與一般成年外傷病患的差異，請選出正確者：","opts":[{"k":"A","t":"老年病患生理儲備 physiologic reserve 較為有限，所以休克時的表現會比一般成年人要早，也比較敏感。"},{"k":"B","t":"老年病患對低血氧 Hypoxia 與低容積 Hypovolemia 的忍受度較高，所以心跳與血壓較不容易產生變化。"},{"k":"C","t":"老年病患由於頸椎的退化性變化使得頸部活動性減低，因此頸椎受傷的機率較一般成年人為低。"},{"k":"D","t":"老年病患發生休克時，可能因先前已有的疾病或藥物，而使得血壓與心跳看似仍在「正常」範圍。"},{"k":"E","t":"以上皆不正確。"}],"answer":"D","expl":"老年病人休克時，因 beta-blocker、高血壓基礎值偏高等，血壓與心跳看似正常，易低估傷勢（occult hypoperfusion），所以 (D)。(A) 老人休克表現較晚；(B) 對缺氧與低血容耐受度低；(C) 頸椎退化反而增加受傷風險。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-17","year":100,"qnum":17,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"對懷孕的外傷病患，以下敘述何者正確？","opts":[{"k":"A","t":"胎兒窘迫 Fetal distress 可能出現在母體的血行動力 Hemodynamics 仍為正常時，並可作為母體可能有內出血的早期徵象。"},{"k":"B","t":"胎兒是否穩定，可以看出母體是否無恙，因此應先作胎兒的評估，再決定是否需要對母體作復甦性治療 resuscitation。"},{"k":"C","t":"懷孕後期，由於組織水腫的關係，容易產生口咽部 Oropharynx 的 swelling，因此如果須要插入氣管內管時，應選擇比正常口徑稍大一點的管子，如 6.57.0。"},{"k":"D","t":"胎兒與懷孕情況的評估如胎心音、子宮大小、是否有陰道出血等，應包括在對懷孕外傷病患的初級評估 Primary Survey 中。"},{"k":"E","t":"以上皆正確。"}],"answer":"A","expl":"胎兒窘迫（fetal distress）可能早於母親的血壓下降出現，因為孕婦失血時會先犧牲子宮胎盤灌流來維持母體，所以 (A)。(B) 應先復甦母親；(C) 孕婦水腫反而要選較小的氣管內管（約 6.0–7.0 mm）；(D) 胎心音等評估屬於 secondary／adjunct，不在 primary survey 取代 ABCDE。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-18","year":100,"qnum":18,"topic":"小兒","subtopic":"總論／其他","stem":"有關小兒外傷性腦損傷 Traumatic Brain Injury，請選出正確者：","opts":[{"k":"A","t":"與成人相同，應常規使用 Mannitol 或 Hyperventilation。"},{"k":"B","t":"通常不建議投與預防性抗癲癇藥物 Anti-seizure prophylaxis。"},{"k":"C","t":"在一歲半以下的幼兒，因為囪門或是顱骨尚未閉合使得顱內壓較不易升高，因此比較不需要作顱內壓監測。"},{"k":"D","t":"類固醇在兒童腦外傷仍有其效果。"},{"k":"E","t":"以上皆正確。"}],"answer":"B","expl":"兒童嚴重 TBI 的處置與成人不盡相同：不建議常規 hyperventilation 或預防性 steroid（CRASH trial 的負面結果）；幼兒顱縫與囪門尚未閉合，仍可能發生 ICP 升高並需要監測；預防性抗癲癇藥物在多數情況不常規建議（可考慮用於重度 TBI 早期），所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-19","year":100,"qnum":19,"topic":"小兒","subtopic":"兒虐（child abuse）警示徵象","stem":"診治兒童外傷病患時，下列何者是應懷疑有「兒虐 Child Abuse」的警告徵象 Red Flags：","opts":[{"k":"A","t":"父母親或照顧者間提供的病史不一致。"},{"k":"B","t":"反覆發生外傷，並於不同的院所就診。"},{"k":"C","t":"視網膜出血。"},{"k":"D","t":"外傷程度遠超過所描述的受傷機轉。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"兒虐 red flags 包括：病史不一致或延遲就醫、反覆受傷且在不同院所就診、retinal hemorrhage（shaken baby）、外傷程度與描述機轉不符等，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-20","year":100,"qnum":20,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"25 歲男性病患與人爭吵，遭人開槍，胸腹部受到多處槍傷後，緊急送往本院急診。EMT 於急救途中，發現病患意識昏迷，瞳孔無擴大，沒有光反射，血壓量不到，心跳由 EKG 監視器顯示為 Pulseless Electrical Activity(PEA)，無自發性呼吸，請問應如何處置？","opts":[{"k":"A","t":"由於病患無生命徵象，應考慮於 CPR 5 分鐘無效後，宣佈死亡。"},{"k":"B","t":"由於病患已經是臨床意義上的死亡，應考慮器官捐贈的事項。"},{"k":"C","t":"病患意識不清，應懷疑有無腦部中槍，即刻安排 CT 檢查，並連絡神外。"},{"k":"D","t":"由於病患受到軀幹穿刺傷，造成無生命跡象，應於 CPR 15 分鐘內，考慮施行緊急開胸術(ED Thoracotomy)。"},{"k":"E","t":"病患若是中槍部位集中於心臟，則因傷及要害，他的預後遠較胸腹其他部位的槍傷為差。"}],"answer":"D","expl":"穿刺性胸腹創傷到院前失去生命徵象（PEA）、CPR 時間不長（<15 分鐘）時，依 EAST/WTA 指引仍應考慮 ED thoracotomy，所以 (D)。(A)(B) 不應過早宣告死亡；(C) 腦部 CT 無助於此狀況；(E) 心臟傷若及時處理反而有機會存活。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-21","year":100,"qnum":21,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"What’s the common pathogen in the overwhelming post-splenectomy sepsis ?","opts":[{"k":"A","t":"Streptococcus pneumonia。"},{"k":"B","t":"E. coli。"},{"k":"C","t":"Staphylococcus aureus。"},{"k":"D","t":"Candida albican。"},{"k":"E","t":"Klebsiella pneumonia。"}],"answer":"A","expl":"脾切除後暴發性感染（OPSI）最常見的致病菌是 Streptococcus pneumoniae，其次為 Haemophilus influenzae type b 與 Neisseria meningitidis（encapsulated organisms），所以 (A)。補充：脾切除後需接種肺炎鏈球菌、Hib、腦膜炎雙球菌疫苗。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-22","year":100,"qnum":22,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列有關橫膈膜損傷(diaphragmatic injury)之敘述何者為非？","opts":[{"k":"A","t":"臨床上會出現 Kehr’s sign。"},{"k":"B","t":"橫膈膜損傷，初期以chest film來診斷，正確率為20-50%。"},{"k":"C","t":"橫膈膜損傷延遲修補，會增加臨床上mortality rate及morbidity rate。"},{"k":"D","t":"按照AAST的分類，橫膈裂傷大於十公分為Grade III。"},{"k":"E","t":"在一些慢性橫膈膜損傷病例，可使用nonabsorbable prosthetic mesh 來修補。"}],"answer":"D","expl":"AAST 橫膈損傷分級：Grade I contusion；II laceration ≤2 cm；III laceration 2–10 cm；IV laceration >10 cm 且組織缺損 ≤25 cm²；V 組織缺損 >25 cm²。因此 >10 cm 不是 Grade III，所以 (D) 錯。(A) Kehr's sign 為左肩疼痛；(B) CXR 初期診斷率約 20–50%；(C) 延遲修補增加死亡率。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-23","year":100,"qnum":23,"topic":"胸部","subtopic":"總論／其他","stem":"下列有關外傷性食道破裂(esophageal perforation)之敘述何者為非？","opts":[{"k":"A","t":"最常出現的受傷機轉為頸部鈍傷。"},{"k":"B","t":"最常出現的受傷部位，為食道中間三分之一的位置。"},{"k":"C","t":"可以使用含鋇劑(thin barium)的顯影劑，做食道攝影後即可診斷。"},{"k":"D","t":"直接修補，可應用於受傷24小時內診斷出的病例。"},{"k":"E","t":"引流術較適合用於延遲性頸部食道破裂病患。"}],"answer":"A","expl":"創傷性食道破裂最常見於穿刺傷（槍傷、刀傷）與醫源性損傷，所以官方答案 (A)「最常見為頸部鈍傷」為錯。","outdated":false,"suspect":true,"flagNote":"(B)「最常見部位為食道中段」也不符：外傷性（尤其穿刺傷）以 cervical esophagus 最常見，其次才是胸段；因此題目有兩個疑問選項，官方答案 (A) 較明確。(C) 單純 thin barium 敏感度約 70–80%，不應宣稱「即可診斷」，與常識也不符。考試以官方 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"100-24","year":100,"qnum":24,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"下列有關主動脈裂傷(Aortic disruption) 之敘述何者為非？","opts":[{"k":"A","t":"最主要是在ligamentum arteriosum of aorta處造成撕裂傷。"},{"k":"B","t":"在X光判讀上可見aortic knob。"},{"k":"C","t":"對於縱膈腔血腫的病患如果接受胸部顯影劑電腦斷層檢查為陰性，主動脈就沒有必要再接受其他進一步檢查。"},{"k":"D","t":"TEE (transesophageal echocardiography) 對於主動脈裂傷是一個有效而且較少侵襲性的檢查。"},{"k":"E","t":"Endovascular stenting graft 目前是針對近端降主動脈裂傷病患的治療工具。"}],"answer":"B","expl":"主動脈破裂的典型 CXR 表現是 aortic knob 消失（obliterated）、縱膈變寬、left apical cap 等，不是「可見 aortic knob」，所以 (B) 為非。(A) 好發於 ligamentum arteriosum 處（isthmus）；(D) TEE 為有效的非侵入性檢查；(E) 現在多用 TEVAR（endovascular stent graft）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-25","year":100,"qnum":25,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"在台灣，目前有關腦死之法律，何者是對的?","opts":[{"k":"A","t":"必須家屬先簽署器官捐贈同意書，醫生才可以進行腦死判定。"},{"k":"B","t":"醫師判定腦死以後，即使家屬不同意捐贈器官，醫師仍可以停止治療，讓病人往生。"},{"k":"C","t":"醫師判定病人腦死以後，在法律上就可認定已死亡。"},{"k":"D","t":"「腦死判定準則」之母法是「人體器官移植條例」。"},{"k":"E","t":"腦死判定是醫學上的問題，不涉及法律。"}],"answer":"D","expl":"台灣的腦死判定準則依據「人體器官移植條例」授權訂定，所以 (D)。(A) 判定不需先簽器官捐贈同意；(B)(C)(E) 的說法不符合台灣法律規定（腦死判定牽涉法律與同意程序）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-26","year":100,"qnum":26,"topic":"休克輸血","subtopic":"總論／其他","stem":"30 歲男性，車禍受傷造成脾臟破裂，送至急診時已呈休克狀態。經輸血急救後，緊急開腹手術，摘除脾臟並止血，術後送至加護病房。以下哪一個參數用於偵測循環不足(perfusion insufficiency)最可靠？","opts":[{"k":"A","t":"意識狀態。"},{"k":"B","t":"血壓。"},{"k":"C","t":"尿量。"},{"k":"D","t":"心臟輸出量。"},{"k":"E","t":"血中乳酸濃度。"}],"answer":"E","expl":"術後評估灌流是否足夠，單靠血壓、尿量、意識都可能被代償遮蔽；血中 lactate 與 base deficit 反映細胞缺氧與無氧代謝，是最可靠的 global perfusion 指標，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-27","year":100,"qnum":27,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"一名40 歲女性汽車駕駛被 EMT 以全固定方式送至急診室。她的生命徵象穩定，下半身無法動彈。神經學檢查發現疼痛 (pain) 與溫度 (temperature) 感覺喪失，本體 (proprioception)感覺與震動 (vibration) 感覺是存留的。最符合以上檢查結果的診斷為:","opts":[{"k":"A","t":"central cord syndrome。"},{"k":"B","t":"anterior cord syndrome。"},{"k":"C","t":"complete cord syndrome。"},{"k":"D","t":"Brown–Séquard syndrome。"},{"k":"E","t":"Horner syndrome。"}],"answer":"D","expl":"官方答案為 Brown–Séquard (D)。題幹：下半身無法動彈、痛覺與溫覺喪失、本體感覺與震動覺保留，這是典型的 anterior cord syndrome（spinothalamic tract 與 corticospinal 受損，dorsal column 保留），應為 (B)。","outdated":false,"suspect":true,"flagNote":"Brown–Séquard 是同側運動與本體感覺喪失、對側痛溫覺喪失，題幹沒有單側表現，與 (D) 不符。因此官方答案 (D) 很可能有誤；若真要選，我的判斷是 (B) anterior cord syndrome，但考試請以官方 (D) 為準並了解此矛盾。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"100-28","year":100,"qnum":28,"topic":"脊椎脊髓","subtopic":"SCIWORA／Chance fracture","stem":"腰椎損傷，經 X 光檢查報告有 Chance fracture，是下列何種診斷?","opts":[{"k":"A","t":"腰椎關節移位。"},{"k":"B","t":"腰椎壓迫性骨折。"},{"k":"C","t":"腰椎體垂直骨折。"},{"k":"D","t":"腰椎體橫斷骨折。"},{"k":"E","t":"腰椎體斜面骨折。"}],"answer":"D","expl":"Chance fracture 是 flexion-distraction injury（安全帶式損傷），骨折線橫向貫穿椎體與後方結構，常合併腹內臟器傷害（小腸、mesentery），所以 (D) 腰椎體橫斷骨折。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-29","year":100,"qnum":29,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"針對腦死與器官捐贈，以下敘述何者較恰當？","opts":[{"k":"A","t":"GCS=3，瞳孔對光無反應，無腦幹反射與自主呼吸，是腦死判定必要條件。"},{"k":"B","t":"癌症與敗血性休克，均是捐贈器官的絕對禁忌症。"},{"k":"C","t":"呈現低體溫時，仍可有效的執行腦死判定。"},{"k":"D","t":"B 型及 C 型肝炎帶原者，是捐贈器官的絕對禁忌症。"},{"k":"E","t":"腦死病患的肺部多半正常，超過 70%可以做肺臟捐贈者。"}],"answer":"A","expl":"腦死判定的必要條件：先排除可逆因素（低體溫 <35°C、藥物、代謝）；之後確認深度昏迷（GCS 3）、brainstem reflexes absent 與 apnea test，所以 (A)。(B)(D) 癌症與肝炎並非所有情形都是絕對禁忌；(C) 低體溫時不應判定；(E) 肺臟多半不適合捐贈，利用率遠低於 70%。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-30","year":100,"qnum":30,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"關於橫膈損傷，以下敘述何者較不恰當？","opts":[{"k":"A","t":"胸部 X 光發現，常被誤為橫膈提高，局部氣胸或血胸。"},{"k":"B","t":"當懷疑左側橫膈疝氣時，置放胃管經常是必要的。"},{"k":"C","t":"左右兩側發生率相當。"},{"k":"D","t":"腹腔鏡手術有極高的診斷率。"},{"k":"E","t":"右側橫膈破裂較不易早期診斷。"}],"answer":"C","expl":"橫膈損傷以左側較常見（約 70–80%），因右側有肝臟保護，所以 (C) 錯。(A) CXR 常被誤判；(B) 懷疑左橫膈疝氣時，胃管出現在胸腔可協助診斷；(E) 右側破裂早期較不易診斷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-31","year":100,"qnum":31,"topic":"災難院前法規","subtopic":"總論／其他","stem":"有關外傷醫療史描述，下列何者為非：","opts":[{"k":"A","t":"人類歷史是一部戰爭史，更是一部外傷史。"},{"k":"B","t":"國外最早確切可考據的外傷史記戴，可見於古希臘陶土罐碎片。"},{"k":"C","t":"中國歷史最早外傷相關確切記戴，是史記”華佗列傳”。"},{"k":"D","t":"意外傷害，為台灣 99 年十大死亡原因第六位。"},{"k":"E","t":"機車車禍，佔台灣最多的交通意外事故死亡。"}],"answer":"C","expl":"題目是外傷醫學史的記憶題。官方答案認為 (C)「中國最早外傷相關記載是史記『華佗列傳』」為錯（華佗的記載見於後漢書與三國志，而非史記）。這題屬史料記憶，對臨床沒有影響，不需要深究。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-32","year":100,"qnum":32,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"有關台灣交通事故傷害創傷預防描述，下列何者為非：","opts":[{"k":"A","t":"88 年 6 月起機車駕駛人必須戴安全帽。"},{"k":"B","t":"89 年 8 月起汽車駕駛人酒醉禁止駕車 。"},{"k":"C","t":"90 年 5 月起汽車駕駛人及前座乘客必須繫安全帶。"},{"k":"D","t":"97 年 1 月起酒駕觸及公共危險罪。"},{"k":"E","t":"目前汽車駕駛人血液酒精濃度達 100mg/100ml，便觸及公共危險罪。"}],"answer":"E","expl":"台灣酒駕刑責門檻會隨法規修訂變動：現行刑法第 185 條之 3 為呼氣酒精濃度 ≥0.25 mg/L 或血液酒精濃度 ≥0.05%（即 50 mg/dL）即構成公共危險罪。","outdated":false,"suspect":true,"flagNote":"官方答案 (E) 把「100 mg/100 mL 才觸及公共危險罪」當作錯誤，但實際上 100 mg/dL 已超過現行與舊版門檻，所以敘述本身並非錯誤。這是法規時效性問題，答案可能依年代不同而不同。考試以官方 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"100-33","year":100,"qnum":33,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一位30 歲男性賽車手不幸發生翻車意外掉落山谷，雙小腿受困於翻車車頂下，三小時後脫困送至急診室。此時 BP 為 130/80 ㎜ Hg，心跳為 90/min，雙小腿腫漲、冰冷、感覺異常、Dorsalis Pedis 無脈博跳動。此時較適當的優先處理為：","opts":[{"k":"A","t":"做 Bil. leg fasciotomy。"},{"k":"B","t":"做 Bil. BK amputation。"},{"k":"C","t":"給予高壓氧治療。"},{"k":"D","t":"給予大量 IV NaHCO3。"},{"k":"E","t":"給予 Heparin。"}],"answer":"A","expl":"被壓 3 小時的 crush injury，雙小腿腫脹、冰冷、感覺異常、無足背脈搏，有 acute limb ischemia 與 compartment syndrome 風險，優先處理是 fasciotomy（並做血管評估／revascularization），所以 (A)。同時要監測 rhabdomyolysis、hyperkalemia 與 AKI。(B) 截肢太早；(E) 抗凝血劑不適合有出血風險者。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-34","year":100,"qnum":34,"topic":"胸部","subtopic":"總論／其他","stem":"關於氣管裂傷，下列何者為非？","opts":[{"k":"A","t":"外傷後病人聲音沙啞時，需懷疑氣管受損。"},{"k":"B","t":"穿刺傷造成之氣管損傷，較常發生於頸部。"},{"k":"C","t":"鈍傷造成的氣管損傷，常位於左右支氣管交界處(carina)。"},{"k":"D","t":"氣管損傷亦須考慮同時有食道損傷之可能。"},{"k":"E","t":"確切診斷工具為電腦斷層(CT)。"}],"answer":"E","expl":"氣管支氣管損傷的確診工具是 bronchoscopy，不是 CT；CT 可見縱隔氣腫等間接徵象。其他：(A) 聲音沙啞需懷疑；(B) 穿刺傷好發於頸部；(C) 鈍傷常在 carina 附近；(D) 要同時評估食道。所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-35","year":100,"qnum":35,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"關於影像輔助胸腔內視鏡手術(video-assisted thoracoscopic surgery, VATS)於胸腔創傷之運用，下列何者為非？","opts":[{"k":"A","t":"適用於生命現象較穩定之病人。"},{"k":"B","t":"可用於尋找小量出血點。"},{"k":"C","t":"對於橫隔裂傷，為一良好之診斷工具。"},{"k":"D","t":"建議創傷七天後再進行此類手術，成功率較高。"},{"k":"E","t":"較複雜之創傷，可搭配迷你開胸手術(minithoracotomy)。"}],"answer":"D","expl":"VATS 於胸部外傷適用於血流動力學穩定的病人，可用於找出小出血點、評估橫膈裂傷、處理 retained hemothorax 與 empyema。retained hemothorax 建議在傷後約 3–7 天內進行，越早效果越好，等到七天後 fibrous peel 形成會使成功率降低，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-36","year":100,"qnum":36,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"下列有關Flail chest 之敘述，何者錯誤？","opts":[{"k":"A","t":"一般定義為，3 根或多於 3 根節斷性肋骨骨折。"},{"k":"B","t":"好發於後胸壁段肋骨。"},{"k":"C","t":"易合併肺鈍挫傷。"},{"k":"D","t":"生理變化可能呈現肺功能 QS/QT 上升及低血氧。"},{"k":"E","t":"出現呼吸窘迫時，應放置氣管內管(ET tube)，並使用呼吸器。"}],"answer":"B","expl":"Flail chest 為 ≥3 根連續肋骨各有 ≥2 處骨折，好發於前外側胸壁（後方有脊椎旁肌肉支撐，較少 flail），所以 (B) 錯。(C) 常合併 pulmonary contusion；(D) 會因 shunt（Qs/Qt）上升而低血氧。補充：現在強調 pain control 與氧合，不一定都要插管，只有 respiratory failure 時才需要通氣支持。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-37","year":100,"qnum":37,"topic":"胸部","subtopic":"肺挫傷／創傷性窒息","stem":"下列有關Traumatic asphyxia 之敘述，何者錯誤？","opts":[{"k":"A","t":"胸部重物壓傷而造成。"},{"k":"B","t":"臨床表徵為頭頸部發紺、眼部結膜下出血等。"},{"k":"C","t":"有些嚴重病患需氣管插管。"},{"k":"D","t":"生理變化會使胸部及上腔靜脈壓力增加。"},{"k":"E","t":"預後與缺氧時間長短無關。"}],"answer":"E","expl":"Traumatic asphyxia 的預後與缺氧持續時間、合併傷害有關，缺氧越久越差，所以 (E)「無關」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-38","year":100,"qnum":38,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關心臟鈍傷之敘述，何者錯誤？","opts":[{"k":"A","t":"高速車禍合併胸部鈍傷病患，需高度懷疑合併心臟鈍傷。"},{"k":"B","t":"臨床可能出現頸靜脈怒張、遙遠低沉的心音、低血壓等徵象。"},{"k":"C","t":"初步診斷應包含胸部X光、心電圖、心肌酶、心肌旋轉蛋白等檢查。"},{"k":"D","t":"雖然建議做心肌酶檢查, 但有時無法反應嚴重程度 。"},{"k":"E","t":"嚴重胸部鈍傷，CPR超過10 min，應實施緊急開胸術(ED thoracotomy) 。"}],"answer":"E","expl":"ED thoracotomy 不是鈍傷病人 CPR >10 分鐘後的常規適應症；鈍傷無生命徵象預後極差，所以 (E) 錯。(A)(B)(C)(D) 為 blunt cardiac injury 的標準觀念：ECG + troponin + echo 評估。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-39","year":100,"qnum":39,"topic":"胸部","subtopic":"Tracheobronchial injury","stem":"對於胸部創傷病患，若胸腔 X 光片出現「fallen lung sign」，下列何者錯誤？","opts":[{"k":"A","t":"支氣管破裂。"},{"k":"B","t":"多數好發離 carina 2.5cm 內。"},{"k":"C","t":"一般好發左側。"},{"k":"D","t":"易合併氣胸。"},{"k":"E","t":"多為快速胸部前後擠壓所造成。"}],"answer":"C","expl":"Fallen lung sign 代表主支氣管完全斷裂，多數在 carina 2.5 cm 以內，且右側比左側較常見（右主支氣管較短且暴露），所以 (C)「好發於左側」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-40","year":100,"qnum":40,"topic":"胸部","subtopic":"總論／其他","stem":"下列有關食道外傷之敘述何者為非？","opts":[{"k":"A","t":"受傷超過 24 小時，不建議直接修補。"},{"k":"B","t":"一般槍傷及刀傷造成的比例最高。"},{"k":"C","t":"頸部二區(Zone II)頸闊肌穿刺傷，需懷疑合併食道受損。"},{"k":"D","t":"鈍傷造成的比例較低，約＜0.1%。"},{"k":"E","t":"占整體外傷病患中發生率約＜1％。"}],"answer":"A","expl":"題目的官方答案 (A) 認為「受傷超過 24 小時不建議直接修補」為錯。","outdated":false,"suspect":true,"flagNote":"現行指引（如 WSES 2019）認為在選擇性病人身上，延遲診斷（>24 小時）並非 primary repair 的絕對禁忌，可用組織加強（buttress）修補，與 (A) 的敘述有出入；但同一份考卷的 100-23 (D) 又把「24 小時內可直接修補」當作正確，兩題觀念不一致，需要小心。考試以官方 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"100-41","year":100,"qnum":41,"topic":"腹部","subtopic":"肝臟","stem":"Grade V blunt hepatic injury 緊急手術中，已輸全血12單位、血小板36單位，現血壓偏低為85/60mmHg、體溫為35℃，受傷肝臟仍持續出血，以下敘述何者為是？","opts":[{"k":"A","t":"進行Pringle Maneuver以減少出血量，並快速將受損肝臟切除。"},{"k":"B","t":"關閉腹部傷口，以非手術療法non-operative management (NOM)替代治療。"},{"k":"C","t":"於肝臟週圍以大塊紗布墊加壓，腹壁傷口以Bogota bag覆蓋，此為損傷控制手術。"},{"k":"D","t":"再輸全血10單位，同時滴注Dopamine以將血壓提昇至收縮壓120mmHg以上，小心將受損肝臟切除，並放置大號引流管。"},{"k":"E","t":"術中發現病患體溫持續下降，此現象可幫助大腦細胞承受較長缺氧時間。"}],"answer":"C","expl":"Grade V 肝損傷持續出血、已大量輸血且有 hypothermia 與血壓不穩，是 damage control 的典型適應症：以 laparotomy pad packing、暫時關腹（Bogota bag）後轉 ICU 復甦，所以 (C)。(A)(D) 繼續大量切肝與輸血會加重 lethal triad；(E) 低體溫會加重凝血病變，不是保護。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-42","year":100,"qnum":42,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"下列有關 seatbelt sign following blunt abdominal trauma 之敘述何者為非？","opts":[{"k":"A","t":"對於車禍後有上述seatbelt sign之病人中，約有12%存有腹內損傷。"},{"k":"B","t":"其中約64%的病人，需要手術治療 operative management。"},{"k":"C","t":"於腹部 CT 上若可見游離氣(free air)，則小腸破裂之機會頗大。"},{"k":"D","t":"此一創傷機轉，可發生腰椎之chance fracture。"},{"k":"E","t":"對於車禍後無seatbelt sign之病人中，約僅有1.9%存有小腸破裂之機會。"}],"answer":"B","expl":"Seatbelt sign 的統計：有 seatbelt sign 的病人約 10–25% 有腹內損傷，需要高度警覺 small bowel／mesentery injury 與 Chance fracture；此題的 64% 需手術比例是特定文獻資料，官方認為錯誤，所以 (B)。臨床上要記得 seatbelt sign 加上 CT free air 或腹膜炎，需手術探查。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-43","year":100,"qnum":43,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"對於頭部外傷，下列敘述何者正確？","opts":[{"k":"A","t":"若本院無神經外科醫師值班，有外傷病患須轉診之前，至少一定要先做 CT，才有辦法知道病患狀況，以便與轉診醫院交待病情 。"},{"k":"B","t":"頭部外傷之病患，變化很大，但是健保審查嚴謹，所以只能做一次頭部電腦斷層，因此，何時作斷層掃描，時機很重要。"},{"k":"C","t":"頭部外傷病患容易造成腦水腫，因此，生命跡象不穩定的患者，不宜大量輸液，但可以給升壓劑。"},{"k":"D","t":"少量 EDH 可以先觀察，若有臨床變化，可以重復做電腦斷層，以決定是否手術治療。"},{"k":"E","t":"以上皆正確。"}],"answer":"D","expl":"EDH 少量、無症狀者可先觀察並重複 CT，臨床變差再手術，所以 (D)。(A) 轉診前不應為了做 CT 而延誤轉院；(B) 臨床需要可重複 CT；(C) TBI 病人低血壓時要先找出血並維持足夠 BP，不可限制輸液。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-44","year":100,"qnum":44,"topic":"災難院前法規","subtopic":"總論／其他","stem":"有關家暴敘述下列何者為非?","opts":[{"k":"A","t":"家暴事件會在高社經地位的家庭裡發生。"},{"k":"B","t":"家暴通常是偶發事件，醫護人員在急診室的處理態度應以和為貴，來看待家暴事件。"},{"k":"C","t":"遭受到家暴的成年女性，依台灣的法律可以拒絕醫院所提供的醫療，例如住院觀察。"},{"k":"D","t":"受家暴者，常因為非外傷的原因，到門診或是急診就醫。"},{"k":"E","t":"施虐者常有服用藥物或是酗酒的行為。"}],"answer":"B","expl":"家暴不分社經地位，醫護人員應依法通報（家庭暴力防治法有責任通報規定），不能以「和為貴」處理，所以 (B) 錯。受害人常因非外傷原因就醫，施虐者常有物質濫用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-45","year":100,"qnum":45,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"一位嚴重外傷病患來到急診室，經評估後各受傷部位 abbreviated injury scale (AIS) 的敘述如下(1)頭頸部為3 分(2)臉部1 分(3)胸部3 分(4)腹部2 分(5)四肢骨折3 分(6)外觀1 分，依照外傷嚴重度分數(Injury Severity Score ISS)的算法，此病患應給予幾分:","opts":[{"k":"A","t":"3+1+3+2+3+1=13。"},{"k":"B","t":"(3+1+3+2+3+1)*2=26。"},{"k":"C","t":"(3*3)+(1*1)+(3*3)+(2*2)+(3*3)+(1*1)=33。"},{"k":"D","t":"(3*3)+(3*3)+(3*3)=27。"},{"k":"E","t":"3*1*3*2*3*1=54。"}],"answer":"D","expl":"ISS 是三個不同身體區域中最高 AIS 平方和：head/neck 3、chest 3、extremity 3，所以 3² + 3² + 3² = 27，(D)。臉部 1、腹部 2、外觀 1 不計入前三高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-46","year":100,"qnum":46,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"有關胸部外傷的緊急處置，以下列何者正確？","opts":[{"k":"A","t":"當患者有開放性氣胸時應趕緊將傷口用凡士林紗布蓋住以避免漏氣，等病人有呼吸變化，才考慮放置胸管。"},{"k":"B","t":"若傷口恰巧在放置胸管的位置(第五肋間與中腋線)時，可將傷口消毒後經傷口放置胸管，以減少對胸腔壁的傷害。"},{"k":"C","t":"處理增壓性氣胸的關鍵，是趕緊在前胸插入大號針減壓。有無放置胸管並不重要。"},{"k":"D","t":"放置胸管時，必須確定管子沿著肋骨下緣滑進，以免傷及血管或神經。"},{"k":"E","t":"以上皆不正確。"}],"answer":"E","expl":"(A) 開放性氣胸應使用三邊封閉的敷料並放胸管；(B) 不宜經原傷口放胸管；(C) 針刺減壓只是暫時，之後須放胸管；(D) 胸管應沿著肋骨「上緣」進入，因為神經血管束在肋骨下緣，所以 (D) 敘述錯；因此全部皆不正確，答案 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-47","year":100,"qnum":47,"topic":"總論評分","subtopic":"總論／其他","stem":"下列有關穿刺傷(penetrating trauma)的敘述何者為非？","opts":[{"k":"A","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"},{"k":"B","t":"槍傷造成的 temporary cavity，一般比 permanent cavity 來的大。"},{"k":"C","t":"槍傷經過路徑(trajectory)對周圍組織的傷害，ㄧ般比刀傷更嚴重。"},{"k":"D","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)，可能會有偏差。"},{"k":"E","t":"治療穿刺傷時，病患血壓應該控制在 140mmHg 最佳。"}],"answer":"E","expl":"穿刺傷病人的血壓管理不是「控制在 140 mmHg」；現行 damage control resuscitation 主張 permissive hypotension（SBP 約 80–90 mmHg，無 TBI 時）直到手術止血，所以 (E) 錯。(B) 槍傷 temporary cavity 比 permanent cavity 大；(D) 彈道可偏折。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-48","year":100,"qnum":48,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於嚴重胸部穿刺傷病患手術，以外傷損傷控制(Trauma damage control)觀念處理時，下列敘述何者正確？\n1.若紓解心包膜填塞時，發現心房穿孔，可考慮縫合或以導尿管(Foley catheter)填塞。\n2.發現肺葉裂傷，可以腸胃道吻合器(GIA)做肺部分切除止血。\n3.胸壁血管裂傷，可直接縫合或以電刀燒灼。\n4.將病患擺位成完全左側躺(true left lateral decubitus position)有利於合併腹部外傷時剖腹探查的施行。","opts":[{"k":"A","t":"2+3+4。"},{"k":"B","t":"1+3+4。"},{"k":"C","t":"1+2+4。"},{"k":"D","t":"1+2+3。"},{"k":"E","t":"1+2+3+4。"}],"answer":"D","expl":"胸部 damage control：心房穿孔可縫合或用 Foley balloon 暫時填塞；肺實質出血可用 GIA stapler 做 non-anatomic resection 或 tractotomy；胸壁血管可縫合或燒灼。第 4 點不正確，因為完全左側臥會使 laparotomy 不易，應採 supine 稍抬高側，所以 (D) 1+2+3。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-49","year":100,"qnum":49,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有ㄧ 35 歲男性遭人以牛排刀刺中上腹(epigastric region)，產生一處 2 公分長傷口，到院時傷口少量出血，但病患呈現休克現象，超音波檢查(FAST)顯現心包膜積液，下列敘述何者為是？\n1.需將心包膜填塞列為可能診斷之ㄧ。\n2.在休克狀況下，須考慮輸液或輸血治療。\n3.非手術性療法已取代手術療法，成為治療外傷性心包膜填塞的主流。\n4.若病患情況快速惡化，且手術室無法立即就緒，有時需考慮於急診室開胸減壓手術(ED thoracotomy) 。\n5.穿刺傷(penetrating injury) 造成的心包膜填塞產生休克時，急診室開胸減壓手術(ED thoracotomy) 救活出院的存活率不差，超過 30%。","opts":[{"k":"A","t":"1+2+5。"},{"k":"B","t":"1+3+4。"},{"k":"C","t":"1+2+3。"},{"k":"D","t":"1+2+4。"},{"k":"E","t":"1+4+5。"}],"answer":"D","expl":"上腹穿刺傷、休克、FAST 見 pericardial effusion，應高度懷疑 cardiac tamponade；休克時補充輸液或輸血，若快速惡化而手術室未備妥，可 ED thoracotomy。手術仍是治療主流，(3) 錯；穿刺性 tamponade 的 ED thoracotomy 存活率不到 30%（約 10–20%），(5) 過度樂觀。所以 (D) 1+2+4。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"100-50","year":100,"qnum":50,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"ㄧ 19 歲男性遭人以刀刺中腹部多處傷口，產生小腸疝出現象(small bowel evisceration)，到院時病患呈現休克現象，以高級外傷救命術精神急救後緊急剖腹治療，發現有小腸腸繫膜裂傷出血，與以緊急縫合止血，但病患生命現象持續不穩定並在後腹腔中線，主動脈分叉處以上五公分處有一逐漸擴張的搏動性腫塊(pulsatile mass)，下列敘述何者為非？\n1.此傷害位於後腹腔分區的第一區(Zone I)。\n2.此種狀況下壓迫填塞是最好的處理方法。\n3.可考慮置放葉克膜(ECMO)減緩出血。\n4.需考慮控制主動脈(clamp aorta)後，打開後腹腔修補血管止血。\n5.動脈攝影栓塞為最佳選擇。","opts":[{"k":"A","t":"1+2+3。"},{"k":"B","t":"1+2+5。"},{"k":"C","t":"2+3+4。"},{"k":"D","t":"2+4+5。"},{"k":"E","t":"2+3+5。"}],"answer":"D","expl":"Zone I 的後腹腔血腫／搏動性腫塊（主動脈）：需要立即 proximal control（clamp aorta）並直接修補血管，所以 (1) 與 (4) 為正確；(2) 單純 packing 不足、(3) ECMO 需肝素會加重出血、(5) 動脈栓塞不適合，因此理論上「為非」者應是 (2)+(3)+(5)，即 (E)。","outdated":false,"suspect":true,"flagNote":"官方答案 (D) 為 (2)+(4)+(5)，把 (4)「clamp aorta 後修補」當成錯誤，而把 (3) ECMO 當成正確，兩者與現行 trauma 處置相反（Zone I hematoma 要手術探查並做近端控制，ECMO 需抗凝不適合出血病人）。官方答案 (D) 很可能有誤。考試請依官方 (D)。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"101-1","year":101,"qnum":1,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"1 位20 歲男性摩托車騎士發生車禍，至急診時意識不清，臉部變形，口鼻中有鮮血持續湧出，呼吸窘促，嘗試經口咽插氣管內管兩次但都失敗，下一步？","opts":[{"k":"A","t":"做經鼻插氣管內管。"},{"k":"B","t":"應先放口咽管。"},{"k":"C","t":"做環狀甲狀軟骨膜切開術( Cricothyroidotomy )。"},{"k":"D","t":"做 rapid sequence intubation 減少病患躁動。"},{"k":"E","t":"做氣管切開術。"}],"answer":"C","expl":"顏面嚴重外傷、口鼻持續出血、經口插管兩次失敗，已達 failed airway 條件，應立即 surgical cricothyroidotomy，所以 (C)。繼續嘗試鼻插管、LMA 或 RSI 都會延誤；tracheostomy 耗時、風險較高，不適合急診。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-2","year":101,"qnum":2,"topic":"災難院前法規","subtopic":"總論／其他","stem":"外傷發生後的第一小時內，病患最主要的死因是？","opts":[{"k":"A","t":"頭部外傷。"},{"k":"B","t":"多重器官衰竭。"},{"k":"C","t":"大量出血。"},{"k":"D","t":"感染。"},{"k":"E","t":"體溫過低。"}],"answer":"C","expl":"同 95-53：外傷第一小時內主要死因為 massive hemorrhage（以及嚴重中樞神經損傷），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-3","year":101,"qnum":3,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"測量 abdominal intra-abdominal Pressure 的方法何者最常使用?","opts":[{"k":"A","t":"測 Stomach pressure。"},{"k":"B","t":"測 inf. vena cava pressure。"},{"k":"C","t":"測 Bladder pressure。"},{"k":"D","t":"測 central venous pressure，再以公式換算。"},{"k":"E","t":"測 portal venous flow，再以公式換算。"}],"answer":"C","expl":"同 99-23：IAP 最常用 intravesical（bladder）pressure，WSACS 建議的標準方法，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-4","year":101,"qnum":4,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重穿刺傷病患，當必須接受 Damage control operation 時，下列那一條血管不宜直接 ligate？","opts":[{"k":"A","t":"Celiac axis。"},{"k":"B","t":"Common hepatic artery。"},{"k":"C","t":"Portal vein。"},{"k":"D","t":"Superior mesenteric artery。"},{"k":"E","t":"Internal iliac artery。"}],"answer":"D","expl":"同 96-15：SMA 結紮會造成大範圍小腸與右半結腸缺血，不宜直接 ligate；celiac、common hepatic、portal vein 與 internal iliac 在緊急時可結紮，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-5","year":101,"qnum":5,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"嚴重腹部外傷手術，下列那一項不是 damage control procedure？","opts":[{"k":"A","t":"將受傷的腸道切除並完成 anastomosis。"},{"k":"B","t":"將斷裂的輸尿管直接結紮。"},{"k":"C","t":"將裂傷的脾臟直接摘除。"},{"k":"D","t":"將裂傷出血的肝臟以大紗布填塞壓迫。"},{"k":"E","t":"將裂傷的肝門靜脈直接結紮。"}],"answer":"A","expl":"同 96-5：damage control 不做 anastomosis（時間與缺血風險），所以 (A)；結紮輸尿管、脾切除、肝 packing、portal vein ligation（極端情況）屬可接受的快速處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-6","year":101,"qnum":6,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"一位男性患者，在家中浴室跌倒後被家人送到急診處。\nBP:130/80mmhg，HR:70 下/min，SO2:96%，神經學檢查發現下肢肌肉張力(L/R:4/5 分)，上肢(L/R:3/5 分)，而且手指靈活度差。下列的敘述何者為非：","opts":[{"k":"A","t":"應趕緊戴上頸圈保護頸椎。"},{"k":"B","t":"較有可能的受傷機轉，是由於跌倒而造成頸部過度向前彎曲(overflextion)所造成的。"},{"k":"C","t":"下肢肌肉張力的恢復會比上肢好。"},{"k":"D","t":"正確診斷需要 MRI 檢查來確立。"},{"k":"E","t":"臨床的診斷為 Central cord syndrorne。"}],"answer":"B","expl":"上肢無力大於下肢、手指靈活度差，是 central cord syndrome 的典型表現，多為頸部 hyperextension（在頸椎狹窄的老年人跌倒時）造成，而不是 hyperflexion，所以 (B) 錯。(A) 先頸圈保護；(C) 下肢比上肢恢復較好；(D) MRI 可確認。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-7","year":101,"qnum":7,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"外傷團隊在評估一位受到子彈打中軀幹的患者時，以下敘述何者正確？","opts":[{"k":"A","t":"由於子彈的走向是成直線，將入口與出口的傷口連接起來，沒有在這條連接線附近的器官幾乎不會有受損。"},{"k":"B","t":"留在人體腹內的子彈一定要設法取出，否則患者常會有嚴重的副作用。"},{"k":"C","t":"手槍子彈造成的傷口必須清創，傷口附近的組織至少要切除一公分以上才好，臉部除外。"},{"k":"D","t":"子彈入口與出口容易區分，醫師必須盡可能敘述那個傷口為入口或出口。"},{"k":"E","t":"以上皆非。"}],"answer":"E","expl":"槍傷彈道可因 yaw、碎裂或撞到骨頭而偏折，不能以入口與出口的直線來預測；腹內彈頭多數不必立即取出；入口與出口常難分辨，不應勉強判定；清創範圍不需固定一公分。所以 (A)(B)(C)(D) 皆錯，(E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-8","year":101,"qnum":8,"topic":"燒傷環境","subtopic":"總論／其他","stem":"一位工人不小心觸摸一條 220V 的電線後昏迷不醒。EMT 在現場施行 CPCR 約一分鐘後患者清醒，一直抱怨左手傷口(入口)與右小腿傷口(出口)十分疼痛。來到急診室BP:120/80mmhgCHR:90 下/min，RR:20 次/min，SPO2:98%，下列何者為非：","opts":[{"k":"A","t":"必須確定呼吸道的通暢，並給予氧氣。"},{"k":"B","t":"不同於燙傷患者，此類患者的點滴注射量應以不超 100ml/hr 為宜。"},{"k":"C","t":"EKG 的監測是必需要的。"},{"k":"D","t":"除傷口處置外，醫師也必須排除其他部位之外傷。"},{"k":"E","t":"以上皆是。"}],"answer":"B","expl":"電擊傷合併肌肉溶解（rhabdomyolysis）風險，需要足夠補液維持尿量（約 1–1.5 mL/kg/hr，myoglobinuria 時更高），而不是限制在 100 mL/hr，所以 (B) 錯。(A)(C)(D) 為標準處置：氣道、ECG 監測、全身檢查。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-9","year":101,"qnum":9,"topic":"小兒","subtopic":"總論／其他","stem":"一位12 歲的小女孩，母親為台北一家醫學中心的小兒科醫師，在自家後院騎自行車，不慎跌倒後送到急診。病患的生命跡象正常，但是左上方腹部有觸痛。超音波檢查發現腹內在Morison’s pouch 有一些血。下列處置步驟以何者較為正確：","opts":[{"k":"A","t":"收入加護病房，病患可以接受非手術療法處置腹部外傷。"},{"k":"B","t":"囑咐家屬回家後每四小時量血壓，有變化再趕緊回到醫院。"},{"k":"C","t":"安排緊急腹部電腦斷層檢查。"},{"k":"D","t":"安排緊急剖腹檢查手術。"},{"k":"E","t":"以上皆是。"}],"answer":"C","expl":"兒童鈍性腹傷在血流動力學穩定、FAST 發現腹腔積血，應做 CT 評估實質器官損傷，再決定 NOM 或手術，所以 (C)。(A) 不是在 CT 前直接決定；(B) 不能直接回家；(D) 穩定者不必立即剖腹。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-10","year":101,"qnum":10,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"外傷性膀胱破裂之敘述，下列何者有誤？","opts":[{"k":"A","t":"肉觀性血尿為膀胱破裂之重要症狀(hallmark)。"},{"k":"B","t":"指診若發現前列腺向上移位或 high riding 時代表可能有近端尿道斷裂。"},{"k":"C","t":"耻骨骨折常造成腹膜內型(intraperitoneal type)之膀胱破裂。"},{"k":"D","t":"當發現尿道口有血液時，應在放置尿管之前先從事逆行性尿道攝影以評估尿道完整性。"},{"k":"E","t":"常合併有骨盆骨折。"}],"answer":"C","expl":"膀胱破裂：extraperitoneal 型多合併骨盆骨折（恥骨骨折的骨片刺穿膀胱），intraperitoneal 型則多見於下腹鈍傷時膀胱充盈，所以 (C)「恥骨骨折常造成腹膜內型」為錯。(D) 尿道口有血要先 RUG 再放 Foley。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-11","year":101,"qnum":11,"topic":"燒傷環境","subtopic":"電擊傷","stem":"電擊外傷(Electrical injury)之敘述，何者有誤？","opts":[{"k":"A","t":"死亡率 3-5%。"},{"k":"B","t":"高電壓電擊的界線定義為 500V~1000V 以上。"},{"k":"C","t":"可發生心室顫動(AF)之電擊電流為16-20 Ma。"},{"k":"D","t":"電弧(Electrical arc)的瞬間溫度可高達 2500-5000℃。"},{"k":"E","t":"臨床上當注意肌肉溶解造成的急性腎衰竭。"}],"answer":"C","expl":"電擊傷：能引起 ventricular fibrillation 的 AC 電流約 60–100 mA，16–20 mA 屬於 let-go 閾值（引起肌肉強直收縮無法放開）而非 VF，所以 (C) 錯。(B) 高電壓界線通常 >500–1000 V；(D) arc 溫度可達數千度；(E) 要注意 rhabdomyolysis 與 AKI。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-12","year":101,"qnum":12,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"Emergency thoracotomy 的 indication 何者為非？","opts":[{"k":"A","t":"胸部穿刺傷，從受傷開始 CPR，10 分鐘。"},{"k":"B","t":"非胸部穿刺傷，從受傷開始 CPR，3 分鐘。"},{"k":"C","t":"鈍傷從受傷開始 CPR，10 分鐘。"},{"k":"D","t":"頸動脈 air embolism，持續 SBP ＜60 mmHg。"},{"k":"E","t":"鈍傷從受傷開始 CPR，10 分鐘，無心跳(asystol)。"}],"answer":"E","expl":"ED thoracotomy 的適應症取決於傷勢類型與有無 signs of life／電氣活動；鈍傷合併 asystole 且 CPR 10 分鐘者預後極差，不應執行，所以 (E)。(A) 胸部穿刺傷 CPR ≤15 分鐘為適應症；(D) 頸動脈氣栓或持續低血壓也屬急救適應症。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-13","year":101,"qnum":13,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"何者不是 damage control operation 時該做的步驟？","opts":[{"k":"A","t":"肝臟周圍(perihepatic)packing。"},{"k":"B","t":"腹部靜脈結紮(ligation)。"},{"k":"C","t":"部分腸切除，不接合。"},{"k":"D","t":"大腸造口(colostomy)。"},{"k":"E","t":"胰臟頭頸部實質或胰管損傷時用 closed-suction drain 引流。"}],"answer":"D","expl":"Damage control operation 在第一階段不做複雜重建與造口：(A) liver packing、(B) 腹部靜脈結紮、(C) 腸切除但不接合、(E) 胰臟傷用 closed suction drain 引流都屬 DCS；(D) 結腸造口（colostomy）屬確定性階段，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-14","year":101,"qnum":14,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有關 emergency thoracotomy 所欲達成之目標何者為非？","opts":[{"k":"A","t":"釋放心包膜填塞(pericardial tamponade)。"},{"k":"B","t":"控制心臟出血(cardiac hemorrhage)。"},{"k":"C","t":"控制胸腔內出血(intrathoracic bleeding)。"},{"k":"D","t":"暫時封閉上行胸主動脈(ascending thoracic aorta)。"},{"k":"E","t":"執行開胸心臟按摩(open cardiac massage)。"}],"answer":"D","expl":"ED thoracotomy 的目標包括：解除 tamponade、控制心臟與胸內出血、open cardiac massage、夾住 descending thoracic aorta 以維持心腦灌流；夾 ascending aorta 不是目標，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-15","year":101,"qnum":15,"topic":"頭部TBI","subtopic":"總論／其他","stem":"35 歲男性病人因騎機車撞擊路邊電線杆，經由神經學檢查，發現左側瞳孔放大、疼痛刺激無法睜開眼瞼、兩下肢有去大腦僵直、喉嚨無法發出聲音，此病人 GCS 昏迷指數共有幾分？","opts":[{"k":"A","t":"3分。"},{"k":"B","t":"4分。"},{"k":"C","t":"5分。"},{"k":"D","t":"6分。"},{"k":"E","t":"7分。"}],"answer":"B","expl":"GCS：疼痛刺激不睜眼 E1；無法發聲 V1；去大腦僵直 M2（extension），共 E1 + V1 + M2 = 4 分，所以 (B)。瞳孔不等大不計入 GCS，但提示 herniation，應立即插管並準備 osmotherapy 與神經外科處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-16","year":101,"qnum":16,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"男性酒後與他人爭執，被踢中右上腹與腰部，因疼痛就醫。受害者血壓 124/70 mmHg 心跳 98/min，腹部明顯反彈徵(rebounding pain)，腹部 CT 顯示右上腹肝臟周遭有游離氣(free air)，合併腹內液體(intraperitoneal fluid)。經診斷腹部鈍挫傷，並有臟器破裂。下列各項有關處置的敘述，何者最為正確？","opts":[{"k":"A","t":"腹部鈍挫傷，生命徵象穩定，如為肝臟、脾臟出血，可選擇保守性非手術治療(selective non-op.)。本例得經腹腔灌洗檢查 (DPL)，以決定是否手術。"},{"k":"B","t":"本例可以腹腔鏡手術(laparoscope op.)取代術治療，術後傷口較小。"},{"k":"C","t":"剖腹探查發現僅為肝臟右葉表淺撕裂傷(Grade II)，已無持續出血，但為避免感染仍應行右肝葉切除手術，其結果最好。"},{"k":"D","t":"剖腹探查時發現十二指腸第二部份(2nd portion)不足二分之一斷裂，十二指腸簡單縫合，並加多管引流(triple drainage)，為治療選項。"},{"k":"E","t":"因十二指腸約近四分之三斷裂，無論胰臟頭有否傷害，將行胰頭十二指腸切除術(Whipple’s Op) 最適當。"}],"answer":"D","expl":"穩定的肝脾傷可 NOM，但本例 CT 見 free air 與腹腔積液，加上 rebound pain，提示 hollow viscus injury，需手術。十二指腸第二部分小於 50% 周徑的裂傷，可 primary repair 並配合減壓（triple drainage 為舊式做法），所以 (D)。(C) 肝 grade II 不需切除；(E) 不需要一律 Whipple；(B) 懷疑 hollow viscus injury 且腹膜炎時，通常剖腹探查較安全。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-17","year":101,"qnum":17,"topic":"災難院前法規","subtopic":"總論／其他","stem":"您僅是外傷醫師，不能通報與驗傷採證下列何種受暴人員和開立診斷書？","opts":[{"k":"A","t":"家庭暴力被害人。"},{"k":"B","t":"受虐兒童。"},{"k":"C","t":"性暴力侵害被害人。"},{"k":"D","t":"受虐或家暴之老先生。"},{"k":"E","t":"以上皆非。"}],"answer":"C","expl":"依台灣法規：醫師遇到家暴、兒童虐待、性侵害皆有責任通報；其中家庭暴力與兒童虐待的驗傷與診斷書可由一般醫師開立，但性侵害被害人的驗傷與證據採集有專責指定醫院與訓練要求，並非一般外傷醫師可單獨進行，所以官方答案 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-18","year":101,"qnum":18,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"病患由救護車送入急診，經急救輸液後，由昏迷中清醒，主訴腹部脹痛。臉色蒼白，四肢冰冷，血壓 82/46mmHg，腹部鼓漲，反彈痛徵(rebounding pain)明顯。病患診斷與處置，何者最不適當？","opts":[{"k":"A","t":"床邊腹部超音波比腹部電腦斷層掃瞄優先。"},{"k":"B","t":"腹部超音波可鑑別肝硬化合併大量腹水或肝臟鈍傷破裂。"},{"k":"C","t":"腹主動脈瘤破裂、肝腫瘤破裂為可能鑑別診斷。"},{"k":"D","t":"肝膽道感染合併敗血症、脾臟破裂為可能鑑別診斷。"},{"k":"E","t":"安排外科手術，因例而異。"}],"answer":"B","expl":"休克、腹部鼓漲的病人，優先 FAST 與緊急處置；但超音波無法可靠區分肝硬化腹水與肝破裂出血，因此 (B) 錯。(C)(D) 為鑑別診斷；(E) 手術要因病而異。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-19","year":101,"qnum":19,"topic":"腹部","subtopic":"脾臟","stem":"有關脾臟破裂病患接受腹部脾臟切除手術，術後 2~3 日發燒的診斷，何者較不可能？","opts":[{"k":"A","t":"腹內膿瘍。"},{"k":"B","t":"輸血或藥物反應。"},{"k":"C","t":"點滴(靜注)靜脈管路感染。"},{"k":"D","t":"導尿管尿路感染。"},{"k":"E","t":"麻醉後肺擴張不全。"}],"answer":"A","expl":"脾切除後術後 2–3 日發燒最常見的是 atelectasis、輸血或藥物反應、導管相關感染（IV line、Foley）；intraabdominal abscess 通常在術後 5–10 天出現，所以 (A) 較不可能。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-20","year":101,"qnum":20,"topic":"影像FAST","subtopic":"總論／其他","stem":"使用全身電腦斷層 (whole body CT Scan) 檢查外傷病患，可幫助診斷頭、胸、腹部外傷，但對於下列那一項診斷並無幫助？","opts":[{"k":"A","t":"肝臟鈍傷破裂出血(Blunt liver injury)。"},{"k":"B","t":"腸道破裂(intestine perforation)。"},{"k":"C","t":"肺部鈍挫傷(Pulmonary contusion)。"},{"k":"D","t":"胸部心臟大血管(Great vessel injury)。"},{"k":"E","t":"心臟鈍挫傷(Blunt cardiac injury)。"}],"answer":"E","expl":"全身 CT 對 blunt liver injury、腸穿孔、pulmonary contusion 與大血管損傷有很好的診斷價值，但對 blunt cardiac injury 沒有幫助，需靠 ECG、troponin 與 echocardiography，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-21","year":101,"qnum":21,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"下列有關”persistent inflammation and catabolism syndrome (PICS)”之敘述何者為非？","opts":[{"k":"A","t":"目前對於此類病人，仍無有效之治療方式。"},{"k":"B","t":"“Physical examination and lab examination”因無法診斷出較細微病變，必須以臨床診斷為主。"},{"k":"C","t":"“Multiple-organ failure (MOF)”為最可能之原因。"},{"k":"D","t":"病人臨床之症狀如”absent bowel sound; increased abdominal tenderness”等為使用”CT”檢查之適應症。"},{"k":"E","t":"病人因重傷後造成“Immunity change-immunosuppression”，為最可能的原因。"}],"answer":"C","expl":"PICS（persistent inflammation, immunosuppression and catabolism syndrome）是重症 chronic critical illness 的後期狀態，重點是持續低度發炎、免疫抑制與蛋白質異化。官方答案 (C) 判斷「MOF 為最可能原因」為非。","outdated":false,"suspect":true,"flagNote":"這題的選項 (B)(D) 與 PICS 無關，內容像是從「delayed small bowel perforation」題目複製（見 99-19），可能是命題時的錯置，所以本題參考價值有限。考試以官方 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"101-22","year":101,"qnum":22,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"下列有關”Abdominal Damage Resuscitation ” 之敘述何者為非？","opts":[{"k":"A","t":"Correction of coagulopathy。"},{"k":"B","t":"”Damage Resuscitation ”之原則不適用於嚴重腹部急症(非外傷性) 。"},{"k":"C","t":"Reoperation。"},{"k":"D","t":"Rewarming。"},{"k":"E","t":"Correction of metabolic acidosis。"}],"answer":"B","expl":"Damage control resuscitation（矯正 coagulopathy、保暖、矯正 acidosis、再手術）的原則也適用於非創傷性的嚴重腹部急症（如破裂的腹主動脈瘤、大量消化道出血），所以 (B)「不適用」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-23","year":101,"qnum":23,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"有關嚴重胸腹外傷病患之急救處理，請選出正確敘述？","opts":[{"k":"A","t":"所有傷患均應該使用”Damage Resuscitation” 且無例外。"},{"k":"B","t":"輸液以”crystalloid”為最佳選擇。"},{"k":"C","t":"“permissive hypotension”觀念可應用於重傷急救。"},{"k":"D","t":"”Damage Resuscitation”之觀念僅適用胸腹外傷領域。"},{"k":"E","t":"手術方式之選擇不必考慮病人之生理狀況。"}],"answer":"C","expl":"同 98-12：現行 damage control resuscitation 主張 permissive hypotension、balanced blood products、限制晶體液，所以 (C)。例外為 TBI 與 SCI，仍需維持較高灌流壓。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-24","year":101,"qnum":24,"topic":"腹部","subtopic":"脾臟","stem":"有關”Splenic artery embolization ”用於脾創傷治療之敘述，請選出錯誤者？","opts":[{"k":"A","t":"“Splenic artery embolization”可適用於老年人。"},{"k":"B","t":"“CT scan” 發現”contrast extravasation”為採用” Splenic artery embolization” 重要考慮因素。"},{"k":"C","t":"“Splenic artery embolization”可以保留脾臟免疫功能。"},{"k":"D","t":"“Selective splenic artery embolization”後引起之”Splenic infarct”會增加病人死亡率。"},{"k":"E","t":"“Splenic artery embolization”仍可用於”high grade” 脾創傷病患。"}],"answer":"D","expl":"Splenic artery embolization 可保留脾臟功能，且可用於老年人與 high-grade 脾損傷（需依血行動力學與 CT blush 判斷）；SAE 後出現 splenic infarct 通常是局部、輕微，並未被證實會增加死亡率，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-25","year":101,"qnum":25,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"一名 8 歲男童，於上學途中被機車攔腰撞上，男童翻滾多圈後倒地不起。被救護車送來急診時生命跡象體溫 36.7°C，呼吸 30 次/分鐘，心跳 125 次/分鐘，血壓 82/65 mmHg。病人意識模糊無法表達，以下關於小兒外傷急救，何者最不適當？","opts":[{"k":"A","t":"若周邊血管無法打上，於此病人可考慮 intraosseous 的方式，若發現脛骨骨折，可以打同邊的末端股骨。"},{"k":"B","t":"可給予 crytalloid 每次 20ml/kg，目標為尿量 1.5ml/kg/hr。"},{"k":"C","t":"由於兒童胸壁骨骼較有彈性，導致胸部挫傷時，較不易發生壓力性氣胸(tension pneumothorax)。"},{"k":"D","t":"按照此病人的生命跡象，流失血量應有大於 30%。"},{"k":"E","t":"首要之務為保護呼吸道，若要選擇氣管內管，則可選大小為 5~5.5 號，有 cuff 的氣管內管。"}],"answer":"C","expl":"兒童胸壁較有彈性，傳遞到肺的能量更大，且縱隔較易移動，因此較容易發生 tension pneumothorax，所以 (C) 錯。(A) 脛骨骨折時用同側下肢以外的 IO 位置（對側脛骨／股骨遠端）；(B) 起始 20 mL/kg，尿量目標約 1–2 mL/kg/hr；(D) 失血量 >30%；(E) 8 歲 cuffed ETT 約 5.5。補充：ATLS 10 建議初始 20 mL/kg 晶體液後盡早給血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-26","year":101,"qnum":26,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"35 歲婦人懷孕 24 週、體重 65 公斤，於人行道遭腳踏車擦撞腹部，被救護車送來急診時，體溫 36.7℃，呼吸 23 次/分鐘，心率 110 次/分鐘，血壓 120/80 mmHg。病人主訴劇烈下腹痛並感覺有宮縮。理學檢查發現下腹壓痛但無反彈痛合併陰道少量出血，以下關於此孕婦敘述何者錯誤？","opts":[{"k":"A","t":"孕婦不知自己的血型，但已知孕婦丈夫的血型為 type O Rh(-)，因此不論驗出產婦的血型為何，都不需要給予 Rh D immuneglobulin。"},{"k":"B","t":"外傷引起胎兒最常見的死因為母親死亡，第二常見為胎盤前置。"},{"k":"C","t":"安胎藥可能會影響到初步創傷評估。"},{"k":"D","t":"雖然此孕婦的血壓仍在正常範圍，但其出血量仍有可能超過 1500ml。"},{"k":"E","t":"若母親在急診處置後仍不幸心跳停止，可考慮緊急剖腹生產。"}],"answer":"B","expl":"胎兒死亡最常見原因是母親死亡，其次是 placental abruption（胎盤早期剝離），不是前置胎盤，所以 (B) 錯。(A) 丈夫為 Rh(-) 時胎兒必為 Rh(-)，不會被母親 Rh 抗體傷害，所以不需要 RhIG；(C) tocolytics 可能掩蓋休克徵象；(D) 孕婦失血 1500 mL 仍可能血壓正常；(E) 心跳停止後 4–5 分鐘內考慮 perimortem cesarean。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-27","year":101,"qnum":27,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"6 歲女童騎乘腳踏車被公車由左側攔腰撞上，女童並沒有戴安全帽且在地上翻滾多圈，送來急診時生命跡象體溫 36.7ºC，呼吸 22 次/min，心跳 140 次/min，血壓 87/40 mmHg，病人昏迷指數為 E2V3M4，身體檢查主要發現頭部及臉部多處擦傷及血腫，胸部發現有擦傷，以下關於此病人的處理，下列敘述何者錯誤?","opts":[{"k":"A","t":"小兒頸椎骨折以低位頸椎為主，若無恰當頸圈使用，可以長背板替代。"},{"k":"B","t":"插管和成人不同處其中一項為 subglottic 較為狹窄。"},{"k":"C","t":"即使此病患經口氣管插管失敗，仍不建議 cricothyrotomy。"},{"k":"D","t":"初步輸液可給予 20 mL/kg 的 crystalloid。"},{"k":"E","t":"胸部挫傷的嚴重度，不能以有無肋骨骨折決定。"}],"answer":"A","expl":"兒童頸椎損傷以上位頸椎（C1–C3，因頭相對大）為主，不是低位頸椎，所以 (A) 錯。同時 backboard 不能取代適當尺寸的頸圈。(B) 兒童 subglottic 最窄；(D) 起始 20 mL/kg 晶體液；(E) 胸部挫傷嚴重度不能以有無肋骨骨折決定。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-28","year":101,"qnum":28,"topic":"小兒","subtopic":"總論／其他","stem":"1歲半大的女童由約1公尺高的桌上不慎摔落，頭部撞到地板，立刻嚎啕大哭，整個過程並無意識喪失現象，至急診室檢查其他四肢活動及行為大致正常，下列何項陳述正確？","opts":[{"k":"A","t":"考量病童年齡較小，為減少放射線的暴露，只安排頭部X光片即可。"},{"k":"B","t":"在急診室觀察3小時後，若無異常現象發現，可讓病童安心離院，回家觀察。"},{"k":"C","t":"若頭部外觀檢查無明顯外傷、頭部X光片檢查無異常，就可讓病童安心離院回家觀察。"},{"k":"D","t":"嬰兒頭部與軀幹比例較成人大，顱骨又較成人薄，所以發生頭骨骨折的機會較高。"},{"k":"E","t":"此病童頭部受傷後並無意識喪失現象，發生顱內出血的機率很低，不需安排額外檢查。"}],"answer":"D","expl":"1.5 歲小兒由 1 公尺高處摔下，頭骨較薄、頭相對於身體比例大，頭骨骨折機率較高，所以 (D)。是否需要 CT 可依 PECARN 規則決定；單純頭部 X-ray 診斷價值有限，不能以此決定回家。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-29","year":101,"qnum":29,"topic":"小兒","subtopic":"總論／其他","stem":"六歲男童過馬路時，遭到酒駕闖紅燈的汽車撞擊受傷；送至急診室時，主訴肚子疼痛，身體檢查發現血壓70/40 mmHg、心跳每分鐘180次、腹部緊繃合併觸痛，若收縮壓持續低於90 mmHg，下列何項為最適當的輸液方式(病人體重約25公斤)？","opts":[{"k":"A","t":"先輸注250 cc溫的等張晶體溶液，血壓持續偏低就須輸250 cc的紅血球濃厚液(packed RBC)。"},{"k":"B","t":"先輸注500 cc溫的等張晶體溶液，血壓持續偏低就須輸250 cc的紅血球濃厚液。"},{"k":"C","t":"先輸注250 cc溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸250 cc的紅血球濃厚液。"},{"k":"D","t":"先輸注500 cc溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸250 cc的紅血球濃厚液。"},{"k":"E","t":"先輸注500 cc溫的等張晶體溶液，必要時可再重覆輸注二次，血壓持續偏低就須輸500 cc的紅血球濃厚液。"}],"answer":"D","expl":"兒童出血性休克：20 kg 以上以 20 mL/kg 計算，25 kg 為 500 mL 晶體液；若仍低血壓，輸 10 mL/kg pRBC（250 mL）。官方答案 (D) 允許重複晶體液兩次後輸血。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議起始 20 mL/kg 晶體液最多一次，仍不穩定就盡快 10 mL/kg pRBC，不再重複晶體液（避免 dilutional coagulopathy）。官方答案 (D) 不變，但臨床請依 ATLS 10/11。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"101-30","year":101,"qnum":30,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"25歲懷孕32週女性，配戴安全帶駕駛小客車，被時速25公里的公車從後追撞，安全氣囊爆開，車身沒有明顯損害，病人無神智喪失(loss of consciousness)，病人在車禍現場可以走動，只有抱怨頸部疼痛；接著病人戴上頸圈，躺在長背板上，由救護車送至急診室，身體理學檢查發現第五、六頸椎壓痛，下列敘述何者正確？","opts":[{"k":"A","t":"產婦配戴安全帶駕駛發生車禍，發生早產的機會比未配戴安全帶者高。"},{"k":"B","t":"病人接受基本外傷評估、確認胎兒心音及活動正常後，即可安全離院。"},{"k":"C","t":"病人不宜接受頸部X-Ray檢查，以防放射線可能造成胎兒畸形。"},{"k":"D","t":"病人不應繼續躺在長背板上，應該改躺在一般的病床以改善胎兒循環。"},{"k":"E","t":"病人接受外傷評估後，仍須接受胎兒心音監視6小時以上，才可以離院。"}],"answer":"E","expl":"同 99-42：孕 ≥20 週受外傷，即使表面看似輕微，也應做至少數小時的 cardiotocographic monitoring，官方答案 (E)（6 小時以上）。補充：ATLS 10 建議至少 4 小時，如有宮縮、陰道出血或母體不穩定需延長至 24 小時。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-31","year":101,"qnum":31,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"在胸部穿刺傷時，緊急初步之檢查有以下之發現即可高度懷疑張力性氣胸 (tension pneumothorax)，除了：","opts":[{"k":"A","t":"無呼吸音。"},{"k":"B","t":"氣管偏移。"},{"k":"C","t":"胸部 X 光。"},{"k":"D","t":"皮下氣腫。"},{"k":"E","t":"頸靜脈搏動上升。"}],"answer":"C","expl":"Tension pneumothorax 是臨床診斷（無呼吸音、氣管偏移、頸靜脈怒張、皮下氣腫、低血壓），不需要等 chest X-ray，所以 (C) 不屬於「緊急初步檢查發現」。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-32","year":101,"qnum":32,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"在胸部創傷的病人，下列因子都會使發病率及死亡率升高，除了：","opts":[{"k":"A","t":"連枷胸 flail chest。"},{"k":"B","t":"外傷嚴重度分數 (injury severity score, ISS) 。"},{"k":"C","t":"輸血量增加。"},{"k":"D","t":"肺挫傷。"},{"k":"E","t":"換氣不足 (hypoventilation) 。"}],"answer":"E","expl":"胸部創傷的死亡率與 flail chest、ISS、輸血量增加、pulmonary contusion 與高齡等因子有關；官方答案 (E) hypoventilation 被認為「不是」風險因子。","outdated":false,"suspect":true,"flagNote":"Hypoventilation（或呼吸衰竭）本身常是胸傷後併發低氧與高碳酸血症的原因與結果，一般不會說它不增加發病率，所以此題用語模糊，可能是引用特定研究的因子分析，答案有疑義。考試仍以官方 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"101-33","year":101,"qnum":33,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"胸部創傷引起的主動脈剝離(Aortic dissection)在 X 光片上所顯示的放射跡象 (radiologic signs)，下列何者為非：","opts":[{"k":"A","t":"縱隔增寬 (widened mediastinum) 。"},{"k":"B","t":"氣管偏移。"},{"k":"C","t":"左支氣管上移。"},{"k":"D","t":"第一或第二肋骨或者是肩胛骨骨折。"},{"k":"E","t":"右支氣管上移。"}],"answer":"C","expl":"Blunt aortic injury 的 CXR 徵象：縱隔增寬、氣管右偏、aortic knob 模糊、left mainstem bronchus depression（向下壓低）、胸骨／第一二肋骨／scapula 骨折、left apical cap 等，不是「左支氣管上移」，所以 (C) 非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-34","year":101,"qnum":34,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"下列有關胸部外傷之敘述何者為非?","opts":[{"k":"A","t":"鏈伽胸(Flail chest)造成缺氧主要機轉為胸部不正常呼吸運動(paradoxical movement)影響氣體交換。"},{"k":"B","t":"當胸管放置後，引流血量大於 1500 毫升稱為大量血胸，頓挫傷及穿刺傷都可能造成大量血胸，其中以穿刺傷為主要造成原因。"},{"k":"C","t":"有關急診行緊急剖胸術，胸部穿刺性外傷患者較鈍傷患者有較好之預後，如果傷患在事故現場已無生命跡象，則不應再行剖胸術急救，因其成效有限。"},{"k":"D","t":"嚴重胸部外傷而影響循環(circulation)常見的原因為大量血胸及心包膜填塞。"},{"k":"E","t":"創傷性膈疝(Traumatic Diaphragmatic Hernia)左側比較容易發生，急性期手術治療宜採剖腹探查術；慢性外傷性橫膈疝氣手術治療以從胸部探查較佳。"}],"answer":"A","expl":"同 100-13：flail chest 低血氧主要來自 pain-limited ventilation 與下方 pulmonary contusion，不是 paradoxical movement 本身，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-35","year":101,"qnum":35,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一位 60 歲男性，在車禍中前胸猛烈撞擊方向盤，被送達急診室時主訴胸痛，他的血壓為60/40 mmHg，呼吸速率為每分鐘 40 次，下列敘述何者有誤 ?","opts":[{"k":"A","t":"病人的低血壓經臨床判斷可能肇因於張力性氣胸或心包填塞(cardiac tamponade)，兩者可以氣管位置是否偏移、呼吸音有無來區分。"},{"k":"B","t":"Beck's triad、Kussmaul's sign 常出現於心包膜填塞病患。"},{"k":"C","t":"張力性氣胸及大量血胸都伴隨有呼吸音降低現象，但可以敲診方式來區分兩者之不同"},{"k":"D","t":"FAST 可以快速而正確診斷心包膜填塞，但偽陰性機會約為 5-10%，當懷疑有心包膜填塞時，輸液給予要限制，避免過多輸液加劇病況。"},{"k":"E","t":"持續需輸血維持生命徵象為開胸適應症之一。"}],"answer":"D","expl":"Cardiac tamponade 時，適度輸液可暫時增加 preload、維持心輸出量，所以不應「限制輸液」，(D) 錯。其餘為標準：tension pneumothorax 與 tamponade 可用氣管位置、呼吸音、敲診區分；FAST 診斷 tamponade 可靠（偽陰性 5–10%）；持續需要輸血維持生命徵象屬開胸適應症。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-36","year":101,"qnum":36,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"一位30 歲之年輕人因右胸槍傷而被送到一地區醫院，在急診室插入胸管後，立刻有 1000 cc的鮮血流出，在轉送往創傷中心(trauma center)治療前，他的血壓突然掉到 80/60 mmHg，且心跳劇增到每分鐘 138 次，下列敘述何者有誤？","opts":[{"k":"A","t":"出血可能原因為肺撕裂傷、肋間血管損傷、內乳動脈損傷。"},{"k":"B","t":"胸椎骨折移位也可能造成血胸，不過大多可以自行恢復。"},{"k":"C","t":"緊急安排胸部電腦檢查，確定出血原因及可能受傷部位，以利後續處理。"},{"k":"D","t":"此時應採取的緊急措施為重覆評估檢查傷者，並快速輸血。"},{"k":"E","t":"胸部 X 光發現有明顯血胸時，胸管放置是必要的，以利後續處置及減少併發症。"}],"answer":"C","expl":"右胸槍傷、胸管一次引流 1000 mL 血，隨後休克惡化，是 massive hemothorax／ongoing bleeding，要立即復甦（輸血）並準備緊急開胸；病人不穩定時不應再去做 CT，所以 (C) 錯。(A) 為常見出血源；(E) 明顯血胸時放胸管為必要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-37","year":101,"qnum":37,"topic":"胸部","subtopic":"總論／其他","stem":"關於肺部鈍傷之敘述何者為非?","opts":[{"k":"A","t":"症狀在受傷後 72 小時達到最高峰。"},{"k":"B","t":"此類病患往往需要使用插管呼吸機治療，Tidal volume 設定為 6 mL/kg。"},{"k":"C","t":"End-inspiratory plateau pressure above 30 cmH2O。"},{"k":"D","t":"預防性抗生素與類固醇在處理此類病患角色並不明確。"},{"k":"E","t":"支持性治療效果以 oxygenation capabilities 及 ventilation 為指標。"}],"answer":"C","expl":"Pulmonary contusion 的保護性通氣策略是 low tidal volume（約 6 mL/kg）並讓 plateau pressure <30 cmH2O，所以 (C)「plateau pressure above 30」為錯。(A) 症狀常在 24–72 小時達高峰；(D) 預防性抗生素與 steroid 沒有明確角色。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-38","year":101,"qnum":38,"topic":"胸部","subtopic":"Tracheobronchial injury","stem":"關於 Tracheobronchial injuries 之敘述何者為非?","opts":[{"k":"A","t":"最常發生的位置在離 Carina 2.5 cm 距離以外。"},{"k":"B","t":"常出現的症狀為 Stridor，Hemoptysis 及 Cervical subcutaneous emphysema。"},{"k":"C","t":"做氣管插管時有導入穿孔處的疑慮。"},{"k":"D","t":"在呼吸機的使用上不建議用正壓呼吸(Positive pressure ventilator)。"},{"k":"E","t":"要確定 Tracheobronchial injuries 需要做支氣管鏡檢查。"}],"answer":"A","expl":"氣管支氣管損傷多在 carina 2.5 cm 以內（主支氣管近端），不是距離 carina 2.5 cm 以外，所以 (A) 錯。(B)(C)(E) 為標準描述；(D) 若必須使用 positive pressure，要小心，盡量選擇性單肺通氣並避免高壓，題目只說「不建議」。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-39","year":101,"qnum":39,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"關於 Esophageal injuries 之敘述何者為非?","opts":[{"k":"A","t":"Esophageal upper and middle third thoracic injuries 可以從 left 4th-5th interspace posterolateral thoracotomy approach。"},{"k":"B","t":"Esophageal distal third injuries 可以從 left 6th interspace posterolateral thoracotomy approach。"},{"k":"C","t":"病患如果在 24 小時內接受診斷及手術治療,可以考慮做 primary repair with single layer suture 。"},{"k":"D","t":"病患如果有 local inflammation, contamination and severity of injury 就不考慮做 primary repair with single layer suture 。"},{"k":"E","t":"針對於嚴重 Esophageal injuries 病患我們可以採用 wide drainage with chest tube 及鼻胃管置放引流術即可。"}],"answer":"A","expl":"食道損傷的手術路徑：上段與中段胸段食道經右側開胸（右 4–5 肋間）最容易暴露，遠端三分之一則走左側 6–7 肋間；所以 (A) 把上、中段寫成「左 4–5 肋間」為錯。(C) 24 小時內診斷可 primary repair；(E) 嚴重者可用 wide drainage。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-40","year":101,"qnum":40,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"有關頭部外傷非手術治療 (nonsurgical therapies for brain injury) 之敘述，以下何者有誤？","opts":[{"k":"A","t":"腦的灌流維持好，腦細胞才有機會恢復功能；否則，腦組織會死亡。所以點滴的給予應足夠，但也不可太多。"},{"k":"B","t":"過度通氣(Hyperventilation)，會使 CO2 分壓下降，讓腦血管收縮，進而降低顱內壓，故適合用來長期控制腦壓。"},{"k":"C","t":"目前尚無證據顯示使用類固醇對嚴重頭部外傷患者有好處，因此不建議在該類患者使用類固醇。"},{"k":"D","t":"抗癲癇藥物的使用，只能有效預防早發性癲癇，但超過七天的遲發性癲癇，不會因為用了藥而不發生。"},{"k":"E","t":"腦壓 (ICP) 在 25 mmHg 以下就算可以接受，即使因躁動或咳嗽等使得 ICP 太高，只要能自己回復正常就沒關係。"}],"answer":"B","expl":"長期 hyperventilation 會造成腦血管過度收縮與缺血，已不建議使用，只在 herniation 時短暫用於救命，所以 (B) 錯。(C) steroid 無益（CRASH trial）；(D) 抗癲癇藥只能預防早發性（7 天內）癲癇。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-41","year":101,"qnum":41,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"下列關於頭部外傷的敘述，何者有誤？","opts":[{"k":"A","t":"如果 skull x-ray 發現骨折，但病患無明顯症狀，仍應安排 head CT，以排除顱內出血。"},{"k":"B","t":"治療病患只能針對 secondary injury 處理，除非預防外傷的發生，對於 primary injury，醫護人員是無能無力的。"},{"k":"C","t":"頭部外傷過於嚴重者，要判定腦死，應符合 GCS 3 分、無腦幹反射且呼吸中止測試時無自發性呼吸運動等條件。"},{"k":"D","t":"腦壓上升，常是因為受傷後的腦血管通透性增加，造成腦水腫、引起腦部 autoregulation受損，代謝異常、腦細胞腫脹，惡性循環的結果。"},{"k":"E","t":"如果 ICP 持續太高，長期使用 Mannitol 持續灌注可得到不錯的降壓效果。"}],"answer":"E","expl":"Mannitol 長期持續灌注會造成 rebound、腎毒性與電解質失衡，不建議，應間歇投予，所以 (E) 錯。(A) X-ray 見 skull fracture 需 CT；(B) TBI 治療重點是預防 secondary injury；(C) 腦死判定條件；(D) 為腦壓上升的惡性循環。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-42","year":101,"qnum":42,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"腦外傷病人器捐之議題何者正確?","opts":[{"k":"A","t":"移植醫師應主動參與判定腦死。"},{"k":"B","t":"主治醫師不可判定腦死。"},{"k":"C","t":"須通報檢察官。"},{"k":"D","t":"心臟停止跳動為死亡時間。"},{"k":"E","t":"家屬若已簽署同意書即可摘取器官。"}],"answer":"C","expl":"外傷或意外所致的腦死病人，屬非自然死亡，依法需通報檢察官（相驗與同意取出器官流程），所以 (C)。(A) 移植醫師不得參與判定腦死（避免利益衝突）；(D) 台灣以腦死判定為死亡的法律程序依「人體器官移植條例」；(E) 家屬同意書尚不足夠，還需完成法定判定程序。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-43","year":101,"qnum":43,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"多重外傷病患: 診斷急性硬腦膜下出血、脾臟破裂併右股骨骨折。術後 1 小時，昏迷指數E2M5Vt，BP:100/60mmHg，HR:120/min，ICP:28 mmHg，FiO2:40%，SaO2:98% 下列何者正確?","opts":[{"k":"A","t":"ICP 適當。"},{"k":"B","t":"須限水避免腦水腫。"},{"k":"C","t":"血壓太低。"},{"k":"D","t":"腦灌流壓太低。"},{"k":"E","t":"以上皆非。"}],"answer":"D","expl":"CPP = MAP − ICP。BP 100/60 → MAP ≈ 73 mmHg，ICP 28，CPP ≈ 45 mmHg（<60），所以腦灌流壓太低，答案 (D)。ICP >20–22 mmHg 需要治療。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-44","year":101,"qnum":44,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"續上題：下列何者處置最不適當?","opts":[{"k":"A","t":"追蹤頭部電腦斷層。"},{"k":"B","t":"給 mannitol。"},{"k":"C","t":"降體溫至攝氏 35 度。"},{"k":"D","t":"升血壓。"},{"k":"E","t":"追蹤 FAST 超音波。"}],"answer":"C","expl":"腦灌流壓不足時，要提高 MAP（vasopressor 或補液）、降 ICP（mannitol／hypertonic saline、head elevation、sedation）、追蹤 CT 與 FAST（脾臟破裂病人）；預防性降溫至 35°C 並不能改善預後（Eurotherm3235 反而顯示有害），所以 (C) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-45","year":101,"qnum":45,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷會引起身體重大的新陳代謝與內分泌變化，臨床表現不包括下列何項敘述：","opts":[{"k":"A","t":"新陳代謝與內分泌的變化與疾病嚴重度成正相關。"},{"k":"B","t":"基礎新陳代謝率大大提升，與疾病嚴重度成正相關。"},{"k":"C","t":"大量脂肪燃燒，以作為主要的燃料來源。"},{"k":"D","t":"醣質新生加上胰島素抗性所導致的高血糖。"},{"k":"E","t":"蛋白質分解大於合成，呈現負氮平衡。"}],"answer":"C","expl":"同 99-10：創傷後代謝反應的重點是 hypermetabolism、insulin resistance、protein catabolism；官方答案 (C) 認為「脂肪為主要能量來源」不屬於創傷後的代謝反應。","outdated":false,"suspect":true,"flagNote":"創傷後 lipolysis 與 fat oxidation 其實也會增加，所以 (C) 的對錯偏向命題者的取捨；考試以官方 (C) 為準，臨床知識請記 mixed-fuel 與蛋白質異化。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"101-46","year":101,"qnum":46,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，不必考量系統性的穩定度(systemic stabilization) 。"},{"k":"D","t":"燙傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"早期 enteral feeding 好處多（調節發炎、保護黏膜屏障、增強免疫），但仍需先達到 systemic stabilization（血流動力學穩定、足夠復甦），休克未控制時餵食可能造成腸缺血，所以 (C)「不必考量穩定度」為錯。燙傷患者可在 4–6 小時內開始 enteral feeding；胃輕癱時可改 post-pyloric feeding。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-47","year":101,"qnum":47,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列敘述何者為誤：","opts":[{"k":"A","t":"因為出血、組織受傷所引起了一連串的身體反應，一開始多以 hyperinflammatory state為主，之後可能進展為 immunosupression state。"},{"k":"B","t":"患者在嚴重創傷後呈現免疫功能低下，主要是以 humoral hypo-immunity 為主。此時期容易因發生嚴重感染而導致多重器官衰竭。"},{"k":"C","t":"嚴重創傷後所引起的大量發炎物質及細胞激素產生，除部分來自受傷組織外，其餘多來自胃腸道。"},{"k":"D","t":"麩胺酸是一重要的免疫營養素，有助於滋養胃腸道及免疫細胞，並促進傷口癒合。"},{"k":"E","t":"精胺酸是一重要的免疫營養素，有助於免疫細胞的增殖以及傷口癒合。"}],"answer":"B","expl":"創傷後免疫抑制主要表現為 cell-mediated immunity（T cell、monocyte HLA-DR）下降，而不是以 humoral hypo-immunity 為主，所以 (B) 錯。(A) 先 hyperinflammatory（SIRS），後 CARS；(C) 腸道在 gut hypothesis 中為炎症介質來源；(D)(E) glutamine、arginine 為免疫營養素。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-48","year":101,"qnum":48,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"病人為一24 歲男性因騎機車與計程車對撞，神智不清經腦部電腦斷層檢查有腦外傷性蜘蛛膜下腔出血，右胸部有血胸及右側大腿股骨骨折，此病人之外傷嚴重度分數評分表(Injury severity score, ISS)共幾分？","opts":[{"k":"A","t":"22+22+22=12。"},{"k":"B","t":"32+32+32=27。"},{"k":"C","t":"42+42+42=48。"},{"k":"D","t":"22+32+42=29。"},{"k":"E","t":"22+32+22=27。"}],"answer":"B","expl":"ISS 取三個不同身體區域最高 AIS 的平方和：head（traumatic SAH）AIS 3、chest（hemothorax）AIS 3、extremity（femur fracture）AIS 3，所以 3² + 3² + 3² = 27，選 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-49","year":101,"qnum":49,"topic":"頭部TBI","subtopic":"創傷後癲癇","stem":"頭部外傷病人發生抽筋，早期使用藥物卻未能控制，超過多少時間則會導致續發性腦損傷？","opts":[{"k":"A","t":"5 分至10 分。"},{"k":"B","t":"10 分至20 分。"},{"k":"C","t":"20 分至 30 分。"},{"k":"D","t":"30 分至 60 分。"},{"k":"E","t":"與抽筋發作時間無關。"}],"answer":"D","expl":"癲癇持續超過 30 分鐘（status epilepticus）會造成不可逆神經元損傷與 secondary brain injury，所以 (D)；癲癇一旦發作需立即 benzodiazepine，再加 phenytoin/levetiracetam。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"101-50","year":101,"qnum":50,"topic":"頭部TBI","subtopic":"腦死判定與器官捐贈","stem":"頭部外傷病人，腦死判定有經低溫療法(Hypothermia)及巴比妥藥物昏迷療法(Barbiturate coma)腦死判定結果為？","opts":[{"k":"A","t":"不受上述兩類療法影響。"},{"k":"B","t":"病人體溫恢復正常即可判定。"},{"k":"C","t":"需等病人生理參數恢復正常及腦中樞神經不受藥物影響才能判定。"},{"k":"D","t":"兩側瞳孔放大，對光無反射應即可判定。"},{"k":"E","t":"昏迷指數 3 分即可判定。"}],"answer":"C","expl":"腦死判定前須排除可逆因素：低體溫、鎮靜／巴比妥類藥物影響、休克與代謝異常；需等生理參數恢復並確認藥物已代謝完，才能判定，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-1","year":102,"qnum":1,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"30歲男性於工作時由4公尺高之平台跌落至地面，送抵急診時意識混亂、心跳為150/min、收縮血壓60mmHg，病患外觀無明顯出血及四肢變形，超音波檢查並無發現有血胸、心包膜積血或腹腔內出血，骨盆檢查發現為不穩定之骨盆骨折，經緊急氣管內管置入、輸液2,000cc並使用床單固定骨盆後，心跳及血壓皆無改善；\n若本院並無可執行動脈栓塞之能力，且將病患轉診至最近可執行動脈栓塞之B醫院需時60分鐘，以下處置何者最適當？","opts":[{"k":"A","t":"通知B醫院並準備 10 單位之全血，立即將病患立即轉院。"},{"k":"B","t":"安排電腦斷層檢查查看是否有其他損傷。"},{"k":"C","t":"通知外科醫師執行雙側髂內動脈結紮手術。"},{"k":"D","t":"先執行 preperitoneal packing 並重新以床單固定骨盆後，將病患立即轉院。"},{"k":"E","t":"以上皆可。"}],"answer":"D","expl":"不穩定骨盆骨折合併休克，已用 binder 與輸液仍無改善，且 FAST 無腹內出血，本院無法做 angioembolization 時，先做 preperitoneal pelvic packing 並維持 binder，再轉院，所以 (D)。補充：REBOA 也是替代選項；轉院前不必再做 CT。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-2","year":102,"qnum":2,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"34歲年輕婦女，與先生爭執，被踢中腹部與腰部，因疼痛就醫。血壓 124/70 mmHg心跳98/min，腹部明顯反彈徵(rebounding pain)，腹部 CT顯示右上腹肝臟周遭有游離氣(free air)，合併腹內液體(intraperitoneal fluid)。經診斷腹部鈍挫傷，並有臟器破裂。下列敘述何者最適當？","opts":[{"k":"A","t":"腹部鈍挫傷，生命徵象穩定，如為肝臟、脾臟出血，可選擇保守性非手術治療(selective non-op.)。但本例宜採剖腹探查治療(laparotomy)。"},{"k":"B","t":"剖腹探查發現僅為肝臟右葉表淺撕裂傷(Grade II)，已無持續出血，但為避免感染仍應行右肝葉切除手術，其結果最好。"},{"k":"C","t":"剖腹探查發現十二指腸第二部份(2nd portion)約近四分之三斷裂，十二指腸相對少見，簡單縫合即可。"},{"k":"D","t":"因十二指腸約近四分之三斷裂，無法排除胰臟頭傷害，將行胰頭十二指腸切除術(Whipple’s Op) 最適當。"},{"k":"E","t":"剖腹探查術後傷口較大，可以腹腔鏡手術(laparoscope op.)取代。"}],"answer":"A","expl":"同 100-12：穩定的肝脾傷可 NOM，但本例 CT 有 free air、腹腔積液且有 peritonitis，提示空腔臟器損傷，宜 laparotomy，所以 (A)。肝 grade II 不需切除；十二指腸 3/4 斷裂需要處理，不能只簡單縫合；也不需要一律 Whipple。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-3","year":102,"qnum":3,"topic":"ICU營養併發症","subtopic":"VTE（靜脈血栓栓塞）預防","stem":"下列有關靜脈血栓栓塞症(venous thromboembolism, VTE)之敘述何者為非？","opts":[{"k":"A","t":"臨床症狀不可靠；常常是無症狀。"},{"k":"B","t":"創傷傷患住院中死亡原因第三常見。"},{"k":"C","t":"D-dimer 檢驗為 negative (< 500) 加上標準化評估為低度可能者，可以排除VTE。"},{"k":"D","t":"使用heparin來預防VTE。"},{"k":"E","t":"創傷後不動(immobilization)是造成VTE的一大原因。"}],"answer":"D","expl":"創傷病人住院期間 PE 為重要的死因之一，預防建議使用 LMWH（或 UFH）搭配機械性預防；D-dimer 在創傷病人幾乎都會上升，不能用來排除 VTE。官方答案 (D)「使用 heparin 預防 VTE」被視為錯。","outdated":false,"suspect":true,"flagNote":"依 EAST 與現行指引，LMWH（enoxaparin）為創傷病人 VTE 預防的建議，heparin 預防並非錯誤；反而 (C)「D-dimer 陰性可排除 VTE」在創傷病人不可靠。答案 (D) 很可能是命題或 OCR 問題。考試仍以官方 (D) 為準。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"102-4","year":102,"qnum":4,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"關於大量輸血(massive transfusion protocol)的敘述下列何者為非 Celiac axis。","opts":[{"k":"A","t":"大量輸血的定義為估計病人在24小時內可能需要輸血超過十個單位的 PRBC"},{"k":"B","t":"大量輸血的血品僅有 Packed RBC及 fresh frozen plasma。"},{"k":"C","t":"大量輸血可能會產生低體溫及低血鈣等併發症。"},{"k":"D","t":"輸血中需要密切監視是否有 hypofibrinogenemia必要時要補充 cryoprecipitate。"},{"k":"E","t":"Transfusion-related acute lung injury (TRALI)常發生在輸血後 1-2小時內病人出現低血氧及呼吸急促的現象。"}],"answer":"B","expl":"大量輸血（massive transfusion）定義為 24 小時內 >10 U pRBC，或 1 小時內 >4 U；血品除了 pRBC 與 FFP，還包括血小板與 cryoprecipitate／fibrinogen，所以 (B) 錯。(C) 併發症：低體溫、低血鈣、凝血異常、酸中毒；(E) TRALI 通常在輸血後 6 小時內。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-5","year":102,"qnum":5,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"A hemodynamically normal 10-year-old girl is admitted to the Pediatric Intensive Care Unit (PICU) for observation after a Grade III (moderately severe) splenic injury has been confirmed by computed tomography (CT). Which of the following mandates prompt celiotomy (laparotomy)?","opts":[{"k":"A","t":"A serum amylase of 200."},{"k":"B","t":"A leukocyte count of 14,000."},{"k":"C","t":"Extraperitoneal bladder rupture."},{"k":"D","t":"Free intraperitioneal air demonstrated on follow-up CT."},{"k":"E","t":"A fall in the hemoglobin level from 12 g/dL to 8 g/dL over 24 hours."}],"answer":"D","expl":"兒童 Grade III 脾臟傷 NOM 期間，若追蹤 CT 出現 free intraperitoneal air，代表有 hollow viscus injury，需要立即 laparotomy，所以 (D)。Amylase 輕度升高、白血球增加、extraperitoneal bladder rupture 不一定需手術；Hb 下降則依血流動力學處理（輸血、血管栓塞）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-6","year":102,"qnum":6,"topic":"頭部TBI","subtopic":"腦死判定與器官捐贈","stem":"嚴重腦外傷病人下列何項非腦死判定條件的臨床檢查診斷?","opts":[{"k":"A","t":"GCS昏迷指數=3。"},{"k":"B","t":"曈孔對光無反應。"},{"k":"C","t":"腦幹反射消失。"},{"k":"D","t":"無自然呼吸反應。"},{"k":"E","t":"去腦僵直反應。"}],"answer":"E","expl":"腦死判定的臨床條件：深度昏迷（GCS 3）、brainstem reflexes absent（瞳孔、角膜、gag、oculocephalic）與 apnea；decerebrate posturing（去腦僵直）表示腦幹仍有功能，所以不屬於腦死條件，答案 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-7","year":102,"qnum":7,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"下列關於 Injury severity score(ISS)的描述評論，何者最不恰當？","opts":[{"k":"A","t":"根源於 Abbreviated injury score(AIS)。"},{"k":"B","t":"將全身分為五個器官部位計分。"},{"k":"C","t":"最低1分，最高 75分。"},{"k":"D","t":"若有任何一項 AIS 6分，ISS會自動變為75分。"},{"k":"E","t":"台灣健保局將 ISS>9分列為重大外傷。"}],"answer":"E","expl":"ISS 最低 1 分、最高 75 分；任何 AIS 6 分直接為 75；官方答案指 (E)「健保署將 ISS >9 列為重大外傷」為錯（一般以 ISS ≥16 為 major trauma）。","outdated":false,"suspect":true,"flagNote":"選項 (B)「五個器官部位」本身也不正確：ISS 為六個身體區域（head/neck、face、chest、abdomen、extremities、external），在 95-32 也曾被認為錯誤。所以 (B)(E) 都有問題，官方答案以 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"102-8","year":102,"qnum":8,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"根據2012 年 Surviving Sepsis Campaign Bundles，下列敘述何者為非？","opts":[{"k":"A","t":"第一線強心劑首選為 Levophed。"},{"k":"B","t":"血糖控制目標 < 180 mg/dl。"},{"k":"C","t":"仍建議使用 hydroxyethyl starches 作為急救輸液。"},{"k":"D","t":"輸液灌注後仍低血壓者, 應給予強心劑， 維持平均動脈壓 ≥ 65 mm Hg。"},{"k":"E","t":"ScvO2 及血中 lactate 數值均可作為復甦成效的指標參考。"}],"answer":"C","expl":"Surviving Sepsis Campaign 2012 反對使用 HES（hydroxyethyl starch）作為復甦輸液（有腎傷害與死亡率增加風險），所以 (C) 錯。(A) 第一線血管收縮劑為 norepinephrine；(B) 血糖目標 <180；(D) MAP ≥65；(E) lactate 與 ScvO2 可作為指標。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-9","year":102,"qnum":9,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"A patient is brought to the emergency department after a motor vehicle crash. He is conscious and there is no obvious external trauma. He arrives at the hospital completely immobilized on a ling spine board. His blood pressure is 60/40mm Hg and his heart rate is 70 beats per minute. His skin is warm. Which one of the following statements is TRUE?","opts":[{"k":"A","t":"Vasoactive medications have no role in this patient’s management."},{"k":"B","t":"The hypotension should be managed with volume resuscitation alone."},{"k":"C","t":"Flexion and extension views of the c-spine should be performed early."},{"k":"D","t":"Abdominal visceral injures can be excluded as a cause of hypotension."},{"k":"E","t":"Flaccidity of the lower extremities and loss of deep tendon reflexes are expected."}],"answer":"E","expl":"病人低血壓、心跳不快（HR 70）、皮膚溫暖，符合 neurogenic shock／spinal cord injury，預期有 spinal shock（flaccid paralysis 與 areflexia），所以 (E)。(A) 需要 vasopressor；(B) 不能單靠輸液；(C) 不應做 flexion/extension view；(D) 仍需排除出血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-10","year":102,"qnum":10,"topic":"災難院前法規","subtopic":"總論／其他","stem":"全民健保於 100 年內因損傷及中毒而至急診就診的人數為?","opts":[{"k":"A","t":"492,157 人。"},{"k":"B","t":"692,157 人。"},{"k":"C","t":"892,157 人。"},{"k":"D","t":"1,092,157 人。"},{"k":"E","t":"1,492,157 人。"}],"answer":"E","expl":"這題是 100 年全民健保急診資料，屬於統計記憶題（損傷與中毒就診約 149 萬人次）。官方答案 (E)；不需要硬背此類數字，重點是外傷與中毒是急診主要就診原因之一。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-11","year":102,"qnum":11,"topic":"災難院前法規","subtopic":"總論／其他","stem":"全民健保於 100 年內至急診就診的人數若以疾病別來分析，「症狀、徵候及診斷欠明之病態」除外，因損傷及中毒就診率排名第幾?","opts":[{"k":"A","t":"損傷及中毒就診率排名第一，第二與第三分別為呼吸與循環系統疾病。"},{"k":"B","t":"損傷及中毒就診率排名第二，第一與第三分別為呼吸與消化系統疾病。"},{"k":"C","t":"損傷及中毒就診率排名第二，第一與第三分別為循環與呼吸系統疾病。"},{"k":"D","t":"損傷及中毒就診率排名第三，第一與第二分別為呼吸與循環系統疾病。"},{"k":"E","t":"損傷及中毒就診率排名第三，第一與第二分別為消化與呼吸系統疾病。"}],"answer":"A","expl":"同上，屬 100 年健保資料的統計題：官方答案為損傷及中毒就診率居第一，其次為呼吸與循環系統疾病，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-12","year":102,"qnum":12,"topic":"頭部TBI","subtopic":"總論／其他","stem":"A young woman sustains a severe head injury as the result of a motor vehicle crash.In the emergency department, her GCS is 6. Her blood pressure in 140/90 mm Hg and her heart rate is 80 beats per minute. She is intubated and mechanically ventilated.Her pupils are 3 mm in size and equally reactive to light. There is no other apparent injury. The most important principle to follow in the early management of her head injury is to:","opts":[{"k":"A","t":"avoid hypotension"},{"k":"B","t":"administer an osmotic diuretic"},{"k":"C","t":"aggressively treat systemic hypertension"},{"k":"D","t":"reduce metabolic requirements of the brain"},{"k":"E","t":"distinguish between intracranial hematoma and cerebral edema"}],"answer":"A","expl":"嚴重 TBI 早期最重要的是 avoid hypotension 與 hypoxia（BTF/ATLS），因為 secondary brain injury 的最大可預防因子是低血壓與缺氧，所以 (A)。(B)(D)(E) 都在後面；(C) 不應積極降壓，維持 CPP 才是重點。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-13","year":102,"qnum":13,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"關於現在較新的輸液急救觀念“Damage Control Resuscitation”或“Hemostatic Resuscitation” (針對嚴重外傷大量失血者)，以下敘述何者錯誤？\n甲、Crystalloid 的使用應該盡量減少。\n乙、輸血應愈早愈好，量愈多愈好。\n丙、不再強調預防低體溫，及盡早施行止血手術或步驟。\n丁、應全面使用新鮮全血做為第一線血品。\n戊、新鮮冷凍血漿應可做為第一線血品輸注。","opts":[{"k":"A","t":"乙丙丁。"},{"k":"B","t":"甲乙戊。"},{"k":"C","t":"甲丙丁。"},{"k":"D","t":"甲乙丁。"},{"k":"E","t":"乙丙戊。"}],"answer":"A","expl":"Damage control resuscitation 的原則：減少 crystalloid、早期給血、balanced transfusion（plasma 為第一線），注意保暖與盡早止血；並不是「愈多愈好」、不是「不再強調保暖與止血」，也不是全面使用 fresh whole blood，所以 (A) 乙丙丁錯。補充：low-titer O whole blood 在一些中心也被使用，但並非普遍標準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-14","year":102,"qnum":14,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列關於孕婦生理變化及外傷處理的敘述何者最恰當？","opts":[{"k":"A","t":"孕婦的血量較一般狀況為低，稱作生理性貧血。"},{"k":"B","t":"孕婦的凝血因子相對不足，容易出血。"},{"k":"C","t":"孕婦受傷急救時，為減少下腔靜脈壓迫，要考慮右側臥。"},{"k":"D","t":"急救孕婦時發生胎兒流產的最多原因是子宮破裂。"},{"k":"E","t":"即使是懷孕期，不尋常的傷情仍應考慮家暴的可能性。"}],"answer":"E","expl":"同 96-23：孕婦外傷若傷勢不尋常，要考慮 intimate partner violence，所以 (E)。其他：孕婦有生理性貧血（血漿容積增加多於紅血球）；凝血因子增加；應採左側臥；胎盤早剝是最常見的胎兒流失原因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-15","year":102,"qnum":15,"topic":"頭部TBI","subtopic":"創傷後癲癇","stem":"嚴重成人頭部外傷、顱骨凹陷性骨折併腦挫傷血腫病人發生急性癲癇給予 1.0gm phenytoin loading dose(<50mg/min)後維持劑量(maintenance dose)為多少劑量?","opts":[{"k":"A","t":"100mg/4hrs"},{"k":"B","t":"100mg/6hrs"},{"k":"C","t":"100mg/8hrs"},{"k":"D","t":"200mg/4hrs"},{"k":"E","t":"200mg/6hrs"}],"answer":"C","expl":"Phenytoin loading dose 後維持劑量為 100 mg q8h（約 300 mg/day），血中濃度維持 10–20 mcg/mL，所以 (C)。補充：目前 levetiracetam 也常作為替代，BTF 指引建議早發性癲癇預防以 7 天為限。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-16","year":102,"qnum":16,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"Blunt bowel perforation 在腹部挫傷病患中，診斷相當重要；下列相關之敘述，何者有誤?","opts":[{"k":"A","t":"發生的 mechanism 通常是外力 compression，因外壓形成 closed loop，再因high intraluminal pressure，而 blowout。"},{"k":"B","t":"在 alcohol drinking, spinal cord injury 或 head injury with conscious disturbance的腹部挫傷病患，常會 missed diagnosis。"},{"k":"C","t":"Abdominal CT 呈現 bowel wall thickness, mesenteric hematoma 或 streaky sign應可確定診斷。"},{"k":"D","t":"Diagnostic peritoneal lavage (DPL)，可作輔助性診斷，可發現 positive Gram stain, elevation of amylase 或 alkaline phosphatase (ALP)。"},{"k":"E","t":"Laparotomy是 treatment of choice，開刀延遲的時間長短與其合併症或死亡率有關。"}],"answer":"C","expl":"同 99-2：CT 的 bowel wall thickening、mesenteric hematoma 或 streaky sign 只是間接徵象，不能「確定」診斷，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-17","year":102,"qnum":17,"topic":"骨盆泌尿","subtopic":"尿道損傷","stem":"關於尿道裂傷之處理的下列敘述何者為非。","opts":[{"k":"A","t":"尿道前側因鈍傷造成尿道完全斷裂要盡快接受端對端吻合修補手術。"},{"k":"B","t":"尿道前側因穿刺傷受損可以接受局部探查及修補術。"},{"k":"C","t":"尿道後側尿道斷裂早期可以接受用內視鏡置放 catheter realignment。"},{"k":"D","t":"尿道後側尿道斷裂可以先接受恥骨上膀胱造口 3-6 個月後再接受尿道重建手術。"},{"k":"E","t":"男性與女性尿道裂傷之處理原則不同。"}],"answer":"A","expl":"前尿道鈍傷合併完全斷裂，急性期通常先以 suprapubic cystostomy（或 catheter）引流，之後延遲再做 urethroplasty，不是盡快端對端吻合，所以 (A) 錯。(B) 穿刺傷可探查修補；(C) 後尿道可早期 catheter realignment；(D) 常先 SPC 3–6 個月後重建。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-18","year":102,"qnum":18,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"下列有關損害控制式復甦(damage control resuscitation, DCR)之敘述何者為非？","opts":[{"k":"A","t":"收縮壓(SBP)90–95mm-Hg 即可。"},{"k":"B","t":"平均動脈壓 (mean arterial pressure) 65mm-Hg。"},{"k":"C","t":"儘早輸血以控制凝血病變(coagulopathy)。"},{"k":"D","t":"提高 FFP : P-RBC 和P-RBC : platelet 的比例。"},{"k":"E","t":"Platelet ＜5萬須輸血小板。"}],"answer":"E","expl":"Damage control resuscitation 的原則：permissive hypotension（歐洲指引建議 SBP 80–90 mmHg）、早期 balanced 輸血、避免大量晶體液、盡早矯正凝血。官方答案指 (E)「血小板 <5 萬須輸血小板」為非。","outdated":false,"suspect":true,"flagNote":"依歐洲出血與凝血病變指引，持續出血的創傷病人應維持血小板 >50×10⁹/L（TBI 或大量出血可 >100），所以 (E) 其實是合理的；反而 (A)「SBP 90–95」與 permissive hypotension 的建議（80–90）稍有出入。答案可能有爭議，考試仍以官方 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"102-19","year":102,"qnum":19,"topic":"腹部","subtopic":"脾臟","stem":"34歲年輕婦女，與先生爭執，被踢中腹與腰部，因疼痛就醫。血壓 124/70mmHg心跳98/min，腹部無反彈徵(rebounding pain)，腹部 CT顯示左上腹單純脾臟破裂，grade III。選擇血管栓塞非手術治療，下列敘述何者最適當？","opts":[{"k":"A","t":"脾臟鈍挫傷，非手術治療血管栓塞，成功率百分之百。"},{"k":"B","t":"脾臟鈍挫傷，合併腹內出血，非手術治療血管栓塞，成功率約百分之五十。"},{"k":"C","t":"非手術治療血管栓塞，主要嚴重倂發症包括疼痛、發燒。"},{"k":"D","t":"非手術治療血管栓塞，輕微倂發症包括疼痛、發燒。"},{"k":"E","t":"非手術治療血管栓塞，是以血管內支架(endovascular stent-graft) 止住破裂血管的出血。"}],"answer":"D","expl":"脾臟血管栓塞的併發症分為輕微（post-embolization syndrome：疼痛、發燒、輕度白血球上升）與嚴重（脾梗塞、脾膿瘍、再出血、血管損傷、腎功能受損），疼痛與發燒屬輕微併發症，所以 (D)。(A)(B) 成功率並非 100% 或 50%（多數報告 >85–90%）；(E) 並非使用 stent-graft，而是 coil／gelfoam 栓塞。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-20","year":102,"qnum":20,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"針對骨盆骨折合併休克之病患，除基本之primary survey外，以下何種處置最不適當？","opts":[{"k":"A","t":"經動脈血管栓塞。"},{"k":"B","t":"由骨科醫師進行骨外固定經動脈血管栓塞。"},{"k":"C","t":"由外科醫師執行preperitoneal packing並以床單固定骨盆經動脈血管栓塞。"},{"k":"D","t":"由外科醫師執行雙側髂內動脈結紮手術。"},{"k":"E","t":"於急診置放主動脈內氣球阻斷下肢血流+經動脈血管栓塞。"}],"answer":"D","expl":"骨盆骨折合併休克：binder、external fixation、preperitoneal packing、angioembolization、REBOA 都是選項；雙側 internal iliac artery ligation 因側枝循環豐富、止血效果差、手術耗時，現今已很少使用，所以 (D) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-21","year":102,"qnum":21,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"有關下列胸部外傷敘述，最適當的答案為：","opts":[{"k":"A","t":"胸部創傷大部份僅須簡單的胸管插管處置。"},{"k":"B","t":"胸部外傷如為胸部穿刺傷，大半不需手術治療。"},{"k":"C","t":"在加護病房的胸部外傷患者，往往需要進行開胸手術治療。"},{"k":"D","t":"胸部創傷中，氣管破裂(tracheobronchial injury )很少見，都不需要手術。"},{"k":"E","t":"主動脈破裂行緊急手術，進行手術一定先行體外循環(heart-lung machine bypass)。"}],"answer":"A","expl":"胸部外傷多數（約 85%）只需要 tube thoracostomy 與支持性治療，不一定要開胸，所以 (A)。(B) 穿刺傷多數也僅需胸管；(D) 氣管支氣管破裂雖少見，但多需手術；(E) 主動脈破裂手術不一定需要 bypass（可 clamp-and-sew、partial bypass 或 TEVAR）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-22","year":102,"qnum":22,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"21歲女性騎機車被汽車擦撞，送抵急診時意識混亂、心跳為130/min、收縮血壓100mmHg，病患外觀無明顯出血及四肢變形，超音波檢查發現有心包膜積血但是沒有血胸或腹腔內出血，骨盆檢查發現為穩定之骨盆，經緊急氣管內管置入、輸液2000cc並使用床單固定骨盆後，心跳為130/min、收縮血壓70mmHg；若本院並無心臟外科醫師，且將病患轉診至最近可執行心臟手術之B醫院需時60分鐘，以下處置何者最適當？","opts":[{"k":"A","t":"通知B醫院並準備4單位之全血，將病患立即轉院。"},{"k":"B","t":"安排心臟超音波查看是否有心臟損傷。"},{"k":"C","t":"安排電腦斷層檢查查看是否確定有心臟損傷。"},{"k":"D","t":"通知外科醫師執行開胸及心包膜切開與引流管放置後，通知B醫院並將病患立即轉院。"},{"k":"E","t":"以上皆可。"}],"answer":"D","expl":"心包填塞合併休克，轉院需要 60 分鐘時，應在原醫院由外科醫師做 pericardiotomy（subxiphoid window 或開胸）與引流、暫時控制，再轉院，所以 (D)。(A)(B)(C) 都會延誤；(E) 不正確。補充：輸液 2000 mL 與現行 limited crystalloid 的概念不同。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-23","year":102,"qnum":23,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有ㄧ35 歲男性遭人以牛排刀刺中上腹(epigastric region)，產生一處 2公分長傷口，到院時傷口少量出血，但病患呈現休克現象，超音波檢查(FAST)顯現心包膜積液，下列敘述何者為是？\n1.張力性氣胸為最可能診斷。\n2.在休克狀況下，須考慮輸液或輸血治療。\n3.非手術性療法已取代手術療法成為治療外傷性心包膜填塞的主流。\n4.若病患情況快速惡化，且手術室無法立即就緒，有時需考慮於急診室開胸減壓手術(ED thoracotomy) 。\n5.穿刺傷(penetrating injury)造成的心包膜填塞產生休克時，急診室開胸減壓手術(ED thoracotomy)救活出院的存活率不差，超過 30%。","opts":[{"k":"A","t":"1+3+5。"},{"k":"B","t":"1+3+4。"},{"k":"C","t":"1+2+3。"},{"k":"D","t":"2+4。"},{"k":"E","t":"2+4+5。"}],"answer":"D","expl":"上腹穿刺傷、休克、FAST 見心包積液，首先考慮 cardiac tamponade（不是 tension pneumothorax），休克時補液／輸血；若快速惡化且手術室無法立即就緒，可 ED thoracotomy，所以 (D) 2+4。非手術不是主流；穿刺性 tamponade 的 ED thoracotomy 存活率約 10–20%，並未超過 30%。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-24","year":102,"qnum":24,"topic":"休克輸血","subtopic":"總論／其他","stem":"關於休克所產生的內分泌變化的敘述下列何者為非?","opts":[{"k":"A","t":"休克會造成交感神經活性增加，使得 adrenal medulla 在 24-48 小時內分泌catecholamine 增加。"},{"k":"B","t":"休克會刺激 hypothalamus 釋放出 corticotrophin-releasing hormone。"},{"k":"C","t":"在休克所產生發炎反應中最早出現的 proinflammatory cytokines 為 Tumor necrosis factor-ɑ(TNF-ɑ) 。"},{"k":"D","t":"低血容休克時會刺激下視丘釋放 anti-diuretic hormone (ADH)造成腎臟遠端腎小管對於水分通透性下降，降低體內水份及鈉離子流失。"},{"k":"E","t":"休克早期會因發炎反應造成中性球(neutrophil)活性增加進而引起細胞及器官功能受損。"}],"answer":"D","expl":"ADH（vasopressin）作用在 distal tubule 與 collecting duct，增加水分通透性，使水分再吸收增加，保留體內水分與血容，所以 (D)「通透性下降」為錯。(A) 交感活性增加使 catecholamine 上升；(B) 休克刺激 CRH-ACTH-cortisol axis；(C) TNF-α 是最早的 proinflammatory cytokine。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-25","year":102,"qnum":25,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤?","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"同 99-14：外傷營養的熱量 25–30 kcal/kg/day 以碳水化合物與脂肪混合，70% 脂肪並非建議，所以 (B) 錯。目前血糖目標約 140–180 mg/dL，不建議 tight control（≤110）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-26","year":102,"qnum":26,"topic":"頭部TBI","subtopic":"總論／其他","stem":"嚴重腦外傷病人昏迷指數 3-8分，經急救血行動力學(Hemodynamic)正常，為降低腦壓增高，給予短時間過度換氣處置時，維持血中二氧化碳下列何項氣體壓力濃度較為適度?","opts":[{"k":"A","t":"PaCO2 25mmHg。"},{"k":"B","t":"PaCO2 30mmHg。"},{"k":"C","t":"PaCO2 35mmHg。"},{"k":"D","t":"PaCO2 40mmHg。"},{"k":"E","t":"PaCO2 45mmHg。"}],"answer":"C","expl":"嚴重 TBI 若需要短時間 hyperventilation（如 herniation 的橋接），PaCO2 以 30–35 mmHg 為限，避免過低（<25）造成腦缺血；官方答案 (C) PaCO2 35 mmHg 為「較適度」。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-27","year":102,"qnum":27,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"以下關於Ventilator Associated Pneumonia(呼吸器相關肺炎)的預防之敘述何者錯誤？","opts":[{"k":"A","t":"床頭搖高約30~45 度，除非其病情不允許。"},{"k":"B","t":"每天應有“Sedation Vacation”，降低或停止鎮靜劑使用，期以減少鎮靜劑及呼吸器使用天數。"},{"k":"C","t":"須預防壓力性潰瘍。"},{"k":"D","t":"盡可能預防血栓的形成。"},{"k":"E","t":"應例行性使用預防性抗生素。"}],"answer":"E","expl":"VAP 預防措施：床頭抬高 30–45°、每日中斷鎮靜（sedation vacation）、預防壓力性潰瘍與血栓、口腔護理；不應例行性使用預防性抗生素（增加抗藥性），所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-28","year":102,"qnum":28,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"A 40-year-old woman restrained driver is transported to the emergency department in full spinal immobilization. She is hemodynamically normal and found to be paraplegic at the level of T10. Neurologic examination also determines that there is loss of pain and temperature sensation with preservation of proprioception and vibration.These findings are consistent with the diagnosis of:","opts":[{"k":"A","t":"central cord syndrome。"},{"k":"B","t":"spinal shock syndrome。"},{"k":"C","t":"anterior cord syndrome。"},{"k":"D","t":"complete cord syndrome。"},{"k":"E","t":"Brown-Sequard’s syndrome 。"}],"answer":"C","expl":"T10 paraplegia、痛溫覺喪失、本體感覺與震動覺保留，是 anterior cord syndrome（前脊髓動脈區域受損，保留 dorsal column）的典型表現，所以 (C)。Brown–Séquard 為單側損傷。（與 100-27 同一表現）","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-29","year":102,"qnum":29,"topic":"災難院前法規","subtopic":"總論／其他","stem":"全民健保於 100 年內因損傷及中毒住院人數共計：","opts":[{"k":"A","t":"507,611 人。"},{"k":"B","t":"407,611 人。"},{"k":"C","t":"307,611 人。"},{"k":"D","t":"207,611 人。"},{"k":"E","t":"107,611 人。"}],"answer":"C","expl":"這是 100 年全民健保因損傷及中毒住院人數的統計題，官方答案為 (C) 307,611 人。屬資料記憶題，臨床價值低，重點是外傷是重要的住院原因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-30","year":102,"qnum":30,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"30歲男性，酒後開車撞樹，送達急診時 GCS 為 E2M4V2，SBP 60 mm-Hg；F.A.S.T.發現腹腔內有大量液體積聚；目前聯絡不到任何家屬。下列敘述何者正確？","opts":[{"k":"A","t":"須緊急手術，請社工簽同意書。"},{"k":"B","t":"須緊急手術，由兩位醫師在手術同意書上簽名。"},{"k":"C","t":"須緊急手術，由負責醫師在病歷上寫明手術適應症(indication)、傷患情況危急且無人可以執行代理同意後手術，不簽同意書。"},{"k":"D","t":"須緊急手術，請警衛簽同意書。"},{"k":"E","t":"以上皆正確。"}],"answer":"C","expl":"無法聯絡家屬且病人無法表達意願時，緊急手術可由負責醫師在病歷詳述適應症、病情危急與無法取得同意的事實後逕行處置，不需他人簽同意書（醫療法有緊急情況的免同意規定），所以 (C)。(A)(D) 社工或警衛無代理權；(B) 兩位醫師簽名並非必要要件。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-31","year":102,"qnum":31,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"有關balanced resuscitation，以下何種敘述最不適當？","opts":[{"k":"A","t":"也稱controlled resuscitation或hypotensive resuscitation。"},{"k":"B","t":"當病患需接受大量輸血時，須及早給予等比例的pRBCs/plasma/platelets。"},{"k":"C","t":"當病患需接受大量輸血時，須及早給予等比例的pRBCs/crystalloids。"},{"k":"D","t":"可以增加脾臟撕裂傷病患的非手術治療成功率。"},{"k":"E","t":"可以增加胸部穿刺傷病患的存活率。"}],"answer":"D","expl":"Balanced resuscitation（controlled resuscitation）指 permissive hypotension 加上 early balanced 輸血（pRBC：plasma：platelet）；官方答案 (D)「增加脾臟撕裂傷 NOM 成功率」被認為最不適當。","outdated":false,"suspect":true,"flagNote":"選項 (C)「等比例給予 pRBC／crystalloids」明顯與 balanced resuscitation 相反（應為 pRBC／plasma／platelets），比 (D) 更顯然錯誤，所以答案 (D) 可能有誤。考試以官方 (D) 為準。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"102-32","year":102,"qnum":32,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕六個月婦女，因車禍就診。血壓、心跳與呼吸等生命徵象穩定，但神智不清，昏迷指數12分(Glasgow Coma Scale：E3V4M5)，瞳孔不等大，對光反應趨緩，右下肢變形骨折。你的處置可不包括：","opts":[{"k":"A","t":"安排腹部超音波(FAST) 。"},{"k":"B","t":"安排胸部X-光(Chest Film)。"},{"k":"C","t":"安排頭部電腦斷層掃描(Brain CT Scan)。"},{"k":"D","t":"監測胎兒心音(Fetal heart beat)。"},{"k":"E","t":"集尿液驗HCG。"}],"answer":"E","expl":"孕 6 個月孕婦（已知懷孕）合併 TBI 與四肢骨折，需要 FAST、CXR、head CT（必要時不因懷孕而延誤）與胎心音監測；既然已知懷孕，不需要再驗尿 HCG，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-33","year":102,"qnum":33,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"下列關於創傷傷患之凝血病變(coagulopathy)敘述何者為非？","opts":[{"k":"A","t":"多重創傷傷患約有 1/4 - 1/3 於到達醫院時已有coagulopathy。"},{"k":"B","t":"單純嚴重腦創傷(traumatic brain injury, TBI)很少大出血，因此少有Coagulopathy。"},{"k":"C","t":"接受大量輸液復甦者會有coagulopathy。"},{"k":"D","t":"嚴重肝臟創傷(severe liver trauma)會有coagulopathy。"},{"k":"E","t":"低體溫(hypothermia)會有coagulopathy。"}],"answer":"B","expl":"嚴重 TBI 本身會因腦組織釋出 tissue factor 而啟動凝血異常（TBI-associated coagulopathy），所以 (B)「少有 coagulopathy」為錯。(A) 約 25–35% 多重創傷到院時已有 trauma-induced coagulopathy；(C)(D)(E) 為正確敘述。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-34","year":102,"qnum":34,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關槍傷的敘述何者為非？","opts":[{"k":"A","t":"槍傷的經過路徑(trajectory)ㄧ般比刀傷更加難以預測。"},{"k":"B","t":"槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。"},{"k":"C","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)可達90%以上的準確率。"},{"k":"D","t":"治療槍傷的基本原則與刀傷同，仍依高級外傷救命術精神為主。"},{"k":"E","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"}],"answer":"C","expl":"同 98-4：槍傷彈道常偏折，不能用直線預測，所以 (C) 的 90% 準確率為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-35","year":102,"qnum":35,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"關於腹腔腔室症候群(Abdominal compartment syndrome)的敘述下列何者為非","opts":[{"k":"A","t":"腹腔腔室症候群是指腹腔內壓力大於 20 mmHg 。"},{"k":"B","t":"我們可以藉由在膀胱、胃部或是下腔靜脈內置放導管而間接得到腹腔內壓力值。"},{"k":"C","t":"腹腔內壓力上升會造成腎靜脈壓上升，血液中腎素(renin)及醛固(aldosterone)上升。"},{"k":"D","t":"腹腔內壓力上升會造成顱內壓力上升，造成大腦灌注壓下降。"},{"k":"E","t":"腹腔內壓力上升會造成胸腔內壓力上升，下腔靜脈回心血流量增加。"}],"answer":"E","expl":"ACS 時腹內壓上升會壓迫 IVC，使 venous return 下降，進而降低 cardiac output，所以 (E)「回心血流量增加」為錯。(A)(B)(C)(D) 為正確敘述：IAP >20 mmHg 加上器官功能障礙、可用 bladder／stomach 等測量、renin-aldosterone 上升、ICP 上升而 CPP 下降。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-36","year":102,"qnum":36,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"同 99-17：創傷後免疫反應先是 SIRS 的 hyperinflammation，其後才是 CARS 的 hypoinflammation，所以 (A) 的順序顛倒，答案錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-37","year":102,"qnum":37,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"40 歲正常男性行走路邊被轉彎計程車撞後倒地，經救護車送達急診，經身體檢查病人四肢無力、一直主訴頭後半部、耳朵、頸部及四肢麻木，臨床臆斷頭頸部受傷部位為?","opts":[{"k":"A","t":"三叉神經。"},{"k":"B","t":"第一頸椎。"},{"k":"C","t":"第二頸椎。"},{"k":"D","t":"第三頸椎。"},{"k":"E","t":"枕骨骨折。"}],"answer":"C","expl":"四肢無力加上頭後側、耳朵與頸部麻木，位置對應 C2 dermatome（枕部、耳後）與上頸髓損傷，所以官方答案 (C) 第二頸椎。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-38","year":102,"qnum":38,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"現在關於嚴重外傷大量失血的灌注原則，已由以往的自由大量輸注(血)，逐漸轉變成為有限量的急救，有人稱之為 Damage Control Resuscitation 或 Hemostatic Resuscitation，以下相關敘述何者錯誤？","opts":[{"k":"A","t":"嚴重外傷病患到院時，縱使尚未接受大量輸液灌注，已有相當比例的病患出現凝血病變。"},{"k":"B","t":"大量自由的輸液灌注之後，可能造成腹部腔室症候群，以及橫紋肌溶解症。"},{"k":"C","t":"傳統的大量輸注，可能造成凝血因子的消耗(Depletion)，稀釋(Dilution)，及功能不良(Dysfunction) 。"},{"k":"D","t":"Permissive Hypotension 是現在輸注觀念中的其中一項。"},{"k":"E","t":"現在的輸血觀念中，新鮮冷凍血漿(FFP)比上 pRBC的比例(輸血單位)較以往(d) 為高。"}],"answer":"B","expl":"大量自由輸液可造成 ACS、凝血病變、體液過量與低體溫；橫紋肌溶解症是壓傷或缺血再灌注造成，與輸液策略無直接因果，所以 (B) 錯。(A) 到院時已有 coagulopathy 的比例不低；(C) 稀釋、消耗與功能障礙；(D)(E) 為 DCR 的原則。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-39","year":102,"qnum":39,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"A trauma patient presents to your emergency department with inspiratory stridor and a suspected c-spine injury. Oxygen saturation is 88% on high-flow oxygen via a nonrebreathing mask. The most appropriate next step is to:","opts":[{"k":"A","t":"apply cervical traction."},{"k":"B","t":"perform immediate tracheostomy."},{"k":"C","t":"insert bilateral thoracostomy tubes."},{"k":"D","t":"maintain 100% oxygen and obtain immediate c-spine x-rays."},{"k":"E","t":"maintain inline immobilization and establish a definitive airway."}],"answer":"E","expl":"吸入性喘鳴（inspiratory stridor）、SpO2 88%，表示上呼吸道阻塞，需要 definitive airway，同時維持 inline immobilization，所以 (E)。(A) 不可做頸椎牽引；(B) 直接氣切非首選；(C)(D) 無關。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-40","year":102,"qnum":40,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"101年十大主要死因，事故傷害排名順位為：","opts":[{"k":"A","t":"第一。"},{"k":"B","t":"第二。"},{"k":"C","t":"第三。"},{"k":"D","t":"第六。"},{"k":"E","t":"第十。"}],"answer":"D","expl":"這題是 101 年台灣十大死因統計：事故傷害排名第六，官方答案 (D)。屬於資料記憶題；每年排名有變動（近年約在第 6–8 名），年輕人則是事故傷害居首位。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-41","year":102,"qnum":41,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"青年人前三大主要死因依序為:","opts":[{"k":"A","t":"第一為事故傷害(26.1%)；第二為自殺(14.6%)；第三為惡性腫瘤(1.6%)。"},{"k":"B","t":"第一為事故傷害(46.1%)；第二為自殺(14.6%)；第三為惡性腫瘤(1.6%)。"},{"k":"C","t":"第一為自殺 (46.1%)；第二為事故傷害 (14.6%)；第三為惡性腫瘤(1.6%)。"},{"k":"D","t":"第一為惡性腫瘤 (46.1%)；第二為事故傷害 (14.6%)；第三為自殺 (1.6%)。"},{"k":"E","t":"第一為先天性心臟病 (46.1%)；第二為事故傷害 (14.6%)；第三為自殺(1.6%)。"}],"answer":"B","expl":"這是青年（15–24 歲）死因統計題：官方答案為事故傷害第一、自殺第二，所以 (B)。數字細節無須硬背，重點是 trauma 為青年人首位死因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-42","year":102,"qnum":42,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控管手術(Damage control operation)之敘述下列何者為非?","opts":[{"k":"A","t":"是以局限的手術來控制病人的出血及感染。"},{"k":"B","t":"術中實施損害控管手術的適應症為病人體溫低於攝氏 35 度。"},{"k":"C","t":"術中實施損害控管手術的適應症為病人血液中酸鹼值 pH小於7.4乳酸值大於2 mmol/l。"},{"k":"D","t":"術中實施損害控管手術的適應症為病人 Prothrombin time or partial thromboplastin time 大於正常值50%。"},{"k":"E","t":"術中實施損害控管手術的適應症為病人有胸部或是腹部骨盆創傷合併收縮壓低於90 mmHg時。"}],"answer":"C","expl":"Damage control 的適應條件：低體溫 <35°C、acidosis（pH <7.2、base deficit >15、lactate >5）、PT/aPTT >50% 延長、休克（SBP <90）合併胸腹骨盆創傷與大量輸血。官方答案 (C) 的「pH <7.4、lactate >2 mmol/L」標準過寬，並非適應症，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-43","year":102,"qnum":43,"topic":"影像FAST","subtopic":"FAST／超音波的使用","stem":"顱內腦外傷出血之成年病人，併有低血壓病況，仍需儘速檢查出血部位，早期治療。神經學檢查評估困難，昏迷的外傷病人腹部臨床能迅速重覆追蹤的檢查為何種?","opts":[{"k":"A","t":"電腦斷層CT。"},{"k":"B","t":"重要部位外傷腹部超音波檢查 FAST。"},{"k":"C","t":"觸診。"},{"k":"D","t":"核磁共振MRI。"},{"k":"E","t":"抽血測血清澱粉酶 (Amylase)。"}],"answer":"B","expl":"意識障礙、需要神經學評估困難的 TBI 病人，腹部可用 serial FAST 迅速重複追蹤是否出血，所以 (B)。CT 與 MRI 不能在床邊重複；amylase 不具特異性；觸診在昏迷病人不可靠。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-44","year":102,"qnum":44,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"病患肝臟嚴重裂傷手術實施損傷控制手術以紗布墊填塞止血時，常見的合併症不包括？","opts":[{"k":"A","t":"再出血。"},{"k":"B","t":"膽汁羈留腹內。"},{"k":"C","t":"門靜脈肝動脈廔管。"},{"k":"D","t":"菌血症。"},{"k":"E","t":"腹內感染。"}],"answer":"C","expl":"肝臟 packing 後常見併發症：再出血、膽汁積聚（bilioma）、腹內感染與膿瘍、菌血症、腹腔高壓；portal vein–hepatic artery fistula 並非常見併發症，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-45","year":102,"qnum":45,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"Which one of the following situations requires Rh immunoglobulin administration to an injured woman?","opts":[{"k":"A","t":"negative pregnancy test, Rh negative, and has torso trauma。"},{"k":"B","t":"positive pregnancy test, Rh positive, and has torso trauma。"},{"k":"C","t":"positive pregnancy test, Rh negative, and has torso trauma。"},{"k":"D","t":"positive pregnancy test, Rh positive, and has an isolated wrist fracture。"},{"k":"E","t":"positive pregnancy test, Rh negative,, and has an isolated wrist fracture。"}],"answer":"C","expl":"Rh-negative 孕婦遭受腹部或軀幹創傷，可能發生 fetomaternal hemorrhage，需要給予 Rh immunoglobulin（RhIG），所以 (C)。孕檢陰性、Rh positive 或單純腕骨折不需要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-46","year":102,"qnum":46,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"對於懷孕外傷病患的診治，影像學檢查往往不可或缺。但是放射暴露對懷孕胎兒又有畸胎的危險，尤以懷孕 8~15 週子宮內胎兒最易受傷害。下列何種常規 X 光檢查，對孕婦子宮與胎兒，放射暴露量(Radiation Exposure)最大？","opts":[{"k":"A","t":"胸部X-光。"},{"k":"B","t":"頭部電腦斷層(Brain CT scan) 。"},{"k":"C","t":"腹部 X-光(KUB)加(IVP series) 。"},{"k":"D","t":"腰椎 X-光(lumbar spine兩張) 。"},{"k":"E","t":"胸部電腦斷層(Chest CT scan) 。"}],"answer":"C","expl":"常規放射線檢查中，對胎兒暴露量最大的是 KUB 加 IVP series（可達數 mGy 以上）；胸部 X-ray 與頭部 CT 對子宮暴露極小；胸部 CT 對子宮暴露也很低，所以 (C)。補充：腹部／骨盆 CT 才是高劑量，需要時仍不應因懷孕而拒絕。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-47","year":102,"qnum":47,"topic":"休克輸血","subtopic":"總論／其他","stem":"十八歲女性機車騎士與轎車發生對撞，送至醫院時血壓 74/30，心跳140，呼吸8，E1V2M2，兩側瞳孔等大且對光有反射，以下敘述何者較恰當？","opts":[{"k":"A","t":"可能有顱內出血及顱底骨骨折，應先插呼吸管後，立即送去做頭部電腦斷層檢查。"},{"k":"B","t":"顱底骨或顏面骨骨折造成的口鼻出血，縱使量多也極少造成出血性休克，應觀察即可。"},{"k":"C","t":"輸液兩千毫升後若仍低血壓，屬於第二級休克，應考慮輸血。"},{"k":"D","t":"若外觀無明顯出血，四肢沒有變形腫脹，應盡速利用理學檢查、胸部及骨盆X光、及 FAST超音波檢查，來排除腔室內出血。"},{"k":"E","t":"若骨盆會陰處無明顯挫瘀傷，無下肢變形或長短差距，且按壓骨盆時無不穩定現象，應可排除骨盆骨折。"}],"answer":"D","expl":"低血壓 74/30、HR 140、GCS 5 的病人，要尋找胸、腹、骨盆、長骨的失血（TBI 不會單獨造成休克），並同時 airway control，所以 (D)。(A) 不穩定不能直接去做 CT；(B) 顏面與顱底出血仍可能很大；(C) 輸液後仍低血壓代表 class III–IV，要輸血；(E) 理學檢查不可排除骨盆骨折。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-48","year":102,"qnum":48,"topic":"休克輸血","subtopic":"總論／其他","stem":"16歲女性騎機車被汽車擦撞，由同行友人送抵急診時意識混亂、心跳為130/min、收縮血壓70mmHg，病患外觀無明顯出血及四肢變形，超音波檢查發現有腹腔內出血但是沒有血胸或心包膜積血，骨盆檢查發現為穩定之骨盆，經緊急氣管內管置入、輸液2000cc後，心跳仍為130/min、收縮血壓70mmHg，以下處置何者最適當？","opts":[{"k":"A","t":"聯絡父母於30分鐘內到院簽屬手術同意書後進行手術。"},{"k":"B","t":"由同行友人簽署同意書後送入手術室進行手術。"},{"k":"C","t":"聯絡社工到急救現場簽署相關文件後送入手術室進行手術。"},{"k":"D","t":"由急救現場2位醫師確認後送入手術室進行手術。"},{"k":"E","t":"以上皆不適當。"}],"answer":"D","expl":"16 歲未成年傷患，生命危急、無家屬在場，可依緊急情況免同意規定，由現場 2 位醫師確認並記載後逕行手術，所以 (D)。(A)(B)(C) 延誤或無法律代理權。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-49","year":102,"qnum":49,"topic":"腹部","subtopic":"脾臟","stem":"對於 blunt splenic injury，使用 multidetector CT檢查，下列敘述何者有誤?","opts":[{"k":"A","t":"對於偵測有無 intra splenic pseudoaneurysm 存在，artery phase image 比 portal phase image更 sensitive且 accurate。"},{"k":"B","t":"對於偵測有無 splenic parenchymal injury， artery phase image 比 portal phase image較不 sensitive及不 accurate。"},{"k":"C","t":"對於偵測有無 active bleeding，artery phase image 比 portal phase image 更sensitive且 accurate。"},{"k":"D","t":"對整體 blunt splenic injury 評估，dual-phase review比 single-phase review來得好。"},{"k":"E","t":"Artery phase image對於 intra-splenic pseudoaneurysm的偵測敏感度可達70%。"}],"answer":"C","expl":"對 blunt splenic injury 的 multidetector CT：arterial phase 對 pseudoaneurysm 與 active bleeding 較敏感，portal venous phase 較能顯示 parenchymal injury，dual-phase 優於 single-phase。官方答案 (C) 認為其中有誤；實務上 active extravasation 在 portal／delayed phase 範圍會擴大，兩階段互補，不能說 arterial phase 一定較 sensitive 且 accurate。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"102-50","year":102,"qnum":50,"topic":"小兒","subtopic":"總論／其他","stem":"下列敘述何者正確？","opts":[{"k":"A","t":"兒童創傷急救中，呼吸道(airway)與換氣(breathing)的處置比循環 (circulation)更重要。"},{"k":"B","t":"兒童的生理代償能力較成人為高；皮下組織較厚。"},{"k":"C","t":"兒童的血量較少，因此休克容易及早發現。"},{"k":"D","t":"老人有較高的外傷發生率及死亡率。"},{"k":"E","t":"即使適當且積極的照護，大部分的老人創傷仍無法回復受傷前的功能狀態。"}],"answer":"A","expl":"兒童創傷急救中，airway 與 breathing 的問題（氣道阻塞、通氣不足）是最快造成缺氧與死亡的原因，所以 (A)。(B) 兒童代償能力強，但皮下脂肪少、易低體溫；(C) 兒童血量少，但代償好，休克常較晚才出現低血壓；(E) 多數老人能恢復。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-1","year":103,"qnum":1,"topic":"休克輸血","subtopic":"REBOA","stem":"嚴重出血休克之外傷病患，可以考慮用主動脈氣球填塞術(Ruscitation Endovascular Balloon Occlusion of the Aorta, REBOA)止血急救。請問施行氣球填塞過程之敘述，下列何者為非？","opts":[{"k":"A","t":"放置氣球時，主要是經由股動脈進入降主動脈(Descending aorta)。"},{"k":"B","t":"氣球放置於主動脈雙側分支(Aortic bifurcation)時，往往會造成腎臟缺血。"},{"k":"C","t":"欲將氣球放置到主動脈雙側分支(Aortic bifurcation)的部位，可以病患的肚擠為長度測量標準。"},{"k":"D","t":"將氣球置放於橫膈膜以上的降主動脈時，可以針對大量肝出血休克病患進行暫時止血。"},{"k":"E","t":"放置氣球後，可以用 X 光定位氣球的位置。"}],"answer":"B","expl":"REBOA zone 3 是 aortic bifurcation 附近（infrarenal，腎動脈以下），不會造成腎缺血；腎動脈在 zone 2 以上，所以 (B) 錯。(A) 由 common femoral artery 進入；(C) 可用肚臍到胸骨角的距離估計；(D) zone 1（左鎖骨下與 celiac 之間）可針對肝出血或腹內大出血；(E) 以 X-ray 確認位置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-2","year":103,"qnum":2,"topic":"災難院前法規","subtopic":"總論／其他","stem":"對於外傷醫療品質中，影響外傷中心對於外病患的照顧的成果，下列何者為非？","opts":[{"k":"A","t":"外傷病患總量應達到一定的數量。"},{"k":"B","t":"救治重大外傷病患的數量。"},{"k":"C","t":"外傷科醫師數量越多越好。"},{"k":"D","t":"需要轉診的病患，應該及時轉到外傷中心。"},{"k":"E","t":"病患數量少的醫學中心，其救治重大外傷病患的表現較數量大的區域醫院差。"}],"answer":"C","expl":"外傷中心品質與病人數量（volume）、救治重大外傷、及時轉診有關，但「外傷科醫師數量越多越好」並非決定因素，更重要的是 24 小時待命、團隊整合與品質改善，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-3","year":103,"qnum":3,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"有關嚴重外傷病患，利用負壓傷口治療(Negative Pressure Wound Therapy, NPWT)的處理方式之敘述，下列何者為非？","opts":[{"k":"A","t":"負壓傷口治療一開始是為了幫助慢性傷口癒合而設計的。"},{"k":"B","t":"一般使用的壓力都設在100~150 mmHg之間。"},{"k":"C","t":"美軍在戰場上截肢的傷口處理，目前也開始漸漸使用負壓傷口治療的方式。"},{"k":"D","t":"負壓傷口治療除了有物理的抽吸以助長肉芽組織生長作用之外，也會增加細胞代謝的活動。"},{"k":"E","t":"負壓傷口治療的應用範圍，主要侷限在外傷清創的傷口處理上，並未擴及使用在一般手術傷口。"}],"answer":"E","expl":"NPWT 最初為慢性傷口設計，常用壓力 −100 至 −150 mmHg，已被軍方用於截肢與戰傷，也廣泛用於一般手術傷口、腹部 open abdomen（temporary abdominal closure）等，所以 (E)「僅限外傷清創傷口」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-4","year":103,"qnum":4,"topic":"休克輸血","subtopic":"總論／其他","stem":"目前有關強力止血材料(Advanced Hemostatic Materials)科技的最新進展，下列何者為非？","opts":[{"k":"A","t":"Zeolite 在止血過程中雖然會產熱，仍然在美軍戰傷處理中廣泛採用。"},{"k":"B","t":"第二代的 COMBAT GAUZE 改採用 Kaolin 作為止血材料，主要經由加速內在凝血途徑(Intrinsic clotting pathway)而止血。"},{"k":"C","t":"甲殼素(CHITOSAN)止血的原理，主要是經由吸引負電荷的血液分子而產生血栓。"},{"k":"D","t":"止血敷料如果被發現有掉落顆粒形成血栓，會有安全的顧慮而停止使用於各種戰地外傷的場合。"},{"k":"E","t":"這些止血材料的使用經驗顯示，仍有一部份傷患的傷口無法經由這類材料完全止血。"}],"answer":"A","expl":"最早的 zeolite（QuikClot 原始顆粒型）止血時會放熱（exothermic）造成燒傷，美軍已改用 kaolin 為基礎的 Combat Gauze 與 chitosan 敷料，所以 (A)「仍廣泛採用」為錯。(B) kaolin 活化 intrinsic pathway；(E) 部分傷口仍需手術止血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-5","year":103,"qnum":5,"topic":"休克輸血","subtopic":"總論／其他","stem":"一位 40 歲男性機車騎士，不幸被計程車撞上，發生出血性休克(Hemorrhagic shock)，被送至急診室急救時，何者為目前最適當的加護急救步驟？","opts":[{"k":"A","t":"立即給予大量輸液及輸血。"},{"k":"B","t":"立即作 CT 檢查。"},{"k":"C","t":"立即進手術室進行手術。"},{"k":"D","t":"立即做血管攝影。"},{"k":"E","t":"立即給予 Dopamine。"}],"answer":"A","expl":"出血性休克的現行重點是盡快控制出血（手術或 angioembolization）並早期輸血（MTP），而非單靠大量晶體液。官方答案 (A)「立即給予大量輸液及輸血」是舊式表達。","outdated":true,"suspect":false,"flagNote":"ATLS 10/11 建議：初始晶體液約 1 L 為上限，盡早 blood products（balanced ratio）、TXA 並盡速 hemorrhage control；「大量輸液」已過時。官方答案 (A) 不變，但請記得 (C) 手術止血同樣重要。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"103-6","year":103,"qnum":6,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"同 99-17：創傷後免疫反應一開始是 SIRS（hyperinflammatory），之後才是 CARS（hypoinflammatory，易感染），所以 (A) 的順序顛倒。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-7","year":103,"qnum":7,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤?","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"同 99-14：營養熱量以碳水化合物與脂肪混合提供，70% 脂肪並非建議，所以 (B) 錯。血糖目標不要過度嚴格（避免 ≤110 mg/dL）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-8","year":103,"qnum":8,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"上腹部鈍傷病人，合併有劇烈胸痛，胸部 X 光出現左側血胸或有氣胸但是臨床身體檢查及胸部 X 光並未發現肋骨骨折，此時最可能的是：","opts":[{"k":"A","t":"外傷性橫膈膜破裂 (diaphragmatic rupture)"},{"k":"B","t":"食道破裂"},{"k":"C","t":"連枷胸 (flail chest)"},{"k":"D","t":"外傷性擠壓性窒息 (traumatic asphyxia)"},{"k":"E","t":"後腹腔臟器破裂"}],"answer":"B","expl":"官方答案為 (B) 食道破裂。上腹鈍傷後劇烈胸痛、左側血氣胸但無肋骨骨折，要想到胸內臟器損傷；食道破裂（Boerhaave 或鈍傷）會有 chest pain、縱隔氣腫與胸腔積液。","outdated":false,"suspect":true,"flagNote":"實際上鈍傷後最常見的是 (A) traumatic diaphragmatic rupture（左側，腹內臟器疝入胸腔，CXR 可見血胸／氣胸樣影像），而鈍性食道破裂極少見。因此 (A)(B) 都可能，官方答案 (B) 較有疑義。考試仍以官方 (B) 為準。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"103-9","year":103,"qnum":9,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部實質性器官及空腔器官之損傷的描述，下列何者錯誤?\na.肝臟是腹腔內最大的實質性器官，也是所有腹部鈍挫傷中最常見的實質器官損傷。\nb.腹部穿刺貫通傷但無內臟脫出或異常滲液者，若已超過 24 小時且一般情況良好者，可先採取嚴密觀察保守治療。\nc.實質性器官損傷的主要表現是腹腔內或後腹膜腔出血且合併有進行性的腹脹及腹痛。但若病人處於無法矯正的休克狀態(SBP< 90mmHg)，即使沒有腹痛的症狀也應進行剖腹探查術。\nd.腹腔內出血 3500ml，合併肝臟右葉 4 度損傷，右腎 4 級損傷及升結腸穿孔且大範圍壞死的患者，最佳的手術方式為以最迅速的方式進行右肝葉切除，右腎摘除，右半結腸切除術及小腸橫結腸吻合術。\ne.因車禍導致腹部鈍挫傷的患者，受傷 1 小時內的腹部 CT 顯示第五級脾臟破裂及大量腹腔內積液，無明顯游離氣體；此時為快速施行脾臟切除術，最建議的手術切口為從左肋緣下進入，以爭取時間完成脾臟切除。","opts":[{"k":"A","t":"bde。"},{"k":"B","t":"abd。"},{"k":"C","t":"ade。"},{"k":"D","t":"cd。"},{"k":"E","t":"de。"}],"answer":"C","expl":"a 錯：鈍傷最常受傷的實質器官是脾臟（其次為肝臟）；d 錯：大量出血且多器官傷害時應採 damage control，不做長時間肝葉切除、腎切除與吻合重建；e 錯：Grade V 脾傷合併大量積液、休克，應採正中剖腹（midline laparotomy）以利暴露與處理其他傷害，而非左肋緣下切口。b 與 c 正確。所以 (C) ade。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-10","year":103,"qnum":10,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列何狀況是緊急開胸探查的手術適應症？\na. 胸內子彈留存。\nb. 氣胸經予以胸管密閉式引流後持續大量漏氣。\nc. 張力性氣胸。\nd. 多根多處肋骨骨折合併氣血胸。\ne. 開放性氣胸合併胸壁缺損。","opts":[{"k":"A","t":"abde。"},{"k":"B","t":"ace。"},{"k":"C","t":"ade。"},{"k":"D","t":"bd。"},{"k":"E","t":"be。"}],"answer":"E","expl":"緊急開胸的適應症：胸管引流後持續大量漏氣（主支氣管破裂）、開放性氣胸合併嚴重胸壁缺損等需手術修補；胸內子彈留存、張力性氣胸（用減壓與胸管）、多根肋骨骨折合併氣血胸（用胸管）不是開胸適應症，所以 (E) b+e。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-11","year":103,"qnum":11,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"您是一位服役於野戰醫院的軍醫，戰鬥中接到一位遭手榴彈炸傷的後送傷兵a. 右小腿外傷性截肢。\nb. 腹部開放性傷口併內臟脫出及出血。\nc. 右側開放性氣胸。\nd. 右臉頰缺失併口鼻出血。\ne. 背部大面積燒傷。\n請問您處理的順序為何？","opts":[{"k":"A","t":"cbdae。"},{"k":"B","t":"dcbae。"},{"k":"C","t":"bcdae。"},{"k":"D","t":"bacde。"},{"k":"E","t":"bcade。"}],"answer":"B","expl":"軍醫處理順序的官方答案為 (B) dcbae：臉頰缺失併口鼻出血（airway）→開放性氣胸→腹部傷→截肢→燒傷，是採 ATLS 的 ABC 順序。","outdated":true,"suspect":false,"flagNote":"依 TCCC（MARCH）架構，肢體嚴重出血（如外傷性截肢，a）應先用 tourniquet 止血，再處理氣道與呼吸；民用 ATLS 則強調 ABC，但 ATLS 10 也已改為 xABCDE（x = exsanguinating hemorrhage control）。因此現行觀念下截肢的出血控制順位會提前。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"103-12","year":103,"qnum":12,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"架構身體lean body mass、主要免疫組成及傷口癒合的營養素為下列何者：","opts":[{"k":"A","t":"醣類。"},{"k":"B","t":"脂肪。"},{"k":"C","t":"蛋白質。"},{"k":"D","t":"維生素。"},{"k":"E","t":"礦物質。"}],"answer":"C","expl":"蛋白質是 lean body mass、免疫蛋白與 collagen／傷口癒合的主要材料，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-13","year":103,"qnum":13,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"嚴重外傷容易導致敗血症與多重器官衰竭。在嚴重敗血症中，下列何者是發生機率最高、也常是最早出現衰竭的系統/器官：","opts":[{"k":"A","t":"腎臟。"},{"k":"B","t":"肝臟。"},{"k":"C","t":"內分泌系統。"},{"k":"D","t":"呼吸系統。"},{"k":"E","t":"神經系統"}],"answer":"C","expl":"官方答案 (C)「內分泌系統」為嚴重敗血症中發生機率最高、最早衰竭的系統（如 relative adrenal insufficiency、血糖異常）。","outdated":false,"suspect":true,"flagNote":"一般 MODS／sepsis 教科書指出最早衰竭的器官是肺（ARDS，respiratory failure），其次為腎、肝；此題的 (C) 與常見說法不同，可能引自特定文獻（內分泌功能障礙很常見但常被忽略）。考試以官方 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"103-14","year":103,"qnum":14,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"下列關於腦傷、顱內壓的敘述何者錯？","opts":[{"k":"A","t":"當發生IICP 時，可快速降低二氧化碳來降低顱內高壓，但不建議常規使用。"},{"k":"B","t":"當發生IICP 時，病人意識不清不可施打鎮靜劑。"},{"k":"C","t":"顱內壓監測器要裝在硬腦膜內。"},{"k":"D","t":"2nd brand injury 是腦傷惡化的主因。"}],"answer":"B","expl":"ICP 升高的病人仍需要鎮靜（降低 CMRO2、避免躁動與咳嗽造成 ICP 峰值）、鎮痛與必要時肌肉鬆弛，但要選短效藥以便神經學評估，所以 (B)「不可施打」為錯。(A) 短暫降低 PaCO2 可救命但不建議常規；(D) secondary brain injury 是惡化主因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-15","year":103,"qnum":15,"topic":"頭部TBI","subtopic":"總論／其他","stem":"車禍病患昏迷指數，E1M4V2，血壓76/44 mmHg，下列何者正確？","opts":[{"k":"A","t":"則病患一定有腦部的損傷。"},{"k":"B","t":"則病患一定有腦部以外其他身體部位的受傷。"},{"k":"C","t":"則病患一定有腦部加上以外其他身體部位的受傷。"},{"k":"D","t":"沒有腦傷。"}],"answer":"B","expl":"GCS 7（E1M4V2）合併血壓 76/44：成人孤立性 TBI 通常不會造成休克（除非瀕死期 Cushing 後崩潰或脊髓損傷），所以低血壓代表合併腦以外的大量失血或其他傷害，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-16","year":103,"qnum":16,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"車禍致腦外傷病人，術後，心搏:118/min，血壓:84/44mmHg，ICP:34mmHg，Sao2:88mmHg 下列何者為錯?","opts":[{"k":"A","t":"可提升 FiO2。"},{"k":"B","t":"不可提升 PEEP。"},{"k":"C","t":"想辦法升血壓。"},{"k":"D","t":"PaCO2 維持35mmH。"}],"answer":"B","expl":"TBI 術後 ICP 34、SBP 84 與 SaO2 88%，需要處理缺氧（提高 FiO2、必要時提高 PEEP）、低血壓（升壓維持 CPP）與維持 PaCO2 約 35 mmHg；PEEP 可適度提高以改善氧合，雖可能略增 ICP，但缺氧更有害，所以 (B)「不可提升 PEEP」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-17","year":103,"qnum":17,"topic":"小兒","subtopic":"總論／其他","stem":"下列有關兒童外傷之敘述何者為非","opts":[{"k":"A","t":"台灣在過去30 餘年來，事故傷害位居少年(1-14 歲)死亡的最大主因，但死亡個案大幅下降。"},{"k":"B","t":"民國 102 年的全國死因統計中，1-14 歲者之惡性腫瘤首度成為首要死因，事故傷害死亡數居次，兩者極為接近。"},{"k":"C","t":"兒童外傷事故地點主要發生在家中或學校；機轉則以跌倒摔落事故為主。"},{"k":"D","t":"兒童外傷死亡則以交通事故為主。"},{"k":"E","t":"燒燙傷在兒童外傷中個案並不多，非主要課題。"}],"answer":"E","expl":"兒童外傷：事故傷害長期為 1–14 歲主要死因，近年死亡數下降；跌落是常見機轉，交通事故導致死亡為主；燒燙傷在兒童外傷中其實相當常見（尤其熱液燙傷），是重要課題，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-18","year":103,"qnum":18,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"下列有關老人外傷之敘述何者為非","opts":[{"k":"A","t":"老人較無法承受缺氧狀態，故面對外傷後休克的個案需盡快插管"},{"k":"B","t":"老人對胸部外傷的耐受性較差，單純肋骨骨折或肺部挫傷也可能導致呼吸衰竭。"},{"k":"C","t":"老人有較多比例具有冠狀動脈疾病，同時全身總血量也隨年紀逐漸降低，故外傷出血休克者常常呈現明顯心搏過速(tachycardia)的現象。"},{"k":"D","t":"因為老人常有高血壓的問題，故單純以血壓來判斷失血量常會失真。"},{"k":"E","t":"針對腹部實質器官外傷出血，非手術療法與早期手術止血相比，有較高的風險。"}],"answer":"C","expl":"老年人因 beta-blocker、自律神經與心臟傳導老化，在出血性休克時常「不一定出現明顯 tachycardia」，所以 (C) 錯。(A)(B)(D) 為老年外傷原則：低耐受、胸傷易呼吸衰竭、血壓基礎值偏高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-19","year":103,"qnum":19,"topic":"小兒","subtopic":"總論／其他","stem":"1 歲半大的女童自高約 1 公尺的桌上不慎摔落，頭部撞到地板，立刻嚎啕大哭，整個過程並無意識喪失現象，至急診室檢查其他四肢活動及行為大致正常，下列何項陳述正確？","opts":[{"k":"A","t":"病童比較難以溝通，所以GCS的判定方法對小兒科病人並不適用。"},{"k":"B","t":"病童在急診室觀察3小時後，若無異常現象發現，可安心離院，回家觀察。"},{"k":"C","t":"病童頭部與軀幹比例較成人大，顱骨較成人薄，所以造成頭骨骨折的機會較高。"},{"k":"D","t":"病童對顱內出血及腦水腫的耐受性比成人差，頭部外傷的預後相對也比成人差。"},{"k":"E","t":"病童頭部受傷後並無意識喪失現象，為減少放射線的暴露，不需安排頭部電腦斷層檢查。"}],"answer":"C","expl":"同 101-28：嬰幼兒頭部相對大、顱骨薄，頭骨骨折機率較高，所以 (C)。是否需要 CT 可依 PECARN；GCS 有小兒版（pediatric GCS）可用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-20","year":103,"qnum":20,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"老年酗酒者跌倒後出現上肢無力重於下肢、反射亢進與感覺障礙，符合 central cord syndrome（常見於頸椎退化的 hyperextension injury），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-21","year":103,"qnum":21,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一位20 歲男性在右胸乳頭上方被刺一刀，送醫院後呈現休克狀態，已放置氣管內插管，並已靜脈輸注2000 cc Lactated Ringer，胸管只引流出 500cc 血液，目前血壓仍是60 /0 mmHg，心跳160 下/分，下列處置何者最優先？","opts":[{"k":"A","t":"做血管攝影。"},{"k":"B","t":"緊急開胸術。"},{"k":"C","t":"腹部CT 檢查。"},{"k":"D","t":"胸部CT 檢查。"},{"k":"E","t":"立即照胸部X 光。"}],"answer":"B","expl":"同 97-19：胸部穿刺傷、休克、胸管 500 mL 且血壓 60/0，要立即 emergency thoracotomy，所以 (B)。補充：已輸 2000 cc LR 超出 ATLS 10/11 對晶體液的建議。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-22","year":103,"qnum":22,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關 診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm3。"},{"k":"C","t":"流出液白血球≧500/mm3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"DPL 陽性標準（鈍傷）：抽出 ≥10 mL 血、RBC >100,000/mm³、WBC >500/mm³、見細菌、膽汁、食物殘渣；500,000/mm³ 並非標準值，所以 (B) 非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-23","year":103,"qnum":23,"topic":"腹部","subtopic":"肝臟","stem":"一個年輕男性外傷患者被送至急診，診斷為肝臟撕裂傷併腹內出血。腹部超音波 掃瞄評估出血量約 1000 cc。下列何者為此患者之臨床表徵？","opts":[{"k":"A","t":"脈搏壓變寬。"},{"k":"B","t":"尿輸出量降到正常值以下。"},{"k":"C","t":"收縮壓維持不變，而舒張壓上升。"},{"k":"D","t":"嗜睡。"}],"answer":"C","expl":"失血約 1000 mL（約 15–30%，Class II）時，交感神經代償使舒張壓上升、脈搏壓變窄，而收縮壓維持不變，所以 (C)。(A) 脈搏壓是變窄不是變寬；(D) 嗜睡屬 Class III 以上。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-24","year":103,"qnum":24,"topic":"氣道","subtopic":"總論／其他","stem":"一名18 歲女性，因機車車禍而送至醫院。由於在車禍現場有意識不清的現象，已 於到院前已經插管，另外右大腿有一深撕裂傷，在救護車上有給予簡單包紮。到院後給予1000 毫升的林格氏液輸液後，血壓由88/67 mm Hg 提升至 122/78 mm Hg。\n由於病人仍未清醒，因此安排電腦斷層檢查，但在正要送病人去檢查時，發現病患的血壓又變為86/63 mm Hg，此時下一步的處理何者較適當？","opts":[{"k":"A","t":"趕快送去做電腦斷層，以盡速查明意識不清問題。"},{"k":"B","t":"趕快再給予1000 毫升的林格氏液後，再去做電腦斷層。"},{"k":"C","t":"先做腹部超音波檢查(FAST)，以排除腹部出血的問題。"},{"k":"D","t":"先確定氣管插管有無問題。"},{"k":"E","t":"檢查右大腿深撕裂傷處是否仍持續出血。"}],"answer":"D","expl":"病人先前輸液後暫時反應（transient responder），再度低血壓，要持續找出血。官方答案 (D) 強調按照 ABC 先確認氣管內管位置與通氣（DOPE 概念）。同時還需要 FAST、檢查大腿出血與準備輸血。補充：ATLS 10/11 對再次輸液 1000 mL RL 的做法不建議，應考慮輸血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-25","year":103,"qnum":25,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"參照上圖，下列有頸部穿刺傷(neck stab wound)的敘述何者為是？","opts":[{"k":"A","t":"Zone-I injury，一般不做任何檢查直接開刀"},{"k":"B","t":"Zone-I 和 Zone-II 的分界是 thyroid gland。"},{"k":"C","t":"Zone-III injury，可能合併 vertebral artery injury。"},{"k":"D","t":"Zone-II injury 即使合併 hard signs (bruit, expanding hematoma)，也要做angiography 確定有無血管損傷。"},{"k":"E","t":"Zone-I injury 不可能造成食道破裂。"}],"answer":"C","expl":"頸部穿刺傷（見圖：Zone I 為鎖骨至 cricoid、Zone II 為 cricoid 至下顎角、Zone III 為下顎角以上）。Zone III 靠近顱底，可能合併 vertebral/internal carotid artery injury，所以 (C)。(A) Zone I 不是一律直接開刀；(B) 分界為 cricoid cartilage；(D) 有 hard signs 需手術探查，不需先做 angiography；(E) Zone I 可傷及食道。","outdated":false,"suspect":false,"flagNote":"","images":["p113-1.jpg"]},{"id":"103-26","year":103,"qnum":26,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關穿刺傷(penetrating trauma)的敘述何者為非？\na. ㄧ般槍傷的出口(exit)，相對進口(entrance)有較嚴重的周圍擦傷。\nb. 槍傷造成的 temporary cavity 一般比 permanent cavity 來的大。\nc. 槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。\nd. 治療槍傷時，以直線原則預測經過路徑(trajectory)可能會有偏差。\ne. 治療穿刺傷時病患收縮血壓應該控制在 140mmHg 以上為佳。","opts":[{"k":"A","t":"a+c+e。"},{"k":"B","t":"a+c。"},{"k":"C","t":"b+d+e。"},{"k":"D","t":"b+e。"},{"k":"E","t":"a+e。"}],"answer":"E","expl":"a 錯：槍傷「入口」才有 abrasion collar，出口通常較大且不規則；e 錯：穿刺傷不建議把 SBP 維持在 140 mmHg 以上，應採 permissive hypotension 直到手術止血。b、c、d 為正確敘述，所以 (E) a+e。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-27","year":103,"qnum":27,"topic":"胸部","subtopic":"總論／其他","stem":"56 歲女性騎機車被汽車擦撞，於救護車上呈現到院前死亡後 5 分鐘送抵急診，病患外觀無明顯出血及四肢變形，超音波檢查發現有腹腔內出血，骨盆檢查發現為穩定之骨盆，經施予心肺復甦術、緊急氣管內管置入、輸液 1000cc 及緊急輸血4U PRBC 後 5 分鐘發現有回復生命跡象，心跳為 130/min、收縮血壓70mmHg；若本院為重度級急救責任醫院，以下處置何者最適當？","opts":[{"k":"A","t":"安排全身電腦斷層確認是否有腦出血並確認腹腔內損害狀況。"},{"k":"B","t":"立即安排手術室並由急救現場 2 位醫師確認後送入手術室進行剖腹手術。"},{"k":"C","t":"因為存活率極低，應趕緊聯繫家屬並解釋，以避免無效醫療。"},{"k":"D","t":"繼續輸血及輸液治療並等待 15 分鐘，在確認病患不再停止心跳後再行處置。"},{"k":"E","t":"請神經外科醫師確認是否已腦死再作打算。"}],"answer":"B","expl":"病人在到院前死亡後 5 分鐘到院，經 CPR 與輸血後恢復生命徵象，FAST 見腹內出血，應立即進手術室，由現場 2 位醫師確認後（依緊急情況規定）開刀止血，所以 (B)。(A) 不穩定不應去做 CT；(C)(D)(E) 延誤處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-28","year":103,"qnum":28,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"某鬧區突傳出槍響，有人發現一名約30歲、體重約70公斤之男性左上腹中彈，送抵急診時意識混亂、口鼻無出血、心跳為140/min、收縮血壓70mmHg，經緊急氣管內管置入、輸液1000cc及輸血4U PRBC後，心跳仍為140/min、收縮血壓75mmHg；\n超音波檢查發現有腹腔內出血，若本院為重度級急救責任醫院，以下處置何者不適當？","opts":[{"k":"A","t":"立即安排手術室進行剖腹手術。"},{"k":"B","t":"手術中發現腹腔內出血量達4500毫升(ml)脾臟及左腎有損傷及持續大量出血時應立即摘除脾臟及左腎。"},{"k":"C","t":"手術中發現降結腸有穿透性損傷時應立即進行切除及吻合重建手術。"},{"k":"D","t":"為避免腹部腔室症候群，不應將腹直肌鞘直接縫合。"},{"k":"E","t":"給予抗生素治療。"}],"answer":"C","expl":"血流動力學不穩定的槍傷，若降結腸有穿透性損傷，應採 damage control（切除、暫不吻合），不應立即吻合重建，所以 (C) 不適當。(A) 緊急剖腹；(B) 持續大量出血可快速摘除脾臟與左腎；(D) 避免關腹造成 ACS；(E) 預防性抗生素。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-29","year":103,"qnum":29,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"有關損害控制式復甦 (damage control resuscitation) 與傳統輸液復甦之比較，何者為是？","opts":[{"k":"A","t":"傳統輸液復甦，使血壓升高，移開了血塊，造成出血量增加。"},{"k":"B","t":"傳統輸液復甦，會使凝血異常 (coagulopathy) 的情況惡化。"},{"k":"C","t":"傳統輸液復甦，會造成組織水腫，進而可能形成腹部腔室症候群。\n(abdominal compartment syndrome) 及多重器官衰竭。"},{"k":"D","t":"損害控制式復甦，讓傷患的平均動脈壓 (mean arterial pressure)維持在 85 mm-Hg 上下即可。"},{"k":"E","t":"損害控制式復甦強調儘早輸血，並降低FFP : P-RBC和P-RBC : platelet 的比例。"}],"answer":"C","expl":"DCR 與傳統輸液復甦的差異：傳統大量晶體液會造成 dilutional coagulopathy、血栓脫落再出血、組織水腫、ACS 與 MOF。官方答案 (C)。","outdated":false,"suspect":true,"flagNote":"(A)(B)(C) 在文獻中皆有支持，題目有多個正確選項；(D) MAP 85 太高（permissive hypotension 約 SBP 80–90、MAP 50–65）；(E) 降低 FFP：RBC 比例是錯的（應提高 plasma 比例）。考試以官方 (C) 為準。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"103-30","year":103,"qnum":30,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"下列何者符合 trauma damage control 的 principle？","opts":[{"k":"A","t":"許可的低血壓(permissive hypotension)。"},{"k":"B","t":"肝臟破裂手術中發現傷患有凝血異常(coagulopathy)，更改術式為 anatomic resection 以節省手術時間。"},{"k":"C","t":"腹壁切口可使用替代物如點滴軟袋暫時封閉，以防止或減輕腹部腔室症候群(abdominal compartment syndrome)。"},{"k":"D","t":"需要大量輸血之傷患，使用 P-RBC : FFP : platelet 比率為1 : 1 : 1 之血品。"},{"k":"E","t":"緊急開腹後接著要去做骨盆骨折之動脈栓塞者，肚子切口可以先不關。"}],"answer":"B","expl":"Damage control 的原則包括：permissive hypotension、早期 balanced 輸血（1:1:1）、暫時關腹（如 Bogota bag／靜脈輸液軟袋）、必要時不關腹。肝破裂合併凝血病變時應 packing，而非 anatomic resection，所以 (B) 才是「不符合」DC 原則的敘述。","outdated":false,"suspect":true,"flagNote":"題幹問「何者符合」，但 (A)(C)(D)(E) 都符合，只有 (B) 不符合，答案是 (B)，推測題幹原意是「何者不符合」而漏掉「不」字（OCR／命題錯字）。官方答案 (B) 與此推測相符。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"103-31","year":103,"qnum":31,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"30 歲男性為機車騎士有戴安全帽，因路滑而跌倒，至 貴院醫院急診時，BP:\n70/50mmhg,HR:135 次/min,腹部鼓脹且有輕微瀰漫性疼痛，GCS12 分。下列何者處置最不恰當:","opts":[{"k":"A","t":"因可能有腹內出血，病人應緊急安排手術。"},{"k":"B","t":"可使用超音波檢查是否有腹內出血。"},{"k":"C","t":"可使用診斷性腹膜灌洗術(DPL)確認是否有腹內出血。"},{"k":"D","t":"應即刻安排腹部電腦斷層檢查腹內受傷的器官。"},{"k":"E","t":"以上皆是恰當的處置。"}],"answer":"D","expl":"血壓 70/50、HR 135、腹部鼓脹的不穩定病人，不適合做 CT（要先 FAST 或 DPL，確認腹內出血後直接開刀），所以 (D) 最不恰當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-32","year":103,"qnum":32,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"下列有關Damage control surgery(傷害控制手術)術後，常規再手術之條件，何者為非？","opts":[{"k":"A","t":"血氧飽和度大於95%。"},{"k":"B","t":"凝血酶原時間(Prothrombin time) 小於十五秒。"},{"k":"C","t":"部分凝血活酶原時間(Activated thromboplastin time) 小於三十五秒。"},{"k":"D","t":"血小板應大於100,000 ul (100x 104 /cumm)µL。"},{"k":"E","t":"Cardiac Index (心臟指數)應大於 3 L/min/m2。"}],"answer":"D","expl":"DCS 後再手術前的復甦目標：體溫 >35–36°C、SpO2 >95%、PT <15 秒、aPTT <35 秒、Cardiac Index >3、lactate 下降、血小板約 >50,000 即可；官方認為 (D)「血小板需 >100,000」不是常規條件，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-33","year":103,"qnum":33,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"有關嚴重外傷病患之急救，請選出正確敘述？","opts":[{"k":"A","t":"所有傷患均應使用“Damage Resuscitation”"},{"k":"B","t":"輸液選擇以“crystalloid”為主"},{"k":"C","t":"“permissive hypotension”觀念可應用於急救"},{"k":"D","t":"“Damage Resuscitation”僅適用胸腹外傷領域"},{"k":"E","t":"不當採用“Damage Control”不會增加病人死亡率"}],"answer":"C","expl":"同 98-12：damage control resuscitation 包含 permissive hypotension 與早期 balanced 輸血，所以 (C)。不當採用 DCS 會增加死亡率；crystalloid 並非主要輸液；DCR 也不限胸腹外傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-34","year":103,"qnum":34,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"外傷病患之檢查及治療下列何者為錯?","opts":[{"k":"A","t":"懷孕外傷病患不能行 X 光檢查。"},{"k":"B","t":"根據第9 版 ALTS，初級評估當中，不需照頸椎平行射線側位攝影 (cross table lateral C-spine x-ray)。"},{"k":"C","t":"外傷病人重點腹部超音波 (Focused assessment sonography in trauma, FAST)及診斷性腹膜灌洗術(Diagnostic peritoneal lavage, DPL) 不屬於二級評估(Secondary survey)當中的檢查。"},{"k":"D","t":"神經性休克 (Neurogenic shock) 很少發生於第六胸椎以下脊椎受損之病患。"},{"k":"E","t":"神經性休克 (Neurogenic shock) 併嚴重的心搏過緩 (Bradycardia) 可使用阿托平 (Atropine)。"}],"answer":"A","expl":"孕婦外傷時，診斷所需的 X-ray 與 CT 仍可進行（母親優先，並盡量降低劑量），不能說「不能行 X 光」，所以 (A) 錯。(B) ATLS 第 9 版 primary survey 不需常規 cross-table C-spine film；(D) neurogenic shock 多見於 T6 以上；(E) 嚴重 bradycardia 可用 atropine。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-35","year":103,"qnum":35,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"在連枷胸 Flail chest，病患發生低血氧 Hypoxia 的主要原因為：","opts":[{"k":"A","t":"斷裂肋骨造成的創傷性氣胸或血胸。"},{"k":"B","t":"低血容性休克 Hypovolemic shock。"},{"k":"C","t":"因多重肋骨骨折所引致的胸壁不協調性運動 Paradoxical movement。"},{"k":"D","t":"疼痛引發的胸壁活動受限(Restricted movement)合併肺部挫傷。"},{"k":"E","t":"以上皆非。"}],"answer":"D","expl":"Flail chest 低血氧主要來自疼痛造成胸壁活動受限，合併底下肺挫傷，而非 paradoxical movement 本身，所以 (D)。（這與 99-50 官方答案 (D) mediastinal shift 不同，也說明該題答案有疑義。）","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-36","year":103,"qnum":36,"topic":"頭部TBI","subtopic":"腦死判定與器官捐贈","stem":"嚴重腦外傷病人下列何項非腦死判定條件的臨床檢查診斷?","opts":[{"k":"A","t":"GCS 昏迷指數=3。"},{"k":"B","t":"曈孔對光無反應。"},{"k":"C","t":"腦幹反射消失。"},{"k":"D","t":"無自然呼吸反應。"},{"k":"E","t":"去腦僵直反應。"}],"answer":"E","expl":"同 102-6：腦死判定的臨床條件包括 GCS 3、瞳孔無光反應、brainstem reflexes absent、apnea；去腦僵直表示腦幹仍有功能，不屬腦死，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-37","year":103,"qnum":37,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"下列關於Injury severity score(ISS)的描述評論，何者最不恰當？","opts":[{"k":"A","t":"根源於 Abbreviated injury score(AIS)。"},{"k":"B","t":"將全身分為五個器官部位計分。"},{"k":"C","t":"最低1 分，最高 75 分。"},{"k":"D","t":"若有任何一項 AIS 6 分，ISS 會自動變為75 分。"},{"k":"E","t":"台灣健保局將ISS>9分列為重大外傷。"}],"answer":"E","expl":"同 102-7：ISS 由 AIS 發展，最低 1 分、最高 75 分（任何 AIS 6 自動為 75）；官方答案 (E)「健保署將 ISS >9 列為重大外傷」為錯（一般以 ISS ≥16 為 major trauma）。","outdated":false,"suspect":true,"flagNote":"選項 (B)「五個器官部位」也不正確：ISS 為六個身體區域，104-6 即以 5 區為錯誤敘述。所以 (B)(E) 都有問題，考試以官方 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"103-38","year":103,"qnum":38,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列關於孕婦生理變化及外傷處理的敘述何者最恰當？","opts":[{"k":"A","t":"孕婦的血量較一般狀況為低，稱作生理性貧血。"},{"k":"B","t":"孕婦的凝血因子相對不足，容易出血。"},{"k":"C","t":"孕婦受傷急救時，為減少下腔靜脈壓迫，要考慮右側臥。"},{"k":"D","t":"急救孕婦時發生胎兒流產的最多原因是子宮破裂。"},{"k":"E","t":"即使是懷孕期，不尋常的傷情仍應考慮家暴的可能性。"}],"answer":"E","expl":"同 96-23：孕婦外傷若傷勢不尋常，要考慮 intimate partner violence，所以 (E)。其他：孕婦血漿容積增加造成 physiologic anemia；凝血因子升高；急救宜採左側臥；胎盤早剝為最常見胎兒流失原因。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-39","year":103,"qnum":39,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"針對骨盆骨折合併休克之病患，除基本之primary survey外，以下何種處置最不適當？","opts":[{"k":"A","t":"經動脈血管栓塞。"},{"k":"B","t":"由骨科醫師進行骨外固定經動脈血管栓塞。"},{"k":"C","t":"由外科醫師執行preperitoneal packing並以床單固定骨盆經動脈血管栓塞。"},{"k":"D","t":"由外科醫師執行雙側髂內動脈結紮手術。"},{"k":"E","t":"於急診置放主動脈內氣球阻斷下肢血流+經動脈血管栓塞。"}],"answer":"D","expl":"同 102-20：雙側 internal iliac artery ligation 因側枝循環豐富、止血效果差與耗時，現已少用，所以 (D) 最不適當；binder、external fixation、preperitoneal packing、angioembolization、REBOA 都是現行選項。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-40","year":103,"qnum":40,"topic":"休克輸血","subtopic":"總論／其他","stem":"關於休克所產生的內分泌變化的敘述下列何者為非?","opts":[{"k":"A","t":"休克會造成交感神經活性增加，使得 adrenal medulla 在 24-48 小時內分泌catecholamine 增加。"},{"k":"B","t":"休克會刺激 hypothalamus 釋放出 corticotrophin-releasing hormone。"},{"k":"C","t":"在休克所產生發炎反應中最早出現的 proinflammatory cytokines 為 Tumor necrosis factor-ɑ(TNF-ɑ) 。"},{"k":"D","t":"低血容休克時會刺激下視丘釋放 anti-diuretic hormone (ADH)造成腎臟遠端腎小管對於水分通透性下降，降低體內水份及鈉離子流失。"},{"k":"E","t":"休克早期會因發炎反應造成中性球(neutrophil)活性增加進而引起細胞及器官功能受損。"}],"answer":"D","expl":"同 102-24：ADH（vasopressin）作用在 distal tubule 與 collecting duct 使水分通透性「增加」，減少水分流失，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-41","year":103,"qnum":41,"topic":"頭部TBI","subtopic":"總論／其他","stem":"嚴重腦外傷病人昏迷指數 3-8 分，經急救血行動力學(Hemodynamic)正常，為降低腦壓增高，給予短時間過度換氣處置時，維持血中二氧化碳下列何項氣體壓力濃度較為適度?","opts":[{"k":"A","t":"PaCO2 25mmHg。"},{"k":"B","t":"PaCO2 30mmHg。"},{"k":"C","t":"PaCO2 35mmHg。"},{"k":"D","t":"PaCO2 40mmHg。"},{"k":"E","t":"PaCO2 45mmHg。"}],"answer":"C","expl":"同 102-26：嚴重 TBI 的短暫 hyperventilation（如 herniation 橋接）PaCO2 以 30–35 mmHg 為限，避免 <25 造成腦缺血，官方答案 (C) 35 mmHg。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-42","year":103,"qnum":42,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"42.懷孕六個月婦女，因車禍就診。血壓、心跳與呼吸等生命徵象穩定，但神智不清，昏迷指數12 分(Glasgow Coma Scale：E3V4M5)，瞳孔不等大，對光反應趨緩，右下肢變形骨折。你的處置可不包括：","opts":[{"k":"A","t":"安排腹部超音波(FAST)"},{"k":"B","t":"安排胸部X-光(Chest Film)。"},{"k":"C","t":"安排頭部電腦斷層掃描(Brain CT Scan)。"},{"k":"D","t":"監測胎兒心音(Fetal heart beat)。"},{"k":"E","t":"集尿液驗HCG。"}],"answer":"E","expl":"同 102-32：已知懷孕 6 個月的外傷病人，不需再驗尿 HCG；其他 FAST、CXR、head CT 與胎心音監測都需要，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-43","year":103,"qnum":43,"topic":"頭部TBI","subtopic":"腦死判定與器官捐贈","stem":"嚴重頭部外傷病人，有經低溫療法(Hypothermia)及巴比妥藥物昏迷療法(Barbiturate coma)腦死判定結果為？","opts":[{"k":"A","t":"不受上述兩類療法影響。"},{"k":"B","t":"病人體溫恢復正常即可判定。"},{"k":"C","t":"需等病人生理參數恢復正常及腦中樞神經不受藥物影響才能判定。"},{"k":"D","t":"兩側瞳孔放大，對光無反射應即可判定。"},{"k":"E","t":"昏迷指數3 分即可判定。"}],"answer":"C","expl":"同 101-50：腦死判定前須排除可逆因素（低體溫、鎮靜／巴比妥類藥物影響、休克與代謝異常），需等藥物代謝與生理參數恢復後才能判定，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-44","year":103,"qnum":44,"topic":"頭部TBI","subtopic":"總論／其他","stem":"病人為一24 歲男性因騎機車與計程車對撞，神智不清經腦部電腦斷層檢查有腦外傷性蜘蛛膜下腔出血，右胸部有血胸及右側大腿股骨骨折，此病人之外傷嚴重度分數評分表(Injury severity score, ISS)共幾分？","opts":[{"k":"A","t":"22+22+22=12。"},{"k":"B","t":"32+32+32=27。"},{"k":"C","t":"42+42+42=48。"},{"k":"D","t":"22+32+42=29。"},{"k":"E","t":"22+32+22=27。"}],"answer":"B","expl":"同 101-48：ISS = 三個不同區域最高 AIS 平方和，head（traumatic SAH）3、chest（hemothorax）3、extremity（femur fracture）3，所以 3² + 3² + 3² = 27，(B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-45","year":103,"qnum":45,"topic":"胸部","subtopic":"Tracheobronchial injury","stem":"關於 Tracheobronchial injuries 之敘述何者為非?","opts":[{"k":"A","t":"最常發生的位置在離 Carina 2.5 cm 距離內。"},{"k":"B","t":"常出現的症狀為 Stridor，Hemoptysis 及 Cervical subcutaneous emphysema。"},{"k":"C","t":"不建議用支氣管來指引做氣管插管。"},{"k":"D","t":"在呼吸機的使用上不建議用正壓呼吸(Positive pressure ventilator)。"},{"k":"E","t":"要確定Tracheobronchial injuries需要做支氣管鏡檢查。"}],"answer":"C","expl":"氣管支氣管損傷多在 carina 2.5 cm 內，症狀包括 stridor、hemoptysis 與頸部皮下氣腫，確診靠 bronchoscopy；插管時最好使用 bronchoscope 引導（避免盲插擴大傷口），所以 (C)「不建議用支氣管鏡指引插管」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-46","year":103,"qnum":46,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"胸部創傷引起的主動脈剝離(Aortic dissection)在 X 光片上所顯示的放射跡象(radiologic signs)，下列何者為非：","opts":[{"k":"A","t":"縱隔增寬 (widened mediastinum) 。"},{"k":"B","t":"氣管偏移。"},{"k":"C","t":"左支氣管上移。"},{"k":"D","t":"第一或第二肋骨或者是肩胛骨骨折。"},{"k":"E","t":"右支氣管上移。"}],"answer":"C","expl":"同 101-33：主動脈損傷的 CXR 徵象包含縱隔增寬、氣管右偏、left mainstem bronchus 被壓低（depression）等，不是「左支氣管上移」，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-47","year":103,"qnum":47,"topic":"影像FAST","subtopic":"總論／其他","stem":"使用全身電腦斷層 (whole CT Scan) 檢查外傷病患，可幫助診斷頭、胸、腹部外傷，但對於下列那一項診斷並無幫助？","opts":[{"k":"A","t":"肝臟鈍傷破裂出血(Blunt liver injury)。"},{"k":"B","t":"腸道破裂(intestine perforation)。"},{"k":"C","t":"肺部鈍挫傷(Pulmonary contusion)。"},{"k":"D","t":"胸部心臟大血管(Great vessel injury)。"},{"k":"E","t":"心臟鈍挫傷(Blunt cardiac injury)。"}],"answer":"E","expl":"同 101-20：CT 對 blunt liver injury、腸穿孔、pulmonary contusion、大血管損傷有價值，但無法診斷 blunt cardiac injury，需靠 ECG、troponin 與 echocardiography，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-48","year":103,"qnum":48,"topic":"小兒","subtopic":"兒虐（child abuse）警示徵象","stem":"診治兒童外傷病患時，下列何者是應懷疑有「兒虐 Child Abuse」的警告徵象Red Flags：","opts":[{"k":"A","t":"父母親或照顧者間提供的病史不一致。"},{"k":"B","t":"反覆發生外傷，並於不同的院所就診。"},{"k":"C","t":"視網膜出血。"},{"k":"D","t":"外傷程度遠超過所描述的受傷機轉。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"同 100-19：兒虐 red flags 包含病史不一致、反覆受傷於不同院所、retinal hemorrhage（shaken baby）、傷勢與機轉不符，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-49","year":103,"qnum":49,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"下列有關主動脈裂傷(Aortic disruption) 之敘述何者為非？","opts":[{"k":"A","t":"最主要是在ligamentum arteriosum of aorta處造成撕裂傷。"},{"k":"B","t":"在X光判讀上可見aortic knob。"},{"k":"C","t":"對於縱膈腔血腫的病患如果接受胸部顯影劑電腦斷層檢查為陰性，主動脈就沒有必要再接受其他進一步檢查。"},{"k":"D","t":"TEE (transesophageal echocardiography) 對於主動脈裂傷是一個有效而且較少侵襲性的檢查。"},{"k":"E","t":"近來 Endovascular stenting graft 針對近端降主動脈裂傷病患的治療有增加趨勢。"}],"answer":"B","expl":"同 100-24：主動脈損傷的 CXR 典型表現是 aortic knob 消失（obliterated），不是可見 aortic knob，所以 (B) 為非。TEVAR 近年漸成為首選。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"103-50","year":103,"qnum":50,"topic":"脊椎脊髓","subtopic":"SCIWORA／Chance fracture","stem":"腰椎損傷，經X 光檢查報告有 Chance fracture，是下列何種診斷?","opts":[{"k":"A","t":"腰椎關節移位。"},{"k":"B","t":"腰椎壓迫性骨折。"},{"k":"C","t":"腰椎體垂直骨折。"},{"k":"D","t":"腰椎體橫斷骨折。"},{"k":"E","t":"腰椎體斜面骨折。"}],"answer":"D","expl":"同 100-28：Chance fracture 是 flexion-distraction 造成的橫向貫穿椎體骨折（安全帶式損傷），常合併腹內傷害，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-1","year":104,"qnum":1,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"有關於 Blunt abdominal trauma 引發的腹部腔室症候群 (abdominal compartment syndrome)，下列敘述何者為是?","opts":[{"k":"A","t":"高於正常之腹內壓力，導致腹內器官灌流不足，對呼吸影響不大。"},{"k":"B","t":"腹內高壓的定義是指腹內壓超過 12mmHg。"},{"k":"C","t":"腹內壓超過20mmHg 是外科手術的適應症。"},{"k":"D","t":"腹內壓力監測一定要穿刺針入腹腔才會準確。"},{"k":"E","t":"少尿常是腹內高壓的第一個臨床表徵。"}],"answer":"E","expl":"WSACS 定義：IAH 為持續 IAP ≥12 mmHg；ACS 為 IAP >20 mmHg 且新發器官功能障礙；少尿是早期臨床表徵，所以官方答案 (E)。","outdated":false,"suspect":true,"flagNote":"選項 (B)「IAH 定義為腹內壓超過 12 mmHg」其實也符合 WSACS 定義（≥12），所以 (B)(E) 都可能正確；(C) IAP >20 不是單獨的手術指標，需合併器官功能障礙；(D) 常以 bladder pressure 測量，不需穿刺入腹腔。考試以官方 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"104-2","year":104,"qnum":2,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"36 歲機車騎士酒後騎車撞電線桿，被 EMT 立即送入急診，理學檢查發現左胸壁有瘀傷且有氣胸，經置放胸管後，病人仍有血壓下降心跳加速及端坐呼吸情形，下列敘述何者為非?","opts":[{"k":"A","t":"立即抽血檢驗血清中酵素 cardiac enzymes 可鑑別診斷心肌挫傷。"},{"k":"B","t":"心臟超音波可診斷是否發生心包膜填塞。"},{"k":"C","t":"持續心搏過速是心肌挫傷的早期徵候。"},{"k":"D","t":"持續心電圖變化或 Q 波可以指出 transmural injury。"},{"k":"E","t":"需檢視胸管有無阻塞。"}],"answer":"A","expl":"鈍性胸傷後血壓下降、心搏過速：考慮 tension pneumothorax、tamponade、胸管阻塞與 blunt cardiac injury。血清酵素（cardiac enzymes/troponin）上升有延遲，立即抽血無法「鑑別」心肌挫傷或排除其他原因，所以 (A) 為非；心臟超音波可診斷 tamponade 與心功能。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-3","year":104,"qnum":3,"topic":"休克輸血","subtopic":"抗凝／抗血小板藥物與外傷出血","stem":"下列有關影響到血小板而凝血異常的藥物之敘述何者為非？","opts":[{"k":"A","t":"Clopidogrel(Plavix)。"},{"k":"B","t":"Aspirin。"},{"k":"C","t":"Warfarin。"},{"k":"D","t":"Ibuprofen。"},{"k":"E","t":"Cilostazol(Pletal)。"}],"answer":"C","expl":"Clopidogrel、aspirin、ibuprofen（NSAID）與 cilostazol 影響血小板功能；warfarin 是 vitamin K antagonist，影響凝血因子 II、VII、IX、X，不屬於血小板藥物，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-4","year":104,"qnum":4,"topic":"骨盆泌尿","subtopic":"總論／其他","stem":"下列有關「外生殖器」外傷之說明何者有誤?","opts":[{"k":"A","t":"MRI scan is the recommended diagnostic test。"},{"k":"B","t":"The external genitalia are involved in one-third to two-thirds of all genitourinary injuries。"},{"k":"C","t":"Blunt scrotal trauma can lead to testicular rupture in as many as 50% of patients。"},{"k":"D","t":"Exploration, rather than pursuing further diagnostic tests, is better in patients with equivocal findings on ultrasonography。"},{"k":"E","t":"Early intervention results in >90% preservation of the testis while delayed surgery ultimately leads to orchiectomy in 45-55%。"}],"answer":"A","expl":"外生殖器鈍傷首選診斷工具為 scrotal ultrasound，不是 MRI，所以 (A) 錯。(C) 鈍傷後睪丸破裂可達約 50%；(D) 超音波結果不明確時建議探查；(E) 早期處理（<72 小時）睪丸保留率高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-5","year":104,"qnum":5,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"關於燒傷的描述何者有誤？","opts":[{"k":"A","t":"對於成人可以使用”rule of nine”評估燒傷面積。"},{"k":"B","t":"焦痂切開術通常使用於環狀深二度至三度的區域，以改善末梢循環及呼吸。"},{"k":"C","t":"大面積燒傷僅是表皮缺損，要特別注意保暖，但是會直接引起全身其他器官衰竭的機會不高。"},{"k":"D","t":"在台灣大面積燒傷病患的初期輸液治療大多遵循 Parkland formula。"},{"k":"E","t":"建築物火災現場搶救出來的燒傷病患要特別注意吸入性嗆傷及並存其他形式的外傷，如骨折及鈍挫傷。"}],"answer":"C","expl":"大面積燒傷會引起 SIRS、低血容、橫紋肌溶解、ARDS、AKI 與 MODS，不是單純表皮缺損，會直接造成多器官衰竭，所以 (C) 錯。補充：ATLS 10 建議起始 2 mL/kg/%TBSA，再依尿量調整，以避免 fluid creep。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-6","year":104,"qnum":6,"topic":"總論評分","subtopic":"總論／其他","stem":"對於外傷嚴重度的計分，以下何者為非？","opts":[{"k":"A","t":"Injury Severity Score(ISS)是由 Baker 等人於1974 年所提出，目前台灣在醫院緊急醫療能力分級評定中規定病例需有 ISS 的紀錄。"},{"k":"B","t":"ISS 的計算是將身體分成 5 個區域分別計算其 Abbreviated Injury Scale (AIS)。"},{"k":"C","t":"AIS 的計分最高為6 分。"},{"k":"D","t":"ISS 的計分最高為 75 分。"},{"k":"E","t":"ISS 的缺點是對於一個區域的 AIS 只取其最高的分數進行計算，會忽略同一區域內多重器官受傷的影響。"}],"answer":"B","expl":"ISS 將身體分為六個區域（head/neck、face、chest、abdomen、extremities/pelvis、external），不是 5 個，所以 (B) 錯。AIS 最高為 6；ISS 最高為 75；ISS 只取每區最高 AIS，是其缺點。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-7","year":104,"qnum":7,"topic":"休克輸血","subtopic":"總論／其他","stem":"有關休克的描述下列何者為非？","opts":[{"k":"A","t":"外傷性休克最常見的原因是出血性休克。"},{"k":"B","t":"休克必須盡快矯正的原因是細胞因為缺血或缺氧造成細胞死亡將會導致個體死亡或其功能無法恢復。"},{"k":"C","t":"外傷病患產生神經性休克大多是因為高位脊髓損傷，最常見的理學檢查是低血壓伴隨心跳緩慢。"},{"k":"D","t":"治療休克必須對症下藥，所以找出休克的原因很重要，在找出原因前不宜給予任何治療以免影響進行鑑別診斷。"},{"k":"E","t":"在 ALTS 的初級評估口訣 ABCDE 中 C 代表循環，另一個重點就是止血。"}],"answer":"D","expl":"休克的處置不應等到找出原因才治療：外傷病人先假設是出血性休克，同時 resuscitation 與找原因，所以 (D) 錯。(C) 神經性休克為低血壓合併心搏緩慢；(E) C 代表 circulation 與 hemorrhage control。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-8","year":104,"qnum":8,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"外傷併嚴重脊椎受傷之病患評估下列何者正確?","opts":[{"k":"A","t":"嚴重脊椎受傷併四肢癱瘓病患，可於初級評估 (Primary survey)照胸部X 光時，同時照脊椎 X 光檢查。"},{"k":"B","t":"監控病患除一般生命徵象外，還要評估監控病患尿液輸出量，一般小孩應維持在0.5 mL/kg/h 以上。"},{"k":"C","t":"若需轉診病患，經初級評估及適當治療後，可不需做脊椎電腦斷層檢查直接轉院。"},{"k":"D","t":"脊椎受傷併嚴重休克病患，若無其他內出血，除給予輸液治療外，在 ATLS 指引中，不建議給予升壓劑。"},{"k":"E","t":"頸椎 C7 以上受損之病患，可能會喪失正常呼吸功能。"}],"answer":"D","expl":"官方答案為 (D)：「ATLS 不建議給升壓劑」。","outdated":true,"suspect":true,"flagNote":"依 ATLS 10，神經性休克若在適當輸液後仍低血壓，可使用 vasopressor（norepinephrine 等）維持灌流，所以 (D) 過時；104-9 (E) 也說可給升壓劑，兩題互相矛盾。另外選項 (E)「C7 以上受損可能喪失正常呼吸功能」也是明確正確的敘述（膈神經 C3–5，高位頸髓損傷影響呼吸）。因此官方答案 (D) 疑有誤，考試仍以官方答案為準。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"104-9","year":104,"qnum":9,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"嚴重胸椎受傷之病患評估及治療下列何者不正確?","opts":[{"k":"A","t":"若合併有頸椎受損的病患，需同時使用半硬式頸圈(semirigid collar)固定。"},{"k":"B","t":"長背板會影響脊椎電腦斷層檢查品質，需於檢查前移除。"},{"k":"C","t":"長背板通常需於次級評估(secondary survey)中移除。"},{"k":"D","t":"移除長背板需使用 Four-Person Logroll。"},{"k":"E","t":"此類休克病患，給予適當輸液治療及排除出血後，仍維持低血壓時，可給予升壓劑。"}],"answer":"B","expl":"胸椎損傷病人：長背板會造成壓瘡，且可能影響影像，應儘早移除（ATLS 10 建議儘快，不一定要等 secondary survey）；移除需 logroll；若合併頸椎傷需使用 semirigid collar；補液與止血後仍低血壓可給升壓劑。官方答案 (B) 認為「長背板影響脊椎 CT 品質」說法不正確，因為多數 CT 仍可在背板上完成。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-10","year":104,"qnum":10,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"下列何者不是目前腹部外傷 Damage control 的階段性作法?","opts":[{"k":"A","t":"Control of hemorrhage and contamination。"},{"k":"B","t":"Resuscitation。"},{"k":"C","t":"Early anastomosis of intestine 。"},{"k":"D","t":"Open abdominal wounds to avoid abdominal compartment syndrome。"},{"k":"E","t":"Packing and rush to SICU。"}],"answer":"C","expl":"Damage control 的階段：控制出血與污染、ICU 復甦與保暖、必要時暫時關腹（避免 ACS）、之後 definitive surgery。早期做腸道吻合會增加缺血與漏的風險，不是 damage control 的作法，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-11","year":104,"qnum":11,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"依據高級外傷救命術(ATLS) 建議，在外傷初始評估中(primary survey) 不包括：","opts":[{"k":"A","t":"頸椎的 x 光檢查(Cervical spine X-ray) 。"},{"k":"B","t":"呼吸道與呼吸的維持 (Airway maintains and breathing)。"},{"k":"C","t":"維持血循與控制出血 (Circulation with hemorrhage control)。"},{"k":"D","t":"頸椎的保護 (Cervical spine protection)。"},{"k":"E","t":"評估動脈脈搏血氧濃度( Pulse oximetry)。"}],"answer":"A","expl":"ATLS primary survey 的內容：airway with C-spine protection、breathing、circulation with hemorrhage control、disability、exposure，加上 adjuncts（ECG、pulse oximetry、CXR、pelvis X-ray、FAST）；頸椎 X-ray 不屬於 primary survey，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-12","year":104,"qnum":12,"topic":"頭部TBI","subtopic":"總論／其他","stem":"嚴重頭部外傷的年輕女性，頭部昏迷分數(GCS)=6；兩邊瞳孔：3mm 等大；對光反射：有；生命徵象穩定。下列各項治療頭部外傷的處置，在急診那一項最優先：","opts":[{"k":"A","t":"使用降腦壓藥物(osmotic diuretic)。"},{"k":"B","t":"積極治療全身性的高血壓(systemic hypertension)。"},{"k":"C","t":"避免低血壓出現(hypotension)，產生休克。"},{"k":"D","t":"減少腦部代謝需求。"},{"k":"E","t":"鑑別腦壓上昇的原因，針對血塊或腦腫治療。"}],"answer":"C","expl":"同 102-12：嚴重 TBI 早期最重要是避免 hypotension 與 hypoxia，防止 secondary brain injury，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-13","year":104,"qnum":13,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部傷害(Abdominal injuries)，實施非手術治療(Non-operative treatment)的敘述，最適當的為那項？","opts":[{"k":"A","t":"急救室腹部超音波檢查 (FAST)，近年建議以全身電腦斷層檢查取代。"},{"k":"B","t":"非手術治療的進展，重點是在急救室立即安排全身電腦斷層檢查(Whole body CT)。"},{"k":"C","t":"非手術治療的進展，主要是立即的血管攝影檢查(angiography study)。"},{"k":"D","t":"腹部肝臟、脾臟鈍挫傷出血，以非手術治療的比例，近年約佔 60%以上，成功率大於80%。"},{"k":"E","t":"腹部槍擊傷，並不適合非手術治療。"}],"answer":"D","expl":"近年肝脾鈍傷的 NOM 比例約 60% 以上，成功率 >80–90%，所以 (D)。(A) FAST 與 CT 互補，不是取代；(B)(C) NOM 進展的重點是血流動力學穩定與選擇性 angioembolization，不是立即全身 CT 或血管攝影；(E) 槍傷在特定穩定病人也可 selective NOM。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-14","year":104,"qnum":14,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"依據2014 年 WTA 的指南 (guideline)，下列關於 血液動力學不穩定(hemodynamic unstable) 的骨盆骨折之處理原則，何者有誤?","opts":[{"k":"A","t":"FAST positive，則先剖腹 (laparotomy)，並打外固定 (external fixation)。"},{"k":"B","t":"FAST negative，則固 定骨盆 ；如仍 然血 液動力 學不穩 定 ，則作動 脈栓塞(TAE) 。"},{"k":"C","t":"FAST negative，則作 腹膜前填料 (preperitoneal packing) 及外固定；如仍然血液動力學不穩定，則作動脈栓塞。"},{"k":"D","t":"FAST negative，則作 REBOA；如仍然血液動力學不穩定，則作動脈栓塞。"},{"k":"E","t":"FAST negative，則作動脈栓塞；如仍然血液動力學不穩定，則到加護病房輸血至血液動力學穩定。"}],"answer":"E","expl":"依 WSES 2014 骨盆骨折指引：血流動力學不穩定且 FAST negative，要先 pelvic binder，再 preperitoneal packing 或 REBOA／angioembolization 控制動脈出血，不能把病人留在 ICU 繼續輸血而不止血，所以 (E)。(A) FAST positive 時先 laparotomy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-15","year":104,"qnum":15,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"依據2012 年 EAST 的指南 (guideline)，下列關於老人創傷之處理原則，何者有誤?","opts":[{"k":"A","t":"送到醫學中心、外傷啟動等的門檻較低。"},{"k":"B","t":"昏迷指數小於 8 分者，如72 小時內昏迷指數沒有改善，則要思考是否限制更加積極性的治療介入。"},{"k":"C","t":"住院後兩小時內將 INR 矯正到 < 正常值的1.6 倍。"},{"k":"D","t":"「年齡」是預後不好的預測指標，可單獨作為限制照護的標準。"},{"k":"E","t":"除非傷患已達垂死狀態，或創傷過於嚴重，否則剛開始還是要積極治療。"}],"answer":"D","expl":"依 EAST 2012 老人創傷指引：降低轉診與啟動門檻、盡早積極復甦、抗凝血逆轉（INR <1.6）；年齡本身不能作為限制照護的單獨標準，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-16","year":104,"qnum":16,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"關於損害控制式復甦 (Damage Control Resuscitation)，下列敘述何者錯誤?","opts":[{"k":"A","t":"容許的低血壓 (Permissive Hypotension)。"},{"k":"B","t":"及早積極地治療凝血功能障礙 (coagulopathy)。"},{"k":"C","t":"大量等張性晶質液 (isotonic crystalloid) 復甦。"},{"k":"D","t":"儘早進入大量輸血協議 (Massive Transfusion Protocol)。"},{"k":"E","t":"損害控制式手術 (Damage Control Surgery)。"}],"answer":"C","expl":"Damage control resuscitation 強調 permissive hypotension、早期 MTP、矯正 coagulopathy 與 DCS，並限制大量晶體液，所以 (C)「大量等張晶質液」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-17","year":104,"qnum":17,"topic":"氣道","subtopic":"總論／其他","stem":"一位顏面外傷、胸部外傷合併右側氣胸與右小腿骨折的多重外傷病患，已經插上胸管引流，並以石膏固定小腿骨折，照會牙科診察其下頷骨折。牙科值班醫師正準備幫他檢查時，原本生命徵象穩定的病人突然躁動，表現出呼吸困難、流冷汗等休克症狀。此時，第一時間應該先做的是：","opts":[{"k":"A","t":"檢查他的呼吸道是否暢通。"},{"k":"B","t":"檢視胸管是否堵塞。"},{"k":"C","t":"測量其血壓是否正常。"},{"k":"D","t":"檢測他兩側瞳孔是否等大。"},{"k":"E","t":"照胸部及小腿 X 光。"}],"answer":"A","expl":"病人在處置中突然躁動、呼吸困難與休克，ABC 優先，應先檢查呼吸道是否暢通（牙科檢查中可能有氣道阻塞），所以 (A)；之後再檢查胸管、血壓等。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-18","year":104,"qnum":18,"topic":"腹部","subtopic":"肝臟","stem":"40 歲男性，於車禍後送至急診，到院時呈現深度休克，腹部超音波(FAST)顯示腹腔內有廣泛性液體積聚，心包無積液，於插管與給予靜脈輸液後緊急送入開刀房。開腹後發現腹內積血約3000CC，左肝嚴重裂傷並有暗色血液持續自肝臟與橫隔間流出，此時病患血壓持續在 80-90/60-70mmHg 間，血氣分析(Blood gas analysis)呈現酸中毒，體溫約 32℃。施以 Pringle Maneuver 作肝門血流阻斷後出血減緩但未停止，請問，此時應採取的手術策略為：","opts":[{"k":"A","t":"迅速以手指或止血鉗將破裂的左肝葉作「非解剖性肝切除」(Non-anatomical Hepatectomy)。"},{"k":"B","t":"請麻醉醫師設法穩住病患狀況，進行標準左肝葉切除手術。"},{"k":"C","t":"以紗塊做肝臟周圍填塞(Perihepatic packing)並盡快結束手術。"},{"k":"D","t":"呼叫院內專精肝臟手術醫師與心胸外科醫師，準備進行開胸與下腔靜脈損傷修補。"},{"k":"E","t":"初步移除肝臟破裂部分，並修補與結紮肝內的出血點。"}],"answer":"C","expl":"肝臟嚴重裂傷、Pringle 後仍出血，加上低體溫（32°C）、酸中毒與持續低血壓，是 damage control 的典型適應症：perihepatic packing 並盡快結束手術，所以 (C)。(A)(B)(E) 的切除或修補耗時，且加重 lethal triad；(D) 為 retrohepatic IVC 傷的備案。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-19","year":104,"qnum":19,"topic":"胸部","subtopic":"總論／其他","stem":"下列何者非 Resuscitative Thoracotomy 之 Indication？","opts":[{"k":"A","t":"Pelvic crushing injury with SBP=70 mmHg。"},{"k":"B","t":"Blunt abdominal trauma with 10 min pre-Hospital CPR。"},{"k":"C","t":"Penetrating torso trauma with 15 min pre-Hospital CPR。"},{"k":"D","t":"Penetrating to neck with sudden collapse at ER。"},{"k":"E","t":"Profound refractory shock (SBP < 60 mmHg) 。"}],"answer":"A","expl":"Resuscitative thoracotomy 適應症：穿刺性胸腹傷到院前 CPR ≤15 分鐘、鈍傷 CPR ≤10 分鐘（有 signs of life）、頸部穿刺傷在急診突然失去生命徵象、profound refractory shock；骨盆擠壓傷合併低血壓是骨盆出血，應 binder/PPP/embolization，不是開胸適應症，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-20","year":104,"qnum":20,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列有關 ICU 重症病患營養治療之敘述，何者為非？","opts":[{"k":"A","t":"較高蛋白的攝取一般更能達到氮平衡或正氮平衡(nitrogen balance)，故Traumatic brain injury (TBI)的病患相比於”非 TBI”的病患，前者對蛋白質的損耗(protein catabolism)更高，也更需要增加蛋白攝取。"},{"k":"B","t":"休克的重症病患仍使用升壓劑或強心劑時，若已接受充分復甦，且升壓劑或強心劑之劑量已持續減少，可嘗試給予腸道灌食。"},{"k":"C","t":"血液動力學不穩定的 ICU 病人，若能接受早期腸道灌食，其 ICU 死亡率及住院死亡率都較低。"},{"k":"D","t":"對於會因腸道營養而加重肝昏迷的病人，可使用支鏈胺基酸(branched chain amino acid)強化配方。"},{"k":"E","t":"對於”damage-control”腹部手術或治療 abdominal compartment syndrome 而不關閉腹部的病患，腸道營養可增加筋膜關閉成功率。"}],"answer":"A","expl":"營養治療：休克病人經充分復甦且升壓劑逐漸減少時可嘗試 enteral feeding；早期腸道營養可降低死亡率，也利於 open abdomen 病人的 fascial closure。官方答案 (A) 為非，是因蛋白質攝取不是「越高越好」，也不是 TBI 就一定需大幅增加蛋白質（ASPEN 建議約 1.2–2.0 g/kg/day 的範圍）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-21","year":104,"qnum":21,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"小兒遠端肱骨髁上骨折，最常合併的神經傷害為：","opts":[{"k":"A","t":"尺神經。"},{"k":"B","t":"橈神經。"},{"k":"C","t":"肌皮神經。"},{"k":"D","t":"正中神經。"},{"k":"E","t":"臂神經叢。"}],"answer":"D","expl":"同 95-27：小兒 supracondylar fracture 最常傷到 anterior interosseous nerve（median nerve 的分支），所以選 median nerve (D)；需注意 brachial artery injury 與 Volkmann contracture。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-22","year":104,"qnum":22,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"腔室壓力昇高症候群(compartment syndrome)得敘述，下列合者為非：","opts":[{"k":"A","t":"可以發生在身體任何部位的肌肉群，但是以脛骨骨折和前臂骨折最易引起。"},{"k":"B","t":"可能因為血流再灌注長時間缺血的肌肉，造成微血管通透性增加而產生。"},{"k":"C","t":"無力或痲木的患肢常常是腔室壓力昇高症候群的晚期徵兆。"},{"k":"D","t":"患肢遠端的脈搏的強弱及微血管再充填的時間，是診斷腔室壓力昇高症候群的可靠徵象。"},{"k":"E","t":"肢體穿刺傷也可能造成腔室徵候群。"}],"answer":"D","expl":"肢體末梢脈搏與 capillary refill 在 compartment syndrome 早期通常仍正常，等到脈搏消失時往往已是晚期，所以 (D)「可靠徵象」為錯。早期徵象是 pain out of proportion 與被動牽拉痛，需要臨床警覺與必要時測壓。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-23","year":104,"qnum":23,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"下列關於外傷初級評估及治療的概念何者最恰當？","opts":[{"k":"A","t":"初級評估最為重要，一旦評估處置後病人生命現象穩定，即可確保病人安全無虞。"},{"k":"B","t":"初級評估要優先評估並處理威脅病人生命的狀況。"},{"k":"C","t":"仰賴詳細的病史詢問，實驗室檢查，及影像學檢查。"},{"k":"D","t":"重點在於迅速，盡速做完不論病人狀況如何，盡速前進到二級評估。"},{"k":"E","t":"初級評估時應信任醫師理學檢查能力，影像學檢查完全不重要。"}],"answer":"B","expl":"Primary survey 的重點是辨識與處置立即威脅生命的狀況（xABCDE），而不是詳細病史與影像；完成後仍要持續 re-evaluation，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-24","year":104,"qnum":24,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"實施外傷登錄的主要目的不包括？","opts":[{"k":"A","t":"績效改進。"},{"k":"B","t":"建立流行病學資料。"},{"k":"C","t":"研究外傷病患預後。"},{"k":"D","t":"改進外傷治療水準。"},{"k":"E","t":"增加部門營利。"}],"answer":"E","expl":"外傷登錄的目的在於品質改進、流行病學、預後研究與提升照護，而非增加部門營利，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-25","year":104,"qnum":25,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列關於孕婦生理變化及外傷處理的敘述何者最恰當？","opts":[{"k":"A","t":"孕婦的血量較一般狀況為低，稱作生理性貧血。"},{"k":"B","t":"孕婦的凝血因子相對不足，容易出血。"},{"k":"C","t":"孕婦受傷急救時，為減少主動脈壓迫，要考慮右側臥。"},{"k":"D","t":"即使是懷孕期，不尋常的傷情仍應考慮家暴的可能性。"},{"k":"E","t":"急救孕婦時發生胎兒流產的最多原因是子宮破裂。"}],"answer":"D","expl":"同 96-23：不尋常的受傷要考慮 intimate partner violence，所以 (D)。其他：孕婦血量增加，有 physiologic anemia；凝血因子升高；宜採左側臥以減少 IVC（非主動脈）壓迫；胎兒流失最常見原因為胎盤早剝。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-26","year":104,"qnum":26,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"外傷嚴重度是依據 ISS 來評分，而在 ISS 的評估上將身體區分成六個部位來計算各部位的受傷嚴重度。下列何項不是 ISS 所區分的部位：","opts":[{"k":"A","t":"頭頸部。"},{"k":"B","t":"胸部。"},{"k":"C","t":"腹部。"},{"k":"D","t":"腰部。"},{"k":"E","t":"四肢。"}],"answer":"D","expl":"ISS 的六個身體區域：head/neck、face、chest、abdomen/pelvic contents、extremities/pelvic girdle、external，沒有「腰部」，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-27","year":104,"qnum":27,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"依照啟動外傷小組(Trauma blue)的標準，請問下列哪一位病人到達急診室時，是不需要啟動 Trauma blue 的：","opts":[{"k":"A","t":"35 歲男性從 3 樓窗戶跳下。"},{"k":"B","t":"19 歲女性因車禍到院，BP:85/45mmHg。"},{"k":"C","t":"25 歲男性工作時，右手被機器輾傷開放性骨折。"},{"k":"D","t":"75 歲女性家中浴室滑倒，到院時 GCS E2V2M2。"},{"k":"E","t":"以上都需要啟動。"}],"answer":"C","expl":"外傷小組啟動（Trauma blue）標準包含高處墜落、低血壓、GCS 下降（如 E2V2M2）；單純肢體開放性骨折或手部機器輾傷、生命徵象穩定，通常不需全隊啟動，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-28","year":104,"qnum":28,"topic":"燒傷環境","subtopic":"低體溫與凍傷","stem":"對於肢體之凍傷(Frostbite)，下列那一步驟優先使用：","opts":[{"k":"A","t":"給予血管擴張劑。"},{"k":"B","t":"給予抗凝血劑治療。"},{"k":"C","t":"給予40 度 C 溫水治療。"},{"k":"D","t":"包紮並抬高患肢。"},{"k":"E","t":"局部立刻塗抹 silvasulphadiazine 藥膏。"}],"answer":"C","expl":"凍傷的優先處理是 rapid rewarming（快速復溫），用溫水浸泡約 37–42°C（各指引略異，WMS 2019 建議 37–39°C），直到肢體變軟、變紅，所以 (C)。不應直接摩擦或乾熱；復溫後包紮並抬高；血管擴張劑與抗凝血劑僅用於選擇性病例（如 iloprost／thrombolysis）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-29","year":104,"qnum":29,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"Blunt bowel perforation 在腹部挫傷病患中，診斷相當重要；下列相關之敘述，何者有誤?","opts":[{"k":"A","t":"發生的 mechanism 通常是外力 compression，因外壓形成 closed loop，再因 high intraluminal pressure，而 blowout。"},{"k":"B","t":"在 alcohol drinking, spinal cord injury 或 head injury with conscious disturbance 的腹部挫傷病患，常會 missed diagnosis。"},{"k":"C","t":"Abdominal CT 呈現 bowel wall thickness, mesenteric hematoma 或 streaky sign 應可確定診斷。"},{"k":"D","t":"Diagnostic peritoneal lavage (DPL)，可作輔助性診斷，可發現 positive Gram stain,elevation of amylase 或 alkaline phosphatase (ALP)。"},{"k":"E","t":"Laparotomy 是 treatment of choice，開刀延遲的時間長短與其合併症或死亡率有關。"}],"answer":"C","expl":"同 99-2：CT 的 bowel wall thickening、mesenteric hematoma 與 streaky sign 只是間接徵象，不能「確定診斷」，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-30","year":104,"qnum":30,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤?","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"同 99-14：熱量以醣類與脂肪混合提供，70% 脂肪並非建議，所以 (B) 錯；血糖不宜過度嚴格控制（避免 ≤110 mg/dL）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-31","year":104,"qnum":31,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"同 99-17：創傷後免疫反應先是 hyperinflammatory（SIRS），之後才是 hypoinflammatory（CARS），所以 (A) 的順序顛倒。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-32","year":104,"qnum":32,"topic":"腹部","subtopic":"脾臟","stem":"對於 blunt splenic injury，使用 multidetector CT 檢查，下列敘述何者有誤?","opts":[{"k":"A","t":"對於偵測有無 intra splenic pseudoaneurysm 存在，artery phase image 比 portal phase image 更 sensitive 且 accurate。"},{"k":"B","t":"對於偵測有無 splenic parenchymal injury, artery phase image 比 portal phase image 較不 sensitive 及不 accurate。"},{"k":"C","t":"對於偵測有無 active bleeding, artery phase image 比 portal phase image 更sensitive 且 accurate。"},{"k":"D","t":"對整體 blunt splenic injury 評估，dual-phase review 比 single-phase review 來得好。"},{"k":"E","t":"Artery phase image 對於 intra-splenic pseudoaneurysm 的偵測敏感度可達 70%。"}],"answer":"C","expl":"同 102-49：對 blunt splenic injury 的 MDCT，arterial phase 對 pseudoaneurysm 與 active bleeding 較敏感，portal venous phase 對 parenchymal injury 較好，dual-phase 優於 single-phase。官方答案 (C) 認為其中有誤，但文獻上兩階段需互補，所以此題僅供參考。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-33","year":104,"qnum":33,"topic":"四肢血管骨科","subtopic":"股骨／開放性骨折","stem":"下列有關大腿骨骨折之敘述，何者為非?","opts":[{"k":"A","t":"大腿骨骨折的標準治療為骨髓內釘固定。"},{"k":"B","t":"封閉性大腿骨骨折施行骨髓內釘固定手術，應待生命徵象穩定麻醉危險性較低時方才施行為佳。"},{"k":"C","t":"開放性大腿骨骨折有高感染風險，不建議以骨髓內釘固定。"},{"k":"D","t":"若無其他可能影響生命的外傷，大腿骨骨折骨髓內釘固定手術應該早期施行。"},{"k":"E","t":"老年人的大腿骨骨折常源自跌倒。"}],"answer":"C","expl":"股骨幹骨折標準治療為 intramedullary nailing；穩定病人宜早期固定（24 小時內），不穩定病人先 damage control orthopedics（外固定）；開放性骨折清創後也可用 IM nail（尤其 Gustilo I–IIIA），所以 (C)「不建議」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-34","year":104,"qnum":34,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"26 歲男性，酒後騎機車自摔，時間不明。送至急診時意識清楚，E4V5M6，心跳155/分，血壓 72/44 mmHg，呼吸急促 32/分。急診立即呼叫外傷小組，同時以 NS大量輸液。經 15 分鐘後外傷小組到達現場，已輸注 NS 2000cc。心跳 120/分，血壓 92/56 mmHg，呼吸 22/分。請問下列措施何者較為不當?","opts":[{"k":"A","t":"尚不需要插管維持呼吸。"},{"k":"B","t":"啟動大量輸血指引(Massive transfusion protocol) 。"},{"k":"C","t":"緊急叫血輸血 pRBC 4U 與 FFP 4U。"},{"k":"D","t":"心跳血壓仍不穩定，在可輸注 pRBC 之前須繼續大量輸液。"},{"k":"E","t":"安排緊急胸部 X 光檢查，以排除氣血胸。"}],"answer":"D","expl":"血壓 72/44、HR 155、已輸 NS 2000 cc 仍不穩，應啟動 MTP 並盡快輸 pRBC 與 plasma，而不是「繼續大量輸液」，所以 (D) 最不當。補充：ATLS 10/11 建議初始晶體液上限約 1 L，盡早 blood products。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-35","year":104,"qnum":35,"topic":"腹部","subtopic":"肝臟","stem":"經輸血與一系列檢查後，發現病人有下列外傷: 右側 SDH 併腦水腫，右鎖骨骨折，右側7~9 肋骨骨折併少量血胸，肝臟裂傷併大量腹腔內積血，右膝粉碎性骨折併右小腿血循不良。整個過程中血壓曾短暫回復至 102/76mmHg，但10 分鐘後又再降至 82/50 mmHg，意識狀態也變為 E1V2M4。請問此時除立即以氣管內管插管外，何種處置需最優先進行?","opts":[{"k":"A","t":"進行開顱手術清除血塊並放置顱內壓監測。"},{"k":"B","t":"放置右側胸管引流血胸。"},{"k":"C","t":"進行剖腹手術以控制腹腔內出血。"},{"k":"D","t":"安排右下肢血管攝影以確認血循受阻的位置。"},{"k":"E","t":"繼續輸血，待血壓穩定後重覆腦部電腦斷層攝影。"}],"answer":"C","expl":"多重傷害中血壓持續下降且有肝臟裂傷併大量腹腔內積血，是血流動力學不穩定的主因，需要優先 laparotomy 控制腹內出血（同時 airway），腦部與四肢傷害可稍後處理，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-36","year":104,"qnum":36,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"五歲男童過馬路時，遭到時速 50 公里的轎車撞擊，彈離車子 3 公尺遠；送至急診室時，抱怨腹部疼痛，身體理學檢查發現血壓 68/40 mmHg、心跳每分鐘 200 次、腹部緊繃合併觸痛(firm, tender)，病人體重約20 公斤，其收縮壓持續低於90 mmHg，下列何項為最適當的輸液復甦方式？","opts":[{"k":"A","t":"先輸注200 cc 溫的等張晶體溶液，血壓持續偏低就須輸 400 cc 的紅血球濃厚液(packed RBC)。"},{"k":"B","t":"先輸注400 cc 溫的等張晶體溶液，血壓持續偏低就須輸 200 cc 的紅血球濃厚液。"},{"k":"C","t":"先輸注200 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸200 cc 的紅血球濃厚液。"},{"k":"D","t":"先輸注200 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸400 cc 的紅血球濃厚液。"},{"k":"E","t":"先輸注400 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸200 cc 的紅血球濃厚液。"}],"answer":"E","expl":"20 kg 兒童出血性休克，20 mL/kg 為 400 mL；若仍低血壓，輸 10 mL/kg pRBC（200 mL）。官方答案 (E) 允許先 400 mL 晶體液並重複 1–2 次後再輸血。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議起始 20 mL/kg 晶體液最多一次，仍不穩定就盡快 10 mL/kg pRBC，不再多次重複晶體液。官方答案 (E) 不變，但臨床請依 ATLS 10/11。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"104-37","year":104,"qnum":37,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"28 歲懷孕32 週女性，配戴安全帶駕駛自小客車，被時速 30 公里的公車從後追撞，安全氣囊爆開，車身沒有明顯損害，病人神智清醒，在車禍現場四肢可以自由活動，只有抱怨頸部疼痛；接著病人戴上頸圈，躺在長背板上，由救護車送至急診室，身體理學檢查發現第五、六頸椎壓痛，下列敘述何者正確？","opts":[{"k":"A","t":"病人不宜接受頸部 X-Ray 檢查，以防放射線可能造成胎兒畸形。"},{"k":"B","t":"病人接受基本外傷評估、確認胎兒心音及活動正常後，就可以安全離院。"},{"k":"C","t":"產婦配戴安全帶駕駛發生車禍，發生早產的機會比未配戴安全帶者高。"},{"k":"D","t":"病人接受外傷評估後，仍須接受胎兒心音監視 6 小時以上，才可以離院。"},{"k":"E","t":"病人不應繼續躺在長背板上，應該改躺在一般的病床以改善胎兒循環。"}],"answer":"D","expl":"同 99-42：孕 ≥20 週受外傷後，需胎心音（CTG）監測；官方答案 (D)（6 小時以上）。補充：ATLS 10 建議至少 4 小時，出現宮縮、陰道出血或母體不穩定需延長。(A) 必要影像不應拒絕；(C) 配戴安全帶可降低不良結果；(E) 頸椎壓痛需繼續固定。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-38","year":104,"qnum":38,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"若腹部鈍傷患者到院兩小時的腹部電腦斷層顯示無異常，但到院後十小時後出現發燒，白血球增高，上腹部壓痛加劇現象，以下處置何者是不適宜的?","opts":[{"k":"A","t":"可再重複一次腹部超音波檢查，若無異常，則應該密切觀察即可。"},{"k":"B","t":"即使腹部超音波正常，重複再做腹部電腦斷層仍有其正當性。"},{"k":"C","t":"若發現胰臟尾部截斷性損傷，則遠端胰臟切除術應是適當的處置。"},{"k":"D","t":"若懷疑有胰臟損傷，但胰管損傷無法由 CT 確定，可考慮做 MRCP 或 ERCP，再決定如何處置。"},{"k":"E","t":"除了影像檢查之外，腹腔鏡手術也是確定診斷的選項之一。"}],"answer":"A","expl":"CT 在受傷後 2 小時正常，但之後出現發燒、白血球升高與上腹壓痛加劇，要想到延遲出現的 pancreatic、duodenal 或 bowel injury，不能僅因超音波正常就繼續觀察，所以 (A) 不適宜。(B)(D)(E) 為合理的追加檢查；(C) 尾部截斷性胰管損傷需遠端胰臟切除。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-39","year":104,"qnum":39,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"五十歲男性登山時不慎失足跌落山谷，受困二十四小時才被救出，山區第一線醫院檢查發現左側連枷胸、肺挫傷及左大腿骨折，經轉送到院時，血壓80/50，心跳130，呼吸 25，SpO2 95% (non-rebreathing mask)，E4V5M6，不記得發生何事，以下敘述何者較不恰當？","opts":[{"k":"A","t":"積極灌注輸液，檢查出血可能來源，避免低體溫，是急救重點。"},{"k":"B","t":"若呈現茶色尿，尿量少，血中 CPK 值超過正常值十倍，須排除橫紋肌溶解症。"},{"k":"C","t":"超音波除了檢查腹內出血之外，也可能幫忙診斷氣胸及血胸。"},{"k":"D","t":"若胸部 X 光呈現縱膈腔變寬現象，應立即做血管攝影檢查以排除胸部大血管損傷。"},{"k":"E","t":"因有肺挫傷, 輸液水分的給予要適中，否則極易造成肺水腫，進一步造成呼吸衰竭。"}],"answer":"D","expl":"(D) 縱隔增寬應先做 CTA 排除 blunt aortic injury，而不是立即進行導管血管攝影，且病人本身仍需要先穩定（低血壓）；所以官方判為較不恰當。(A)(B)(C)(E) 為合理：積極找出血源與保暖、橫紋肌溶解（CPK >10 倍正常）、超音波可診斷氣血胸、肺挫傷輸液要適中。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-40","year":104,"qnum":40,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"一位38 歲中年男性和人發生爭吵後，不幸脖子遭刀刺傷，傷口約 3 公分長於右側Sternocleidomastoid muscle 之前，為 Zone II injuries，且呈現 Pulsatile hematomas，此時以下處置何者最正確?","opts":[{"k":"A","t":"此病患需進入加護病房以防止血腫變大導致呼吸道阻塞。"},{"k":"B","t":"做 Bronchoscopy，若沒有異常，便直接留觀即可。"},{"k":"C","t":"做 Esophagoscopy，若沒有異常，便直接留觀即可。"},{"k":"D","t":"照 Chest X-ray，若沒有異常，便直接留觀即可。"},{"k":"E","t":"需開刀探查脖子(Exploration)。"}],"answer":"E","expl":"頸部 Zone II 穿刺傷合併 pulsatile／expanding hematoma 是 hard sign，需要立即手術探查，所以 (E)。其他選項都延誤處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-41","year":104,"qnum":41,"topic":"腹部","subtopic":"脾臟","stem":"有關“Splenic artery embolization”用於脾創傷治療之敘述，請選出錯誤者？","opts":[{"k":"A","t":"“Splenic artery embolization”可適用於老年人。"},{"k":"B","t":"“CT scan”發現“contrast extravasation”為採用“Splenic artery embolization”重要考慮因素。"},{"k":"C","t":"“Splenic artery embolization”無法保留脾臟免疫功能。"},{"k":"D","t":"“Selective splenic artery embolization”後引起之“Splenic infarct”不會增加病人死亡率。"},{"k":"E","t":"“Splenic artery embolization”仍可用於“high grade”脾創傷。"}],"answer":"C","expl":"同 99-25：脾動脈栓塞（SAE）可保留脾臟免疫功能，所以 (C)「無法保留」為錯；(A)(B)(D)(E) 為標準觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-42","year":104,"qnum":42,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕第三期的 27 歲孕婦因車禍被送到急診室就醫，她是坐在車子後座的乘客，當時 有綁安全帶。到院時血壓是 120/70 mmHg、心跳是 107 次/分鐘、氣管暢通、兩側呼吸音正常、四肢溫暖、肢端脈搏也正常。自訴當時有撞及頭部及腹部但超音波檢查並無異常發現，胎兒的心跳和胎動情形也正常。下列敘述何者正確？","opts":[{"k":"A","t":"立即進行剖腹生產。"},{"k":"B","t":"安排不注射顯影劑之電腦斷層掃描檢查。"},{"k":"C","t":"若抽血檢驗值正常，可直接讓病人離院回家。"},{"k":"D","t":"須繼續監測病患和胎兒至少 4 小時。"},{"k":"E","t":"懷孕第三期之婦女, 外傷後流產之機會並不比第一期高。"}],"answer":"D","expl":"孕婦（第三孕期）外傷後，即使初步檢查正常，仍需持續監測母親與胎兒至少 4 小時（ATLS 10），所以 (D)。(A) 不需要剖腹產；(B) 需要的影像不必拒絕，但此題無需 CT；(C) 不可僅憑抽血正常就回家；(E) 懷孕後期外傷造成胎盤早剝風險高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-43","year":104,"qnum":43,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"70 公斤健康的男性，不幸發生車禍導致多重外傷，送至急診室時初估病人失血量約1.2 liters，病人在此階段時，下列敘述何者錯誤?","opts":[{"k":"A","t":"此病人應為 Class II hemorrhage。"},{"k":"B","t":"Tachypnea (20-30 次/minutes)。"},{"k":"C","t":"Increased pulse pressure。"},{"k":"D","t":"Tachycardia (100-120 次/minutes)。"},{"k":"E","t":"Normal systolic blood pressure。"}],"answer":"C","expl":"失血 1.2 L（約 24% 的 5 L 血量）屬於 Class II（15–30%）：心搏約 100–120、呼吸 20–30、收縮壓正常、脈搏壓變窄（舒張壓上升）。所以 (C)「脈搏壓增加」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-44","year":104,"qnum":44,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"承上題，此病人經檢查後,診斷如下：左臉骨 LeFort II fracture (Abbreviated Injury Scale:2)，左側第三及第四肋骨骨折無血氣胸 (AIS:2)，liver laceration grade IV (AIS:4)，spleen laceration grade III (AIS:3)，left femur close fracture (AIS:3)，請問此病人 Injury Severity Score (ISS) 及 New Injury Severity Score (NISS)分別為：","opts":[{"k":"A","t":"29 & 34。"},{"k":"B","t":"29 & 42。"},{"k":"C","t":"29 & 29。"},{"k":"D","t":"14 & 17。"},{"k":"E","t":"9 & 17。"}],"answer":"A","expl":"ISS 取三個不同區域最高 AIS 平方和：abdomen（liver IV）4、extremity（femur）3、face 2（或 chest 2），所以 4² + 3² + 2² = 29；NISS 取全身最嚴重的三個傷（不分區域）：liver 4、spleen 3、femur 3，所以 4² + 3² + 3² = 34。答案 (A) 29 & 34。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-45","year":104,"qnum":45,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，然而升壓藥的使用為其絕對禁忌症。"},{"k":"D","t":"燒傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"早期 enteral feeding 可調節發炎與增強免疫；升壓藥並非絕對禁忌，若已充分復甦且劑量穩定或逐漸減少，可嘗試腸道灌食，所以 (C)「絕對禁忌」為錯。(D) 燙傷可在 4–6 小時內開始；(E) 胃輕癱可改 post-pyloric feeding。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-46","year":104,"qnum":46,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤：","opts":[{"k":"A","t":"熱量及蛋白質之給予應參考創傷的嚴重度計算，越嚴重者需求越高。"},{"k":"B","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"C","t":"頭部創傷患者的蛋白質需求量高於腹部創傷者。"},{"k":"D","t":"頭部外傷患者，為避免二氧化碳產生過多加重了顱內高壓的問題，在熱量的供給部分(碳水化合物與脂肪)，建議可提高碳水化合物的比例。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(110 mg/Dl)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"D","expl":"TBI 病人要避免 CO2 產生過多，因此熱量配方應降低碳水化合物比例（避免過多 CO2）、提高脂肪比例，所以 (D)「提高碳水化合物」為錯。其他：熱量與蛋白質依嚴重度計算；蛋白質需求 1.0–1.5 g/kg/day；血糖不宜過度嚴格控制。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-47","year":104,"qnum":47,"topic":"ICU營養併發症","subtopic":"疼痛控制","stem":"疼痛的控制是外傷照護的重要一環，下列相關敘述何者錯誤：","opts":[{"k":"A","t":"疼痛的控制有助於緩解外傷引起的壓力反應，同時也是一品質照護的重要指標"},{"k":"B","t":"一些非藥物的處置(non-pharmacologic intervention)，如骨折固定、傷口包紮、適當的患者擺位等，亦有助於疼痛的緩解。"},{"k":"C","t":"在胸腔外傷患者，可考慮施行硬脊膜外或肋膜腔內注射藥物等止痛方式，可減少全身性嗎啡用藥所帶來的副作用。"},{"k":"D","t":"嗎啡類藥物為嚴重疼痛的標準用藥，在腎功能不佳的情況下，首選者為morphine。"},{"k":"E","t":"嗎啡類藥物為嚴重疼痛的標準用藥，在血壓不穩的情況下，首選者為 fentanyl。"}],"answer":"D","expl":"同 99-48：腎功能不佳時，morphine 的活性代謝物（M6G）會蓄積，不宜作為首選，所以 (D) 錯；可改用 fentanyl 或 hydromorphone。(E) 血壓不穩時 fentanyl 較好。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"104-48","year":104,"qnum":48,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"您是一位外科醫師在鄉下醫院值班， 119 弟兄緊急送入一位 75 歲男性機車騎士遭卡車撞擊，抵達現場時仍有脈搏，送醫途中失去脈搏，on 喉頭氣罩 LMA 開始CPR，到院時已 CPR 十分鐘，下列何者處置不宜？","opts":[{"k":"A","t":"繼續 CPR。"},{"k":"B","t":"緊急開胸 CPR。"},{"k":"C","t":"將喉頭氣罩換為氣管內管。"},{"k":"D","t":"打上點滴給予大量輸液。"},{"k":"E","t":"與家屬連繫解釋病情，給予心理支持。"}],"answer":"B","expl":"75 歲鈍傷病人在到院前失去脈搏，CPR 已 10 分鐘，鈍傷 ED thoracotomy 預後極差，不宜緊急開胸，所以 (B)。(A)(C)(E) 為合理處置。","outdated":true,"suspect":false,"flagNote":"選項 (D)「打點滴給予大量輸液」被官方視為合理，但現行 ATLS 10/11 與 DCR 已不再主張大量晶體液，應是限量晶體液與盡早輸血。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"104-49","year":104,"qnum":49,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"您是在一位重度外傷醫院值班的醫師，119 弟兄緊急送入一位25 歲男性機車騎士遭卡車撞擊胸部劇烈疼痛，抵達醫院時衣飾微弱血壓偏低仍有脈搏，在急救室五分鐘時突然失去意識與脈搏，下列何者處置不宜?","opts":[{"k":"A","t":"緊急開胸繼續 CPR。"},{"k":"B","t":"與家屬連繫解釋病情，給予心理支持。"},{"k":"C","t":"打上點滴給予大量輸液。"},{"k":"D","t":"聯絡基地醫院，盡速安排轉院。"},{"k":"E","t":"聯絡手術室，轉送開刀房。"}],"answer":"D","expl":"25 歲鈍傷病人抵達時仍有脈搏，之後在急救室失去脈搏，屬於 witnessed arrest with signs of life，可緊急開胸（或送開刀房）並輸血；轉院會延誤，所以不宜的是 (D)。(A)(B)(C)(E) 為合理。","outdated":true,"suspect":false,"flagNote":"選項 (C)「打點滴給予大量輸液」在今日應改為 limited crystalloid 與早期輸血（MTP）。官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"104-50","year":104,"qnum":50,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"有一位四十多歲的女性患者從火災現場被送來醫院，到院時間為下午一點，在急診室裡病患意識清醒，但直喊口渴，經理學檢查發現患者整個軀幹前方和右下肢均為二至三度燒傷，患者體重為五十公斤，心、肺、腎功能均正常…。請問該患者燒傷面積占體表面積百分之多少？","opts":[{"k":"A","t":"18。"},{"k":"B","t":"27。"},{"k":"C","t":"36。"},{"k":"D","t":"22.5。"},{"k":"E","t":"45。"}],"answer":"C","expl":"九分法（rule of nine）：軀幹前方 18%、一側下肢 18%，所以 18 + 18 = 36%，答案 (C)。二至三度燒傷才計入。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-1","year":105,"qnum":1,"topic":"ICU營養併發症","subtopic":"疼痛控制","stem":"疼痛的控制是外傷照護的重要一環，下列相關敘述何者錯誤：","opts":[{"k":"A","t":"疼痛的控制有助於緩解外傷引起的壓力反應，同時也是品質照護的重要指標。"},{"k":"B","t":"一些非藥物的處置(non-pharmacologic intervention)，如骨折固定、傷口包紮、適當的患者擺位等，亦有助於疼痛的緩解。"},{"k":"C","t":"在胸腔外傷患者，可考慮施行硬脊膜外或肋膜腔內注射藥物等止痛方式，可減少全身性嗎啡用藥所帶來的副作用。"},{"k":"D","t":"嗎 啡 類 藥 物為 嚴重 疼 痛 的標 準 用 藥。 在 腎 功能 不 佳 的情 況 下 ，首 選 者為morphine。"},{"k":"E","t":"嗎啡類藥物為嚴重疼痛的標準用藥。在血壓不穩的情況下，首選者為 fentanyl。"}],"answer":"D","expl":"同 99-48：腎功能不佳時，morphine 不是首選（代謝物蓄積），所以 (D) 錯；血壓不穩時 fentanyl 對血流動力學影響較小。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-2","year":105,"qnum":2,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"一嚴重頭部外傷併肋骨骨折患者，在給予了足夠疼痛控制後仍有躁動，導致顱內壓上升，於是決定進一步給予鎮定劑使用。患者有腎功能不全病史。在考慮患者特殊的臨床狀況與照護需求下，下列何者為最適當的選擇：","opts":[{"k":"A","t":"Ketamine。"},{"k":"B","t":"Lorazepam (商品名：Ativan)。"},{"k":"C","t":"Midazolam (商品名：Dormicum)。"},{"k":"D","t":"Haloperidol。"},{"k":"E","t":"Propofol。"}],"answer":"E","expl":"嚴重 TBI 躁動、腎功能不全：propofol 短效、可降低 CMRO2 與 ICP、不依賴腎臟代謝，並利於定期評估神經學狀態，所以 (E)。midazolam 與 lorazepam 在腎衰竭會蓄積；haloperidol 無鎮靜鎮痛效果且 QT 風險；ketamine 在較新資料中對 TBI 的 ICP 疑慮減少，但仍非此題首選。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-3","year":105,"qnum":3,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷會引起身體重大的新陳代謝與內分泌變化，臨床表現不包括下列何項敘述：","opts":[{"k":"A","t":"新陳代謝與內分泌的變化與疾病嚴重度成正相關。"},{"k":"B","t":"基礎新陳代謝率大大提升，與疾病嚴重度成正相關。"},{"k":"C","t":"大量脂肪燃燒，以作為主要的燃料來源。"},{"k":"D","t":"醣質新生加上胰島素抗性所導致的高血糖。"},{"k":"E","t":"蛋白質分解大於合成，呈現負氮平衡。"}],"answer":"C","expl":"同 99-10：創傷後代謝反應以 hypermetabolism、insulin resistance、protein catabolism 為主；官方答案 (C) 認為「脂肪為主要燃料」不是創傷後表現。","outdated":false,"suspect":true,"flagNote":"創傷後 lipolysis 與 fat oxidation 其實也會增加，所以 (C) 的敘述有爭議；考試以官方 (C) 為準，臨床記得 mixed-fuel。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"105-4","year":105,"qnum":4,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，暫不需考量系統性的穩定度(systemic stabilization)。"},{"k":"D","t":"燙傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"同 101-46：早期 enteral feeding 好處多，但仍要在 systemic stabilization（血流動力學穩定）後開始，不能「不需考量穩定度」，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-5","year":105,"qnum":5,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"關於 limb compartment syndrome，下列敘述何者錯誤?","opts":[{"k":"A","t":"Compartment syndrome is limb-threatening."},{"k":"B","t":"Common areas where compartment syndrome occurs are the lower leg, forearm,foot, hand, gluteal region, and the thigh."},{"k":"C","t":"The compartment syndrome may occur in any site in which muscle is contained within in a closed fascial space, and the skin never act as a restricting barrier."},{"k":"D","t":"The end-stage of this neuromuscular injury is called Volkmann’s ischemic contracture."},{"k":"E","t":"The absence of a palpable distal pulse usually is an uncommon or late finding in compartment syndrome."}],"answer":"C","expl":"Compartment syndrome 發生在被筋膜（或緊縮的皮膚、敷料、石膏）包覆的肌肉空間，皮膚也可能是 restricting barrier（例如環狀燒傷、緊包石膏），所以 (C)「皮膚從不扮演限制」為錯。(E) 遠端脈搏消失是晚期表現；(D) 晚期為 Volkmann ischemic contracture。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-6","year":105,"qnum":6,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部實質性器官及空腔器官之損傷的描述，下列何者錯誤?\na. 肝臟是腹腔內最大的實質性器官，也是所有腹部鈍挫傷中最常見的實質器官損傷。\nb. 腹部穿刺貫通傷但無內臟脫出或異常滲液者，若已超過 24 小時且一般情況良好者，可先採取嚴密觀察保守治療。\nc. 實質性器官損傷的主要表現是腹腔內或後腹膜腔出血且合併有進行性的腹脹及腹痛。但若病人處於無法矯正的休克狀態(SBP< 90mmHg)，即使沒有腹痛的症狀也應進行剖腹探查術。\nd. 腹腔內出血 3500ml，合併肝臟右葉 4 度損傷，右腎 4 級損傷及升結腸穿孔且大範圍壞死的患者，最佳的手術方式為以最迅速的方式進行右肝葉切除，右腎摘除，右半結腸切除術及小腸橫結腸吻合術。\ne. 因車禍導致腹部鈍挫傷的患者，受傷 1 小時內的腹部 CT 顯示第五級脾臟破裂及大量腹腔內積液，無明顯游離氣體。此時為快速施行脾臟切除術，最建議的手術切口為從左肋緣下進入，以爭取時間完成脾臟切除。","opts":[{"k":"A","t":"b、d、e。"},{"k":"B","t":"a、b、d。"},{"k":"C","t":"a、d、e。"},{"k":"D","t":"c、d。"},{"k":"E","t":"d、e。"}],"answer":"C","expl":"同 103-9：a 錯（鈍傷最常受傷的實質器官是脾臟）；d 錯（大量出血且多器官傷害應採 damage control，不做長時間切除與吻合）；e 錯（Grade V 脾傷應走正中剖腹，不是左肋緣下切口）；b、c 正確。所以 (C) a、d、e。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-7","year":105,"qnum":7,"topic":"休克輸血","subtopic":"輸血併發症（TRALI 等）","stem":"關於輸血相關急性肺損傷(Transfusion- Related Acute Lung Injury, TRALI)之診斷與治療，何者正確？","opts":[{"k":"A","t":"若 BNP (B-natriuretic peptide) >200 pg/ml，一定可以排除 TRALI。"},{"k":"B","t":"TRALI 因為有肺水腫、高血壓，所以對利尿劑反應佳。"},{"k":"C","t":"TRALI 因為是發炎反應，所以對類固醇效果很好。"},{"k":"D","t":"TRALI 發生率於單一捐血者(single donor)的血小板比隨機捐血者(random donor)血小板高。"},{"k":"E","t":"以上皆正確。"}],"answer":"D","expl":"TRALI 的診斷不能單靠 BNP（BNP >200 傾向 TACO，但不能一定排除 TRALI）；利尿劑對 TRALI 通常無效（TACO 才有效）；steroid 無明確療效。官方答案 (D) 認為單一捐血者血小板（apheresis）造成 TRALI 的機率較高，可能與血漿含量較多與來自 HLA/HNA 抗體的多產婦捐血者有關。所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-8","year":105,"qnum":8,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部閉合性損傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序是：","opts":[{"k":"A","t":"肝、脾等實質性器官→胃→十二指腸第一部→空腸→迴腸→大腸及它們的系膜→盆腔器官。"},{"k":"B","t":"肝、脾等實質性器官→十二指腸第一部→胃→迴腸→空腸→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→迴腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→迴腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→迴腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"腹部鈍傷剖腹探查的順序：先控制出血（四象限 packing，肝、脾與橫膈檢查），再依序探查胃、十二指腸、空腸、迴腸、大腸及盆腔器官。官方答案 (C) 包含橫膈肌的檢查，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-9","year":105,"qnum":9,"topic":"腹部","subtopic":"脾臟","stem":"有關於 Blunt abdominal trauma with splenic injury 的非手術療法 NOM (non-operative management)之敘述何者為是？","opts":[{"k":"A","t":"非手術療法 (NOM) non-operative management 的成功機率高達 70~80%，故大多數脾臟受傷病患是不需要切除脾臟的。"},{"k":"B","t":"Hemodynamic stable 的病患不需要入加護病房。"},{"k":"C","t":"於 abdominal CT 上若可見 spleen 之顯影劑溢出 (contrast extravasation) 則NOM 之成功機會小，需立即施行手術。"},{"k":"D","t":"Hemodynamic unstable 的病患需立即施行血管栓塞術 (Angioembolization) 以保住脾臟。"},{"k":"E","t":"Grade III 以上的 splenic laceration，NOM 不易成功，需儘早手術。"}],"answer":"A","expl":"脾損傷 NOM 的成功率約 70–90%，多數病人不必切除脾臟，所以 (A)。(B) 穩定病人也常入 ICU／密切觀察；(C) contrast blush 不是立即手術，可先 angioembolization；(D) 不穩定者應手術而非栓塞；(E) Grade III 以上不等於 NOM 失敗，依血流動力學決定。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-10","year":105,"qnum":10,"topic":"顏面頸部","subtopic":"總論／其他","stem":"以下何種情形，要高度懷疑可能發生 blunt cerebrovascular injury (BCVI)？","opts":[{"k":"A","t":"Arterial hemorrhage from neck/nose/mouth。"},{"k":"B","t":"Cervical bruit in patient < 50 yrs old。"},{"k":"C","t":"Stroke on CT or MRI。"},{"k":"D","t":"Neurologic deficit inconsistent with head CT。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"Blunt cerebrovascular injury（BCVI）高度懷疑情形：頸部／鼻口動脈出血、年輕人 cervical bruit、CT／MRI 見 stroke、神經學缺損與頭部 CT 不符、Horner、LeFort II/III、C-spine fracture 等，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-11","year":105,"qnum":11,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹腔的外傷緊急手術，下列敘述何者為非﹖","opts":[{"k":"A","t":"穿刺傷若懷疑有腹主動脈損傷時，可作 Mattox maneuver 以利探查與阻斷血管。"},{"k":"B","t":"鈍傷時如發現左側近骨盆處的後腹腔有血腫但無明顯擴大或搏動，可不予打開。"},{"k":"C","t":"下腔靜脈的裂傷，若無法在部分阻斷下修補而需要完全阻斷時，不用考慮同時做腎動脈以下的動脈阻斷。"},{"k":"D","t":"若懷疑病人在橫膈膜以上有其他出血處時，較不宜使用 REBOA(Resuscitation Endovascular Balloon Occlusion of Aorta)阻斷主動脈。"},{"k":"E","t":"若不得已需阻斷 celiac trunk 以上的主動脈，在出血部位修補完成後要鬆開血管鉗夾時，應注意 Reperfusion injury 所可能造成之傷害及電解質不平衡造成心臟停止之風險。"}],"answer":"C","expl":"腹內大血管出血的外科技巧：Mattox maneuver（左側內臟內翻）可暴露腹主動脈；IVC 完全阻斷時要同時考慮腎動脈以下的 aorta 阻斷，以減少血液動力學波動，所以 (C) 錯。(B) 鈍傷骨盆旁後腹腔血腫若穩定不擴大可不打開；(D) 橫膈以上出血不適合 REBOA；(E) 鬆開 aortic clamp 時要預防 reperfusion injury 與電解質異常。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-12","year":105,"qnum":12,"topic":"腹部","subtopic":"肝臟","stem":"關於肝臟裂傷的病人，下列敘述何者為非﹖","opts":[{"k":"A","t":"三級(Grade III)肝裂傷的病人若生命徵象穩定，經電腦斷層檢查顯示動脈相有contrast blush、靜脈相有 contrast pooling，則此病人不需要做血管攝影。"},{"k":"B","t":"四級肝裂傷腹部鼓脹的病人經大量輸液治療，收縮血壓仍低於 90mmHg 且已排除其他可能造成大出血的損傷，應優先選擇作緊急剖腹探查手術而非血管攝影。"},{"k":"C","t":"肝裂傷做緊急剖腹探查手術時，可先以大塊紗巾填塞肝臟四周並作肝門靜脈阻斷(Pringle Maneuver)，並尋找有無其他出血來源。"},{"k":"D","t":"如需阻斷肝門靜脈時，每次可阻斷 20 分鐘。"},{"k":"E","t":"若肝靜脈的損傷一路裂到肝臟後方的下腔靜脈，明顯無法靠大塊紗巾壓迫止血且空間有限難以修補時，可考慮作肝上及肝下的下腔靜脈阻斷合併體外循環或Atriocaval shunt。"}],"answer":"A","expl":"Grade III 肝裂傷若血流動力學穩定，CT 見動脈 blush／靜脈 pooling 代表 active bleeding，應做 angioembolization，所以 (A)「不需要」為錯。(B) 不穩定時優先開刀；(C) 填塞加 Pringle；(D) Pringle 可間歇阻斷約 15–20 分鐘；(E) retrohepatic IVC 傷可用 atriocaval shunt 或 total vascular exclusion。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-13","year":105,"qnum":13,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關骨盆腔骨折的敘述何者為誤﹖","opts":[{"k":"A","t":"懷疑骨盆腔骨折時，可嘗試按壓骨盆腔確認是否穩定，但切勿頻繁重複按壓。"},{"k":"B","t":"骨盆腔骨折併出血且腹腔內有積液之病人，應優先考慮剖腹探查手術。"},{"k":"C","t":"骨盆腔骨折無腹腔內積液之病人，可優先考慮血管攝影。"},{"k":"D","t":"側面壓迫(Lateral compression)之骨盆腔骨折較易造成大出血及休克。"},{"k":"E","t":"懷疑骨盆腔出血造成休克之病人，在補充輸液與準備手術或血管攝影的同時，應先行固定壓迫以限縮骨盆腔空間。"}],"answer":"D","expl":"骨盆骨折中，lateral compression 最常見，但大出血與休克最常見於 anteroposterior compression（open book）與 vertical shear，所以 (D) 錯。(A) 反覆按壓會使血塊脫落；(B)(C) 有腹內積液優先剖腹，無則優先血管攝影；(E) 應盡快用 binder 固定。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-14","year":105,"qnum":14,"topic":"休克輸血","subtopic":"總論／其他","stem":"下列何種傷勢較不會造成出血性休克﹖","opts":[{"k":"A","t":"骨盆腔骨折。"},{"k":"B","t":"趾骨閉鎖性骨折。"},{"k":"C","t":"腹部鈍傷立即超音波檢查顯示陰性，但經過 2 小時後肚子疼痛鼓脹。"},{"k":"D","t":"胸腔穿刺傷。"},{"k":"E","t":"股骨閉鎖性骨折。"}],"answer":"B","expl":"趾骨閉鎖性骨折失血量很少，不會造成出血性休克；骨盆骨折、股骨骨折、胸部穿刺傷與延遲出現的腹內出血都可能造成休克，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-15","year":105,"qnum":15,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"有關腹部腔室症候群(ACS abdominal compartment syndrome)，下列何者錯誤?","opts":[{"k":"A","t":"正常之腹內壓力為 5 to 7 mmHg。"},{"k":"B","t":"用身體檢查預測腹部腔室症候群的準確度低。"},{"k":"C","t":"ACS (腹部腔室症候群) 是指腹內壓 IAP ≧ 20 mmHg 且有器官衰竭的證據。"},{"k":"D","t":"腹部腔室症候群不會影響病人的呼吸功能。"},{"k":"E","t":"Abdominal perfusion pressure (APP)為 mean arterial pressure (MAP) 減去Intraabdominal pressure (IAP)之差值。"}],"answer":"D","expl":"ACS 時腹內壓上升會使橫膈抬高、肺順應性下降、peak airway pressure 上升，嚴重影響呼吸功能，所以 (D) 錯。(A) 正常 IAP 約 5–7 mmHg；(C) ACS = IAP >20 mmHg 加新發器官衰竭；(E) APP = MAP − IAP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-16","year":105,"qnum":16,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下例有關緊急開胸手術的適應症，何者為非?","opts":[{"k":"A","t":"心包膜填塞。"},{"k":"B","t":"胸壁穿刺傷，疑似心臟受損。"},{"k":"C","t":"鈍性心臟損傷。"},{"k":"D","t":"大量血胸合併休克。"},{"k":"E","t":"放完胸管後，從胸管流出每小時超過 200hr 以上的血液，持續 4 小時。"}],"answer":"C","expl":"急診開胸的適應症：心包填塞、胸壁穿刺傷疑似心臟損傷、大量血胸合併休克、胸管引流 >200 mL/hr 達 2–4 小時；單純 blunt cardiac injury 並不是開胸適應症（以 ECG、troponin、echo 評估與支持治療），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-17","year":105,"qnum":17,"topic":"頭部TBI","subtopic":"總論／其他","stem":"一位 40 歲機車騎士被送至急診室，有明顯頭部外傷，兩眼瞳孔大小不等，血壓80/40mm Hg，呼吸聲音大，給予痛刺激時，兩眼睜開且兩側上臂彎曲並發出呻吟聲，以下的敘述何者正確？","opts":[{"k":"A","t":"此病患 GCS 為 6 分，屬於 severe head injury。"},{"k":"B","t":"此病患需迅速建立呼吸道，例如放置氣管內管，並給予暫時性過度換氣處置(Hyperventilation)。"},{"k":"C","t":"先輸予含葡萄糖水之靜脈輸液，將血壓提升至 100mm Hg 以上，且穩定後再送電腦斷層室行頭部及腹部電腦斷層檢查。"},{"k":"D","t":"做頭部電腦斷層時要注射顯影劑。"},{"k":"E","t":"若該院無神經外科醫師，則可以在病患到急診室時不做任何檢查，緊急將病患轉至其他有能力處置神經急症之醫院。"}],"answer":"B","expl":"同 98-26：嚴重頭部外傷併瞳孔不等大且低血壓，需先確保 airway（插管）與給氧，herniation 徵象時可短暫 hyperventilation，並同時處理低血壓；不應給含糖輸液。官方答案 (B)；依描述 GCS 約 7–8，(A)「6 分」不精確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-18","year":105,"qnum":18,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"有關於吸入性燒傷，下列何者錯誤?","opts":[{"k":"A","t":"二氧化碳與血紅素結合能力是氧氣 100 倍，所以二氧化碳中毒是最常見火場死亡原因。"},{"k":"B","t":"上呼吸道燒傷主要因為溫度性損傷，導致後咽部組織受傷水腫，立即阻塞呼吸道造成死亡。"},{"k":"C","t":"血液氣體分析可適用於評估下呼吸道燒傷與氧合問題，但對於診斷上呼吸道阻塞幫忙不大。"},{"k":"D","t":"濃煙吸到下呼吸道會有化學損傷，導致出血性氣管支氣管炎。"},{"k":"E","t":"如鼻腔或舌咽處有碳粒，最好選擇預防性插管。"}],"answer":"A","expl":"造成火場死亡的最常見原因是 carbon monoxide（CO，與血紅素親和力為氧的 200–250 倍）中毒，不是二氧化碳，所以 (A) 錯。(B) 上呼吸道熱損傷造成水腫阻塞；(C) ABG 對診斷上氣道阻塞幫助不大；(D)(E) 為標準觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-19","year":105,"qnum":19,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"有關食道鈍傷損傷，以下何者為非？","opts":[{"k":"A","t":"因為胃部氣體壓迫，常發生在下段食道處。"},{"k":"B","t":"有可能有縱膈積氣的情況產生。"},{"k":"C","t":"身體理學檢查對於頸部食道損傷或有幫助，但對於排除胸腔部位的食道損傷，則助益很小。"},{"k":"D","t":"當病人有右側氣胸或血胸卻無合併肋骨骨折時須納入考慮。"},{"k":"E","t":"食道損傷併發症發生的主要原因，常為疏漏或延遲診斷(Missed/delayed diagnosis) 。"}],"answer":"D","expl":"鈍性食道損傷多與胃內壓突然升高有關，常在下段；縱隔氣腫是重要徵象；因下段食道偏左，常造成左側氣胸或血胸，而非右側，所以 (D)「右側」為錯。(E) 併發症主要因延遲診斷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-20","year":105,"qnum":20,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關 blunt neck injury，下列何者正確？\na.頸部損傷依解剖位置可以分成 zone 1-3 三個區域。\nb.食道或氣管的損傷常會導致氣胸。\nc. carotid artery 的鈍傷常常導致動脈剝離，並往遠心端延伸。\nd.發現食道損傷破裂應盡速手術修補。","opts":[{"k":"A","t":"a、b 。"},{"k":"B","t":"a、b、c 。"},{"k":"C","t":"a、b、d 。"},{"k":"D","t":"a、b、c、d 。"},{"k":"E","t":"b、c、d。"}],"answer":"D","expl":"Blunt neck injury：頸部分 Zone I–III 三區；食道、氣管損傷可造成縱隔氣腫與氣胸；carotid artery 鈍傷常造成 dissection 並向遠端延伸；食道破裂應盡快手術修補（24 小時內效果較佳），所以 (D) a、b、c、d 皆正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-21","year":105,"qnum":21,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"八歲男童過馬路時，遭到時速 50 公里的轎車撞擊，彈離車子 3 公尺遠；送至急診室時，抱怨腹部疼痛，身體理學檢查發現血壓 68/40 mmHg、心跳每分鐘 200 次、腹部緊繃合併觸痛(firm, tender)，病人體重約 30 公斤，其收縮壓持續低於 90 mmHg，下列何項為最適當的輸液復甦方式？","opts":[{"k":"A","t":"先輸注 300 cc 溫的等張晶體溶液，血壓持續偏低就須輸 600 cc 的紅血球濃厚液(packed RBC)。"},{"k":"B","t":"先輸注 600 cc 溫的等張晶體溶液，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"},{"k":"C","t":"先輸注 300 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"},{"k":"D","t":"先輸注 300 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 600 cc 的紅血球濃厚液。"},{"k":"E","t":"先輸注 600 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"}],"answer":"E","expl":"30 kg 兒童出血性休克：20 mL/kg = 600 mL 晶體液；仍低血壓則輸 10 mL/kg pRBC = 300 mL。官方答案 (E) 允許先 600 mL 晶體液並重複 1–2 次後再輸血。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議起始 20 mL/kg 晶體液最多一次，若仍不穩定就盡快 10 mL/kg pRBC，不再多次重複晶體液。官方答案 (E) 不變，但臨床請依 ATLS 10/11。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"105-22","year":105,"qnum":22,"topic":"小兒","subtopic":"總論／其他","stem":"15 個月大女童在約 1 公尺高的桌上玩的時候，不慎摔落，頭部撞到地板，立刻嚎啕大哭，當時並沒有意識喪失現象，約 5 分鐘後停止哭泣，其他四肢活動及行為大致正常；下列何項陳述正確？","opts":[{"k":"A","t":"在急診室觀察 3-6 小時後，若無異常現象發現，可讓病童安心離院回家觀察。"},{"k":"B","t":"考量病童年齡較小，為減少放射線的暴露，安排頭部 X 光片較適當。"},{"k":"C","t":"若頭部外觀檢查無明顯外傷、頭部 X 光片檢查無明顯異常，就可讓病童安心離院回家觀察。"},{"k":"D","t":"嬰兒頭顱骨縫未完全密合，年齡屬於中度至重度危險因素，建議安排頭部電腦層檢查。"},{"k":"E","t":"此病童頭部受傷後並無意識喪失現象，發生顱內出血的機率很低，不需安排額外檢查。"}],"answer":"D","expl":"15 個月幼兒由約 1 公尺高處摔落：PECARN 對 <2 歲病童，跌落 >0.9 m、顱縫未癒合（前囪門）等屬較高風險因子，建議依風險評估 CT 或觀察，所以官方答案 (D)。單純頭部 X-ray 靈敏度不足，不能作為出院依據。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-23","year":105,"qnum":23,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕 30 週女性因高速車禍撞擊受傷，被送至一級創傷中心急救，3 分鐘後忽然量不到脈搏，下列敘述何者正確？","opts":[{"k":"A","t":"產婦發生車禍，胎兒的存活率不高，急救重點應該放在產婦上。"},{"k":"B","t":"必須先證實胎兒還有心跳，再進行緊急剖腹產，以確保胎兒存活。"},{"k":"C","t":"若急救復甦無效，應該在產婦心臟停止五分鐘內進行緊急剖腹產。"},{"k":"D","t":"進行緊急剖腹產時，應該使用水平子宮切口以利取出胎兒。"},{"k":"E","t":"緊急剖腹產未完成前，產婦不宜使用升壓劑，以免造成胎兒循環不足。"}],"answer":"C","expl":"同 99-44：孕 ≥20 週產婦心跳停止，若急救復甦無效，應在 4–5 分鐘內進行 perimortem cesarean，所以 (C)。不必先確認胎心；應用 vertical midline incision；不禁止 vasopressor。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-24","year":105,"qnum":24,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"68 歲酗酒男性因四肢無力送至急診室診治，據朋友陳述早上發現病人昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射 4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"同 103-20：老年酗酒者跌倒後上肢無力重於下肢、反射亢進與感覺障礙，符合 central cord syndrome，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-25","year":105,"qnum":25,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"下列有關外傷氣胸血胸患者治療原則，何者正確?","opts":[{"k":"A","t":"只要有一邊肺葉沒有傷害，幾乎不用插胸管。"},{"k":"B","t":"治療觀念轉為盡量保守，要緊急開腹的患者盡量不要插胸管。"},{"k":"C","t":"如果插的胸管不流，表示已經止血，不要通胸管避免再出血。"},{"k":"D","t":"雖然有連枷胸多處肋骨骨折，如無氣血胸，可以不插胸管。"},{"k":"E","t":"發生張力性氣胸，針刺減壓即可，不用插胸管。"}],"answer":"D","expl":"Flail chest 多處肋骨骨折若無氣胸或血胸，不一定需要放胸管，重點是止痛與肺部照護，所以 (D)。(A) 單側肺沒傷仍可能需要胸管；(B) 不應因要剖腹就不放胸管；(C) 胸管不流可能阻塞；(E) tension pneumothorax 針刺後仍需放胸管。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-26","year":105,"qnum":26,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"頸脊髓損傷致呼吸困難，呈腹式呼吸是損傷哪幾節頸神經?","opts":[{"k":"A","t":"1,2,3 節頸神經。"},{"k":"B","t":"2,3,4 節頸神經。"},{"k":"C","t":"3,4,5 節頸神經。"},{"k":"D","t":"5,6,7 節頸神經。"},{"k":"E","t":"6,7 頸神經/胸神經。"}],"answer":"C","expl":"隔膜由 C3–C5（phrenic nerve）支配，頸髓 C3–C5 損傷時呼吸主要靠腹式呼吸，所以 (C)；C1–C2 損傷可立即呼吸停止。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-27","year":105,"qnum":27,"topic":"腹部","subtopic":"脾臟","stem":"一名二十五歲男子在汽車車禍後被送往設有一般外科的醫院。他的 GCS 為 13，抱怨腹痛。他的血壓在到達醫院時收縮壓為 80mmHg，但是在給予 2 升靜脈內輸液後增加至 110/70mm Hg。他的心率保持每分鐘 120 次。電腦斷層掃描(CT)顯示第一級主動脈損傷(grade I aortic injury)和脾裂傷合併明顯的顯影劑外滲(contrast extravasation)。他的收縮壓在 CT 後下降到 70 mm Hg。下一步是什麼？","opts":[{"k":"A","t":"contrast angiography."},{"k":"B","t":"transfer to a higher level trauma center."},{"k":"C","t":"exploratory laparotomy."},{"k":"D","t":"transfuse packed red blood cells to stabilize his vital signs."},{"k":"E","t":"transesophageal echocardiography."}],"answer":"C","expl":"病人原本輸液有反應，但 CT 後血壓又降到 70，且有脾裂傷合併 contrast extravasation（active bleeding），代表 transient responder，應緊急 laparotomy，所以 (C)。補充：Grade I aortic injury 可延後處理；已輸 2 L 輸液超出現行 ATLS 建議。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-28","year":105,"qnum":28,"topic":"腹部","subtopic":"脾臟","stem":"一位血液動力學正常的 10 歲女孩在電腦斷層掃描(CT)證實 III 級(中度嚴重)脾損傷後，住入兒科重症監護病房(PICU)進行密切觀察及非手術療法。以下那一項是之後需要緊急開腹手術的適應症？","opts":[{"k":"A","t":"A serum amylase of 200."},{"k":"B","t":"A leukocyte count of 14,000."},{"k":"C","t":"Extraperitoneal bladder rupture."},{"k":"D","t":"Intra-abdominal pressure >20mmHg with new onset renal failure."},{"k":"E","t":"A fall in the hemoglobin level from 12 g/dL to 10.3 g/dL over 24 hours."}],"answer":"D","expl":"兒童 Grade III 脾傷 NOM 期間，出現 IAP >20 mmHg 合併新發腎衰竭，符合 ACS，需要緊急 decompressive laparotomy，所以 (D)。Amylase 輕度升高、白血球增加、extraperitoneal bladder rupture 與小幅 Hb 下降，都不一定需要手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-29","year":105,"qnum":29,"topic":"腹部","subtopic":"肝臟","stem":"關於肝撕裂傷，下列哪種說法是正確的?","opts":[{"k":"A","t":"Liver injury occurs in approximately 5% of all trauma admissions."},{"k":"B","t":"Grade V liver injury means Juxtahepatic venous injuries (i.e., retrohepatic vena cava/central major hepatic veins)"},{"k":"C","t":"Care for the patient with possible liver injury should proceed by the tenants of Advanced Trauma Life Support (ATLS). Of utmost importance is the initial evaluation, including attention to airway, breathing, and circulation."},{"k":"D","t":"Nonoperative treatment of the hemodynamically stable patient with blunt liver injury has become the standard of care in most trauma centers."},{"k":"E","t":"All of the above."}],"answer":"E","expl":"肝損傷：約 5% 住院外傷病人；Grade V 為 juxtahepatic venous injuries（Grade VI 為 hepatic avulsion）；依 ATLS 評估；血流動力學穩定者 NOM 已成為標準，所以 (E) 皆正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-30","year":105,"qnum":30,"topic":"頭部TBI","subtopic":"總論／其他","stem":"外傷急救時，如打算插鼻胃管(Nasogastric tube )之禁忌症為：","opts":[{"k":"A","t":"胃部穿孔。"},{"k":"B","t":"橫隔膜已破裂。"},{"k":"C","t":"開放性頭蓋骨陷入性骨折 (Depressed skull fracture)。"},{"k":"D","t":"頸椎骨折。"},{"k":"E","t":"顱底骨折。"}],"answer":"E","expl":"顱底骨折（或嚴重顏面中臉部骨折）是置放 NG tube 的禁忌，因可能導入顱內，應改用 OG tube，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-31","year":105,"qnum":31,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於使用腹腔鏡手術診斷及治療腹部外傷病人時，下列敘述何者為是?","opts":[{"k":"A","t":"微創手術對病人傷害小，生命現象不穩定病人獲益尤多。"},{"k":"B","t":"病人傷害程度越複雜，越適合使用腹腔鏡手術治療。"},{"k":"C","t":"病人若出現生命現象不穩定時，應考慮轉為剖腹手術。"},{"k":"D","t":"微創手術傷口小，能保證維持病人術中生命現象穩定。"},{"k":"E","t":"微創手術是外科的趨勢，應該能適用於所有外傷病患。"}],"answer":"C","expl":"腹腔鏡手術適用於血流動力學穩定的病人（如懷疑橫膈、腸道損傷的診斷）；若生命現象不穩定，應轉為剖腹手術，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-32","year":105,"qnum":32,"topic":"總論評分","subtopic":"總論／其他","stem":"下列有關穿刺傷(penetrating trauma)的敘述何者為非？","opts":[{"k":"A","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"},{"k":"B","t":"槍傷造成的 temporary cavity 一般比 permanent cavity 來的大。"},{"k":"C","t":"槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。"},{"k":"D","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)可能會有偏差。"},{"k":"E","t":"治療穿刺傷時病患收縮血壓應該控制在 140mmHg 以上為佳。"}],"answer":"E","expl":"同 100-47：穿刺傷病人在止血前不建議維持 SBP >140，應採 permissive hypotension（SBP 約 80–90 mmHg，無 TBI 時），所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-33","year":105,"qnum":33,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有ㄧ 28 歲男性遭人以刀刺中腹部多處傷口，產生小腸疝出現象(small bowel evisceration)，到院時病患呈現休克現象，依高級外傷救命術精神急救後緊急剖腹治療，發現有小腸穿孔及腸繫膜裂傷出血，與以緊急縫合止血，但病患生命現象持續不穩定並在後腹腔中線，主動脈分叉處以上五公分處有一逐漸擴張的搏動性腫塊(pusatile mass)，下列敘述何者為非？","opts":[{"k":"A","t":"此傷害位於後腹腔分區的第一區(Zone I)。"},{"k":"B","t":"此種狀況下可能是主動脈裂傷出血。"},{"k":"C","t":"應考慮壓迫止血，無論如何不可打開後腹腔。"},{"k":"D","t":"需考慮控制主動脈(clamp aorta)後，打開後腹腔修補血管止血。"},{"k":"E","t":"要改成動脈攝影栓塞成功止血並不容易。"}],"answer":"C","expl":"後腹腔 Zone I（中央、含主動脈）搏動性擴大血腫需要打開、近端控制並修補血管，不能只壓迫、更不能「無論如何不可打開」，所以 (C) 為非，官方答案 (C) 正確。","outdated":false,"suspect":true,"flagNote":"與 100-50（同一情境）對照：100-50 的官方答案把 (4)「clamp aorta 後修補」當成錯誤，與本題 (D) 的觀念相反，所以 100-50 的官方答案疑似有誤；本題官方答案 (C) 合理。原官方答案維持 (C)，考試請以官方答案為準。","images":[]},{"id":"105-34","year":105,"qnum":34,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"45 歲男性病人車禍外傷昏迷，顱內出血。手術後，病患病況依然未見好轉，二位相關專科醫師診斷為末期病人。家屬表示希望尊重病人意願，希望撤除維生醫療。病人 IC 卡上註記有預立選擇安寧緩和醫療意願，不施予心肺復甦術，此時可否撤除維生醫療?","opts":[{"k":"A","t":"得逕行撤除維生醫療。"},{"k":"B","t":"需經由醫學倫理委員會決議，方可撤除維生醫療。"},{"k":"C","t":"需經由安寧照護會診，方可撤除維生醫療。"},{"k":"D","t":"由一位親屬簽署終止或撤除維生醫療同意書後，方可撤除維生醫療。"},{"k":"E","t":"絕對不可撤除維生醫療。"}],"answer":"A","expl":"依台灣安寧緩和醫療條例：病人經兩位相關專科醫師診斷為末期，且 IC 卡上已註記不施行心肺復甦術與維生醫療意願，醫師可依其意願不施行或撤除維生醫療，不需要再經倫理委員會、安寧會診或家屬簽署，所以 (A)。法律細節近年有修訂，請依現行條文確認。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-35","year":105,"qnum":35,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"有關嚴重創傷出血病人的輸血治療及輸血併發症，下列選擇何者目前比較不適當？","opts":[{"k":"A","t":"儘早以血液製品做復甦，合併限制性的溶液復甦 。"},{"k":"B","t":"須大量輸血時，初期盡可能以 PRBC : FFP : Platelet = 1:1:1 比例輸血，可改善創傷病人預後。"},{"k":"C","t":"持續且積極的以晶體溶液進行容積復甦，並根據抽血檢驗再決定給予血液製品，以減少輸血併發症。"},{"k":"D","t":"若輸血後出現急性肺水腫，可使用心臟超音波檢查或 BNP(brain natriuretic pressure)檢驗以區別輸血相關的急性肺損傷(TRALI)或容積過量(TACO)。"},{"k":"E","t":"對呼吸器使用病人，應在輸血前進行氣道壓力限制，這是由於低潮氣容積對急性肺損傷病人可降低其死亡率。"}],"answer":"C","expl":"現行大量出血病人的 DCR：早期 balanced blood products、限制性晶體液（permissive hypotension）、低潮氣量保護肺；持續積極大量晶體液復甦會加重稀釋性凝血病變，所以 (C) 較不適當。(D) 可用 echo／BNP 區分 TRALI 與 TACO。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-36","year":105,"qnum":36,"topic":"腹部","subtopic":"脾臟","stem":"下列有關因腹部鈍傷而施行脾臟切除的敘述何者有誤？","opts":[{"k":"A","t":"脾臟受傷的病人，確實地治療出血遠比擔心切除脾臟後，造成 overwhelming infection 來的重要。"},{"k":"B","t":"發生 overwhelming post-splenectomy infection 的機率不高，約 2.6%-5.2%。"},{"k":"C","t":"發生 overwhelming post-splenectomy infection 的病原體為 encapsulated organism，如 pneumococcus, meningococcus。"},{"k":"D","t":"接種疫苗的時機建議在手術後數週後。"},{"k":"E","t":"建議約每 15 年接種一次疫苗。"}],"answer":"E","expl":"脾切除後 OPSI 發生率約 0.5–5%（多為 encapsulated organisms，如 pneumococcus、meningococcus、Hib）；疫苗建議在術後 14 天左右接種（或手術前至少 2 週），並依各疫苗規定追加（如 pneumococcus 約每 5 年），不是「每 15 年」，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-37","year":105,"qnum":37,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"22 歲男性車禍，左膝以下開放性骨折合併動脈急性出血及大量軟組織缺損(soft tissue loss)，經直接壓迫止血(direct compression)無效之後，請問最恰當的止血步驟為何?","opts":[{"k":"A","t":"立刻截肢。"},{"k":"B","t":"立即注射凝血因子 (Factor VII)。"},{"k":"C","t":"立即使用夾版固定 (splinting)。"},{"k":"D","t":"立即使用 Tourniquet。"},{"k":"E","t":"立即維持病患低血壓(permissive hypotensive therapy) 。"}],"answer":"D","expl":"肢體開放性骨折合併動脈出血，直接壓迫失敗時，應立即使用 tourniquet（TCCC 與 ATLS 10 皆建議），所以 (D)。不需立刻截肢；補充凝血因子 VII、夾板或維持低血壓都不能取代止血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-38","year":105,"qnum":38,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"45 歲女性因左側前胸穿刺刀傷被送至急診室，剛入急診室時病患意識清醒，隨即失去意識，呼吸停止且量不到血壓，心電圖顯示 narrow complex tachycardia，FAST 顯示有 pericardial effusion 及 left side moderate hemothorax。此時最恰當的處置步驟為何?","opts":[{"k":"A","t":"進行氣管插管，打上二條粗 iv line，給 epinephrine。"},{"k":"B","t":"Bag mask ventilation，聯絡心臟科醫師進行 pericardiocentesis。"},{"k":"C","t":"進行氣管插管並同時進行緊急開胸手術(emergency resuscitative thoracotomy)。"},{"k":"D","t":"進行氣管插管並開始 CPR，待病患回復心跳血壓後再做胸部電腦斷層確定診斷。"},{"k":"E","t":"停止急救，宣佈病患死亡。"}],"answer":"C","expl":"胸部穿刺傷在急診失去意識、呼吸停止、量不到血壓，FAST 見 pericardial effusion 與左側血胸，是 witnessed arrest 的穿刺性胸傷，應立即氣管插管並同時 resuscitative thoracotomy 解除 tamponade，所以 (C)。Pericardiocentesis 與 CPR 都無法解決根本問題。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-39","year":105,"qnum":39,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"肋骨骨折早期骨折固定手術(ribs fixation)，依據建議仍有爭議(controversial)，手術固定的好處不包括：","opts":[{"k":"A","t":"減少加護病房留住時間(ICU stay)。"},{"k":"B","t":"縮短呼吸道插管時間。"},{"k":"C","t":"固定手術，減少疼痛。"},{"k":"D","t":"槤拁胸 (flail chest)，減少胸管置放比率。"},{"k":"E","t":"降低肺部感染比例( pulmonary infection rate) 。"}],"answer":"D","expl":"肋骨固定手術（SSRF）的潛在好處是止痛、縮短呼吸器與 ICU 天數、降低肺炎與氣管切開比率；它並不是用來減少胸管放置比率，因為氣血胸本身仍需引流，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-40","year":105,"qnum":40,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"胸部外傷患者，儘早使用胸腔鏡輔助手術治療(Video-assisted Thoracoscopic Surgery;\nVATS)胸部外傷，近年進步神速，依據建議手術最大的效益為：","opts":[{"k":"A","t":"診斷與治療肋骨骨折。"},{"k":"B","t":"診斷橫膈膜的小破損(diaphragmatic small laceration)。"},{"k":"C","t":"診斷與治療肺部挫傷(pulmonary contusion)。"},{"k":"D","t":"治療胸部大血管出血。"},{"k":"E","t":"移除胸部內至流血塊(retained hemothorax)或血胸。"}],"answer":"E","expl":"VATS 在胸部創傷最明確的效益是清除 retained hemothorax（凝固的血胸），降低 empyema 與 fibrothorax 風險，建議在傷後數天內（約 3–7 天）進行，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-41","year":105,"qnum":41,"topic":"頭部TBI","subtopic":"總論／其他","stem":"嚴重頭部外傷的年輕女性，頭部昏迷分數(GCS)E1V2M3=6，兩邊瞳孔等大，各約3mm；對光有反射，生命徵象穩定。下列各項治療頭部外傷的處置，在急診那一項最優先：","opts":[{"k":"A","t":"避免低血壓出現(hypotension)，產生休克。"},{"k":"B","t":"使用降腦壓藥物(osmotic diuretic)。"},{"k":"C","t":"插管使用呼吸器，降低血中二氧化碳濃度，減少腦部水腫。"},{"k":"D","t":"使用麻醉藥物，減少腦部代謝需求。"},{"k":"E","t":"鑑別腦壓上昇的原因，針對血塊或腦腫治療。"}],"answer":"A","expl":"同 102-12：嚴重 TBI 早期最重要是避免 hypotension 與 hypoxia，防止 secondary brain injury，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-42","year":105,"qnum":42,"topic":"其他","subtopic":"總論／其他","stem":"ICD-10 CM 中對於外傷的完整診斷必須包含數個面向，下列何者為非？","opts":[{"k":"A","t":"外傷部位，即診斷碼。"},{"k":"B","t":"外傷機轉，分為意外、自我傷害、他人加害及意圖未明。"},{"k":"C","t":"外傷發生地點。"},{"k":"D","t":"外傷發生時，傷者的活動。"},{"k":"E","t":"外傷發生時，傷者意識受酒精影響的程度。"}],"answer":"E","expl":"ICD-10-CM 的外傷完整診斷包含：傷害部位（診斷碼）、外傷機轉／意圖（意外、自傷、他傷、未明）、發生地點與活動，不需要記載意識受酒精影響的程度，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-43","year":105,"qnum":43,"topic":"總論評分","subtopic":"總論／其他","stem":"對於外傷嚴重度評估的論述以下何者為非？","opts":[{"k":"A","t":"Injury severity score (ISS)是由 Baker 於 1974 年提出。"},{"k":"B","t":"台灣最廣泛使用的是 ISS。"},{"k":"C","t":"除了 ISS 之外，其他的評估方式都不盡理想。"},{"k":"D","t":"International classification of disease injury severity score (ICISS) 較 ISS 有更平滑且相關性更高的死亡率分布。"},{"k":"E","t":"New injury severity score (NISS)與 ISS 的計算方式相似，NISS 是取所有 AIS 中分數最高的三個平方和而 ISS 是在六組 AIS 中取出最高的三組，再取其平方和。"}],"answer":"C","expl":"外傷嚴重度評估：ISS 由 Baker 於 1974 年提出；ICISS 與 NISS、TRISS、RTS 等也被廣泛研究，ISS 並非唯一理想方式，所以 (C)「其他方式都不盡理想」為錯。(E) NISS 取全身最高三個 AIS 的平方和，ISS 取六區各取最高的三區。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-44","year":105,"qnum":44,"topic":"骨盆泌尿","subtopic":"尿道損傷","stem":"有位建築工人在鷹架上滑落跌坐到一隻橫桿上，急診理學檢查發現陰囊以及會陰部血腫如下圖，請問下列何者檢查為宜?","opts":[{"k":"A","t":"尿道逆行性攝影 (retrograde urethrography)。"},{"k":"B","t":"骨盆腔電腦斷層 (pelvic CT scan)。"},{"k":"C","t":"陰囊超音波 (scrotal sonography)。"},{"k":"D","t":"膀胱造影 (cystography)。"},{"k":"E","t":"血管攝影 (pelvic angiography)。"}],"answer":"A","expl":"跨騎傷（straddle injury）後陰囊與會陰部血腫（butterfly hematoma）要高度懷疑 bulbar urethral injury，首選為 retrograde urethrography，所以 (A)。不要先放 Foley。","outdated":false,"suspect":false,"flagNote":"","images":["p145-1.jpg"]},{"id":"105-45","year":105,"qnum":45,"topic":"骨盆泌尿","subtopic":"尿道損傷","stem":"一位醉漢發生車禍解出少量血尿並抱怨下腹痛，送醫後血壓與血紅素數值皆正常，也發現下腹淤青，腹膜炎症狀很明顯，請問診斷此患者最有用的工具為？","opts":[{"k":"A","t":"注射顯影劑電腦斷層檢查 (CY-CT scan)。"},{"k":"B","t":"尿道攝影 (urethrography)。"},{"k":"C","t":"靜脈腎盂尿路攝影 (IVU)。"},{"k":"D","t":"膀胱攝影 (cystography)。"},{"k":"E","t":"膀胱鏡檢 (cystoscopy)。"}],"answer":"D","expl":"下腹鈍傷、少量血尿與腹膜炎，應懷疑膀胱破裂（尤其 intraperitoneal），最有用的檢查是 cystography（逆行膀胱攝影，或 CT cystography），所以 (D)。普通 CT 不加 cystography 可能漏診。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-46","year":105,"qnum":46,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"下列關於事件指揮系統(incident command system, ICS)之敘述何者為非？","opts":[{"k":"A","t":"衛生醫療機構或災難應變單位的人員都應熟悉的基本知識。"},{"k":"B","t":"是災難事件(disaster)能否成功應變的關鍵。"},{"k":"C","t":"指揮官(incident commander, IC)必須為整個災難應變負責。"},{"k":"D","t":"若於災難現場，事件指揮中心(incident command post)應位於暖區(warm zone)， 且於地勢的相對上坡、上風或上游處。"},{"k":"E","t":"僅適用於現場(field)應變，在醫院內部的災難事件並不適用。"}],"answer":"E","expl":"ICS（Incident Command System）適用於現場與醫院內部（HICS）的災難應變，不是僅限現場，所以 (E) 為非。","outdated":false,"suspect":true,"flagNote":"選項 (D)「指揮站設在 warm zone」本身也不正確：incident command post 通常設在 cold zone（安全的支援區），且在上風、上坡處；因此 (D) 也有問題，官方答案以 (E) 為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"105-47","year":105,"qnum":47,"topic":"災難院前法規","subtopic":"總論／其他","stem":"在一場大型聚會活動中，您和二名護理師受聘支援醫療站。某區突然發生爆炸意外；待群眾被疏散後，您的救護團隊進入已確定現場安全的管制區，發現有五名傷患，病況初步評估如下，請決定您後送這些病人到醫院的優先順序(由先到後依序為)：\n甲病患：年輕男性，坐臥在地上、大喊：「我的腿斷了，快來救我」。\n乙病患：年輕女性，呼吸急促、臉色蒼白、主述腹部鼓脹疼痛。\n丙病患：年輕女性，口鼻出血、呼吸有雜音、僅對疼痛刺激有反應。\n丁病患：中年男性，持續大喊應該送他到醫院，不然要找律師告你。","opts":[{"k":"A","t":"甲、乙、丙、丁。"},{"k":"B","t":"丁、丙、乙、甲。"},{"k":"C","t":"乙、丙、甲、丁。"},{"k":"D","t":"丙、乙、甲、丁。"},{"k":"E","t":"甲、丙、乙、丁。"}],"answer":"D","expl":"MCI 優先順序：丙（口鼻出血、呼吸有雜音、僅對疼痛有反應，氣道危急）→ 乙（呼吸急促、臉色蒼白、腹脹，疑似腹內出血休克）→ 甲（骨折，能說話）→ 丁（大聲說話，輕傷），所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-48","year":105,"qnum":48,"topic":"休克輸血","subtopic":"抗凝／抗血小板藥物與外傷出血","stem":"關於外傷病患使用抗凝血劑之敘述，何者為非：","opts":[{"k":"A","t":"INR 最好在住院 4 小時內改正回來。"},{"k":"B","t":"可使用 fresh-frozen plasma 及 Vit.K 治療。"},{"k":"C","t":"如果沒有明顯出血，INR 延長可以不必更正。"},{"k":"D","t":"迅速送達設備完善又具經驗之醫院，則死亡殘廢之發生率可減至最低。"},{"k":"E","t":"老人病患要特別注意有無使用抗凝血劑。"}],"answer":"C","expl":"外傷病人使用抗凝血劑：INR 延長即使無明顯出血，通常也應盡快矯正（尤其老年人、頭部外傷），所以 (C)「不必更正」為錯。補充：現行指引（如歐洲出血指引）偏好 PCC（四因子）加 vitamin K 做 warfarin 逆轉，而不是單用 FFP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-49","year":105,"qnum":49,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"對於胰臟鈍傷，下列敘述何者為非?","opts":[{"k":"A","t":"由於位於後腹膜腔，臨床診斷比較困難。"},{"k":"B","t":"血中 Amylase 濃度是一項高敏感指標，有高達 80%病患有 hyperamylasemia。"},{"k":"C","t":"Abdominal CT 診斷有高達 80%的 sensitivity 及 specificity，但仍與受傷時間、影像的解析度及影像判讀人的經驗相關。"},{"k":"D","t":"ERCP (Endoscipic Retrograde Cholangio-pancreitco-graphy)對於診斷 main pancreatic duct 是否受傷或斷裂(transection)有很高的診斷率。"},{"k":"E","t":"Main Pancreatic duct 斷裂，是行外科手術處理的適應症(surgical indication)。"}],"answer":"B","expl":"Serum amylase 對胰臟鈍傷既不敏感也不專一，早期可正常，所以 (B)「高敏感指標、80%」為錯。(C) CT 診斷有一定限制；(D) ERCP 對 main duct 診斷準確；(E) main pancreatic duct 斷裂為手術適應症。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"105-50","year":105,"qnum":50,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"關於大量傷患檢傷分類(triage during mass-casualty events)的敘述，何者為非?","opts":[{"k":"A","t":"運用有限可用的資源，對最多的病人做最好的治療。"},{"k":"B","t":"評估的順序一般為呼吸道(airway)、通氣(breathing)、循環(circulation)及神經學損傷(neurologic injuries)。"},{"k":"C","t":"可利用顏色來標示嚴重程度及緊急後送的順序，如綠色(green)常被用來標示嚴重且須快速轉送的病人。"},{"k":"D","t":"常以黃色(yellow)標示若於數小時內未獲得治療則會危及生命或肢體的病人。"},{"k":"E","t":"檢傷分類是必須一直持續的，因為有些病人的病情可能會改變。"}],"answer":"C","expl":"Triage 標示：red＝立即需要治療（immediate）；yellow＝可延遲數小時（delayed）；green＝輕傷（minimal）；black/gray＝死亡或預期死亡。綠色不是嚴重需快速轉送的病人，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-1","year":106,"qnum":1,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列有關 ICU 重症病患營養治療之敘述，何者為非？","opts":[{"k":"A","t":"較 高 蛋白 的攝 取 一般 更 能達 到氮 平 衡或 正 氮 平衡(nitrogen balance) ，故Traumatic brain injury (TBI)的病患相比於”非 TBI”的病患，前者對蛋白質的損耗(protein catabolism)更高，也更需要增加蛋白攝取。"},{"k":"B","t":"休克的重症病患仍使用升壓劑或強心劑時，若已接受充分復甦，且升壓劑或強心劑之劑量已持續減少，可嘗試給予腸道灌食。"},{"k":"C","t":"血液動力學不穩定的 ICU 病人，若能接受早期腸道灌食，其 ICU 死亡率及住院死亡率都較低。"},{"k":"D","t":"對於會因腸道營養而加重肝昏迷的病人，可使用支鏈胺基酸(branched chain amino acid)強化配方。"},{"k":"E","t":"對於”damage-control”腹部手術或治療 abdominal compartment syndrome 而不關閉腹部的病患，腸道營養可增加筋膜關閉成功率。"}],"answer":"A","expl":"同 104-20：營養治療中，TBI 與非 TBI 的蛋白質需求不一定需要大幅增加，「蛋白質越高越能達氮平衡」並非絕對，所以官方答案 (A) 為非。(B)(C)(E) 早期腸道營養與充分復甦後可進行；(D) BCAA 配方用於肝性腦病變。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-2","year":106,"qnum":2,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"八歲男童過馬路時，遭到時速 50 公里的轎車撞擊，彈離車子 3 公尺遠；送至急診室時，抱怨腹部疼痛，身體理學檢查發現血壓 68/40 mmHg、心跳每分鐘 200 次、腹部緊繃合併觸痛(firm, tender)，病人體重約 30 公斤，其收縮壓持續低於 90 mmHg，下列何項為最適當的輸液復甦方式？","opts":[{"k":"A","t":"先輸注 300 cc 溫的等張晶體溶液，血壓持續偏低就須輸 600 cc 的紅血球濃厚液(packed RBC)。"},{"k":"B","t":"先輸注 600 cc 溫的等張晶體溶液，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"},{"k":"C","t":"先輸注 300 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"},{"k":"D","t":"先輸注 300 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 600 cc 的紅血球濃厚液。"},{"k":"E","t":"先輸注 600 cc 溫的等張晶體溶液，必要時可再重覆輸注 1~2 次，血壓持續偏低就須輸 300 cc 的紅血球濃厚液。"}],"answer":"E","expl":"同 105-21：30 kg 兒童出血性休克，20 mL/kg = 600 mL 晶體液，仍低血壓則輸 10 mL/kg pRBC = 300 mL。官方答案 (E) 允許重複晶體液 1–2 次後再輸血。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議初始 20 mL/kg 晶體液最多一次，不穩定即盡快 10 mL/kg pRBC，不再多次重複晶體液。官方答案 (E) 不變，但臨床請依 ATLS 10/11。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"106-3","year":106,"qnum":3,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"同 99-17：創傷後免疫反應先是 hyperinflammation（SIRS），隨後才是 hypoinflammatory（CARS），所以 (A) 順序顛倒。","outdated":true,"suspect":false,"flagNote":"(E)「建議使用麩胺酸 glutamine」：近年試驗與營養指引不建議在創傷與重症常規補充靜脈 glutamine；官方答案 (A) 不變。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"106-4","year":106,"qnum":4,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部實質性器官及空腔器官之損傷的描述，下列何者錯誤?\na.肝臟是腹腔內最大的實質性器官，也是所有腹部鈍挫傷中最常見的實質器官損傷。\nb.腹部穿刺貫通傷但無內臟脫出或異常滲液者，若已超過 24 小時且一般情況良好者，可先採取嚴密觀察保守治療。\nc.實質性器官損傷的主要表現是腹腔內或後腹膜腔出血且合併有進行性的腹脹及腹痛。但若病人處於無法矯正的休克狀態(SBP< 90mmHg)，即使沒有腹痛的症狀也應進行剖腹探查術。\nd.腹腔內出血 3500ml，合併肝臟右葉 4 度損傷，右腎 4 級損傷及升結腸穿孔且大範圍壞死的患者，最佳的手術方式為以最迅速的方式進行右肝葉切除，右腎摘除，右半結腸切除術及小腸橫結腸吻合術。\ne.因車禍導致腹部鈍挫傷的患者，受傷 1 小時內的腹部 CT 顯示第五級脾臟破裂及大量腹腔內積液，無明顯游離氣體；此時為快速施行脾臟切除術，最建議的手術切口為從左肋緣下進入，以爭取時間完成脾臟切除。","opts":[{"k":"A","t":"bde。"},{"k":"B","t":"abd。"},{"k":"C","t":"ade。"},{"k":"D","t":"cd。"},{"k":"E","t":"de。"}],"answer":"C","expl":"同 103-9：a 錯（鈍傷最常受傷的是脾臟）；d 錯（damage control 而非大範圍切除重建）；e 錯（Grade V 脾傷走正中剖腹）；b、c 正確。所以 (C) ade。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-5","year":106,"qnum":5,"topic":"休克輸血","subtopic":"總論／其他","stem":"關於休克所產生的內分泌變化的敘述下列何者為非?","opts":[{"k":"A","t":"休克會造成交感神經活性增加，使得 adrenal medulla 在 24-48 小時內分泌catecholamine 增加。"},{"k":"B","t":"休克會刺激 hypothalamus 釋放出 corticotrophin-releasing hormone。"},{"k":"C","t":"在休克所產生發炎反應中最早出現的 proinflammatory cytokines 為 Tumor necrosis factor-ɑ(TNF-ɑ) 。"},{"k":"D","t":"低血容休克時會刺激下視丘釋放 anti-diuretic hormone (ADH)造成腎臟遠端腎小管對於水分通透性下降，降低體內水份及鈉離子流失。"},{"k":"E","t":"休克早期會因發炎反應造成中性球(neutrophil)活性增加進而引起細胞及器官功能受損。"}],"answer":"D","expl":"同 102-24：ADH 作用在遠端腎小管與集尿管，增加水分通透性、保留水分，所以 (D)「通透性下降」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-6","year":106,"qnum":6,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤?","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"同 99-14：熱量由醣類與脂肪混合，70% 脂肪非建議，所以 (B) 錯；血糖目標不宜過嚴（避免 ≤110 mg/dL）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-7","year":106,"qnum":7,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"Blunt bowel perforation 在腹部挫傷病患中，診斷相當重要；下列相關之敘述，何者有誤?","opts":[{"k":"A","t":"發生的 mechanism 通常是外力 compression，因外壓形成 closed loop，再因high intraluminal pressure，而 blowout。"},{"k":"B","t":"在 alcohol drinking, spinal cord injury 或 head injury with conscious disturbance的腹部挫傷病患，常會 missed diagnosis。"},{"k":"C","t":"Abdominal CT 呈現 bowel wall thickness, mesenteric hematoma 或 streaky sign應可確定診斷。"},{"k":"D","t":"Diagnostic peritoneal lavage (DPL)，可作輔助性診斷，可發現 positive Gram stain, elevation of amylase 或 alkaline phosphatase (ALP)。"},{"k":"E","t":"Laparotomy 是 treatment of choice，開刀延遲的時間長短與其合併症或死亡率有關。"}],"answer":"C","expl":"同 99-2：腹部 CT 的 bowel wall thickening、mesenteric hematoma、streaky sign 只是間接徵象，不能「確定診斷」，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-8","year":106,"qnum":8,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"有關頭部外傷非手術治療 (nonsurgical therapies for brain injury) 之敘述，以下何者有誤？","opts":[{"k":"A","t":"腦的灌流維持好，腦細胞才有機會恢復功能；否則，腦組織會死亡。所以點滴的給予應足夠，但也不可太多。"},{"k":"B","t":"過度通氣(Hyperventilation)，會使 CO2 分壓下降，讓腦血管收縮，進而降低顱內壓，故適合用來長期控制腦壓。"},{"k":"C","t":"目前尚無證據顯示使用類固醇對嚴重頭部外傷患者有好處，因此不建議在該類患者使用類固醇。"},{"k":"D","t":"抗癲癇藥物的使用，只能有效預防早發性癲癇，但超過七天的遲發性癲癇，不會因為用了藥而不發生。"},{"k":"E","t":"腦壓 (ICP) 在 25 mmHg 以下就算可以接受，即使因躁動或咳嗽等使得 ICP 太高，只要能自己回復正常就沒關係。"}],"answer":"B","expl":"同 101-40：長期 hyperventilation 會造成腦血管過度收縮與缺血，已不建議，只在 herniation 時短暫救命，所以 (B) 錯。(C) steroid 無益；(D) 抗癲癇藥只能預防早發性癲癇。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-9","year":106,"qnum":9,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"下列有關胸部外傷之敘述何者為非?","opts":[{"k":"A","t":"鏈伽胸(Flail chest)造成缺氧主要機轉為胸部不正常呼吸運動(paradoxical movement)影響氣體交換。"},{"k":"B","t":"當胸管放置後，引流血量大於 1500 毫升稱為大量血胸，頓挫傷及穿刺傷都可能造成大量血胸，其中以穿刺傷為主要造成原因。"},{"k":"C","t":"有關急診行緊急剖胸術，胸部穿刺性外傷患者較鈍傷患者有較好之預後，如果傷患在事故現場已無生命跡象，則不應再行剖胸術急救，因其成效有限。"},{"k":"D","t":"嚴重胸部外傷而影響循環(circulation)常見的原因為大量血胸及心包膜填塞。"},{"k":"E","t":"創傷性膈疝(Traumatic Diaphragmatic Hernia)左側比較容易發生，急性期手術治療宜採剖腹探查術；慢性外傷性橫膈疝氣手術治療以從胸部探查較佳。"}],"answer":"A","expl":"同 100-13：flail chest 低血氧主要來自疼痛造成換氣受限與下方 pulmonary contusion，paradoxical movement 本身不是主因，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-10","year":106,"qnum":10,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"下列有關 seatbelt sign following blunt abdominal trauma 之敘述何者為非？","opts":[{"k":"A","t":"對於車禍後有上述 seatbelt sign 之病人中，約有 12%存有腹內損傷。"},{"k":"B","t":"其中約 64%的病人，需要手術治療 operative management。"},{"k":"C","t":"於腹部 CT 上若可見游離氣(free air)，則小腸破裂之機會頗大。"},{"k":"D","t":"此一創傷機轉，可發生腰椎之 chance fracture。"},{"k":"E","t":"對於車禍後無 seatbelt sign 之病人中，約僅有 1.9%存有小腸破裂之機會。"}],"answer":"B","expl":"同 100-42：seatbelt sign 與腹內損傷、Chance fracture 相關；統計數字（12%、64%、1.9%）出自特定文獻，官方認為 (B) 有誤。臨床重點是 seatbelt sign 加 CT free air 或腹膜炎，需手術探查。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-11","year":106,"qnum":11,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列關於 Blunt diaphragmatic rupture 的敘述，何者不合理?","opts":[{"k":"A","t":"較少單獨外傷傷害，最常合併 associated injury，是 hepatic 或 splenic laceration。"},{"k":"B","t":"左側的發生率較右側為高。"},{"k":"C","t":"CXR 顯示 diaphragmatic elevation 或 visceral herniation 到胸腔。"},{"k":"D","t":"皆需手術治療，行 diaphragmatic repair，在 acute phase，可由 laparotomy approach。"},{"k":"E","t":"其合併 cardio-pulmonary dysfunction 的發生，可能與其 increased intra-abdominal pressure 有關。"}],"answer":"A","expl":"同 99-1：鈍性橫膈破裂常合併肝、脾與骨盆等損傷，左側較常見，CXR 可見橫膈抬高或內臟疝入，急性期可經腹手術修補。官方答案指 (A) 為不合理。","outdated":false,"suspect":true,"flagNote":"(A) 的敘述其實與文獻一致，看不出錯誤，答案疑有問題；考試仍以官方 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"106-12","year":106,"qnum":12,"topic":"腹部","subtopic":"肝臟","stem":"下列對於 blunt hepatic injury 的敘述，何者較不適當?","opts":[{"k":"A","t":"大部分可採取 non-operative management，其 successful rate 可達 95%以上。"},{"k":"B","t":"Abdominal CT 是相當準確的診斷工具，當它顯示有 contrast extravasation，表示一定是 arterial active bleeding, angiographic embolization 或手術是最好的治療方式。"},{"k":"C","t":"Liver abscess 是其可能的 complication，可用 CT or sono-guided percutaneous drainage 來處理。"},{"k":"D","t":"Liver biloma 發生的機會約為 3%，亦可用 percutaneous drainage 處理，若合併intra-hepatic duct stricture，可用 ERCP with stent 來引流。"},{"k":"E","t":"病患出院後，restriction of activity 是必要的；對於 high grade injury(≧3)，可能需要 3-4 個月時間才能恢復 full activity。"}],"answer":"B","expl":"同 99-9：CT 見 contrast extravasation 不一定代表動脈性出血，也可能是靜脈或 pseudoaneurysm，不能說「一定」，所以 (B) 不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-13","year":106,"qnum":13,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下列有關胰臟損傷 pancreatic injury 之敘述何者錯誤？","opts":[{"k":"A","t":"可能合併肝臟或近端小腸 proximal small bowel 損傷。"},{"k":"B","t":"腹部 X 光 plain abdominal radiographs 檢查，沒有發現胸椎或腰椎骨折 fractures of the lower thoracic and/or upper lumbar vertebrae，即可排除胰臟損傷的可能性。"},{"k":"C","t":"診斷性腹腔灌洗 diagnostic peritoneal lavage，對於胰臟損傷的診斷，可能出現偽陰性。"},{"k":"D","t":"血清澱粉酶濃度 serum amylase level 高低，與胰臟損傷程度沒有相關性。"},{"k":"E","t":"診斷胰管損傷 pancreatic duct injury，可以安排 endoscopic retrograde cholangio-pancreatography (ERCP)或 magnetic retrograde cholangio-pancreatography (MRCP)檢查。"}],"answer":"B","expl":"同 97-2：X-ray 沒有胸腰椎骨折不能排除胰臟損傷，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-14","year":106,"qnum":14,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關於 neck penetrating injury，下列敘述何者為非?","opts":[{"k":"A","t":"Zone II 區域比 Zone I 或 Zone III 區域更容易進行外科介入性治療(surgical intervention)。"},{"k":"B","t":"Zone III 區域因位置靠近 thoracic outlet 血管區，故手術時常需作 median sternotomy 或 clavicle resection。"},{"k":"C","t":"在 Zone I 或 Zone III 區域，arteriography 通常被認為是可被接受的檢查，來檢視大血管是否被傷害。"},{"k":"D","t":"因頸部食道傷害延遲診斷超過 12 小時，其死亡率可高達 17%。"},{"k":"E","t":"用 esophagography 來診斷食道破裂，其敏感度 (sensitivity)約為 70-80%。"}],"answer":"B","expl":"同 97-30：把 median sternotomy 與 clavicle resection 描述為 Zone III 的做法是錯的（那是 Zone I）；Zone III 需考慮 mandibular subluxation，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-15","year":106,"qnum":15,"topic":"小兒","subtopic":"總論／其他","stem":"以下關於小兒外傷處置的敘述何者正確？\n甲、外傷造成心跳停止的最常見原因為失血性休克。\n乙、估計氣管內管直徑，約同於第五指直徑。\n丙、因為插管時可能引發較強烈的迷走神經刺激，因此建議先打 atropine。\n丁、當小兒困難插管時，應先考慮 needle cricothyroidotomy，而非 surgical cricothyroidotomy。\n戊、兒童的生理耐受性較成人為差，因此同比例的失血時，低血壓出現的較早。","opts":[{"k":"A","t":"甲、丙、戊。"},{"k":"B","t":"丙、丁、戊。"},{"k":"C","t":"乙、丙、丁。"},{"k":"D","t":"乙、丙、戊。"},{"k":"E","t":"甲、丁、戊。"}],"answer":"C","expl":"同 97-35：乙（氣管內管約小指粗）、丙（官方認為插管前可用 atropine）、丁（兒童困難插管用 needle cricothyroidotomy）正確；甲（兒童創傷心跳停止最常見是低氧）與戊（兒童低血壓出現較晚）錯。所以 (C)。","outdated":true,"suspect":false,"flagNote":"丙「建議先打 atropine」在現行指引（ATLS 10、PALS）已非常規，僅在特定情況考慮。官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"106-16","year":106,"qnum":16,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關 cardiac injury 治療之敘述何者為非？","opts":[{"k":"A","t":"懷疑心臟鈍挫傷的病人，可能合併有其他原因，造成血行動力學不穩定時，可以考慮放置 pulmonary artery catheter 做鑑別診斷。"},{"k":"B","t":"大概只有 5-10% nonpenetrating cardiac injury 需要手術介入治療。"},{"k":"C","t":"Cardiac injury 的病人如果到院時就以心肺停止，即使在急診行緊急開胸術，預後仍很差。"},{"k":"D","t":"胸部穿刺傷的病人，如果到院時生命徵象穩定，假如 FAST 發現 pericardial fluid或者是有 pericardial view 發現 clotted laceration， 可先觀察就好，不需要做手術探查。"},{"k":"E","t":"Cardiac injury 的病人，如果在急診需進行緊急開胸時，建議採用 left anterolateral thoracotomy。"}],"answer":"D","expl":"穿刺性胸傷、生命徵象穩定，若 FAST 發現 pericardial fluid，必須做 subxiphoid pericardial window 或手術探查，不能只觀察，所以 (D) 錯。(B) 約 5–10% 鈍性心臟傷需手術；(E) ED thoracotomy 採 left anterolateral。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-17","year":106,"qnum":17,"topic":"腹部","subtopic":"肝臟","stem":"Grade V blunt hepatic injury 緊急手術中，已輸全血 12 單位、血小板 36 單位，現血壓偏低為 85/60mmHg、體溫為 35℃，受傷肝臟仍持續出血，以下敘述何者為是？","opts":[{"k":"A","t":"進行 Pringle Maneuver 以減少出血量，並快速將受損肝臟切除。"},{"k":"B","t":"關閉腹部傷口，以非手術療法 non-operative management (NOM)替代治療。"},{"k":"C","t":"於肝臟週圍以大塊紗布墊加壓，腹壁傷口以 Bogda bag 覆蓋，此為創傷控制手術。"},{"k":"D","t":"再輸全血 10 單位，同時滴注 Dopamin 以將血壓提昇至收縮壓 120mmHg 以上，小心將受損肝臟切除，並放置大號引流管。"},{"k":"E","t":"術中發現病患體溫持續下降，此現象可幫助大腦細胞承受較長缺氧時間。"}],"answer":"C","expl":"同 100-41：Grade V 肝損傷合併低體溫、大量輸血與持續出血，應 damage control：perihepatic packing，暫時關腹（Bogota bag），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-18","year":106,"qnum":18,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"下列何者非 Tactical Field Care 應當執行的醫療救治?","opts":[{"k":"A","t":"Bleeding control。"},{"k":"B","t":"Tension Pneumothorax。"},{"k":"C","t":"Pneumothorax。"},{"k":"D","t":"Cardiopulmonary Resuscitation (CPR) 。"},{"k":"E","t":"Airway problem- maintain airway。"}],"answer":"D","expl":"依 TCCC（Tactical Combat Casualty Care）：Tactical Field Care 階段處理 massive hemorrhage（tourniquet）、airway、tension pneumothorax、open pneumothorax 等；爆炸或穿刺傷無脈搏無呼吸者，在戰術環境不做 CPR，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-19","year":106,"qnum":19,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關骨盆骨折合併泌尿系統損傷的敘述何者錯誤?","opts":[{"k":"A","t":"男性比女性較易發生尿道損傷。"},{"k":"B","t":"若有血尿(gross hematuria)出現，在放置導尿管(Foley catheter)前應先進行逆行性尿道攝影(retrograde urethrogram)檢查,排除尿道損傷。"},{"k":"C","t":"逆行性膀胱攝影(retrograde cystogram) x 光片若出現火焰狀型態( “flame-like”appearance) ，則應懷疑有膀胱破裂。"},{"k":"D","t":"若合併膀胱破裂,大部份是屬腹腔內破裂(intraperitoneal bladder rupture) ，只需放置導尿管保守治療。"},{"k":"E","t":"骨盆骨折的男性在肛門指診若發現有高位攝護腺(high riding prostate) ，需懷疑有尿道斷裂。"}],"answer":"D","expl":"骨盆骨折合併膀胱破裂時，多為 extraperitoneal（骨片刺傷），可導尿保守處理；intraperitoneal bladder rupture 則需手術修補，所以 (D)「只需放導尿管」為錯。(B) 血尿先做 RUG；(C) flame-like 為 extraperitoneal 破裂的造影表現；(E) high-riding prostate 提示尿道斷裂。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-20","year":106,"qnum":20,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列有關橫膈膜損傷(diaphragmatic injury)常見的影像學表現，下列敘述何者為非？","opts":[{"k":"A","t":"胸部 X 光影像發現患側橫膈降低。"},{"k":"B","t":"胸部 X 光影像發現縱膈腔朝健側偏移。"},{"k":"C","t":"胸部 X 光影像發現胸腔有 air-fluid level。"},{"k":"D","t":"胸部 X 光影像發現鼻胃管蜷繞在胸腔內。"},{"k":"E","t":"胸部電腦斷層影像出現 collar sign。"}],"answer":"A","expl":"橫膈損傷的 CXR 表現為患側橫膈「抬高」或輪廓不清、縱隔向健側偏移、胸腔內見 air-fluid level 或腸氣、鼻胃管蜷曲於胸腔，CT 可見 collar sign；橫膈降低不是典型表現，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-21","year":106,"qnum":21,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"您經手一位多重外傷之病患，急診診斷為頭皮撕裂傷(AIS =1)，左手腕骨(AIS=2)，左股骨幹骨折(AIS=3)，骨盆骨折(AIS=3)，脾臟撕裂傷(AIS=3)，左側兩根肋骨骨折(AIS=2)，請問關於 ISS(Injury Severity Score)，以下何者正確?","opts":[{"k":"A","t":"此病患 ISS 總分應為 3*3+3*3+3*3=27。"},{"k":"B","t":"ISS 分數只要在病患離開急診住院時填寫一次即可，分數不會再變動。"},{"k":"C","t":"ISS 的缺點是只計算分區內最高分，容易忽略同一區域多重器官受傷的影響。"},{"k":"D","t":"ISS 在分類上屬於 physiological score。"},{"k":"E","t":"ISS 是台灣現行的外傷登錄法，也是與預後相關性最高的登錄法。"}],"answer":"C","expl":"ISS 取六個身體區域中最高 AIS 的前三名平方和：abdomen（spleen）3、extremity/pelvic girdle（femur 與骨盆 3）3、chest 2，所以 3² + 3² + 2² = 22；頭皮屬 external 1，腕骨也在 extremity 區域。ISS 是 anatomic score、缺點是同一區只取最高分，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-22","year":106,"qnum":22,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"關於肋骨骨折的病患，以下何者為非?","opts":[{"k":"A","t":"老年人肋骨骨折常因疼痛不敢呼吸而造成二氧化碳堆積以至於呼吸衰竭，是故此類病人建議住院治療以備不時之需，插氣管內管以呼吸器輔助之。"},{"k":"B","t":"肋骨斷裂數越多，合併肺部併發症機率越高。"},{"k":"C","t":"高位肋骨骨折病患需同時考慮主動脈弓受損。"},{"k":"D","t":"目前研究指出，多根肋骨骨折病患接受肋骨固定可幫助止痛、加速呼吸器脫離及縮短住院。"},{"k":"E","t":"肋骨骨折合併氣血胸者只須胸管治療即可，完全不需要任何手術治療。"}],"answer":"E","expl":"肋骨骨折合併氣血胸，多數靠胸管即可，但仍有部分需要 VATS（retained hemothorax）、開胸或固定手術，所以 (E)「完全不需要任何手術」為錯。(A) 老年人肋骨骨折易呼吸衰竭，建議住院；(C) 高位肋骨骨折要想到 aortic injury；(D) 固定可止痛並縮短呼吸器天數。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-23","year":106,"qnum":23,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"急診接獲通報，田中高鐵站爆炸案造成多人受傷事件(mass casualty event, MCE)，醫院指派你帶領醫療小組前往現場成立緊急醫療站，以下敘述何者為是？","opts":[{"k":"A","t":"醫療站應該離現場越近越好，才能就近照顧病人。"},{"k":"B","t":"醫師身為專業人員，不論受訓與否，應與搜救人員一同進入災區搶救生命。"},{"k":"C","t":"此事件應由內科醫師擔任檢傷官會比外科醫師合適。"},{"k":"D","t":"現場以檢傷分類為主，以現有資源盡可能救助最大量的傷患。"},{"k":"E","t":"身處醫療資源優渥的台灣，將手邊資源挹注在單一重傷患也是可行的。"}],"answer":"D","expl":"MCE 現場醫療站原則：檢傷分類為主，以有限資源讓最多傷患受益，所以 (D)。醫療站應設在安全的 cold zone 而非越近越好；醫師未受訓不應貿然進入危險區；檢傷官以有經驗的外科或急診醫師較合適；資源不應只挹注單一重傷患。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-24","year":106,"qnum":24,"topic":"頭部TBI","subtopic":"總論／其他","stem":"有關於頭部外傷的處理原則，下列敘述何者錯誤？","opts":[{"k":"A","t":"急診室的處理依據 ATLS 的原則，應優先處理 Airway, Breathing, Circulation。"},{"k":"B","t":"作為大量輸液時，0.9%生理食鹽水較 Lactate Ringer’s 為佳。"},{"k":"C","t":"在嚴重頭部外傷的病人，因為病人可能會有低血糖的問題，所以應該例行給予含醣的輸液做補充。"},{"k":"D","t":"在接受鎮靜劑治療之病患，需補足靜態能量消耗量(Resting metabolic expenditure)之 100%。"},{"k":"E","t":"經腸道或經靜脈給予之營養製劑配方，應於受傷後七天內給予含至少 15%蛋白質之熱量來源，以維持氮平衡。"}],"answer":"C","expl":"嚴重頭部外傷不應例行給予含糖輸液，因為高血糖會加重腦傷，所以 (C) 為錯。(A) 依 ATLS ABC；(B) 大量輸液時 0.9% NaCl 因等滲而較不致增加腦水腫（LR 為輕度低滲）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-25","year":106,"qnum":25,"topic":"頭部TBI","subtopic":"總論／其他","stem":"一位 65 歲男性病患酒後被人用球棒重擊頭部，送至急診室時 BP：140/75mmHg，HR:78/min，GCS 呈現 E1V2M4，病人外觀看起來有熊貓眼，有淡粉紅色液體從鼻孔及耳朵流出，且病人一直嘔吐，則下列敘述何者不正確？","opts":[{"k":"A","t":"病人可能有顱底骨折。"},{"k":"B","t":"因為意識不清楚，故應先予插管維持呼吸道暢通。"},{"k":"C","t":"因為病人一直嘔吐，故應插鼻胃管(NG tube)做引流。"},{"k":"D","t":"待病人生命徵象穩定且無呼吸道問題時可安排 Brain CT scan。"},{"k":"E","t":"可考慮給予預防性抗生素。"}],"answer":"C","expl":"顱底骨折徵象（熊貓眼、鼻耳漏）禁忌放置 NG tube，須改為 OG tube，所以 (C) 不正確。意識不清（GCS 7）應插管保護氣道，穩定後做 brain CT。","outdated":true,"suspect":false,"flagNote":"(E)「可考慮預防性抗生素」：目前證據（例如 Cochrane 回顧）並不支持顱底骨折合併腦脊液漏常規預防性使用抗生素；官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"106-26","year":106,"qnum":26,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"一位 30 歲男性在高速公路上車禍後被送至急診，抵達急診時已用頸圈固定，病人訴雙手麻痛且無力，理學檢查發現病人生命徵象正常無呼吸困難，GCS：E4V5M6，雙上肢肌力 4 分，雙下肢肌力 5 分，雙上肢對於觸覺較不敏感，左側胸部有壓痛，其餘檢查正常，胸部 X-ray 發現左側第一及第二肋骨骨折無氣血胸。則下列何者為是？","opts":[{"k":"A","t":"應趕緊使用 methylprednisolone (Solu-Medrol) 5.4mg/kg bolus。"},{"k":"B","t":"病人是 Brown-Sequard syndrome。"},{"k":"C","t":"在年輕人通常是因為 disc protrusion 所造成神經的壓迫。"},{"k":"D","t":"若病人在急診室等候病床時突然感到呼吸困難，可能是 spinal cord injury 在變化所造成，應立即推去做 C-spine MRI 以確定診斷。"},{"k":"E","t":"病人若在急診室等候病床的過程中喪失意識，可能是頭部外傷所造成，應立即推去做 brain CT scan。"}],"answer":"C","expl":"病人上肢無力與感覺差較下肢明顯，符合 central cord syndrome，不是 Brown-Séquard（單側運動與對側痛溫覺喪失）；年輕人多與椎間盤突出或過伸傷有關，所以 (C)。Methylprednisolone 在現行指引不建議常規使用；呼吸困難也不是立刻送 MRI 的指標。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-27","year":106,"qnum":27,"topic":"頭部TBI","subtopic":"輕度頭部外傷 CT 適應症（Canadian CT Head Rule）","stem":"下列有關輕度頭部外傷之定義與分類之敘述何者有誤?","opts":[{"k":"A","t":"輕度頭部外傷 : GCS score 12-15 分。"},{"k":"B","t":"低危險性輕度頭部外傷： GCS score 15 分，並無意識昏迷、失憶症、持續性嘔吐及頭痛等症狀。"},{"k":"C","t":"中危險性輕度頭部外傷： GCS score 15 分，有以下任一症狀，包括意識喪失、失憶症、持續性嘔吐及廣泛性頭痛。"},{"k":"D","t":"高危險性輕度頭部外傷： GCS score 14 或 15 分，有顱骨骨折或有神經學缺失症狀。"},{"k":"E","t":"如有凝血機轉異常、藥物或酒精的濫用，以前腦部開過刀、癲癇病史、多重外傷、<2 歲以下受虐兒、年紀超過 60 歲，不管症狀如何皆屬高危險性輕度頭部外傷。"}],"answer":"A","expl":"輕度頭部外傷定義為 GCS 13–15（12 分以下屬中度），所以 (A) 錯。(B)(C)(D)(E) 為低、中、高風險分類與高風險因子。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-28","year":106,"qnum":28,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"下列有關顱內壓監測 (ICP monitoring)之適應症與治療何者錯誤?","opts":[{"k":"A","t":"嚴重頭部外傷 (GCS score 3-8 分 ) CT 檢查異常時，如 hematoma 、contusions 、edema 、 compressed basal cisterns。"},{"k":"B","t":"嚴重頭部外傷 (GCS score 3-8 分 ) CT 檢查正常，但有下列二條件以上，得使用顱內壓監測：40 歲以上。肢體動作異常，去大腦強直、去皮質強直 、偏癱等。"},{"k":"C","t":"收縮壓在 90mmHg 以下。"},{"k":"D","t":"輕度頭部外傷( GCS score 13~15 分)與中度頭部外傷( GCS score 9~12 分)，不建議例行使用顱內壓監測，但可依病情需要個別考慮使用。"},{"k":"E","t":"建議使用類固醇治療顱內壓升高。"}],"answer":"E","expl":"顱內壓監測適應症：GCS 3–8 且 CT 異常；CT 正常但 >40 歲、動作姿勢異常或收縮壓 <90 mmHg 者；輕中度頭部外傷不例行監測。Steroid 對 TBI 無益甚至有害（CRASH trial），所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-29","year":106,"qnum":29,"topic":"其他","subtopic":"總論／其他","stem":"ICD-10 對於外傷的診斷需包含數個面向才算完整，下列何者敘述最不正確？","opts":[{"k":"A","t":"外傷部位，以解剖部位為軸心"},{"k":"B","t":"外傷機轉，分為意外、自我傷害、他人加害及意圖未明"},{"k":"C","t":"外傷發生的地點。"},{"k":"D","t":"外傷發生時，受傷人員從事的活動。"},{"k":"E","t":"外傷發生時，傷者的血中酒精濃度及意識受影響的程度。"}],"answer":"B","expl":"ICD-10 外傷診斷需有傷害部位、機轉與意圖（意外、自傷、他傷、未明）、發生地點與活動；血中酒精濃度或意識程度並非診斷碼必備項目，所以 (E) 較不正確（見 105-42）。官方答案給 (B)。","outdated":false,"suspect":true,"flagNote":"(B) 的敘述與 105-42 的 (B) 相同，且被視為正確；官方答案 (B) 與 105-42 的答案 (E) 互相矛盾，疑似有誤，考試仍請以官方答案為準。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"106-30","year":106,"qnum":30,"topic":"災難院前法規","subtopic":"總論／其他","stem":"爆炸傷主要來自於物理性、化學性或核能反應造成能量於短時間釋放出來，會造成不同級別的損傷，以下何者為非？","opts":[{"k":"A","t":"初級爆炸傷，指的是由爆炸震波造成的傷害。"},{"k":"B","t":"次級爆炸傷，指的是因爆炸中飛濺出來的物體造成的損傷。"},{"k":"C","t":"三級爆炸傷，指的是爆炸造成建築物倒塌後所引起的傷害。"},{"k":"D","t":"四級爆炸傷，指的是爆炸中閃光、輻射或熱能所造成的損傷。"},{"k":"E","t":"五級爆炸傷，指的是爆炸後中心形成真空後反向空氣所造成的傷害。"}],"answer":"E","expl":"爆炸傷分級：Primary＝爆震波（含 blast lung）；Secondary＝飛濺破片；Tertiary＝人被氣浪拋擲或建物倒塌；Quaternary＝其他（燒傷、閃光、輻射、吸入、擠壓）；Quinary 為生化或放射污染相關損傷，不是「真空後反向空氣」，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-31","year":106,"qnum":31,"topic":"胸部","subtopic":"VATS／ECMO","stem":"有關 Advantanges of ECMO in severe traumatic lung injury , except","opts":[{"k":"A","t":"ECMO may be used as a temporary replacement for the injured lungs that reduced ventilator settings."},{"k":"B","t":"Prevent further barotrauma, provide adequate ventilation, oxygenation and improvement of hypercapnia."},{"k":"C","t":"Lung rest “and buy time for lung recovery."},{"k":"D","t":"Correct coagulopathy status."},{"k":"E","t":"In the famous CESAR study, ECMO significantly improve survival without severe Disability. (Murray score > 3, or pH <7.20)"}],"answer":"D","expl":"ECMO 於嚴重肺損傷可暫代肺功能、避免 barotrauma、讓肺休息（CESAR 試驗顯示存活且無嚴重失能比例提升）；但 ECMO 需抗凝並會干擾凝血，不能矯正 coagulopathy，所以 (D) 不是優點。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-32","year":106,"qnum":32,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"肢體腔室症候群(compartment syndrome)，臨床症狀包含如下：臨床上如有肢體腔室症候群，哪一項最常、最早出現?","opts":[{"k":"A","t":"疼痛(pain)。"},{"k":"B","t":"蒼白(pallor)。"},{"k":"C","t":"麻木(paresthesia)。"},{"k":"D","t":"麻痺(paralysis)。"},{"k":"E","t":"無脈搏(pulselessness)。"}],"answer":"A","expl":"Compartment syndrome 最早、最常見的症狀是與損傷程度不成比例且被動拉伸加劇的疼痛（pain）；脈搏消失與麻痺是晚期，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-33","year":106,"qnum":33,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"慢性肝膽疾病或免疫功能缺損患者，假日旅遊到海邊採蚵，下肢被礁岩上蚵殼割傷。傷口隔日紅、腫、熱、痛，迅速沿著腳、足踝、小腿往上延伸。引起壞死性筋膜炎 (Necrotizing fasciitis)，下列有關憶斷與處置，何者不正確?","opts":[{"k":"A","t":"感染可能是，海洋(創傷)弧菌傷口感染。"},{"k":"B","t":"感染敗血原因可能是，嗜肉細菌傷口感染。"},{"k":"C","t":"僅需使用抗生素，外科手術增加死亡率。"},{"k":"D","t":"導致敗血症，迅速死亡。"},{"k":"E","t":"感染原因可能是，壞蛆菌感染。"}],"answer":"C","expl":"壞死性筋膜炎的標準治療是早期廣效抗生素加積極 debridement；僅用抗生素會增加死亡率，所以 (C) 錯。海水、蚵殼傷口、肝病者要考慮 Vibrio vulnificus。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-34","year":106,"qnum":34,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"發生車禍 30 歲男性病人，由救護車送達急診。主訴剛剛有撞擊到胸口，現覺胸口悶痛且呼吸不順暢：血壓 98/62 mmHg、每分鐘心率 120 次、呼吸 26 次；體溫 37.2℃。有關此病患可能出現的症狀及徵候，下列敘述何者錯誤？","opts":[{"k":"A","t":"心包膜填塞表現出來的 Beck triad 包括頸靜脈怒張、低血壓及低沉的心音(muffled heart sound)。"},{"k":"B","t":"心包膜填塞可能會有的 Kussmaul signs，病人深吐氣時頸靜脈會更加擴張。"},{"k":"C","t":"若病人出現 Hamman sign，要考慮病人有 pneumomediastinum 的可能性。"},{"k":"D","t":"若身體檢查發現病人的胸部右鎖骨中線以內有穿刺傷，需考慮心臟傷害的鑑別診斷。"},{"k":"E","t":"創傷性主動脈破裂在胸部 X 光上，可能出現食道偏離第 4 節胸椎-棘突(spinous process)的右側 1－2 公分以上。"}],"answer":"B","expl":"Kussmaul sign 為吸氣時頸靜脈反而更怒張（而非吐氣時），常見於縮窄性心包炎，也可見於心包填塞，所以 (B) 錯。(A) Beck triad 正確；(C) Hamman sign 提示縱隔氣腫；(D) 右鎖骨中線以內穿刺傷需想到心臟。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-35","year":106,"qnum":35,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"依據 2013 年 WTA 的指南 (guideline)，下列關於胰臟損傷之處理原則，何者有誤?","opts":[{"k":"A","t":"是否手術主要看主胰管是否有損傷。"},{"k":"B","t":"如剖腹探查發現胰臟有小於 50% 周長的撕裂傷，沒有胰管損傷的證據，則將其修補後放外部引流 (external drainage) 即可。"},{"k":"C","t":"第三級(grade III)行遠端胰臟切除術 (distal pancreatectomy) 並試著保留脾臟。"},{"k":"D","t":"第四級 (grade IV) 行外部引流 (external drainage) 。"},{"k":"E","t":"第五級 (grade V)，可能以損害控制 (damage control) 原則行胰臟十二指腸切除術 (pancreaticoduodenectomy)。"}],"answer":"B","expl":"胰臟損傷的處理取決於 main pancreatic duct 有無損傷；Grade I–II（無胰管損傷）止血加 external drainage，不需縫合修補實質，所以 (B)「修補後引流」為錯；Grade III 遠端胰臟切除；Grade V 的 Whipple 可採 damage control 分階段。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-36","year":106,"qnum":36,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"當膈神經(phrenic nerve)受傷時，會造成橫膈膜的 paralysis 而引起病人呼吸困難。而膈神經(phrenic nerve)的神經組成為何?","opts":[{"k":"A","t":"C1 and C2。"},{"k":"B","t":"C3 through C5。"},{"k":"C","t":"C6 and C7。"},{"k":"D","t":"T2 through T4。"},{"k":"E","t":"T9 and T10。"}],"answer":"B","expl":"膈神經來自 C3–C5（\"C3, 4, 5 keep the diaphragm alive\"），所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-37","year":106,"qnum":37,"topic":"四肢血管骨科","subtopic":"斷肢保存／壓砸傷／橫紋肌溶解","stem":"到院前對斷肢或斷指最恰當的保存步驟為何?","opts":[{"k":"A","t":"將斷肢或斷指以 sterile water 沖洗乾淨。"},{"k":"B","t":"將沖洗乾淨的斷肢或斷指浸泡在含有冰塊的 D5W 中。"},{"k":"C","t":"將紗布以 lactated Ringer’s solution 浸潤後包裹沖洗乾淨的斷肢或斷指，之後放入乾淨的 plastic bag 內，再將 plastic bag 放入碎冰中。"},{"k":"D","t":"將沖洗乾淨的斷肢或斷指浸泡在含有冰塊的 Lactated Ringer’s Solution 中，並置入維持0℃的冰箱中保存。"},{"k":"E","t":"以上皆非。"}],"answer":"C","expl":"斷肢（斷指）保存：以生理食鹽水或 LR 沖洗，包上以相同液體浸濕的紗布，放入乾淨塑膠袋，再放在冰上（避免直接接觸冰、不要乾冰），所以 (C)。不可直接浸泡於液體中。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-38","year":106,"qnum":38,"topic":"休克輸血","subtopic":"總論／其他","stem":"25 歲男性騎乘機車發生車禍，送至急診室時，BP：70/50mmHg，意識模糊， 對痛有反應，喃喃自語，頭皮有血腫，無其他明顯外傷，經緊急氣管內管插管及 2L生理食鹽水輸液後，BP：90/50mmHg，皮膚仍然溼冷，微血管再填充時間為 5 秒，電腦斷層顯示額葉散在性的出血與大腦腫脹，下列何者處置為佳?","opts":[{"k":"A","t":"給予 mannitol，積極治療顱內壓昇高，以期治療低血壓。"},{"k":"B","t":"給予升壓劑，以提高腦灌注壓，改善腦部灌流。"},{"k":"C","t":"安排胸部 X 光，與腹部超音波，積極地找尋其他的出血。"},{"k":"D","t":"安排緊急開顱手術。"},{"k":"E","t":"繼續給予大量生理食鹽水輸液補充。"}],"answer":"C","expl":"頭部外傷但合併休克時，不能把低血壓歸因於 TBI，應找其他出血來源（胸 X 光、骨盆 X 光、FAST 或 DPL），所以 (C)。成人單純 TBI 很少造成低血壓。","outdated":true,"suspect":false,"flagNote":"題幹「2L 生理食鹽水」的初始復甦已不符現行 ATLS 10/11（初始 1 L 後盡早輸血），且 NS 大量輸注有稀釋性酸中毒風險；官方答案 (C) 仍成立。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"106-39","year":106,"qnum":39,"topic":"老年孕婦","subtopic":"總論／其他","stem":"一位 82 歲男性從五層階梯處跌落，被緊急送至急診室，下列敘述關於他的臨床受傷機轉與年輕傷患相較之下何者為不適當之敘述?","opts":[{"k":"A","t":"相較於年輕傷患，會因為藥物或其他生理因素之影響，使得生命徵象的變化被掩蓋或是形成假象。"},{"k":"B","t":"相較於年輕傷患，其發生頸椎受傷的可能性上升，主要是因為椎體與椎間盤的退化、狹窄及彈性減弱造成。"},{"k":"C","t":"相較於年輕傷患，其發生顱內出血的臨床表現會更快速。"},{"k":"D","t":"相較於年輕傷患，其發生潛在性骨折的可能性增加。"},{"k":"E","t":"相較於年輕傷患，其發生潛在內出血的風險性增加。"}],"answer":"C","expl":"老年人腦萎縮，顱內出血症狀常延後出現，不是更快，所以 (C) 為不適當。(A) 藥物（beta blocker）會掩蓋生命徵象；(B) 頸椎退化；(D)(E) 潛在骨折與內出血風險增加。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-40","year":106,"qnum":40,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"胰臟外傷時何者用來診胰管受損斷裂最適當的診斷工具是？","opts":[{"k":"A","t":"Abdominal CT。"},{"k":"B","t":"MRCP。"},{"k":"C","t":"ERCP。"},{"k":"D","t":"DPL。"},{"k":"E","t":"PET。"}],"answer":"C","expl":"胰管損傷最準確的診斷是 ERCP，所以 (C)；MRCP（含 secretin）為不侵入式選項，穩定病人也常先用。CT 對 duct 損傷敏感度有限。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-41","year":106,"qnum":41,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"關於 Chest trauma 現今的治療何者為佳：","opts":[{"k":"A","t":"無論 pneumothorax or hemothorax 患者皆需 chest tube 引流。"},{"k":"B","t":"對於像 flail chest with ventilator support 的患者 ribs fracture fixation 的手術對治療並沒有幫助。"},{"k":"C","t":"Massive hemothorax 需維持患者 hemodynamic stable, 若出血量每小時大於 200毫升連續 4 小時則須考慮手術治療。"},{"k":"D","t":"只要好的止痛，肺部 intensive care 對患者並無明顯好處。"},{"k":"E","t":"pig-tail 因管徑太細容易阻塞不可用於 pneumothorax or hemothorax。"}],"answer":"C","expl":"Massive hemothorax：初始引流 >1,500 mL 或持續 >200 mL/hr 達 2–4 小時（官方寫 4 小時）需手術，所以 (C)。(A) 小量或無症狀氣胸可觀察；(B) flail chest 固定手術有幫助；(D) 肺部照護很重要；(E) 小管徑 pigtail 可用於氣胸及部分血胸。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-42","year":106,"qnum":42,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關骨盆腔骨折(Pelvic fracture)診斷治療之敘述何者為非？","opts":[{"k":"A","t":"可能會合併尿道損傷或腹內器官損傷。"},{"k":"B","t":"若病人在進行 CT 掃描時發現有顯影劑外洩，病人通常需 接受血管攝影栓塞治療(TAE) 。"},{"k":"C","t":"目前最有效的治療為骨骼外固定術，大約 90%以上病人都可止血。"},{"k":"D","t":"合併腹內空心臟器穿孔時，需進行剖腹手術治療。"},{"k":"E","t":"若病人生命現象不穩定，但無法做血管攝影栓塞治療(TAE)止血時，可以腹膜外填塞手術或腹腔內填塞手術協助止血。"}],"answer":"C","expl":"骨盆骨折：CT contrast extravasation 通常需 TAE；不穩定且無法 TAE 時可 preperitoneal packing；external fixation 或 binder 是暫時固定，並非「最有效、90% 止血」，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-43","year":106,"qnum":43,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術(damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血；紗布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復; 通過輸注液體和血液恢復正常的心血管狀態以及使用昇壓相關藥物；低溫後殘留凝血病變的矯正反轉；並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation)應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現致命三害(lethal triad)時。"}],"answer":"C","expl":"Damage control 的精神是縮短首次手術：控制出血與污染、暫時關腹，ICU 矯正低體溫、酸中毒、凝血病變後再做 definitive repair；休克時不做完整吻合重建，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-44","year":106,"qnum":44,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"腸道營養可改善創傷病患的治療結果原因為何，下列何者為非？","opts":[{"k":"A","t":"促進腸道蠕動。"},{"k":"B","t":"促進腸道絨毛的生長。"},{"k":"C","t":"保障腸道上皮細胞的完整。"},{"k":"D","t":"增加腸道黏膜的穿透性(permeability) 。"},{"k":"E","t":"促進腸道黏膜完整及免疫力。"}],"answer":"D","expl":"腸道營養能維持腸黏膜完整、促進腸道蠕動與免疫、降低腸道通透性（bacterial translocation），而非「增加通透性」，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-45","year":106,"qnum":45,"topic":"小兒","subtopic":"總論／其他","stem":"兩個月大男童因車禍被送至急診室，兩小腿明顯變形，合併有低血壓情形，醫護人員嘗試兩次由肘前窩處(antecubital fossa)打點滴失敗，下列何項為接續緊急建立輸液通道的最佳方式？","opts":[{"k":"A","t":"內頸靜脈中心靜脈導管Internal jugular central line。"},{"k":"B","t":"遠端隱靜脈切開術Distal saphenous vein cutdown。"},{"k":"C","t":"股靜脈中心靜脈導管Femoral vein central line。"},{"k":"D","t":"脛骨近端骨內針套管插入術Intraosseous (IO) cannulation of the proximal tibia。"},{"k":"E","t":"股骨遠端骨內針套管插入術IO cannulation of the distal femur。"}],"answer":"E","expl":"2 個月嬰兒休克且周邊靜脈建立失敗，應立即 intraosseous（ATLS 對 6 歲以下可直接 IO）。因雙小腿變形（疑骨折），不可用近端脛骨，改用遠端股骨 IO，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-46","year":106,"qnum":46,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕32週女性因高速車禍撞擊受傷，被送至一級創傷中心急救，3分鐘後忽然量不到脈搏，下列敘述何者正確？","opts":[{"k":"A","t":"產婦發生車禍，胎兒的存活率不高，急救重點應該放在產婦上。"},{"k":"B","t":"必須先證實胎兒還有心跳，再進行緊急剖腹產，以確保胎兒存活。"},{"k":"C","t":"若急救復甦無效，應該在產婦心臟停止五分鐘內進行緊急剖腹產。"},{"k":"D","t":"進行緊急剖腹產時，應該使用水平子宮切口以利取出胎兒。"},{"k":"E","t":"緊急剖腹產未完成前，產婦不宜使用升壓劑，以免造成胎兒循環不足。"}],"answer":"C","expl":"同 99-44：孕婦心臟停止，若復甦無效，應在 4–5 分鐘內進行緊急剖腹產（perimortem cesarean），不必確認胎心，建議用 vertical midline incision，也可使用 vasopressor，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-47","year":106,"qnum":47,"topic":"總論評分","subtopic":"Trimodal death distribution／到院前死亡高峰","stem":"下列有關 trimodel death distribution 之敘述何者為非？","opts":[{"k":"A","t":"外傷死亡分佈最多落在第一個死亡高峰。"},{"k":"B","t":"第一個死亡高峰發生在外傷事故現場。"},{"k":"C","t":"第三個死亡高峰常見原因是敗血症和多器官衰竭。"},{"k":"D","t":"第一、第二階段的處置和第三個死亡高峰沒有關係。"},{"k":"E","t":"第三個死亡高峰現在已經逐漸降低。"}],"answer":"D","expl":"外傷三峰死亡分布：第一峰（數秒至數分鐘，現場，最多）、第二峰（數小時，Golden Hour）、第三峰（數天至數週，sepsis 與 MOF）；早期處置品質會影響第三峰，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-48","year":106,"qnum":48,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"20 歲女性從 6 公尺高跌落，先被 EMT 送至地區醫院急診室，經 survey and resuscitation後，初步診斷為 bilateral calcaneal fracture and T12 compression fracture,後因 unstable hemodynamic status, 地區醫院急診室醫師 order blood transfusion with PRBC 4U &FFP 4U 後，緊急後送至 30 分鐘車程之醫學中心，on arrival in the emergency department of medical center, the vital sign were BT:35.8C, Pulse:80/min, Respiratory rate:20/min, Blood pressure:80/50 mmHg, GCS:E3V5M6，尚剩 FFP 2U 仍在輸血中，身為醫學中心急診室值班醫師的你(妳)，下列敘述或處置何者最不恰當?","opts":[{"k":"A","t":"Check breathing sounds 及安排 portable CxR。"},{"k":"B","t":"可能為 neurogenic shock,輸完血液製品後,須儘快使用 dopamine。"},{"k":"C","t":"執行 Focused Assessment Sonography in Trauma (FAST)檢查。"},{"k":"D","t":"檢查是否有 pelvic fracture。"},{"k":"E","t":"檢查是否有 femur fracture。"}],"answer":"B","expl":"多處骨折、持續低血壓時，先排除出血性休克（胸、腹、骨盆、股骨），neurogenic shock 是排除診斷；不應在輸血後馬上假設為 neurogenic 而給 dopamine，所以 (B) 最不恰當。補充：升壓劑首選 norepinephrine，dopamine 不再是首選。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-49","year":106,"qnum":49,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷會引起身體重大的新陳代謝與內分泌變化，臨床表現不包括下列何項敘述：","opts":[{"k":"A","t":"新陳代謝與內分泌的變化與疾病嚴重度成正相關。"},{"k":"B","t":"基礎新陳代謝率大大提升，與疾病嚴重度成正相關。"},{"k":"C","t":"大量脂肪燃燒，以作為主要的燃料來源。"},{"k":"D","t":"醣質新生加上胰島素抗性所導致的高血糖。"},{"k":"E","t":"蛋白質分解大於合成，呈現負氮平衡。"}],"answer":"C","expl":"創傷後 hypermetabolism：基礎代謝率增加、醣質新生加上 insulin resistance 造成高血糖、蛋白質分解大於合成呈負氮平衡；熱量來源以葡萄糖與蛋白質分解為主，並非「大量燃燒脂肪為主要燃料」，所以 (C)（官方答案）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"106-50","year":106,"qnum":50,"topic":"燒傷環境","subtopic":"低體溫與凍傷","stem":"針對 Cold injury 的處置，下列選擇何者錯誤？","opts":[{"k":"A","t":"注意病人是否有 organized cardiac rhythm；若無，則持續 CPR 直到回溫。"},{"k":"B","t":"發現 Cold injury 病人當下，若已出現 cardiac arrest，則不須考慮回溫且可宣佈死亡。"},{"k":"C","t":"回溫可使用溫毯、加溫的靜脈輸液、膀胱/腹膜/肋膜灌洗、溫溼的通氣。\n(ventilation)，甚至 cardiopulmonary bypass。"},{"k":"D","t":"若病人體溫已低於 28℃合併 ventricular fibrillation，建議先回溫到 28℃以上後再給予藥物或去顫。"},{"k":"E","t":"不建議放置鎖骨下或內頸靜脈導管，因為容易誘發無法控制的心律不整。"}],"answer":"B","expl":"低體溫心跳停止原則 \"no one is dead until warm and dead\"，必須回溫到接近正常再判斷，所以 (B) 錯。(C) 回溫方式包括 ECMO、CPB、體腔灌洗；(E) 中心靜脈導管可能誘發心律不整，故避免。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-1","year":107,"qnum":1,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"根據第十版 ATLS 對於胸部外傷處理下列何者正確?\n1.張力性氣胸針刺減壓 Needle decompression of pneumothorax 成人改為第五肋間腋\n1.中線或前線。\n2.小兒為鎖骨中線第二肋間下緣。\n3.血胸胸管選擇為 36-40 Fr。\n4.大量血胸時可給予斷血炎注射液 Tranexamic acid 1g over 10 min stat and 1g over8h given within 3h。","opts":[{"k":"A","t":"1+3。"},{"k":"B","t":"2+4。"},{"k":"C","t":"1+2+3。"},{"k":"D","t":"1+2 +4。"},{"k":"E","t":"1+2+3+4。"}],"answer":"D","expl":"ATLS 10：成人 tension pneumothorax 針刺減壓位置改為第 5 肋間（腋前線至中線前方）；小兒在鎖骨中線第 2 肋間；胸管大小為 28–32 Fr（不是 36–40 Fr）；TXA 依 CRASH-2：1 g（10 分鐘）加 1 g（8 小時）、傷後 3 小時內。所以 1、2、4 正確，3 錯，答案為 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-2","year":107,"qnum":2,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"多重外傷併出血病患，下列敘述何者錯誤?","opts":[{"k":"A","t":"輸液治療給予溫暖的等滲液體，通常初始劑量是成人約 1500-2000ml。"},{"k":"B","t":"Class I 出血時無明顯生理變化。"},{"k":"C","t":"Class II 出血量約佔全身血量 15-30%。"},{"k":"D","t":"Class III 出血時，鹼基評估(Base deficit)約至–6to–10mEq/L。"},{"k":"E","t":"兒童患者尿液輸出期望維持 1mL/kg/hr。"}],"answer":"A","expl":"ATLS 10：成人初始輸液為 1 L 溫熱等張晶體液，而不是 1.5–2 L，所以 (A) 錯。Class I 無明顯變化；Class II 失血 15–30%；Class III 鹼基缺失 −6 至 −10；兒童尿量目標約 1 mL/kg/hr。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-3","year":107,"qnum":3,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列敘述何者有錯誤?","opts":[{"k":"A","t":"免疫營養配方例如 Glutamine， 常被建議使用。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。可依外傷病患嚴重度調整至 35 to 40 Kcal/Kg/day。"},{"k":"C","t":"蛋白質的建議劑量為 0.6 to 0.8 g/kg/day，燒燙傷患者更可高於 1.0 g/kg/day。"},{"k":"D","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"C","expl":"蛋白質建議為 1.2–2.0 g/kg/day（燒傷更高），0.6–0.8 g/kg/day 只是一般成人需求，所以 (C) 為錯。","outdated":true,"suspect":false,"flagNote":"(A)「免疫營養 glutamine 常被建議」：近年試驗（如 REDOXS）與營養指引不建議在重症與創傷常規補充靜脈 glutamine；官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"107-4","year":107,"qnum":4,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"關於腹部腔室症候群(abdominal compartment syndrome)的敘述，下列何者有誤?","opts":[{"k":"A","t":"腹部腔室症候群發生時，一般是使用藥物控制即可。"},{"k":"B","t":"正常之腹內壓力為 5 to 7 mmHg。"},{"k":"C","t":"ACS (腹部腔室症候群) 是指在無脫水狀態下，腹內壓 IAP≧ 20 mmHg，且有器官衰竭的證據。"},{"k":"D","t":"一般使用測量膀胱壓力，來取代腹內壓力。"},{"k":"E","t":"Abdominal perfusion pressure (APP)為 mean arterial pressure (MAP) 減去Intraabdominal pressure (IAP)之差值。"}],"answer":"A","expl":"ACS 的主要處置是外科 decompressive laparotomy，藥物只能作為輔助或預防，所以 (A) 錯。IAP 正常 5–7 mmHg、ACS＝IAP >20 mmHg 加新器官衰竭、以膀胱壓測量、APP＝MAP−IAP。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-5","year":107,"qnum":5,"topic":"總論評分","subtopic":"總論／其他","stem":"多重性外傷病人的何項損傷須優先安排手術?","opts":[{"k":"A","t":"收縮壓 70 mmHg 併脾臟破裂。"},{"k":"B","t":"意識清楚但有小量腦出血。"},{"k":"C","t":"上肢撕裂傷 5 公分。"},{"k":"D","t":"股骨閉鎖性骨折。"},{"k":"E","t":"老人病患橈骨骨折。"}],"answer":"A","expl":"休克（SBP 70）合併脾臟破裂是活動性出血，需最優先手術止血，所以 (A)。其餘皆可延後處理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-6","year":107,"qnum":6,"topic":"腹部","subtopic":"肝臟","stem":"下面那一位腹部受傷病人不需馬上開腹手術：","opts":[{"k":"A","t":"休克且 FAST 陽性，可能腹部出血。"},{"k":"B","t":"FAST 陽性，有腹膜炎。"},{"k":"C","t":"CT 有 LIVER injury，生命徵象穩定。"},{"k":"D","t":"CT 有 free air，生命徵象穩定。"},{"k":"E","t":"CT 有脾臟損傷，生命徵象不穩定。"}],"answer":"C","expl":"血流動力學穩定的肝損傷（CT 確診）可 NOM，不需立即開腹，所以 (C)。休克加 FAST 陽性、腹膜炎、CT 有 free air（腸穿孔）、不穩定脾損傷皆需手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-7","year":107,"qnum":7,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"您是一位服役於野戰醫院的軍醫，戰鬥中接到一位遭手榴彈炸傷的後送傷兵.a)右小腿外傷性截肢。\nb)腹部開放性傷口併內臟脫出及出血。\nc)右側開放性氣胸。\nd)右臉頰缺失併口鼻出血。\ne)背部大面積燒傷。\n請問您處理的順序為何？","opts":[{"k":"A","t":"cbdae。"},{"k":"B","t":"dcbae。"},{"k":"C","t":"bcdae。"},{"k":"D","t":"bacde。"},{"k":"E","t":"bcade。"}],"answer":"B","expl":"戰場多處受傷的處理順序，官方答案 (B) 為 d（口鼻出血，氣道）→ c（開放性氣胸）→ b（腹部內臟脫出）→ a（截肢）→ e（燒傷），依 ABC 次序以氣道問題最優先。","outdated":true,"suspect":false,"flagNote":"現行 TCCC 與 ATLS 10 以 MARCH（先處理大出血，再 ABC） 為準：肢體截斷的大出血（massive hemorrhage，用 tourniquet）應最優先處理，之後才是氣道、呼吸。所以 (B) 的順序（把 a 排在第四）過時；官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"107-8","year":107,"qnum":8,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部閉合性損傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序 為何呢？","opts":[{"k":"A","t":"肝、脾等實質性器官→胃→十二指腸第一部→空腸→回腸→大腸及它們的系膜→盆腔器官。"},{"k":"B","t":"肝、脾等實質性器官→十二指腸第一部→胃→回腸→空腸→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"同 105-8：腹部鈍傷剖腹探查的傳統順序為肝、脾實質器官 → 橫膈 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸與系膜 → 盆腔器官，所以 (C)。實務上先 packing 控制出血，再處理污染。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-9","year":107,"qnum":9,"topic":"影像FAST","subtopic":"總論／其他","stem":"下列有關 hybrid ER 之敘述何者為非？","opts":[{"k":"A","t":"Hybrid ER 首先於 2011 年日本成立並證實可明顯改善重傷病人之存活率。"},{"k":"B","t":"Hybrid ER 可立即在急診室進行 CT 診斷與快速進行大量出血之控制。"},{"k":"C","t":"Hybrid ER 定義為急診室、緊急 CT 室、介入性放射診斷室與手術之整合。"},{"k":"D","t":"現又有改良旋轉式(rotated-type) Hybrid ER 系統，可將病人及緊急檢查與必要手術於同一床位進行且不須轉床，它並將 C-arm 結合在 CT 旁，此系統並同時有三床備用。"},{"k":"E","t":"台灣目前也已有 Hybrid ER 運作治療重大外傷病患。"}],"answer":"E","expl":"官方答案 (E) 認為「台灣目前已有 Hybrid ER」為錯誤，也就是當時尚無。","outdated":true,"suspect":false,"flagNote":"這是有時效性的題目：近年台灣已有醫院引進或規劃 Hybrid ER，我無法確認目前確切的數量，請以最新資訊為準；官方答案 (E) 不變。(A) 日本於 2011 年成立 Hybrid ER。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"107-10","year":107,"qnum":10,"topic":"休克輸血","subtopic":"總論／其他","stem":"下列有關外傷病患初步處置之敘述何者為非？","opts":[{"k":"A","t":"診療過程中一定要常用手量病患血壓並確認收縮壓在 90 mmHg 以上。"},{"k":"B","t":"遇嚴重出血須輸血時目標為血漿：血小板：紅血球比例為 1:1:2。"},{"k":"C","t":"外傷病人有時進行肛門指診可幫助瞭屆是否有出血(腸道外傷)、前列腺上移(尿道外傷斷裂)，括約肌張力(脊椎外傷)及骨頭碎片(骨盆骨折) 。"},{"k":"D","t":"病人生命徵象不穩定時，通常 CT 檢查會延遲。"},{"k":"E","t":"腹部槍傷時絕對需要立即進行剖腹探勘手術。"}],"answer":"B","expl":"大量輸血應採 plasma : platelet : RBC = 1:1:1（PROPPR，2015），而非 1:1:2，所以 (B) 為非。","outdated":false,"suspect":true,"flagNote":"(E)「腹部槍傷絕對需要立即剖腹」過於絕對：穩定、無腹膜炎的腹部槍傷，部分中心採 selective non-operative management；(E) 也有爭議，官方答案以 (B) 為準。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"107-11","year":107,"qnum":11,"topic":"其他","subtopic":"總論／其他","stem":"下列有關飲酒和外傷之敘述何者為非?","opts":[{"k":"A","t":"美國 21-49 歲人口超過 60%有飲酒習慣。"},{"k":"B","t":"酒精也是一種藥物且與使用劑量相關。"},{"k":"C","t":"美國因車禍死亡者其中 40%與飲酒有關。"},{"k":"D","t":"「啤酒或紅酒等不如烈酒危險」的觀念是對的。"},{"k":"E","t":"大多數人酒駕會受影響之血中酒精濃度 blood alcohol concentration (BAO)為超過 0.05 %/volume。"}],"answer":"D","expl":"酒精種類（啤酒、紅酒、烈酒）所含 ethanol 量相同時危險性相當，認為「啤酒或紅酒較不危險」是錯誤觀念，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-12","year":107,"qnum":12,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"大面積燒傷後因為全身性發炎反應症候群(Systemic Inflammatory Response Syndrome, SIRS)源於發炎細胞釋出大量細胞因子(cytokines)而對生理造成影響，以下何者為非？","opts":[{"k":"A","t":"大面積燒傷後即使沒有吸入性創傷，也會因為SIRS而發生急性呼吸窘迫症候群。"},{"k":"B","t":"大面積燒傷後在沒有燒傷的部位也會發生燒傷後水腫(burn edema)，即是SIRS的結果。"},{"k":"C","t":"大面積燒傷後發生燒傷後水腫是因為輸液急救後所造成的，所以不要輸太多水及及早使用膠體輸液(colloid)而非晶體輸液(crystalloid)就不會發生燒傷水腫了。"},{"k":"D","t":"大面積燒傷後因為燒傷水腫容易造成喉頭水腫而危及呼吸道，所以儘早插管是必須考量的。"},{"k":"E","t":"燒傷水腫主要是微血管管壁孔徑增加造成capillary leakage所造成的。"}],"answer":"C","expl":"燒傷水腫是 SIRS 與微血管通透性增加的結果，不是輸液造成；早期使用 colloid 也無法避免燒傷水腫，所以 (C) 為非。(D) 吸入傷害與頸部水腫可能需早插管。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-13","year":107,"qnum":13,"topic":"總論評分","subtopic":"總論／其他","stem":"對於外傷嚴重度評估的論述以下何者為非？","opts":[{"k":"A","t":"Injury severity score (ISS)是由Baker於1974年提出。"},{"k":"B","t":"台灣對於外傷嚴重度的評估最常使用的是ISS。"},{"k":"C","t":"除了ISS之外，其他的評估方式都不甚理想沒有評估的價值。"},{"k":"D","t":"International classification of disease injury severity score (ICISS) 較ISS有更平滑且相關性更高的死亡率分布。"},{"k":"E","t":"New injury severity score (NISS)與ISS的計算方式相似，NISS是取所有AIS中分數最高的三個平方和，ISS是在各組AIS中取出各組最高的三個分數，再取其平方和。"}],"answer":"C","expl":"同 105-43：ISS 並非唯一合理的評估方式，TRISS、NISS、ICISS 等也有價值，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-14","year":107,"qnum":14,"topic":"影像FAST","subtopic":"總論／其他","stem":"一名 24 歲男性，因交通事故導致腹部鈍傷，轉送至具有良好設備的大型醫院創傷中心。患者血壓 106/50mmHg，心跳速率 90/min，體溫 37℃，意識清醒，可自行呼吸，動脈血氧飽和度 99%。腹部電腦斷層掃描發現脾臟第三級損傷，且有顯影劑溢出(contrast extravasation)。下列處置，何者最適當？","opts":[{"k":"A","t":"直接緊急剖腹手術，行脾臟切除術。"},{"k":"B","t":"持續給予輸液及輸血治療，若無法維持血壓穩定，則行脾臟切除手術。"},{"k":"C","t":"因第三級損傷的非手術療法(non-operative management)失敗率較高，故應行脾臟切除術。"},{"k":"D","t":"安排血管栓塞(angioembolization)止血。"},{"k":"E","t":"緊急剖腹手術，用紗布加壓止血，並留置紗布於出血處。待穩定後再行第二次手術移除紗布。"}],"answer":"D","expl":"血流動力學穩定的 Grade III 脾損傷，CT 見 contrast extravasation，首選 angioembolization，所以 (D)；持續不穩才手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-15","year":107,"qnum":15,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"嚴重外傷的患者，若出現凝血功能異常(coagulopathy)，最重要的處置原則是下列何者？","opts":[{"k":"A","t":"大量輸血以維持血壓。"},{"k":"B","t":"找到出血位置並止血。"},{"k":"C","t":"給予溫毯及烤燈。"},{"k":"D","t":"矯正酸中毒(acidosis)。"},{"k":"E","t":"適度給予鈣離子(calcium)。"}],"answer":"B","expl":"外傷凝血病變（trauma-induced coagulopathy）最重要的處理是找到出血位置並止血，同時避免低體溫、酸中毒與稀釋；單靠輸血或加溫無法解決根本問題，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-16","year":107,"qnum":16,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"年紀增大，生理功能的衰退及組織器官機能的老化，使老年外傷的特點為：","opts":[{"k":"A","t":"外傷治療的進步，使得老年外傷死亡率近年獲得些許的改善和減低。"},{"k":"B","t":"老年人外傷最常造成死亡結果之因素為意外跌倒傷害。"},{"k":"C","t":"老年人的車禍常因酒醉開車、超速發生，往往導致嚴重的擠壓性鈍傷。"},{"k":"D","t":"老年者的嚴重外傷，積極搶救與撤除無效的醫療，兩者原則相互衝突。"},{"k":"E","t":"老年者的外傷以車禍佔最大宗，接著才是意外跌倒。"}],"answer":"A","expl":"老年外傷死亡率近年因照護進步而略為改善，所以 (A)。老年人最常見的機轉是跌倒；老年人車禍不一定因酒駕或超速；積極搶救與撤除無效醫療並不互相衝突（要與病人意願及預後一併考量）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-17","year":107,"qnum":17,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"肋骨骨折早期骨折固定手術(ribs fixation)，依據建議仍有爭議(controversial)，手術固定的好處不包括：","opts":[{"k":"A","t":"縮短呼吸道插管時間。"},{"k":"B","t":"槤拁胸 (flail chest)，減少胸管置放比率。"},{"k":"C","t":"減少加護病房留住時間(ICU stay)。"},{"k":"D","t":"降低肺部感染比例( pulmonary infection rate)。"},{"k":"E","t":"固定手術，減少疼痛。"}],"answer":"B","expl":"同 105-39：肋骨固定可止痛、縮短呼吸器與 ICU 天數、降低肺炎，但不是為了減少胸管放置，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-18","year":107,"qnum":18,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"關於大量輸血協議 (Massive Transfusion Protocol)啟動的 criteria，何者有誤 ?","opts":[{"k":"A","t":"評估血液消耗評分(Assessment of Blood Consumptionscore ; ABC score)包括脈搏大於每分鐘 120 下、收縮壓小於 90 毫米汞柱、FAST 為 postive，以及軀幹穿刺傷；符合任何一項。"},{"k":"B","t":"持續的血流動力學不穩定。"},{"k":"C","t":"活動性出血(active bleeding)需要手術或血管栓塞。"},{"k":"D","t":"在急診處即需要輸血。"},{"k":"E","t":"明顯不受控制的出血(uncontrolled bleeding)。"}],"answer":"A","expl":"ABC score 的四項（HR >120、SBP <90、FAST 陽性、穿刺傷）符合其中 2 項以上才建議啟動 MTP，而不是任何一項，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-19","year":107,"qnum":19,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"關於血液動力學不穩定(hemodynamic unstable)的骨盆骨折之處理原則，下列何者有誤?","opts":[{"k":"A","t":"FAST positive，則先緊急剖腹探查。"},{"k":"B","t":"FAST negative，則作腹膜前填塞 (preperitoneal packing) 及外固定；如仍然血液動力學不穩定，則作動脈栓塞(TAE)。"},{"k":"C","t":"FAST negative，則切 CT 並安排動脈栓塞(TAE)，並且持續輸血至血液動力學穩定。"},{"k":"D","t":"FAST negative，則作作動脈栓塞(TAE)；如仍然血液動力學不穩定，則作腹膜前填塞 (preperitoneal packing) 及外固定。"},{"k":"E","t":"在急診即使用床單固定骨盆。"}],"answer":"C","expl":"血流動力學不穩定的骨盆骨折：先 binder／床單固定；FAST 陽性先處理腹內出血（剖腹）；FAST 陰性則做 preperitoneal packing 或 TAE，不應為了 CT 而延誤，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-20","year":107,"qnum":20,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"下列有關安寧緩和醫療條例之敘述，何者為不適當？(安寧緩和醫療條例)","opts":[{"k":"A","t":"末期病人指罹患嚴重傷病，經醫師診斷認為不可治癒，且有醫學上之證據，近期內病程進行至死亡已不可避免者。"},{"k":"B","t":"心肺復甦術指對臨終、瀕死或無生命徵象之病人，施予體外心臟按壓、心臟電擊之緊急救治行為。"},{"k":"C","t":"維生醫療指用以維持末期病人生命徵象，但無治癒效果，而只能延長其瀕死過程的醫療措施。"},{"k":"D","t":"安寧緩和醫療指為減輕或免除末期病人之生理、心理及靈性痛苦，施予緩解性、支持性之醫療照護，以增進其生活品質。"},{"k":"E","t":"意願人指立意願書選擇安寧緩和醫療或作維生醫療抉擇之人。"}],"answer":"B","expl":"安寧緩和醫療條例對心肺復甦術的定義不只是體外心臟按壓與電擊，還包括氣管內插管、急救藥物注射、人工調頻與人工呼吸等標準急救程序，所以 (B) 不完整，為不適當。法條可能修訂，請以現行條文為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-21","year":107,"qnum":21,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"病人符合下列臨床條件之一，且有預立醫療決定者，醫療機構或醫師得依其預立醫療決定終止、撤除或不施行維持生命治療或人工營養及流體餵養之全部或一部。下列何項狀況不適宜？(病人自主權利法)","opts":[{"k":"A","t":"末期病人。"},{"k":"B","t":"處於不可逆轉之昏迷狀況。"},{"k":"C","t":"中重度失智。"},{"k":"D","t":"永久植物人狀態 。"},{"k":"E","t":"其他經中央主管機關公告之病人疾病狀況或痛苦難以忍受、疾病無法治癒且依當時醫療水準無其他合適解決方法之情形。"}],"answer":"C","expl":"依病人自主權利法，適用條件為：末期病人、不可逆轉昏迷、永久植物人、極重度失智、其他經公告的病況；單純「中重度」失智不在其內（需為極重度），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-22","year":107,"qnum":22,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"病患肝臟嚴重裂傷手術實施損傷控制手術以紗布墊填塞止血時，下列合併症何者最少見？","opts":[{"k":"A","t":"再出血。"},{"k":"B","t":"膽汁羈留腹內。"},{"k":"C","t":"門靜脈肝動脈廔管。"},{"k":"D","t":"菌血症。"},{"k":"E","t":"腹內感染。"}],"answer":"C","expl":"肝臟 packing 的併發症：再出血、膽汁瘀積或 biloma、膿瘍與腹內感染、菌血症；門靜脈與肝動脈的瘻管雖有，但最少見，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-23","year":107,"qnum":23,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"關於多重外傷病人出血性休克時輸血的原則何者為是？","opts":[{"k":"A","t":"多重外傷病人出血性休克輸紅血球標準仍以 Hb10 mg/dl 為準。"},{"k":"B","t":"多重外傷病人出血性休克時其血小板功能一般在正常範圍內。"},{"k":"C","t":"多重外傷病人出血性休克時輸紅血球外尚需考慮輸 FFP 以平衡凝血病變。"},{"k":"D","t":"多重外傷病人出血性休克時血液凝固功能和體溫無關。"},{"k":"E","t":"多重外傷病人出血性休克時輸血的快慢遠比止血與否重要。"}],"answer":"C","expl":"大量出血輸血：紅血球 Hb 10 已不是標準（restrictive 7）；血小板功能下降；低體溫會惡化凝血；止血優先於輸血速度；需同時補充 FFP 與血小板以平衡凝血病變，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-24","year":107,"qnum":24,"topic":"腹部","subtopic":"脾臟","stem":"一位血液動力學正常的10歲女孩經過電腦斷層掃描(CT)後確認第III級(中等嚴重)脾損傷後，進入兒科加護病房(PICU)進行密切觀察。 以下哪項符合緊急開刀的適應症(剖腹術)？","opts":[{"k":"A","t":"抽血發現amylase >200。"},{"k":"B","t":"抽血發現leukocyte:14,000。"},{"k":"C","t":"腹腔外膀胱破裂 (Extraperitoneal bladder rupture) 。"},{"k":"D","t":"在追蹤的CT發現腹腔內游離空氣 (Free intraperitoneal air)。"},{"k":"E","t":"血紅素在 24 小時內由 12 g/dL 掉到 10.9 g/dL。"}],"answer":"D","expl":"兒童 Grade III 脾損傷 NOM 期間，出現腹內游離空氣暗示 hollow viscus injury，需剖腹；amylase 輕度升高、白血球 14,000、extraperitoneal 膀胱破裂（導尿即可）與小幅 Hb 下降（12 → 10.9）都不是立即手術指徵，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-25","year":107,"qnum":25,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術(damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血；布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復; 通過輸注液體和血液恢復正常的心血管狀態以及使用昇壓相關藥物；低溫後殘留凝血病變的矯正反轉；並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation)應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現致命三害(lethal triad)時。"}],"answer":"C","expl":"同 106-43：休克時不做完整吻合重建（damage control 的精神是縮短手術），所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-26","year":107,"qnum":26,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列何種情況不適合進行早期靜脈營養(parenteral nutrition)?","opts":[{"k":"A","t":"無法進行或失敗。"},{"k":"B","t":"需要補足熱量的缺損，但無法由腸道營養完成時。"},{"k":"C","t":"高度營養風險的病人。"},{"k":"D","t":"腸衰竭的病人。"},{"k":"E","t":"高劑量使用升壓劑的病人。"}],"answer":"E","expl":"PN 的使用時機：EN 不可行或失敗、需補足 EN 不足的熱量、高營養風險、腸衰竭；在高劑量升壓劑（血流動力學不穩定）時，應先穩定再考慮營養，不適合早期 PN，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-27","year":107,"qnum":27,"topic":"ICU營養併發症","subtopic":"總論／其他","stem":"外傷重症病人發生 hypovolemic hypernatremia 時下列何種立即處置是正確的?","opts":[{"k":"A","t":"Ringer's solution。"},{"k":"B","t":"D5W。"},{"k":"C","t":"0.22% or 0.47% sodium chloride。"},{"k":"D","t":"free water。"},{"k":"E","t":"concentrating the nutrient formula。"}],"answer":"A","expl":"Hypovolemic hypernatremia 先恢復血容量（isotonic Ringer's／生理食鹽水），之後再補 free water 緩慢降鈉，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-28","year":107,"qnum":28,"topic":"災難院前法規","subtopic":"總論／其他","stem":"下列有關酒駕時呼氣酒精濃度達到多少即違反「刑法」第 185 條之 3 不能安全駕駛罪，處二年以下有期徒刑，得併科 20 萬元以下罰金？","opts":[{"k":"A","t":"0.15mg/L。"},{"k":"B","t":"0.25mg/L。"},{"k":"C","t":"0.55mg/L。"},{"k":"D","t":"0.85mg/L。"},{"k":"E","t":"2.0mg/L。"}],"answer":"B","expl":"依刑法第 185 條之 3，呼氣酒精濃度達每公升 0.25 mg（或血液酒精濃度 0.05%）即屬不能安全駕駛罪，所以 (B)。","outdated":true,"suspect":false,"flagNote":"題幹刑度「二年以下、20 萬以下罰金」為當年條文；據我所知法條已修正加重刑度（約三年以下、30 萬以下罰金），請以現行法條確認；0.25 mg/L 門檻不變。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"107-29","year":107,"qnum":29,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"有關良好的外傷照護下列有關之敘述何者為非？","opts":[{"k":"A","t":"必須有外傷小組啟動機制。"},{"k":"B","t":"必須有完整的外傷登錄。"},{"k":"C","t":"外傷登錄員由醫師兼任會比經過受訓過的專人適任。"},{"k":"D","t":"必須有跨科部的外傷團隊。"},{"k":"E","t":"必須有併發症及死亡病例討論會。"}],"answer":"C","expl":"良好外傷照護需要外傷小組啟動機制、完整外傷登錄（由受訓過的專責登錄員負責，不宜由醫師兼任）、跨科部團隊、併發症及死亡討論會，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-30","year":107,"qnum":30,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"下列有關台灣 2017 年的事故傷害死亡之敘述何者為非？","opts":[{"k":"A","t":"1~24 歲的死亡人口之首位死因。"},{"k":"B","t":"25~44 歲的死亡人口之第二位死因。"},{"k":"C","t":"1 歲以下的死亡人口之第四位死因。"},{"k":"D","t":"與心臟疾病一樣平均年數損失約 13.6 年。"},{"k":"E","t":"各年齡層事故傷害死亡率，以 65 歲以上者為最多。"}],"answer":"D","expl":"此為台灣 2017 年統計資料題：事故傷害是 1–24 歲首位死因；平均損失壽命年數遠高於心臟疾病，所以 (D) 說兩者相同為非。數字細節請以官方統計為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-31","year":107,"qnum":31,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關 thoracotomy 下列何者有誤?","opts":[{"k":"A","t":"只有大約 15％的胸部受傷患者最終需要進行 thoracotomy。"},{"k":"B","t":"Pericardial tamponade, cardiac herniation, cardiac rupture, or a post-traumatic cardiac arrhythmia 可能需要 immediate and emergent thoracotomy。"},{"k":"C","t":"Urgent thoracotomy 是指在受傷後數分鐘至數小時進行緊急胸廓切開術，以控制和管理潛在的危及生命的疾病或防止進一步惡化，受傷或感染的發展。"},{"k":"D","t":"針對要 emergent thoracotomy 病人最好的姿勢是右側臥，以利處理各種位置的胸部損傷。"},{"k":"E","t":"以上內容皆正確。"}],"answer":"D","expl":"Emergent thoracotomy（ED thoracotomy）病人採仰臥，left anterolateral thoracotomy；不是右側臥，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-32","year":107,"qnum":32,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關腹部血管損傷下列何者有誤?","opts":[{"k":"A","t":"abdominal vascular injury 通常依據處置的方式不同分為 zone1~3。"},{"k":"B","t":"針對腹部血管損傷，建議例行操作 abdominal aortography 來看血管損傷的位置與程度，以利開刀評估。"},{"k":"C","t":"Resuscitative endovascular balloon occlusion of the aorta (REBOA) 目前對臨床的應用還很限制，目前針對危急生命的複雜性骨盆腔骨折較有幫忙。"},{"k":"D","t":"Zone II 的位置損傷，處置可能採取保守不開刀觀察，避免出血更難控制。"},{"k":"E","t":"Endovascular technique 也可應用在腹部血管損傷的個案中，但侷限出血量較少時。"}],"answer":"B","expl":"腹部血管損傷依 zone 分類處理；不建議例行 abdominal aortography（耽誤時間）；REBOA 目前主要用在致命性骨盆骨折或腹部出血；Zone II 穩定非擴大血腫可觀察，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-33","year":107,"qnum":33,"topic":"頭部TBI","subtopic":"總論／其他","stem":"一位 65 歲男性病患酒後被人用球棒重擊頭部，送至急診室時 BP：140/75mmHg，HR:78/min，GCS 呈現 E1V2M4，病人外觀看起來有熊貓眼，有淡粉紅色液體從鼻孔及耳朵流出，且病人一直嘔吐，則下列敘述何者不正確？","opts":[{"k":"A","t":"病人可能有顱底骨折。"},{"k":"B","t":"因為意識不清楚，故應先予插管維持呼吸道暢通。"},{"k":"C","t":"因為病人一直嘔吐，故應插鼻胃管(NG tube)做引流。"},{"k":"D","t":"待病人生命徵象穩定且無呼吸道問題時可安排 Brain CT scan。"},{"k":"E","t":"可考慮給予預防性抗生素。"}],"answer":"C","expl":"同 106-25：顱底骨折徵象時禁忌 NG tube，改為 OG tube，所以 (C) 不正確。","outdated":true,"suspect":false,"flagNote":"(E)「可考慮預防性抗生素」：目前證據（如 Cochrane 回顧）不支持顱底骨折常規預防性抗生素；官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"107-34","year":107,"qnum":34,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關 診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"DPL 陽性標準：鈍傷抽出 ≥10 mL 血、RBC ≥100,000/mm³、WBC ≥500/mm³、革蘭染色見細菌、或有腸內容物與膽汁；「RBC ≥500,000」不正確，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-35","year":107,"qnum":35,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"有關於骨盆骨折，下列敘述何者錯誤？","opts":[{"k":"A","t":"若合併休克的話，死亡率會提高不少。"},{"k":"B","t":"常見受傷機轉是車禍、跌倒和墜落。"},{"k":"C","t":"只需要考慮是否合併泌尿系統的傷害，其他腹內臟器如消化系統不會受到影響。"},{"k":"D","t":"初步處理以穩定骨盆為主，可使用 pelvic wrap。"},{"k":"E","t":"若持續出血中，Angiographic embolization 是個可行的止血方法。"}],"answer":"C","expl":"骨盆骨折常合併泌尿道、直腸、小腸與其他腹內器官損傷，所以 (C)「只需要考慮泌尿」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-36","year":107,"qnum":36,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"對於受傷情況嚴重者，初步處理後往往需要加護病房觀察治療，以下敘述何者錯誤？","opts":[{"k":"A","t":"外傷造成的死亡有三大高峰，第三高峰常見傷後幾天至幾週，最常見原因是多重器官衰竭與敗血症。"},{"k":"B","t":"外傷病人常需要大量輸血，記得同時補充凝血因子如新鮮冷凍血漿以免凝血功能異常。"},{"k":"C","t":"急性腎衰竭常見在傷者轉入加護病房後，可能是因為休克、低血容引起。"},{"k":"D","t":"若傷者引發 Acute Respiratory Distress Syndrome(急性呼吸窘迫症候群)，原因可能是嚴重肺挫、大量輸血、胰臟受傷等等造成。"},{"k":"E","t":"斷肢重建後，可能會發生 Reperfusion Injury (再灌流傷害)，低血鉀是常見的表徵。"}],"answer":"E","expl":"再灌流傷害（reperfusion injury）常見表現為 hyperkalemia、代謝性酸中毒與 myoglobinuria，不是低血鉀，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-37","year":107,"qnum":37,"topic":"骨盆泌尿","subtopic":"總論／其他","stem":"四十歲男性自鷹架(四公尺高)跌落，主訴右側腰痛。到院時心律 122/BPM，血壓101/78 mmHg。腹部影像如圖，請問何者處置為非？","opts":[{"k":"A","t":"聯繫血管攝影室，可能需進行栓塞止血。"},{"k":"B","t":"血庫與手術室需準備，病患有出血性休克需開腹之可能。"},{"k":"C","t":"開立口服止痛藥，若無其他部位受傷，可離院於門診追蹤。"},{"k":"D","t":"安排加護病房住院觀察。"},{"k":"E","t":"緊急會診泌尿科，以安排尿路檢查。"}],"answer":"C","expl":"CT 顯示右腎嚴重破裂與大範圍腎周血腫並有顯影劑外滲（我依圖判讀，細節請以原圖為準），屬高等級腎損傷，且心跳快，不可開止痛藥離院，需加護病房觀察，準備 angioembolization 或手術與泌尿科會診，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":["p172-1.jpg"]},{"id":"107-38","year":107,"qnum":38,"topic":"腹部","subtopic":"肝臟","stem":"一位年輕機車騎士因嚴重車禍送至當地區域醫院，外院懷疑有肝臟撕裂傷，因而轉送至您所值班的醫學中心，請問下列何者需最先進行?","opts":[{"k":"A","t":"腹部電腦斷層。"},{"k":"B","t":"快速超音波(FAST) 。"},{"k":"C","t":"腹部血管攝影。"},{"k":"D","t":"立即手術。"},{"k":"E","t":"腹部 X 光。"}],"answer":"B","expl":"懷疑肝裂傷的外傷病人轉入後，床邊最快速、不需搬動的是 FAST，可決定是否有腹內出血與是否需立即手術，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-39","year":107,"qnum":39,"topic":"胸部","subtopic":"總論／其他","stem":"35 歲 男 性 酒 後 與 人 鬥 毆 ， 到 院 時 血 壓 為 8 6 / 4 2 m m H g ， 經 輸 液 後 回 升 至107/72mmHg，自電腦斷層室檢查後，送回急診途中血壓再度下降至 68/52mmHg，以下處置何者最正確？(影像如下)","opts":[{"k":"A","t":"電腦斷層顯示顯影劑漏出(contrast extravasation)，表示病患處於出血狀態，需立即聯繫血管攝影室，安排栓塞止血。"},{"k":"B","t":"由於血壓不穩定，需直接送入手術室開腹止血。"},{"k":"C","t":"立即檢查呼吸道與肺部換氣狀況，並繼續輸血。"},{"k":"D","t":"血壓下降可能是因為頭部可能遭受重擊導致腦幹出血，故需再做腦部電腦斷層。"},{"k":"E","t":"病患目前血壓不穩定，不適合接受手術，故送至加護病房觀察。"}],"answer":"C","expl":"檢查途中血壓再度下降，應重新用 ABC 評估：先查呼吸道與肺部換氣（如 tension pneumothorax）並持續輸血；依題意認為需先處理，所以 (C)。無法逐一確認圖中所見，請以官方答案為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-40","year":107,"qnum":40,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"一名 25 歲之年輕男性與人鬥毆後被送至急診，主訴頸部鈍器重擊，現吞嚥困難。檢傷時生命徵象穩定，檢查發現頸部無開放性傷口，但於右側頸部 Zone 2 有一大範圍皮下血腫。有關此病人之敘述何者最不適當？","opts":[{"k":"A","t":"即使喉鏡檢查(Laryngoscopy)正常，仍應密切觀察病人呼吸道症狀至少 24 小時。"},{"k":"B","t":"若頸部血腫持續擴大，即應視為 neck exploration 的手術適應症。"},{"k":"C","t":"若病人穩定但臨床上懷疑有血管損傷 (vascular injury)， 電腦斷層血管攝影術(CTA)為可靠之高診斷率檢查工具。"},{"k":"D","t":"若 plain film 發現第三頸椎椎體 (C3 vertebral body) fracture，應高度懷疑合併血管損傷 (vascular injury)。"},{"k":"E","t":"在統計上，頸部 Zone 2 鈍傷造成血管損傷 (vascular injury) 的比例較 Zone 1 和Zone 3 高。"}],"answer":"E","expl":"鈍性頸部傷害中，血管損傷（如 carotid dissection）較常在 Zone I 與 Zone III（顱底、頸胸交界），不是 Zone II 最高，所以 (E) 為非。(B) 持續擴大的血腫需手術；(C) CTA 為可靠檢查；(D) C-spine 骨折提示血管傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-41","year":107,"qnum":41,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"一名 29 歲、懷孕 32 周之女性(血型為 Rh 陰性)因腹部鈍傷及右大腿穿刺傷導致大量失血。病患在救護車上被妥善綁上止血帶。送至急診時大腿已止血，但有少量陰道出血。意識清楚、生命徵象皆穩定。有關此病人之敘述何者正確？","opts":[{"k":"A","t":"讓此病人右側躺，可以增加回心血量並提高 cardiac output。"},{"k":"B","t":"根據 ATLS 之出血量分級，失血量應在 total blood volume 的 15%以內，為 Class I hemorrhage。"},{"k":"C","t":"孕期 24 周以上之孕婦應以 continuous fetal heart rate monitoring 評估胎兒情況至少四到六小時。"},{"k":"D","t":"若無急產或需緊急引產/剖腹產之情況，則不須給予 anti-Rh(D) immunoglobulin。"},{"k":"E","t":"破傷風疫苗 tetanus toxoid 禁用於孕婦。"}],"answer":"C","expl":"孕 ≥20–24 週的外傷孕婦即使生命徵象穩定，也應做連續胎心監測至少 4–6 小時（有子宮收縮、陰道出血等需更久），所以 (C)。(A) 孕婦應採左側臥或手動向左推子宮，而非右側臥；(D) Rh 陰性母親有胎母輸血風險，需給 anti-D immunoglobulin；(E) 破傷風疫苗孕婦可用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-42","year":107,"qnum":42,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"一名20 歲之男性因車禍被送至急診。有明顯的右側胸壁變形、大片腹壁瘀血及腹部鼓脹。因胸部X 光片顯示大片右側氣胸，急診醫師已經放入胸管並給予氧氣面罩使用。此時病人生命徵象為心跳 152 下/分、呼吸33 下/分、血壓 72/56 mmHg、體溫 35.7oC、血氧濃度 SpO2 98%。給予 2000ml normal saline fluid challenge 後血壓仍然不穩定，且 SpO2 下降至 92%。下列何者為最優先的處置？","opts":[{"k":"A","t":"建立 definite airway。"},{"k":"B","t":"重照胸部 X 光片以排除胸管功能不好造成的 tension pneumothorax。"},{"k":"C","t":"胸腹部電腦斷層。"},{"k":"D","t":"Diagnostic peritoneal lavage。"},{"k":"E","t":"Laparotomy。"}],"answer":"E","expl":"胸管後仍低血壓且腹部瘀血鼓脹，對 2 L 輸液無反應，為 FAST／腹內出血的非反應者，最優先是 laparotomy，所以 (E)。","outdated":true,"suspect":false,"flagNote":"題幹「2000 mL normal saline fluid challenge」不符合 ATLS 10/11（初始約 1 L 後盡快輸血，避免大量晶體液）；官方答案 (E) 不變。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"107-43","year":107,"qnum":43,"topic":"小兒","subtopic":"總論／其他","stem":"一名 10 個月大的男嬰遭母親之同居人施暴、並從一公尺左右的高度摔下，胸腹部著地。送至急診時全身有多處瘀傷、哭鬧不止。生命徵象為心跳 200 下/分、呼吸 65下/分、血壓 62/44 mmHg、體溫 36.1oC。有關此病人之敘述何者正確？","opts":[{"k":"A","t":"進行嬰幼兒的 trauma primary survey 時，circulation (c) 的評估和穩定應優先於airway (a) 和 breathing and ventilation (b)。"},{"k":"B","t":"此男嬰已進入休克狀態。應立即以 isotonic crystalloids 進行 resuscitation。"},{"k":"C","t":"與成人相比，嬰幼兒較不容易因腹部鈍傷造成肝臟或脾臟損傷。"},{"k":"D","t":"與成人相比，嬰幼兒較不容易因胸部鈍傷造成 tension pneumothorax 及pulmonary contusion。"},{"k":"E","t":"Intravenous (IV) cannulation 失敗時，intraosseous (IO) cannulation 可以迅速建立resuscitation 途徑，但 IO cannula 不可用於輸血。"}],"answer":"B","expl":"10 個月嬰兒心率 200、血壓 62/44 為代償失敗的休克，ATLS 建議先給 20 mL/kg 等張晶體液（最多一次），不穩定則 10 mL/kg pRBC，所以 (B)。(A) 仍是 ABC 順序；(C) 兒童腹部鈍傷肝脾傷較常見；(D) 兒童胸壁較軟，肺挫傷常見；(E) IO 可輸血。懷疑虐童需通報。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-44","year":107,"qnum":44,"topic":"胸部","subtopic":"VATS／ECMO","stem":"一名 10 歲女童因車禍導致胸部鈍傷及呼吸窘迫。胸管放置後引流出乳白色引流液。\n有關此病人之處置何者最不合理？","opts":[{"k":"A","t":"全靜脈營養 TPN。"},{"k":"B","t":"若藥物治療無效，安排胸腔鏡手術治療。"},{"k":"C","t":"從胸管打入硬化劑到肋膜腔。"},{"k":"D","t":"給予高脂肪、高碳水化合物比例的食物。"},{"k":"E","t":"以上處置皆合理。"}],"answer":"D","expl":"胸管引出乳白色液體＝乳糜胸（chylothorax）。處置為低脂（MCT）飲食或 TPN、必要時 octreotide、胸腔鏡手術或胸管打入硬化劑，所以給「高脂肪」食物最不合理，答案 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-45","year":107,"qnum":45,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一名 21 歲男性因上背部遭數發槍擊而送來急診。到院時已呈休克狀態(血壓 60/40 mmHg)且呼吸窘迫。氣管內插管及放入雙側胸管後，胸部 X 光顯示右側肺部已擴張且無積液、但左側仍有大量血胸且左側胸管持續有大量鮮血流出。FAST 發現明顯 pericardial tamponade。此時病人忽然心跳停止。有關此病人之敘述何者最適當？","opts":[{"k":"A","t":"立即啟動體外循環小組，裝上體外循環機(ECMO)後轉送手術室。"},{"k":"B","t":"立即施行 left posterolateral thoracotomy。"},{"k":"C","t":"立即施行 left anterolateral thoracotomy。"},{"k":"D","t":"立即施行 clamshell bilateral thoracotomy。"},{"k":"E","t":"Echo-guided pericardiocentesis。"}],"answer":"C","expl":"上背部槍傷、左側大量血胸、心包填塞且心跳停止，應立即在急診 resuscitative thoracotomy（left anterolateral），可再延伸成 clamshell，所以 (C)。ECMO、心包穿刺或 posterolateral thoracotomy 都不是即時處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-46","year":107,"qnum":46,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"一名 46 歲男性建築工從五公尺的高處跌落，臀部及左大腿著地。送至急診時意識清楚、血壓穩定，主訴下腹部疼痛及雙下肢癱瘓無力。陰莖根部及陰囊有嚴重血腫；\n會陰部有一 10 公分之深層撕裂傷且持續滲血。腹部 X 光發現 pubic synthesis separation 及左側 sacroiliac joint dislocation。此時病人血壓降至 75/48 mmHg 且對resuscitation 無反應。有關此病人之處置何者最不合理？","opts":[{"k":"A","t":"立即綁上 pelvic binder 並安排骨盆骨折內固定手術。"},{"k":"B","t":"Suprapubic cystostomy。"},{"k":"C","t":"施行 pre-peritoneal packing。"},{"k":"D","t":"安排血管攝影，必要時進行 arterial embolization。"},{"k":"E","t":"置入 REBOA (resuscitative endovascular balloon occlusion of the aorta) 到腹主動脈 zone III 進行止血。"}],"answer":"A","expl":"骨盆骨折合併休克且對復甦無反應：先 pelvic binder 穩定，再依情況 pre-peritoneal packing、TAE、REBOA（zone III）與 suprapubic cystostomy（尿道傷時）；不能一開始就做骨盆內固定的確定性手術（失血與時間不允許），所以 (A) 最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-47","year":107,"qnum":47,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"以下哪些關於燒傷病人的處理有誤？","opts":[{"k":"A","t":"燒燙傷後應立即用冷水沖洗。"},{"k":"B","t":"病人送院過程中應使用冰塊來維持傷口的低溫。"},{"k":"C","t":"三級燒傷 TBSA 20%的 60kg 男病人應該在到院後的八小時內給予 2400ml 的液體補充。"},{"k":"D","t":"頸部有環狀全層燒傷的病人應該由下巴到胸骨上切跡做焦痂切開術，深度於fascia layer 上。"},{"k":"E","t":"Inhalation injury 的病人在急診插管後一開始呼吸器的設定，應調整為較快速呼吸頻率 16-20/min 以及適中之 tidal volume (6-8ml/kg)。"}],"answer":"B","expl":"燒傷早期處置：流動冷水沖洗（約 20 分鐘，不要用冰塊，以免低體溫與組織傷害），所以 (B) 錯。(C) Parkland 4 mL × 60 × 20 = 4,800 mL/24h，前 8 小時給一半（2,400 mL）；ATLS 10 起始速率為 2 mL/kg/%TBSA。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-48","year":107,"qnum":48,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"一名 29 歲男性因工安意外遭受高位頸椎 (C2-3) 損傷。轉入加護病房時血壓為 72/40 mmHg。若以 Swan-Ganz catheter 評估此病人的休克情形，下列何者為最合理的測量結果？","opts":[{"k":"A","t":"中心靜脈壓 (CVP) 及肺微血管契壓 (PCWP)下降、心輸出量 (CO) 下降、全身血管阻力 (SVR) 下降、肺動脈氧氣飽和度 (SvO2) 下降。"},{"k":"B","t":"CVP 及 PCWP 上升、CO 下降、SVR 下降、SvO2 下降。"},{"k":"C","t":"CVP 及 PCWP 上升、CO 上升、SVR 下降、SvO2 下降。"},{"k":"D","t":"CVP 及 PCWP 下降、CO 下降、SVR 上升、SvO2 下降。"},{"k":"E","t":"CVP 及 PCWP 下降、CO 上升、SVR 正常、SvO2 下降。"}],"answer":"A","expl":"C2–C3 頸髓傷造成 neurogenic shock：交感神經失去張力，血管擴張（SVR 下降）、靜脈回流減少（CVP／PCWP 下降），且心動過緩使 CO 下降，所以官方答案 (A)。注意先排除出血性休克。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-49","year":107,"qnum":49,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，然而升壓藥的使用為其絕對禁忌症。"},{"k":"D","t":"燒傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"升壓劑不是腸道營養的絕對禁忌症：充分復甦且升壓劑劑量穩定或下降時，可開始低劑量腸道營養，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"107-50","year":107,"qnum":50,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"一嚴重頭部外傷併肋骨骨折患者，在給予了足夠疼痛控制後仍有躁動，導致顱內壓上升，於是決定進一步給予鎮定劑使用。患者有腎功能不全病史。在考慮患者特殊的臨床狀況與照護需求下，下列何者為最適當的選擇：","opts":[{"k":"A","t":"Ketamine。"},{"k":"B","t":"Lorazepam (商品名：Ativan) 。"},{"k":"C","t":"Midazolam (商品名：Dormicum) 。"},{"k":"D","t":"Haloperidol。"},{"k":"E","t":"Propofol。"}],"answer":"E","expl":"嚴重 TBI 躁動需鎮靜時，propofol 起效快、半衰期短、可隨時滴定並做神經學評估，也會降低腦代謝與 ICP，且不依賴腎臟代謝，所以 (E)。Lorazepam、midazolam 易累積，haloperidol 不是標準鎮靜；ketamine 現今已不禁用於 TBI，但本題以 (E) 為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-1","year":108,"qnum":1,"topic":"休克輸血","subtopic":"Lethal triad（致命三角）","stem":"Lethal triad 包括下列哪三項因子？","opts":[{"k":"A","t":"Hypoxia，acidosis，hypothermia。"},{"k":"B","t":"Acidosis，hypothermia，hyponatremia。"},{"k":"C","t":"Hypothermia，coagulopathy，hypoxia。"},{"k":"D","t":"Coagulopathy， acidosis，hypoxia。"},{"k":"E","t":"Hypothermia,，acidosis，coagulopathy。"}],"answer":"E","expl":"Lethal triad：hypothermia、acidosis、coagulopathy，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-2","year":108,"qnum":2,"topic":"災難院前法規","subtopic":"總論／其他","stem":"有關外傷病人到院前之敘述及處置何者最不合理？","opts":[{"k":"A","t":"對頭部外傷且失去意識的患者，目前最新的大型臨床研究顯示由 EMT 在事故現場或運送途中盡早以 RSI 進行氣管內插管對病人之預後較有幫助。"},{"k":"B","t":"若已插上氣管內管，在運送過程中若有搬運病人則應在搬運後以聽診或 end-tidal CO2 監測器確定氣管內管位置。"},{"k":"C","t":"大量出血之病患可在運送途中由受過訓練之 EMT 人員建立 peripheral IV line 並給予基本的靜脈輸液。"},{"k":"D","t":"若 peripheral IV line 建立困難，也可由受過訓練之 EMT 人員建立 interosseous (IO)line。"},{"k":"E","t":"針對四肢大量出血且壓迫止血無效的病患，應由受過訓練之 EMT 人員適當使用止血帶 (tourniquet)。"}],"answer":"A","expl":"到院前頭部外傷由 EMT 以 RSI 插管，大型研究並未顯示改善預後（甚至可能更差），所以 (A) 最不合理。(B) 搬動後需再確認管位；(C)(D)(E) 為標準處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-3","year":108,"qnum":3,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"25 歲男性在工地由二層樓高的地方跌落地面 ，到院時病人意識不清，煩燥不安(agitation)，GCS=7，BP=95/65，HR=122，RR=30，SaO2=85%，左側 breathing sound decreased。經放置氣管內管並由左側第五肋間 needle decompression 後，病人GCS=12，BP=120/80，HR=108，RR=20，SaO2=98%。請問下一步的處理步驟為何？","opts":[{"k":"A","t":"立即做 brain CT。"},{"k":"B","t":"立即做 FAST examination。"},{"k":"C","t":"立即放置左側胸管。"},{"k":"D","t":"立即做 abdominal CT。"},{"k":"E","t":"立即了解受傷機轉(trauma mechanism)。"}],"answer":"C","expl":"張力性氣胸經 needle decompression 後病人好轉，下一步是放置左側胸管（needle 只是暫時處置），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-4","year":108,"qnum":4,"topic":"休克輸血","subtopic":"REBOA","stem":"有關於急診使用 REBOA (resuscitative endovascular balloon occlusion of the aorta) 作為 resuscitation 輔助的敘述，下列何者較適當？","opts":[{"k":"A","t":"欲控制骨盆骨折造成的出血應將 balloon 打在 Zone I descending aorta。"},{"k":"B","t":"欲控制腎臟破裂造成的出血應將 balloon 打在 Zone II descending aorta。"},{"k":"C","t":"欲控制肝臟破裂造成的出血應將 balloon 打在 Zone III descending aorta。"},{"k":"D","t":"脾臟破裂合併胸部穿刺傷者為 REBOA 之 contraindication。"},{"k":"E","t":"腹腔內器官受損合併 pneumoperitoneum 者為 REBOA 之 contraindication。"}],"answer":"D","expl":"REBOA 位置：Zone I（胸降主動脈）用於腹部／後腹腔出血，Zone III（腎動脈以下）用於骨盆與下肢出血；Zone II 為內臟動脈區，避免阻斷。胸部出血（胸部穿刺傷）為 REBOA 禁忌，因阻斷會使近端壓力升高、加重胸內出血，所以官方答案 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-5","year":108,"qnum":5,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"一位外傷病人被送到急診室，呈現昏迷狀態，生命徵候為：血壓 78/58 mmHg，脈搏120/min，呼吸次數 30/min，有關此病人之下列敘述何者為正確？","opts":[{"k":"A","t":"此病人血壓偏低最有可能原因為緊張性氣胸(tension pneumothorax)。"},{"k":"B","t":"立即推病人至電腦斷層掃瞄室掃瞄頭部，找出昏迷之原因。"},{"k":"C","t":"此病人若有出血，其出血量可能超過 1500 ㏄。"},{"k":"D","t":"立即照胸部 X 光排除緊張性氣胸。"},{"k":"E","t":"立即插 CVP(中央靜脈導管)給與乳酸林格液(lactate Ringer)2000 ㏄。"}],"answer":"C","expl":"昏迷、血壓 78/58、脈搏 120 為 Class III（失血 30–40%，約 1,500–2,000 mL）以上的出血性休克表現，所以 (C)。休克要先找出血，不應先做 head CT；不需先放 CVP 灌注 2 L LR（ATLS 10 初始 1 L）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-6","year":108,"qnum":6,"topic":"休克輸血","subtopic":"總論／其他","stem":"男性車禍傷患，經急診診斷骨盆腔骨折、後腹腔出血、脾臟撕裂傷與左側血胸。生命徵象仍不穩定，經急救復甦安排輸血，並通知外科預行緊急手術，下列何者處置最適當？","opts":[{"k":"A","t":"立即輸注乳酸林格液 (Lactate Ringers Solution) 2.0 公升急救。"},{"k":"B","t":"僅用生理食鹽水 (normal saline solution)3.0 公升急救。"},{"k":"C","t":"儘早安排輸血，紅血球濃厚液(Packed RBCs)與血漿(FFP)維持 1: 1。"},{"k":"D","t":"維持血壓在正常值高處，即收縮壓 140 mmHg 之上。"},{"k":"E","t":"聯絡其他醫院安排轉院治療。"}],"answer":"C","expl":"多處出血休克：盡早 balanced transfusion，pRBC：FFP 約 1:1（MTP），不給 2–3 L 晶體液，不追求正常血壓（permissive hypotension，SBP 約 80–90），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-7","year":108,"qnum":7,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"關於外傷病人的輸液及輸血原則，以下敘述何者不當？\n1. 無論生命現象為何，均先給予 1 至 2L 的乳酸林格氏液，不夠再追加。\n2. 外傷病人於急診急救時，因避免 packed RBC 以減少 fluid overload。\n3. 對於穿刺傷病人的給液及輸血，可考慮 permissive hypovolemia 原則，並非血壓越高越好。\n4. 對於穿刺傷病人的給液及輸血，以讓病人保持理想血壓為原則，通常是 140/90 mmHg 左右。","opts":[{"k":"A","t":"2、3。"},{"k":"B","t":"1、2。"},{"k":"C","t":"2、4。"},{"k":"D","t":"1、2、4。"},{"k":"E","t":"2、3、4。"}],"answer":"D","expl":"穿刺傷、大量出血的輸液原則：不給大量晶體液，早輸血，採 permissive hypotension；所以 1（無論如何先給 1–2 L LR）、2（避免 pRBC）、4（維持 140/90）都不當，答案 (D)。","outdated":true,"suspect":false,"flagNote":"選項 1「先給 1–2 L LR 不夠再追加」與 ATLS 10/11 不一致（初始約 1 L，盡快輸血）；官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"108-8","year":108,"qnum":8,"topic":"災難院前法規","subtopic":"總論／其他","stem":"50 歲男性因摩托車事故送到一家小型綜合醫院急診室，該日無外科醫師可提供緊急外傷手術的能力。到院時 GCS=6，心率為 120 次/分，血壓為 88/60 mmHg，經急診室醫師緊急插入氣管內管後，FAST 發現有 abdominal fluid accumulation。在輸入 1000cc的 lactic ringer 後，心率為 100 次/分，血壓為 115/65 mmHg。在準備上救護車轉送至外傷中心時，病人血壓下降至 90/55mmHg 。此時最佳的處理步驟為何？","opts":[{"k":"A","t":"因 FAST(+)，故立即安排做 abdominal CT。"},{"k":"B","t":"因 FAST(+)，故立即在急診室施行 DPL。"},{"k":"C","t":"立即輸血並持續轉院流程。"},{"k":"D","t":"因 GCS=6，故立即安排 Brain CT。"},{"k":"E","t":"以 Shared decision making 的觀念跟病人家屬討論後決定後續處理方。"}],"answer":"C","expl":"基層醫院 FAST 陽性、輸液後血壓再度下降，這是 transient responder，不要在當地做 CT 或 DPL 延誤，應立即輸血並持續轉院流程，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-9","year":108,"qnum":9,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列有關急診室開胸手術(Emergency department thoracotomy)之敘述何者為非？","opts":[{"k":"A","t":"以中路探查鋸開胸骨進入胸腔較容易。"},{"k":"B","t":"若發現心包膜填塞，需打開心包膜減壓。"},{"k":"C","t":"對胸部尖銳物刺傷病患，在急診目睹其心跳停止時，應緊急施行。"},{"k":"D","t":"對 懷 疑 同 時 合 併 腹 腔 內 損 傷 病 患 可 將 胸 主 動 脈 以 血 管 鉗 夾 住 (cross clamp of aorta) 。"},{"k":"E","t":"鈍傷引起的病人，進行急診室開胸手術的搶救比例比穿刺傷更差。"}],"answer":"A","expl":"急診開胸應採 left anterolateral thoracotomy（必要時延伸 clamshell），而非首選 median sternotomy，所以 (A) 為非。(B) 心包填塞需打開心包；(C) 穿刺傷目睹心跳停止是適應症；(D) 可 cross clamp 胸主動脈；(E) 鈍傷預後較差。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-10","year":108,"qnum":10,"topic":"腹部","subtopic":"肝臟","stem":"一位年輕機車騎士因嚴重車禍送至當地區域醫院,外院懷疑有肝臟撕裂傷，因而轉送至您所值班的醫學中心，請問下列何者需最先進行？","opts":[{"k":"A","t":"腹部電腦斷層。"},{"k":"B","t":"快速超音波(FAST)。"},{"k":"C","t":"腹部血管攝影。"},{"k":"D","t":"立即手術。"},{"k":"E","t":"腹部 X 光。"}],"answer":"B","expl":"同 107-38：懷疑肝裂傷轉入，先做床邊 FAST，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-11","year":108,"qnum":11,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"對外傷的初次評估(Primary survey)來說，下列那一項胸腔方面問題較難由臨床症狀及身體檢查診斷，常等到 X 光檢查才診斷出來。","opts":[{"k":"A","t":"張力性氣胸。"},{"k":"B","t":"大量血胸。"},{"k":"C","t":"開放性氣胸。"},{"k":"D","t":"鏈枷胸。"},{"k":"E","t":"鎖骨骨折。"}],"answer":"E","expl":"張力性氣胸、大量血胸、開放性氣胸、flail chest 都能在 primary survey 以理學檢查發現；鎖骨骨折常需 X-ray，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-12","year":108,"qnum":12,"topic":"頭部TBI","subtopic":"創傷後癲癇","stem":"中度頭部外傷的年輕男性，生命徵象穩定，頭部昏迷分數(GCS)E2V3M5=10，兩邊瞳孔等大，各約 3mm; 對光有反射。下列各項治療頭部外傷的處置，那一項最不正確？","opts":[{"k":"A","t":"可使用降腦壓藥物(osmotic diuretic)。"},{"k":"B","t":"維持血壓收縮壓在 110 mmHg 以上，避免低血壓產生休克。"},{"k":"C","t":"如有癲癇發作，可使用抗癲癇藥物。"},{"k":"D","t":"插管使用呼吸器，降低血中二氧化碳濃度 PaCO2<25，可減少腦部水腫。"},{"k":"E","t":"腦壓如有上昇，鑑別上昇原因，針對血塊或腦腫治療。"}],"answer":"D","expl":"中度頭部外傷：避免低血壓與缺氧，必要時使用滲透性利尿劑，癲癇用抗癲癇藥，PaCO2 目標約 35–40 mmHg；預防性過度換氣至 PaCO2 <25 會造成腦血管收縮缺血，所以 (D) 最不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-13","year":108,"qnum":13,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"有關胸部外傷治療， 近年建議儘早使用胸腔鏡輔助手術治療( Vi d e o - a s s i s t e d Thoracoscopic Surgery; VATS)胸部外傷，依據建議手術最大的效益包括：","opts":[{"k":"A","t":"診斷與治療肺部挫傷(pulmonary contusion)。"},{"k":"B","t":"移除胸部血胸或滯流血塊(retained hemothorax)。"},{"k":"C","t":"診斷與治療肋骨骨折。"},{"k":"D","t":"治療胸部大血管出血。"},{"k":"E","t":"診斷橫膈膜疝氣(diaphragmatic herniation)。"}],"answer":"B","expl":"同 105-40：VATS 最大效益是清除 retained hemothorax，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-14","year":108,"qnum":14,"topic":"影像FAST","subtopic":"總論／其他","stem":"一名 21 歲女性，因交通事故導致腹部鈍傷，轉送至具有良好設備的大型醫院創傷中心。\n評估時患者血壓 106/54mmHg，心跳速率 115/min，體溫 36℃，意識清醒，可自行呼吸，動脈血氧飽和度 99%。腹部電腦斷層掃描發現脾臟第四級損傷，且有顯影劑溢出(contrast extravasation)。身為該院外傷團隊的領導者，下列處置或敘述，何者最適當？","opts":[{"k":"A","t":"大量輸液及輸血治療，並給予 tranexamic acid，若能維持甚至提升血壓，則不需要進一步的治療，有較高的機會可自行止血。"},{"k":"B","t":"電腦斷層掃描未見游離氣體(free air)，可排除中空器官破裂的可能性。"},{"k":"C","t":"因第四級損傷的非手術療法(non-operative management)失敗率較高，故應逕行脾臟切除術。"},{"k":"D","t":"盡快安排血管栓塞(angioembolization)止血，同時確保緊急手術房的可用性。"},{"k":"E","t":"緊急剖腹手術，用紗布加壓止血，並留置紗布於出血處。待穩定後再行第二次手術移除紗布。"}],"answer":"D","expl":"血流動力學尚穩定的 Grade IV 脾損傷合併 contrast extravasation，首選 angioembolization，同時準備手術室，所以 (D)。不可只靠輸液期待自行止血；CT 無 free air 不能完全排除中空器官破裂。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-15","year":108,"qnum":15,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"同 107-34：DPL 陽性標準是 RBC ≥100,000/mm³，而非 500,000，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-16","year":108,"qnum":16,"topic":"腹部","subtopic":"肝臟","stem":"關於肝損傷，以下陳述正確的是哪一項？","opts":[{"k":"A","t":"約 5％的創傷入院病人發生肝損傷。"},{"k":"B","t":"第五級肝臟外傷(Grade V liver injury)表示有近肝靜脈傷害(Juxtahepatic venous injuries)包含肝後下腔靜脈及主要肝靜脈傷害(etrohepatic vena cava/central major hepatic veins)。"},{"k":"C","t":"照顧肝臟外傷(liver trauma)的患者，包括高級創傷救命術(ATLS)的進行，最重要的是初步評估，包括注意氣道，呼吸和循環。"},{"k":"D","t":"對於血液動力學穩定的肝臟外傷患者，非手術治療(Nonoperative treatment)已成為大多數創傷中心的標準治療。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"肝損傷的描述：約 5% 外傷入院病人；Grade V 為 juxtahepatic venous injuries；依 ATLS 評估；穩定者 NOM 為標準；所以 (E) 皆正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-17","year":108,"qnum":17,"topic":"骨盆泌尿","subtopic":"總論／其他","stem":"四十歲男性機車失速打滑，會陰部大面積開放性傷口，且持續出血中。到院時心律122/BPM，血壓 101/78 mmHg。相關影像如圖，請問何者處置為非？","opts":[{"k":"A","t":"聯繫血管攝影室，可能需進行栓塞止血。"},{"k":"B","t":"血庫與手術室需準備，病患持續性之外出血有手術之需要。"},{"k":"C","t":"開立口服止痛藥，傷口縫合後，可離院於門診追蹤。"},{"k":"D","t":"安排加護病房住院觀察。"},{"k":"E","t":"緊急會診泌尿科，以安排尿路檢查。"}],"answer":"C","expl":"會陰部大面積開放傷口仍持續出血、心跳快，應準備 angioembolization、手術室與加護病房，並由泌尿科評估尿路，不能開止痛藥縫合後離院，所以 (C) 為非。圖片我未逐項判讀，細節以原圖為準。","outdated":false,"suspect":false,"flagNote":"","images":["p181-1.jpg"]},{"id":"108-18","year":108,"qnum":18,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術(damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血；紗布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復；通過輸注液體和血液恢復正常的心血管狀態以及使用昇壓相關藥物；低溫後殘留凝血病變的矯正反轉；並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation) 應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現”致命三害”(lethal triad)時。"}],"answer":"C","expl":"同 106-43：damage control 在休克時不做完整吻合重建，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-19","year":108,"qnum":19,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"下列對 spinal cord injury 造成 neurologic shock 的敍述何者錯誤？","opts":[{"k":"A","t":"受影響的軀幹會出現 flaccidity 和 loss of reflex 的症狀。"},{"k":"B","t":"Spinal cord injury 的 level 要在 T6 以上。"},{"k":"C","t":"Peripheral blood vessel dilatation。"},{"k":"D","t":"病人會出現 bradycardia and hypotension。"},{"k":"E","t":"以上皆正確。"}],"answer":"A","expl":"Neurogenic shock 是交感張力喪失（T6 以上）造成血管擴張、低血壓、心搏過緩；「軀幹 flaccid 與反射消失」是 spinal shock 的神經學表現，不屬於 neurogenic shock 的血流動力學描述，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-20","year":108,"qnum":20,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"下列五位傷者均是由 EMT 以救護車及擔架送至急診室且皆已套上 neck collar。根據NEXUS low-risk criteria，哪一位可以不需要安排頸部影像學檢查即移除 neck collar？","opts":[{"k":"A","t":"四十歲腳踏車騎士跌落水溝，E4V5M6，生命徵象穩定；右側 tibia shaft 開放性骨折；無 focal neurological signs、無 neck pain/tenderness。"},{"k":"B","t":"十三歲體操選手練單槓時摔落，E4V5M6，生命徵象穩定；腰椎及尾椎挫傷；無 focal neurological signs、無 neck pain/tenderness。"},{"k":"C","t":"五十歲貨車駕駛酒駕自撞橋墩，E3V5M6，生命徵象穩定；無頭部鈍傷，胸部及雙膝鈍傷；無 focal neurological signs、無 neck pain/tenderness。"},{"k":"D","t":"二十歲極限運動玩家自越野機車上摔落，E4V5M6，心跳偏快但血壓穩定；腹部鈍傷且有明顯 peritoneal signs；無 focal neurological signs、無 neck pain/tenderness。"},{"k":"E","t":"七十歲行人遭腳踏車撞倒，E4V5M6，生命徵象穩定；前額 3cm laceration wound；\n無 focal neurological signs、無 neck pain/tenderness。"}],"answer":"B","expl":"NEXUS 低風險條件需要同時符合：無頸部中線壓痛、無 focal neurologic deficit、警覺正常、無中毒、無 distracting injury。A（開放性脛骨骨折）、C（酒駕）、D（腹膜炎）為排除；官方答案 (B)（13 歲體操選手，腰椎與尾椎挫傷）。","outdated":false,"suspect":true,"flagNote":"(E) 70 歲前額撕裂傷也符合 NEXUS 五項（NEXUS 不以年齡排除；年齡 ≥65 是 Canadian C-spine rule 的高風險項），所以 (E) 也可能符合；(B) 的腰尾椎挫傷是否算 distracting injury 也有爭議。官方答案 (B)。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"108-21","year":108,"qnum":21,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"下列有關肢體部位peripheral nerve評估之敘述何者為非？","opts":[{"k":"A","t":"手肘部位受傷，同側小指感覺異常且無法外展，要懷疑尺神經受損。"},{"k":"B","t":"遠端肱骨骨折，且drop wrist垂腕或大拇指無法extension，要懷疑正中神經受損。"},{"k":"C","t":"肩關節脫臼，肩膀外側感覺異常，且Deltoid無力，要懷疑腋神經axillary nerve受損。"},{"k":"D","t":"髖關節後位脫臼，且垂足致腳踝無法背屈，要懷疑坐骨神經sciatica nerve受損。"},{"k":"E","t":"膝關節脫臼或近端腓骨骨折，且外側足背感覺異常，要懷疑腓淺神經superficial peroneal nerve受損。"}],"answer":"B","expl":"垂腕（drop wrist）與拇指無法伸直是 radial nerve 受損（常見於肱骨骨幹或遠端骨折），不是 median nerve，所以 (B) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-22","year":108,"qnum":22,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一名 38 歲男性登山客失足跌落山谷，遲至 24 小時後才獲救。檢傷時發現除呼吸偏快 (28下/分) 以外其餘生命徵象穩定；嗜睡但可喚醒，GCS 為 E3V4M6。檢查發現病人四肢肌肉腫脹、有多處瘀血及鈍傷痕跡，合併多處擦傷及右側第一、第二蹠骨骨折。頭頸和胸腹部皆無明顯傷痕及壓痛。插上導尿管後病人解出茶色尿液。有關此病人之敘述及處置何者最不合理？","opts":[{"k":"A","t":"Arterial blood gas analysis 最有可能的結果是 metabolic acidosis with respiratory compensation。"},{"k":"B","t":"針對此病人的問題，檢驗 myoglobinuria 會比 serum creatinine kinase 敏感性更高。"},{"k":"C","t":"大量 hydration 可能會惡化四肢肌肉腫脹，甚至造成 compartment syndrome。"},{"k":"D","t":"血液中的電解質最有可能的變化是 h y p e r k a l e m i a 、 h y p o c a l c e m i a 及hyperphosphatemia。"},{"k":"E","t":"目前並無明確證據支持鹼化尿液對此病人的腎功能有保護作用。"}],"answer":"B","expl":"橫紋肌溶解症（茶色尿）的診斷以血清 CK 最敏感，myoglobinuria 較不敏感且會很快消失，所以 (B) 最不合理。補充：治療以積極補液維持尿量；鹼化尿液的證據不足。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-23","year":108,"qnum":23,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"大 面 積 燒 傷 後 因 為 全 身 性 發 炎 反 應 症 候 群 (Systemic Inflammatory Response Syndrome, SIRS)源於發炎細胞釋出大量細胞因子 (cytokines)而對生理造成影響，以下何者為非？","opts":[{"k":"A","t":"大面積燒傷雖無吸入性創傷，也會因為SIRS而發生ARDS。"},{"k":"B","t":"大面積燒傷後在沒有燒傷的部位也會發生燒傷後水腫(burn edema)，就是SIRS的結果。"},{"k":"C","t":"大面積燒傷後發生燒傷後水腫是因為輸液急救後所造成的，所以只使用膠體輸液(colloid)就不會發生燒傷水腫了。"},{"k":"D","t":"大面積燒傷後因為燒傷水腫容易造成喉頭水腫而危及呼吸道，所以儘早插管是必須的。"},{"k":"E","t":"燒傷水腫主要是因微血管通透性增加造成capillary leakage。"}],"answer":"C","expl":"同 107-12：燒傷水腫是 SIRS 與微血管通透性增加所致，不是輸液引起；只用 colloid 無法避免，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-24","year":108,"qnum":24,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"一嚴重頭部外傷併肋骨骨折患者，在給予了足夠疼痛控制後仍有躁動，導致顱內壓上升，於是決定進一步給予鎮定劑使用。患者有腎功能不全病史。在考慮患者特殊的臨床狀況與照護需求下，下列何者為最適當的選擇：","opts":[{"k":"A","t":"Ketamine。"},{"k":"B","t":"Lorazepam (商品名：Ativan)。"},{"k":"C","t":"Midazolam (商品名：Dormicum)。"},{"k":"D","t":"Haloperidol。"},{"k":"E","t":"Propofol。"}],"answer":"E","expl":"同 107-50：嚴重 TBI 躁動需鎮靜，且有腎功能不全，propofol 起效快、可滴定、不依賴腎臟排除，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-25","year":108,"qnum":25,"topic":"燒傷環境","subtopic":"低體溫與凍傷","stem":"寒流來襲時一名 60 歲露宿公園的街友於清晨因叫喚不醒而被社工送至急診。病人呈現嚴重低體溫 (30.5oC)，身上無外傷。下列何項檢查結果是這位病人較可能會發生的？\n1. Hematocrit 上升；2. Platelet count 上升；3. Metabolic alkalosis；\n4. Lipase 上升；5. EKG 呈 QT prolong；6. EKG 出現 Osborn J wave","opts":[{"k":"A","t":"1、3、4、5、6。"},{"k":"B","t":"2、3、4、5。"},{"k":"C","t":"3、4、5、6。"},{"k":"D","t":"1、3、6。"},{"k":"E","t":"2、4、5。"}],"answer":"A","expl":"嚴重低體溫常見：hemoconcentration（Hct 上升）、血小板下降（脾臟與肝臟滯留，不是上升）、胰臟炎（lipase 上升）、QT prolong 與 Osborn J wave，所以 2 錯；官方答案 (A) 包含 1、3、4、5、6。","outdated":false,"suspect":true,"flagNote":"其中 3「metabolic alkalosis」存疑：嚴重低體溫通常傾向代謝性或呼吸性酸中毒（乳酸上升、CO2 排出變化），我無法確認官方依據。考試仍以官方答案 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"108-26","year":108,"qnum":26,"topic":"腹部","subtopic":"肝臟","stem":"一名 30 歲男 性病人 因車 禍造 成輕 微 subarachnoid hemorrhage 及 Gr. IV liver laceration。經急診 resuscitation 和 trans-arterial angioembolization 後生命徵象漸趨穩定。住進 ICU 後因併發 abdominal compartment syndrome 而剖腹探查；術中發現肝臟破裂面緩慢滲血﹑但無其他器官傷害。手術醫師決定以紗布填塞腹腔並做 temporary abdominal closure。有關此病人之處置何者最不合理？","opts":[{"k":"A","t":"應嘗試在 24-48 小時內再度進行手術關閉腹壁。"},{"k":"B","t":"此情況下病人之 fluid 和 protein loss 會增加。"},{"k":"C","t":"開腹傷口關閉前不適合給予腸道營養，需給予 TPN 或 PPN 支持。"},{"k":"D","t":"即使病人沒有糖尿病病史，此階段血糖過高仍會增加傷口感染風險。"},{"k":"E","t":"以上處置皆合理。"}],"answer":"C","expl":"Open abdomen（暫時關腹）病人在血流動力學穩定後應儘早給腸道營養，甚至可提高 fascial closure 成功率，所以 (C)「不適合給腸道營養」為不合理。(A) 24–48 小時內再手術；(B) 體液與蛋白質流失增加；(D) 高血糖增加感染。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-27","year":108,"qnum":27,"topic":"腹部","subtopic":"脾臟","stem":"一位血液動力學正常的10歲女孩經過電腦斷層掃描(CT)後確認第III級(中等嚴重)脾損傷後，進入兒科加護病房(PICU)進行密切觀察。 以下哪項符合緊急開刀的適應症(剖腹術)？","opts":[{"k":"A","t":"抽血發現amylase >200。"},{"k":"B","t":"抽血發現leukocyte:14,000。"},{"k":"C","t":"腹腔外膀胱破裂 (Extraperitoneal bladder rupture)。"},{"k":"D","t":"在追蹤的CT發現腹腔內游離空氣 (Free intraperitoneal air)。"},{"k":"E","t":"血紅素在 24 小時內由 12 g/dL 掉到 10.9 g/dL。"}],"answer":"D","expl":"同 107-24：兒童 Grade III 脾損傷 NOM 期間，追蹤 CT 發現腹內游離空氣，提示空腔臟器損傷，需剖腹，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-28","year":108,"qnum":28,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"一名10歲男孩自機車後座跌落。未戴安全帽且左側頭部著地。送至急診時GCS為E3V2M5且非常躁動。為保護呼吸道，現已插上氣管內管。電腦斷層檢查發現左側temporal bone fracture、左側顳葉位置有4cm*0.7cm之epidural hematoma (EDH)及輕微subarachnoid hemorrhage；並未發現midline shift。於急診現場等待神經外科醫師會診時血壓穩定，但GCS迅速惡化為E1VeM4且右側肢體只有M1。下列敘述何者最不合理？","opts":[{"k":"A","t":"有可能是EDH繼續擴大造成左側uncal herniation。"},{"k":"B","t":"可考慮使用hyperventilation將PaCO2降至35-40 mmHg並合併osmoitc diuretics。"},{"k":"C","t":"與其他部位之EDH相比，temporal EDH較少需要考慮手術治療。"},{"k":"D","t":"但此病患之情況已符合hematoma evacuation之indication。"},{"k":"E","t":"若該醫院無法提供手術治療，此情況下應安排轉院。"}],"answer":"C","expl":"顳部 EDH（尤其合併 temporal bone fracture，傷到 middle meningeal artery）進展快，容易造成 uncal herniation，手術指徵較寬鬆；病人 GCS 迅速惡化、對側偏癱，已符合 evacuation 指徵，所以 (C)「較少需要手術」為最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-29","year":108,"qnum":29,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"懷孕的外傷病人當其傷勢惡化時，下列何者最先出現反應？","opts":[{"k":"A","t":"胎兒的心跳。"},{"k":"B","t":"孕婦的心跳。"},{"k":"C","t":"孕婦的意識狀態。"},{"k":"D","t":"孕婦的血壓。"},{"k":"E","t":"孕婦的排尿量。"}],"answer":"A","expl":"孕婦因生理性血容量增加（約 30–50%），出血時為保護胎盤灌流會先減少子宮血流，所以胎兒心跳（胎兒窘迫）常早於母體心跳、血壓與意識變化出現，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-30","year":108,"qnum":30,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"一名25歲、懷孕33周之女性因車禍導致胸腹部鈍傷。送至急診時意識不清、心跳偏快、血壓為71/49 mmHg；有少量陰道出血。有關此病人之敘述何者正確？","opts":[{"k":"A","t":"此孕期之孕婦preload、afterload、heart rate較未懷孕時皆增加。"},{"k":"B","t":"此孕期之孕婦respiratory drive增加；tidal volume及functional residual capacity較未懷孕時皆降低。"},{"k":"C","t":"此孕期之孕婦以continuous fetal heart rate monitoring 評估胎兒較無意義。"},{"k":"D","t":"若惡化至pulseless ventricular tachycardia，電擊器之能量輸出設定較一般成人之去顫能量為低。"},{"k":"E","t":"若惡化至cardiac arrest，一般建議CPCR啟動五分鐘以內完成cesarean delivery，對胎兒有較好的神經學預後。"}],"answer":"E","expl":"孕婦生理：preload 與 HR 增加、afterload 下降；tidal volume 增加、FRC 下降；胎心監測有意義；去顫能量與一般成人相同；心跳停止時應在 4–5 分鐘內完成 perimortem cesarean 以提升母胎預後，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-31","year":108,"qnum":31,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於腹部穿刺傷之處理原則，下列敘述何者錯誤？","opts":[{"k":"A","t":"腹部刀子穿刺傷，血液動力學穩定，沒有瀰漫性腹膜炎，沒有內臟剜出，不必常規手術。"},{"k":"B","t":"腹部槍傷，血液動力學穩定 (hemodynamic stable)，沒有瀰漫性腹膜炎 (diffuse pertonitis)，沒有內臟剜出 (eviceration)，常規必須手術。"},{"k":"C","t":"血液動力學穩定，可使用胸腔鏡或腹腔鏡評估橫隔和腹膜穿刺情況。"},{"k":"D","t":"如要選擇非手術療法，須要做腹部電腦斷層評估或連續臨床檢查。"},{"k":"E","t":"血液動力學不穩定，常規必須手術。"}],"answer":"B","expl":"依官方答案，(B)「穩定的腹部槍傷、無腹膜炎、無內臟脫出，常規必須手術」為錯誤，亦即這類病人可考慮 selective non-operative management（連續臨床觀察或 CT）；穩定的刀傷同理。不穩定則必須手術。此立場與 109-36、110-39、112-7 一致；107-10 的 (E) 則採相反立場（見該題備註）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-32","year":108,"qnum":32,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"依據 2019 年 WTA 的指南 (guideline)，下列關於血液動力學不穩定(hemodynamic unstable) 的骨盆骨折之處理原則，何者最為正確？","opts":[{"k":"A","t":"FAST positive，則先剖腹 (laparotomy)，不需打外固定 (external fixation)。"},{"k":"B","t":"FAST negative，則先剖腹 (laparotomy)；如仍然血液動力學不穩定，則作動脈栓塞(TAE)。"},{"k":"C","t":"FAST negative ， 則 作 腹 膜 前 填 塞 (preperitoneal packing) 及外固定(external fixation)；如仍然血液動力學不穩定，則作動脈栓塞 (TAE)。"},{"k":"D","t":"FAST negative，則作外固定(external fixation)；如仍然血液動力學不穩定，則作動脈栓塞 (TAE)。"},{"k":"E","t":"FAST negative，則作動脈栓塞(TAE)；如仍然血液動力學不穩定，則到加護病房輸血至血液動力學穩定。"}],"answer":"C","expl":"不穩定骨盆骨折、FAST negative：先 pelvic binder／外固定與 preperitoneal packing，若仍不穩定再 TAE；FAST positive 則先處理腹內出血（剖腹），同時固定骨盆，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-33","year":108,"qnum":33,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下列關於胰臟損傷之處理原則，何者有誤？","opts":[{"k":"A","t":"第一級 (grade I) 和第二級 (grade II) 原則上不需手術。"},{"k":"B","t":"如剖腹探查發現胰臟有小於 50% 周長的撕裂傷，沒有胰管損傷的證據，則將其修補後放外部引流 (external drainage) 即可。"},{"k":"C","t":"第三級 (grade III) 行遠端胰臟切除術 (distal pancreatectomy) 並試著保留脾臟。"},{"k":"D","t":"第四級 (grade IV) 行外部引流 (external drainage)。"},{"k":"E","t":"第五級 (grade V)，可能以損害控制 (damage control) 原則行胰臟十二指腸切除術(pancreaticoduodenectomy)。"}],"answer":"B","expl":"同 106-35：Grade I–II 不需手術（引流為主）；無胰管損傷的小撕裂傷不需修補，直接 external drainage，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-34","year":108,"qnum":34,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"30 歲男性，酒後開車撞樹，送達急診時 GCS 為 E1M4V1，SBP 60 mm-Hg；F.A.S.T.發現腹腔內有大量液體積聚。下列敘述何者最為正確？","opts":[{"k":"A","t":"先給予等張性晶質液和輸血，待收縮壓上升至100 mm-Hg時，做腹部電腦斷層看是哪裡在出血，然後找外科醫師緊急開腹。"},{"k":"B","t":"先給予 Voluven 和輸血，待收縮壓上升至100 mm-Hg時，做腹部電腦斷層看是哪裡在出血，然後找外科醫師緊急開腹。"},{"k":"C","t":"先給予輸液和輸血，待收縮壓上升至100 mm-Hg時，找外科醫師緊急開腹。"},{"k":"D","t":"給予輸液和輸血，同時找外科醫師緊急開腹。"},{"k":"E","t":"以上皆正確。"}],"answer":"D","expl":"休克且 FAST 大量腹腔積液、無反應：復甦的同時立即通知外科開腹，不能等血壓回升或先做 CT；不建議用 Voluven（HES 增加腎損傷與凝血病變），所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-35","year":108,"qnum":35,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"下列關於創傷傷患之凝血病變(coagulopathy)敘述何者為非？","opts":[{"k":"A","t":"多重創傷傷患約有 1/4 ~ 1/3 於到達醫院時已有coagulopathy。"},{"k":"B","t":"接受大量輸液復甦者會有coagulopathy。"},{"k":"C","t":"在急診即須開始治療coagulopathy。"},{"k":"D","t":"含澱粉類的代用血漿(如 voluven)會讓coagulopathy更加惡化。"},{"k":"E","t":"單純嚴重腦創傷(traumatic brain injury, TBI)很少大出血，少有coagulopathy。"}],"answer":"E","expl":"創傷凝血病變：約 1/4–1/3 多重創傷病人到院時已有；大量輸液稀釋；HES 惡化凝血；應在急診即開始處理；單純嚴重 TBI 也常出現 coagulopathy（腦組織釋出 tissue factor），並非很少，所以 (E) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-36","year":108,"qnum":36,"topic":"其他","subtopic":"總論／其他","stem":"ICD-10 CM 對於外傷的診斷需包含數個面向才算完整，下列何者敘述最不正確？","opts":[{"k":"A","t":"外傷部位，以解剖部位為主標出損傷的部位。"},{"k":"B","t":"外傷機轉，受傷的原因中以交通運輸最常見。"},{"k":"C","t":"外傷發生初期或後續的併發症並不重要。"},{"k":"D","t":"外傷發生時，受傷人員從事的活動。"},{"k":"E","t":"外傷發生時，特別是車禍中，傷者的血中酒精濃度。"}],"answer":"C","expl":"ICD-10-CM 外傷診斷包含損傷部位、機轉（如交通運輸）、地點、活動，並需記錄初期或後續併發症與血中酒精濃度，所以 (C)「併發症並不重要」為最不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-37","year":108,"qnum":37,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"多重外傷併出血病患，下列敘述何者錯誤？","opts":[{"k":"A","t":"輸液治療給予溫暖的等滲液體，通常初始劑量是成人約 1500-2000ml。"},{"k":"B","t":"Class I 出血時無明顯生理變化。"},{"k":"C","t":"Class II 出血量約佔全身血量 15-30%。"},{"k":"D","t":"Class III 出血時，鹼基評估(Base deficit)約至–6to–10mEq/L。"},{"k":"E","t":"兒童患者尿液輸出期望維持 1mL/kg/hr。"}],"answer":"A","expl":"同 107-2：ATLS 10 成人初始輸液是 1 L，而不是 1.5–2 L，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-38","year":108,"qnum":38,"topic":"ICU營養併發症","subtopic":"總論／其他","stem":"外傷重症病人發生 hypovolemic hypernatremia 時下列何種立即處置是正確的？","opts":[{"k":"A","t":"Ringer's solution。"},{"k":"B","t":"D5W。"},{"k":"C","t":"0.22% or 0.47% sodium chloride。"},{"k":"D","t":"free water。"},{"k":"E","t":"concentrating the nutrient formula。"}],"answer":"A","expl":"同 107-27：hypovolemic hypernatremia 先以 isotonic（Ringer's 或 NS）恢復血容量，再補 free water，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-39","year":108,"qnum":39,"topic":"胸部","subtopic":"橫膈膜損傷","stem":"下列關於 Blunt diaphragmatic rupture 的敘述，何者不合理？","opts":[{"k":"A","t":"較少單獨外傷傷害，最常合併 associated injury，是 hepatic 或 splenic laceration。"},{"k":"B","t":"左側的發生率較右側為高。"},{"k":"C","t":"CXR 顯示 diaphragmatic elevation 或 visceral herniation 到胸腔。"},{"k":"D","t":"皆需手術治療，行 diaphragmatic repair，在 acute phase，可由 laparotomy approach。"},{"k":"E","t":"其合併 cardio-pulmonary dysfunction 的發生，可能與其 increased intra-abdominal pressure 有關。"}],"answer":"A","expl":"同 106-11：鈍性橫膈破裂常合併肝、脾損傷，左側較常見，CXR 可見橫膈抬高或內臟疝入，急性期經腹修補，增加腹壓可造成心肺功能障礙。官方答案指 (A) 為不合理。","outdated":false,"suspect":true,"flagNote":"(A) 的敘述其實與文獻一致，看不出錯誤，答案疑有問題；官方 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"108-40","year":108,"qnum":40,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關於 neck penetrating injury，下列敘述何者為非？","opts":[{"k":"A","t":"Zone II 區域比 Zone I 或 Zone III 區域更容易進行外科介入性治療(surgical intervention)。"},{"k":"B","t":"Zone III 區域因位置靠近 thoracic outlet 血管區，故手術時常需作 median sternotomy 或 clavicle resection。"},{"k":"C","t":"在 Zone I 或 Zone III 區域，arteriography 通常被認為是可被接受的檢查，來檢視大血管是否被傷害。"},{"k":"D","t":"因頸部食道傷害延遲診斷超過 12 小時，其死亡率可高達 17%。"},{"k":"E","t":"用 esophagography 來診斷食道破裂，其敏感度 (sensitivity)約為 70-80%。"}],"answer":"B","expl":"同 106-14：Zone III 為顱底到下頜角，不是靠近 thoracic outlet（那是 Zone I），median sternotomy 或 clavicle resection 屬 Zone I，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-41","year":108,"qnum":41,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，暫不需考量系統性的穩定度(systemic stabilization)。"},{"k":"D","t":"燙傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"腸道營養應在充分復甦、系統穩定（升壓劑穩定或下降）後儘早開始，並非不需考慮穩定度，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-42","year":108,"qnum":42,"topic":"休克輸血","subtopic":"輸血併發症（TRALI 等）","stem":"關於輸血相關急性肺損傷(Transfusion- Related Acute Lung Injury, TRALI)之診斷與治療，何者正確？","opts":[{"k":"A","t":"若 BNP (B-natriuretic peptide) >200 pg/ml，一定可以排除 TRALI。"},{"k":"B","t":"TRALI 因為有肺水腫、高血壓，所以對利尿劑反應佳。"},{"k":"C","t":"TRALI 因為是發炎反應，所以對類固醇效果很好。"},{"k":"D","t":"TRALI 發生率於單一捐血者(single donor)的血小板比隨機捐血者(random donor)血小板高。"},{"k":"E","t":"以上皆正確。"}],"answer":"D","expl":"同 105-7：TRALI 不能單靠 BNP 排除（BNP >200 只是傾向 TACO）；利尿劑與 steroid 都無明確療效；官方答案 (D)：單一捐血者血小板的 TRALI 發生率較隨機捐血者高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-43","year":108,"qnum":43,"topic":"四肢血管骨科","subtopic":"股骨／開放性骨折","stem":"下列有關大腿骨骨折之敘述，何者為非？","opts":[{"k":"A","t":"大腿骨骨折的標準治療為骨髓內釘固定。"},{"k":"B","t":"封閉性大腿骨骨折施行骨髓內釘固定手術，應待生命徵象穩定麻醉危險性較低時方才施行為佳。"},{"k":"C","t":"開放性大腿骨骨折有高感染風險，不建議以骨髓內釘固定。"},{"k":"D","t":"若無其他可能影響生命的外傷，大腿骨骨折骨髓內釘固定手術應該早期施行。"},{"k":"E","t":"老年人的大腿骨骨折常源自跌倒。"}],"answer":"C","expl":"股骨骨折的標準治療為 IM nail；開放性股骨骨折在清創與抗生素後，可用 IM nail（目前有證據支持），不是不建議，所以 (C) 為非。生命徵象不穩定時可先 damage control orthopedics（external fixation）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-44","year":108,"qnum":44,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射4+，兩 側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"老年酗酒者跌倒後四肢無力，上肢肌力（3/5）差於下肢（4/5），合併感覺障礙與反射亢進，符合 central cord syndrome（頸椎退化加過度伸展），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-45","year":108,"qnum":45,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關槍傷的敘述何者為非？","opts":[{"k":"A","t":"槍傷的經過路徑(trajectory)ㄧ般比刀傷更加難以預測。"},{"k":"B","t":"槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。"},{"k":"C","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)可達 90%以上的準確率。"},{"k":"D","t":"治療槍傷的基本原則與刀傷同，仍依高級外傷救命術精神為主。"},{"k":"E","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"}],"answer":"C","expl":"槍傷的彈道常因彈頭翻轉、碎裂與撞擊骨頭而偏折，直線預測並不可靠，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-46","year":108,"qnum":46,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"一般認為外傷是一外科疾病，而從生理病理角度來看，則是一免疫發炎反應。下列相關敘述何者錯誤?","opts":[{"k":"A","t":"這複雜的發炎免疫反應，一開始大多以 hypoinflammatory state 為主，之後可能進展為 hyperinflammatory state。"},{"k":"B","t":"Hypoinflammatory state 時期的主要問題是容易發生感染。"},{"k":"C","t":"發炎免疫低下的狀況並不總是不好的，有時反而保護了患者，避免因過度的壓力反應所導致細胞、器官傷害。"},{"k":"D","t":"可經由胃腸道灌食，來節全身發炎反應，並降低多重器官衰竭的發生率。"},{"k":"E","t":"麩胺酸是一重要的免疫營養，有助於調節免疫發炎反應並促進傷口癒合，建議在創傷或燙傷患者使用。"}],"answer":"A","expl":"同 106-3：創傷後免疫反應先是 hyperinflammation（SIRS），之後才是 hypoinflammatory（CARS），所以 (A) 順序顛倒。","outdated":true,"suspect":false,"flagNote":"(E)「建議使用麩胺酸 glutamine」：近年試驗與營養指引不建議在創傷與重症常規補充靜脈 glutamine；官方答案 (A) 不變。原官方答案維持 (A)，僅供臨床與新版指引對照。","images":[]},{"id":"108-47","year":108,"qnum":47,"topic":"燒傷環境","subtopic":"電擊傷","stem":"電擊外傷(Electrical injury)之敘述，何者有誤？","opts":[{"k":"A","t":"死亡率 3-5%。"},{"k":"B","t":"高電壓電擊的界線定義為 500V~1000V 以上。"},{"k":"C","t":"可發生心室顫動(AF)之電擊電流為 16-20 Ma。"},{"k":"D","t":"電弧(Electrical arc)的瞬間溫度可高達 2500-5000℃。"},{"k":"E","t":"臨床上當注意肌肉溶解造成的急性腎衰竭。"}],"answer":"C","expl":"電擊傷：低頻交流電約 50–100 mA 以上才容易造成 ventricular fibrillation；16–20 mA 為 let-go（無法鬆手）閾值，所以 (C) 錯。高電壓界線約 500–1000 V。注意橫紋肌溶解與腎衰竭。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-48","year":108,"qnum":48,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有關老年外傷病患與一般成年外傷病患的差異，請選出正確者：","opts":[{"k":"A","t":"老年病患生理儲備 physiologic reserve 較為有限，所以休克時的表現會比一般成年人要早，也比較敏感。"},{"k":"B","t":"老年病患對低血氧 Hypoxia 與低容積 Hypovolemia 的忍受度較高，所以心跳與血壓較不容易產生變化。"},{"k":"C","t":"老年病患由於頸椎的退化性變化使得頸部活動性減低，因此頸椎受傷的機率較一般成年人為低。"},{"k":"D","t":"老年病患發生休克時，可能因先前已有的疾病或藥物，而使得血壓與心跳看似仍在「正常」範圍。"},{"k":"E","t":"以上皆不正確。"}],"answer":"D","expl":"老年病人因疾病或藥物（如 beta blocker）、血管硬化，血壓與心跳可能看似正常，掩蓋休克，所以 (D)。(A) 老年人生理儲備差，但休克表現不一定較早出現；(B) 忍受度低；(C) 頸椎受傷機率反而增加。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-49","year":108,"qnum":49,"topic":"顏面頸部","subtopic":"顏面骨折（LeFort、咬合）","stem":"有關顏面骨骨折(facial bone fracture)，何者正確？","opts":[{"k":"A","t":"上頷骨(maxilla)骨折是最常見之顏面骨骨折。"},{"k":"B","t":"顴骨(zygoma)骨折，一般不會有結膜下出血(subconjunctival hemorrhage)之症狀。"},{"k":"C","t":"顴骨(zygoma)骨折，一般不會造成眼眶周圍腫脹瘀青之症狀。"},{"k":"D","t":"一旦有鼻骨骨折，就要開刀治療。"},{"k":"E","t":"若病人顏面外傷後，有咬合不正(malocclusion)之症狀，需懷疑有下頷骨(mandible)骨折。"}],"answer":"E","expl":"顏面外傷後咬合不正需懷疑下頜骨（mandible）或上頜骨骨折，所以 (E)。最常見的顏面骨折是鼻骨；顴骨骨折常合併眼周瘀青與結膜下出血；鼻骨骨折不一定要開刀。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"108-50","year":108,"qnum":50,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"有關外傷小組的敘述何者不正確 ？","opts":[{"k":"A","t":"外傷小組之組成每個醫院可以不同，可隨著醫院的層級、所在地理位置與外傷病患類型來設計。"},{"k":"B","t":"可以規定依病患傷害嚴重度之不同，啟動不同層級之外傷小組。"},{"k":"C","t":"由醫師、護理人員、檢驗放射技術人員聯合組成。"},{"k":"D","t":"外傷急救醫院之外傷小組依賴團隊成員之默契，一般來說不需要文字規定。"},{"k":"E","t":"外傷小組的運作良否直接與病患之預後存活與否相關。"}],"answer":"D","expl":"外傷小組需有明確的書面啟動標準與流程，不能只靠默契，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-1","year":109,"qnum":1,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"下列何者非為目前肋骨骨折固定手術的建議適應症？","opts":[{"k":"A","t":"明顯的胸壁變形 (Significant Chest Wall Deformity)。"},{"k":"B","t":"多處肋骨骨折合併嚴重疼痛 (Multiple ribs fracture with severe pain)。"},{"k":"C","t":"連枷胸合併呼吸衰竭 (Flail chest with respiratory failure)。"},{"k":"D","t":"單純肋骨骨折多於六處 (Non flail type rib fracture more than 6 ribs)。"},{"k":"E","t":"骨癒合不良之肋骨骨折合併疼痛(Pain due to non-union or malunion of rib fractures)。"}],"answer":"D","expl":"SSRF 的建議適應症：flail chest 合併呼吸衰竭、多根骨折合併嚴重疼痛、明顯胸壁變形、骨折不癒合或畸形癒合伴疼痛、脫離呼吸器困難；單純肋骨骨折超過六根並不是單獨的適應症，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-2","year":109,"qnum":2,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"有一個 20 歲男性，右側胸腔遭受槍擊，送至他院時因休克緊急放置氣管內管，經檢查後發現子彈未貫穿，右側氣血胸已放置胸管，電話聯絡後送至貴院急診。至急診後，意識尚算清醒，E3VtM6，SpO2:86%，生命徵象 HR:110，BP:85/60 mmHg，RR:\n25/min。請問到院後應先做甚麼？","opts":[{"k":"A","t":"檢查氣管內管位置。"},{"k":"B","t":"檢查胸管功能。"},{"k":"C","t":"迅速施行超音波 (FAST)。"},{"k":"D","t":"啟動大量輸血機制 (Massive Blood Transfusion Protocol)。"},{"k":"E","t":"緊急會診胸腔外科醫師準備緊急手術 (Trauma Team Activation)。"}],"answer":"A","expl":"轉入時 SpO2 86%（已插管、有胸管），首先要確認氣管內管位置與通氣（DOPE），其次胸管功能，再做 FAST 與啟動 MTP，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-3","year":109,"qnum":3,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"對於 injury prevention 的對策一般有 3E，(1)enforcement and legalization (2)education and behavior change (3)engineering and environmental modification，請問何者是最有效的作為？","opts":[{"k":"A","t":"Enforcement and legalization。"},{"k":"B","t":"Education and behavior change。"},{"k":"C","t":"Engineering and environmental modification。"},{"k":"D","t":"三者皆一樣有效。"},{"k":"E","t":"三者皆無顯著之效。"}],"answer":"B","expl":"官方答案為 (B) Education and behavior change。","outdated":false,"suspect":true,"flagNote":"傷害預防文獻通常認為被動式的 engineering and environmental modification（如安全氣囊、護欄、道路設計）效果最持久，教育與行為改變效果最有限，所以 (C) 似乎比 (B) 更合理；官方答案可能有誤，請依官方答案作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"109-4","year":109,"qnum":4,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"在下列的 AIS 之下，請計算外傷嚴重度分數(injury severity score)，頭部 AIS 為 2 分，臉部 AIS 為 1 分，胸部 AIS 有為 2 分，腹部 AIS 為 3 及 4 分，四肢為 4 分。","opts":[{"k":"A","t":"11。"},{"k":"B","t":"41。"},{"k":"C","t":"10。"},{"k":"D","t":"36。"},{"k":"E","t":"5 。"}],"answer":"D","expl":"ISS：頭頸 2、臉 1、胸 2、腹 4（取最高 4，不是 3+4）、四肢 4；取三個最高區域：腹 4² + 四肢 4² + 頭或胸 2² = 16 + 16 + 4 = 36，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-5","year":109,"qnum":5,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列敘述有關懷孕的外傷患者，何者為非？","opts":[{"k":"A","t":"在懷孕初期不宜使用 X 光檢查。"},{"k":"B","t":"ATLS 流程同非懷孕者。"},{"k":"C","t":"優先治療母親，其次才是胎兒。"},{"k":"D","t":"即使孕婦的血壓正常，胎盤的血液供應可能已經不足。"},{"k":"E","t":"外傷引起胎兒死亡的最主要原因是母親死亡。"}],"answer":"A","expl":"懷孕外傷病人必要的 X 光不應因懷孕而延遲（母親優先，劑量通常遠低於傷害閾值），所以 (A)「不宜使用」為非。(B)(C)(D)(E) 都是正確觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-6","year":109,"qnum":6,"topic":"腹部","subtopic":"脾臟","stem":"一名 32 歲男性，因暴力事件導致腹部鈍傷，由救護車轉送至具有良好設備的大型醫院外傷中心。患者血壓 102/53mmHg，心跳速率 95/min，體溫 36.5℃，意識清醒，可自行呼吸，動脈血氧飽和度 98%。腹部電腦斷層掃描發現脾臟第四級損傷，且有顯影劑溢出(contrast extravasation)。下列處置，何者最適當？","opts":[{"k":"A","t":"持續給予輸液及輸血治療，若無法維持血壓穩定，則行脾臟切除手術。"},{"k":"B","t":"直接緊急剖腹手術，行脾臟切除術。"},{"k":"C","t":"因第四級損傷的非手術療法(non-operative management)失敗率較高，故應行脾臟切除術。"},{"k":"D","t":"緊急剖腹手術，用紗布加壓止血，並留置紗布於出血處。待穩定後再行第二次手術移除紗布。"},{"k":"E","t":"安排血管栓塞(angioembolization)止血，若栓塞止血失敗，或放射科準備時間過久，則逕行緊急手術。"}],"answer":"E","expl":"血流動力學穩定的 Grade IV 脾損傷合併 contrast extravasation，首選 angioembolization，若失敗或放射科延遲則手術，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-7","year":109,"qnum":7,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"下列有關 Surgical airway 的敘述何者為非？\n1.Cricothyroidectomy 宜施行於 6 歲以上兒童。\n2.Cricothyroidectomy 應選用 7 號氣切套管。\n3.Needle cricothyroidotomy 小孩宜使用 12 或 14 號穿刺針。\n4.Needle cricothyroidotomy 氧氣供應至少需 15 L/min。","opts":[{"k":"A","t":"1+2。"},{"k":"B","t":"1+3。"},{"k":"C","t":"2+3。"},{"k":"D","t":"2+4。"},{"k":"E","t":"1+2+3。"}],"answer":"E","expl":"官方答案 (E)＝1、2、3 皆錯。1 錯（surgical cricothyroidotomy 通常用於 ≥12 歲，不是 6 歲）；2 錯（氣切套管要依年齡選小號，不是固定 7 號）；4 氧氣流量 15 L/min 為標準。","outdated":false,"suspect":true,"flagNote":"項 3「小孩 needle cricothyroidotomy 用 12 或 14 號針」據我所知與 ATLS 的說法一致，因此 3 應為正確，答案似乎應為 (A) 1+2；官方答案 (E) 存疑，請以官方為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"109-8","year":109,"qnum":8,"topic":"小兒","subtopic":"小兒輸液復甦（晶體 bolus 容量）","stem":"一幼稚園中班出遊發生車禍，一名小朋友至院時有休克現象，經評估呼吸道及呼吸換氣沒有異常，血壓 100/76 mmHg，心跳 130/min，呼吸 24/min，腹部反彈痛，懷疑有腹內出血，此輸液該如何給較洽當？","opts":[{"k":"A","t":"一次給 2000 ml 等張晶質溶液之後再評估後續的量。"},{"k":"B","t":"每公斤給予 20ml 等張晶質溶液若有必要可再給 1-2 次。"},{"k":"C","t":"給予適當等張晶質溶液後，懷疑有持續出血時應直接給予輸血治療 20 ml/kg。"},{"k":"D","t":"先輸膠質溶液 20ml/Kg 以保持血管內容積量，效果比較好。"},{"k":"E","t":"維持尿量 0.5-1.0 mL/kg/hour。"}],"answer":"B","expl":"兒童腹內出血休克：20 mL/kg 等張晶質溶液，必要時可重複 1–2 次，仍不穩定再輸血 10 mL/kg，所以 (B)。","outdated":true,"suspect":false,"flagNote":"ATLS 10 起建議初始 20 mL/kg 晶體液僅一次，不穩定就盡快輸 pRBC（10 mL/kg），不再多次重複晶體液。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"109-9","year":109,"qnum":9,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"頭部外傷(Traumatic brain injury) 目前處置原則何者正確？","opts":[{"k":"A","t":"不建議使用類固醇 glucocorticoids (steroids)。"},{"k":"B","t":"年輕人(15-49 歲)建議維持收縮壓 ≥ 100 mmHg。"},{"k":"C","t":"嚴重頭部外傷合併低血壓時建議使用甘露醇(Mannitol)。"},{"k":"D","t":"建議例行使用 Prophylactic hyperventilation (pCO2 < 25 mmHg)。"},{"k":"E","t":"早期使用抗癲癇藥物，對於預防晚期外傷後癲癇 lats post-traumatic seizures 是有效的。"}],"answer":"A","expl":"依 CRASH 試驗與 BTF 指引，TBI 不建議使用 corticosteroid（死亡率反而增加），所以 (A)。(B) BTF 第四版建議 15–49 歲及 >70 歲維持 SBP ≥110 mmHg（50–69 歲 ≥100）；(C) 低血壓時不應給甘露醇（利尿會加重低血容）；(D) 不建議預防性過度換氣；(E) 抗癲癇藥只能預防早發性癲癇，不能預防晚發性癲癇。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-10","year":109,"qnum":10,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"頸部外傷評估法中 CCR (The Canadian C-Spine Rules) 敘述何者為非？","opts":[{"k":"A","t":"分三種危險因子來評估: (評估順序為\"高\"→\"低\"→\"運動\")。"},{"k":"B","t":"不適用於下列病患 GCS < 15、生命徵象不穩定、年紀 < 16 歲等。"},{"k":"C","t":"陰性預測值(negative predictive value) 中 The Canadian C-spine rule 高於NEXUS low-risk criteria。"},{"k":"D","t":"高危險因子包含 1.患者大於 70 歲. 2.危險的受傷機轉. 3.有肢體感覺異常。"},{"k":"E","t":"運動功能評估患者是否能夠轉動頸部左右各 45 度。"}],"answer":"D","expl":"Canadian C-spine rule 的高危險因子為：年齡 ≥65 歲、危險機轉、四肢感覺異常，而不是「>70 歲」，所以 (D) 為非。CCR 不適用於 GCS <15、生命徵象不穩定、<16 歲；敏感度高於 NEXUS。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-11","year":109,"qnum":11,"topic":"休克輸血","subtopic":"Tranexamic acid（TXA／transamine）","stem":"外傷導致之休克，多半為出血所引起，外傷出血是創傷初期死亡的主要因素。外傷止血的新觀念，下列敘述那項最正確：","opts":[{"k":"A","t":"局部止血敷料，近年進展快速，但尚無臨床證實，能有效外部傷口止血。"},{"k":"B","t":"止血敷料，如含化學成分殼聚醣(Chitosan:甲殼素 Chitin 聚合物)，產生高熱止血。"},{"k":"C","t":"止血藥物 Tranexamic acid (TXA / transamin)，機轉在增加血液凝血功能。"},{"k":"D","t":"止血敷料，如含高嶺土(kaolin hemostatic agents)，減少溶血，能快速止血。"},{"k":"E","t":"止血藥物，治療外傷使用重組技術生產的血液因子 7a(Recombinant Factor VIIa)，原先針對治療血友病。"}],"answer":"E","expl":"重組活化因子 VIIa（rFVIIa）原本用於血友病（有抑制因子），後來也試用於外傷大量出血，但試驗未證實明確生存益處，不建議常規使用，所以 (E)。TXA 是抗纖維蛋白溶解藥，不是增加凝血功能；kaolin 與 chitosan 敷料已證實可有效止血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-12","year":109,"qnum":12,"topic":"小兒","subtopic":"總論／其他","stem":"三歲幼兒外傷送至急診，逐漸出現呼吸窘迫、神智昏睡時，下列的敘述最不適當的是：","opts":[{"k":"A","t":"幼兒胸部骨質結構尚未完全，縱使沒有肋骨骨折也可能氣胸或血胸。"},{"k":"B","t":"幼兒對張力性氣胸的治療，縱生理結構與成人不同，但治療原則相同。"},{"k":"C","t":"幼兒對張力性氣胸耐受力(tolerable)差，易照成休克。"},{"k":"D","t":"幼兒不考慮使用藥物引導插管(drug-assisted)，應考慮外科氣道切開術。"},{"k":"E","t":"幼兒呼吸靠橫膈運動為主，但對舒醒球呼吸(bag-masker ventilation)效果佳。"}],"answer":"D","expl":"3 歲幼兒呼吸窘迫仍可依 ATLS 做藥物輔助插管（RSI）並預備 surgical airway 作為備案，不是一律考慮外科氣道切開，所以 (D) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-13","year":109,"qnum":13,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"下列對 Emergency department resuscitated thoracotomy 的敍述何者為非?","opts":[{"k":"A","t":"病人經 CPR 超過 15 分鐘後，如果仍沒有 Sign of life，就不應該施行。"},{"k":"B","t":"需要有經驗的外傷醫師(例如 CVS 醫師)在急診室支援。"},{"k":"C","t":"如果懷疑 cardiac tamponade，可在 phrenic nerve 的後側進行 vertical pericardiotomy。"},{"k":"D","t":"如果懷疑 abdominal hemorrhage，可進行 aortic cross clamp。"},{"k":"E","t":"為了施行 pulmonary hilum clamp，在 lysis inferior pulmonary ligment 時，要注意避免下肺靜脈的 injury。"}],"answer":"C","expl":"急診開胸做 pericardiotomy 時，切口應在 phrenic nerve 的「前方」（anterior）做縱向切開，避免傷到 phrenic nerve，所以 (C) 錯。(A) CPR 超過 15 分鐘無 sign of life 不建議開胸（鈍傷）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-14","year":109,"qnum":14,"topic":"骨盆泌尿","subtopic":"腎臟外傷","stem":"24 歲男性因左側 flank stab injury 送到急診室。到院時病人煩燥不安(agitation)，他的BP=88/50 mmHg，HR=128 次/min，RR=28 次/min，在輸入 1000cc 的 Lactated Ringer's solution 後，BP=105/65 mmHg，HR=100 次/min，放 foley 後發現有 150cc 的血尿，FAST 發現左側 splenorenal fossa 有 fluid accumulation。15 分鐘後血壓降為 85/60 mmHg， HR 上升至 120 次/min，此時最佳的處理步驟為何?","opts":[{"k":"A","t":"輪 2U packed red blood cells，並給予 tranexamic acid。"},{"k":"B","t":"安排做 abdominal CT。"},{"k":"C","t":"聯絡放射科醫師進行 angioembolization。"},{"k":"D","t":"聯絡外科醫師進行 exploratory laparotomy。"},{"k":"E","t":"On endotracheal tube，建立 definitive airway。"}],"answer":"D","expl":"左側腰部刀傷、輸液後只是暫時反應，15 分鐘後血壓再度下降，FAST 見 splenorenal 積液，是 transient responder，應立即剖腹，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-15","year":109,"qnum":15,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"25 歲男性在工地由二層樓高的地方跌落地面 ，到院時病人意識不清，GCS=7，BP=95/65，HR=122，RR=30，SaO2=85%，左側 breathing sound decreased。經放置氣管內管並由左側第五肋間 needle decompression 後，病人 GCS=12，BP=120/80，HR=108，RR=20，SaO2=98%。請問下一步的處理步驟為何?","opts":[{"k":"A","t":"立即做 brain CT。"},{"k":"B","t":"立即做 FAST examination。"},{"k":"C","t":"立即放置左側胸管。"},{"k":"D","t":"立即做 abdominal CT。"},{"k":"E","t":"立即了解受傷機轉(trauma mechanism) 。"}],"answer":"C","expl":"同 108-3：needle decompression 後的下一步是置入胸管，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-16","year":109,"qnum":16,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"一位多重外傷病人被送到急診室，呈現昏迷狀態，生命癥候為：血壓 75/50 mmHg，脈搏 140/min，呼吸次數 35/min，有關此病人的情況及處置下列敘述何者為正確？","opts":[{"k":"A","t":"立即推病人至電腦斷層掃瞄室，掃瞄頭部，找出昏迷之原因。"},{"k":"B","t":"立即插 CVP(中央靜脈導管)給與乳酸林格液(Lactated Ringer's solution)2,000 C.C.。"},{"k":"C","t":"此病人若有出血，其出血量可能超過 1,500 C.C.。"},{"k":"D","t":"立即照胸部 X 光，排除緊張性氣胸。"},{"k":"E","t":"此病人血壓偏低，最有可能原因為緊張性氣胸(tension pneumothorax)。"}],"answer":"C","expl":"昏迷、血壓 75/50、脈搏 140、呼吸 35 屬 Class III–IV 出血性休克，失血量可能 >1,500 mL，所以 (C)。休克應先找出血，不應先做 head CT 或單靠 2 L LR（ATLS 10 初始 1 L）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-17","year":109,"qnum":17,"topic":"休克輸血","subtopic":"總論／其他","stem":"有一位 45 歲女性病患，因車禍受傷而送醫急救。到院時血壓 60/30 mmHg，心跳150/min，Glasgow Coma Scale Score 為 10 分，經 primary survey and resuscitation 緊急輸液 2,000C.C 的 Lactated Ringer's solution 及輸血 1,000C.C.後，血壓上升為 70/40 mmHg，腹部超音波顯示腹腔內有大量液體，胸部 X 光顯示兩側沒有血胸或氣胸，雙側瞳孔等大有光反射，則下列何處置較適當？","opts":[{"k":"A","t":"安排腹腔鏡檢查。"},{"k":"B","t":"立刻進行腹部電腦斷層檢查。"},{"k":"C","t":"安排緊急開腹手術。"},{"k":"D","t":"立刻安排血管攝影。"},{"k":"E","t":"立刻做 Diagnostic peritoneal lavage。"}],"answer":"C","expl":"輸液與輸血後血壓仍低，FAST 陽性、胸部 X 光陰性，應緊急剖腹，所以 (C)。腹腔鏡與 CT 不適合不穩定病人。補充：題幹初始 2,000 mL LR 超出現行 ATLS 10/11（約 1 L）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-18","year":109,"qnum":18,"topic":"顏面頸部","subtopic":"總論／其他","stem":"一名 19 歲男性因行車糾紛遭槍擊。EMT 獲報趕至現場時傷患仍坐在駕駛座上，意識清醒、心跳及呼吸偏快但血壓穩定；於左側頸部有一彈孔緩緩滲血。傷患間歇的咳血、但四肢仍可活動且無麻木感。下列處置合者最為適當？","opts":[{"k":"A","t":"傷口以紗布覆蓋，將病人以 sitting position 盡快送至有能力處理之外傷中心，同時要求病患盡量避免咳嗽。"},{"k":"B","t":"傷口以紗布覆蓋，裝上頸圈 (neck collar) 後以長背板 supine position 盡快送至有能力處理之外傷中心，運送同時備好抽痰設備。"},{"k":"C","t":"傷口以防水且不透氣之 occlusive dressing 覆蓋，將病人以 sitting position 盡快送至有能力處理之外傷中心，運送同時備好抽痰設備。"},{"k":"D","t":"傷口以防水且不透氣之 occlusive dressing 覆蓋，裝上頸圈 (neck collar) 後以長背板 supine position 盡快送至有能力處理之外傷中心，運送同時備好抽痰設備。"},{"k":"E","t":"立即於現場放置 larygeal mask airway 穩定病人呼吸道之後再以長背板 supine position 盡快送至有能力處理之外傷中心。"}],"answer":"C","expl":"頸部槍傷、咳血：以不透氣敷料（occlusive dressing，避免空氣栓塞）覆蓋，採坐姿讓病人保護自己氣道，備好抽痰設備，盡快送創傷中心，所以 (C)；穿刺性頸傷不建議常規戴頸圈（可能掩蓋出血）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-19","year":109,"qnum":19,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"不施行心肺復甦術或維生醫療，應符合下列規定，何者為非？(安寧緩和醫療條例)","opts":[{"k":"A","t":"應由二位相關專科醫師診斷確為末期病人。"},{"k":"B","t":"應有意願人簽署之意願書。未成年人無法表達意願時，則應由法定代理人簽署意願書。"},{"k":"C","t":"末期病人無簽署意願書且意識昏迷或無法清楚表達意願時，應由最近親屬簽署同意書代替之。"},{"k":"D","t":"末期病人無簽署意願書且意識昏迷或無法清楚表達意願時，如最近親屬意思表示不一致時，父母之序位先於成年子女、孫子女。"},{"k":"E","t":"無最近親屬者，應經安寧緩和醫療照會後，依末期病人最大利益出具醫囑代替之。"}],"answer":"D","expl":"依安寧緩和醫療條例，最近親屬意思不一致時，依序位順序決定：配偶、成年子女與孫子女、父母…；故父母的序位在成年子女之後，不是先於，所以 (D) 錯。條文曾修訂，請以現行版為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-20","year":109,"qnum":20,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"下列有關心臟死後器官捐贈作業參考規範之敘述，下列何者不適當？(心臟死後器官捐贈作業參考規範)","opts":[{"k":"A","t":"待病人自然心跳停止後，開始進入「5 分鐘的等候觀察期」，須確認病人在此觀察期無再次出現收縮性血壓或心搏性心率，再由主治醫師宣判死亡，並留存相關紀錄文件。"},{"k":"B","t":"若病人為非病死或可疑為非病死者，暫停心臟死後器官捐贈作業。"},{"k":"C","t":"為了減少病人不適及維持捐贈器官功能，可能給予必要之醫療處置，包括鎮靜、止痛藥物、抗凝血劑等。"},{"k":"D","t":"若溫缺血時超過 120 分鐘，若病人或其家屬同意捐贈組織，應續執行組織摘取作業。"},{"k":"E","t":"潛在捐贈者於原先醫療過程中未使用體外循環機器，為維持其器官功能得另行裝置體外循環機器。"}],"answer":"E","expl":"心臟死後器官捐贈作業參考規範：原先醫療過程未使用體外循環（ECMO）者，不得為了維持器官功能而另外裝置，所以 (E) 不適當。依據是官方答案，細節請以現行規範為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-21","year":109,"qnum":21,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術(damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血；紗布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復；通過輸注液體和血液恢復正常的心血管狀態以及使用升壓相關藥物；低溫後殘留凝血病變的矯正反轉；\n並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation)應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現\"致命三害\"(lethal triad)時。"}],"answer":"C","expl":"同 106-43：damage control 時不做完整吻合重建，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-22","year":109,"qnum":22,"topic":"腹部","subtopic":"脾臟","stem":"一名年輕男子因為發生一件汽車車禍之後，被送往一間有一般外科醫生工作的醫院。\n他的 GCS 為 13，抱怨腹痛。他的血壓在到達醫院檢傷分類處時收縮壓為 80 毫米汞柱，但隨著給予靜脈注射輸液 2L 之後增加至 110/70 毫米汞柱。他的心率每分鐘仍然是 120次。 電腦斷層掃描(CT)顯示主動脈損傷和脾深度撕裂傷伴有腹腔內部的大量液體。\nCT 後血壓降至 70 mm Hg。下一步是？","opts":[{"k":"A","t":"使用顯影劑之動脈攝影。"},{"k":"B","t":"轉到下一個外傷中心。"},{"k":"C","t":"剖腹探查手術。"},{"k":"D","t":"持續輸注紅血球厚液(PRBC)直到生命徵象穩定。"},{"k":"E","t":"安排心臟超音波。"}],"answer":"C","expl":"休克經輸液後仍低血壓（transient responder），CT 顯示主動脈損傷與脾深裂傷合併大量腹腔積血，CT 後血壓降到 70，應馬上剖腹，所以 (C)。持續輸血不能解決活動性出血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-23","year":109,"qnum":23,"topic":"腹部","subtopic":"脾臟","stem":"一名 27 歲男學生在球場上被足球直接撞擊腹部之後抱怨持續性左上腹壓痛和左肩痛。\n在急診室評估時病人意識清楚，生命徵象穩定。創傷(FAST)超音波檢查顯示肝腎空間(Morrison pouch)和脾臟凹陷(splenic recess)中有大量明顯的流體。 這個病人最合適的下一步是執行 ?","opts":[{"k":"A","t":"直接剖腹探查手術。"},{"k":"B","t":"診斷性腹腔鏡手術 (diagnostic laparoscopy)。"},{"k":"C","t":"診斷性腹膜灌洗(DPL)。"},{"k":"D","t":"24 小時之後再做一次超音波。"},{"k":"E","t":"靜脈注射顯影劑腹部電腦斷層檢查。"}],"answer":"E","expl":"足球撞擊腹部後，左肩 Kehr sign 且 FAST 陽性，但生命徵象穩定，應做 IV contrast CT 評估肝脾損傷分級，所以 (E)。不穩定才直接剖腹。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-24","year":109,"qnum":24,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"36 歲男性，酒後騎機車自摔，時間不明。送至急診時身上無明顯傷口，意識不清E1V1M4，心跳 155/分，血壓 68/44 mmHg，呼吸急促 32/分。下列處置何者較為不當?\n(24-28 為連鎖題組)","opts":[{"k":"A","t":"急診立即呼叫外傷小組。"},{"k":"B","t":"立即插管維持呼吸道。"},{"k":"C","t":"NS 大量輸液，同時啟動大量輸血指引(Massive transfusion protocol)，緊急叫血輸血pRBC 4U 與 FFP 4U。"},{"k":"D","t":"立即施行緊急頭部電腦斷層檢查，以排除顱內出血。"},{"k":"E","t":"立即施行緊急胸部骨盆 X 光檢查，以排除氣血胸與骨盆骨折。"}],"answer":"D","expl":"休克（SBP 68）且意識不清的 trauma：先 ABC、啟動外傷小組、插管、MTP、胸與骨盆 X 光及 FAST；不應先做頭部 CT，因為病人不穩定，所以 (D) 不恰當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-25","year":109,"qnum":25,"topic":"休克輸血","subtopic":"總論／其他","stem":"經 10 分鐘後外傷小組到達現場，已輸注 NS 1,000 C.C.並開始輸血 pRBC 與 FFP。此時已插管，E1VtM1，心跳 145/分，血壓 76/58 mmHg，呼吸 20/分(呼吸器)。請問下列措施，何者較為不當？","opts":[{"k":"A","t":"確認胸部骨盆 X 光檢查結果。"},{"k":"B","t":"進行腹部超音波檢查，以排除腹腔內出血。"},{"k":"C","t":"檢查四肢是否有明顯長骨骨折，若有應給予適當固定。"},{"k":"D","t":"因不確定低血壓原因，在未確認出血處前，可暫維持血壓在 90-100 mmHg 上下，以避免增加出血量。"},{"k":"E","t":"需避免 NS 過分輸注，以免影響凝血功能。"}],"answer":"D","expl":"疑似 TBI（GCS 3）病人不宜採取 permissive hypotension，因腦灌注壓需維持（BTF 建議 SBP ≥100–110 mmHg）；所以 (D)「暫維持 90–100」較不當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-26","year":109,"qnum":26,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"經輸血後血壓逐漸恢復至 108/76mmHg，同時腹部超音波發現腹腔有大量積液，胸部X 光發現右側多發性肋骨骨折與氣血胸，右膝骨折合併右小腿血循不良。此時下列何者應該最優先施行?","opts":[{"k":"A","t":"放置右側胸管引流氣血胸。"},{"k":"B","t":"進行電腦斷層檢查，應至少檢查頭頸部與腹部。"},{"k":"C","t":"安排開刀房準備手術。"},{"k":"D","t":"安排右下肢血管攝影以確認血循受阻的位置。"},{"k":"E","t":"安排加護病房繼續治療。"}],"answer":"A","expl":"血壓回升後確認右側氣血胸，最優先是放置右側胸管引流（可能快速惡化成 tension，且之後需要正壓），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-27","year":109,"qnum":27,"topic":"腹部","subtopic":"肝臟","stem":"病人進行與一系列檢查後，確認病人有下列外傷: 右側 SDH 併腦水腫，右鎖骨骨折，右側 4~9 肋骨骨折併氣血胸，肝臟裂傷 Gr 4 併大量腹腔內積血，右膝粉碎性骨折併右小腿血循不良。整個過程中血壓雖曾最高回復至 112/80mmHg，但 20 分鐘後又再降至80/52 mmHg。請問此時，下列何種處置需最優先進行?","opts":[{"k":"A","t":"開顱手術清除血塊並放置顱內壓監測。"},{"k":"B","t":"腹部血管攝影與栓塞，以控制肝臟出血。"},{"k":"C","t":"繼續大量輸血，待血壓穩定後進行腹部血管攝影與栓塞。"},{"k":"D","t":"剖腹手術以控制腹腔內出血。"},{"k":"E","t":"右下肢血管攝影以確認血循受阻的位置。"}],"answer":"D","expl":"腹內大量出血（肝 Grade IV）且血壓再度掉到 80/52，是 unstable，應立即剖腹手術控制出血，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-28","year":109,"qnum":28,"topic":"DCS_ACS","subtopic":"Abdominal compartment syndrome（IAP 測量／處置）","stem":"經過開顱手術清除血塊並放置顱內壓監測、右肝動脈結紮並紗塊壓迫止血 (pads packing)、右膝復位與外固定等多科手術後，患者送至加護病房觀察。觀察期間心跳約為 90~100/分，血壓維持 120~130mmHg，體溫逐漸恢復至 37.5C，但腹內壓由術後的14 mmHg，18 mmHg 逐漸上升至 22 mmHg，此時應做何處理?","opts":[{"k":"A","t":"可能腹腔內持續出血，立即回到開刀房再次剖腹探查。"},{"k":"B","t":"可能腹腔內持續出血，安排血管攝影，必要時栓塞治療。"},{"k":"C","t":"可能為休克後腸道腫脹，立即回到開刀房將腹壁打開以減壓。"},{"k":"D","t":"心跳血壓仍然穩定，應確認尿液排出狀況，若無寡尿(oligouria)現象，可以繼續觀察。"},{"k":"E","t":"以上皆非。"}],"answer":"D","expl":"腹內壓由 14 上升至 22 mmHg，但心跳與血壓穩定、尿量正常，沒有新器官衰竭，則只是 intra-abdominal hypertension 而非 ACS（需 IAP >20 且新器官衰竭），可持續觀察並監測，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-29","year":109,"qnum":29,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"創傷病人早期給予營養，下列何者為非?","opts":[{"k":"A","t":"在 24-48 小時內，盡量給予腸道營養(Enteral Nutrition) 。"},{"k":"B","t":"靜脈營養在創傷後立即補充。"},{"k":"C","t":"可給予微量營養 micronutrients。"},{"k":"D","t":"可早期給予 Metoclopramide 促進腸道蠕動。"},{"k":"E","t":"創傷前 48 小時給予 25-70%的靜態能量需(Resting Energy Expenditure，簡稱 REE)的量。"}],"answer":"B","expl":"早期營養：24–48 小時內儘量給腸道營養；不建議創傷後立即給 PN（EN 無法達標時才考慮），所以 (B) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-30","year":109,"qnum":30,"topic":"休克輸血","subtopic":"REBOA","stem":"下列關於急救復甦性主動脈血管內氣球阻斷術(Resuscitative Endovascular Balloon Occlusion of Aorta, REBOA)的敘述何者有誤?","opts":[{"k":"A","t":"可應用在早期暫時無法加壓控制的出血。"},{"k":"B","t":"主動脈可分成ZONE 1,ZONE 2,ZONE 3，此三大區域可皆適用REBOA來控制出血。"},{"k":"C","t":"為避免腹內器官出血，阻斷血流時間不宜過長，盡量控制在30分鐘以內。"},{"k":"D","t":"可能有創傷性腦損傷，內臟缺血及下肢壞死等併發症的風險。"},{"k":"E","t":"可替代開胸手術及主動脈夾鉗來暫時控制出血。"}],"answer":"B","expl":"REBOA 的 Zone 1（胸降主動脈）與 Zone 3（腎動脈以下）可使用，Zone 2（內臟動脈區）為 no-occlusion zone，不適合阻斷，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-31","year":109,"qnum":31,"topic":"災難院前法規","subtopic":"總論／其他","stem":"妥善的到院前處置對於外傷病人後續治療及預後有相當大的幫助。有關到院前處置之敘述下列何者適當？","opts":[{"k":"A","t":"大量出血之病患可在運送途中由受過訓練之 EMT 人員打上 large bore catheter 以盡早開始 resuscitation。"},{"k":"B","t":"針對四肢近端大量出血、無法使用止血帶(tourniquet)的病患，應由受過訓練之EMT 人員進行 vascular ligation 控制出血。"},{"k":"C","t":"若已插上氣管內管，在運送過程中若有搬運病人則應在搬運後仔細觀察氣管內管壁是否有霧氣以確定氣管內管位置。"},{"k":"D","t":"因屬高度侵入性處置且感染風險太高，目前臨床指引不建議由 EMT 人員建立interosseous (IO) line。"},{"k":"E","t":"頭部外傷病患且 GCS 低於 9 分，目前並沒有證據支持由 EMT 在事故現場或運送途中以 RSI 進行氣管內插管可以獲得較佳之預後。"}],"answer":"E","expl":"院前處置：沒有證據支持 EMT 在現場對 GCS <9 的頭部外傷病人以 RSI 插管可獲得較佳預後，所以 (E)。EMT 不做 vascular ligation；氣管內管確認用 capnography 而非只看霧氣；IO 可由 EMT 建立。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-32","year":109,"qnum":32,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"下列病例皆為剛送入急診的 traumatic brain injury 的患者，何者可以不需要安排緊急手術治療？","opts":[{"k":"A","t":"GCS 滿分，電腦斷層顯示 epidural hematoma 約 45ml。"},{"k":"B","t":"GCS E3V4M6，電腦斷層顯示 parietal cerebral hemorrhage 約 15ml。"},{"k":"C","t":"GCS E1VeM4，電腦斷層顯示 depressed temporal skull bone fracture with pneumocephalus。"},{"k":"D","t":"GCS E1VeM4，電腦斷層顯示 cerebellum hemorrhage 約 20ml。"},{"k":"E","t":"GCS E3V4M6，電腦斷層顯示 acute subdural hematoma 約 15mm 厚和病患側 lateral ventricle compression。"}],"answer":"B","expl":"同 109 年各 TBI 手術指徵：EDH >30 mL 需手術；ASDH 厚度 >10 mm 或中線偏移 >5 mm 需手術；depressed skull fracture 與 cerebellar hemorrhage 昏迷且血腫較大需手術；GCS 13 的 parietal ICH 15 mL（<30 mL）可不必緊急手術，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-33","year":109,"qnum":33,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"腹部鈍傷的患者，何種形況可考慮 NOM(Nonoperative management)並優先考慮血管栓塞治療(Angioembolization)?","opts":[{"k":"A","t":"Hemodynamically unstable, FAST (Focused Assessment with Sonography in Trauma)呈現腹內出血。"},{"k":"B","t":"Hemodynamically unstable, abdominal CT 呈現肝臟，脾臟撕裂傷併出現顯影劑滲漏(contrast extravasation)。"},{"k":"C","t":"Hemodynamically stable, abdominal CT 呈現脾臟撕裂傷併有 contrast extravasation。"},{"k":"D","t":"Hemodynamically stable，abdominal CT 呈現肝臟撕裂傷，無明顯 contrast extravasation。"},{"k":"E","t":"Hemodynamically stable，abdominal CT 呈現 hemoperitoneum 但無明顯肝臟脾臟損傷。"}],"answer":"C","expl":"血流動力學穩定的腹部鈍傷，CT 見脾臟 contrast extravasation，可考慮 NOM 並優先 angioembolization，所以 (C)。不穩定者需剖腹；肝裂傷無 blush 者可單純觀察。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-34","year":109,"qnum":34,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部鈍傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序是?","opts":[{"k":"A","t":"肝、脾等實質性器官→大腸及它們的系膜→空腸→回腸→胃→十二指腸第一部→盆腔器。"},{"k":"B","t":"回腸→空腸→肝、脾等實質性器官→十二指腸第一部→胃→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"同 105-8：探查順序為肝、脾實質器官 → 橫隔肌 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸及系膜 → 盆腔器官，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-35","year":109,"qnum":35,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"有關如何處理嚴重肢體傷害與出血的敘述，何者錯誤?","opts":[{"k":"A","t":"控制外傷出血，可以逐步進行，第一步就是直接加壓止血。"},{"k":"B","t":"然後覆蓋敷料，再使用彈性繃帶以適當壓力，將壓力集中在傷口上維持在適當的位置。"},{"k":"C","t":"如果仍然持續出血，請在受傷部位附近的動脈點用力加壓。"},{"k":"D","t":"如果繼續流血，請考慮將止血帶(Touniquet)或氣動式止血帶直接應用，直到止血。"},{"k":"E","t":"氣動止血帶在上肢可能需要 150 毫米汞柱的壓力，在下肢需要 200 毫米汞柱的壓力。"}],"answer":"E","expl":"直接加壓、加壓敷料後仍出血，應直接使用 tourniquet；氣動止血帶壓力通常上肢約 250 mmHg、下肢約 300–400 mmHg（或高於收縮壓 50–100 mmHg）。「上肢 150、下肢 200」不足，所以 (E) 錯。","outdated":true,"suspect":false,"flagNote":"(C)「在近端動脈點用力加壓」的 pressure-point 做法已不再被 ATLS 10 與 TCCC 建議，現行做法是直接加壓失敗就盡早上 tourniquet；官方答案 (E) 不變。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"109-36","year":109,"qnum":36,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於腹部穿刺傷之處理原則，下列敘述何者錯誤?","opts":[{"k":"A","t":"血液動力學不穩定，常規必須手術。"},{"k":"B","t":"腹部槍傷，血液動力學穩定，沒有瀰漫性腹膜炎 (diffuse peritonitis)，沒有內臟剜出 (evisceration)，常規必須手術。"},{"k":"C","t":"腹部刀子穿刺傷，血液動力學穩定，沒有瀰漫性腹膜炎，沒有內臟剜出，不必常規手術。"},{"k":"D","t":"如要選擇非手術療法，需要做腹部電腦斷層評估或系列理學檢查。"},{"k":"E","t":"血液動力學穩定，可使用診斷性腹腔鏡評估橫隔和腹膜穿刺情況。"}],"answer":"B","expl":"依官方答案，(B)「穩定的腹部槍傷、無腹膜炎、無內臟脫出，常規必須手術」為錯誤，亦即這類病人可考慮 selective non-operative management；不穩定則必須手術。此立場與 108-31、110-39、112-7 一致；107-10 的 (E) 則採相反立場（見該題備註）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-37","year":109,"qnum":37,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列關於血液動力學不穩定 (hemodynamic unstable) 的骨盆骨折之處理原則，何者最為正確?","opts":[{"k":"A","t":"FAST negative，則先剖腹 (laparotomy)；如仍然血液動力學不穩定，則作動脈栓塞 (TAE)。"},{"k":"B","t":"FAST negative，則作動脈栓塞；如仍然血液動力學不穩定，則到加護病房輸血至血液動力學穩定。"},{"k":"C","t":"FAST negative，則作外固定 (external fixation)；如仍然血液動力學不穩定，則作動脈栓塞。"},{"k":"D","t":"FAST negative，則作腹膜前填塞 (preperitoneal packing) 及外固定；如仍然血液動力學不穩定，則作動脈栓塞。"},{"k":"E","t":"FAST positive，則先剖腹，不需打外固定。"}],"answer":"D","expl":"同 107-19、108-32：不穩定骨盆骨折，FAST negative：先 preperitoneal packing 及外固定，仍不穩定再 TAE，所以 (D)。FAST positive 先剖腹，同時固定骨盆。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-38","year":109,"qnum":38,"topic":"休克輸血","subtopic":"Lethal triad（致命三角）","stem":"Lethal triad 包括下列哪三項因子？","opts":[{"k":"A","t":"Hypoxia，acidosis，hypothermia。"},{"k":"B","t":"Acidosis，hypothermia，hyponatremia。"},{"k":"C","t":"Hypothermia，coagulopathy，hypoxia。"},{"k":"D","t":"Coagulopathy， acidosis，hypoxia。"},{"k":"E","t":"Hypothermia,，acidosis，coagulopathy。"}],"answer":"E","expl":"同 108-1：Lethal triad 為 hypothermia、acidosis、coagulopathy，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-39","year":109,"qnum":39,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"關於外傷病人的輸液及輸血原則，以下敘述何者不當？\n1.無論生命現象為何，均先給予 1 至 2L 的乳酸林格氏液，不夠再追加。\n2.外傷病人於急診急救時，因避免 packed RBC 以減少 fluid overload。\n3.對於穿刺傷病人的給液及輸血，可考慮 permissive hypovolemia 原則，並非血壓越高越好。\n4.對於穿刺傷病人的給液及輸血，以讓病人保持理想血壓為原則，通常是 140/90 mmHg 左右。","opts":[{"k":"A","t":"2、3。"},{"k":"B","t":"1、2。"},{"k":"C","t":"2、4。"},{"k":"D","t":"1、2、4。"},{"k":"E","t":"2、3、4。"}],"answer":"D","expl":"同 108-7：穿刺傷、大量出血不給大量晶體液，早輸血並採 permissive hypotension；1、2、4 皆不當，所以 (D)。","outdated":true,"suspect":false,"flagNote":"選項 1「無論如何先給 1–2 L LR」不符合 ATLS 10/11（初始約 1 L，並盡早輸血）；官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"109-40","year":109,"qnum":40,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"同 107-34：DPL 陽性標準為 RBC ≥100,000/mm³（鈍傷），而非 500,000，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-41","year":109,"qnum":41,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"下列有關肢體部位peripheral nerve評估之敘述何者為非？","opts":[{"k":"A","t":"手肘部位受傷，同側小指感覺異常且無法外展，要懷疑尺神經受損。"},{"k":"B","t":"遠端肱骨骨折，且drop wrist垂腕或大拇指無法extension，要懷疑正中神經受損。"},{"k":"C","t":"肩關節脫臼，肩膀外側感覺異常，且Deltoid無力，要懷疑腋神經axillary nerve受損。"},{"k":"D","t":"髖關節後位脫臼，且垂足致腳踝無法背屈，要懷疑坐骨神經sciatica nerve受損。"},{"k":"E","t":"膝關節脫臼或近端腓骨骨折，且外側足背感覺異常，要懷疑腓淺神經superficial peroneal nerve受損。"}],"answer":"B","expl":"同 108-21：垂腕與拇指無法伸直是 radial nerve 受損，而非 median nerve，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-42","year":109,"qnum":42,"topic":"骨盆泌尿","subtopic":"總論／其他","stem":"四十歲男性機車失速打滑，會陰部大面積開放性傷口，且持續出血中。到院時心律122/BPM，血壓 101/78 mmHg。相關影像如圖，請問何者處置為非？","opts":[{"k":"A","t":"聯繫血管攝影室，可能需進行栓塞止血。"},{"k":"B","t":"血庫與手術室需準備，病患持續性之外出血有手術之需要。"},{"k":"C","t":"開立口服止痛藥，傷口縫合後，可離院於門診追蹤。"},{"k":"D","t":"安排加護病房住院觀察。"},{"k":"E","t":"緊急會診泌尿科，以安排尿路檢查。"}],"answer":"C","expl":"同 108-17：會陰部大面積開放傷口持續出血，需準備血管攝影、手術室與 ICU，並會診泌尿科，不能縫合後離院，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":["p200-1.jpg"]},{"id":"109-43","year":109,"qnum":43,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一名 38 歲男性登山客失足跌落山谷，遲至 24 小時後才獲救。檢傷時發現除呼吸偏快(28 下/分) 以外其餘生命徵象穩定；嗜睡但可喚醒，GCS 為 E3V4M6。檢查發現病人四肢肌肉腫脹、有多處瘀血及鈍傷痕跡，合併多處擦傷及右側第一、第二蹠骨骨折。\n頭頸和胸腹部皆無明顯傷痕及壓痛。插上導尿管後病人解出茶色尿液。有關此病人之敘述及處置何者最不合理？","opts":[{"k":"A","t":"Arterial blood gas analysis 最有可能的結果是 metabolic acidosis with respiratory compensation。"},{"k":"B","t":"針對此病人的問題，檢驗 myoglobinuria 會比 serum creatinine kinase 敏感性更高。"},{"k":"C","t":"大量 hydration 可能會惡化四肢肌肉腫脹，甚至造成 compartment syndrome。"},{"k":"D","t":"血液中的電解質最有可能的變化是 hyperkalemia、hypocalcemia 及 hyperphosphatemia。"},{"k":"E","t":"目前並無明確證據支持鹼化尿液對此病人的腎功能有保護作用。"}],"answer":"B","expl":"同 108-22：橫紋肌溶解症以血清 CK 為最敏感的診斷指標，myoglobinuria 較不敏感，所以 (B) 最不合理。鹼化尿液無明確證據。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-44","year":109,"qnum":44,"topic":"燒傷環境","subtopic":"低體溫與凍傷","stem":"寒流來襲時一名 60 歲露宿公園的街友於清晨因叫喚不醒而被社工送至急診。病人呈現嚴重低體溫 (30.5oC)，身上無外傷。下列何項檢查結果是這位病人較可能會發生的？\n1.Hematocrit 上升；2.Platelet count 上升；3.Metabolic alkalosis；4.Lipase 上升；5. EKG呈 QT prolong；6.EKG 出現 Osborn J wave。","opts":[{"k":"A","t":"1、3、4、5、6。"},{"k":"B","t":"2、3、4、5。"},{"k":"C","t":"3、4、5、6。"},{"k":"D","t":"1、3、6。"},{"k":"E","t":"2、4、5。"}],"answer":"A","expl":"同 108-25：嚴重低體溫常見 Hct 上升（hemoconcentration）、血小板下降、lipase 上升（胰臟炎）、QT prolong 與 Osborn J wave；官方答案 (A) 包含 1、3、4、5、6。","outdated":false,"suspect":true,"flagNote":"其中 3「metabolic alkalosis」存疑：嚴重低體溫通常傾向酸中毒（乳酸上升、通氣變化），我無法確認官方依據。考試仍以官方答案 (A) 為準。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"109-45","year":109,"qnum":45,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"一名10歲男孩自機車後座跌落。未戴安全帽且左側頭部著地。送至急診時GCS為E3V2M5且非常躁動。為保護呼吸道，現已插上氣管內管。電腦斷層檢查發現左側temporal bone fracture、左側顳葉位置有4cm*0.7cm之epidural hematoma (EDH)及輕微subarachnoid hemorrhage；並未發現midline shift。於急診現場等待神經外科醫師會診時血壓穩定，但GCS迅速惡化為E1VeM4且右側肢體只有M1。下列敘述何者最不合理？","opts":[{"k":"A","t":"有可能是EDH繼續擴大造成左側uncal herniation。"},{"k":"B","t":"可考慮使用hyperventilation將PaCO2降至35-40 mmHg並合併osmoitc diuretics。"},{"k":"C","t":"與其他部位之EDH相比，temporal EDH較少需要考慮手術治療。"},{"k":"D","t":"但此病患之情況已符合hematoma evacuation之indication。"},{"k":"E","t":"若該醫院無法提供手術治療，此情況下應安排轉院。"}],"answer":"C","expl":"同 108-28：顳部 EDH 容易造成 uncal herniation，病人 GCS 快速惡化並出現對側偏癱已符合手術指徵，所以 (C)「較少需要手術」最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-46","year":109,"qnum":46,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"一名25歲、懷孕33周之女性因車禍導致胸腹部鈍傷。送至急診時意識不清、心跳偏快、血壓為71/49 mmHg；有少量陰道出血。有關此病人之敘述何者正確？","opts":[{"k":"A","t":"此孕期之孕婦preload、afterload、heart rate較未懷孕時皆增加。"},{"k":"B","t":"此孕期之孕婦respiratory drive增加；tidal volume及functional residual capacity較未懷孕時皆降低。"},{"k":"C","t":"此孕期之孕婦以continuous fetal heart rate monitoring 評估胎兒較無意義。"},{"k":"D","t":"若惡化至pulseless ventricular tachycardia，電擊器之能量輸出設定較一般成人之去顫能量為低。"},{"k":"E","t":"若惡化至cardiac arrest，一般建議CPCR啟動五分鐘以內完成cesarean delivery，對胎兒有較好的神經學預後。"}],"answer":"E","expl":"同 108-30：孕婦心跳停止若復甦無效，應在 4–5 分鐘內進行 perimortem cesarean，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-47","year":109,"qnum":47,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"依據 2019 年 WTA 的指南 (guideline)，下列關於血液動力學不穩定(hemodynamic unstable) 的骨盆骨折之處理原則，何者最為正確？","opts":[{"k":"A","t":"FAST positive，則先剖腹 (laparotomy)，不需打外固定 (external fixation)。"},{"k":"B","t":"FAST negative，則先剖腹 (laparotomy)；如仍然血液動力學不穩定，則作動脈栓塞(TAE)。"},{"k":"C","t":"FAST negative ， 則 作 腹 膜 前 填 塞 (preperitoneal packing) 及外固定(external fixation)；如仍然血液動力學不穩定，則作動脈栓塞 (TAE)。"},{"k":"D","t":"FAST negative，則作外固定(external fixation)；如仍然血液動力學不穩定，則作動脈栓塞 (TAE)。"},{"k":"E","t":"FAST negative，則作動脈栓塞(TAE)；如仍然血液動力學不穩定，則到加護病房輸血至血液動力學穩定。"}],"answer":"C","expl":"同 108-32：不穩定骨盆骨折，FAST negative：preperitoneal packing 與外固定，再 TAE，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-48","year":109,"qnum":48,"topic":"其他","subtopic":"總論／其他","stem":"ICD-10 CM 對於外傷的診斷需包含數個面向才算完整，下列何者敘述最不正確？","opts":[{"k":"A","t":"外傷部位，以解剖部位為主標出損傷的部位。"},{"k":"B","t":"外傷機轉，受傷的原因中以交通運輸最常見。"},{"k":"C","t":"外傷發生初期或後續的併發症並不重要。"},{"k":"D","t":"外傷發生時，受傷人員從事的活動。"},{"k":"E","t":"外傷發生時，特別是車禍中，傷者的血中酒精濃度。"}],"answer":"C","expl":"同 108-36：ICD-10-CM 外傷診斷包含部位、機轉、地點、活動與併發症，所以 (C)「併發症並不重要」為最不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-49","year":109,"qnum":49,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關於 neck penetrating injury，下列敘述何者為非？","opts":[{"k":"A","t":"Zone II 區域比 Zone I 或 Zone III 區域更容易進行外科介入性治療(surgical intervention)。"},{"k":"B","t":"Zone III 區域因位置靠近 thoracic outlet 血管區，故手術時常需作 median sternotomy或 clavicle resection。"},{"k":"C","t":"在 Zone I 或 Zone III 區域，arteriography 通常被認為是可被接受的檢查，來檢視大血管是否被傷害。"},{"k":"D","t":"因頸部食道傷害延遲診斷超過 12 小時，其死亡率可高達 17%。"},{"k":"E","t":"用 esophagography 來診斷食道破裂，其敏感度 (sensitivity)約為 70-80%。"}],"answer":"B","expl":"同 106-14：median sternotomy 與 clavicle resection 屬 Zone I，不是 Zone III，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"109-50","year":109,"qnum":50,"topic":"災難院前法規","subtopic":"外傷登錄／品質改善／外傷小組","stem":"有關外傷小組的敘述何者不正確 ？","opts":[{"k":"A","t":"外傷小組之組成每個醫院可以不同，可隨著醫院的層級、所在地理位置與外傷病患類型來設計。"},{"k":"B","t":"可以規定依病患傷害嚴重度之不同，啟動不同層級之外傷小組。"},{"k":"C","t":"由醫師、護理人員、檢驗放射技術人員聯合組成。"},{"k":"D","t":"外傷急救醫院之外傷小組依賴團隊成員之默契，一般來說不需要文字規定。"},{"k":"E","t":"外傷小組的運作良否直接與病患之預後存活與否相關。"}],"answer":"D","expl":"同 108-50：外傷小組需有書面啟動標準與流程，不能只靠默契，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-1","year":110,"qnum":1,"topic":"氣道","subtopic":"總論／其他","stem":"Transtracheal jet 充氣設施適用於解除哪一種危急情況?","opts":[{"k":"A","t":"心包填塞。"},{"k":"B","t":"肺栓塞。"},{"k":"C","t":"張力性氣胸。"},{"k":"D","t":"上呼吸道阻塞。"},{"k":"E","t":"吸入性肺炎。"}],"answer":"D","expl":"Transtracheal jet insufflation（針刺環甲膜加噴射通氣）用於上呼吸道阻塞、無法插管且無法通氣時的緊急氣道，所以 (D)。它不能解除心包填塞或張力性氣胸。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-2","year":110,"qnum":2,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"某外傷病人的 AIS 如下：頭頸部 AIS 為 2 分，臉部 AIS 為 1 分，胸部 AIS 有為 2 分，腹部 AIS 為 3 及 4 分，四肢為 4 分。請計算其外傷嚴重度分數(injury severity score)","opts":[{"k":"A","t":"11。"},{"k":"B","t":"41。"},{"k":"C","t":"10。"},{"k":"D","t":"36。"},{"k":"E","t":"5 。"}],"answer":"D","expl":"同 109-4：ISS 取頭頸、臉、胸、腹、四肢、體表六區各區最高分，取最高三區平方和：腹 4² + 四肢 4² + 頭頸或胸 2² = 16 + 16 + 4 = 36，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-3","year":110,"qnum":3,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"面對腹部實質器官(solid organs)鈍傷的處置，下列敘述何者並不適當?","opts":[{"k":"A","t":"腹部電腦斷層掃描為重要的檢查評估工具。"},{"k":"B","t":"是否採用非手術療法的最重要指標是器官損傷評分(injury scale)等級。"},{"k":"C","t":"非手術療法(non-operative management)已成為主要治療選擇。"},{"k":"D","t":"當受傷的器官有 active bleeding 時，目前已有許多 trauma centers 採用血管栓塞(angioembolization)做為第一步的止血治療。"},{"k":"E","t":"肝臟與脾臟是最常見的腹部實質器官損傷部位。"}],"answer":"B","expl":"腹部實質器官鈍傷是否 NOM，最重要的是血流動力學是否穩定，而不是器官損傷分級（Grade 高低只供參考），所以 (B) 不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-4","year":110,"qnum":4,"topic":"腹部","subtopic":"脾臟","stem":"一名 40 歲男性，因暴力事件導致腹部鈍傷，由救護車轉送至具有良好設備的大型醫院外傷中心。患者到院時血壓 103/56mmHg，心跳速率 98/min，體溫 36.4℃，意識清醒，可自行呼吸，動脈血氧飽和度 98%。腹部電腦斷層掃描發現脾臟第四級損傷，且有顯影劑溢出(contrast extravasation)。下列處置，何者最適當?","opts":[{"k":"A","t":"持續給予輸液及輸血治療，若無法維持血壓穩定，則行脾臟切除手術。"},{"k":"B","t":"直接緊急剖腹手術，行脾臟切除術。"},{"k":"C","t":"因第四級損傷的非手術療法(non-operative management)失敗率較高，故應行脾臟切除術。"},{"k":"D","t":"緊急剖腹手術，用紗布加壓止血，並留置紗布於出血處。待穩定後再行第二次手術移除紗布。"},{"k":"E","t":"安排血管栓塞(angioembolization)止血，若栓塞止血失敗，或放射科準備時間過久，則逕行緊急手術。"}],"answer":"E","expl":"同 109-6：穩定的 Grade IV 脾損傷合併 contrast extravasation，首選 angioembolization，若失敗或延遲則手術，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-5","year":110,"qnum":5,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"嚴重外傷的患者，若出現凝血功能異常(coagulopathy)，最重要的處置原則是下列何者?","opts":[{"k":"A","t":"大量輸血以維持血壓。"},{"k":"B","t":"適度給予 tranexamic acid。"},{"k":"C","t":"矯正酸中毒(acidosis)。"},{"k":"D","t":"給予溫毯及烤燈。"},{"k":"E","t":"找到出血位置並止血。"}],"answer":"E","expl":"外傷凝血病變最重要的是找到並控制出血來源，TXA、矯正酸中毒與保暖都是輔助，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-6","year":110,"qnum":6,"topic":"休克輸血","subtopic":"總論／其他","stem":"下列有關輸液治療下列何者正確?","opts":[{"k":"A","t":"Lactated Ringer’s pH 值約 5.5。"},{"k":"B","t":"Normal Saline 接近生理 pH 約 7.4。"},{"k":"C","t":"少量 Hypertonic saline (eg, 3%, 5%, and 7.5%)用於急救手術治療中，相對較少發生ARDS 等併發症。"},{"k":"D","t":"相對於 Albumin 比 Saline 於外傷急救中能提供更好的預後。"},{"k":"E","t":"針對具有穩定血壓外傷病患，到院前給予 2 公升比 1 公升輸液能提供更好的預後。"}],"answer":"C","expl":"LR pH 約 6.5、NS pH 約 5.0（兩者都偏酸，並非接近 7.4）；SAFE 試驗顯示 albumin 與 saline 存活相近，TBI 次群反而較差；到院前 2 L 並不優於 1 L。官方答案 (C) 認為小量高張生理食鹽水較少引起 ARDS 等併發症；但 ROC 試驗未顯示高張液可提升存活，因此臨床並不常規使用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-7","year":110,"qnum":7,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"預立醫療決定書之敘述何者錯誤?","opts":[{"k":"A","t":"適用對象除了在判定末期病人外，包含「不可逆轉之昏迷、永久植物人、極重度失智、其他經中央主管機關公告之重症」。"},{"k":"B","t":"自主權利法概念上等同安樂死。"},{"k":"C","t":"可以選擇接受、拒絕或撤除「維持生命治療、人工營養及流體餵養」的醫療照護選項。"},{"k":"D","t":"「預立醫療照護諮商」是自費門診。"},{"k":"E","t":"執行需經兩位相關專科醫師確診及緩和團隊兩次照會。"}],"answer":"B","expl":"病人自主權利法不等同安樂死：病人可預立醫療決定，拒絕或撤除維持生命治療與人工營養及流體餵養，並不是主動結束生命，所以 (B) 錯。適用對象為末期、不可逆昏迷、永久植物人、極重度失智及其他公告重症。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-8","year":110,"qnum":8,"topic":"腹部","subtopic":"脾臟","stem":"有關 Blunt spleen injury 在加護病房中之治療及觀察下列敘述何者為是?\n1.Grade IV 及 Grade V 之 injury, 大部分可以 Nonoperative management 治療成功。\n2.Pediatric blunt spleen injury ( > 6 y/o), 因較無 post splenectomy overwhelming sepsis之疑慮，由於小孩之 spleen capsule 較厚, 故以手術治療為主。\n3.Spleen angioembolization( SAE), 可做為 Nonoperative management 輔助治療。\n4.Spleen angioembolization( SAE), material 之選擇, gelfoam 優於 coil, 且較不易造成 post procedure bleeding.\n5.Spleen partial infarction 是做完 SAE 後常見之 complication.","opts":[{"k":"A","t":"1,2,3,4。"},{"k":"B","t":"3,4。"},{"k":"C","t":"4,5。"},{"k":"D","t":"3,5。"},{"k":"E","t":"2,4。"}],"answer":"D","expl":"脾損傷：SAE 可作為 NOM 的輔助，常見併發症之一是 partial splenic infarction，所以 3 與 5 正確，答案 (D)。1（Grade IV/V 大多 NOM 成功）不對；兒童脾損傷仍以 NOM 為主；SAE 材料的優劣不是 gelfoam 優於 coil 的結論。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-9","year":110,"qnum":9,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"骨盆骨折(pelvic fracture)常形成大量後腹腔血腫(retroperitoneal hematoma)， 造成出血性休克甚至死亡，因此對於骨盆骨折病人出血的認知是很重要的，下列何種敘述是不對的?","opts":[{"k":"A","t":"後骨盆骨折比前骨盆骨折更易流血。"},{"k":"B","t":"後骨盆骨折常因垂直推擠造成(vertical shear mechanism)。"},{"k":"C","t":"垂直推擠時常造成 inferior gluteal artery 傷害。"},{"k":"D","t":"骨盆骨折失血量和骨折嚴重度有關。"},{"k":"E","t":"具有臨床意義的動脈傷害的比率約為 20%，骨盆骨折的機轉包含前後推擠、側邊推擠、垂直推擠與混合機轉，都會造成出血死亡。"}],"answer":"C","expl":"後骨盆骨折（vertical shear）常傷到 superior gluteal artery（經 greater sciatic notch），而非 inferior gluteal artery，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-10","year":110,"qnum":10,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"嚴重外傷懷孕婦女抵達急救室後，臉色蒼白，血壓 100/75mmHg. 心跳 120/min.，GCS:12，腹部明顯懷孕，觸診子宮胎位正常，醫療記錄與家屬證實已懷孕 30 週，下列敘述那項最正確：","opts":[{"k":"A","t":"應予 100%氧氣補充，股靜脈(femoral veins)兩條大口徑輸液管線。"},{"k":"B","t":"背板頸圈保護脊椎，維持 30 度右側傾斜躺姿(30o left lateral position)或左側墊高(title)。"},{"k":"C","t":"如懷孕婦女心肺血流動力停止，母親急需心肺復甦(CPR)，此時急救小組應維持右側傾斜躺姿，以有效胸部心臟按壓。"},{"k":"D","t":"母親(CPR)如無恢復自主循環，懷孕胎兒>32 週才考慮臨終剖腹產。建議應在四分鐘內開始，胎兒分娩應在剖腹產後五分鐘內完成。"},{"k":"E","t":"在外傷母親發生低血容量性心臟驟停時，胎兒已經經歷了長時間的缺氧，在此情境ATLS 不主張臨終剖腹產(perimortem caesarian section)。"}],"answer":"E","expl":"官方答案為 (E)：認為 ATLS 在低容積性心臟驟停時不主張 perimortem cesarean。","outdated":false,"suspect":true,"flagNote":"此答案與本題庫其他年度矛盾：99-44、105-23、106-46、108-30 的官方答案都主張孕婦心跳停止、復甦無效時，應在 4–5 分鐘內進行 perimortem cesarean。另外 (B)「30 度右側傾斜躺姿 (30° left lateral position)」文字自相矛盾，可能是正確選項（應為左側傾斜）。此題官方答案疑有誤，請依官方作答。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"110-11","year":110,"qnum":11,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"台灣事故傷害(即創傷)死亡人數近卅年的趨勢，下列何者最正確?","opts":[{"k":"A","t":"交通事故死亡逐年減少的趨勢，但近五年小幅振盪起伏。"},{"k":"B","t":"男性事故傷害死亡率為女性 5 倍以上。"},{"k":"C","t":"外傷死亡為 40 歲以下死亡原因的第六名。"},{"k":"D","t":"108 年事故傷害(即創傷)死亡人數，占台灣十大死因統計第五位。"},{"k":"E","t":"以死亡率來比較，107 年比 77 年減少不到一半。"}],"answer":"A","expl":"台灣事故傷害死亡趨勢：交通事故死亡長期下降，近年小幅振盪，所以 (A)。男性死亡率約為女性 2–3 倍；外傷為 40 歲以下死因前幾名（非第六）；數字細節請以衛福部統計為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-12","year":110,"qnum":12,"topic":"休克輸血","subtopic":"總論／其他","stem":"有一位 40 歲女性病患，因車禍受傷而送醫急救。到院時血壓 60/30 mmHg，心跳 150/min，Glasgow Coma Scale Score 為 11 分，經 primary survey and resuscitation 緊急輸液 2,000C.C 的 Ringer’s lactate 及輸血 1,000C.C.後，血壓上升為 70/40 mmHg，腹部超音波顯示腹腔內有大量液體，胸部 X 光顯示兩側沒有血胸或氣胸，雙側瞳孔等大有光反射，則下列何處置較適當?","opts":[{"k":"A","t":"安排給予升壓劑。"},{"k":"B","t":"立刻進行腹部電腦斷層檢查。"},{"k":"C","t":"安排緊急開腹手術。"},{"k":"D","t":"立刻安排血管攝影。"},{"k":"E","t":"立刻做 Diagnostic peritoneal lavage。"}],"answer":"C","expl":"同 109-17：輸液與輸血後血壓仍低、FAST 陽性、胸部 X 光陰性，應緊急剖腹，所以 (C)。題幹初始 2,000 mL LR 超出現行 ATLS 10/11（約 1 L）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-13","year":110,"qnum":13,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"一名 35 歲男性工人工作時腹部遭鋼筋穿刺導致大量失血及。送至急診時意識清醒；生命徵象為心跳 150 下/分、呼吸 28 下/分、血壓 80/48 mmHg、體溫 35.8oC。理學檢查發現腹部相當脹。有關此病人之敘述何者最為合理?","opts":[{"k":"A","t":"應立即以 FAST 檢查排除腹部 hollow organ perforation。"},{"k":"B","t":"若沒有 pneumoperitoneum，基本上可排除 hollow organ perforation。"},{"k":"C","t":"也可以考慮以 diagnostic peritoneal lavage 排除 hollow organ perforation。"},{"k":"D","t":"若有 pneumoperitoneum 且病人為 transient responder to resuscitation，應安排angioembolization 止血後再剖腹探查。"},{"k":"E","t":"即使 resuscitation 後血行動力學穩定，此病人仍應盡速安排剖腹探查手術。"}],"answer":"E","expl":"腹部穿刺傷（鋼筋貫穿）合併休克，不論復甦後是否穩定，都應盡速剖腹探查，所以 (E)。FAST 不能排除空腔臟器穿孔；沒有 pneumoperitoneum 也不能排除。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-14","year":110,"qnum":14,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"根據現有之臨床指引及臨床研究證據，下列哪一位病患適合在急診現場放置 REBOA (Resuscitative Endovascular Balloon Occlusion of the Aorta) 且最可能獲得 survival benefit?","opts":[{"k":"A","t":"三十歲健康男性腹部及右胸近距離槍傷，十分鐘內即上救護車送醫，現於檢傷發現血壓量不到。"},{"k":"B","t":"二十歲健康男性頭部鈍傷及左胸穿刺傷，電腦斷層發現雙側大腦大面積腦出血及cardiac temponade；於電腦斷層室送回急診的途中失去生命徵象。"},{"k":"C","t":"六十歲男性，有高血壓及 6 公分腹主動脈瘤；因腹部鈍傷造成腹主動脈瘤破裂，低血容性休克，現於急診現場 resuscitation。"},{"k":"D","t":"五十歲男性，肝硬化及凝血功能異常；左胸穿刺傷合併大量氣血胸，胸管置入後流出 1800ml 鮮血。對 resuscitation 無反應逐漸失去生命徵象。"},{"k":"E","t":"十八歲健康女性嚴重骨盆骨折合併大量骨盆腔出血；在等候血管栓塞時進展至低血容性休克而後失去意識。"}],"answer":"E","expl":"REBOA（Zone III 或 Zone I）最適合不能由壓迫控制的腹部或骨盆出血，如嚴重骨盆骨折合併休克，所以 (E)。胸部出血（槍傷、胸管大量出血）與頭部出血病人不適合。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-15","year":110,"qnum":15,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"不施行心肺復甦術或維生醫療，應符合下列規定，何者為非?","opts":[{"k":"A","t":"應由二位相關專科醫師診斷確為末期病人。"},{"k":"B","t":"應有意願人簽署之意願書。未成年人無法表達意願時，則應由法定代理人簽署意願書。"},{"k":"C","t":"雖然與末期病人於意識昏迷或無法清楚表達意願前明示之意思表示不一致，仍應以最近親屬出具同意書之醫療決定為主。"},{"k":"D","t":"末期病人無簽署意願書且意識昏迷或無法清楚表達意願時，如最近親屬意思表示不一致時，成年子女、孫子女之序位先於父母。"},{"k":"E","t":"無最近親屬者，應經安寧緩和醫療照會後，依末期病人最大利益出具醫囑代替之。"}],"answer":"C","expl":"安寧緩和醫療條例：病人於意識昏迷前明示的意思表示優先，最近親屬的同意書不能推翻，所以 (C) 錯。最近親屬意思不一致時，依序位：成年子女、孫子女先於父母。條文曾修訂，請以現行版為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-16","year":110,"qnum":16,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"下列有關心臟死後器官捐贈作業參考規範之敘述，下列何者不適當?","opts":[{"k":"A","t":"待病人自然心跳停止後，開始進入「5 分鐘的等候觀察期」，須確認病人在此觀察期無再次出現收縮性血壓或心搏性心率，再由主治醫師宣判死亡，並留存相關紀錄文件。"},{"k":"B","t":"若病人疑非病死或外傷死亡者，不得進行眼角膜、皮膚、骨骼或其他組織項目之捐贈作業。"},{"k":"C","t":"為了減少病人不適及維持捐贈器官功能，可能給予必要之醫療處置，包括鎮靜、止痛藥物、抗凝血劑等。"},{"k":"D","t":"若溫缺血時超過 120 分鐘，若病人或其家屬同意捐贈組織，應續執行組織摘取作業。"},{"k":"E","t":"潛在捐贈者於原先醫療過程中未使用體外循環機器，不得為維持捐贈器官功能而另行裝置體外循環機器。"}],"answer":"B","expl":"同 109-20：心臟死後器官捐贈作業參考規範：疑似非病死者不得進行心臟死後的「器官」捐贈，但組織捐贈在法律許可（如檢察官同意）時仍可進行，所以 (B)「不得進行任何組織捐贈」較不適當；(E) 未使用體外循環者不得為維持器官而另行裝置。細節請以現行規範為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-17","year":110,"qnum":17,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"有關胸腔外傷的敘述，下列何者錯誤?","opts":[{"k":"A","t":"主動脈傷害，常發生在車禍事故或空難所造成的減速性創傷(deceleration trauma)。"},{"k":"B","t":"上述減速性創傷產生的主動脈傷害，血管破裂幾乎都發生在上升主動脈(約ligamentum arteriosum 的遠端 1.5 公分)。"},{"k":"C","t":"心臟的鈍力性外傷，可見於車禍、高處墜落，或拳腳重擊胸口，且可以是致死原因。"},{"k":"D","t":"銳器所致的穿刺傷，即使未嚴重傷及心臟，可以因為出血導致心包膜填塞(cardiac tamponade)致死。"},{"k":"E","t":"對於胸主動脈出血性休克，輸液原則是 permitting moderate hypotension，控制 SBP60-90 mmHg 間即可。"}],"answer":"B","expl":"減速性鈍傷的主動脈破裂最常發生在 aortic isthmus（靠近 ligamentum arteriosum、左鎖骨下動脈遠端），而不是升主動脈，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-18","year":110,"qnum":18,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"一位 10 歲男孩因為車禍導致腹部鈍傷(blunt abdominal trauma)而接受電腦斷層掃描(CT)，發現第 III 級(中等嚴重)脾損傷後，因為血液動力學正常入住兒科加護病房(PICU)進行密切觀察。 以下哪項符合緊急開刀的適應症(剖腹術)?","opts":[{"k":"A","t":"抽血發現 amylase >200."},{"k":"B","t":"抽血發現 leukocyte:14,000."},{"k":"C","t":"腹腔外膀胱破裂 (Extraperitoneal bladder rupture) 。"},{"k":"D","t":"在追蹤的 CT 發現腹腔內游離空氣 (Free intraperitoneal air) 。"},{"k":"E","t":"血紅素在 24 小時內由 12 g/dL 掉到 10.9 g/dL。"}],"answer":"D","expl":"同 107-24：兒童 Grade III 脾損傷追蹤 CT 發現腹內游離空氣，需剖腹，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-19","year":110,"qnum":19,"topic":"腹部","subtopic":"脾臟","stem":"一名 27 歲男學生在球場上被足球直接撞擊腹部之後抱怨持續性左上腹壓痛和左肩痛。\n在急診室評估時病人意識清楚，生命徵象穩定。創傷(FAST)超音波檢查顯示肝腎空間(Morrison pouch)和脾臟凹陷(splenic recess)中有大量明顯的流體。這個病人最合適的下一步是執行?","opts":[{"k":"A","t":"直接剖腹探查手術。"},{"k":"B","t":"診斷性腹腔鏡手術 (diagnostic laparoscopy) 。"},{"k":"C","t":"診斷性腹膜灌洗(DPL) 。"},{"k":"D","t":"24 小時之後再做一次超音波。"},{"k":"E","t":"腹部電腦斷層檢查包含靜脈注射顯影劑。"}],"answer":"E","expl":"同 109-23：腹部鈍傷、生命徵象穩定、FAST 陽性，應做 IV contrast CT，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-20","year":110,"qnum":20,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"下列有關老人外傷之敘述，何者為非?","opts":[{"k":"A","t":"台灣已成高齡化的社會。以民國 109 年的全國死因統計來看，外傷為 65 歲以上者之老人死亡原因的第三位，僅次於癌症和心血管疾病。"},{"k":"B","t":"依衛福部的統計，總體而言，各年齡層的事故傷害死亡率，以 65 歲以上者之老人最高。"},{"k":"C","t":"老人外傷個案佔全體外傷個案的比例逐年升高。"},{"k":"D","t":"就美國經驗，老人外傷的死因，以跌倒、交通事故、與燒燙傷為首"},{"k":"E","t":"就老人外傷而言，即使為輕微的外傷機轉，也可能導致嚴重外傷或外傷後併發症，特別是因心血管疾病而使用抗凝血劑的老年傷患。"}],"answer":"A","expl":"依台灣統計，外傷（事故傷害）在 65 歲以上死因並不是第三名（排名在癌症、心臟病、肺炎、腦血管疾病等之後）。官方答案 (A) 為非。確切排名請以衛福部最新統計為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-21","year":110,"qnum":21,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列有關懷孕婦女外傷之敘述，何者為非?","opts":[{"k":"A","t":"懷孕過程中，血漿的增加將大於紅血球的增加，故懷孕末期會呈現輕微的生理性貧血現象(physiologic anemia of pregnancy)"},{"k":"B","t":"懷孕 10 周以後，心輸出量將逐漸增加。至懷孕晚期，20-30%的心輸出需提供給子宮。"},{"k":"C","t":"正常狀態下，懷孕時心跳將增加 10-15 次/分，血壓則反而稍降"},{"k":"D","t":"懷孕中期以後，平躺時因子宮壓迫到下腔靜脈，減少下肢血液回流而導致心輸出量下降，減少量可以高達 30%。故孕婦外傷時，若需固定於長背板應右側墊高，朝左側半側臥。或以手將子宮推往左側，以減少下腔靜脈的壓迫。"},{"k":"E","t":"孕婦的總血量與心輸出量會優先給應給子宮。故胎兒較孕婦而言，較不容易呈現休克反應。"}],"answer":"E","expl":"孕婦出血時，子宮血管會先收縮以保護母體，造成胎兒灌流減少，因此胎兒更容易出現缺氧與休克，母體生命徵象常是晚期變化，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-22","year":110,"qnum":22,"topic":"休克輸血","subtopic":"抗凝／抗血小板藥物與外傷出血","stem":"下列關於頭部外傷病人使用 anticoagulant，下列何者錯誤?","opts":[{"k":"A","t":"抗血小板如 apsirin，palvix 應使用血小板當反轉劑。"},{"k":"B","t":"warfarin 可以使用 FFP，Vitamin K，prothrombin complex concentrate (Kcentra)，Factor VIIa 當反轉劑。"},{"k":"C","t":"Heparin 應使用 Protamine sulfate 當反轉劑。"},{"k":"D","t":"使用 Pradaxa 可以用 idarucizumab 當反轉劑。"},{"k":"E","t":"使用 Rivaroxaban 的病人最安全，不需要停藥。"}],"answer":"E","expl":"頭部外傷使用抗凝血劑：warfarin 可用 PCC（Kcentra）、vitamin K、FFP；heparin 用 protamine；dabigatran 用 idarucizumab；rivaroxaban 等 Xa 抑制劑仍需評估停藥與反轉（PCC 或 andexanet），並非最安全或不需要停藥，所以 (E) 錯。","outdated":true,"suspect":false,"flagNote":"選項 (A)「抗血小板藥物應輸血小板反轉」已被 PATCH 試驗（2016）質疑（ICH 病人輸血小板結果更差）；(B)「Factor VIIa」也不再被推薦；官方答案 (E) 不變。原官方答案維持 (E)，僅供臨床與新版指引對照。","images":[]},{"id":"110-23","year":110,"qnum":23,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"下列有關明顯為孕婦的外傷病患處置之敘述何者為非?","opts":[{"k":"A","t":"清除呼吸道。"},{"k":"B","t":"維持適當的換氣。"},{"k":"C","t":"維持適當的組織灌流並且止血。"},{"k":"D","t":"評估病患意識狀況。"},{"k":"E","t":"Logroll 移動病患以檢查背部時以左邊高，翻到右側為主。"}],"answer":"E","expl":"孕婦（子宮明顯）翻身檢查背部，應向左側傾斜（右側墊高）以避免子宮壓迫 IVC，不是「左邊高、翻到右側」，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-24","year":110,"qnum":24,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"一名患者遭受到骨盆槍傷，手術中發現在左側髂總動脈有 50% 橫斷。儘管夾住了左髂總動脈近端和左髂外動脈近端，但仍有持續出血。 最合適的下一步是什麼？","opts":[{"k":"A","t":"Clamp the left common iliac vein."},{"k":"B","t":"Clamp the left internal iliac artery."},{"k":"C","t":"Clamp the aorta just above its bifurcation."},{"k":"D","t":"Pack the pelvis and proceed to angiography."},{"k":"E","t":"performed the graft bypass surgery."}],"answer":"D","expl":"髂總動脈 50% 橫斷、近端與遠端夾住後仍持續出血，常見是 internal iliac 或 back-bleeding；不要盲目夾血管，可先 packing 骨盆並轉血管攝影（或結紮），所以官方答案 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-25","year":110,"qnum":25,"topic":"小兒","subtopic":"總論／其他","stem":"有關外傷病童使用骨針的敘述下列何者不適當？","opts":[{"k":"A","t":"骨針建議放置處為遠端股骨 (distal femur) 及近端脛骨 (proximal tibia) 。"},{"k":"B","t":"近端脛骨插入骨針時最好朝向腳趾端與皮膚表面呈 45 度角刺入，以避免傷及生長板。"},{"k":"C","t":"在大量出血性休克的病童，可預期周邊血管收縮，不易建立輸液管路，但是，一般周邊血管靜脈注射仍優於骨針的使用。"},{"k":"D","t":"骨針可以用來輸血，但是有一些藥物經由骨針給予其吸收效價會有所折扣。"},{"k":"E","t":"在外傷病童，骨針使用的最大病發症是輸液外漏 (extravasation of fluid)"}],"answer":"B","expl":"兒童 IO：位置為近端脛骨與遠端股骨；近端脛骨進針點在脛骨粗隆下 1–3 cm，針頭朝腳端偏離生長板，約 60–90 度，不是 45 度（官方答案 (B)）。IO 可輸血與給藥，最大併發症為 extravasation；休克兒童周邊靜脈難建立時，應盡早使用 IO，而非堅持周邊靜脈。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-26","year":110,"qnum":26,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"27 歲男性大學生，開車與它車擦撞，下車查看時被對方三人持棒球棒摳打造成頭部及身體多處受傷，病患當時主訴頭痛、暈及身體挫傷疼痛，但意識清楚能自行走上救護車，抵逹醫院時突昏迷，右眼瞳孔擴大、昏迷指數 8 分、BP:158/90、HR:85，請問下列最可能診斷?","opts":[{"k":"A","t":"延遲性腦出血(ICH)。"},{"k":"B","t":"硬膜下出血(SDH)。"},{"k":"C","t":"硬膜上出血(EDH)。"},{"k":"D","t":"廣泛性腦挫傷(Diffuse brain injury)。"},{"k":"E","t":"以上皆可能。"}],"answer":"C","expl":"意識曾清楚，之後突然昏迷、單側瞳孔放大、血壓上升、心跳慢（Cushing 反應），符合 EDH 的 lucid interval 與 herniation，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-27","year":110,"qnum":27,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關骨盆骨折合併尿道斷裂的敘述何者為非?","opts":[{"k":"A","t":"球部尿道(Bulbar urethra)是最容易因 blunt trauma 受傷的尿道。"},{"k":"B","t":"外傷性尿道損傷常見於骨盆骨折病患。"},{"k":"C","t":"尿道口有血是尿道損傷的主要症狀，沒有出血即可排除尿道損傷。"},{"k":"D","t":"後尿道損傷通常由於骨盆骨折，處理應以穩定生命優先。"},{"k":"E","t":"緊急情況下，恥骨上尿液引流是尿道斷裂病患引流尿液的適當處置。"}],"answer":"C","expl":"尿道損傷時尿道口出血是常見表現，但沒有出血並不能排除損傷，所以 (C) 為非。(A) 鈍傷最常傷及球部尿道（跨騎傷）；骨盆骨折則多傷後尿道（膜部）；(E) 急症可用 suprapubic 引流。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-28","year":110,"qnum":28,"topic":"老年孕婦","subtopic":"總論／其他","stem":"有一 80 歲男性患者，走路被機車撞倒，大腿明顯變形，119 送至一地區醫院，生命徵象穩定，意識清楚，若你是急診醫師，什麼處置是不宜：","opts":[{"k":"A","t":"問明有無特殊病史。"},{"k":"B","t":"抽血檢查包含 INR、ABG"},{"k":"C","t":"轉送醫學中心。"},{"k":"D","t":"直接收住院觀察治療。"},{"k":"E","t":"注意有無使用抗凝血劑。"}],"answer":"D","expl":"80 歲老人大腿變形，疑似股骨骨折，且可能服用抗凝血劑，生命徵象穩定時，應評估病史、INR 與血氣，並轉到具骨科與創傷處置能力的醫學中心；不宜在地區醫院直接收住院觀察，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-29","year":110,"qnum":29,"topic":"胸部","subtopic":"創傷性主動脈損傷","stem":"有關外傷性主動脈裂傷(Traumatic aortic disruption)下列敘述何者正確?","opts":[{"k":"A","t":"屬於有立即性生命威脅之胸部外傷，必須在 primary survey 時明確診斷。"},{"k":"B","t":"缺乏專一性的病徵，通常是靠病史中有減速力的外傷加上胸部 X 光的特徵發現高度懷疑，提高警覺。"},{"k":"C","t":"只要胸部 X 光無相關的特徵，就可完全排除此診斷。"},{"k":"D","t":"左支氣管被推擠向上(elevation of the left main bronchus) 胸部 X 光特徵之一。"},{"k":"E","t":"主動脈攝影(Aortography)已證實為準確的篩檢方法。"}],"answer":"B","expl":"外傷性主動脈破裂缺乏專一性症狀，依減速傷機轉加上 CXR 表現（縱隔腔變寬、aortic knob 消失、左主支氣管向下壓、NG tube 向右偏）高度懷疑，再以 CTA 確診，所以 (B)。CXR 正常不能排除；左主支氣管是被「向下」推擠。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-30","year":110,"qnum":30,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"有關外傷性心包膜填塞(Cardiac tamponade)，下列何者為非?","opts":[{"k":"A","t":"主要是因心包囊積液，影響血液回流心臟所致。若診斷急性橫隔膜破裂，以觀察為主。"},{"k":"B","t":"最常見的原因是胸腔鈍傷。"},{"k":"C","t":"典型的臨床表徵包括低沉的心音、低血壓、頸靜脈擴張。"},{"k":"D","t":"可能會出現 Kussmaul’s sign。"},{"k":"E","t":"可以藉由聽呼吸音及胸腔敲診，與張力性氣胸做鑑別診斷。"}],"answer":"B","expl":"心包填塞最常見於穿刺傷（尤其心臟刺傷），鈍傷較少，所以 (B) 為非；(D) Kussmaul sign 可出現；(E) 可由呼吸音與敲診與張力性氣胸鑑別。","outdated":false,"suspect":true,"flagNote":"選項 (A) 後半句「若診斷急性橫隔膜破裂，以觀察為主」與心包填塞無關且觀念錯誤（急性橫隔膜破裂需手術修補），似是誤植文字，使 (A) 也成為「錯誤」選項；官方答案 (B) 為準。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"110-31","year":110,"qnum":31,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"一位 60 歲男性，從三樓墜落，被送至急診室，病人意識清楚，生命徵象穩定，但下背部明顯腫痛，下肢癱瘓無法活動，X-ray 發現 T12 fracture dislocation ，有關急診室外傷醫師第一線處置，下面的敘述那項正確?","opts":[{"k":"A","t":"應立即理學檢查 anus tone。"},{"k":"B","t":"Reduction of dislocation 手術須待病人下背消腫後進行。"},{"k":"C","t":"Neurogenic shock 呈現 hypotension and tachycardia。"},{"k":"D","t":"應儘速使用 methylprednisolone。"},{"k":"E","t":"應該儘速給予病人穿上背架以固定骨折。"}],"answer":"A","expl":"T12 fracture-dislocation 合併下肢癱瘓：急診應立即評估肛門括約肌張力與球海綿體反射（判斷脊髓損傷程度與是否 spinal shock），所以 (A)。(C) neurogenic shock 為低血壓合併心搏過緩；(D) methylprednisolone 不建議常規使用；(E) 背架不是最優先，需保持 log-roll 與脊椎排列。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-32","year":110,"qnum":32,"topic":"休克輸血","subtopic":"總論／其他","stem":"一名 30 歲男性車禍後送醫。送至急診時 GCS 為 E4V5M6，心跳 134 下/分、血壓 79/48 mmHg、呼吸淺快、SpO2 為 92%；病人持續抱怨腹部及左背部、左肩疼痛。有關此病人之下一步處置何者較不合理?","opts":[{"k":"A","t":"目前狀況不需進行氣管內插管。"},{"k":"B","t":"需注意是否有氣胸之可能。"},{"k":"C","t":"立即於右側 femoral vein 打一條 3-way central venous catheter 方便大量輸液給予。"},{"k":"D","t":"應立即以超音波做 E-FAST 檢查判斷休克原因。"},{"k":"E","t":"應除去身上衣物檢查是否有其他外傷，必要時以烤燈保溫。"}],"answer":"C","expl":"休克併腹部、左背、左肩痛，疑腹內出血（脾）與氣胸，優先 E-FAST，建立大口徑周邊靜脈（或 introducer）輸液，並保暖與脫衣檢查；在腹部可能傷及 IVC 時，股靜脈 3-way CVC 流速慢且不一定可靠，不是第一選擇，所以 (C) 較不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-33","year":110,"qnum":33,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"下列何者非 \"definite airway\":","opts":[{"k":"A","t":"orotracheal tube."},{"k":"B","t":"nasotracheal tube."},{"k":"C","t":"tracheostomy."},{"k":"D","t":"cricothyroidotomy."},{"k":"E","t":"laryngeal tube airway."}],"answer":"E","expl":"Definitive airway 指氣囊在氣管內且固定的氣道：orotracheal、nasotracheal、tracheostomy、cricothyroidotomy；laryngeal tube（LMA、King LT 等聲門上裝置）不是 definitive airway，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-34","year":110,"qnum":34,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"病患接受大量輸血程序(massive transfusion protocol)治療後可能出現的併發症，下列何者為非?","opts":[{"k":"A","t":"鹼血症 alkalosis。"},{"k":"B","t":"高血鈉 hypernatremia。"},{"k":"C","t":"低血鈣 hypocalcemia。"},{"k":"D","t":"高血鉀 hyperkalemia。"},{"k":"E","t":"輸血相關急性肺損傷 TRALI。"}],"answer":"B","expl":"大量輸血的併發症：低體溫、低血鈣（citrate）、高血鉀（儲存血 K+）、酸中毒（之後可能轉為代謝性鹼血症）、凝血病變與 TRALI／TACO；不會造成高血鈉，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-35","year":110,"qnum":35,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"關於外傷病患接受急診室緊急開胸復甦術(ED thoracotomy resuscitation)的禁忌症，下列何者為非?","opts":[{"k":"A","t":"胸或腹部鈍傷，到院前無目擊生命徵象或經 10 分鐘到院前 CPR 未恢復生命徵象。"},{"k":"B","t":"明顯嚴重的頭部損傷。"},{"k":"C","t":"腹部臟器外露合併到院後心跳停止。"},{"k":"D","t":"胸或腹部穿刺傷，經 15 分鐘到院前 CPR 未恢復生命徵象。"},{"k":"E","t":"因嚴重內科疾病求診，惟到院前疑似頭部撞傷血腫，於急診室突然失去生命徵象。"}],"answer":"C","expl":"ED thoracotomy 的禁忌或不建議：鈍傷到院前無生命徵象、鈍傷 CPR >10 分鐘、穿刺傷 CPR >15 分鐘、嚴重頭部損傷、非創傷的嚴重內科疾病；腹部臟器外露（evisceration）不是禁忌，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-36","year":110,"qnum":36,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"對於處理外傷出血性休克的病患下列敘述何者正確 ：","opts":[{"k":"A","t":"維持適當的 urine output 很重要，對於成人最好維持尿液排出 1 ml/kg/hr。"},{"k":"B","t":"持續的 acidosis 代表 inadequate resuscitation or 持續 blood loss，建議不要使用sodium bicarbonate 來治療病患。"},{"k":"C","t":"大量輸血為定義一天內輸血大於 10U 或 1 小時大於 6U。"},{"k":"D","t":"可以使用 transamine iv over 30 mins 在 3 小時內完成。"},{"k":"E","t":"大部分接受輸血的患者都需要給 calcium 的補充。"}],"answer":"B","expl":"大量出血休克：酸中毒需要治療出血與恢復灌流，不建議用 sodium bicarbonate 來矯正，所以 (B)。(A) 成人尿量目標約 0.5 mL/kg/hr（兒童 1 mL/kg/hr）；(D) TXA 為 10 分鐘內給 1 g，不是 30 分鐘；(E) 並非全部病人都需要鈣，但大量輸血病人常需要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-37","year":110,"qnum":37,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"有關成人因外傷造成的出血性休克的急救及復甦何者正確?","opts":[{"k":"A","t":"一開始先輸注 1 公升等張晶質輸液，看其血壓反應變化來評估後續是否需要輸血。"},{"k":"B","t":"若需要輸注大量血品，建議 PRBC FFP platelet 1:1:1 方式輸血。"},{"k":"C","t":"受傷後三小時內給予 bolus 1g loading IVF 輸注 10 分鐘的 tranexamic acid，8 小時後再給予 tranexamic acid 1g ，能降低死亡率。"},{"k":"D","t":"使用 Thromboelastography (TEG) or rotational thromboelastometry(ROTEM)能幫忙評估病患的凝血功能狀態來給予相對應的血品。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"外傷出血性休克：初始 1 L 等張晶質輸液，必要時輸血；大量輸血 pRBC：FFP：platelet 約 1:1:1；TXA 傷後 3 小時內 1 g（10 分鐘），再 1 g（8 小時）（CRASH-2）；TEG/ROTEM 可指引血品使用，所以 (E) 皆是。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-38","year":110,"qnum":38,"topic":"頭部TBI","subtopic":"輕度頭部外傷 CT 適應症（Canadian CT Head Rule）","stem":"評估腦部外傷的 Canadian head CT rule 不包括下例何者：","opts":[{"k":"A","t":"臉部撕裂傷。"},{"k":"B","t":"GCS 未達 15 分。"},{"k":"C","t":"年紀大於 65 歲。"},{"k":"D","t":"持續嘔吐。"},{"k":"E","t":"顱骨是否有凹陷性骨折。"}],"answer":"A","expl":"Canadian CT Head Rule 高風險：GCS <15（2 小時後）、疑似開放或凹陷性顱骨骨折、顱底骨折徵象、嘔吐 ≥2 次、年齡 ≥65 歲；中風險：失憶 ≥30 分鐘、危險機轉。臉部撕裂傷不在其中，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-39","year":110,"qnum":39,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於腹部穿刺傷之處理原則，下列敘述何者錯誤?","opts":[{"k":"A","t":"血液動力學不穩定，常規必須手術。"},{"k":"B","t":"腹部槍傷，血液動力學穩定，沒有瀰漫性腹膜炎 (diffuse peritonitis)，沒有內臟剜出 (evisceration)，不必常規手術。"},{"k":"C","t":"腹部刀子穿刺傷，血液動力學穩定，有瀰漫性腹膜炎，沒有內臟剜出，不必常規手術。"},{"k":"D","t":"如要選擇非手術療法，需要做腹部電腦斷層評估或系列理學檢查。"},{"k":"E","t":"血液動力學穩定，可使用診斷性腹腔鏡評估橫隔和腹膜穿刺情況。"}],"answer":"C","expl":"腹部穿刺傷：不穩定需剖腹；穩定的槍傷或刀傷若無腹膜炎、無內臟脫出可考慮 selective NOM；但若已有瀰漫性腹膜炎，就需要手術，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-40","year":110,"qnum":40,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"下列關於創傷傷患之凝血病變 (coagulopathy) 敘述何者為非?","opts":[{"k":"A","t":"多重創傷傷患約有 1/4 至 1/3 於到達醫院時已有 coagulopathy。"},{"k":"B","t":"嚴重肝臟創傷會有 coagulopathy。"},{"k":"C","t":"代謝性酸血症 (metabolic acidosis) 會有 coagulopathy。"},{"k":"D","t":"單純嚴重腦創傷 (traumatic brain injury, TBI) 很少大出血，少有 coagulopathy。"},{"k":"E","t":"接受大量輸液復甦者會有 coagulopathy。"}],"answer":"D","expl":"同 108-35：單純嚴重 TBI 也常出現 coagulopathy（腦組織釋出 tissue factor），並非少有，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-41","year":110,"qnum":41,"topic":"ICU營養併發症","subtopic":"VTE（靜脈血栓栓塞）預防","stem":"下列有關創傷傷患靜脈血栓栓塞症 (venous thromboembolism) 之敘述何者錯誤?","opts":[{"k":"A","t":"發生率，西方人和東方人差不多。"},{"k":"B","t":"常無症狀；即使有，臨床症狀也不可靠。"},{"k":"C","t":"D-dimer > 500 ng/ml 代表很可能有靜脈血栓栓塞症。"},{"k":"D","t":"置放中心靜脈導管可能會導致靜脈血栓栓塞症。"},{"k":"E","t":"IVC filter 不可常規使用。"}],"answer":"C","expl":"創傷病人 D-dimer 幾乎都會升高（組織損傷與血腫），特異性很低，D-dimer >500 不代表有 VTE，所以 (C) 錯。(E) IVC filter 不應常規預防性使用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-42","year":110,"qnum":42,"topic":"ICU營養併發症","subtopic":"VTE（靜脈血栓栓塞）預防","stem":"下列有關創傷傷患靜脈血栓栓塞症 (venous thromboembolism) 之預防何者錯誤?","opts":[{"k":"A","t":"盡早下床行走。"},{"k":"B","t":"2020年美國西部創傷協會 (Western Trauma Association, WTA) 建議使用創傷栓塞評分系統 (Trauma Embolic Scoring System) 來評估是否需要施行靜脈血栓栓塞症之預防。"},{"k":"C","t":"藥物預防 (pharmacologic prophylaxis) 應在流血已經被控制後24小時內投與。"},{"k":"D","t":"藥物預防應在腦創傷(traumatic brain injury, TBI)72小時內投與。"},{"k":"E","t":"藥物預防之投與須至少三個月。"}],"answer":"B","expl":"創傷 VTE 預防：儘早下床；出血控制穩定後 24–72 小時內開始藥物預防；TBI 病人在 CT 穩定後約 24–72 小時開始；(B) 關於 2020 年 WTA 與 Trauma Embolic Scoring System 的敘述，官方認為不正確，我無法逐項確認出處；(E) 官方未視為錯誤。所以官方答案 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-43","year":110,"qnum":43,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"在下列的AIS之下，請計算外傷嚴重度分數(injury severity score)，頭部AIS為2分，臉部AIS為1分，胸部AIS有為2分，腹部AIS為3及4分，四肢為4分。","opts":[{"k":"A","t":"11。"},{"k":"B","t":"41。"},{"k":"C","t":"10。"},{"k":"D","t":"36。"},{"k":"E","t":"5 。"}],"answer":"D","expl":"同 109-4：ISS = 腹 4² + 四肢 4² + 頭頸或胸 2² = 36，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-44","year":110,"qnum":44,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非?","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"同 107-34：DPL 陽性標準 RBC ≥100,000/mm³（鈍傷），而非 500,000，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-45","year":110,"qnum":45,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部閉合性損傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序為何呢?","opts":[{"k":"A","t":"肝、脾等實質性器官→胃→十二指腸第一部→空腸→回腸→大腸及它們的系膜→盆腔器官。"},{"k":"B","t":"肝、脾等實質性器官→十二指腸第一部→胃→回腸→空腸→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"同 105-8：腹部鈍傷探查順序為肝、脾 → 橫隔肌 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸及系膜 → 盆腔器官，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-46","year":110,"qnum":46,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列有關ICU重症病患營養治療之敘述，何者為非?","opts":[{"k":"A","t":"較高蛋白的攝取一般更能達到氮平衡或正氮平衡(nitrogen balance)，故 Traumatic brain injury (TBI)的病患相比於”非 TBI”的病患，前者對蛋白質的損耗(protein catabolism)更高，也更需要增加蛋白攝取。"},{"k":"B","t":"休克的重症病患仍使用升壓劑或強心劑時，若已接受充分復甦，且升壓劑或強心劑之劑量已持續減少，可嘗試給予腸道灌食。"},{"k":"C","t":"血液動力學不穩定的 ICU 病人，若能接受早期腸道灌食，其 ICU 死亡率及住院死亡率都較低。"},{"k":"D","t":"對於會因腸道營養而加重肝昏迷的病人，可使用支鏈胺基酸(branched chain amino acid)強化配方。"},{"k":"E","t":"對於”damage-control”腹部手術或治療 abdominal compartment syndrome 而不關閉腹部的病患，腸道營養可增加筋膜關閉成功率。"}],"answer":"A","expl":"同 104-20：官方認為「TBI 比非 TBI 病人更需要增加蛋白攝取」的說法為非，所以 (A)。其他選項為腸道營養的標準觀念。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-47","year":110,"qnum":47,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"急診接獲通報，田中高鐵站爆炸案造成多人受傷事件(mass casualty event, MCE)，醫院指派你帶領醫療小組前往現場成立緊急醫療站，以下敘述何者為是?","opts":[{"k":"A","t":"醫療站應該離現場越近越好，才能就近照顧病人。"},{"k":"B","t":"醫師身為專業人員，不論受訓與否，應與搜救人員一同進入災區搶救生命。"},{"k":"C","t":"此事件應由內科醫師擔任檢傷官會比外科醫師合適。"},{"k":"D","t":"現場以檢傷分類為主，以現有資源盡可能救助最大量的傷患。"},{"k":"E","t":"身處醫療資源優渥的台灣，將手邊資源挹注在單一重傷患也是可行的。"}],"answer":"D","expl":"同 106-23：MCE 現場醫療站以檢傷分類為主，使資源服務最多傷患，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-48","year":110,"qnum":48,"topic":"災難院前法規","subtopic":"總論／其他","stem":"下列有關酒駕時呼氣酒精濃度達到多少即違反「刑法」第185條之3不能安全駕駛罪，處二年以下有期徒刑，得併科20萬元以下罰金?","opts":[{"k":"A","t":"0.15mg/L。"},{"k":"B","t":"0.25mg/L。"},{"k":"C","t":"0.55mg/L。"},{"k":"D","t":"0.85mg/L。"},{"k":"E","t":"2.0mg/L。"}],"answer":"B","expl":"同 107-28：依刑法第 185 條之 3，呼氣酒精濃度 ≥0.25 mg/L（或血液酒精濃度 ≥0.05%）屬不能安全駕駛罪，所以 (B)。","outdated":true,"suspect":false,"flagNote":"題幹刑度「二年以下、20 萬以下罰金」為當年條文；據我所知法條已修正加重刑度（約三年以下、30 萬以下罰金），請以現行法條確認；0.25 mg/L 門檻不變。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"110-49","year":110,"qnum":49,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射 4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"同 108-44：老年酗酒者跌倒後上肢無力重於下肢、反射亢進與感覺障礙，符合 central cord syndrome，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"110-50","year":110,"qnum":50,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一名 38 歲男性登山客失足跌落山谷，遲至 24 小時後才獲救。檢傷時發現除呼吸偏快(28 下/分) 以外其餘生命徵象穩定；嗜睡但可喚醒，GCS 為 E3V4M6。檢查發現病人四肢肌肉腫脹、有多處瘀血及鈍傷痕跡，合併多處擦傷及右側第一、第二蹠骨骨折。\n頭頸和胸腹部皆無明顯傷痕及壓痛。插上導尿管後病人解出茶色尿液。有關此病人之敘述及處置何者最不合理？","opts":[{"k":"A","t":"Arterial blood gas analysis 最有可能的結果是 metabolic acidosis with respiratory compensation。"},{"k":"B","t":"針對此病人的問題，檢驗 myoglobinuria 會比 serum creatinine kinase 敏感性更高。"},{"k":"C","t":"大量 hydration 可能會惡化四肢肌肉腫脹，甚至造成 compartment syndrome。"},{"k":"D","t":"血 液 中 的 電 解 質 最 有 可 能 的 變 化 是 h y p e r k a l e m i a 、 h y p o c a l c e m i a 及hyperphosphatemia。"},{"k":"E","t":"目前並無明確證據支持鹼化尿液對此病人的腎功能有保護作用。"}],"answer":"B","expl":"同 108-22：橫紋肌溶解症以血清 CK 最敏感，myoglobinuria 較不敏感，所以 (B) 最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-1","year":111,"qnum":1,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關泌尿道外傷之敘述何者錯誤?","opts":[{"k":"A","t":"下泌尿道外傷也常合併嚴重外傷一起發生，如骨盆骨折等。"},{"k":"B","t":"膀胱外傷最常見的類型為腹膜腔內破裂(intraperitoneal rupture)。"},{"k":"C","t":"腹膜腔外膀胱破裂(extraperitoneal bladder rupture)常因骨盆骨折導致。"},{"k":"D","t":"腹膜腔內膀胱破裂常需以手術縫合治療，而腹膜腔外膀胱破裂則常以導尿引流治療即可。"},{"k":"E","t":"骨盆骨折懷疑有尿道受傷時在影像學檢查確認病灶前最好先不要盲目放置導尿管。"}],"answer":"B","expl":"膀胱外傷最常見的是 extraperitoneal rupture（約 60–65%，常合併骨盆骨折），intraperitoneal 約 25–35%，所以 (B) 錯。腹膜腔內破裂需手術修補，腹膜腔外破裂多可導尿引流；疑尿道傷時避免盲目導尿。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-2","year":111,"qnum":2,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"對於 injury prevention 的對策一般有 3E，(1)enforcement and legislation (2)education and behavior change (3)engineering and environmental modification，請問何者是最有效的作為？","opts":[{"k":"A","t":"Enforcement and legislation."},{"k":"B","t":"Education and behavior change."},{"k":"C","t":"Engineering and environmental modification."},{"k":"D","t":"三者皆一樣有效。"},{"k":"E","t":"三者皆無顯著之效。"}],"answer":"B","expl":"官方答案為 (B) Education and behavior change。","outdated":false,"suspect":true,"flagNote":"同 109-3：傷害預防文獻通常認為被動式的 engineering and environmental modification（如安全氣囊、護欄、道路設計）效果最持久，所以 (C) 似乎比 (B) 更合理；官方答案可能有誤，請依官方答案作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"111-3","year":111,"qnum":3,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"大面積燒傷後因為全身性發炎反應症候群(Systemic Inflammatory Response Syndrome, SIRS)源於發炎細胞釋出大量細胞因子 (cytokines)而對生理造成影響，以下何者為非？","opts":[{"k":"A","t":"大面積燒傷雖無吸入性創傷，也會因為SIRS而發生ARDS。"},{"k":"B","t":"大面積燒傷後在沒有燒傷的部位也會發生燒傷後水腫(burn edema)，就是SIRS的結果。"},{"k":"C","t":"大面積燒傷後發生燒傷後水腫是因為輸液急救後所造成的，所以只使用膠體輸液(colloid)就不會發生燒傷水腫了。"},{"k":"D","t":"大面積燒傷後因為燒傷水腫容易造成喉頭水腫而危及呼吸道，所以儘早插管是必須的。"},{"k":"E","t":"燒傷水腫主要是因微血管通透性增加造成capillary leakage。"}],"answer":"C","expl":"同 107-12：燒傷水腫是 SIRS 與微血管通透性增加的結果，只用 colloid 無法避免，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-4","year":111,"qnum":4,"topic":"休克輸血","subtopic":"REBOA","stem":"有關 REBOA(resuscitative endovascular balloon occlusion of the aorta)，下列何者敘述並非適當？","opts":[{"k":"A","t":"可做為橫膈膜以下出血的暫時控制出血手段。"},{"k":"B","t":"放置前，務必測試球囊(balloon)是否可順利充滿(inlflation)。"},{"k":"C","t":"球囊(balloon)於 aorta 中的位置，如果狀況允許，最好能用 X-ray 確認。"},{"k":"D","t":"如有肺部出血，REBOA 反而可能會加重其出血狀況。"},{"k":"E","t":"產後大出血亦可用 REBOA 做初步的出血控制。"}],"answer":"B","expl":"官方答案為 (B)：認為「放置前務必測試球囊是否可順利充滿」不適當。","outdated":false,"suspect":true,"flagNote":"(A)(C)(D)(E) 都符合 REBOA 的觀念（橫膈以下出血、X-ray 確認位置、胸內出血會加重、產後出血可用）；(B) 在一般做法中也是常見建議，我看不出它明顯錯誤，可能依特定產品說明書（例如避免在體外充氣）。此題官方答案存疑，請依官方作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"111-5","year":111,"qnum":5,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一名 20 歲女性，交通事故後意識昏迷，由救護車轉送至具有良好設備的大型醫院外傷中心。患者到院時血壓 78/45mmHg，心跳速率 125/min，GCS 為 E1M1V1，外傷醫師已到場。經放置氣管內管後，初步超音波檢查發現，左側肋膜腔有大量積液，腹腔內亦有多量腹水。此時患者突然發生心跳停止，脈搏消失，且血壓量不到，遂開始 CPR。\n此時下列處置，何者最適當？","opts":[{"k":"A","t":"立刻轉送至開刀房做搶救手術。"},{"k":"B","t":"持續 CPR，待有 ROSC(return of spontaneous circulation)後，再盡快轉送至開刀房做搶救手術。"},{"k":"C","t":"從 femoral artery 放置 REBOA(resuscitative endovascular balloon occlusion of the aorta)，有 ROSC 後再盡快轉送至開刀房做搶救手術。"},{"k":"D","t":"做 left anterolateral thoracotomy 以做 aortic clamping、left lung pedicle clamping 及open cardiac massage。"},{"k":"E","t":"持續 CPR，待有 ROSC 後，盡快安排血管栓塞(angioembolization)止血。"}],"answer":"D","expl":"心跳停止、左胸大量積液與腹水，應立即 left anterolateral thoracotomy 做 resuscitative thoracotomy（aortic cross-clamp、肺門鉗夾、open cardiac massage），所以 (D)。REBOA 在胸腔出血與心跳停止時不是首選。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-6","year":111,"qnum":6,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關 pelvic fracture (使用 Young- Burgess 分類)之敘述，何者為非？","opts":[{"k":"A","t":"對於 unstable pelvic fracture, early external fixation 是考慮的選項。"},{"k":"B","t":"Pelvic angioembolization,目前為 pelvic fracture hemorrhage 止血主要選擇。"},{"k":"C","t":"Stable type pelvic fracture (e.g Lateral compression I, APC type I)，有時也會產生pelvic hemorrhage."},{"k":"D","t":"Unstable type pelvic fracture，文獻報告約有 40~70%之 pelvic hemorrhage rate."},{"k":"E","t":"Sacral-iliac (SI) joint traumatic disruption，發生 pelvic hemorrhage 機會低。"}],"answer":"E","expl":"Young-Burgess 分類：SI joint 破壞（尤其合併後骨盆環不穩定）出血風險高，所以 (E) 為非。(B) 骨盆 TAE 為主要止血選項；(C) 穩定型骨折也可能出血；(D) 不穩定骨折出血率約 40–70%。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-7","year":111,"qnum":7,"topic":"腹部","subtopic":"脾臟","stem":"有關 Blunt spleen injury，在加護病房中之治療及觀察，下列敘述何者為是?\n1.Grade V 及 spleen hilum 之 injury，大部分可以 Nonoperative management 治療成功\n2.Pediatric blunt spleen injury ( > 6 y/o)，因較無 post splenectomy overwhelming sepsis 之疑慮, 且由於小孩之 spleen capsule 較厚，故以手術治療為主。\n3.Spleen angioembolization( SAE)，可做為 Nonoperative management 輔助治療。\n4.Spleen partial infarction 是做完 SAE 後常見之 complication.\n5.Spleen angioembolization( SAE), material 之選擇， gelfoam 優於 coil，且較不易造成 post procedure bleeding.","opts":[{"k":"A","t":"1,2,3,5。"},{"k":"B","t":"1,2,4。"},{"k":"C","t":"3,4。"},{"k":"D","t":"3,5。"},{"k":"E","t":"4,5。"}],"answer":"C","expl":"同 110-8：SAE 可輔助 NOM，常見併發症為脾臟部分梗塞；Grade V 及脾門損傷 NOM 成功率較低；兒童脾損傷以 NOM 為主；gelfoam 並不優於 coil，所以 3 與 4 正確，答案 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-8","year":111,"qnum":8,"topic":"胸部","subtopic":"Flail chest／肋骨固定","stem":"微創手術近年進步神速，胸部外傷患者合併肋骨骨折如連枷胸，可儘早接受使用鈦鋼板肋骨固定手術(ribs fixation)，依據此類肋骨固定手術的建議，那項較不正確：","opts":[{"k":"A","t":"三根以上的肋骨多處斷裂骨折，合併槤枷胸，為手術適應症(indication)。"},{"k":"B","t":"肋骨手術固定，可減少疼痛與呼吸器使用時間。"},{"k":"C","t":"肋骨背後(posterior)端，肋骨斷裂處離橫突(transverse process)過近，此骨折處不建議手術固定。"},{"k":"D","t":"前胸部 (anterior)之胸骨骨折，手術固定前，應考慮排除心臟頓挫傷 blunt heart injury或肺挫傷。"},{"k":"E","t":"下端第 10 或 11 單根肋骨斷裂骨折，不論有無併發症，均建議手術固定。"}],"answer":"E","expl":"肋骨固定指徵：flail chest（≥3 根連續骨折）、嚴重疼痛、胸壁變形等；單根下位（第 10、11 肋）骨折不論有無併發症，並不一定建議固定，所以 (E) 較不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-9","year":111,"qnum":9,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"嚴重外傷懷孕婦女抵達急救室後，臉色蒼白，經急救後血壓只 55/?mmHg.心跳145/min. GCS:3.腹部明顯懷孕，當下急救復甦顯然失效，下列有關瀕死孕婦剖腹產(Perimortem Cesarean Section)，敘述那項最正確：","opts":[{"k":"A","t":"應予標準急救處置外，維持 30 度右側傾斜躺姿(30o left lateral position)或左側墊高(title)。"},{"k":"B","t":"如懷孕婦女血流動力停止，母親急需心肺復甦(CPR)，應維持右側傾斜躺姿，並有效胸部心臟按壓。"},{"k":"C","t":"母親(CPR)如無恢復自主循環，懷孕胎兒>24 週，考慮瀕死剖腹產(Perimortem Cesarean Section)"},{"k":"D","t":"建議應在心肺復甦(CPR)五分鐘內開始，胎兒分娩應在剖腹產後三分鐘內完成。"},{"k":"E","t":"此時剖腹產術式，採用標準剖腹產下腹橫切傷口(Pfannenstiel incision)。"}],"answer":"C","expl":"孕 >24 週的孕婦，CPR 無法恢復自主循環時，應考慮 perimortem cesarean（於 4–5 分鐘內開始，5 分鐘內娩出胎兒），採 vertical midline incision（非 Pfannenstiel），所以 (C)。(A)(B) 的左側傾斜文字有誤植。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-10","year":111,"qnum":10,"topic":"小兒","subtopic":"總論／其他","stem":"三歲幼兒外傷送至急診，逐漸出現呼吸窘迫、神智昏睡時，下列的敘述最不適當的是：","opts":[{"k":"A","t":"幼兒胸部骨質結構尚未完全，縱使沒有肋骨骨折也可能氣胸或血胸。"},{"k":"B","t":"幼兒對張力性氣胸的治療，縱生理結構與成人不同，但治療原則相同。"},{"k":"C","t":"幼兒對張力性氣胸耐受力(tolerable)差，易造成休克。"},{"k":"D","t":"幼兒不考慮使用藥物引導插管(drug-assisted)，應考慮外科氣道切開術。"},{"k":"E","t":"幼兒呼吸靠橫膈運動為主，但對舒醒球呼吸(bag-masker ventilation)效果佳。"}],"answer":"D","expl":"同 109-12：3 歲幼兒仍可依 ATLS 做藥物輔助插管（RSI）並預備 surgical airway 作為備案，不是一律先外科氣道，所以 (D) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-11","year":111,"qnum":11,"topic":"休克輸血","subtopic":"總論／其他","stem":"有一位 40 歲女性病患，因車禍受傷而送醫急救。到院時血壓 60/30 mmHg，心跳150/min，Glasgow Coma Scale Score 為 15 分，經 primary survey and resuscitation 緊急輸液 1,000C.C 的 Ringer’s lactate 及輸血 1,000C.C.後，血壓上升為 70/40 mmHg，腹部超音波顯示腹腔內有大量液體，胸部 X 光顯示兩側沒有血胸或氣胸，雙側瞳孔等大有光反射，則下列何處置較適當？","opts":[{"k":"A","t":"安排給予升壓劑。"},{"k":"B","t":"立刻進行腹部電腦斷層檢查。"},{"k":"C","t":"立刻安排血管攝影。"},{"k":"D","t":"立刻做 Diagnostic peritoneal lavage."},{"k":"E","t":"安排緊急開腹手術。"}],"answer":"E","expl":"輸液 1 L 加輸血 1 L 後血壓仍低，FAST 陽性、胸部 X 光無血胸或氣胸，為 non-responder，需要緊急開腹止血，所以 (E)。升壓劑、CT、血管攝影與 DPL 都會延誤。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-12","year":111,"qnum":12,"topic":"腹部","subtopic":"脾臟","stem":"19 歲的男性發生機車事故後送至醫院，他的生命跡象正常，但上腹部有一塊瘀青並延伸至左側，患者並無其他的明顯外傷，經腹部電腦斷層檢查後有看到脾臟破裂併顯影劑外漏至腹腔內，同時骨盆腔部位有一大塊液體滯留，這患者最需要的處置是為下列何者？","opts":[{"k":"A","t":"施打肺炎雙球菌疫苗。"},{"k":"B","t":"脾臟血管栓塞。"},{"k":"C","t":"施打中央靜脈導管。"},{"k":"D","t":"氣管內管插管。"},{"k":"E","t":"安排 Diagnostic peritoneal lavage."}],"answer":"B","expl":"生命徵象穩定，CT 顯示脾臟破裂合併 contrast extravasation，首選 splenic angioembolization，所以 (B)。肺炎雙球菌疫苗是脾切除後或 SAE 後才考慮的後續處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-13","year":111,"qnum":13,"topic":"顏面頸部","subtopic":"顏面骨折（LeFort、咬合）","stem":"以下何處(種)臉部骨折與腦脊髓液滲漏之發生最為相關？","opts":[{"k":"A","t":"Maxillary ridge"},{"k":"B","t":"Le Fort III."},{"k":"C","t":"Orbital blowout."},{"k":"D","t":"Zygoma."},{"k":"E","t":"Palatine bone."}],"answer":"B","expl":"Le Fort III（顱顏分離）骨折線通過 cribriform plate，最易造成 CSF leak，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-14","year":111,"qnum":14,"topic":"胸部","subtopic":"Cardiac tamponade／心臟外傷","stem":"有關胸腔外傷的敘述，下列何者錯誤？","opts":[{"k":"A","t":"主動脈傷害，常發生在車禍事故或空難所造成的減速性創傷(deceleration trauma)"},{"k":"B","t":"上述減速性創傷產生的主動脈傷害，血管破裂幾乎都發生在上升主動 脈(約ligamentum arteriosum 的遠端 1.5 公分)。"},{"k":"C","t":"心臟的鈍力性外傷，可見於車禍、高處墜落，或拳腳重擊胸口，且可以是致死原因。"},{"k":"D","t":"銳器所致的穿刺傷，即使未嚴重傷及心臟，可以因為出血導致心包膜填塞(cardiac tamponade)致死。"},{"k":"E","t":"超過 90%的胸腔大血管損傷起因於穿刺傷。"}],"answer":"B","expl":"同 110-17：減速傷造成的主動脈破裂最常在 aortic isthmus（ligamentum arteriosum 附近、左鎖骨下動脈遠端），不是升主動脈，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-15","year":111,"qnum":15,"topic":"腹部","subtopic":"肝臟","stem":"關於肝臟鈍挫傷非手術治療處理後相關併發症的描述，以下何者為非？","opts":[{"k":"A","t":"創傷後非手術處理方式之膽汁滲漏比例約 3~20%，經引流 4~6 週後，通常會自行緩解。"},{"k":"B","t":"如果病人創傷後產生急性右上腹痛，黃疸及上腸胃道出血，應考慮是創傷後的十二指腸急性出血。"},{"k":"C","t":"如產生肝膿瘍可經由引流及抗生素治療得到改善，不一定要手術治療。"},{"k":"D","t":"創傷後 3~5 日, 如產生全身系統性發炎反應，應考慮腹腔鏡手術進行腹腔清洗及引流。"},{"k":"E","t":"肝臟內之巨大血腫，有可能引發肝臟的腔室症候群，導致門脈高壓。"}],"answer":"B","expl":"肝損傷 NOM 後急性右上腹痛、黃疸與上消化道出血是典型的 hemobilia（膽道出血），不是十二指腸出血，所以 (B) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-16","year":111,"qnum":16,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤？","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"C","t":"蛋白質的建議劑量為 1.2 to 2.0 g/kg/day，燒燙傷患者更可高於 2.0g/kg/day。"},{"k":"D","t":"熱量的建議為 25 to 30 kcal/kg/day。為讓及早達到總熱量的目標值，若腸道營養攝取不夠， 應於受傷後第一天儘早給予靜脈營養，以及早達到 100%每天熱量需求量。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"D","expl":"營養：24–48 小時內開始 EN；蛋白質 1.2–2.0 g/kg/day；不建議在受傷第一天就用 PN 補足 100% 熱量（過早 PN 增加感染併發症），應在 EN 不足且 7 天左右才考慮，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-17","year":111,"qnum":17,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術(damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血 ；紗布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復；通過輸注液體和血液恢復正常的心血管狀態以及使用昇壓相關藥物；低溫後殘留凝血病變的矯正反轉；\n並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation)應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現”致命三害”(lethal triad)時。"}],"answer":"C","expl":"同 106-43：damage control 在休克時不做完整吻合重建，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-18","year":111,"qnum":18,"topic":"腹部","subtopic":"脾臟","stem":"一名 27 歲男學生在球場上被足球直接撞擊腹部之後抱怨持續性左上腹壓痛和左肩痛。\n在急診室評估時病人意識清楚，生命徵象穩定。創傷(FAST)超音波檢查顯示肝腎空間(Morrison pouch)和脾臟凹陷(splenic recess)中有大量明顯的流體。 這個病人最合適的下一步是執行 ?","opts":[{"k":"A","t":"直接剖腹探查手術。"},{"k":"B","t":"診斷性腹腔鏡手術 (diagnostic laparoscopy)。"},{"k":"C","t":"診斷性腹膜灌洗(DPL)。"},{"k":"D","t":"24 小時之後再做一次超音波。"},{"k":"E","t":"腹部電腦斷層檢查包含靜脈注射顯影劑。"}],"answer":"E","expl":"同 109-23：腹部鈍傷、生命徵象穩定且 FAST 陽性，做 IV contrast CT，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-19","year":111,"qnum":19,"topic":"休克輸血","subtopic":"REBOA","stem":"在 急診 室，有 一位創 傷性 低血壓 的病人 ，你 嘗試置 放 REBOA (Resuscitative EndovascularBalloon Occlusion of the Aorta)，下面哪一個選項不是禁忌症(Contraindication)?","opts":[{"k":"A","t":"頸部穿刺傷。"},{"k":"B","t":"非因胸腔、腹腔出血或其他大量出血所致的心臟停止。"},{"k":"C","t":"到院前或在急診室心跳停止，時間少於 10 分鐘。"},{"k":"D","t":"近端主動脈剝離。"},{"k":"E","t":"癌症末期。"}],"answer":"C","expl":"REBOA 禁忌症：胸部穿刺傷與頸部穿刺傷（出血在阻斷點上方）、近端主動脈剝離、非出血所致的心臟停止等；到院前或急診心跳停止時間少於 10 分鐘（有機會恢復）並非禁忌，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-20","year":111,"qnum":20,"topic":"休克輸血","subtopic":"REBOA","stem":"在 急診 室，有 一位創 傷性 低血壓 的病人 ，你 嘗試置 放 REBOA (Resuscitative Endovascular Balloon Occlusion of the Aorta)，下面哪一個選項不是適應症(Indications)?","opts":[{"k":"A","t":"腹腔出血但對於初期體液復甦有部分反應。"},{"k":"B","t":"對於各年齡層皆可適用。"},{"k":"C","t":"到院前或在急診室心跳停止，時間少於 10 分鐘。"},{"k":"D","t":"對於下肢近端鼠蹊處，肢端截肢或斷肢大量出血的病患，仍可以使用。"},{"k":"E","t":"腹部鈍傷，查無腹腔大量出血，經理學檢查，疑似骨盆骨折的低血壓患者。"}],"answer":"B","expl":"REBOA 適應症：橫膈以下出血、對初期復甦部分有反應、腹股溝或肢端大量出血且無法壓迫止血、疑似骨盆骨折休克、心跳停止少於 10 分鐘；並非各年齡層皆適用（兒童與孕婦等資料少，血管過細），所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-21","year":111,"qnum":21,"topic":"總論評分","subtopic":"多重外傷定義（Berlin definition）","stem":"小丸子與爺爺、奶奶、姊姊、及父親同搭一車出遊，途中發生車禍送醫急救。依據 2014年 Berlin definition，何者屬於多重外傷(polytrauma)患者？","opts":[{"k":"A","t":"意識清楚、生命徵象穩定合併頭、胸、四肢多處撕裂傷的 72 歲奶奶。"},{"k":"B","t":"左側鎖骨閉鎖性骨折(AIS 2)及單純第二至第八肋骨骨折(AIS 3)的姊姊。"},{"k":"C","t":"蜘蛛膜下腔出血(AIS 3)及左手遠端橈骨閉鎖性骨折(AIS 2)之 73 歲爺爺。"},{"k":"D","t":"左大腿骨骨折(AIS 3)及脾臟第四度撕裂傷(AIS 4)，血壓 75mmHg 的父親。"},{"k":"E","t":"肝臟第四度撕裂傷(AIS 4)合併代謝性酸中毒(base excess = - 6.3)之小丸子。"}],"answer":"D","expl":"Berlin definition 多重外傷：至少兩個身體區域 AIS ≥3，加上以下至少一項：SBP ≤90、GCS ≤8、base excess ≤ −6、INR >1.4 或 aPTT >40 秒、年齡 ≥70；父親（四肢 AIS 3 加腹部 AIS 4，且 SBP 75）符合，所以 (D)。爺爺只有一個 AIS ≥3 區域；小丸子與姊姊也只有一個區域。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-22","year":111,"qnum":22,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關腹部血管損傷之敘述，何者為非？","opts":[{"k":"A","t":"對損傷之血管進行探查手術時，應優先考慮進行近端血流控制(proximal control)。"},{"k":"B","t":"直接打開血腫處能夠最快速且最容易修補損傷之血管。"},{"k":"C","t":"手術中如果發現肝動脈損傷，可考慮直接與以結紮。"},{"k":"D","t":"肝門靜脈之損傷，處理上較肝動脈損傷困難；接受結紮而非修補或重建之患者有較高之併發症比率及死亡率。"},{"k":"E","t":"對於鈍挫傷導致之腎周圍血腫(peri-renal hematoma)，在沒有破裂、快速增大、及脈動(pulsatile)的狀況下，不建議打開血腫探查。"}],"answer":"B","expl":"腹部血管損傷處理：先近端控制（proximal control），再打開血腫修補；直接打開血腫風險高，易使出血失控，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-23","year":111,"qnum":23,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於微創手術應用於腹部外傷之敘述，何者有誤？","opts":[{"k":"A","t":"雖然有文獻指出微創手術能夠應用於腹部外傷合併休克之患者，但相對穩定的生命徵象仍被認為是腹部外傷患者能否接受微創手術的先決條件。"},{"k":"B","t":"對於腹部鈍傷後，影像學檢查無法解釋臨床表現的患者(unclear abdomen)，可考慮進行腹腔鏡探查手術。"},{"k":"C","t":"針對腹部外傷進行之微創手術，能降低非治療性剖腹手術(non-therapeutic laparotomy)之可能性，從而降低併發症及整體醫療費用，故不論機構的照護能力或外科醫師的經驗如何，都應該選擇微創手術治療患者。"},{"k":"D","t":"對於合併有顱內損傷之腹部外傷患者，腹腔鏡手術進行的過程可能導致患者顱內壓上升，故需謹慎評估是否適合採行微創手術治療腹部損傷。"},{"k":"E","t":"氣體栓塞(venous gas embolism)雖然罕見，但卻有極高的死亡率。手術中一旦懷疑氣體栓塞的發生，第一步應立即停止手術並移除腹腔氣體以減低腹內壓。"}],"answer":"C","expl":"微創手術用於腹部外傷需視病人穩定度、機構能力與醫師經驗，並非不論條件都應選擇，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-24","year":111,"qnum":24,"topic":"脊椎脊髓","subtopic":"頸椎評估／固定（Canadian C-Spine、頸圈、長背板）","stem":"關於 spinal and spinal cord injury，以下何者為是？","opts":[{"k":"A","t":"外傷病人中，有腦傷合併脊椎髓傷的比例遠較有脊椎損傷合併腦傷的病人還多。"},{"k":"B","t":"只要脊椎損傷無法排除，病人就無法撤除頸圈(neck collar)及長背板(spine board)。"},{"k":"C","t":"胸椎骨折中，若為彎曲伸展型骨折(flexion/distraction (chance) fracture)型，須小心伴隨有腹內器官或是後腹腔的損傷。"},{"k":"D","t":"脊椎損傷一定是連續性，若頸椎骨折，則腰椎以下不會有其他病灶。"},{"k":"E","t":"高處墜落的病患常見骨盆骨折，但脊椎損傷相對少見。"}],"answer":"C","expl":"Chance fracture（flexion-distraction）常合併腹內器官與後腹腔損傷，所以 (C)。(A) 脊椎損傷合併腦傷比例較高；(B) 可依臨床與影像清除頸椎；(D) 脊椎損傷可為不連續多處；(E) 高處墜落常合併脊椎損傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-25","year":111,"qnum":25,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"Traumatic Brain Injury 常因腦出血和水腫導致顱內壓升高，依 Monro-Kellie Doctrine定律，醫護人員要儘快降低病患的顱內壓，下列敍述何者為非？","opts":[{"k":"A","t":"可短暫使用過度呼吸(Hyperventlation)，將血液 Paco2 調降至 35mmHg，造成血管收縮減少腦血流。"},{"k":"B","t":"避免 Hypo-或 Hyper-Vplemia，維持病患在 normo-volemia。"},{"k":"C","t":"最好選擇 D5S 輸液，給予 saline 加上醣分供給病患的熱量及營養。"},{"k":"D","t":"Hypertonic saline 可使用在低血壓病患，快速降低腦壓。"},{"k":"E","t":"Mannital 能快速有效降低顱內壓，但對低血壓病患是不適合的。"}],"answer":"C","expl":"TBI 不應給含糖輸液（D5S 會造成高血糖），以等張生理食鹽水為宜，所以 (C) 為非。(D) 高張鹽水可用於低血壓病人；(E) 甘露醇有利尿作用，低血壓時不適合；(A) 過度換氣僅短暫、輕度使用（PaCO2 約 30–35）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-26","year":111,"qnum":26,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"68 歲男性走路時跌倒，頭及雙上臂、雙膝挫傷腫痛，經救護車送至外傷責任醫院治療，意識清楚但有暈眩現象，BP:138/87、HR:82，雙下肢體因疼痛稍無力、雙前臂手掌麻痛且稍沒力，經觸摸後更加疼痛，下列何者為非？","opts":[{"k":"A","t":"執行 x-ray 檢查時可以拿掉頸椎。"},{"k":"B","t":"完整的 x-ray 檢查要照到 C1-7。"},{"k":"C","t":"臨床上的診斷 central cord syndrome。"},{"k":"D","t":"可以使用 steroid 來改善症狀。"},{"k":"E","t":"治療結果尚佳。"}],"answer":"B","expl":"依官方答案 (B)：「完整 X-ray 要照到 C1–C7」為非（正確應涵蓋 C1 到 T1，包括 C7–T1 交界）。中央脊髓症候群以保守治療為主，預後尚可。","outdated":true,"suspect":false,"flagNote":"(D)「可使用 steroid 改善症狀」已不被現行指引建議（AANS/CNS 2013 不建議在急性 SCI 常規使用）；(A) 病人有神經症狀時在影像檢查期間不應拿掉頸圈，因此 (A) 也被視為不正確，官方答案 (B) 有爭議，請依官方作答。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"111-27","year":111,"qnum":27,"topic":"頭部TBI","subtopic":"總論／其他","stem":"72 歲男性開車下陽明山時被後車追撞，送至醫院時呈現昏迷，對痛刺激眼睛仍閉著，一直呻吟，上下肢胡亂揮動，下肢呈現 Flaccid，BP:140/90、HR:82、RR:18/min，對於頸部外傷的處置，那一項最為優先","opts":[{"k":"A","t":"固定頭頸部並給予 Osmotic diuretics。"},{"k":"B","t":"過度呼吸(Hpperventilation)維持 Paco2 35mmHg 左右。"},{"k":"C","t":"Hypertonic saline 降低腦壓。"},{"k":"D","t":"避免低血壓(Hypotension) 。"},{"k":"E","t":"安排電腦斷層，確定有沒有腦出血。"}],"answer":"D","expl":"昏迷合併下肢 flaccid 的頸部外傷（可能合併 TBI 與脊髓傷），最優先是避免低血壓（維持 MAP 與腦灌注），所以 (D)。過度換氣與利尿劑都不是首要。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-28","year":111,"qnum":28,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷病患營養治療之敘述，何者為非？","opts":[{"k":"A","t":"對於能夠由口進食的重症患者，由口進食應優於 EN(腸道營養)或 PN(靜脈營養)。"},{"k":"B","t":"如果有由口進食與 EN 之禁忌，PN 應在三到七天內實施。"},{"k":"C","t":"嚴重營養不良的病人如無法給予腸道營養，應要早期且漸進地給予靜脈營養。"},{"k":"D","t":"早期全量 EN 和 PN 應住院馬上達到目標值。"},{"k":"E","t":"所有患者皆應考慮進行營養評估，特別是住院超過 48 小時者。"}],"answer":"D","expl":"營養：能口進食則優先口進食；EN 不可行時再考慮 PN，營養不良者可早期漸進給 PN；不應「住院馬上達到全量」目標（需漸進），所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-29","year":111,"qnum":29,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有一 80 歲男性患者，走路被機車撞倒，大腿明顯變形，119 送至一地區醫院，生命徵象穩定，意識清楚，若你是急診醫師，什麼處置是不宜：","opts":[{"k":"A","t":"問明有無病史。"},{"k":"B","t":"抽血檢查包含 INR ,ABG。"},{"k":"C","t":"轉送醫學中心。"},{"k":"D","t":"直接收住院觀察治療。"},{"k":"E","t":"老人病患要特別注意有無使用抗凝血劑。"}],"answer":"D","expl":"同 110-28：80 歲老人大腿變形，疑似股骨骨折，且可能服用抗凝血劑，應評估後轉醫學中心，不宜直接收住院觀察，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-30","year":111,"qnum":30,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"針對大量輸血流程(Massive Transfusion Protocol, MTP)之敘述何者為非？","opts":[{"k":"A","t":"啟動流程之判斷包含使用Assessment of Blood Consumption Score≧2分, 臨床上持續不穩定之生命徵象患者抑或是急性出血亟需手術或血管栓塞治療之病患。"},{"k":"B","t":"Thromboelastography (TEG)或 Rotational thromboelastometry (ROTEM) 能對輸注血品內容(blood product content)給予指引。"},{"k":"C","t":"CRASH-2 Trial中Tranexamic acid之使用可以改善病患死亡率。"},{"k":"D","t":"Prothrombin complex concentrate之使用並無臨床效益。"},{"k":"E","t":"大量輸血流程亦可運用於非外傷病患。"}],"answer":"D","expl":"MTP：ABC score ≥2、持續不穩定、需要手術或栓塞者啟動；TEG/ROTEM 指引血品；CRASH-2 證實 TXA 降低死亡率；PCC（prothrombin complex concentrate）已有臨床益處（如 warfarin 逆轉與部分創傷凝血病變），所以 (D)「無臨床效益」為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-31","year":111,"qnum":31,"topic":"胸部","subtopic":"VATS／ECMO","stem":"有關 ECMO在Traumatic lung injury之敘述，何者為非 ?","opts":[{"k":"A","t":"ECMO使用於traumatic lung injury需考慮coagulopathy及systemic heparinization之因素。"},{"k":"B","t":"ECMO使用於traumatic lung injury，目前已發表較大之series study，其survival rate約為 60~80%之間。"},{"k":"C","t":"針對此類病患即使沒有顱內出血亦不可使用anticoagulant therapy。"},{"k":"D","t":"針對此類病患中接受胸腹部手術之病患有較高之死亡率。"},{"k":"E","t":"使用呼吸器超過48小時外傷病患最常見之併發症之一為Acute respiratory distress syndrome 。"}],"answer":"C","expl":"ECMO 用於創傷肺損傷需要權衡凝血病變與全身肝素；若無顱內出血，仍可使用肝素抗凝（或採低肝素／無肝素方案），不是絕對不能，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-32","year":111,"qnum":32,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"有關治療外傷出血之藥物 transamine，下列敘述何者錯誤 ?","opts":[{"k":"A","t":"Tranexamic acid 主要作用於阻斷 plasminogen 轉變為 plasmin 的途徑。"},{"k":"B","t":"在 CRASH-2 trial 中，使用 transamine 的實驗組，證明可明顯降低因外傷性出血所造成的早期死亡。"},{"k":"C","t":"估計若外傷出血之藥物 transamine 在外傷後三小時內早期使用，全球每年約可拯救70000~100000 人的性命。"},{"k":"D","t":"若外傷性出血之初級評估時，發現病患已呈休克，需於 24 小時內靜脈給予 2g 的transamine 已減低早期死亡或大量輸血。"},{"k":"E","t":"以上皆正確。"}],"answer":"C","expl":"CRASH-2：TXA 於傷後 3 小時內使用（1 g 10 分鐘，再 1 g 8 小時）可降低死亡；TXA 阻斷 plasminogen 轉成 plasmin；官方認為 (C) 關於「每年可拯救 70,000–100,000 人」的估計數字不正確，我無法確認原始文獻數字，請以官方答案為準。(D) 兩次合計 2 g。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-33","year":111,"qnum":33,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"有關戰傷醫療的處置與觀念，以下敘述何者正確 ?","opts":[{"k":"A","t":"戰傷的現場照護 TACTICAL FIELD CARE (TFC)，是在壓制敵人火力後，進行依MARCH PAWS 原則的戰傷急救內容。"},{"k":"B","t":"戰傷中佔最多的可避免死亡原因為呼吸道問題，其次則為張力性氣胸。"},{"k":"C","t":"戰傷醫療的準則 TCCC (Tactical Combat Casualty Care)，其內容乃遵照 ATLS 的原則，並無不同。"},{"k":"D","t":"TCCC guideline 最早為美軍特種作戰司令部(SOCOM)於 1996 年所出版，2021年烏克蘭文版 TCCC guideline 正式啟用。"},{"k":"E","t":"以上皆正確。"}],"answer":"A","expl":"TCCC 的 Tactical Field Care：在壓制敵火、相對安全後，依 MARCH PAWS 原則（Massive hemorrhage、Airway、Respiration、Circulation、Head injury/Hypothermia、Pain、Antibiotics、Wounds、Splinting）進行，所以 (A)。戰傷可避免死亡最多者是大出血，其次為張力性氣胸與氣道問題；TCCC 與 ATLS 並不完全相同。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-34","year":111,"qnum":34,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"一個患者從工地墜落後被送入急診，緊急救護員描述鋼筋從背後穿刺，鋼筋在體外部分已在現場被截斷露出約 10 公分，理學檢查發現患者穿刺處於背部腰椎第五節附近，到院時意識清楚，血壓 95mmHg/80mmHg，心跳 140/min，初步超音波檢查發現腹內有大量液體。下列處置何者不適當？","opts":[{"k":"A","t":"啟動大量輸血流程。"},{"k":"B","t":"若生命徵象經初步輸血輸液後穩定，先於現場試圖將鋼筋移除以利後續檢查。"},{"k":"C","t":"若生命徵象經初步輸血輸液後穩定，可進行電腦斷層檢查檢查損傷位置。"},{"k":"D","t":"直接送手術室進行剖腹探查手術，於手術室中將鋼筋移除。"},{"k":"E","t":"若此處之下腔大靜脈大量出血無法止血時，可考慮直接將其結紮止血。"}],"answer":"B","expl":"鋼筋貫穿傷的穿刺物（impaled object）不可在現場或急診隨意拔除，需在手術室控制出血條件下移除，所以 (B) 不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-35","year":111,"qnum":35,"topic":"休克輸血","subtopic":"Permissive hypotension／限制輸液","stem":"關於可容許的低血壓復甦術(permissive hypotension)，下列何者為非?","opts":[{"k":"A","t":"適用於所有出血性休克外傷病患，包含腦部外傷。"},{"k":"B","t":"施行於出血點確認並成功止血前的復甦階段。"},{"k":"C","t":"容許的收縮壓範圍在 80~90mmHg。"},{"k":"D","t":"目的是減少大量 crystalloid 輸液所造成的副作用。"},{"k":"E","t":"屬於損害控制復甦術(Damage control resuscitation)其中的一環。"}],"answer":"A","expl":"Permissive hypotension 適用於穿刺或鈍傷的出血性休克（出血未控制前，SBP 約 80–90 mmHg），但不適用於合併腦部外傷與脊髓傷的病人（需維持灌注壓），所以 (A) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-36","year":111,"qnum":36,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"一個 6 歲小孩從火場被救出，其 back, bilateral buttock 及 bilateral posterior legs 均有呈現紅腫及水泡，其被燒傷的體表面積為多少?","opts":[{"k":"A","t":"27%。"},{"k":"B","t":"28%。"},{"k":"C","t":"30%。"},{"k":"D","t":"32%。"},{"k":"E","t":"36%。"}],"answer":"D","expl":"兒童燒傷面積以 Lund-Browder 圖估算（6 歲頭部比例較大、下肢較小）：後軀幹含臀部約 18%，雙後下肢約 14%，合計約 32%，所以官方答案 (D)；我的概算與官方略有出入，請以官方答案為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-37","year":111,"qnum":37,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"對於處理外傷出血性休克的病患下列敘述何者正確 ：","opts":[{"k":"A","t":"維持適當的 urine output 很重要，對於成人最好維持尿液排出 1 ml/kg/hr。"},{"k":"B","t":"持續的 acidosis 代表 inadequate resuscitation or 持續 blood loss，建議不要使用sodium bicarbonate 來治療病患。"},{"k":"C","t":"大量輸血為定義一天內輸血大於 10U 或 1 小時大於 6U。"},{"k":"D","t":"可以使用 transamine iv over 30 mins 在 3 小時內完成。"},{"k":"E","t":"大部分接受輸血的患者都需要給 calcium 的補充。"}],"answer":"B","expl":"同 110-36：酸中毒要治療出血與恢復灌流，不建議用 sodium bicarbonate，所以 (B)。(A) 成人尿量目標約 0.5 mL/kg/hr；(D) TXA 為 10 分鐘內給予；(E) 不是大部分都需要 calcium。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-38","year":111,"qnum":38,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"下列有關 Surgical airway 的敘述何者為非？\n1.Cricothyroidectomy 宜施行於 6 歲以上兒童。\n2.Cricothyroidectomy 應選用 7 號氣切套管。\n3.Needle cricothyroidotomy 小孩宜使用 12 或 14 號穿刺針。\n4.Needle cricothyroidotomy 氧氣供應至少需 15 L/min。","opts":[{"k":"A","t":"1+2。"},{"k":"B","t":"1+3。"},{"k":"C","t":"2+3。"},{"k":"D","t":"2+4。"},{"k":"E","t":"1+2+3。"}],"answer":"E","expl":"同 109-7：官方答案 (E)＝1、2、3 皆錯。1 錯（surgical cricothyroidotomy 通常用於 ≥12 歲，不是 6 歲）；2 錯（氣切套管依年齡選小號，不是固定 7 號）；4 氧流量 15 L/min 為標準。","outdated":false,"suspect":true,"flagNote":"項 3「小孩 needle cricothyroidotomy 用 12 或 14 號針」據我所知與 ATLS 說法一致，因此 3 應為正確，答案似乎應為 (A) 1+2；官方答案 (E) 存疑，請以官方為準。原官方答案維持 (E)，考試請以官方答案為準。","images":[]},{"id":"111-39","year":111,"qnum":39,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部鈍傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序是?","opts":[{"k":"A","t":"肝、脾等實質性器官→大腸及它們的系膜→空腸→回腸→胃→十二指腸第一部→盆腔器。"},{"k":"B","t":"回腸→空腸→肝、脾等實質性器官→十二指腸第一部→胃→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"同 105-8：腹部鈍傷探查順序為肝、脾 → 橫隔肌 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸及系膜 → 盆腔器官，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-40","year":111,"qnum":40,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"同 107-34：DPL 陽性標準 RBC ≥100,000/mm³（鈍傷），而非 500,000，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-41","year":111,"qnum":41,"topic":"四肢血管骨科","subtopic":"Compartment syndrome（肢體）","stem":"一名 38 歲男性登山客失足跌落山谷，遲至 24 小時後才獲救。檢傷時發現除呼吸偏快(28 下/分) 以外其餘生命徵象穩定；嗜睡但可喚醒，GCS 為 E3V4M6。檢查發現病人四肢肌肉腫脹、有多處瘀血及鈍傷痕跡，合併多處擦傷及右側第一、第二蹠骨骨折。\n頭頸和胸腹部皆無明顯傷痕及壓痛。插上導尿管後病人解出茶色尿液。有關此病人之敘述及處置何者最不合理？","opts":[{"k":"A","t":"Arterial blood gas analysis 最有可能的結果是 metabolic acidosis with respiratory compensation。"},{"k":"B","t":"針對此病人的問題，檢驗 myoglobinuria 會比 serum creatinine kinase 敏感性更高。"},{"k":"C","t":"大量 hydration 可能會惡化四肢肌肉腫脹，甚至造成 compartment syndrome。"},{"k":"D","t":"血液中的電解質最有可能的變化是 h y p e r k a l e m i a 、 h y p o c a l c e m i a 及hyperphosphatemia。"},{"k":"E","t":"目前並無明確證據支持鹼化尿液對此病人的腎功能有保護作用。"}],"answer":"B","expl":"同 108-22：橫紋肌溶解症以血清 CK 最敏感，myoglobinuria 較不敏感，所以 (B) 最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-42","year":111,"qnum":42,"topic":"ICU營養併發症","subtopic":"敗血症／SIRS／PICS／感染","stem":"對於受傷情況嚴重者，初步處理後往往需要加護病房觀察治療，以下敘述何者錯誤？","opts":[{"k":"A","t":"外傷造成的死亡有三大高峰，第三高峰常見傷後幾天至幾週，最常見原因是多重器官衰竭與敗血症。"},{"k":"B","t":"外傷病人常需要大量輸血，記得同時補充凝血因子如新鮮冷凍血漿以免凝血功能異常。"},{"k":"C","t":"急性腎衰竭常見在傷者轉入加護病房後，可能是因為休克、低血容引起。"},{"k":"D","t":"若傷者引發 Acute Respiratory Distress Syndrome(急性呼吸窘迫症候群)，原因可能是嚴重肺挫、大量輸血、胰臟受傷等等造成。"},{"k":"E","t":"斷肢重建後，可能會發生 Reperfusion Injury (再灌流傷害)，低血鉀是常見的表徵。"}],"answer":"E","expl":"同 107-36：再灌流傷害常見 hyperkalemia 與酸中毒，不是低血鉀，所以 (E) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-43","year":111,"qnum":43,"topic":"四肢血管骨科","subtopic":"斷肢保存／壓砸傷／橫紋肌溶解","stem":"到院前對斷肢或斷指最恰當的保存步驟為何?","opts":[{"k":"A","t":"將斷肢或斷指以 sterile water 沖洗乾淨。"},{"k":"B","t":"將沖洗乾淨的斷肢或斷指浸泡在含有冰塊的 D5W 中。"},{"k":"C","t":"將紗布以 lactated Ringer’s solution 浸潤後包裹沖洗乾淨的斷肢或斷指，之後放入乾淨的 plastic bag 內，再將 plastic bag 放入碎冰中。"},{"k":"D","t":"將沖洗乾淨的斷肢或斷指浸泡在含有冰塊的 Lactated Ringer’s Solution 中，並置入維持 0℃的冰箱中保存。"},{"k":"E","t":"以上皆非。"}],"answer":"C","expl":"同 106-37：斷肢以生理食鹽水或 LR 沖洗，用同樣液體浸濕的紗布包裹，放入乾淨塑膠袋，再置於冰上（不直接接觸冰），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-44","year":111,"qnum":44,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷患者的營養代謝支持，經由腸道進食為首要選擇途徑。下列敘述何者為誤：","opts":[{"k":"A","t":"經由胃腸道灌食，有助於調節全身發炎反應。"},{"k":"B","t":"經由胃腸道灌食，有助於增強免疫能力。"},{"k":"C","t":"胃腸道進食越早越好，暫不需考量系統性的穩定度(systemic stabilization)。"},{"k":"D","t":"燙傷患者，甚至早至 4-5 小時即可開始。"},{"k":"E","t":"若遇胃輕癱(gastroparesis)，可考慮由胃進食積極轉換為小腸灌食。"}],"answer":"C","expl":"同 107-49：腸道營養應在充分復甦、系統穩定（升壓劑穩定或下降）後儘早給予，不能不考慮穩定度，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-45","year":111,"qnum":45,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"您是一位服役於野戰醫院的軍醫，戰鬥中接到一位遭手榴彈炸傷的後送傷兵a. 右小腿外傷性截肢。\nb. 腹部開放性傷口併內臟脫出及出血。\nc. 右側開放性氣胸。\nd. 右臉頰缺失併口鼻出血。\ne. 背部大面積燒傷。\n請問您處理的順序為何？","opts":[{"k":"A","t":"cbdae。"},{"k":"B","t":"dcbae。"},{"k":"C","t":"bcdae。"},{"k":"D","t":"bacde。"},{"k":"E","t":"bcade。"}],"answer":"B","expl":"同 107-7：官方答案 (B) 為 d（口鼻出血，氣道）→ c（開放性氣胸）→ b（腹部內臟脫出）→ a（截肢）→ e（燒傷）。","outdated":true,"suspect":false,"flagNote":"現行 TCCC 與 ATLS 10 以 MARCH（先處理大出血，再 ABC） 為準：肢體截斷的大出血（massive hemorrhage，用 tourniquet）應最優先處理，之後才是氣道、呼吸。所以 (B) 的順序（把 a 排在第四）過時；官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"111-46","year":111,"qnum":46,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤？","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"熱量的建議為 25 to 30 kcal/kg/day。為避免高血糖，其中 70% 建議來自脂肪、30%來自醣類。"},{"k":"C","t":"蛋白質的建議劑量為 1.0 to 1.5 g/kg/day，燒燙傷患者更可高於 2.0 g/kg/day。"},{"k":"D","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"B","expl":"同 106-6：熱量來源是醣類與脂肪混合，70% 脂肪並非建議，所以 (B) 錯；血糖目標不宜過嚴（避免 ≤110 mg/dL）。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-47","year":111,"qnum":47,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"一位 30 歲之年輕人因右胸槍傷而被送到一地區醫院，在急診室插入胸管後，立刻有1000 cc 的鮮血流出，在轉送往創傷中心(trauma center)治療前，他的血壓突然掉到80/60 mmHg，且心跳劇增到每分鐘 138 次，下列敘述何者有誤？","opts":[{"k":"A","t":"出血可能原因為肺撕裂傷、肋間血管損傷、內乳動脈損傷。"},{"k":"B","t":"胸椎骨折移位也可能造成血胸，不過大多可以自行恢復。"},{"k":"C","t":"緊急安排胸部電腦檢查，確定出血原因及可能受傷部位，以利後續處理。"},{"k":"D","t":"此時應採取的緊急措施為重覆評估檢查傷者，並快速輸血。"},{"k":"E","t":"胸部 X 光發現有明顯血胸時，胸管放置是必要的，以利後續處置及減少併發症。"}],"answer":"C","expl":"右胸槍傷、胸管初始引流 1,000 mL 且血壓下降，是大量血胸合併休克，應快速輸血並儘速手術（開胸），不能先做 CT，所以 (C) 有誤。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"111-48","year":111,"qnum":48,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"下列有關頸部穿刺傷的敘述何者為是？","opts":[{"k":"A","t":"Zone II 的槍擊貫穿傷，都應該手術檢查。"},{"k":"B","t":"Zone I 的穿刺傷合併大範圍的皮下氣腫，應該手術檢查。"},{"k":"C","t":"Zone I 的穿刺傷合併咳血，應該手術檢查。"},{"k":"D","t":"Zone III 的穿刺傷合併吞嚥困難，應該手術檢查。"},{"k":"E","t":"Zone II 的槍擊貫穿傷，50%以上會有需手術治療的損傷。"}],"answer":"B","expl":"頸部穿刺傷：Zone I 合併大範圍皮下氣腫，高度懷疑氣管或食道損傷，需手術或進一步檢查（支氣管鏡、食道攝影），官方答案 (B)。","outdated":true,"suspect":false,"flagNote":"傳統做法是 Zone II 穿透頸闊肌的槍傷一律手術探查；現行做法（EAST/WTA、ATLS）已改為依 hard signs 與 CTA 的 selective approach，hard signs 才立即手術。官方答案 (B) 不變。原官方答案維持 (B)，僅供臨床與新版指引對照。","images":[]},{"id":"111-49","year":111,"qnum":49,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"背部穿刺外傷病人於急診檢查，有右側下肢運動肌力消失，有痛覺、溫覺，左側下肢有運動能力，傷處皮節兩節下部痛覺溫覺消失，此病人為：","opts":[{"k":"A","t":"左側脊髓損傷。"},{"k":"B","t":"右側脊髓損傷。"},{"k":"C","t":"前側脊髓動脈損傷。"},{"k":"D","t":"後側脊髓損傷。"},{"k":"E","t":"以上皆非。"}],"answer":"B","expl":"Brown-Séquard 症候群：病灶同側運動與本體覺喪失，對側（病灶下約 1–2 節）痛覺與溫覺喪失，因此右側運動消失、左側痛溫覺消失表示右側半切損傷，所以官方答案 (B)。","outdated":false,"suspect":true,"flagNote":"題幹文字不清（「右側下肢運動肌力消失，有痛覺、溫覺」與後面的痛溫覺消失敘述看起來互相矛盾），我只能依 Brown-Séquard 的典型描述推論；請以官方答案作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"111-50","year":111,"qnum":50,"topic":"休克輸血","subtopic":"總論／其他","stem":"男性車禍傷患，經急診診斷骨盆腔骨折、後腹腔出血、脾臟撕裂傷與左側血胸。經急救復甦處理後生命徵象仍不穩定，通知外科預行緊急手術；並安排輸血。但血庫通知患者驗血為 A 型 Rh 陰性，血庫無 Rh 陰性血，下列何者處置最適當？","opts":[{"k":"A","t":"聯絡其他醫院安排轉院治療。"},{"k":"B","t":"通知媒體召集 Rh 陰性 A 型捐血者。"},{"k":"C","t":"僅用乳酸林格液 (Lactate Ringers Solution)急救。"},{"k":"D","t":"乳酸林格液 5000 cc 輸注後，改用膠體溶液(如: HES:hydroxyethyl starch)。"},{"k":"E","t":"改採 Rh 陽性 A 型血輸血，緊急開刀。"}],"answer":"E","expl":"大量出血時，Rh 陰性病人無 Rh 陰性血，不應延遲輸血，可改輸 Rh 陽性血（男性與非育齡女性可接受，之後再追蹤抗體），所以 (E)。育齡女性則需評估再給 anti-D。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-1","year":112,"qnum":1,"topic":"休克輸血","subtopic":"Lethal triad（致命三角）","stem":"相對於傳統的致命三角(lethal triad)，在現代急救技術越發進步之下，我們會遇到致命鑽石(lethal diamond)，其中新加入的元素是下列何者？","opts":[{"k":"A","t":"Hypothermia。"},{"k":"B","t":"Acidosis。"},{"k":"C","t":"Hypocalcemia。"},{"k":"D","t":"Hyperkalemia。"},{"k":"E","t":"Coagulopathy。"}],"answer":"C","expl":"Lethal diamond 在三角（hypothermia、acidosis、coagulopathy）之外加入 hypocalcemia（低血鈣）；低鈣影響凝血與心肌收縮，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-2","year":112,"qnum":2,"topic":"休克輸血","subtopic":"REBOA","stem":"下列有關 REBOA(resuscitative endovascular balloon occlusion of the aorta)的敘述，何者並不適當？","opts":[{"k":"A","t":"可用以暫時控制橫膈膜以下的大出血。"},{"k":"B","t":"如果狀況允許，最好能用 X-ray 確認球囊(balloon)於 aorta 中的位置。"},{"k":"C","t":"非外傷患者不適用。"},{"k":"D","t":"球囊(balloon)放置在 aortic zone 3，可初步控制骨盆骨折出血。"},{"k":"E","t":"REBOA 可能會加重肺部出血狀況。"}],"answer":"C","expl":"REBOA 並非只用於外傷：也用於產後大出血、上消化道大出血、主動脈瘤破裂等，所以 (C)「非外傷不適用」錯。(D) Zone III 可控制骨盆出血；(E) 阻斷會加重肺出血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-3","year":112,"qnum":3,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一名36歲男性，夜晚騎機車自撞汽車後意識不清，由救護車轉送至有外傷中心且有良好設備的大型醫院急診室。患者到院時血壓70/45mmHg，心跳速率123/min，GCS為E1M1V1。經放置氣管內管且輸液輸血後，血壓提升至80/60mmHg，心跳速率120/min。\n床邊超音波檢查顯示，有大量積液位於左肋膜腔，亦有多量腹水。此時患者突然發生心跳停止，脈搏消失，且血壓量不到，遂開始CPR。此時下列處置中，何者較適當？","opts":[{"k":"A","t":"立刻轉送至開刀房做搶救手術。"},{"k":"B","t":"持續CPR，待有ROSC(return of spontaneous circulation)後，再盡快轉送至開刀房做搶救手術。"},{"k":"C","t":"從femoral artery 放置REBOA(resuscitative endovascular balloon occlusion of the aorta)，有ROSC後再盡快轉送至開刀房做搶救手術。"},{"k":"D","t":"持續CPR，待有ROSC後，盡快安排血管栓塞(angioembolization)止血。"},{"k":"E","t":"做resuscitative thoracotomy以做aortic clamping、left lung pedicle clamping及open cardiac massage，有ROSC後盡快轉送至開刀房做搶救手術。"}],"answer":"E","expl":"心跳停止、左胸大量積液與腹水，應立即 resuscitative thoracotomy（aortic cross-clamp、肺門鉗夾、open cardiac massage），所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-4","year":112,"qnum":4,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列有關 surgical critically ill 之病人 nutritional support 之敘述，何者為非？","opts":[{"k":"A","t":"許多研究由於 sampling method、mixed type patients、severity of patients，常導致不同結果。"},{"k":"B","t":"達到 energy 和 protein goal 同等重要，protein 的 goal favor 3.0~4.0 g/kg/day。"},{"k":"C","t":"目前臨床實務上建議在 acute phase 時，可 combine enteral nutrition and parenteral nutrition 使用。"},{"k":"D","t":"Severe skeletal-muscle wasting and weakness occurring during critical illness 容易造成sarcopenia。"},{"k":"E","t":"Vit D 對於 intestinal permeability and inflammatory response to pathogens 有角色。"}],"answer":"B","expl":"重症營養：蛋白質目標約 1.2–2.0 g/kg/day，不是 3–4 g/kg/day，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-5","year":112,"qnum":5,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"近年的文獻報告證實，血栓彈力 Viscoelastic hemostatic assay (VHAs)分析，在外傷大出血的病患有極大的功效。血栓彈力圖(thromboela-stogram，TEG/ROTEM)是反映血液凝固動態變化的指標，可檢測凝血功能全貌：包含凝血因子、纖維蛋白、血小板及纖維蛋白溶解(fibrinolysis)。下列敘述那項較不正確：","opts":[{"k":"A","t":"急性創傷、大量出血休克、心臟或器官移植手術患者的凝血功能評估。"},{"k":"B","t":"簡單，只需要一管全血，送醫院中央檢驗單位即可。"},{"k":"C","t":"各種出血原因的鑑別診斷，進而指導成分輸血。"},{"k":"D","t":"鑑別診斷原發性纖維蛋白溶解亢進(primary hyperfibrinolysis)或繼發性纖維蛋白原溶解亢進。"},{"k":"E","t":"減少不必要的血液成分的輸血。"}],"answer":"B","expl":"TEG/ROTEM 是 point-of-care 檢查，需要快速在床邊或附近完成，不應送中央檢驗單位延遲，所以 (B) 較不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-6","year":112,"qnum":6,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"下列關於胰臟損傷之處理原則，何者正確？(甲) 第一級 (grade I) 和第二級 (grade II) 原則上不需手術。 (乙) 如因其他原因行剖腹探查時，發現胰臟有小於 50%周長的撕裂傷，沒有胰管損傷的證據，則將其修補後放外部引流(external drainage)即可。\n(丙) 第三級 (grade III) 行遠端胰臟切除術(distal pancreatectomy)並試著保留脾臟。\n(丁) 第四級 (grade IV) 行外部引流(external drainage)。 (戊) 第五級 (grade V) 行胰臟十二指腸切除術(pancreaticoduodenectomy)，並將總膽管與胰管接在小腸。","opts":[{"k":"A","t":"甲、乙、丙。"},{"k":"B","t":"甲、乙、丁。"},{"k":"C","t":"甲、丙、丁。"},{"k":"D","t":"甲、丙、戊。"},{"k":"E","t":"甲、丁、戊。"}],"answer":"C","expl":"胰臟損傷：Grade I–II 不需手術（引流）；Grade III 遠端胰臟切除術；Grade IV 外部引流（官方答案）；小於 50% 周長的撕裂且無胰管損傷，不縫合修補，只做 external drainage，所以乙錯；Grade V 在不穩定時採 damage control，不一定做完整重建，所以戊錯。答案 (C) 甲、丙、丁。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-7","year":112,"qnum":7,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於腹部穿刺傷之處理原則，下列敘述何者錯誤？ (甲) 血液動力學穩定，常規必須手術。 (乙) 腹部刀子穿刺傷，血液動力學穩定，有瀰漫性腹膜炎 (diffuse peritonitis)，沒有內臟剜出 (evisceration)，不必常規手術。 (丙) 腹部槍傷 (手槍)，血液動力學穩定，常規需要手術。 (丁) 如要選擇非手術療法，需要做腹部電腦斷層評估或系列理學檢查。 (戊) 血液動力學穩定，可使用胸腔鏡評估橫隔穿刺情況。","opts":[{"k":"A","t":"甲、乙、丙。"},{"k":"B","t":"甲、乙、戊。"},{"k":"C","t":"乙、丙、戊。"},{"k":"D","t":"甲、丙、戊。"},{"k":"E","t":"甲、乙、丙、戊。"}],"answer":"A","expl":"穿刺傷：不穩定才常規手術，穩定的刀傷或槍傷若無腹膜炎、無內臟脫出可考慮 selective NOM；所以甲（穩定常規手術）、乙（瀰漫性腹膜炎不必手術）、丙（槍傷常規手術）皆錯，答案 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-8","year":112,"qnum":8,"topic":"骨盆泌尿","subtopic":"腎臟外傷","stem":"關於腎臟鈍傷的處理原則，下列敘述何者錯誤？","opts":[{"k":"A","t":"血液動力學穩定，必須行腹部電腦斷層檢查。"},{"k":"B","t":"血液動力學不穩定，常規必須手術。"},{"k":"C","t":"在因其他原因行緊急剖腹探查時，不要將後腹腔打開檢視腎臟鈍傷情況。"},{"k":"D","t":"血液動力學穩定，腹部電腦斷層檢查發現有顯影劑滲漏，則需行血管攝影，看是否需要栓塞。"},{"k":"E","t":"血液動力學穩定，腹部電腦斷層檢查發現腎臟無顯影，則須行血管攝影及放支架。"}],"answer":"C","expl":"腎臟鈍傷：血流動力學穩定先做 CT；不穩定需手術；剖腹時若腎周血腫不擴大、無脈動可不打開；若不穩定、擴大或脈動則需打開探查，所以 (C)「一律不要打開」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-9","year":112,"qnum":9,"topic":"休克輸血","subtopic":"Tranexamic acid（TXA／transamine）","stem":"有一位 50 歲男性病患，於車禍後 30 分鐘內送至某醫學中心急救。到院時血壓 70/40 mmHg，心跳 130/min，Glasgow Coma Scale Score 為 15 分，經 primary survey 後，腹部超音波顯示腹腔內有大量液體，電腦斷層如附圖 a 及 b，報告顯示有腸系膜大量contrast extravasation，胸部 X 光顯示兩側沒有血胸或氣胸，雙側瞳孔等大有光反射，resuscitation 緊急輸液 1,000C.C.的 Ringer’s lactate 及輸血 1,000C.C.後，血壓仍為 70/40 mmHg，則下列何處置何者較適當？","opts":[{"k":"A","t":"立刻給予升壓劑。"},{"k":"B","t":"因輸血治療效果不佳，就停止輸血治療。"},{"k":"C","t":"安排血管攝影栓塞治療，但是需等候 2 小時之後才能做栓塞。"},{"k":"D","t":"立刻給予 Tranexamic acid 1gm IV，並持續輸血，且聯絡開刀房，立即安排手術治療。"},{"k":"E","t":"立刻安排核磁共振檢查。\n圖 a 圖 b"}],"answer":"D","expl":"不穩定、腸系膜大量 contrast extravasation，輸血後血壓仍低，應立即手術，並給 TXA 1 g 且持續輸血，所以 (D)。不應等 2 小時再栓塞，也不要升壓劑取代輸血。我未逐項判讀附圖，請以官方答案為準。","outdated":false,"suspect":false,"flagNote":"","images":["p231-1.jpg"]},{"id":"112-10","year":112,"qnum":10,"topic":"休克輸血","subtopic":"REBOA","stem":"下列有關 REBOA (resuscitative endovascular balloon occlusion of the aorta)作為resuscitation 輔助的敘述，何者錯誤？","opts":[{"k":"A","t":"欲控制腎臟破裂造成的出血應將 balloon 打在 Zone I descending aorta。"},{"k":"B","t":"欲控制小腸系膜破裂的出血應將 balloon 打在 Zone I descending aorta。"},{"k":"C","t":"欲控制產後大出血應將 balloon 打在 Zone III descending aorta。"},{"k":"D","t":"腹腔內器官受損合併 pneumoperitoneum 者為 REBOA 之 contraindication。"},{"k":"E","t":"腹腔內器官受損合併 open pneumothorax 者為 REBOA 之 contraindication。"}],"answer":"D","expl":"REBOA 位置：腎臟與腸系膜出血用 Zone I；產後出血用 Zone III；開放性氣胸（胸部傷）為禁忌；單純 pneumoperitoneum 不是禁忌，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-11","year":112,"qnum":11,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"根據 TECC/TCCC 的概念，下列何者不包含在 MARCH assessment 的項目中？","opts":[{"k":"A","t":"大量出血。"},{"k":"B","t":"呼吸道。"},{"k":"C","t":"血液循環系統。"},{"k":"D","t":"昏迷指數。"},{"k":"E","t":"低體溫。"}],"answer":"D","expl":"MARCH 為 Massive hemorrhage、Airway、Respiration、Circulation、Head injury／Hypothermia；GCS 並不在其中，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-12","year":112,"qnum":12,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"腹部實體器官挫傷病患採取非手術治療 (non-operative management)方式， 之後可能產生的合併症， 下列敘述何者為非？","opts":[{"k":"A","t":"脾臟裂傷可能產生 pseudoaneurysm with delayed rupture and bleeding。"},{"k":"B","t":"肝臟裂傷可能產生 biloma or abscess。"},{"k":"C","t":"腎臟裂傷可能產生 urinoma or peri-renal abscess。"},{"k":"D","t":"絕大多數產生的合併症，需要實行外科剖腹手術處理。"},{"k":"E","t":"脾臟裂傷亦可能產生 abscess formation。"}],"answer":"D","expl":"實質器官 NOM 後併發症如脾 pseudoaneurysm、肝 biloma 或膿瘍、腎 urinoma 與膿瘍等，多數可用經皮引流、栓塞、內視鏡等處理，不需剖腹，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-13","year":112,"qnum":13,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"關於損害控制手術 (damage control operation)，以下哪項是錯誤的？","opts":[{"k":"A","t":"控制出血和污染的損害控制手術，包括控制頸部，軀幹或四肢主要動脈和靜脈出血；紗布填塞(packing)腹腔以控制不可避免的凝血機能障礙。"},{"k":"B","t":"ICU 的治療包括對體溫過低的患者進行有效的體溫恢復；通過輸注液體和血液恢復正常的心血管狀態以及使用昇壓相關藥物；低溫後殘留凝血病變的矯正反轉；並支持功能失調的肺和腎臟。"},{"k":"C","t":"損害控制手術(damage control operation)包括在首次手術中切除胃腸道主要損傷部分加上完全吻合重建，即使病人處於休克狀態。"},{"k":"D","t":"如果病人情況穩定，階段性手術(staged operation)應該包括完成確定性修復(definitive repairs)，尋找可能遺漏的傷害和正式縫合傷口。"},{"k":"E","t":"損害控制手術(damage control operation)的適應症之一是當患者在手術過程中出現“致命三害”(lethal triad)時。"}],"answer":"C","expl":"同 106-43：damage control 休克時不做完整吻合重建，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-14","year":112,"qnum":14,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"下列有關老人外傷之敘述何者為非？","opts":[{"k":"A","t":"老人較無法承受缺氧狀態，故面對外傷後休克的個案需盡快插管。"},{"k":"B","t":"老人對胸部外傷的耐受性較差，單純肋骨骨折或肺部挫傷也可能導致呼吸衰竭。"},{"k":"C","t":"老人外傷最常見的外傷機轉是跌倒。"},{"k":"D","t":"老人有較多比例具有冠狀動脈疾病，同時全身總血量也隨年紀逐漸降低，故外傷出血休克者常常呈現明顯心搏過速(tachycardia)的現象。"},{"k":"E","t":"因為老人常有高血壓的問題，故單純以血壓來判斷失血量常會誤判。"}],"answer":"D","expl":"老年人因 beta blocker、自主神經反應較差、心臟疾病，出血休克時不一定出現明顯心搏過速，所以 (D) 為非。(C) 跌倒最常見。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-15","year":112,"qnum":15,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"胸部鈍挫傷引起之主動脈損傷 (traumatic aortic injury)，其胸部 X 光影像之變化，下列何者正確？","opts":[{"k":"A","t":"縱膈腔變寬是最具特異性(specific)的徵兆。"},{"k":"B","t":"如果造成血胸，左、右兩邊發生的機率相等。"},{"k":"C","t":"可能使左側支氣管向上偏移。"},{"k":"D","t":"鼻胃管可能向左偏。"},{"k":"E","t":"肺肩部肋膜血腫(apical hematoma)或第一肋骨骨折，要懷疑降主動脈損傷。"}],"answer":"E","expl":"主動脈傷害的 CXR 表現：縱隔變寬（敏感、特異性低）、aortic knob 消失、左主支氣管向下壓、NG tube 向右偏、apical cap（肺尖肋膜血腫）、第 1、2 肋骨骨折、左血胸，所以 (E)。血胸以左側為多。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-16","year":112,"qnum":16,"topic":"胸部","subtopic":"總論／其他","stem":"關於主動脈解剖學分區，以下何者為真？","opts":[{"k":"A","t":"右側 carotid artery 至 celiac trunk 之間的區域為 zone 1。"},{"k":"B","t":"Celia trunk 至 renal artery 之間的區域為 zone 2。"},{"k":"C","t":"Celiac trunk 至 inferior mesenteric artery 之間的區域為 zone 2。"},{"k":"D","t":"Superior mesenteric artery 至 aorta bifurcation 之間的區域為 zone 3。"},{"k":"E","t":"Aorta bifurcation 以下的區域為 zone 4。"}],"answer":"B","expl":"REBOA 主動脈分區：Zone 1 為左鎖骨下動脈到 celiac trunk；Zone 2 為 celiac trunk 到最低腎動脈；Zone 3 為最低腎動脈到 aortic bifurcation，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-17","year":112,"qnum":17,"topic":"總論評分","subtopic":"多重外傷定義（Berlin definition）","stem":"小丸子與爺爺、奶奶、母親、及父親同搭一車出遊，途中發生車禍送醫急救。依據 2014年 Berlin definition，何者屬於多重外傷(polytrauma)患者？","opts":[{"k":"A","t":"意識清楚、生命徵象穩定合併頭、胸、四肢多處撕裂傷的 72 歲奶奶。"},{"k":"B","t":"左側鎖骨閉鎖性骨折(AIS 2)及單純第二至第八肋骨骨折(AIS 3)的小丸子。"},{"k":"C","t":"脾臟第四度撕裂傷(AIS 4)及左手遠端橈骨閉鎖性骨折(AIS 2)之 73 歲爺爺。"},{"k":"D","t":"左大腿骨骨折(AIS 3)合併血壓 75mmHg 的 53 歲父親。"},{"k":"E","t":"肝臟第三度撕裂傷(AIS 3)及蜘蛛膜下腔出血(AIS 3)，合併代謝性酸中毒(base excess = - 6.3)之 51 歲母親。"}],"answer":"E","expl":"Berlin definition：至少 2 個區域 AIS ≥3，加上 SBP ≤90、GCS ≤8、base excess ≤ −6、INR >1.4、年齡 ≥70 其中一項；母親（肝 AIS 3、SAH AIS 3、BE −6.3）符合，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-18","year":112,"qnum":18,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於微創手術應用於腹部外傷之敘述，何者正確？","opts":[{"k":"A","t":"雖然有文獻指出微創手術能夠應用於腹部外傷合併休克之患者，但相對穩定的生命徵象仍被認為是腹部外傷患者能否接受微創手術的先決條件。"},{"k":"B","t":"針對腹部外傷進行之微創手術，能降低非治療性剖腹手術(non-therapeutic laparotomy)之可能性，從而降低併發症及整體醫療費用。然而，是否選擇微創手術治療患者仍需視機構的照護能力及外科醫師的經驗而定。"},{"k":"C","t":"對於合併有顱內損傷之腹部外傷患者，腹腔鏡手術進行的過程可能導致患者顱內壓上升，故需謹慎評估是否適合採行微創手術治療腹部損傷。"},{"k":"D","t":"氣體栓塞(venous gas embolism)雖然罕見，但卻有極高的死亡率。手術中一旦懷疑氣體栓塞的發生，第一步應立即停止手術並移除腹腔氣體以減低腹內壓。"},{"k":"E","t":"以上皆是。"}],"answer":"E","expl":"微創手術於腹部外傷：需相對穩定生命徵象、依機構與醫師經驗選擇、顱內傷時要小心 ICP 上升、氣體栓塞時立即停止並移除氣腹，所以 (E) 皆是。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-19","year":112,"qnum":19,"topic":"脊椎脊髓","subtopic":"總論／其他","stem":"15 歲女高中生，因不願意參加學校段考，遭老師及媽媽責怪，吞服多顆鎮定劑後，由五樓高處跌落二樓，經 119 送至醫院急診，昏迷指數 E1V2M4，瞳孔不等大 2.5/3.5，對光反應不明顯，BP85/45、HR60/min，雙下肢癱瘓，anal tone loose，右側(7th.8th)肋骨骨折，有少許氣血胸，肚子稍漲，FAST 些許 ascites，經緊急氣管插管後，下列處置或敘述何者正確？","opts":[{"k":"A","t":"應馬上啟動緊急輸血 PRBC 8U 及大量 L-R fluid 維持穩定的血壓。"},{"k":"B","t":"應儘快投與 mega dose methyl-prednisone 30mg/kg 15min，接著1個小時後 5.4mg/kg run 23 小時。"},{"k":"C","t":"最好等到頭部外傷、胸腹部外傷穩定後，才去處理脊髓損傷的減壓及固定手術。"},{"k":"D","t":"因雙下肢癱瘓，雙上肢仍有 musle tone，研判脊椎損傷在 L3 以下。"},{"k":"E","t":"因脊髓損傷導致副交感神經遭受阻礙，造成血壓偏低，心跳減緩及雙下肢溫暖。"}],"answer":"C","expl":"多重傷合併 TBI、胸腹傷與脊髓傷：先處理危及生命的 ABC、頭部與胸腹，再處理脊髓減壓與固定，所以 (C)。(B) 高劑量 methylprednisolone 不被現行指引建議；(E) 脊髓損傷造成的是交感神經張力喪失（neurogenic shock）；(A) 大量 LR 與 8 U PRBC 不是標準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-20","year":112,"qnum":20,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"關於外傷病患營養治療之敘述,何者為非：","opts":[{"k":"A","t":"對於能夠由口進食的重症患者，由口進食應優於 EN(腸道營養)或 PN(靜脈營養)。"},{"k":"B","t":"如果有由口進食與 EN 之禁忌，PN 應在三到七天內實施。"},{"k":"C","t":"嚴重營養不良的病人如無法給予腸道營養，應要早期且漸進地給予靜脈營養。"},{"k":"D","t":"早期全量 EN 和 PN 應住院馬上達到目標值。"},{"k":"E","t":"所有患者皆應考慮進行營養評估，特別是住院超過 48 小時者。"}],"answer":"D","expl":"同 111-28：營養應漸進達標，不是住院後馬上全量，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-21","year":112,"qnum":21,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"35 歲女性，因騎機車發生車禍，經救護車送至急診室，意識清楚，脈搏 90/min，血壓110/70 mmHg，呼吸速率 18/min，左側呼吸音減低、敲診呈現 dullness，胸部 X 光發現左胸腔疑似有腸氣，最佳的治療規劃為：","opts":[{"k":"A","t":"放置鼻胃管，住院觀察。"},{"k":"B","t":"安排腸胃道攝影。"},{"k":"C","t":"輸液(crystalloid fluids)、輸血、加護病房觀察。"},{"k":"D","t":"進行剖腹手術探查。"},{"k":"E","t":"進行開胸手術探查。"}],"answer":"D","expl":"左側血胸徵象且 CXR 見腸氣，疑急性橫膈破裂與腸疝入，血流動力學穩定時依官方答案應剖腹探查（急性期經腹修補較好），所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-22","year":112,"qnum":22,"topic":"腹部","subtopic":"脾臟","stem":"一名 38 歲女性車禍後送至急診。經腹部電腦斷層檢查後初步診斷為第三級脾臟破裂(AATS Grade III spleen laceration)。因病患血行動力學穩定，因此被安排至加護病房觀察。經過 24 小時候再次追蹤病患臨床狀況，下列何者為緊急剖腹探查之適應症？","opts":[{"k":"A","t":"Serum amylase 340 U/L。"},{"k":"B","t":"Leukocyte count 19,000/mm。"},{"k":"C","t":"Extraperitoneal bladder rupture on follow-up CT。"},{"k":"D","t":"Free intraperitoneal air demonstrated on follow-up CT。"},{"k":"E","t":"Hemoglobin level drop from 13 g/dL to 7 g/dL。"}],"answer":"D","expl":"同 107-24：脾 Grade III NOM 期間追蹤 CT 出現腹內游離空氣，提示空腔臟器損傷，需剖腹，所以官方答案 (D)。","outdated":false,"suspect":true,"flagNote":"(E)「Hb 24 小時內由 13 掉到 7」代表至少 6 g/dL 的下降，提示持續出血，也應立即介入（輸血、angioembolization 或手術），並非不合理的選項；官方答案 (D) 有爭議，請依官方作答。原官方答案維持 (D)，考試請以官方答案為準。","images":[]},{"id":"112-23","year":112,"qnum":23,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"有關戰場戰傷救護中的處置流程，下列敘述何者為誤？","opts":[{"k":"A","t":"到院前的救護以 TCCC/TECC 為處置準則。"},{"k":"B","t":"遇大量出血的傷患，需先為其建立暢通呼吸道。"},{"k":"C","t":"在敵火下，醫護不宜冒險接近傷者，以免增加人員損失。"},{"k":"D","t":"TCCC/TECC 中的 MARCH 處置評估部分，H 是指 Head injury 或 Hypothermia。"},{"k":"E","t":"遇有開放性傷口時，除敷料保護傷口外，應早期給予口服抗生素，以降低感染率。"}],"answer":"B","expl":"MARCH 的第一項是 Massive hemorrhage，必須先止血，再處理氣道，所以 (B) 錯。(C) 在敵火下以反擊與脫離為先；(E) 開放性傷口早期口服抗生素為 TCCC 建議。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-24","year":112,"qnum":24,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"針對肋骨骨折之處理，下列敘述何者為正確？","opts":[{"k":"A","t":"肋骨骨折的診斷以胸部 X 光為第一線診斷工具，診斷後均必須進行電腦斷層檢查。"},{"k":"B","t":"氣血胸是最主要需要觀察的肋骨骨折合併症，但非常少見。"},{"k":"C","t":"止痛為肋骨骨折治療時的重要考量。"},{"k":"D","t":"只要有肋骨骨折即為手術固定的適應症。"},{"k":"E","t":"低位肋骨骨折時因肋骨將衝擊吸收，故不須考慮是否有腹內器官受損。"}],"answer":"C","expl":"肋骨骨折治療的重點是止痛（多模式止痛），所以 (C)。X 光不一定都要加 CT；氣血胸並不罕見；不是所有肋骨骨折都要手術；低位肋骨骨折需考慮肝、脾、腎損傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-25","year":112,"qnum":25,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"在外傷損害控制復甦(Damage control resuscitation)中所謂的死亡三角，下列徵象何者為非？","opts":[{"k":"A","t":"PT INR > 1.5。"},{"k":"B","t":"Body temperature < 35’C。"},{"k":"C","t":"Arterial blood gas analysis showed PH < 7.2。"},{"k":"D","t":"持續監測腹部壓力，若壓力值超過 15mmHg，達到 Grade II IAH，應立即剖腹手術減壓。"},{"k":"E","t":"Coagulopathy during operation。"}],"answer":"D","expl":"Lethal triad：INR >1.5（凝血病變）、體溫 <35°C、pH <7.2；IAP 超過 15 mmHg（IAH Grade II）並不是死亡三角的內容，也不是「立即剖腹」的標準（ACS 才需要減壓），所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-26","year":112,"qnum":26,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"下列何者不是用來預測大量輸血的 scoring system？","opts":[{"k":"A","t":"PWH (Prince of Wales Hospital) score。"},{"k":"B","t":"Vandromme score。"},{"k":"C","t":"Schreiber score。"},{"k":"D","t":"Boey score。"},{"k":"E","t":"Larson score。"}],"answer":"D","expl":"預測大量輸血的評分：ABC、PWH、Vandromme、Schreiber（McLaughlin）、Larson、TASH 等；Boey score 用於穿孔性消化性潰瘍的預後，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-27","year":112,"qnum":27,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"下列有關終結(termination)大量輸血的 protocol 於 society recommendations of Task Force for Advanced Bleeding Care in Trauma 於 laboratory result-guide model of resuscitation 中其相關目標值的敘述何者不正確？","opts":[{"k":"A","t":"Hb 控制介於 7-9 g/dL。"},{"k":"B","t":"PT , aPTT 小於 1.5 倍。"},{"k":"C","t":"PLT > 50 X 103/uL。"},{"k":"D","t":"Fibrinogen > 1.5 – 2.0 g/L。"},{"k":"E","t":"Base excess < -2。"}],"answer":"E","expl":"歐洲大量出血指引的目標值：Hb 7–9 g/dL、PT/aPTT <1.5 倍、血小板 >50 × 10³/μL（TBI 時 >100）、fibrinogen >1.5–2.0 g/L，酸中毒指標 base excess 應矯正（目標接近正常），所以 (E)「< −2」為不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-28","year":112,"qnum":28,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關泌尿道外傷之敘述何者錯誤？","opts":[{"k":"A","t":"下泌尿道外傷也常合併嚴重外傷一起發生，如骨盆骨折等。"},{"k":"B","t":"膀胱外傷最常見的類型為腹膜腔內破裂(intraperitoneal rupture)。"},{"k":"C","t":"腹膜腔外膀胱破裂(extraperitoneal bladder rupture)常因骨盆骨折導致。"},{"k":"D","t":"腹膜腔內膀胱破裂常需以手術縫合治療，而腹膜腔外膀胱破裂則常以導尿引流治療即可。"},{"k":"E","t":"骨盆骨折懷疑有尿道受傷時在影像學檢查確認病灶前最好先不要盲目放置導尿管。"}],"answer":"B","expl":"同 111-1：膀胱外傷最常見的是 extraperitoneal rupture，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-29","year":112,"qnum":29,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"嚴重外傷懷孕婦女抵達急救室後，臉色蒼白，經急救後血壓只 55/?mmHg，心跳145/min， GCS:3，腹部明顯懷孕，當下急救復甦顯然失效，下列有關瀕死孕婦剖腹產(Perimortem Cesarean Section)，敘述那項最正確：","opts":[{"k":"A","t":"應予標準急救處置外，維持 30 度右側傾斜躺姿(30o left lateral position)或左側墊高(title)。"},{"k":"B","t":"如懷孕婦女血流動力停止，母親急需心肺復甦(CPR)，應維持右側傾斜躺姿，並有效胸部心臟按壓。"},{"k":"C","t":"母親(CPR)如無恢復自主循環，懷孕胎兒>24 週，考慮瀕死剖腹產(Perimortem Cesarean Section)。"},{"k":"D","t":"建議應在心肺復甦(CPR)五分鐘內開始，胎兒分娩應在剖腹產後三分鐘內完成。"},{"k":"E","t":"此時剖腹產術式，採用標準剖腹產下腹橫切傷口(Pfannenstiel incision)。"}],"answer":"C","expl":"同 111-9：孕 >24 週的孕婦，CPR 無法恢復自主循環時，應考慮 perimortem cesarean（4–5 分鐘內開始，5 分鐘內娩出胎兒），採 vertical midline incision，所以 (C)。(A)(B) 的左側傾斜文字有誤植。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-30","year":112,"qnum":30,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"某外傷病人的 AIS 如下：頭頸部 AIS 為 2 分，臉部 AIS 為 1 分，胸部 AIS 有為 2 分，腹部 AIS 為 3 及 4 分，四肢為 4 分。請計算其外傷嚴重度分數(injury severity score)。","opts":[{"k":"A","t":"11。"},{"k":"B","t":"41。"},{"k":"C","t":"10。"},{"k":"D","t":"36。"},{"k":"E","t":"5。"}],"answer":"D","expl":"同 109-4：ISS = 腹 4² + 四肢 4² + 頭頸或胸 2² = 16 + 16 + 4 = 36，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-31","year":112,"qnum":31,"topic":"四肢血管骨科","subtopic":"股骨／開放性骨折","stem":"有關外傷病童使用骨針的敘述下列何者不適當？","opts":[{"k":"A","t":"骨針建議放置處為遠端股骨(distal femur)及近端脛骨(proximal tibia)。"},{"k":"B","t":"近端脛骨插入骨針時最好朝向腳趾端與皮膚表面呈 45 度角刺入，以避免傷及生長板。"},{"k":"C","t":"在大量出血性休克的病童，可預期周邊血管收縮，不易建立輸液管路，但是，一般周邊血管靜脈注射仍優於骨針的使用。"},{"k":"D","t":"骨針可以用來輸血，但是有一些藥物經由骨針給予其吸收效價會有所折扣。"},{"k":"E","t":"在外傷病童，骨針使用的最大病發症是輸液外漏(extravasation of fluid)。"}],"answer":"B","expl":"同 110-25：兒童 IO 近端脛骨進針點在脛骨粗隆下 1–3 cm，針頭朝腳端偏離生長板；官方答案 (B)「45 度」不適當。IO 可輸血與給藥，最大併發症為 extravasation；休克時應盡早使用 IO，而非堅持周邊靜脈。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-32","year":112,"qnum":32,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"25 歲男性在工地由二層樓高的地方跌落地面 ，到院時病人意識不清 ，GCS=7，BP=95/65，HR=122，RR=30，SaO2=85%，左側 breathing sound decreased。經放置氣管內管並由左側第五肋間 needle decompression 後，病人 GCS=12，BP=120/80，HR=108，RR=20，SaO2=98%。請問下一步的處理步驟為何？","opts":[{"k":"A","t":"立即做 brain CT。"},{"k":"B","t":"立即做 FAST examination。"},{"k":"C","t":"立即放置左側胸管。"},{"k":"D","t":"立即做 abdominal CT。"},{"k":"E","t":"立即了解受傷機轉(trauma mechanism) 。"}],"answer":"C","expl":"同 108-3：needle decompression 後的下一步是置入胸管，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-33","year":112,"qnum":33,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部鈍傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序是？","opts":[{"k":"A","t":"肝、脾等實質性器官→大腸及它們的系膜→空腸→回腸→胃→十二指腸第一部→骨盆腔器官。"},{"k":"B","t":"回腸→空腸→肝、脾等實質性器官→十二指腸第一部→胃→大腸及它們的系膜→骨盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→骨盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→骨盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→骨盆腔器官。"}],"answer":"C","expl":"同 105-8：探查順序為肝、脾 → 橫隔肌 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸及系膜 → 盆腔器官，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-34","year":112,"qnum":34,"topic":"休克輸血","subtopic":"出血分級（Class I–IV）／失血量估計","stem":"一位外傷病人被送到急診室，呈現昏迷狀態，生命徵候為：血壓 78/58 mmHg，脈搏120/min，呼吸次數 30/min，有關此病人之下列敘述何者為正確？","opts":[{"k":"A","t":"此病人血壓偏低最有可能原因為緊張性氣胸(tension pneumothorax)。"},{"k":"B","t":"立即推病人至電腦斷層掃瞄室掃瞄頭部，找出昏迷之原因。"},{"k":"C","t":"此病人若有出血，其出血量可能超過 1500 ㏄。"},{"k":"D","t":"立即照胸部 X 光排除緊張性氣胸。"},{"k":"E","t":"立即插 CVP(中央靜脈導管)給與乳酸林格液(lactate Ringer)2000 ㏄。"}],"answer":"C","expl":"同 108-5：昏迷、血壓 78/58、脈搏 120 為 Class III 以上的出血性休克，失血量可能 >1,500 mL，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-35","year":112,"qnum":35,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射 4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"同 108-44：老年酗酒者跌倒後上肢無力重於下肢、反射亢進與感覺障礙，符合 central cord syndrome，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-36","year":112,"qnum":36,"topic":"燒傷環境","subtopic":"吸入性燒傷／CO 中毒","stem":"大 面 積 燒 傷 後 因 為 全 身 性 發 炎 反 應 症 候 群 (Systemic Inflammatory Response Syndrome, SIRS)源於發炎細胞釋出大量細胞因子(cytokines)而對生理造成影響，以下何者為非？","opts":[{"k":"A","t":"大面積燒傷後即使沒有吸入性創傷，也會因為 SIRS 而發生急性呼吸窘迫症候群。"},{"k":"B","t":"大面積燒傷後在沒有燒傷的部位也會發生燒傷後水腫(burn edema)，即是 SIRS 的結果。"},{"k":"C","t":"大面積燒傷後發生燒傷後水腫是因為輸液急救後所造成的，所以不要輸太多水及及早使用膠體輸液(colloid)而非晶體輸液(crystalloid)就不會發生燒傷水腫了。"},{"k":"D","t":"大面積燒傷後因為燒傷水腫容易造成喉頭水腫而危及呼吸道，所以儘早插管是必須考量的。"},{"k":"E","t":"燒傷水腫主要是微血管管壁孔徑增加造成 capillary leakage 所造成的。"}],"answer":"C","expl":"同 107-12：燒傷水腫是 SIRS 與微血管通透性增加的結果，只用 colloid 無法避免，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-37","year":112,"qnum":37,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"一名 25 歲之年輕男性與人鬥毆後被送至急診，主訴頸部鈍器重擊，現吞嚥困難。檢傷時生命徵象穩定，檢查發現頸部無開放性傷口，但於右側頸部 Zone 2 有一大範圍皮下血腫。有關此病人之敘述何者最不適當？","opts":[{"k":"A","t":"即使喉鏡檢查(Laryngoscopy)正常，仍應密切觀察病人呼吸道症狀至少 24 小時。"},{"k":"B","t":"若頸部血腫持續擴大，即應視為 neck exploration 的手術適應症。"},{"k":"C","t":"若病人穩定但臨床上懷疑有血管損傷(vascular injury)， 電腦斷層血管攝影術(CTA)為可靠之高診斷率檢查工具。"},{"k":"D","t":"若 plain film 發現第三頸椎椎體(C3 vertebral body) fracture，應高度懷疑合併血管損傷(vascular injury)。"},{"k":"E","t":"在統計上，頸部 Zone 2 鈍傷造成血管損傷(vascular injury)的比例較 Zone 1 和 Zone3 高。"}],"answer":"E","expl":"同 107-40：鈍性頸部傷害中，血管損傷較常在 Zone I 與 Zone III，不是 Zone II 最高，所以 (E) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-38","year":112,"qnum":38,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"有關頭部外傷非手術治療(nonsurgical therapies for brain injury)之敘述，以下何者有誤？","opts":[{"k":"A","t":"腦的灌流維持好，腦細胞才有機會恢復功能；否則，腦組織會死亡。所以點滴的給予應足夠，但也不可太多。"},{"k":"B","t":"過度通氣(Hyperventilation)，會使 CO2 分壓下降，讓腦血管收縮，進而降低顱內壓，故適合用來長期控制腦壓。"},{"k":"C","t":"目前尚無證據顯示使用類固醇對嚴重頭部外傷患者有好處，因此不建議在該類患者使用類固醇。"},{"k":"D","t":"抗癲癇藥物的使用，只能有效預防早發性癲癇，但超過七天的遲發性癲癇，不會因為用了藥而不發生。"},{"k":"E","t":"腦壓(ICP)在 25 mmHg 以下就算可以接受，即使因躁動或咳嗽等使得 ICP 太高，只要能自己回復正常就沒關係。"}],"answer":"B","expl":"同 101-40：長期預防性 hyperventilation 會造成腦血管過度收縮與缺血，已不建議，只在 herniation 時短暫使用，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-39","year":112,"qnum":39,"topic":"小兒","subtopic":"總論／其他","stem":"以下關於小兒外傷處置的敘述何者正確？\n甲、外傷造成心跳停止的最常見原因為失血性休克。\n乙、估計氣管內管直徑，約同於第五指直徑。\n丙、因為插管時可能引發較強烈的迷走神經刺激，因此建議先打 atropine。\n丁、當 小 兒 困 難 插 管 時 ， 應 先 考 慮 needle cricothyroidotomy， 而 非 surgical cricothyroidotomy。\n戊、兒童的生理耐受性較成人為差，因此同比例的失血時，低血壓出現的較早。","opts":[{"k":"A","t":"甲、丙、戊。"},{"k":"B","t":"丙、丁、戊。"},{"k":"C","t":"乙、丙、丁。"},{"k":"D","t":"乙、丙、戊。"},{"k":"E","t":"甲、丁、戊。"}],"answer":"C","expl":"同 106-15：乙（氣管內管約小指粗）、丙（官方認為插管前可用 atropine）、丁（兒童困難插管用 needle cricothyroidotomy）正確；甲（兒童創傷心跳停止最常見是低氧）與戊（兒童低血壓出現較晚）錯。所以 (C)。","outdated":true,"suspect":false,"flagNote":"丙「建議先打 atropine」在現行指引（ATLS 10、PALS）已非常規，僅在特定情況考慮。官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"112-40","year":112,"qnum":40,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有關腹部實質性器官及空腔器官之損傷的描述，下列何者錯誤？\na. 肝臟是腹腔內最大的實質性器官，也是所有腹部鈍挫傷中最常見的實質器官損傷。\nb. 腹部穿刺貫通傷但無內臟脫出或異常滲液者，若已超過 24 小時且一般情況良好者，可先採取嚴密觀察保守治療。\nc. 實質性器官損傷的主要表現是腹腔內或後腹膜腔出血且合併有進行性的腹脹及腹痛。但若病人處於無法矯正的休克狀態(SBP< 90mmHg)，即使沒有腹痛的症狀也應進行剖腹探查術。\nd. 腹腔內出血 3500ml，合併肝臟右葉 4 度損傷，右腎 4 級損傷及升結腸穿孔且大範圍壞死的患者，最佳的手術方式為以最迅速的方式進行右肝葉切除，右腎摘除，右半結腸切除術及小腸橫結腸吻合術。\ne. 因車禍導致腹部鈍挫傷的患者，受傷 1 小時內的腹部 CT 顯示第五級脾臟破裂及大量腹腔內積液，無明顯游離氣體。此時為快速施行脾臟切除術，最建議的手術切口為從左肋緣下進入，以爭取時間完成脾臟切除。","opts":[{"k":"A","t":"b、d、e。"},{"k":"B","t":"a、b、d。"},{"k":"C","t":"a、d、e。"},{"k":"D","t":"c、d。"},{"k":"E","t":"d、e。"}],"answer":"C","expl":"同 103-9：a 錯（鈍傷最常受傷的是脾臟）；d 錯（damage control 而非大範圍切除重建）；e 錯（Grade V 脾傷走正中剖腹）；b、c 正確。所以 (C) a、d、e。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-41","year":112,"qnum":41,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"45 歲男性病人車禍外傷昏迷，顱內出血。手術後，病患病況依然未見好轉，二位相關專科醫師診斷為末期病人。家屬表示希望尊重病人意願，希望撤除維生醫療。病人 IC卡上註記有預立選擇安寧緩和醫療意願，不施予心肺復甦術，此時可否撤除維生醫療？","opts":[{"k":"A","t":"得逕行撤除維生醫療。"},{"k":"B","t":"需經由醫學倫理委員會決議，方可撤除維生醫療。"},{"k":"C","t":"需經由安寧照護會診，方可撤除維生醫療。"},{"k":"D","t":"由一位親屬簽署終止或撤除維生醫療同意書後，方可撤除維生醫療。"},{"k":"E","t":"絕對不可撤除維生醫療。"}],"answer":"A","expl":"同 105-34：依安寧緩和醫療條例，兩位相關專科醫師診斷為末期，且 IC 卡已註記不施行心肺復甦術與維生醫療意願，醫師可逕行依其意願撤除，不需倫理委員會、安寧會診或家屬簽署，所以 (A)。法律細節近年有修訂，請依現行條文確認。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-42","year":112,"qnum":42,"topic":"腹部","subtopic":"肝臟","stem":"經輸血與一系列檢查後，發現病人有下列外傷：右側 SDH 併腦水腫，右鎖骨骨折，右側 7~9 肋骨骨折併少量血胸，肝臟裂傷併大量腹腔內積血，右膝粉碎性骨折併右小腿血循不良。整個過程中血壓曾短暫回復至 102/76mmHg，但 10 分鐘後又再降至 82/50 mmHg，意識狀態也變為 E1V2M4。請問此時除立即以氣管內管插管外，何種處置需最優先進行？","opts":[{"k":"A","t":"進行開顱手術清除血塊並放置顱內壓監測。"},{"k":"B","t":"放置右側胸管引流血胸。"},{"k":"C","t":"進行剖腹手術以控制腹腔內出血。"},{"k":"D","t":"安排右下肢血管攝影以確認血循受阻的位置。"},{"k":"E","t":"繼續輸血，待血壓穩定後重覆腦部電腦斷層攝影。"}],"answer":"C","expl":"同 109-27：肝臟大量出血且血壓再度下降，應優先剖腹控制出血，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-43","year":112,"qnum":43,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關 診斷性腹腔灌洗術之結果判讀之陽性敘述何者為非？","opts":[{"k":"A","t":"反抽出血液≧10ml。"},{"k":"B","t":"流出液紅血球≧500,000/mm 3。"},{"k":"C","t":"流出液白血球≧500/mm 3 。"},{"k":"D","t":"流出液格蘭氏染色發現細菌存在。"},{"k":"E","t":"流出液發現腸道內容物或膽汁。"}],"answer":"B","expl":"同 107-34：DPL 陽性標準 RBC ≥100,000/mm³（鈍傷），而非 500,000，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-44","year":112,"qnum":44,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"30 歲男性於工作時由 4 公尺高之平台跌落至地面，送抵急診時意識混亂、心跳為150/min、收縮血壓 60mmHg，病患外觀無明顯出血及四肢變形，超音波檢查並無發現有血胸、心包膜積血或腹腔內出血，骨盆檢查發現為不穩定之骨盆骨折，經緊急氣管內管置入、輸液 2,000cc 並使用床單固定骨盆後，心跳及血壓皆無改善；若本院並無可執行動脈栓塞之能力，且將病患轉診至最近可執行動脈栓塞之 B 醫院需時 60 分鐘，以下處置何者最適當？","opts":[{"k":"A","t":"通知 B 醫院並準備 10 單位之全血，立即將病患立即轉院。"},{"k":"B","t":"安排電腦斷層檢查查看是否有其他損傷。"},{"k":"C","t":"通知外科醫師執行雙側髂內動脈結紮手術。"},{"k":"D","t":"先執行 preperitoneal packing 並重新以床單固定骨盆後，將病患立即轉院。"},{"k":"E","t":"以上皆可。"}],"answer":"D","expl":"不穩定骨盆骨折、FAST 陰性、對輸液與骨盆固定無反應，且無法就地做血管栓塞，依官方答案應先做 preperitoneal packing 並重新固定骨盆，再轉院，所以 (D)。","outdated":true,"suspect":false,"flagNote":"題幹「輸液 2,000 cc」超出現行 ATLS 10/11 建議（初始約 1 L 後盡快輸血）；官方答案 (D) 不變。原官方答案維持 (D)，僅供臨床與新版指引對照。","images":[]},{"id":"112-45","year":112,"qnum":45,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"30 歲男性，酒後開車撞樹，送達急診時 GCS 為 E2M4V2，SBP 60 mm-Hg；F.A.S.T.發現腹腔內有大量液體積聚；目前聯絡不到任何家屬。下列敘述何者正確？","opts":[{"k":"A","t":"須緊急手術，請社工簽同意書。"},{"k":"B","t":"須緊急手術，由兩位醫師在手術同意書上簽名。"},{"k":"C","t":"須緊急手術，由負責醫師在病歷上寫明手術適應症(indication)、傷患情況危急且無人可以執行代理同意後手術，不簽同意書。"},{"k":"D","t":"須緊急手術，請警衛簽同意書。"},{"k":"E","t":"以上皆正確。"}],"answer":"C","expl":"緊急危及生命且找不到家屬或代理人時，可依緊急情況（醫療法緊急處置規定）先手術，由負責醫師在病歷詳細記載適應症與無法取得同意的原因，不應找社工、警衛簽名，所以 (C)。法條細節請以現行規定為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-46","year":112,"qnum":46,"topic":"總論評分","subtopic":"槍傷彈道與穿刺傷處置原則","stem":"下列有關槍傷的敘述何者為非？","opts":[{"k":"A","t":"槍傷的經過路徑(trajectory)ㄧ般比刀傷更加難以預測。"},{"k":"B","t":"槍傷經過路徑(trajectory)對周圍組織的傷害ㄧ般比刀傷更嚴重。"},{"k":"C","t":"治療槍傷時，以直線原則預測經過路徑(trajectory)可達 90%以上的準確率。"},{"k":"D","t":"治療槍傷的基本原則與刀傷同，仍依高級外傷救命術精神為主。"},{"k":"E","t":"ㄧ般槍傷的進口(entrance)，相對出口(exit)有較嚴重的周圍擦傷。"}],"answer":"C","expl":"同 108-45：槍傷的彈道常偏折，直線預測不可靠，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-47","year":112,"qnum":47,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"對於懷孕外傷病患的診治，影像學檢查往往不可或缺。但是放射暴露對懷孕胎兒又有畸胎的危險，尤以懷孕 8~15 週子宮內胎兒最易受傷害。下列何種常規 X 光檢查，對孕婦子宮與胎兒，放射暴露量(Radiation Exposure)最大？","opts":[{"k":"A","t":"胸部 X-光。"},{"k":"B","t":"頭部電腦斷層(Brain CT scan) 。"},{"k":"C","t":"腹部 X-光(KUB)加(IVP series) 。"},{"k":"D","t":"腰椎 X-光(lumbar spine 兩張) 。"},{"k":"E","t":"胸部電腦斷層(Chest CT scan) 。"}],"answer":"C","expl":"孕婦影像檢查輻射暴露：KUB 加 IVP 系列的子宮與胎兒劑量最大（相較於胸部 X 光、頭部 CT、腰椎 X 光與胸部 CT）；必要時仍不要因擔心輻射而延遲診斷，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-48","year":112,"qnum":48,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"下列有關胸部外傷之敘述何者為非？","opts":[{"k":"A","t":"鏈伽胸(Flail chest)造成缺氧主要機轉為胸部不正常呼吸運動(paradoxical movement)影響氣體交換。"},{"k":"B","t":"當胸管放置後，引流血量大於 1500 毫升稱為大量血胸，頓挫傷及穿刺傷都可能造成大量血胸，其中以穿刺傷為主要造成原因。"},{"k":"C","t":"有關急診行緊急剖胸術，胸部穿刺性外傷患者較鈍傷患者有較好之預後，如果傷患在事故現場已無生命跡象，則不應再行剖胸術急救，因其成效有限。"},{"k":"D","t":"嚴重胸部外傷而影響循環(circulation)常見的原因為大量血胸及心包膜填塞。"},{"k":"E","t":"創傷性膈疝(Traumatic Diaphragmatic Hernia)左側比較容易發生，急性期手術治療宜採剖腹探查術；慢性外傷性橫膈疝氣手術治療以從胸部探查較佳。"}],"answer":"A","expl":"同 100-13：flail chest 低血氧主要來自疼痛造成換氣受限與下方 pulmonary contusion，paradoxical movement 本身不是主因，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-49","year":112,"qnum":49,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"何者不是 damage control operation 時該做的步驟？","opts":[{"k":"A","t":"肝臟周圍(perihepatic)packing。"},{"k":"B","t":"腹部靜脈結紮(ligation)。"},{"k":"C","t":"部分腸切除，不接合。"},{"k":"D","t":"大腸造口(colostomy)。"},{"k":"E","t":"胰臟頭頸部實質或胰管損傷時用 closed-suction drain 引流。"}],"answer":"D","expl":"Damage control 手術：packing、血管結紮或暫時性分流、腸切除不接合、暫時關腹、胰臟用 closed-suction drain；大腸造口屬於後續 definitive 步驟，通常不在第一次 damage control 做，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"112-50","year":112,"qnum":50,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤？","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"C","t":"蛋白質的建議劑量為 1.2 to 2.0 g/kg/day，燒燙傷患者更可高於 2.0g/kg/day。"},{"k":"D","t":"熱量的建議為 25 to 30 kcal/kg/day。為讓及早達到總熱量的目標值，若腸道營養攝取不夠，應於受傷後第一天儘早給予靜脈營養，以及早達到 100%每天熱量需求量。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control (≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"D","expl":"同 111-16：不建議在受傷第一天就用 PN 補足 100% 熱量，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-1","year":113,"qnum":1,"topic":"休克輸血","subtopic":"Lethal triad（致命三角）","stem":"相對於傳統的致命三角(lethal triad)，在現代急救技術越發進步之下，我們會遇到致命鑽石(lethal diamond)，其中新加入的元素是下列何者？","opts":[{"k":"A","t":"Hypothermia。"},{"k":"B","t":"Acidosis。"},{"k":"C","t":"Hypocalcemia。"},{"k":"D","t":"Hyperkalemia。"},{"k":"E","t":"Coagulopathy。"}],"answer":"C","expl":"同 112-1：Lethal diamond 在 hypothermia、acidosis、coagulopathy 之外加入 hypocalcemia，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-2","year":113,"qnum":2,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"下列有關老人外傷之敘述何者為非？","opts":[{"k":"A","t":"老人較無法承受缺氧狀態，故面對外傷後休克的個案需盡快插管。"},{"k":"B","t":"老人對胸部外傷的耐受性較差，單純肋骨骨折或肺部挫傷也可能導致呼吸衰竭。"},{"k":"C","t":"老人外傷最常見的外傷機轉是跌倒。"},{"k":"D","t":"老人有較多比例具有冠狀動脈疾病，同時全身總血量也隨年紀逐漸降低，故外傷出血休克者常常呈現明顯心搏過速(tachycardia)的現象。"},{"k":"E","t":"因為老人常有高血壓的問題，故單純以血壓來判斷失血量常會誤判。"}],"answer":"D","expl":"同 112-14：老年人因藥物與自主神經反應差，出血休克時不一定明顯心搏過速，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-3","year":113,"qnum":3,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"下列有關終結(termination)大量輸血的 protocol 於 society recommendations of Task Force for Advanced Bleeding Care in Trauma 於 laboratory result-guide model of resuscitation 中其相關目標值的敘述何者不正確？","opts":[{"k":"A","t":"Hb 控制介於 7-9 g/dL。"},{"k":"B","t":"PT , aPTT 小於 1.5 倍。"},{"k":"C","t":"PLT > 50 X 103/uL。"},{"k":"D","t":"Fibrinogen > 1.5 – 2.0 g/L。"},{"k":"E","t":"Base excess < -2。"}],"answer":"E","expl":"同 112-27：大量輸血終止的目標：Hb 7–9、PT/aPTT <1.5 倍、血小板 >50、fibrinogen >1.5–2.0 g/L；base excess 目標應接近正常，「< −2」不正確，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-4","year":113,"qnum":4,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"何者不是 damage control operation 時該做的步驟？","opts":[{"k":"A","t":"肝臟周圍(perihepatic)packing。"},{"k":"B","t":"腹部靜脈結紮(ligation)。"},{"k":"C","t":"部分腸切除，不接合。"},{"k":"D","t":"大腸造口(colostomy)。"},{"k":"E","t":"胰臟頭頸部實質或胰管損傷時用 closed-suction drain 引流。"}],"answer":"D","expl":"同 112-49：大腸造口屬 definitive 步驟，不在第一次 damage control 做，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-5","year":113,"qnum":5,"topic":"小兒","subtopic":"總論／其他","stem":"三歲幼兒外傷送至急診，逐漸出現呼吸窘迫、神智昏睡時，下列的敘述最不適當的是：","opts":[{"k":"A","t":"幼兒胸部骨質結構尚未完全，縱使沒有肋骨骨折也可能氣胸或血胸。"},{"k":"B","t":"幼兒對張力性氣胸的治療，縱生理結構與成人不同，但治療原則相同。"},{"k":"C","t":"幼兒對張力性氣胸耐受力(tolerable)差，易造成休克。"},{"k":"D","t":"幼兒不考慮使用藥物引導插管(drug-assisted)，應考慮外科氣道切開術。"},{"k":"E","t":"幼兒呼吸靠橫膈運動為主，但對舒醒球呼吸(bag-masker ventilation)效果佳。"}],"answer":"D","expl":"同 109-12：3 歲幼兒仍可依 ATLS 做 RSI 並預備 surgical airway 作為備案，所以 (D) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-6","year":113,"qnum":6,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤？","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"C","t":"蛋白質的建議劑量為 1.2 to 2.0 g/kg/day，燒燙傷患者更可高於 2.0g/kg/day。"},{"k":"D","t":"熱量的建議為 25 to 30 kcal/kg/day。為讓及早達到總熱量的目標值，若腸道營養攝取不夠，應於受傷後第一天儘早給予靜脈營養，以及早達到 100%每天熱量需求量。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"D","expl":"同 111-16：不建議在受傷第一天就用 PN 補足 100% 熱量，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-7","year":113,"qnum":7,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於微創手術應用於腹部外傷之敘述，何者有誤？","opts":[{"k":"A","t":"雖然有文獻指出微創手術能夠應用於腹部外傷合併休克之患者，但相對穩定的生命徵象仍被認為是腹部外傷患者能否接受微創手術的先決條件。"},{"k":"B","t":"對於腹部鈍傷後，影像學檢查無法解釋臨床表現的患者(unclear abdomen)，可考慮進行腹腔鏡探查手術。"},{"k":"C","t":"針對腹部外傷進行之微創手術，能降低非治療性剖腹手術(non-therapeutic laparotomy)之可能性，從而降低併發症及整體醫療費用，故不論機構的照護能力或外科醫師的經驗如何，都應該選擇微創手術治療患者。"},{"k":"D","t":"對於合併有顱內損傷之腹部外傷患者，腹腔鏡手術進行的過程可能導致患者顱內壓上升，故需謹慎評估是否適合採行微創手術治療腹部損傷。"},{"k":"E","t":"氣體栓塞(venous gas embolism)雖然罕見，但卻有極高的死亡率。手術中一旦懷疑氣體栓塞的發生，第一步應立即停止手術並移除腹腔氣體以減低腹內壓。"}],"answer":"C","expl":"同 111-23：微創手術於腹部外傷需視病人穩定度、機構與醫師經驗，並非不論條件都應選擇，所以 (C) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-8","year":113,"qnum":8,"topic":"胸部","subtopic":"VATS／ECMO","stem":"有關 ECMO 在 Traumatic lung injury 之敘述，何者為非 ?","opts":[{"k":"A","t":"ECMO 使用於 traumatic lung injury 需考慮 coagulopathy 及 systemic heparinization之因素。"},{"k":"B","t":"ECMO 使用於 traumatic lung injury，目前已發表較大之 series study，其 survival rate約為 60~80%之間。"},{"k":"C","t":"針對此類病患即使沒有顱內出血亦不可使用 anticoagulant therapy。"},{"k":"D","t":"針對此類病患中接受胸腹部手術之病患有較高之死亡率。"},{"k":"E","t":"使用呼吸器超過 48 小時外傷病患最常見之併發症之一為 Acute respiratory distress syndrome 。"}],"answer":"C","expl":"同 111-31：ECMO 用於創傷肺損傷需權衡凝血病變與全身肝素；無顱內出血時仍可抗凝，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-9","year":113,"qnum":9,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"根據現有之臨床指引及臨床研究證據，下列哪一位病患適合在急診現場放置 REBOA (Resuscitative Endovascular Balloon Occlusion of the Aorta) 且最可能獲得 survival benefit?","opts":[{"k":"A","t":"三十歲健康男性腹部及右胸近距離槍傷，十分鐘內即上救護車送醫，現於檢傷發現血壓量不到。"},{"k":"B","t":"二十歲健康男性頭部鈍傷及左胸穿刺傷，電腦斷層發現雙側大腦大面積腦出血及 cardia c tem po nade ； 於 電 腦 斷 層 室 送 回 急 診 的 途 中 失 去 生 命 徵 象 。"},{"k":"C","t":"六十歲男性，有高血壓及 6 公分腹主動脈瘤；因腹部鈍傷造成腹主動脈瘤破裂，低血容性休克，現於急診現場 resuscitation。"},{"k":"D","t":"五十歲男性，肝硬化及凝血功能異常；左胸穿刺傷合併大量氣血胸，胸管置入後流出 1800ml 鮮血。對 resuscitation 無反應逐漸失去生命徵象。"},{"k":"E","t":"十八歲健康女性嚴重骨盆骨折合併大量骨盆腔出血；在等候血管栓塞時進展至低血容性休克而後失去意識。"}],"answer":"E","expl":"同 110-14：REBOA 最適合不能壓迫止血的骨盆或腹部出血，如嚴重骨盆骨折合併休克，所以 (E)。胸部出血與頭部出血病人不適合。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-10","year":113,"qnum":10,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"一名患者遭受到骨盆槍傷，手術中發現在左側髂總動脈有 50% 橫斷。儘管夾住了左髂總動脈近端和左髂外動脈近端，但仍有持續出血。 最合適的下一步是什麼？","opts":[{"k":"A","t":"Clamp the left common iliac vein."},{"k":"B","t":"Clamp the left internal iliac artery."},{"k":"C","t":"Clamp the aorta just above its bifurcation."},{"k":"D","t":"Pack the pelvis and proceed to angiography."},{"k":"E","t":"performed the graft bypass surgery."}],"answer":"D","expl":"同 110-24：髂總動脈 50% 橫斷、近遠端夾住後仍出血，常為 internal iliac 或 back-bleeding；先 packing 骨盆並轉血管攝影，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-11","year":113,"qnum":11,"topic":"頭部TBI","subtopic":"輕度頭部外傷 CT 適應症（Canadian CT Head Rule）","stem":"評估腦部外傷的 Canadian head CT rule 不包括下例何者：","opts":[{"k":"A","t":"臉部撕裂傷。"},{"k":"B","t":"GCS 未達 15 分。"},{"k":"C","t":"年紀大於 65 歲。"},{"k":"D","t":"持續嘔吐。"},{"k":"E","t":"顱骨是否有凹陷性骨折。"}],"answer":"A","expl":"同 110-38：Canadian CT Head Rule 不含臉部撕裂傷，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-12","year":113,"qnum":12,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射 4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"同 108-44：central cord syndrome（上肢重於下肢），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-13","year":113,"qnum":13,"topic":"災難院前法規","subtopic":"傷害預防（3E）／流行病學／死因統計","stem":"對於 injury prevention 的對策一般有 3E，(1)enforcement and legalization (2)education and behavior change (3)engineering and environmental modification，請問何者是最有效的作為？","opts":[{"k":"A","t":"Enforcement and legalization。"},{"k":"B","t":"Education and behavior change。"},{"k":"C","t":"Engineering and environmental modification。"},{"k":"D","t":"三者皆一樣有效。"},{"k":"E","t":"三者皆無顯著之效。"}],"answer":"B","expl":"官方答案為 (B) Education and behavior change。","outdated":false,"suspect":true,"flagNote":"同 109-3、111-2：傷害預防文獻通常認為被動式的 engineering and environmental modification（如安全氣囊、護欄、道路設計）效果最持久，所以 (C) 似乎比 (B) 更合理；官方答案可能有誤，請依官方答案作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"113-14","year":113,"qnum":14,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"經輸血後血壓逐漸恢復至 108/76mmHg，同時腹部超音波發現腹腔有大量積液，胸部 X 光發現右側多發性肋骨骨折與氣血胸，右膝骨折合併右小腿血循不良。此時下列何者應該最優先施行?","opts":[{"k":"A","t":"放置右側胸管引流氣血胸。"},{"k":"B","t":"進行電腦斷層檢查，應至少檢查頭頸部與腹部。"},{"k":"C","t":"安排開刀房準備手術。"},{"k":"D","t":"安排右下肢血管攝影以確認血循受阻的位置。"},{"k":"E","t":"安排加護病房繼續治療。"}],"answer":"A","expl":"同 109-26：確認右側氣血胸後最優先是放置胸管引流（病情可能快速惡化），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-15","year":113,"qnum":15,"topic":"四肢血管骨科","subtopic":"周邊神經評估","stem":"下列有關肢體部位 peripheral nerve 評估之敘述何者為非？","opts":[{"k":"A","t":"手肘部位受傷，同側小指感覺異常且無法外展，要懷疑尺神經受損。"},{"k":"B","t":"遠端肱骨骨折，且 drop wrist 垂腕或大拇指無法 extension，要懷疑正中神經受損。"},{"k":"C","t":"肩關節脫臼，肩膀外側感覺異常，且 Deltoid 無力，要懷疑腋神經 axillary nerve受損。"},{"k":"D","t":"髖關節後位脫臼，且垂足致腳踝無法背屈，要懷疑坐骨神經 sciatica nerve 受損。"},{"k":"E","t":"膝關節脫臼或近端腓骨骨折，且外側足背感覺異常，要懷疑腓淺神經 superficial peroneal nerve 受損。"}],"answer":"B","expl":"同 108-21：垂腕與拇指無法伸直是 radial nerve 受損，而非 median nerve，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-16","year":113,"qnum":16,"topic":"顏面頸部","subtopic":"頸部穿刺傷 zone 分區與處置","stem":"有關於 neck penetrating injury，下列敘述何者為非？","opts":[{"k":"A","t":"Zone II 區域比 Zone I 或 Zone III 區域更容易進行外科介入性治療(surgical intervention)。"},{"k":"B","t":"Zone III 區域因位置靠近 thoracic outlet 血管區，故手術時常需作 median sternotomy 或 clavicle resection。"},{"k":"C","t":"在 Zone I 或 Zone III 區域，arteriography 通常被認為是可被接受的檢查，來檢視大血管是否被傷害。"},{"k":"D","t":"因頸部食道傷害延遲診斷超過 12 小時，其死亡率可高達 17%。"},{"k":"E","t":"用 esophagography 來診斷食道破裂，其敏感度 (sensitivity)約為 70-80%。"}],"answer":"B","expl":"同 106-14：median sternotomy 與 clavicle resection 屬 Zone I，不是 Zone III，所以 (B) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-17","year":113,"qnum":17,"topic":"災難院前法規","subtopic":"總論／其他","stem":"有關外傷病人到院前之敘述及處置何者最不合理？","opts":[{"k":"A","t":"對頭部外傷且失去意識的患者，目前最新的大型臨床研究顯示由 EMT 在事故現場 或運送途中盡早以 RSI 進行氣管內插管對病人之預後較有幫助。"},{"k":"B","t":"若已插上氣管內管，在運送過程中若有搬運病人則應在搬運後以聽診或 end-tidal CO2 監測器確定氣管內管位置。"},{"k":"C","t":"大量出血之病患可在運送途中由受過訓練之 EMT 人員建立 peripheral IV line 並給予基本的靜脈輸液。"},{"k":"D","t":"若 peripheral IV line 建立困難，也可由受過訓練之 EMT 人員建立 interosseous (IO)line。"},{"k":"E","t":"針對四肢大量出血且壓迫止血無效的病患，應由受過訓練之 EMT 人員適當使用止血帶 (tourniquet)。"}],"answer":"A","expl":"同 108-2：到院前頭部外傷由 EMT 以 RSI 插管，大型研究並未顯示改善預後，所以 (A) 最不合理。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-18","year":113,"qnum":18,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"下列對 spinal cord injury 造成 neurologic shock 的敍述何者錯誤？","opts":[{"k":"A","t":"受影響的軀幹會出現 flaccidity 和 loss of reflex 的症狀。"},{"k":"B","t":"Spinal cord injury 的 level 要在 T6 以上。"},{"k":"C","t":"Peripheral blood vessel dilatation。"},{"k":"D","t":"病人會出現 bradycardia and hypotension。"},{"k":"E","t":"以上皆正確。"}],"answer":"A","expl":"同 108-19：Neurogenic shock 為交感張力喪失造成血管擴張、低血壓、心搏過緩；軀幹 flaccid 與反射消失是 spinal shock 的神經學表現，所以 (A) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-19","year":113,"qnum":19,"topic":"休克輸血","subtopic":"輸血併發症（TRALI 等）","stem":"關於輸血相關急性肺損傷(Transfusion- Related Acute Lung Injury, TRALI)之診斷與治療，何者正確？","opts":[{"k":"A","t":"若 BNP (B-natriuretic peptide) >200 pg/ml，一定可以排除 TRALI。"},{"k":"B","t":"TRALI 因為有肺水腫、高血壓，所以對利尿劑反應佳。"},{"k":"C","t":"TRALI 因為是發炎反應，所以對類固醇效果很好。"},{"k":"D","t":"TRALI 發生率於單一捐血者(single donor)的血小板比隨機捐血者(random donor)血小板高。"},{"k":"E","t":"以上皆正確。"}],"answer":"D","expl":"同 105-7：TRALI 不能單靠 BNP 排除；利尿劑與 steroid 無明確療效；官方答案 (D)：單一捐血者血小板的 TRALI 發生率較隨機捐血者高。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-20","year":113,"qnum":20,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有關老年外傷病患與一般成年外傷病患的差異，請選出正確者：","opts":[{"k":"A","t":"老年病患生理儲備 physiologic reserve 較為有限，所以休克時的表現會比一般成年人要早，也比較敏感。"},{"k":"B","t":"老年病患對低血氧 Hypoxia 與低容積 Hypovolemia 的忍受度較高，所以心跳與血壓較不容易產生變化。"},{"k":"C","t":"老年病患由於頸椎的退化性變化使得頸部活動性減低，因此頸椎受傷的機率較一般成年人為低。"},{"k":"D","t":"老年病患發生休克時，可能因先前已有的疾病或藥物，而使得血壓與心跳看似仍在「正常」範圍。"},{"k":"E","t":"以上皆不正確。"}],"answer":"D","expl":"同 108-48：老年病人可能因疾病或藥物（如 beta blocker）使血壓與心跳看似正常，掩蓋休克，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-21","year":113,"qnum":21,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"根據第十版 ATLS 對於胸部外傷處理下列何者正確?\n1. 張力性氣胸針刺減壓 Needle decompression of pneumothorax 成人改為第五肋間腋中線或前線。\n2. 小兒為鎖骨中線第二肋間下緣。\n3. 血胸胸管選擇為 36-40 Fr。\n4. 大量血胸時可給予斷血炎注射液 Tranexamic acid 1g over 10 min stat and 1g over8h given within 3h。","opts":[{"k":"A","t":"1+3。"},{"k":"B","t":"2+4。"},{"k":"C","t":"1+2+3。"},{"k":"D","t":"1+2 +4。"},{"k":"E","t":"1+2+3+4。"}],"answer":"D","expl":"同 107-1：ATLS 10：成人 needle decompression 改為第 5 肋間腋前線至中線；兒童鎖骨中線第 2 肋間；胸管為 28–32 Fr（不是 36–40 Fr）；TXA 依 CRASH-2。所以 1、2、4 正確，答案 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-22","year":113,"qnum":22,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在腹部閉合性損傷行緊急手術治療時，若未知明確受傷部位，則應進行探查的順序為何呢？","opts":[{"k":"A","t":"肝、脾等實質性器官→胃→十二指腸第一部→空腸→回腸→大腸及它們的系膜→盆腔器官。"},{"k":"B","t":"肝、脾等實質性器官→十二指腸第一部→胃→回腸→空腸→大腸及它們的系膜→盆腔器官。"},{"k":"C","t":"肝、脾等實質性器官→橫隔肌→胃→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"D","t":"胃→肝、脾等實質性器官→橫隔肌→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"},{"k":"E","t":"胃→橫隔肌→肝、脾等實質性器官→十二指腸第一部→空腸→回腸→大腸以及它們的系膜→盆腔器官。"}],"answer":"C","expl":"同 105-8：探查順序為肝、脾 → 橫隔肌 → 胃 → 十二指腸第一部 → 空腸 → 回腸 → 大腸及系膜 → 盆腔器官，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-23","year":113,"qnum":23,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"燒傷治療的相關議題中，下列何者描述最不合適?","opts":[{"k":"A","t":"燒傷輸液量的預估量在第一天通常以 2x 體重(公斤)x 燒傷面積(%)來估計，其中一半的輸液量預計在受傷後 8 小時輸完。"},{"k":"B","t":"燒傷造成呼吸道的窘迫只會發生在有吸入性灼傷的病人。"},{"k":"C","t":"化學性灼傷可以分為酸性、鹼性及有機酸灼傷。"},{"k":"D","t":"電燒傷依電壓分為高壓電以及低壓電的電灼傷。"},{"k":"E","t":"環形第三度燒灼傷的部位必須儘早執行焦痂切開術(escharotomy)。"}],"answer":"B","expl":"燒傷的呼吸道窘迫不只發生於吸入性灼傷：頸部與顏面燒傷水腫、胸壁環形焦痂限制換氣、一氧化碳中毒等都可能造成，所以 (B)「只會發生在吸入性灼傷」為不合適。(A) 2 mL/kg/%TBSA（ATLS 10）；(E) 環形焦痂需 escharotomy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-24","year":113,"qnum":24,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"一名 24 歲男性，夜晚騎重型機車自撞電線桿後意識不清，由救護車自地區醫院轉送至有外傷中心且有良好設備的大型醫院急診室。患者已在外院放置好氣管內管，到院時血壓 72/48mmHg，心跳速率 131/min，GCS 為 E1M1V1，外傷專科醫師已到現場。床邊超音波檢查發現有左側肋膜大量積液及大量腹水，遂放置左側胸管，同時輸血，左側胸管一下子就引流出 2000mL 血液。血壓於輸血後提升至 85/68mmHg，心跳速率 125/min，已準備將傷患轉送至手術房進行搶救手術，此時患者突然發生心跳停止，摸不到脈搏，且量不到血壓。在此情境中，身為在場的外傷專科醫師，下列處置，何者較適當？","opts":[{"k":"A","t":"開始 CPR，待有 ROSC(return of spontaneous circulation)後，再盡快轉送至手術房做搶救手術。"},{"k":"B","t":"開始 CPR，待有 ROSC 後，盡快安排血管栓塞(angioembolization)止血。"},{"k":"C","t":"做 resuscitative thoracotomy 以做 aortic clamping、視情況加做 left lung pedicle clamping，及 open cardiac massage，有 ROSC 後盡快轉送至開刀房做搶救手術。"},{"k":"D","t":"開始 CPR，同時立刻將患者送至手術房做搶救手術。"},{"k":"E","t":"從 femoral artery 放置 REBOA(resuscitative endovascular balloon occlusion of the aorta)，有 ROSC 後再盡快轉送至開刀房做搶救手術。"}],"answer":"C","expl":"胸管立即引流 2,000 mL 血液、輸血後仍心跳停止，應立即 resuscitative thoracotomy（aortic clamping、肺門鉗夾、open cardiac massage），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-25","year":113,"qnum":25,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"脊髓損傷可分為完全性脊髓損傷(complete spinal cord injury)與不完全性脊髓損傷(Incomplete spinal cord injury)，下列敘述何者為非？","opts":[{"k":"A","t":"中索症候群(central cord syndrome) ，臨床上常造成上肢障礙比下肢明顯，電腦斷層不一定看到頸椎骨折或移位。"},{"k":"B","t":"前索症候群(anterior cord syndrome)，造成損傷平面以下的運動和痛、溫覺喪失，本體感覺存在；四肢癱瘓，臨床上常造成上肢障礙比下肢明顯。"},{"k":"C","t":"後索症候群(posterior cord syndrome)，造成損傷平面以下本體感覺喪失，而運動和痛、溫覺存在。"},{"k":"D","t":"布朗塞卡氏症候群(Brown-Séquard syndrome) 表現病變平面以下對側痛、溫覺喪失，同側深感覺喪失及上運動神經元癱瘓。"},{"k":"E","t":"馬尾症候群(cauda equina syndrome): 導致頻尿、尿失禁、下肢感覺異常。"}],"answer":"B","expl":"Anterior cord syndrome：損傷平面以下運動與痛溫覺喪失，本體覺保留；「上肢重於下肢」是 central cord syndrome 的特徵，不是前索症候群，所以 (B) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-26","year":113,"qnum":26,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"下列有關 Nutritional Support in surgical critically ill patients with hepatic failure，何者敘述不正確?","opts":[{"k":"A","t":"大部分的 nutritional guidance 和 critically ill patients 差不多。"},{"k":"B","t":"在 liver surgery and liver transplantation 的病患之 postoperative nutrition，建議能量及蛋白質之給予可達 35 kcal/kg.BW/day 及 1.5g/kg.BW/day。"},{"k":"C","t":"文獻顯示，給予 BCAA(Branch chain amino acids )明顯增進病患預後。"},{"k":"D","t":"肥胖的病患，如果合併 acute liver failure，死亡風險高。"},{"k":"E","t":"Heart failure 的病患若有 hyperbilirubinemia，一般常見是 congestive hepatopathy引起，應先考慮處理 heart 之問題。"}],"answer":"C","expl":"肝衰竭病人的營養：BCAA 未明確增進預後（可用於肝性腦病變不耐受蛋白質時），所以 (C) 不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-27","year":113,"qnum":27,"topic":"災難院前法規","subtopic":"總論／其他","stem":"一名 45 歲男性從 20 英尺高處墜落，被送至資源有限的地區醫院。症狀包括意識模糊、皮膚蒼白、出冷汗、右側胸部呼吸音減弱、叩診為鼓音(Hyperresonance)、腹部腫脹、骨盆不穩定。生命徵象顯示心率每分鐘 140 次，血壓 80/60 mmHg，呼吸速率每分鐘 36 次，氧飽和度為 88%。急診室有移動 X 光機和 CT 設備，但外科醫師正在手術中，無法確認何時才能結束手術。最近的創傷中心距離 2 小時車程。在這種資源受限且時間緊迫的情況下，以下哪項是最合適且優先的初步處置組合？","opts":[{"k":"A","t":"立即氣管插管、使用骨盆固定帶、FAST 超音波、準備緊急開腹手術。"},{"k":"B","t":"大量輸液、CXR、使用升壓劑、等待外科醫師手術結束。"},{"k":"C","t":"使用骨盆固定帶、右側 finger thoracostomy、輸血並轉診至創傷中心。"},{"k":"D","t":"右鎖骨中線 needle decompression、中心靜脈導管置放、安排腹部 CT。"},{"k":"E","t":"放置 REBOA(Resuscitative Endovascular Balloon Occlusion of the Aorta )、靜脈注射 tranexamic acid(TXA)、啟動大量輸血、安撫家屬情緒。"}],"answer":"C","expl":"資源有限、休克、右胸鼓音（疑張力性氣胸）、骨盆不穩定：先骨盆固定帶、右側 finger thoracostomy（減壓）、輸血並盡早轉診到創傷中心，所以 (C)。補充：REBOA 與等待手術都不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-28","year":113,"qnum":28,"topic":"氣道","subtopic":"總論／其他","stem":"一名汽車駕駛在車禍現場被急救人員確認為嚴重頭部外傷，且無法維持呼吸道暢通，隨即接受了經口氣管插管。病患抵達急診室時，呈現去大腦皮質反應。使用 Ambu氣囊進行通氣時，左側胸腔聽不到呼吸音且左側胸廓呼吸時沒有起伏。其血壓為160/80 mmHg，心率每分鐘 100 次，氧飽和度為 86%。下一步應進行的評估和處置是：","opts":[{"k":"A","t":"確認動脈血氣分析。"},{"k":"B","t":"進行側位頸椎 X 光檢查。"},{"k":"C","t":"評估氣管內管的位置。"},{"k":"D","t":"進行左側胸腔針刺減壓。"},{"k":"E","t":"插入左側胸管。"}],"answer":"C","expl":"插管後左胸無呼吸音、無起伏，最常見是管子插入右主支氣管（DOPE），所以先評估氣管內管位置，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-29","year":113,"qnum":29,"topic":"胸部","subtopic":"總論／其他","stem":"一名 24 歲男性在胸部被刺傷約 30 分鐘後被送至醫院。胸部左側乳頭內側有一 3公分的傷口。其血壓為 70/40 mmHg，心率為每分鐘 140 次。身體檢查顯示頸靜脈怒張、雙側呼吸音正常、心音低弱。以下哪一項對於診斷和處理此患者的傷勢最有幫助？","opts":[{"k":"A","t":"胸部電腦斷層掃描。"},{"k":"B","t":"12 導程心電圖。"},{"k":"C","t":"插入左側胸管。"},{"k":"D","t":"輸注升壓劑。"},{"k":"E","t":"FAST exam。"}],"answer":"E","expl":"胸部左側乳頭內側刺傷（心臟危險區）、休克、頸靜脈怒張、心音低弱，為心包填塞（Beck triad），FAST 最快速確認，所以 (E)。CT 與升壓劑不適合。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-30","year":113,"qnum":30,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"30 歲的女性，懷孕 30 週，發生自 5 樓墜樓事故後送至醫院，孕婦到院時血壓 70/40 mmHg，心跳 130/min，Glasgow Coma Scale Score 為 8 分，經 Resuscitation 及primary survey 後，腹部超音波顯示腹腔內有大量液體，經緊急會診產科醫師後發現無胎心音，此時孕婦血壓回到 95/70 mmHg，電腦斷層顯示疑似子宮破裂併胎兒外露至孕婦的腹腔和大量腹腔內積液堆積，以下敘述及處置，何者較不適當？","opts":[{"k":"A","t":"立刻給予升壓劑。"},{"k":"B","t":"孕婦動脈血的 PaCO2 的正常數值範圍在 25-30 mmHg。"},{"k":"C","t":"孕婦的 Fibrinogen 的正常數值範圍在 400-450 mg/dL。"},{"k":"D","t":"立刻給予 Tranexamic acid 1gm IV，並持續輸血，且聯絡開刀房，立即安排入開刀房進行手術治療。"},{"k":"E","t":"孕婦動脈血的 Hematocrit 的正常數值範圍在 32%~42%。"}],"answer":"A","expl":"孕婦出血性休克應以補充血量與止血為主，不是先給升壓劑，所以 (A) 較不適當。補充：孕婦 PaCO2 正常約 28–32 mmHg，fibrinogen 約 400–450 mg/dL，Hct 約 32–42%。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-31","year":113,"qnum":31,"topic":"災難院前法規","subtopic":"總論／其他","stem":"有關外傷病人到院前之敘述何者正確？","opts":[{"k":"A","t":"對頭部外傷且失去意識的患者，不宜由受過足夠訓練之 EMT 在事故現場或運送途中盡早以 RSI 進行氣管內插管。"},{"k":"B","t":"若已插上氣管內管，在運送過程中若有搬運病人則應在搬運後以聽診或 end-tidal CO2 監測器確定氣管內管位置。"},{"k":"C","t":"針對四肢大量出血且壓迫止血無效的病患，應由受過訓練之 EMT 人員適當使用止血帶 (tourniquet)。"},{"k":"D","t":"若 peripheral IV line 建立困難，也可由受過訓練之 EMT 人員建立 interosseous (IO)line。"},{"k":"E","t":"以上皆正確。"}],"answer":"E","expl":"同 108-2、113-17：到院前頭部外傷不宜常規由 EMT 以 RSI 插管；搬運後確認管位；大量四肢出血用 tourniquet；IO 可由 EMT 建立，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-32","year":113,"qnum":32,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"40 歲男性工地跌倒造成右側下肢被鋼筋穿刺傷，下列何者處置較不適當?","opts":[{"k":"A","t":"進行初級評估時若傷口正在出血首先應考慮局部壓迫止血或者使用止血帶止血。"},{"k":"B","t":"進行次級評估時應評估是否有動脈受傷之跡象，如動脈脈動消失或遠端肢體冰冷等。"},{"k":"C","t":"Ankle Brachial Index (ABI) > 0.9，則應該考慮是否有血管受損。"},{"k":"D","t":"懷疑股神經(femoral nerve) 有受傷，可測試膝關節伸展(knee extension)以評估功能。"},{"k":"E","t":"如果傷口出血合併有骨折移位變形應該考慮將患肢徒手復位後固定。"}],"answer":"C","expl":"ABI <0.9 才懷疑血管損傷，「>0.9」描述錯誤，所以 (C) 為非。注意：關於 (E) 徒手復位後固定，在動脈損傷與脈搏消失時，復位並固定是常見處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-33","year":113,"qnum":33,"topic":"休克輸血","subtopic":"Damage control resuscitation／MTP／血品比例","stem":"56 歲女性，於斑馬線被轉彎的公車輾過，經由 EMT 送入急診時已呈現明顯休克徵象。檢傷快速評估 E1V1M4，HR 142/min，RR 32/min，SBP 62mmHg。下腹部明顯血液外流。請問下列何者最不適當 (該醫院為重度級急救責任醫院，33、34 為題組)","opts":[{"k":"A","t":"立即啟動外傷小組。"},{"k":"B","t":"立即送入外科急救區並開始插管急救復甦。"},{"k":"C","t":"除輸液外，須立即啟動大量輸血指引(Massive transfusion protocol)，緊急叫血輸血 pRBC 6U 與 FFP 6U。"},{"k":"D","t":"立即施行全身電腦斷層並檢查，從頭部至骨盆，需注射顯影劑。"},{"k":"E","t":"立即評估下腹部傷口狀況，嘗試包紮止血。"}],"answer":"D","expl":"不穩定的休克病人不應先做全身 CT；應立即啟動外傷小組、插管、MTP、止血，所以 (D) 最不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-34","year":113,"qnum":34,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"經第一階段急救復甦後，病人仍然昏迷，心跳 126/min，血壓 78/56 mmHg，RR24/min，SaO2 96%。傷口檢視確認為骨盆開放性骨折並持續出血，傷口呈不規則撕裂狀，肉眼可見脹大的膀胱與腸道。請問下列何者須最優先進行","opts":[{"k":"A","t":"繼續大量輸血，應開始輸注血小板。"},{"k":"B","t":"照會骨科處理開放性骨盆骨折。"},{"k":"C","t":"照會泌尿科醫師評估是否可放置導尿管或進行膀胱造廔。"},{"k":"D","t":"骨盆骨折併持續出血休克，立即安排血管攝影與栓塞治療。"},{"k":"E","t":"立即聯絡開刀房安排手術。"}],"answer":"E","expl":"開放性骨盆骨折合併持續出血與休克，肉眼可見膀胱與腸道（疑腹內臟器損傷），應立即手術（damage control laparotomy、控制出血、造口），所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-35","year":113,"qnum":35,"topic":"顏面頸部","subtopic":"顏面骨折（LeFort、咬合）","stem":"下列有關顏面骨骨折的敘述，何者為非？","opts":[{"k":"A","t":"必要時先保護病人的呼吸道。"},{"k":"B","t":"病人經常口鼻出血，為骨折處輕微滲血，可以請家屬不須太過擔心。"},{"k":"C","t":"填塞止血後可經由口腔放置胃管，持續監測出血情形。"},{"k":"D","t":"血管栓塞或手術皆為止血的方法。"},{"k":"E","t":"病人發生嚴重的顏面骨骨折，須要排除可能的鈍傷性腦血管損傷(blunt cerebrovascular injuries) 或顱內出血 (intracranial hemorrhage)。"}],"answer":"B","expl":"顏面骨折病人口鼻出血不能掉以輕心，可能造成氣道危害與大量出血，所以 (B) 為非。(C) 顏面骨折（尤其 Le Fort 或顱底骨折）胃管應經口放置；(E) 需排除 BCVI 與顱內出血。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-36","year":113,"qnum":36,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"在重症創傷患者中，關於創傷性腹部手術後的併發症管理，下列哪一項策略是首選？","opts":[{"k":"A","t":"早期腹部再探查以評估未確認損傷。"},{"k":"B","t":"使用類固醇治療以減少 inflammatory response。"},{"k":"C","t":"使用 Temporary Abdominal Closure 以管理存在或潛在的腹部高壓症候群(abdominal compartment syndrome)。"},{"k":"D","t":"在所有腹部手術後例行施行神經阻滯以改善疼痛管理。"},{"k":"E","t":"使用較高劑量的抗生素以預防手術部位感染。"}],"answer":"C","expl":"創傷腹部手術後，使用 temporary abdominal closure 處理存在或潛在的 ACS 是首選策略，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-37","year":113,"qnum":37,"topic":"腹部","subtopic":"脾臟","stem":"對於脾臟創傷的手術處理，以下哪項手術技術是適合處理較嚴重級別脾損傷(例如Grade IV 或 V)的方法？","opts":[{"k":"A","t":"脾臟修補術 (Splenorrhaphy)。"},{"k":"B","t":"脾臟部分切除 (Partial splenectomy)。"},{"k":"C","t":"完全脾臟切除 (Total splenectomy)。"},{"k":"D","t":"脾臟動脈栓塞 (Splenic artery embolization)。"},{"k":"E","t":"僅進行腹部引流 (Abdominal drainage only)。"}],"answer":"C","expl":"嚴重脾損傷（Grade IV/V）若需手術，通常採 total splenectomy；脾修補與部分切除適用於較輕等級，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-38","year":113,"qnum":38,"topic":"總論評分","subtopic":"多重外傷定義（Berlin definition）","stem":"小丸子與爺爺、奶奶、母親、及父親同搭一車出遊，途中發生車禍送醫急救。依據2014 年 Berlin definition 所定義之多重外傷(polytrauma)，何者屬於多重外傷(polytrauma)患者？","opts":[{"k":"A","t":"意識清楚、生命徵象穩定合併頭、胸、四肢多處撕裂傷的 73 歲爺爺。"},{"k":"B","t":"肝臟第三度撕裂傷(AIS 3)及蜘蛛膜下腔出血(AIS 3)，無代謝性酸中毒(base excess = - 1.2)之 51 歲母親。"},{"k":"C","t":"脾臟第四度撕裂傷(AIS 4)及左手遠端橈骨開放性骨折(AIS 3)之 72 歲奶奶。"},{"k":"D","t":"左大腿骨骨折(AIS 3)合併血壓 75mmHg 的 53 歲父親。"},{"k":"E","t":"左側鎖骨閉鎖性骨折(AIS 2)及單純第二至第八肋骨骨折(AIS 3)的小丸子。"}],"answer":"C","expl":"Berlin definition：兩個區域 AIS ≥3 加上 SBP ≤90、GCS ≤8、BE ≤ −6、INR >1.4 或年齡 ≥70；72 歲奶奶（脾 AIS 4、橈骨開放性骨折 AIS 3，且年齡 ≥70）符合，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-39","year":113,"qnum":39,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"76 歲女性，騎腳踏車遭違規右轉機車撞飛，當埸失去意識，頭皮撕裂傷且地上留有大 片 血 跡 ， 右 大 腿 彎 曲 變 形 ， 經 目 擊者連絡 救 護 車 扺 逹 ， 初 步 量 得 血 壓150/95mmHg、心跳 85/min、可自行呼吸但有些許窘迫，緊急送至醫院急診，測得血壓 185/105、心跳 68/min，昏迷指數 E1V2M3，瞳孔 2.5/3.0 對光反應不明顯，左胸的呼吸聲稍有減弱，立即實施氣管內插管，左大腿先包紮固定，胸部 x-ray 左側有少許氣血胸，FAST 沒有明顯 ascites，請問下列處置或敘述何者正確？","opts":[{"k":"A","t":"依 Monro-Kellie Doctrine 定律，可長時間給予 3% hypertonic saline ，減少腦部水分來降低腦壓。"},{"k":"B","t":"血壓太高造成進入腦部血液增加，使得腦部腫漲，需調降血壓減少腦部出血。"},{"k":"C","t":"最好選擇使用 D5S 輸液補充水分，含有醣份可以供應外傷昏迷病患的營養及熱量。"},{"k":"D","t":"只能短時間給予病人 Hyper-Ventilation，快速降低 PaCO2 至 35mmHg 左右，使腦血管收縮減少腦部血流來降低腦壓。"},{"k":"E","t":"依 Monro-Kellie Doctrine 定 律 ， 須 限 制 輸 液 的 投 與 ， 使 頭 部 外 傷 病 患Hypo-Volemia 狀態，減少腦部的血液逹成降低腦壓。"}],"answer":"B","expl":"依官方答案 (B) 認為高血壓應降低。","outdated":false,"suspect":true,"flagNote":"病人 E1V2M3、血壓 185/105、心跳 68，是 Cushing 反應（顱內壓升高的代償性高血壓與心搏過緩）；此時不應急著降血壓，否則會降低腦灌注壓（BTF 建議維持 CPP 60–70、SBP ≥100–110）。另 (D)「只能短時間 hyperventilation，PaCO2 約 35」較符合現行觀念（短暫救命用），所以官方答案 (B) 疑似有誤，請依官方作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"113-40","year":113,"qnum":40,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"關於脊椎外傷的診斷，下列為非?","opts":[{"k":"A","t":"Neurogenic shock patients often present with reflexive tachycardia with hypotension."},{"k":"B","t":"Spinal shock is the temporary loss or depression of spinal reflex below the level of spinal cord injury."},{"k":"C","t":"CT is more sensitive than MRI at detecting bone injuries, but MRI is better at detecting neural and soft tissue injury."},{"k":"D","t":"Anterior cord syndrome usually has preserved proprioception and tactile sensation."},{"k":"E","t":"Central cord syndrome can present with paresthesia and muscle weakness."}],"answer":"A","expl":"Neurogenic shock 常表現為低血壓合併心搏過緩（交感喪失），而非反射性心搏過速，所以 (A) 為非。(B) Spinal shock 為暫時性反射消失；(C) CT 看骨傷較敏感、MRI 看軟組織與神經；(D)(E) 正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-41","year":113,"qnum":41,"topic":"脊椎脊髓","subtopic":"Neurogenic shock","stem":"57 歲男性，因使用毒品被通緝，經警方發現藏匿地點而被團團圍困，經對峙多時，因不想入監服刑，畏罪輕生自五樓跳下，先掉至二樓雨遮再跌落地面。經救護車緊急 送 至 醫 院 急 診 ， 病 患 意 識 混 亂 ， 昏 迷 指 數 E2V 2 M 5 ， 可 自 行 呼 吸 ， 血 壓80/50mmHg、心跳 115/min，雙上肢胡亂揮動，雙下肢體癱瘓，anal tone loose，左側肋骨 5th、6th，7th 骨折，腹部稍有腫脹，觸摸有些許痛的反應，FAST 有些 Ascites，下列處置及敘述何者正確？","opts":[{"k":"A","t":"此病患研判脊髓損傷，導致 Neurogenic shock，不必投與大量輸液，只需使用inotropic drug 來升血壓。"},{"k":"B","t":"需投與大量的 methyl-prednisolone ,30mg/kg 15min 然後 1 小時後，投與\n5.4mg/kg ,run 23 小時，治療脊髓損傷。"},{"k":"C","t":"此病患最可能脊髓損傷的位置在 L3 以下。"},{"k":"D","t":"此病患脊髓損傷導致交感神經受到傷害，導致血管擴張造成血壓偏低。"},{"k":"E","t":"此病患研判有脊髓損傷需儘快開刀，減壓及固定，以利神經恢復，否則來不及。"}],"answer":"D","expl":"雙下肢癱瘓、肛門括約肌鬆弛、休克、FAST 有腹水：同時有出血與 neurogenic shock，脊髓損傷導致交感神經受損、血管擴張造成低血壓，所以 (D)。不應只靠 inotrope、不需 methylprednisolone；病灶在胸腰椎，不是 L3 以下；手術時機需在穩定之後。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-42","year":113,"qnum":42,"topic":"胸部","subtopic":"Massive hemothorax／胸管引流","stem":"胸部外傷之初次與二次評估中，何種狀況需使用胸腔電腦斷層評估？","opts":[{"k":"A","t":"胸部 X 光顯示右側氣血胸。"},{"k":"B","t":"心肌酵素升高，心電圖顯示竇性頻脈。"},{"k":"C","t":"左胸水果刀刺傷，合併生命徵象不穩定。"},{"k":"D","t":"胸部 X 光顯示縱膈腔寬度大於 10 公分。"},{"k":"E","t":"傷患抱怨胸口疼痛。"}],"answer":"D","expl":"胸部 X 光縱隔寬度 >8 cm（官方題幹寫 10 cm）、aortic knob 消失等提示主動脈損傷時，需胸部 CTA 評估，所以 (D)。不穩定的刺傷不應先做 CT。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-43","year":113,"qnum":43,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"有一 80 歲男性患者，走路被機車撞倒，大腿明顯變形，119 送至一地區醫院，生命徵象穩定，意識清楚，若你是急診醫師，什麼處置是不宜：","opts":[{"k":"A","t":"問明有無病史。"},{"k":"B","t":"抽血檢查包含 INR ,ABG。"},{"k":"C","t":"轉送醫學中心。"},{"k":"D","t":"直接收住院觀察治療。"},{"k":"E","t":"老人病患要特別注意有無使用抗凝血劑。"}],"answer":"D","expl":"同 110-28：80 歲老人大腿變形，疑似股骨骨折，且可能服用抗凝血劑，應評估後轉醫學中心，所以 (D) 為不宜。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-44","year":113,"qnum":44,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"關於老年人外傷 (Geriatric trauma) 之描述，下列何者有誤：","opts":[{"k":"A","t":"因合併多重疾病比例較高，併發症和死亡率也偏高。"},{"k":"B","t":"胸部外傷造成氣胸，合併肋骨骨折機會比年輕人為高。"},{"k":"C","t":"早期低血容性休克較不容易發現，檢查 serum lactate level 及 base deficit 可幫助評估。"},{"k":"D","t":"頭部外傷，造成硬腦膜外血腫及顱內出血機會較高，也較容易早期出現神經學症狀。"},{"k":"E","t":"適度的評估及調整病人原使用之治療性抗凝血藥物，有助改善病人預後。"}],"answer":"D","expl":"老年人腦萎縮，顱內出血症狀常延後出現，且硬腦膜下血腫比 EDH 常見，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-45","year":113,"qnum":45,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"年輕男性遭遇重大事故，被送來急診接受診治，經詳細檢查後發現身上多處創傷，其損傷部位與 AIS (Abbreviated Injury Scale) 如下：顱內出血，AIS: 4；胸腔氣胸，AIS: 2；脾臟損傷，AIS: 4；肝損傷，AIS: 4；腎臟血腫，AIS: 2；大腿骨折，AIS: 3；\n請問該病患的 ISS (Injury Severity Score) 是幾分？","opts":[{"k":"A","t":"48。"},{"k":"B","t":"41。"},{"k":"C","t":"19。"},{"k":"D","t":"65。"},{"k":"E","t":"11。"}],"answer":"B","expl":"ISS：顱內出血 4、胸 2、腹（脾 4、肝 4、腎 2，取最高 4）、四肢 3；取三個最高區域：頭 4² + 腹 4² + 四肢 3² = 16 + 16 + 9 = 41，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-46","year":113,"qnum":46,"topic":"災難院前法規","subtopic":"總論／其他","stem":"在戰術場景下，一名 35 歲男性執行特勤任務時遭到爆炸衝擊，雙腿嚴重受傷，出現大量出血。由於仍在危險環境，應首先考慮何種措施來控制出血？","opts":[{"k":"A","t":"緊急使用靜脈輸血。"},{"k":"B","t":"使用戰術止血帶 (Tourniquet) 。"},{"k":"C","t":"立即進行手術止血。"},{"k":"D","t":"壓迫包紮傷口。"},{"k":"E","t":"使用抗生素以防感染。"}],"answer":"B","expl":"在戰術環境仍在危險（Care Under Fire）、四肢大量出血，首先使用 tourniquet，因為最快速有效，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-47","year":113,"qnum":47,"topic":"頭部TBI","subtopic":"EDH／SDH 處置","stem":"一名長期患有憂鬱症之 37 歲女性自三樓高處跳樓自殺，後被目擊者聯絡 EMT 送醫。到院時有明顯頭部外傷且意識不清 (E2V4M5)，同時合併軀幹及四肢多重外傷。\n經 resuscitation 及一系列影像學檢查後發現顱骨骨折及左側額葉 subdural hematoma，經神經外科醫師判斷建議手術治療。若病人同時合併有下列何項臨床診斷，應視為開顱手術之 contraindication 而必須優先以手術處理？","opts":[{"k":"A","t":"C1 fracture – Jefferson Type 2。"},{"k":"B","t":"Right side flail chest with hemothroax and lung contusion。"},{"k":"C","t":"Gr. IV liver laceration with hemoperitoneum and hypovolemic shock, unresponsive to resuscitation。"},{"k":"D","t":"Pelvic fracture – LC type II with retroperitoneal hematoma, no contrast extravasation under enhanced CT。"},{"k":"E","t":"Right femoral shaft open fracture。"}],"answer":"C","expl":"病人合併 Grade IV 肝裂傷、腹內大量出血且對復甦無反應，這是立即危及生命的出血性休克，應優先剖腹止血，開顱手術必須延後，所以 (C)。其餘（C1 骨折、flail chest、穩定的骨盆骨折、股骨骨折）不會凌駕開顱手術。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-48","year":113,"qnum":48,"topic":"骨盆泌尿","subtopic":"腎臟外傷","stem":"你是一個接受完整外傷手術訓練的外科醫師，在一家區域級醫院值勤，有完整的手術室設備和人力，離最近的一家醫學中心轉診車程約為 1 小時。半夜急診照會一名25 歲機車駕駛，已經做完全身電腦斷層，左側腎臟撕裂傷第四級合併顯影劑滲漏，患 者 已 經 輸 了 6U 紅 血 球 濃 厚 液 和 6U 的 新 鮮 冷 凍 血 漿 但 血 壓 仍 然 處 於75mmHg/60mmHg，心跳 140/分，請問此時最合理的選擇為何？","opts":[{"k":"A","t":"直接剖腹探查，不打開後腹腔，直接將腹腔進行紗布填塞後轉診。"},{"k":"B","t":"直接剖腹探查，將左側腎臟摘除，並將後腹腔出血處填塞後轉診醫學中心。"},{"k":"C","t":"患者休克不宜直接手術，直接轉診醫學中心。"},{"k":"D","t":"患者休克不宜直接手術，讓患者入住加護病房持續輸血試圖維持血壓。"},{"k":"E","t":"持續輸血試圖穩定血壓，等隔天早上放射科醫師上班安排血管栓塞。"}],"answer":"B","expl":"區域醫院有手術能力、不穩定的 Grade IV 腎臟損傷合併 contrast extravasation，輸血後仍低血壓，應直接剖腹探查，必要時做腎臟切除並填塞止血，所以官方答案 (B)；不應只填塞不打開後腹腔，也不應等隔天栓塞。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-49","year":113,"qnum":49,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"外傷病患有下列生理變化，受傷機轉或是檢查發現，可能會需要啟動損害控制復甦(Damage control resuscitation)，何者為非?","opts":[{"k":"A","t":"PT INR > 1.5。"},{"k":"B","t":"HR>100/min。"},{"k":"C","t":"GCS < 8。"},{"k":"D","t":"PH < 7.25。"},{"k":"E","t":"Base deficit > 6。"}],"answer":"C","expl":"DCR 啟動的參考條件：凝血病變（INR >1.5）、酸中毒（pH <7.25、base deficit >6）、休克指標（HR >100）、低體溫等；GCS <8 是神經學指標，不是 DCR 的啟動條件，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"113-50","year":113,"qnum":50,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"一名 25 歲男性因車禍被送至急診。現意識清楚並持續抱怨腹部悶痛，無明顯peritoneal signs。生命徵象為心跳 134 下/分、呼吸 22 下/分、血壓 80/52 mmHg、體溫 36.6oC。有關此病人之處置及敘述何者最不合理？","opts":[{"k":"A","t":"暫時不需要氣管內插管"},{"k":"B","t":"給予 normal saline 2000ml challenge 後血壓升至 94/65 mmHg，應安排腹部電腦斷層檢查。"},{"k":"C","t":"從電腦斷層室送回急診的路上血壓再度掉為 76/50 mmHg，應改以 colloids 做resuscitation。"},{"k":"D","t":"電腦斷層檢查發現無 solid organ injury，但腹內有大量積液，應懷疑是否有腸系膜損傷。"},{"k":"E","t":"若電腦斷層發現有 pneumoperitoneum，無論血壓如何，即為 surgical exploration之 indication。"}],"answer":"C","expl":"休克後給晶質液暫時反應，再度惡化屬 transient responder；膠體液（colloids）並無優勢，也不是首選，應盡早輸血，所以 (C) 最不合理。","outdated":true,"suspect":false,"flagNote":"選項 (B)「NS 2000 mL challenge」被視為合理，但 ATLS 10/11 建議初始約 1 L 晶質液，之後盡早輸血；官方答案 (C) 不變。原官方答案維持 (C)，僅供臨床與新版指引對照。","images":[]},{"id":"114-1","year":114,"qnum":1,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"下列有關老人外傷之敘述何者為非？","opts":[{"k":"A","t":"老人較無法承受缺氧狀態，故面對外傷後休克的個案需盡快插管。"},{"k":"B","t":"老人對胸部外傷的耐受性較差，單純肋骨骨折或肺部挫傷也可能導致呼吸衰竭。"},{"k":"C","t":"老人外傷最常見的外傷機轉是跌倒。"},{"k":"D","t":"老人有較多比例具有冠狀動脈疾病，同時全身總血量也隨年紀逐漸降低，故外傷出血休克者常常呈現明顯心搏過速(tachycardia)的現象。"},{"k":"E","t":"因為老人常有高血壓的問題，故單純以血壓來判斷失血量常會誤判。"}],"answer":"D","expl":"同 112-14：老年人因藥物與自主神經反應較差，出血休克時不一定明顯心搏過速，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-2","year":114,"qnum":2,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關腹部穿刺傷之敘述何者有誤?","opts":[{"k":"A","t":"對於血流動力學稳定且無腹膜刺激症狀的患者，如果前腹部介於兩條腋前線之間發生刀傷(包括刺傷)可以進行局部探查。"},{"k":"B","t":"如果腹部前筋膜被穿透，患者需入院接受一系列臨床檢查；如果出现腹膜刺激症狀或血流動力學不稳定時，则需进行剖腹探查術。"},{"k":"C","t":"一些醫療中心會進行 CT 检查或不太常見的診断性腹腔灌洗 (DPL)以評估筋膜穿透的患者。"},{"k":"D","t":"建議對側腹部(腋前線和腋後線之間)或背部(腋後線之間)的刀傷進行 CT 檢查，因為進行一系列腹部檢查和/或 DPL 時，可能會遺漏這些部位下方的腹膜後結購損傷。"},{"k":"E","t":"對於槍傷通常會優先進行局部傷口探查。"}],"answer":"E","expl":"腹部槍傷不能靠局部傷口探查來排除腹膜穿透（彈道不可預測），需依血流動力學、腹膜炎與 CT 等評估，所以 (E) 有誤。局部探查只適用於前腹部的刀傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-3","year":114,"qnum":3,"topic":"災難院前法規","subtopic":"大量傷患檢傷（MCI／triage／ICS）","stem":"下列何者最能正確描述 Mass-Casualty Incident(MCI)的定義？","opts":[{"k":"A","t":"傷患超過十人以上的事件。"},{"k":"B","t":"需動員軍方支援的事故。"},{"k":"C","t":"傷患數量暫時超過當地醫療系統可即時應付的能力。"},{"k":"D","t":"僅限於爆炸或恐攻事件。"},{"k":"E","t":"造成社會恐慌但無實際傷亡者。"}],"answer":"C","expl":"MCI 定義：傷患數量暫時超過當地醫療系統可即時應付的能力，並非固定人數，也不限於爆炸或恐攻，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-4","year":114,"qnum":4,"topic":"燒傷環境","subtopic":"燒傷面積估算與 Parkland 輸液","stem":"以下哪一種燒傷患者應轉送至具備燒傷中心資格的醫療院所？","opts":[{"k":"A","t":"局部淺二度燒傷 5% TBSA 的成人。"},{"k":"B","t":"深二度以上燒傷 10% TBSA 的兒童。"},{"k":"C","t":"面積 1% 的表淺燒傷。"},{"k":"D","t":"頭皮局部一度燒傷。"},{"k":"E","t":"表皮擦傷伴輕度紅腫。"}],"answer":"B","expl":"依 ABA 轉診標準，部分皮層或深度燒傷（深二度以上）≥10% TBSA、特殊部位、化學或電燒傷、吸入傷害等需轉燒傷中心；官方答案 (B) 為深二度以上燒傷 10% TBSA 的兒童。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-5","year":114,"qnum":5,"topic":"災難院前法規","subtopic":"戰術／軍陣外傷（TCCC／TECC／MARCH）","stem":"根據 Tactical Emergency Casualty Care(TECC)中之 MARCH 原則，下列哪一項為首要處理步驟？","opts":[{"k":"A","t":"Airway – 呼吸道確保。"},{"k":"B","t":"Circulation – 循環支持。"},{"k":"C","t":"Massive Hemorrhage – 控制大量出血。"},{"k":"D","t":"Head Injury – 頭部保護。"},{"k":"E","t":"Exposure – 去除衣物並評估全身傷勢。"}],"answer":"C","expl":"MARCH 的第一項是 Massive hemorrhage（控制大量出血），所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-6","year":114,"qnum":6,"topic":"休克輸血","subtopic":"Lethal triad（致命三角）","stem":"相對於傳統的致命三角(lethal triad)，在現代急救技術越發進步之下，我們會遇到致命鑽石(lethal diamond)，其中新加入的元素是下列何者？","opts":[{"k":"A","t":"Hypothermia。"},{"k":"B","t":"Acidosis。"},{"k":"C","t":"Hypocalcemia。"},{"k":"D","t":"Hyperkalemia。"},{"k":"E","t":"Coagulopathy。"}],"answer":"C","expl":"同 112-1：Lethal diamond 在 hypothermia、acidosis、coagulopathy 之外加入 hypocalcemia，所以 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-7","year":114,"qnum":7,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"下列何者不是四肢大量出血的 soft signs？","opts":[{"k":"A","t":"History of moderate hemorrhage。"},{"k":"B","t":"Proximity injury。"},{"k":"C","t":"Diminished pulse。"},{"k":"D","t":"Expanding hematoma。"},{"k":"E","t":"Peripheral nerve deficient。"}],"answer":"D","expl":"肢體血管損傷的 hard signs：脈搏消失、活動性出血、擴大的血腫、震顫（thrill）、血管雜音；expanding hematoma 屬 hard sign，不是 soft sign；soft signs 包括中等出血史、鄰近傷、脈搏減弱、周邊神經缺損，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-8","year":114,"qnum":8,"topic":"四肢血管骨科","subtopic":"總論／其他","stem":"下列何者不是判斷肌肉組織仍然存活的 4Cs?","opts":[{"k":"A","t":"color。"},{"k":"B","t":"consistency。"},{"k":"C","t":"capillary bleeding。"},{"k":"D","t":"cold。"},{"k":"E","t":"contractility。"}],"answer":"D","expl":"判斷肌肉存活的 4Cs：Color、Consistency、Capillary bleeding、Contractility；Cold 不是，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-9","year":114,"qnum":9,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"依據第 11 版 ATLS，右膝槍傷病人合併持續性出血、現場只有你一人，下列處置何者為宜?","opts":[{"k":"A","t":"於右大腿綁上止血帶後，用電話求救。"},{"k":"B","t":"用電話求救後，等足夠急救人員到場再處置。"},{"k":"C","t":"用電話求救後，用清潔的布或紗布於外部皮膚傷口上試著加壓止血。"},{"k":"D","t":"用電話求救後，先確認呼吸道通暢。"},{"k":"E","t":"以上皆非。"}],"answer":"C","expl":"依官方答案 (C)：呼叫求援後，先以乾淨布料或紗布直接加壓止血。補充：若直接加壓失敗且為肢體致命大出血，現行 ATLS 與 Stop the Bleed 建議盡早使用 tourniquet；膝部傷口位於關節處，止血帶效果有限。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-10","year":114,"qnum":10,"topic":"休克輸血","subtopic":"Tranexamic acid（TXA／transamine）","stem":"依據第 11 版 ATLS，Transamine 的給法，下列何者為宜?","opts":[{"k":"A","t":"於受傷 3 小時內，給予 2gram STAT 後續不需追加。"},{"k":"B","t":"於受傷 5 小時內，給予 2gram STAT 後續不需追加。"},{"k":"C","t":"於受傷 3 小時內，給予 2gram STAT 後續給予 1gram Q8h*1 day。"},{"k":"D","t":"於受傷 3 小時內，給予 1gram STAT 後續於 8 小時後再追加 1gram。"},{"k":"E","t":"以上皆非。"}],"answer":"A","expl":"官方答案為 (A)：傷後 3 小時內給 TXA 2 g STAT，後續不需追加。","outdated":false,"suspect":true,"flagNote":"據我查到，ATLS 11 支持傷後 3 小時內使用 TXA，劑量可為 1 g（約 10 分鐘）加 1 g（8 小時）輸注，或單次 2 g；因此選項 (D)（1 g 加 8 小時後追加 1 g）同樣符合 ATLS 11，且本題庫較早年度（107-1、110-37）以 CRASH-2 的 1+1 方案作為標準。此題官方答案可能不唯一，考試請依官方作答。原官方答案維持 (A)，考試請以官方答案為準。","images":[]},{"id":"114-11","year":114,"qnum":11,"topic":"總論評分","subtopic":"總論／其他","stem":"一名 28 歲男性機車撞車，高速撞擊後昏迷、腹部膨脹。急診初評：BP 72/40 mmHg、HR 148/min、RR 30/min、SpO₂ 88%(氧氣 10 L/min)，GCS 7。右股部外出血已以止血帶控制，FAST 顯示腹腔大量液體(懷疑脾臟破裂)。外科團隊正準備開腹，麻醉科正在建立氣道。下列何者正確？\n1. 優先控制外出血(x)後建立氣道(A)。\n2. 啟動大量輸血(MTP)，限制晶體液注射量。\n3. 若資源有限，可依 Flex 原則於急診室內進行 REBOA 暫時性控制出血。\n4. 應立即行 CT 確認脾臟破裂分級再決定手術。\n5. 在氣道尚未建立前給予鎮靜與肌鬆劑以利插管。","opts":[{"k":"A","t":"1+2。"},{"k":"B","t":"1+2+3。"},{"k":"C","t":"1+2+4。"},{"k":"D","t":"1+2+5。"},{"k":"E","t":"1+3+5。"}],"answer":"B","expl":"休克合併腹部膨脹：xABCDE 先控制外出血（止血帶），再建立氣道；啟動 MTP 並限制晶質液；資源有限時可考慮 REBOA；不穩定不做 CT；氣道未建立前不應給鎮靜與肌鬆劑（RSI 需準備好才進行），所以 (B) 1+2+3。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-12","year":114,"qnum":12,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"一名 56 歲男性高速車禍後腹痛、意識模糊。急診評估：BP 88/50 mmHg、HR132/min、RR 28/min、SpO₂ 90%，GCS 10。FAST 檢查顯示左上腹游離液體(疑脾破裂)，骨盆穩定。家屬情緒激動，要求立即轉院；創傷外科與麻醉團隊正準備手術。下列哪些作法正確？\n1. 醫師需同時整合臨床評估、團隊溝通與家屬安撫(Weave 概念)。\n2. 轉診通報時應依 S-xABCDE-BAR 架構完整報告傷情。\n3. 若病人短暫穩定，可於轉送前完成造影 CT。\n4. 溝通內容應包含出血控制、氣道、呼吸、循環、神經與暴露狀態。\n5. 應暫緩與家屬溝通，避免干擾手術準備。","opts":[{"k":"A","t":"1+2。"},{"k":"B","t":"1+2+3。"},{"k":"C","t":"1+2+4。"},{"k":"D","t":"1+2+3+4。"},{"k":"E","t":"1+2+3+4+5。"}],"answer":"C","expl":"病人整合照護：同時整合臨床評估、團隊與家屬溝通（Weave 概念）、依 S-xABCDE-BAR 完整報告傷情、轉診溝通含 xABCDE；不穩定時不應為了 CT 延誤轉送，也不該暫緩與家屬溝通，所以 (C) 1+2+4。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-13","year":114,"qnum":13,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"下列有關 Damage Control Surgery (DCS) 的敘述，何者為非？","opts":[{"k":"A","t":"DCS 的核心概念為先行控制出血與污染，再行 definitive repair。"},{"k":"B","t":"適用於 trauma-induced coagulopathy, hypothermia, acidosis (lethal triad)。"},{"k":"C","t":"初期手術目標包括：臟器保護、快速 definitive anastomosis。"},{"k":"D","t":"術後需轉入 ICU 進行積極 resuscitation。"},{"k":"E","t":"DCS 最常應用於嚴重腹部外傷合併生理不穩定病人。"}],"answer":"C","expl":"DCS 的核心是縮短首次手術：控制出血與污染、暫時關腹，再於 ICU 矯正生理後做 definitive repair；首次手術不做 definitive anastomosis，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-14","year":114,"qnum":14,"topic":"休克輸血","subtopic":"創傷凝血病變／VHA（TEG／ROTEM）","stem":"近年的文獻報告證實，血栓彈力 Viscoelastic hemostatic assay (VHAs)分析，在外傷大出血的病患有極大的功效。血栓彈力圖(thromboela-stogram，TEG/ROTEM)是反映血液凝固動態變化的指標，可檢測凝血功能全貌：包含凝血因子、纖維蛋白、血小板及纖維蛋白溶解(fibrinolysis)。下列敘述那項較不正確：","opts":[{"k":"A","t":"急性創傷、大量出血休克、心臟或器官移植手術患者的凝血功能評估。"},{"k":"B","t":"簡單，只需要一管全血，送醫院中央檢驗單位即可。"},{"k":"C","t":"各種出血原因的鑑別診斷，進而指導成分輸血。"},{"k":"D","t":"鑑別診斷原發性纖維蛋白溶解亢進(primary hyperfibrinolysis)或繼發性纖維蛋白原溶解亢進。"},{"k":"E","t":"減少不必要的血液成分的輸血。"}],"answer":"B","expl":"同 112-5：TEG/ROTEM 為 point-of-care 檢查，需快速在床邊或附近完成，不應送中央檢驗單位延遲，所以 (B) 較不正確。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-15","year":114,"qnum":15,"topic":"休克輸血","subtopic":"REBOA","stem":"關於 REBOA 在 trauma critical care 的應用，下列何者錯誤？","opts":[{"k":"A","t":"REBOA 可分為 Zone I (left subclavian 至 celiac) 與 Zone III (below renal artery至 aortic bifurcation)。"},{"k":"B","t":"Zone I inflation 常用於 torso trauma 合併 uncontrolled intra-abdominal bleeding。"},{"k":"C","t":"Zone III inflation 適用於 pelvic fracture 合併 massive hemorrhage。"},{"k":"D","t":"REBOA balloon inflation 時間一般建議 ≤ 60–90 分鐘。"},{"k":"E","t":"REBOA 可取代所有開胸止血 (ED thoracotomy) 的適應症。"}],"answer":"E","expl":"REBOA 不能取代所有 ED thoracotomy 適應症（胸腔內出血、心包填塞等需要開胸），所以 (E) 錯。(A) Zone I 與 Zone III 的定義正確；(D) 阻斷時間盡量越短越好，一般建議 Zone I 不超過約 30–60 分鐘，官方未視為錯誤。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-16","year":114,"qnum":16,"topic":"四肢血管骨科","subtopic":"止血帶與肢體血管損傷（hard／soft signs）","stem":"12 歲小男孩騎 U-bike 遭貨車撞擊，入院時因開放性右下腿骨折出現持續動脈出血，伴胸壁挫傷、顏面腫脹合併喘鳴(stridor)。生命徵象：BP 80/50 mmHg、HR 140/min、RR 28/min、GCS 6；患者喘氣且不能說話，皮膚蒼白濕冷。依 ATLS 第 11 版治療準則，以下哪項是最合適且優先的初步處置組合？","opts":[{"k":"A","t":"以快速序列插管(Rapid Sequence Intubation, RSI)維持呼吸道暢通。"},{"k":"B","t":"安排緊急胸部及骨盆 X 光。"},{"k":"C","t":"建立中心靜脈監測並準備大量輸血(Massive Transfusion)。"},{"k":"D","t":"給予 20 mL/kg crystalloid fluid resuscitation。"},{"k":"E","t":"立即以直接加壓與止血帶(tourniquet)控制出血。"}],"answer":"E","expl":"依 ATLS 11 的 xABCDE，開放性骨折持續動脈出血應首先用直接加壓與 tourniquet 控制（x），然後才是氣道（A）；所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-17","year":114,"qnum":17,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"30 歲男性行人遭汽車追撞，左脛骨閉合移位性骨折、骨盆疼痛、嚴重呼吸困難與心搏過速。已由理學檢查與影像確診左側張力性氣胸(tension pneumothorax)，並立即行胸部減壓處置(Needle decompression)，初步處置後心率與呼吸均有改善，但仍持續低血壓。下一個應進行的評估和處置是：","opts":[{"k":"A","t":"放置骨盆固定帶(pelvic binder)。"},{"k":"B","t":"進行尿道攝影與膀胱攝影(urethrogram, cystogram)。"},{"k":"C","t":"安排腹部與骨盆電腦斷層(CT)。"},{"k":"D","t":"啟動大量輸血流程並準備血管栓塞(angioembolization)。"},{"k":"E","t":"直接送開刀房行腹膜前骨盆填塞(pre-peritoneal pelvic packing)。"}],"answer":"A","expl":"張力性氣胸減壓後仍低血壓，且有骨盆疼痛，應儘快用 pelvic binder 固定骨盆，再依 FAST 與反應決定 MTP、TAE 或 preperitoneal packing，所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-18","year":114,"qnum":18,"topic":"胸部","subtopic":"總論／其他","stem":"關於主動脈解剖學分區，以下何者為真？","opts":[{"k":"A","t":"右側 carotid artery 至 celiac trunk 之間的區域為 zone 1。"},{"k":"B","t":"Celia trunk 至 renal artery 之間的區域為 zone 2。"},{"k":"C","t":"Celiac trunk 至 inferior mesenteric artery 之間的區域為 zone 2。"},{"k":"D","t":"Superior mesenteric artery 至 aorta bifurcation 之間的區域為 zone 3。"},{"k":"E","t":"Aorta bifurcation 以下的區域為 zone 4。"}],"answer":"B","expl":"同 112-16：REBOA 的 Zone 1 為左鎖骨下動脈到 celiac trunk；Zone 2 為 celiac trunk 到最低腎動脈；Zone 3 為最低腎動脈到 aortic bifurcation，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-19","year":114,"qnum":19,"topic":"腹部","subtopic":"胰臟／十二指腸","stem":"對於胰臟鈍傷，下列敘述何者為非?","opts":[{"k":"A","t":"由於胰臟位在人體的後腹膜腔的解剖構造，胰臟受傷在臨床診斷上比較困難。"},{"k":"B","t":"Main Pancreatic duct 斷裂且無法經由 ERCP (Endoscipic Retrograde Cholangio-pancreitco-graphy)置放內支架時，是進行外科手術處理的適應症(surgical indication)。"},{"k":"C","t":"Abdominal CT (+-)比腹部超音波對於胰臟鈍傷有較高的診斷率。"},{"k":"D","t":"ERCP (Endoscipic Retrograde Cholangio-pancreitco-graphy)有助於診斷 main pancreatic duct 是否有斷裂。"},{"k":"E","t":"血中 Amylase 濃度對於胰臟鈍傷具高敏感度指標。"}],"answer":"E","expl":"同 105-49：Serum amylase 對胰臟鈍傷既不敏感也不專一，所以 (E) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-20","year":114,"qnum":20,"topic":"老年孕婦","subtopic":"懷孕外傷（左側臥、胎兒評估、Rh 免疫球蛋白、影像）","stem":"25 歲的女性，懷孕 22 週，發生自 6 樓墜樓事故後送至醫院，孕婦到院時血壓 60/40 mmHg，心跳 140/min，Glasgow Coma Scale Score 為 8 分，經 Resuscitation 及 primary survey 後，腹部超音波顯示腹腔內有大量液體，經緊急會診產科醫師後發現無胎心音，此時孕婦血壓回到 80/60 mmHg，電腦斷層顯示疑似子宮破裂併胎兒外露至孕婦的腹腔和大量腹腔內積液堆積(如圖所示)，以下敘述及處置，何者較不適當？","opts":[{"k":"A","t":"聯絡外傷科醫師、婦產科醫師及開刀房，立即安排入刀房進行手術治療。"},{"k":"B","t":"立刻予以緊急輸血，原則為 PRBC : FFP 為 1:1 的比例。"},{"k":"C","t":"孕婦的 Fibrinogen 的正常數值範圍在 400-450 mg/dL"},{"k":"D","t":"於受傷後 3 小時內盡早給予 Tranexamic acid 1gm IV。"},{"k":"E","t":"立刻給予升壓劑，使其收縮壓能大於 150 mmHg。"}],"answer":"E","expl":"孕婦腹內大出血休克：緊急輸血（PRBC：FFP 1:1）、3 小時內 TXA、立即送手術室，並採 permissive hypotension；不應用升壓劑把血壓拉到 SBP >150，所以 (E) 較不適當。附圖我未逐項判讀，請以官方答案為準。","outdated":false,"suspect":false,"flagNote":"","images":["p264-1.jpg"]},{"id":"114-21","year":114,"qnum":21,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"有一位 30 歲男性病患，因颱風遭受路樹壓砸傷後 20 分鐘內送至某醫學中心急救。到院時血壓 80/40 mmHg，心跳 140/min，Glasgow Coma Scale Score 為 15 分，經 primary survey及 Resuscitation 後，血壓心跳回到 95/50 mmHg，心跳 120/min 腹部超音波顯示右後腹腔內有大量液體，電腦斷層如附圖 a 及 b，報告顯示有右後腹腔 contrast extravasation，胸部X 光顯示兩側沒有血胸或氣胸，雙側瞳孔等大有光反射，則下列何處置較不適當？\n圖 a.圖 b.","opts":[{"k":"A","t":"建議於受傷 3 小時內給予 Tranexamic acid 1gm IV。"},{"k":"B","t":"立刻進行輸血治療。"},{"k":"C","t":"立刻安排血管攝影栓塞，且同時聯絡開刀房，若做血管栓塞治療失敗，則緊急入開刀房進行手術處理。"},{"k":"D","t":"於確定 stop bleeding 之前，避免維持過高的血壓，需進行 Permissive hypotension，以免造成 lethal triad (Hypothermia，Acidosis，Coagulopathy)。"},{"k":"E","t":"不需安排血管攝影栓塞或手術治療，於加護病房觀察即可。"}],"answer":"E","expl":"後腹腔 contrast extravasation（active bleeding）仍需 TXA、輸血與 permissive hypotension，並安排 angioembolization 與手術備案；不能只在 ICU 觀察，所以 (E) 較不適當。附圖我未逐項判讀，請以官方答案為準。","outdated":false,"suspect":false,"flagNote":"","images":["p264-2.jpg"]},{"id":"114-22","year":114,"qnum":22,"topic":"休克輸血","subtopic":"總論／其他","stem":"下列何者不是可能造成休克的大量出血位置？","opts":[{"k":"A","t":"胸腔 (Thoracic cavity)。"},{"k":"B","t":"腹腔 (Peritoneal cavity)。"},{"k":"C","t":"後腹腔 (Retroperitoneal space)。"},{"k":"D","t":"長骨與軟組織 (Long bone / Soft tissue compartments)。"},{"k":"E","t":"腦室內出血 (Intraventricular hemorrhage)。"}],"answer":"E","expl":"休克的大量出血位置：胸腔、腹腔、後腹腔（骨盆）、長骨與軟組織；顱內出血（包括腦室內出血）因顱腔容量有限，不會造成成人出血性休克，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-23","year":114,"qnum":23,"topic":"休克輸血","subtopic":"總論／其他","stem":"關於休克 (Shock) 與灌流改善 (Improved perfusion) 的臨床表現，下列何者錯誤？","opts":[{"k":"A","t":"中樞神經系統 (CNS) 在早期休克可能出現躁動，晚期則可能呈現嗜睡。"},{"k":"B","t":"皮膚在休克時通常冰冷濕黏，且微血管充填時間延長。"},{"k":"C","t":"腎臟功能改善的指標是尿量恢復，但此評估需較長時間才能觀察。"},{"k":"D","t":"血流動力學改善時，可能表現為心跳數下降趨於正常、血壓改善。"},{"k":"E","t":"對皮膚溫度與微血管回填時間的評估完全客觀，且不受外部環境影響。"}],"answer":"E","expl":"皮膚溫度與微血管充填時間的評估相當主觀，會受環境溫度與測量方式影響，所以 (E)「完全客觀」為錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-24","year":114,"qnum":24,"topic":"顏面頸部","subtopic":"氣管損傷","stem":"37 歲男性因車禍送至急診室，當時病人血壓：89/59 mmHg，脈搏: 106/分，呼吸：\n18/分，病人昏迷指數為 E1M2V1，病人外觀明顯右側有 Raccoon eyes，兩側鼻腔明顯出血，右側下巴明顯撕裂傷及變形，病人呼吸道的處置首選為何？","opts":[{"k":"A","t":"Non-rebreathing mask。"},{"k":"B","t":"Nasotracheal Intubation。"},{"k":"C","t":"Orotracheal Intubation。"},{"k":"D","t":"Cricothyroidotomy。"},{"k":"E","t":"Tracheostomy。"}],"answer":"D","expl":"熊貓眼（顱底骨折）、鼻出血、下頜骨撕裂傷與變形、GCS 4：禁忌 nasotracheal intubation；嚴重顏面外傷無法經口時需 surgical airway，官方答案 (D) cricothyroidotomy。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-25","year":114,"qnum":25,"topic":"骨盆泌尿","subtopic":"骨盆骨折出血處置（binder／packing／栓塞）","stem":"下列有關 pelvic fracture (使用 Young- Burgess 分類)之敘述，何者為非？","opts":[{"k":"A","t":"對於 unstable pelvic fracture, early external fixation 是考慮的選項。"},{"k":"B","t":"Pelvic angioembolization,目前為 pelvic fracture hemorrhage 止血主要選擇。"},{"k":"C","t":"Stable type pelvic fracture (e.g Lateral compression I, APC type I)，有時也會產生pelvic hemorrhage。"},{"k":"D","t":"Unstable type pelvic fracture，文獻報告約有 40~70%之 pelvic hemorrhage rate。"},{"k":"E","t":"Sacral-iliac (SI) joint traumatic disruption，發生 pelvic hemorrhage 機會低。"}],"answer":"E","expl":"同 111-6：SI joint 破壞（尤其合併後骨盆環不穩定）出血風險高，所以 (E) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-26","year":114,"qnum":26,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"以下何種病人病況需立即 Damage Control Surgery 機率最低?","opts":[{"k":"A","t":"胸部鈍挫傷併心包膜積液。"},{"k":"B","t":"開放性骨盆骨折。"},{"k":"C","t":"鈍挫傷併發 Mangled extremity。"},{"k":"D","t":"髖部股三角區槍傷。"},{"k":"E","t":"胸部穿刺傷併肋膜腔積液，收縮壓 100 mmHg。"}],"answer":"E","expl":"胸部穿刺傷合併肋膜腔積液但收縮壓 100 mmHg，通常以胸管處理，不需要立即 damage control surgery，機率最低，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-27","year":114,"qnum":27,"topic":"DCS_ACS","subtopic":"Damage control surgery（適應症與術式）","stem":"以下何種 Damage Control 術式在重大外傷病人不被強烈建議施行?","opts":[{"k":"A","t":"心包膜腔針刺術(Pericardiocetesis)。"},{"k":"B","t":"骨盆外固定(External Fixation)。"},{"k":"C","t":"截肢(Amputation)。"},{"k":"D","t":"血管分流(Vascular Shunt)。"},{"k":"E","t":"筋膜切開術(Fasciotomy)。"}],"answer":"A","expl":"Damage control 術式包括骨盆外固定、截肢、血管分流與暫時性血管修復、fasciotomy；pericardiocentesis 是暫時性處置，不被強烈建議作為 DC 術式（需手術處理心包填塞），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-28","year":114,"qnum":28,"topic":"胸部","subtopic":"ED／resuscitative thoracotomy 適應症與禁忌","stem":"關於在急診復甦室施行緊急開胸術(Emergency Department thoracotomy) 的適應症及禁忌症描述，以下何者為非?","opts":[{"k":"A","t":"目視下胸部穿刺傷併心跳停止，經到院前 CPR 小於 15 分鐘者，可建議施行之。"},{"k":"B","t":"目視下非胸部的穿刺傷併心跳停止，經到院前 CPR 小於 15 分鐘者，可建議施行之。"},{"k":"C","t":"目視下胸部頓挫傷併心跳停止，經到院前 CPR 小於 10 分鐘者，可建議施行之。"},{"k":"D","t":"因腹內出血併發持續性的嚴重低血壓(SBP< 60 mmHg)，可建議施行之。"},{"k":"E","t":"因鈍挫傷後 CPR 大於 10 分鐘者，仍無生命徵象者，不建議施行之。"}],"answer":"B","expl":"ED thoracotomy：胸部穿刺傷到院前 CPR <15 分鐘、鈍傷 <10 分鐘；鈍傷 CPR >10 分鐘無生命徵象不建議；腹內出血嚴重低血壓可考慮；官方答案 (B)：「目視下非胸部穿刺傷併心跳停止，經 CPR <15 分鐘可建議施行」為錯。","outdated":false,"suspect":true,"flagNote":"據我所知，EAST/WTA 2015 指引對 penetrating extrathoracic injury 且有 signs of life、CPR <15 分鐘者是「有條件建議」施行 ED thoracotomy，因此 (B) 與該指引並不衝突；官方答案 (B) 有爭議，請依官方作答。原官方答案維持 (B)，考試請以官方答案為準。","images":[]},{"id":"114-29","year":114,"qnum":29,"topic":"腹部","subtopic":"肝臟","stem":"下列有關鈍性肝臟外傷(blunt liver injury)之敘述，何者為非？","opts":[{"k":"A","t":"hemodynamically unstable 病人應立即進行剖腹手術(laparotomy)。"},{"k":"B","t":"大多數 hemodynamically stable 病人可採非手術治療(Non-operative management, NOM)。"},{"k":"C","t":"若電腦斷層顯示 contrast extravasation，通常不需進一步處置即可成功保守治療。"},{"k":"D","t":"血管栓塞(angioembolization)可作為輔助性止血方法。"},{"k":"E","t":"肝損傷合併大量輸血需求者，應警覺出血控制失敗風險。"}],"answer":"C","expl":"鈍性肝損傷若 CT 見 contrast extravasation，並非通常保守治療即可成功，需考慮 angioembolization 或手術，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-30","year":114,"qnum":30,"topic":"腹部","subtopic":"脾臟","stem":"19 歲的男性發生機車事故後送至醫院，他的生命跡象正常，但上腹部有一塊瘀青並延伸至左側，患者並無其他的明顯外傷，經腹部電腦斷層檢查後有看到脾臟破裂併顯影劑外漏至腹腔內，同時骨盆腔部位有一大塊液體滯留，這患者最需要的處置是為下列何者？","opts":[{"k":"A","t":"施打肺炎雙球菌疫苗。"},{"k":"B","t":"脾臟血管栓塞。"},{"k":"C","t":"施打中央靜脈導管。"},{"k":"D","t":"氣管內管插管。"},{"k":"E","t":"安排 Diagnostic peritoneal lavage。"}],"answer":"B","expl":"同 111-12：穩定、脾臟破裂合併 contrast extravasation，首選 splenic angioembolization，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-31","year":114,"qnum":31,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"王小美，於下班途中騎摩拖車發生車禍，經救護車緊急送至醫院進行救治，王小美神智清楚，生命徵象: 血壓 96/64 mmHg， 呼吸 20 次/min ，心跳 104/ min， 體溫: 35.5 ℃，經過整體評估、復甦及影像學檢查後，發現有臉部下巴撕裂傷 5 公分；\n頭部電腦斷層發現蜘蛛網膜下出血 (subarachnoid hemorrhage)；胸部電腦斷層發現左側第 8-10 肋骨骨折，無合併氣、血胸；腹部電腦斷層發現脾臟中度撕裂傷≧2 公分且合併血腹(出血量>1000cc)；四肢無骨折但有多處挫擦傷及撕裂傷，針對王小美的臨床損傷情形，請依據外傷嚴重度分數(Injury Severity Score, ISS)評估，王小美ISS 分數為幾分?","opts":[{"k":"A","t":"11。"},{"k":"B","t":"17。"},{"k":"C","t":"19。"},{"k":"D","t":"22。"},{"k":"E","t":"25。"}],"answer":"D","expl":"ISS：頭頸（SAH）AIS 3、胸（肋骨骨折）AIS 2、腹（脾臟中度撕裂傷）AIS 3、臉與體表 AIS 1；取最高三區平方和：頭 3² + 腹 3² + 胸 2² = 9 + 9 + 4 = 22，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-32","year":114,"qnum":32,"topic":"總論評分","subtopic":"多重外傷定義（Berlin definition）","stem":"大雄與靜香、小夫、胖虎、及哆啦 A 夢使用竹蜻蜓飛於七層樓高，途中遭遇強烈陣風從高處墜落。依據 2014 年 Berlin definition 所定義之多重外傷(polytrauma)， 何者屬於多重外傷患者？","opts":[{"k":"A","t":"意識清楚、生命徵象穩定合併頭、胸、四肢多處撕裂傷的哆啦 A 夢。"},{"k":"B","t":"肝臟第三度撕裂傷(AIS 3)及蜘蛛膜下腔出血(AIS 3)，合併昏迷指數 7 分(Glasgow Coma Scale = 7)之大雄。"},{"k":"C","t":"脾臟第四度撕裂傷(AIS 4)及左手遠端橈骨開放性骨折(AIS 3)，意識清楚無休克、凝血障礙、或酸中毒之靜香。"},{"k":"D","t":"左大腿骨骨折(AIS 3)合併收縮壓(SBP = 75mmHg)的胖虎。"},{"k":"E","t":"左側鎖骨閉鎖性骨折(AIS 2)及單純第二至第八肋骨骨折(AIS 3)，合併代謝性酸中毒(base excess = - 6.3)之小夫。"}],"answer":"B","expl":"Berlin definition：至少兩個區域 AIS ≥3，加上 SBP ≤90、GCS ≤8、base excess ≤ −6、INR >1.4 或年齡 ≥70 其中一項；大雄（肝 AIS 3、SAH AIS 3、GCS 7）符合，所以 (B)。靜香無生理異常；胖虎與小夫只有一個 AIS ≥3 區域。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-33","year":114,"qnum":33,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"下列有關腹部鈍傷導致腹部血管損傷之敘述，何者為非？","opts":[{"k":"A","t":"暫時性血管分流術(Temporary vascular shunting)，為損傷控制手術(Damage control surgeries)。"},{"k":"B","t":"對損傷之血管進行探查手術時，應優先考慮進行近端血流控制(proximal control)。"},{"k":"C","t":"嚴重肝臟撕裂傷合併生命徵象不穩定之患者，於手術中如果發現肝動脈損傷，應考慮直接與以結紮。"},{"k":"D","t":"肝門靜脈之損傷，處理上較肝動脈損傷困難；接受結紮而非修補或重建之患者有較低之併發症比率及死亡率。"},{"k":"E","t":"對於鈍挫傷導致之腎周圍血腫(peri-renal hematoma)，在沒有破裂、快速增大、脈動(pulsatile)、或合併其他腸道損傷的狀況下，應考慮採取保守治療。"}],"answer":"D","expl":"肝門靜脈損傷處理上較肝動脈損傷困難，且結紮而非修補或重建者有「較高」的併發症與死亡率，不是較低，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-34","year":114,"qnum":34,"topic":"腹部","subtopic":"腹部總論（診斷／NOM／穿刺傷／DPL／剖腹策略）","stem":"關於微創手術應用於腹部外傷之敘述，何者為非？","opts":[{"k":"A","t":"雖然有文獻指出微創手術能夠應用於腹部外傷合併休克之患者，但相對穩定的生命徵象仍被認為是腹部外傷患者能否接受微創手術的先決條件。"},{"k":"B","t":"針對腹部外傷進行之微創手術，能降低非治療性剖腹手術(non-therapeutic laparotomy)之可能性，從而降低併發症及整體醫療費用。然而，對於需接受手術之腹部外傷患者，能否採取微創手術策略，仍應依照機構的照護能力及外科醫師的經驗是否足夠而定。"},{"k":"C","t":"氣體栓塞(Gas embolism)發生率雖然低(小於 1%)，然而可能產生併發症死亡的機率大於 25%。術中早期辨識患者產生氣體栓塞並及早介入，是避免患者死亡最重要的一環。"},{"k":"D","t":"二氧化碳(CO2 )為一常用於微創手術之氣體，透過建立一定程度之氣腹(pneumoperitoneum)以創造足夠之手術空間，具有不可燃、高度水溶性、便宜、及容易取得之優點。對於嚴重多重外傷之患者，為一安全無虞之醫用氣體。"},{"k":"E","t":"微創手術能否順利進行，與 pneumoperitoneal pressure(PP)有關。較高之 PP雖然可創造較大及完整之手術空間，然而卻可能造成明顯的靜脈回流(venous return)受阻及迷走神經刺激，對已經休克之患者造成傷害。"}],"answer":"D","expl":"CO2 氣腹雖然常用，但對嚴重多重外傷病人並非「安全無虞」：高碳酸血症、顱內壓上升、靜脈回流受阻與氣體栓塞等風險，需謹慎，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-35","year":114,"qnum":35,"topic":"頭部TBI","subtopic":"ICP／CPP 處置（mannitol／hypertonic saline）","stem":"55 歲男性，深夜騎摩托車遭闖紅燈休旅車撞擊，安全帽破裂，意識昏迷，左大腿骨折，身體有多處擦挫傷。經救護車緊急送至醫院急診，昏迷指數 E1V1M4，瞳孔兩邊等大 2.5/2.5，對光反射不明顯，BP190/95mmHg、HR89/min，緊急氣管內管插管後，發現右側胸壁有皮下氣腫及輕微氣血胸，右股骨骨折，肚子微脹，FAST 沒明顯 ascites，請問下列處置何者為是？","opts":[{"k":"A","t":"高血壓可以使腦部血流加快，腦壓升高腫漲容易出血，須適時調降血壓"},{"k":"B","t":"輸液以 D5S 為佳，除供應腦傷病患水分及電解質外，也能補充糖份，增加受傷腦部營養及熱量"},{"k":"C","t":"依 Monro-Kellie Doctrine 定律，可短暫給與 hyertonic-saline，減少腦部水份快速降低腦壓效果"},{"k":"D","t":"可適度使用 hyper-ventilation，將 PaCO2 下降至大約 35mmHg，使腦血管擴張，增加腦部血流。"},{"k":"E","t":"為維持 CPP(Cerebral Perfusion Pressue)＞70mmHg，要投與多量的血品或輸液，將腦部處於 Hyper-volemia 狀態，減少大腦損傷。"}],"answer":"C","expl":"嚴重 TBI 不建議含糖輸液（D5S）；高血壓可能是 Cushing 反應，不應急著降低；hypertonic saline 可短暫降低腦壓；過度換氣只可短暫使用（讓腦血管收縮而非擴張）；也不應刻意造成 hypervolemia，所以官方答案 (C)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-36","year":114,"qnum":36,"topic":"頭部TBI","subtopic":"總論／其他","stem":"42 歲男性工人,沒作好安全防護，不慎從工地 12 公尺高鷹架跌落地面，當場意識不清，經 通報 119，打上輸液緊急送至醫院急診，經檢傷呈現血壓 90/50、心跳 62/min，瞳孔不等大 3.5/3.0，對光反應微弱，對痛刺激眼睛無法張開，呻呤但仍可以知道痛處，經緊急氣管插管後，檢查發現呼吸 24 下/min，右側肋骨 6,7,8th 骨折，右側呼吸音減弱，雙下肢及右跟骨骨折變形，癱瘓，肚子稍漲，FAST 顯示些許 Ascites，請問下列處置何者為非？","opts":[{"k":"A","t":"應啟動緊急輸血 packed RBC 或全血及輸液維持穩定的血壓。"},{"k":"B","t":"研判可能脊髓損傷，阻礙交感神經遭受阻礙，導致血壓偏低，心跳減緩(Bradycardia)。"},{"k":"C","t":"證據力不足及副作用大，投與 mega dose methyl-prednisone 仍有爭議。"},{"k":"D","t":"輸血輸液後，如沒有其他明確出血跡像，如果血壓仍低，心跳依舊緩慢，仍續給予多量輸液維持穩定血壓。"},{"k":"E","t":"等到腹部及頭部傷勢穩定後，再去實施脊椎減壓及固定手術。"}],"answer":"D","expl":"疑似脊髓損傷的 neurogenic shock（低血壓、心搏過緩），在排除其他出血後，不應持續給予大量輸液維持血壓（容易造成肺水腫），而是適度輸液後使用升壓劑，所以 (D) 為非。(C) methylprednisolone 仍有爭議，現行不建議常規使用。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-37","year":114,"qnum":37,"topic":"ICU營養併發症","subtopic":"外傷後代謝反應／營養支持","stem":"外傷患者的營養代謝支持是整體照護中很重要的一環，下列相關建議何者錯誤？","opts":[{"k":"A","t":"營養支持除了計算熱量、蛋白質之適量供應外，開始的時間點、給與的路徑及配方比例也都很重要。"},{"k":"B","t":"建議儘早恢復胃腸道進食；於受傷後 12 to 24 hours 內即可開始。"},{"k":"C","t":"蛋白質的建議劑量為 1.2 to 2.0 g/kg/day，燒燙傷患者更可高於 2.0g/kg/day。"},{"k":"D","t":"熱量的建議為 25 to 30 kcal/kg/day。為讓及早達到總熱量的目標值，若腸道營養攝取不夠， 應於受傷後第一天儘早給予靜脈營養，以及早達到 100%每天熱量需求量。"},{"k":"E","t":"關於血糖控制，目前不建議過度的 tight control(≦110 mg/dL)，因容易發生低血糖，反而導致死亡及罹病率上升。"}],"answer":"D","expl":"同 111-16：不建議在受傷第一天就用 PN 補足 100% 熱量，所以 (D) 錯。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-38","year":114,"qnum":38,"topic":"災難院前法規","subtopic":"安寧緩和／預立醫療／同意書／腦死法規","stem":"下列有關心臟死後器官捐贈作業參考規範之敘述，下列何者不適當?","opts":[{"k":"A","t":"待病人自然心跳停止後，開始進入「5 分鐘的等候觀察期」，須確認病人在此觀察期無再次出現收縮性血壓或心搏性心率，再由主治醫師宣判死亡，並留存相關紀錄文件。"},{"k":"B","t":"若病人疑非病死或外傷死亡者，不得進行眼角膜、皮膚、骨骼或其他組織項目之捐贈作業。"},{"k":"C","t":"為了減少病人不適及維持捐贈器官功能，可能給予必要之醫療處置，包括鎮靜、止痛藥物、抗凝血劑等。"},{"k":"D","t":"若溫缺血時超過 120 分鐘，若病人或其家屬同意捐贈組織，應續執行組織摘取作業。"},{"k":"E","t":"潛在捐贈者於原先醫療過程中未使用體外循環機器，不得為維持捐贈器官功能而另行裝置體外循環機器。"}],"answer":"B","expl":"同 110-16：心臟死後器官捐贈作業參考規範：疑似非病死者不得進行心臟死後的「器官」捐贈，但組織捐贈在法律許可（如檢察官同意）時仍可進行，所以 (B)「不得進行任何組織捐贈」較不適當；(E) 未使用體外循環者不得為維持器官而另行裝置。細節請以現行規範為準。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-39","year":114,"qnum":39,"topic":"四肢血管骨科","subtopic":"股骨／開放性骨折","stem":"有關外傷病童使用骨針的敘述下列何者不適當？","opts":[{"k":"A","t":"骨針建議放置處為遠端股骨 (distal femur) 及近端脛骨 (proximal tibia) 。"},{"k":"B","t":"近端脛骨插入骨針時最好朝向腳趾端與皮膚表面呈 45 度角刺入，以避免傷及生長板。"},{"k":"C","t":"在大量出血性休克的病童，可預期周邊血管收縮，不易建立輸液管路，但是，一般周邊血管靜脈注射仍優於骨針的使用。"},{"k":"D","t":"骨針可以用來輸血，但是有一些藥物經由骨針給予其吸收效價會有所折扣。"},{"k":"E","t":"在外傷病童，骨針使用的最大病發症是輸液外漏 (extravasation of fluid)"}],"answer":"B","expl":"同 110-25：近端脛骨 IO 進針點在脛骨粗隆下 1–3 cm，針頭朝腳端偏離生長板，約 60–90 度，官方答案 (B)「45 度」不適當。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-40","year":114,"qnum":40,"topic":"休克輸血","subtopic":"REBOA","stem":"有關主動脈復甦性血管内球囊閉合術 (Resuscitative Endovascular Balloon Occlusion of the Aorta, REBOA)，何者為非：","opts":[{"k":"A","t":"主動脈分為三個區域，其中 Zone I 與 Zone III 可放置球囊。"},{"k":"B","t":"REBOA 只能暫時控制出血。"},{"k":"C","t":"與 RT (復甦性開胸手術) 相比，REBOA 可以帶來生存獲益，特別是對於不需要 CPR 的患者。"},{"k":"D","t":"對於骨盆骨折與 PPP (腹膜前骨盆腔填塞)相比，REBOA 是一種侵入性較小的手術，並且可以改善預後。"},{"k":"E","t":"出血性休克都可使用 REBOA。"}],"answer":"E","expl":"REBOA 並非所有出血性休克都能使用（胸部出血、頭部出血、近端主動脈損傷等為禁忌），所以 (E) 錯。(C) 與 RT 相比的生存益處為官方觀點；(D) 骨盆骨折時 REBOA 為較微創選項。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-41","year":114,"qnum":41,"topic":"休克輸血","subtopic":"總論／其他","stem":"對於外傷合併出血的患者接受輸液治療之原則，下列何者有誤?","opts":[{"k":"A","t":"輸液治療的效果評估指標包含生命徵象、估計出血量，來評估輸液方式的改變。"},{"k":"B","t":"快速輸液治療以達到正常的血壓是最主要的目標。"},{"k":"C","t":"在一般成人，原則上初期快速輸液是使用 isotonic crystalloid solution 1000 cc 以內。"},{"k":"D","t":"若輸液治療效果只有短暫或無反應時，應盡早考慮輸血治療。"},{"k":"E","t":"輸液治療效果的觀察指標包括生命徵象、意識、尿量等。"}],"answer":"B","expl":"現行出血性休克復甦的目標不是快速輸液以達到正常血壓，而是 permissive hypotension 並盡早輸血控制出血，所以 (B) 有誤。(C) 成人初始輸液約 1 L 內。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-42","year":114,"qnum":42,"topic":"老年孕婦","subtopic":"老年外傷（生理儲備、抗凝血藥、評估原則）","stem":"老年人生理方面變化 (physiological changes in aging)的描述，下列何者有誤：","opts":[{"k":"A","t":"Increased kyphoscoliosis."},{"k":"B","t":"Decreased gas exchange."},{"k":"C","t":"Increased subcutaneous fat."},{"k":"D","t":"Nutritional deficiency."},{"k":"E","t":"Decreased lung elasticity."}],"answer":"C","expl":"老年人皮下脂肪減少（不是增加），皮膚變薄、體溫調節差；脊柱後側彎增加、氣體交換下降、肺彈性下降與營養缺乏都會發生，所以 (C) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-43","year":114,"qnum":43,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"30 男性，因駕駛汽車發生車禍，胸腔撞擊方向盤，經救護車送至急診室，意識，呼吸急促，脈搏 140/min，呼吸次數 28/min, 血壓 90/60 mmHg，頸部皮下氣腫，兩側呼吸音降低，下一步較適合的處置是？","opts":[{"k":"A","t":"快速誘導氣管插管。"},{"k":"B","t":"安排胸部 X 光。"},{"k":"C","t":"針刺肋膜腔減壓 (needle decompression) 。"},{"k":"D","t":"進行早期輸血治療。"},{"k":"E","t":"立即進手術室緊急手術探查。"}],"answer":"C","expl":"外傷後胸部撞擊方向盤、頸部皮下氣腫、雙側呼吸音降低且休克，需立即 needle decompression（或手指胸廓切開）解除可能的張力性氣胸，所以 (C)。同時需考慮氣管支氣管損傷。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-44","year":114,"qnum":44,"topic":"總論評分","subtopic":"ISS／AIS 計分（Injury Severity Score）","stem":"中年婦女從四層樓高處墜落，被送來急診接受診治，經詳細檢查後發現身上多處創傷，其損傷部位與 AIS (Abbreviated Injury Scale) 如下：顱內出血，AIS: 4；左側氣胸，AIS: 2；脾臟破裂，AIS: 4；肝臟撕裂傷，AIS: 4；大腿骨折，AIS: 3；雙側小腿骨折，AIS: 2；請問該病患的 ISS (Injury Severity Score) 是幾分？","opts":[{"k":"A","t":"48。"},{"k":"B","t":"41。"},{"k":"C","t":"19。"},{"k":"D","t":"65。"},{"k":"E","t":"11。"}],"answer":"B","expl":"ISS：顱內出血 AIS 4、胸 2、腹（脾 4、肝 4，取最高 4）、四肢 3（股骨 3、小腿 2，取 3）；三個最高區：頭 4² + 腹 4² + 四肢 3² = 16 + 16 + 9 = 41，所以 (B)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-45","year":114,"qnum":45,"topic":"胸部","subtopic":"Tension pneumothorax／needle decompression","stem":"在治療胸腔外傷時，有幾項必須在 primary survey 就應立即分辨並馬上治療的傷害，下列何者除外？","opts":[{"k":"A","t":"Tension pneumothorax."},{"k":"B","t":"Cardiac tamponade."},{"k":"C","t":"Massive hemothorax."},{"k":"D","t":"Trachea laceration."},{"k":"E","t":"Open pneumothorax."}],"answer":"D","expl":"Primary survey 需立即辨識與處理的致命胸傷：張力性氣胸、開放性氣胸、大量血胸、心包填塞、連枷胸（氣道阻塞）；氣管或支氣管撕裂傷屬 secondary survey 要想到的潛在致命傷，所以 (D)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-46","year":114,"qnum":46,"topic":"氣道","subtopic":"Surgical airway／cricothyroidotomy","stem":"下列何者非 \"definite airway\":","opts":[{"k":"A","t":"orotracheal tube."},{"k":"B","t":"nasotracheal tube."},{"k":"C","t":"tracheostomy."},{"k":"D","t":"cricothyroidotomy."},{"k":"E","t":"laryngeal tube airway."}],"answer":"E","expl":"同 110-33：laryngeal tube（聲門上裝置）不是 definitive airway，所以 (E)。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-47","year":114,"qnum":47,"topic":"總論評分","subtopic":"ATLS primary survey／xABCDE","stem":"關於 xABCDE 評估中「X 步驟」與止血措施，下列何者錯誤？","opts":[{"k":"A","t":"「X 步驟」主要用於快速評估並控制大量可壓迫性外出血。"},{"k":"B","t":"在控制大出血時，可使用直接壓迫、填塞、止血帶等方法。"},{"k":"C","t":"止血帶應放置於出血點近端 5–8 公分處，且避免放置在關節上。"},{"k":"D","t":"正確使用止血帶後，遠端應無脈搏且出血停止。"},{"k":"E","t":"「X 步驟」的執行需在完成氣道管理(A 步驟)之後，才可開始進行。"}],"answer":"E","expl":"xABCDE 的 x 代表 exsanguinating hemorrhage，應在 A（氣道）之前處理，所以 (E) 錯。止血帶放置於出血點近端 5–8 cm、避開關節；正確使用後遠端應無脈搏且出血停止。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-48","year":114,"qnum":48,"topic":"氣道","subtopic":"總論／其他","stem":"最有可能透過正確放置口咽氣道(oral airway)來緩解的上呼吸道阻塞的情境是：","opts":[{"k":"A","t":"不停嘔吐。"},{"k":"B","t":"顏臉部骨折。"},{"k":"C","t":"口腔內不斷流出大量分泌物。"},{"k":"D","t":"後咽部血腫。"},{"k":"E","t":"昏迷且舌頭向後位移。"}],"answer":"E","expl":"口咽氣道可緩解昏迷病人舌頭後墜造成的上呼吸道阻塞，所以 (E)。嘔吐、顏面骨折、分泌物太多或後咽血腫需要吸引、保護氣道或其他處置。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-49","year":114,"qnum":49,"topic":"腹部","subtopic":"空腔器官／腸與腸繫膜","stem":"下有關 blunt bowel mesenteric injury(BBMI)的相關敘述何者為非 ?","opts":[{"k":"A","t":"於腹部鈍傷中並不常見，發生率約小於 5%。"},{"k":"B","t":"當腹部鈍傷 concurrent 三個 solid organ injury 時，BBMI 發生率超過三成。"},{"k":"C","t":"當病患意識不清時容易被 miss diagnosis。"},{"k":"D","t":"當病患 hemodynamic stable 時，應積極安排血管攝影栓塞。"},{"k":"E","t":"電腦斷層 false negative rate 大於 9%，臨床上有疑慮時可安排 Diagnostic laparoscopy."}],"answer":"D","expl":"鈍性腸系膜損傷（BBMI）：發生率低於 5%，多個實質器官損傷時發生率高，意識不清時容易漏診，CT 偽陰性約 9% 以上，必要時可做 diagnostic laparoscopy；血流動力學穩定時應依 CT 表現決定觀察或手術（腸缺血、持續出血），不是積極安排血管攝影栓塞，所以 (D) 為非。","outdated":false,"suspect":false,"flagNote":"","images":[]},{"id":"114-50","year":114,"qnum":50,"topic":"脊椎脊髓","subtopic":"Central cord syndrome","stem":"72 歲酗酒男性因四肢無力(weakness)送至急診室診治，據目擊者陳述病人被發現昏倒在樓梯間，扶他上床後，持續抱怨四肢無力；身體理學檢查發現四肢反射 4+，兩側上肢肌力 3/5，兩側下肢肌力 4/5，同時兩側下肢知覺變差(sensory deficits)，下列何者為最有可能的診斷？","opts":[{"k":"A","t":"中央脊髓症候群(Central cord syndrome)。"},{"k":"B","t":"前脊髓症候群(Anterior cord syndrome)。"},{"k":"C","t":"後脊髓症候群(Posterior cord syndrome)。"},{"k":"D","t":"硬腦膜下血腫(Subdural hematoma)。"},{"k":"E","t":"馬尾症候群(Cauda equina)。"}],"answer":"A","expl":"同 108-44：central cord syndrome（上肢重於下肢），所以 (A)。","outdated":false,"suspect":false,"flagNote":"","images":[]}]};
